    static final class MediaUploadRetryPolicy {
        static boolean shouldRetry(int attempt, Throwable failure) {
            if (attempt >= MEDIA_UPLOAD_MAX_ATTEMPTS || failure == null) {
                return false;
            }
            Throwable current = failure;
            for (int depth = 0; depth < 6 && current != null; depth++) {
                if (current instanceof EOFException) {
                    return true;
                }
                if (current instanceof IOException) {
                    String message = current.getMessage();
                    if (message != null
                            && message.toLowerCase(Locale.ROOT)
                            .contains("unexpected end of stream")) {
                        return true;
                    }
                }
                Throwable next = current.getCause();
                if (next == current) {
                    break;
                }
                current = next;
            }
            return false;
        }
    }

    private static final class PromptComposerPickerEdit {
        final String text;
        final int cursor;

        PromptComposerPickerEdit(String text, int cursor) {
            this.text = text == null ? "" : text;
            this.cursor = Math.max(0, cursor);
        }

        static PromptComposerPickerEdit apply(
                String draft,
                int selectionStart,
                int selectionEnd,
                String uploadPath
        ) {
            String source = draft == null ? "" : draft;
            String inserted = uploadPath == null ? "" : uploadPath;
            int first = PromptComposerImeStatePolicy.clampSelection(
                    Math.min(selectionStart, selectionEnd),
                    source.length()
            );
            int last = PromptComposerImeStatePolicy.clampSelection(
                    Math.max(selectionStart, selectionEnd),
                    source.length()
            );
            return new PromptComposerPickerEdit(
                    source.substring(0, first) + inserted + source.substring(last),
                    first + inserted.length()
            );
        }
    }

    private static final class UploadPickerComposerState {
        final String targetWindowId;
        final String draftText;
        final int selectionStart;
        final int selectionEnd;
        final boolean composerVisible;
        String stagedText;
        int nextSelectionStart;
        int nextSelectionEnd;

        UploadPickerComposerState(
                String targetWindowId,
                String draftText,
                int selectionStart,
                int selectionEnd,
                boolean composerVisible
        ) {
            this.targetWindowId = targetWindowId == null ? "" : targetWindowId.trim();
            this.draftText = draftText == null ? "" : draftText;
            this.selectionStart = PromptComposerImeStatePolicy.clampSelection(
                    selectionStart,
                    this.draftText.length()
            );
            this.selectionEnd = PromptComposerImeStatePolicy.clampSelection(
                    selectionEnd,
                    this.draftText.length()
            );
            this.composerVisible = composerVisible;
            this.stagedText = this.draftText;
            this.nextSelectionStart = this.selectionStart;
            this.nextSelectionEnd = this.selectionEnd;
        }

        void advance(PromptComposerPickerEdit edit) {
            if (edit == null) {
                return;
            }
            stagedText = edit.text;
            nextSelectionStart = edit.cursor;
            nextSelectionEnd = edit.cursor;
        }

        void writeToBundle(Bundle outState) {
            outState.putBoolean(STATE_UPLOAD_PICKER_PENDING, true);
            outState.putString(STATE_UPLOAD_PICKER_TARGET, targetWindowId);
            outState.putString(STATE_UPLOAD_PICKER_DRAFT, draftText);
            outState.putInt(STATE_UPLOAD_PICKER_SELECTION_START, selectionStart);
            outState.putInt(STATE_UPLOAD_PICKER_SELECTION_END, selectionEnd);
            outState.putBoolean(STATE_UPLOAD_PICKER_COMPOSER_VISIBLE, composerVisible);
        }

        static UploadPickerComposerState fromBundle(Bundle savedInstanceState) {
            if (savedInstanceState == null
                    || !savedInstanceState.getBoolean(STATE_UPLOAD_PICKER_PENDING, false)) {
                return null;
            }
            return new UploadPickerComposerState(
                    savedInstanceState.getString(STATE_UPLOAD_PICKER_TARGET, ""),
                    savedInstanceState.getString(STATE_UPLOAD_PICKER_DRAFT, ""),
                    savedInstanceState.getInt(STATE_UPLOAD_PICKER_SELECTION_START, 0),
                    savedInstanceState.getInt(STATE_UPLOAD_PICKER_SELECTION_END, 0),
                    savedInstanceState.getBoolean(
                            STATE_UPLOAD_PICKER_COMPOSER_VISIBLE,
                            false
                    )
            );
        }
    }

