    enum ActiveSwitchPhase {
        IDLE,
        PENDING_FRAME,
        BLOCKED_KEEP_LAST_GOOD,
        COMMITTED,
        ROLLED_BACK,
        REPLACED
    }

    static final class ActiveSwitchIdentity {
        final String windowId;
        final String sessionId;
        final String threadId;

        ActiveSwitchIdentity(String windowId, String sessionId, String threadId) {
            this.windowId = clean(windowId);
            this.sessionId = clean(sessionId);
            this.threadId = clean(threadId);
        }

        private static String clean(String value) {
            return value == null ? "" : value.trim();
        }

        boolean sameWindow(ActiveSwitchIdentity other) {
            return other != null && !windowId.isEmpty() && windowId.equals(other.windowId);
        }

        boolean exactlyMatches(ActiveSwitchIdentity other) {
            return sameWindow(other)
                    && sessionId.equals(other.sessionId)
                    && threadId.equals(other.threadId);
        }

        ActiveSwitchIdentity bindMissingFrom(ActiveSwitchIdentity other) {
            if (!sameWindow(other)) {
                return this;
            }
            return new ActiveSwitchIdentity(
                    windowId,
                    sessionId.isEmpty() ? other.sessionId : sessionId,
                    threadId.isEmpty() ? other.threadId : threadId
            );
        }
    }

    static final class ActiveSwitchEventResult {
        final String disposition;

        ActiveSwitchEventResult(String disposition) {
            this.disposition = disposition == null ? "" : disposition;
        }
    }

    /** Pure owner for one visible Active title/body transition generation. */
    static final class ActiveSwitchTitleLifecycle {
        private long generation = 0;
        private ActiveSwitchPhase phase = ActiveSwitchPhase.IDLE;
        private ActiveSwitchIdentity identity = new ActiveSwitchIdentity("", "", "");
        private String committedFrameHash;
        private String candidateFrameHash = "";
        private String candidateBodySha256 = "";
        private long startedAtMs = 0;
        private long deadlineAtMs = 0;
        private String disposition = "idle";

        ActiveSwitchTitleLifecycle(String committedFrameHash) {
            this.committedFrameHash = clean(committedFrameHash);
        }

        long begin(ActiveSwitchIdentity nextIdentity, long nowMs) {
            if (phase == ActiveSwitchPhase.PENDING_FRAME
                    || phase == ActiveSwitchPhase.BLOCKED_KEEP_LAST_GOOD) {
                phase = ActiveSwitchPhase.REPLACED;
            }
            generation++;
            identity = nextIdentity == null
                    ? new ActiveSwitchIdentity("", "", "")
                    : nextIdentity;
            candidateFrameHash = "";
            candidateBodySha256 = "";
            startedAtMs = Math.max(0, nowMs);
            deadlineAtMs = startedAtMs + ACTIVE_SWITCH_COMMIT_DEADLINE_MS;
            phase = ActiveSwitchPhase.PENDING_FRAME;
            disposition = "begin";
            return generation;
        }

        void seedCommittedFrame(String frameHash) {
            String cleanHash = clean(frameHash);
            if (!cleanHash.isEmpty()) {
                committedFrameHash = cleanHash;
            }
        }

        ActiveSwitchEventResult bindIdentity(
                long eventGeneration,
                ActiveSwitchIdentity exactIdentity
        ) {
            ActiveSwitchEventResult stale = rejectStaleOrInactive(eventGeneration);
            if (stale != null) {
                return stale;
            }
            if (exactIdentity == null || !identity.sameWindow(exactIdentity)) {
                return result("event-identity-mismatch");
            }
            // WHY: /terminal-frame and DOM response events may omit optional
            // session/thread fields. A current-generation event for the exact
            // stable window inherits the identity pinned by selection, while
            // every nonempty supplied value must still agree for reused windows.
            if ((!identity.sessionId.isEmpty()
                    && !exactIdentity.sessionId.isEmpty()
                    && !identity.sessionId.equals(exactIdentity.sessionId))
                    || (!identity.threadId.isEmpty()
                    && !exactIdentity.threadId.isEmpty()
                    && !identity.threadId.equals(exactIdentity.threadId))) {
                return result("event-identity-mismatch");
            }
            identity = identity.bindMissingFrom(exactIdentity);
            return result("select-identity-bound");
        }

        ActiveSwitchEventResult onFrame(
                long eventGeneration,
                ActiveSwitchIdentity eventIdentity,
                int status,
                boolean acceptedFrame,
                int bodyLength,
                int rowCount,
                String frameHash,
                String bodySha256
        ) {
            ActiveSwitchEventResult rejected = rejectEvent(eventGeneration, eventIdentity);
            if (rejected != null) {
                return rejected;
            }
            if (status < 200 || status >= 300) {
                return result("frame-rejected-status");
            }
            String cleanHash = clean(frameHash);
            String cleanBodySha256 = clean(bodySha256);
            // WHY(v277 title/body authority): exact session identity proves which
            // target answered, not that Android accepted and displayed its body.
            // Only an accepted frame may become the candidate paired with changed DOM.
            if (!acceptedFrame
                    || bodyLength <= 0
                    || rowCount <= 0
                    || cleanHash.isEmpty()
                    || !cleanBodySha256.matches("^[0-9a-f]{64}$")) {
                return result("frame-rejected-empty");
            }
            candidateFrameHash = cleanHash;
            candidateBodySha256 = cleanBodySha256;
            return result("frame-candidate");
        }

        ActiveSwitchEventResult onDom(
                long eventGeneration,
                ActiveSwitchIdentity eventIdentity,
                boolean acceptedFrame,
                int bodyLength,
                int rowCount,
                String frameHash,
                String domHash,
                String bodySha256
        ) {
            ActiveSwitchEventResult rejected = rejectEvent(eventGeneration, eventIdentity);
            if (rejected != null) {
                return rejected;
            }
            String cleanFrameHash = clean(frameHash);
            String cleanDomHash = clean(domHash);
            String cleanBodySha256 = clean(bodySha256);
            // WHY(v277 title/body authority): changed DOM is publishable only when
            // it belongs to the exact accepted frame candidate above.
            if (!acceptedFrame
                    || bodyLength <= 0
                    || rowCount <= 0
                    || candidateFrameHash.isEmpty()
                    || candidateBodySha256.isEmpty()
                    || !candidateFrameHash.equals(cleanFrameHash)
                    || !candidateFrameHash.equals(cleanDomHash)
                    || !candidateBodySha256.equals(cleanBodySha256)) {
                return result("dom-rejected-hash");
            }
            committedFrameHash = candidateFrameHash;
            candidateFrameHash = "";
            candidateBodySha256 = "";
            phase = ActiveSwitchPhase.COMMITTED;
            return result("same-generation-frame-dom-commit");
        }

        ActiveSwitchEventResult onDeadline(long eventGeneration, long nowMs) {
            if (eventGeneration != generation) {
                return result("late-generation-ignored");
            }
            if (phase != ActiveSwitchPhase.PENDING_FRAME) {
                return result("inactive-generation-ignored");
            }
            if (nowMs < deadlineAtMs) {
                return result("deadline-not-reached");
            }
            phase = ActiveSwitchPhase.BLOCKED_KEEP_LAST_GOOD;
            candidateFrameHash = "";
            candidateBodySha256 = "";
            return result("commit-deadline-no-frame-dom");
        }

        ActiveSwitchEventResult onFailure(long eventGeneration, String reason) {
            if (eventGeneration != generation) {
                return result("late-generation-ignored");
            }
            String cleanReason = clean(reason);
            if (phase != ActiveSwitchPhase.PENDING_FRAME
                    && phase != ActiveSwitchPhase.BLOCKED_KEEP_LAST_GOOD) {
                return result("inactive-generation-ignored");
            }
            candidateFrameHash = "";
            candidateBodySha256 = "";
            if ("select-error".equals(cleanReason) || "select-unreachable".equals(cleanReason)) {
                phase = ActiveSwitchPhase.ROLLED_BACK;
            } else {
                phase = ActiveSwitchPhase.BLOCKED_KEEP_LAST_GOOD;
            }
            return result(cleanReason);
        }

        void reset(String reason) {
            phase = ActiveSwitchPhase.IDLE;
            identity = new ActiveSwitchIdentity("", "", "");
            candidateFrameHash = "";
            candidateBodySha256 = "";
            startedAtMs = 0;
            deadlineAtMs = 0;
            disposition = clean(reason);
        }

        boolean blocksSendFor(String windowId) {
            String cleanWindowId = clean(windowId);
            return !cleanWindowId.isEmpty()
                    && cleanWindowId.equals(identity.windowId)
                    && (phase == ActiveSwitchPhase.PENDING_FRAME
                    || phase == ActiveSwitchPhase.BLOCKED_KEEP_LAST_GOOD);
        }

        static boolean promptComposerLocalSendControlEnabled(
                boolean composerVisible,
                boolean stableTarget
        ) {
            // WHY: switch/title settling is a delivery gate, not a local-feedback
            // gate. A stable target can be queued immediately while the backend
            // still fails closed before paste+Enter; only an incoherent target
            // must leave the visible Send control disabled.
            return !composerVisible || stableTarget;
        }

        static boolean keepsGenerationForSameTargetConfirmation(String reason) {
            String cleanReason = clean(reason);
            // WHY: one row tap owns one transition generation through its late
            // server confirmation. A fresh local tap is a new user intent and
            // must still be able to replace a blocked generation.
            return cleanReason.startsWith("select-live")
                    && !cleanReason.startsWith("select-live-local");
        }

        long leasedRendererGeneration() {
            // WHY: the native lifecycle may keep blocking Send after its visual
            // deadline, but its JavaScript-document generation is only a bounded
            // paint lease. Keeping that lease while BLOCKED makes every fresh
            // document generation-0 frame permanently stale and freezes both
            // realtime paint and one-finger scroll.
            return phase == ActiveSwitchPhase.PENDING_FRAME ? generation : 0L;
        }

        long rendererEventGeneration(long eventGeneration, String eventWindowId) {
            if (eventGeneration == generation) {
                return eventGeneration;
            }
            String cleanWindowId = clean(eventWindowId);
            if (phase == ActiveSwitchPhase.BLOCKED_KEEP_LAST_GOOD
                    && eventGeneration == 0L
                    && !cleanWindowId.isEmpty()
                    && cleanWindowId.equals(identity.windowId)) {
                // WHY: a main-frame replacement starts a new JavaScript world at
                // generation 0. Once the old document's paint lease expires,
                // normalize only that exact target back to the retained native
                // lifecycle. The existing frame SHA + changed-DOM + identity
                // gate still has to commit before title/body or Send authority
                // is published; foreign targets and nonzero stale generations
                // remain rejected.
                return generation;
            }
            return eventGeneration;
        }

        long generation() {
            return generation;
        }

        ActiveSwitchPhase phase() {
            return phase;
        }

        ActiveSwitchIdentity identity() {
            return identity;
        }

        String committedFrameHash() {
            return committedFrameHash;
        }

        String disposition() {
            return disposition;
        }

        private ActiveSwitchEventResult rejectStaleOrInactive(long eventGeneration) {
            if (eventGeneration != generation) {
                return result("late-generation-ignored");
            }
            if (phase != ActiveSwitchPhase.PENDING_FRAME
                    && phase != ActiveSwitchPhase.BLOCKED_KEEP_LAST_GOOD) {
                return result("inactive-generation-ignored");
            }
            return null;
        }

        private ActiveSwitchEventResult rejectEvent(
                long eventGeneration,
                ActiveSwitchIdentity eventIdentity
        ) {
            ActiveSwitchEventResult stale = rejectStaleOrInactive(eventGeneration);
            if (stale != null) {
                return stale;
            }
            if (!identity.exactlyMatches(eventIdentity)) {
                return result("event-identity-mismatch");
            }
            return null;
        }

        private ActiveSwitchEventResult result(String nextDisposition) {
            disposition = nextDisposition;
            return new ActiveSwitchEventResult(nextDisposition);
        }

        private static String clean(String value) {
            return value == null ? "" : value.trim();
        }
    }

    static final class ActiveSwitchRendererDocumentGeneration {
        static long generationToReplay(
                String documentTarget,
                String pendingTarget,
                long currentPendingGeneration,
                long requestedGeneration
        ) {
            String cleanDocumentTarget = cleanWindowId(documentTarget);
            String cleanPendingTarget = cleanWindowId(pendingTarget);
            if (!isStableWindowId(cleanDocumentTarget)
                    || !cleanDocumentTarget.equals(cleanPendingTarget)
                    || currentPendingGeneration <= 0L
                    || requestedGeneration != currentPendingGeneration) {
                return 0L;
            }
            return currentPendingGeneration;
        }

        private static String cleanWindowId(String value) {
            return value == null ? "" : value.trim();
        }

        private static boolean isStableWindowId(String value) {
            if (value == null || value.length() < 2 || value.charAt(0) != '@') {
                return false;
            }
            for (int index = 1; index < value.length(); index++) {
                if (!Character.isDigit(value.charAt(index))) {
                    return false;
                }
            }
            return true;
        }

        private ActiveSwitchRendererDocumentGeneration() {
        }
    }

    static final class ActiveSwitchSelectedBodyCachePolicy {
        static boolean canPaint(
                boolean resumed,
                String cachedWindowId,
                String selectedWindowId,
                String pendingWindowId,
                long transitionGeneration,
                long pendingGeneration,
                long cacheAgeMs,
                String frameHash,
                int bodyLength,
                int rowCount
        ) {
            String cached = cleanWindowId(cachedWindowId);
            return resumed
                    && isStableWindowId(cached)
                    && cached.equals(cleanWindowId(selectedWindowId))
                    && cached.equals(cleanWindowId(pendingWindowId))
                    && transitionGeneration > 0L
                    && transitionGeneration == pendingGeneration
                    && cacheAgeMs >= 0L
                    && cacheAgeMs <= ACTIVE_SWITCH_SELECTED_BODY_CACHE_MAX_AGE_MS
                    && frameHash != null
                    && !frameHash.trim().isEmpty()
                    && bodyLength > 0
                    && rowCount > 0;
        }

        private static String cleanWindowId(String value) {
            return value == null ? "" : value.trim();
        }

        private static boolean isStableWindowId(String value) {
            if (value == null || value.length() < 2 || value.charAt(0) != '@') {
                return false;
            }
            for (int index = 1; index < value.length(); index++) {
                if (!Character.isDigit(value.charAt(index))) {
                    return false;
                }
            }
            return true;
        }

        private ActiveSwitchSelectedBodyCachePolicy() {
        }
    }

