    static final class PromptComposerImeStatePolicy {
        static boolean sameTargetAndBody(
                String visibleTarget,
                String requestedTarget,
                String visibleBody,
                String requestedBody
        ) {
            return clean(visibleTarget).equals(clean(requestedTarget))
                    && value(visibleBody).equals(value(requestedBody));
        }

        static boolean shouldDeferRestore(
                boolean hasActiveComposition,
                boolean sameTargetAndBody
        ) {
            return hasActiveComposition && !sameTargetAndBody;
        }

        static boolean callbackOwnsRestore(
                String restoreTarget,
                String currentTarget,
                long restoreRevision,
                long currentRevision
        ) {
            return !clean(restoreTarget).isEmpty()
                    && clean(restoreTarget).equals(clean(currentTarget))
                    && restoreRevision >= 0L
                    && restoreRevision == currentRevision;
        }

        static int clampSelection(int selection, int textLength) {
            return Math.max(0, Math.min(Math.max(0, textLength), selection));
        }

        private static String clean(String value) {
            return value == null ? "" : value.trim();
        }

        private static String value(String value) {
            return value == null ? "" : value;
        }

        private PromptComposerImeStatePolicy() {
        }
    }

