    static final class PromptComposerRequestContext {
        final String actionId;
        final String tapId;
        final String actionKind;
        final String traceId;
        final String target;
        final String idempotencyRef;

        private PromptComposerRequestContext(
                String actionId,
                String tapId,
                String actionKind,
                String traceId,
                String target,
                String idempotencyRef
        ) {
            this.actionId = safeCorrelationId(actionId);
            this.tapId = safeCorrelationId(tapId);
            this.actionKind = safeCorrelationId(actionKind);
            this.traceId = safeCorrelationId(traceId);
            this.target = safeTarget(target);
            this.idempotencyRef = safeIdempotencyRef(idempotencyRef);
        }

        static PromptComposerRequestContext capture(
                String actionId,
                String tapId,
                String actionKind,
                String target,
                String rawIdempotencyKey
        ) {
            return new PromptComposerRequestContext(
                    actionId,
                    tapId,
                    actionKind,
                    "",
                    target,
                    shortOneWayIdempotencyRef(rawIdempotencyKey)
            );
        }

        PromptComposerRequestContext withTraceId(String nextTraceId) {
            return new PromptComposerRequestContext(
                    actionId,
                    tapId,
                    actionKind,
                    nextTraceId,
                    target,
                    idempotencyRef
            );
        }

        String toSafeLogFields() {
            return " actionId=" + actionId
                    + " tapId=" + tapId
                    + " actionKind=" + actionKind
                    + " traceId=" + traceId
                    + " target=" + target
                    + " idempotencyRef=" + idempotencyRef;
        }

        private static String safeCorrelationId(String value) {
            if (value == null) {
                return "";
            }
            String safe = value.trim().replaceAll("[^A-Za-z0-9._:@-]", "-");
            return safe.length() > 96 ? safe.substring(0, 96) : safe;
        }

        private static String safeTarget(String value) {
            String safe = value == null ? "" : value.trim();
            return safe.matches("^@[0-9]+$") ? safe : "unstable";
        }

        private static String safeIdempotencyRef(String value) {
            String safe = value == null ? "" : value.trim().toLowerCase(Locale.US);
            return safe.matches("^[0-9a-f]{12}$") ? safe : "";
        }

        private static String shortOneWayIdempotencyRef(String rawIdempotencyKey) {
            if (rawIdempotencyKey == null || rawIdempotencyKey.trim().isEmpty()) {
                return "";
            }
            try {
                byte[] digest = MessageDigest.getInstance("SHA-256").digest(
                        rawIdempotencyKey.getBytes(StandardCharsets.UTF_8)
                );
                char[] alphabet = "0123456789abcdef".toCharArray();
                char[] result = new char[12];
                for (int index = 0; index < 6; index++) {
                    int value = digest[index] & 0xff;
                    result[index * 2] = alphabet[value >>> 4];
                    result[index * 2 + 1] = alphabet[value & 0x0f];
                }
                return new String(result);
            } catch (Exception unavailableSha256) {
                // Never fall back to a reversible/raw key representation.
                return "";
            }
        }
    }

