    static final class PromptComposerSendLifecycleRecord {
        final PromptComposerSendLifecyclePhase phase;
        final PromptComposerSendLifecycleDisposition disposition;
        final long sequence;
        final String actionId;
        final String tapId;
        final String traceId;
        final String target;
        final String idempotencyRef;
        final boolean inFlightBefore;
        final int queueSizeBefore;
        final boolean inFlightAfter;
        final int queueSizeAfter;
        final long elapsedMs;

        private PromptComposerSendLifecycleRecord(
                PromptComposerSendLifecyclePhase phase,
                PromptComposerSendLifecycleDisposition disposition,
                long sequence,
                String actionId,
                String tapId,
                String traceId,
                String target,
                String idempotencyRef,
                boolean inFlightBefore,
                int queueSizeBefore,
                boolean inFlightAfter,
                int queueSizeAfter,
                long elapsedMs
        ) {
            this.phase = phase == null ? PromptComposerSendLifecyclePhase.UNKNOWN : phase;
            this.disposition = disposition == null
                    ? PromptComposerSendLifecycleDisposition.UNKNOWN
                    : disposition;
            this.sequence = Math.max(1, sequence);
            this.actionId = PromptComposerSendLifecycle.safeLifecycleId(actionId);
            this.tapId = PromptComposerSendLifecycle.safeLifecycleId(tapId);
            this.traceId = PromptComposerSendLifecycle.safeLifecycleId(traceId);
            this.target = PromptComposerSendLifecycle.safeTarget(target);
            this.idempotencyRef = PromptComposerSendLifecycle.safeIdempotencyRef(idempotencyRef);
            this.inFlightBefore = inFlightBefore;
            this.queueSizeBefore = Math.max(0, queueSizeBefore);
            this.inFlightAfter = inFlightAfter;
            this.queueSizeAfter = Math.max(0, queueSizeAfter);
            this.elapsedMs = Math.max(0, elapsedMs);
        }

        String toSafeLogFields() {
            return "lifecyclePhase=" + phase.name().toLowerCase(Locale.US).replace('_', '-')
                    + " lifecycleDisposition="
                    + disposition.name().toLowerCase(Locale.US).replace('_', '-')
                    + " lifecycleSequence=" + sequence
                    + " actionId=" + actionId
                    + " tapId=" + tapId
                    + " lifecycleTraceId=" + traceId
                    + " target=" + target
                    + " idempotencyRef=" + idempotencyRef
                    + " inFlightBefore=" + inFlightBefore
                    + " queueSizeBefore=" + queueSizeBefore
                    + " inFlightAfter=" + inFlightAfter
                    + " queueSizeAfter=" + queueSizeAfter
                    + " elapsedMs=" + elapsedMs;
        }
    }

    static final class PromptComposerSendLifecycle {
        final String actionId;
        final String tapId;
        final String traceId;
        final String target;
        final long startedAtMs;
        final long sequence;
        final PromptComposerSendLifecycleRecord lastRecord;

        private PromptComposerSendLifecycle(
                String actionId,
                String tapId,
                String traceId,
                String target,
                long startedAtMs,
                long sequence,
                PromptComposerSendLifecycleRecord lastRecord
        ) {
            this.actionId = safeLifecycleId(actionId);
            this.tapId = safeLifecycleId(tapId);
            this.traceId = safeLifecycleId(traceId);
            this.target = safeTarget(target);
            this.startedAtMs = Math.max(0, startedAtMs);
            this.sequence = Math.max(0, sequence);
            this.lastRecord = lastRecord;
        }

        static PromptComposerSendLifecycle start(String target, long startedAtMs) {
            return new PromptComposerSendLifecycle(
                    generatedSafeId("send-action"),
                    generatedSafeId("send-tap"),
                    generatedSafeId("send-trace"),
                    target,
                    startedAtMs,
                    0,
                    null
            );
        }

        PromptComposerSendLifecycle transition(
                PromptComposerSendLifecyclePhase phase,
                PromptComposerSendLifecycleDisposition disposition,
                boolean inFlightBefore,
                int queueSizeBefore,
                boolean inFlightAfter,
                int queueSizeAfter,
                String idempotencyRef,
                long nowMs
        ) {
            long nextSequence = sequence + 1;
            PromptComposerSendLifecycleRecord record = new PromptComposerSendLifecycleRecord(
                    phase,
                    disposition,
                    nextSequence,
                    actionId,
                    tapId,
                    traceId,
                    target,
                    idempotencyRef,
                    inFlightBefore,
                    queueSizeBefore,
                    inFlightAfter,
                    queueSizeAfter,
                    Math.max(0, nowMs - startedAtMs)
            );
            return new PromptComposerSendLifecycle(
                    actionId,
                    tapId,
                    traceId,
                    target,
                    startedAtMs,
                    nextSequence,
                    record
            );
        }

        private static String generatedSafeId(String prefix) {
            return safeLifecycleId(prefix + "-" + UUID.randomUUID().toString());
        }

        private static String safeLifecycleId(String value) {
            if (value == null) {
                return "";
            }
            String safe = value.trim().replaceAll("[^A-Za-z0-9._:@-]", "-");
            return safe.length() > 96 ? safe.substring(0, 96) : safe;
        }

        private static String safeTarget(String value) {
            String safe = value == null ? "" : value.trim();
            return safe.matches("^@[0-9]+$") ? safe : "unstable";
        }

        private static String safeIdempotencyRef(String value) {
            String safe = value == null ? "" : value.trim().toLowerCase(Locale.US);
            return safe.matches("^[0-9a-f]{12}$") ? safe : "";
        }
    }

    /**
     * Pure-Java global draft authority used by the release Activity dump path.
     *
     * <p>No inspected draft value, key, target, count, length, or hash enters a
     * result. Unknown wins over nonempty whenever a required state boundary is
     * malformed or unavailable.
     */
    static final class PromptDraftInstallSafetyAuthority {
        private static final String MARKER_PREFIX =
                "WEZTERM_PROMPT_DRAFT_INSTALL_SAFETY_V1";
        private static final String CONSUME_MARKER_PREFIX =
                "WEZTERM_PROMPT_DRAFT_INSTALL_SAFETY_CONSUME_V1";

        enum Outcome {
            EMPTY,
            NONEMPTY,
            UNKNOWN
        }

        enum Reason {
            OK,
            NOT_EMPTY,
            STORE_UNAVAILABLE,
            STORE_MALFORMED,
            MUTATION_RACE,
            PENDING_WRITER,
            DURABILITY_FAILURE,
            PROCESS_NOT_SEALED,
            NONCE_MISMATCH,
            OTHER_REDACTED
        }

        enum ConsumeStatus {
            CONSUMED,
            ALREADY_CONSUMED,
            SEALED,
            REJECTED
        }

        static final class Result {
            final Outcome outcome;
            final Reason reason;
            final boolean processSealHandoff;

            Result(Outcome outcome, Reason reason, boolean processSealHandoff) {
                this.outcome = outcome;
                this.reason = reason;
                this.processSealHandoff = processSealHandoff;
            }
        }

        static final class ConsumeResult {
            final ConsumeStatus status;
            final Reason reason;
            final boolean writerReleased;

            ConsumeResult(ConsumeStatus status, Reason reason, boolean writerReleased) {
                this.status = status;
                this.reason = reason;
                this.writerReleased = writerReleased;
            }
        }

        static Result evaluate(
                String visibleDraft,
                Map<?, ?> allPreferences,
                long revisionBefore,
                long revisionAfter,
                boolean pendingWriter,
                boolean composerAvailable,
                boolean storeAvailable
        ) {
            if (!composerAvailable || visibleDraft == null) {
                return unknown(Reason.OTHER_REDACTED);
            }
            if (!storeAvailable || allPreferences == null) {
                return unknown(Reason.STORE_UNAVAILABLE);
            }
            if (pendingWriter) {
                return unknown(Reason.PENDING_WRITER);
            }
            if (revisionBefore != revisionAfter) {
                return unknown(Reason.MUTATION_RACE);
            }

            boolean nonempty = !visibleDraft.isEmpty();
            boolean malformed = false;
            try {
                for (Map.Entry<?, ?> entry : allPreferences.entrySet()) {
                    Object rawKey = entry.getKey();
                    if (!(rawKey instanceof String)) {
                        malformed = true;
                        continue;
                    }
                    String key = (String) rawKey;
                    if (!key.startsWith(PREF_PROMPT_DRAFT_PREFIX)) {
                        continue;
                    }
                    Object value = entry.getValue();
                    if (!(value instanceof String)) {
                        malformed = true;
                    } else if (!((String) value).isEmpty()) {
                        nonempty = true;
                    }
                }
            } catch (RuntimeException failure) {
                return unknown(Reason.STORE_UNAVAILABLE);
            }
            if (malformed) {
                return unknown(Reason.STORE_MALFORMED);
            }
            if (revisionBefore != revisionAfter) {
                return unknown(Reason.MUTATION_RACE);
            }
            if (nonempty) {
                return new Result(Outcome.NONEMPTY, Reason.NOT_EMPTY, false);
            }
            return new Result(Outcome.EMPTY, Reason.OK, false);
        }

        static Result finalizeEmptySeal(
                Result beforeCommit,
                boolean commitSucceeded,
                Result afterCommit,
                boolean sealPresent,
                String activeInvocationId,
                String requestedInvocationId
        ) {
            if (beforeCommit == null) {
                return unknown(Reason.OTHER_REDACTED);
            }
            if (beforeCommit.outcome != Outcome.EMPTY) {
                return beforeCommit;
            }
            if (!commitSucceeded
                    || !sealPresent
                    || !isValidInvocationId(activeInvocationId)
                    || !activeInvocationId.equals(requestedInvocationId)) {
                return unknown(Reason.DURABILITY_FAILURE);
            }
            if (afterCommit == null) {
                return unknown(Reason.OTHER_REDACTED);
            }
            if (afterCommit.outcome == Outcome.UNKNOWN) {
                return afterCommit;
            }
            if (afterCommit.outcome != Outcome.EMPTY) {
                return unknown(Reason.MUTATION_RACE);
            }
            return new Result(Outcome.EMPTY, Reason.OK, true);
        }

        static boolean isExactRequest(String[] args) {
            return isExactSealRequest(args);
        }

        static boolean isExactSealRequest(String[] args) {
            return args != null
                    && args.length == 2
                    && PROMPT_DRAFT_INSTALL_SAFETY_DUMP_ARG.equals(args[0])
                    && isValidInvocationId(args[1]);
        }

        static boolean isExactConsumeRequest(String[] args) {
            return args != null
                    && args.length == 2
                    && PROMPT_DRAFT_INSTALL_SAFETY_CONSUME_DUMP_ARG.equals(args[0])
                    && isValidInvocationId(args[1]);
        }

        static String marker(String invocationId, Result result) {
            if (!isValidInvocationId(invocationId) || result == null) {
                return "";
            }
            return MARKER_PREFIX
                    + "|" + invocationId
                    + "|" + result.outcome.name()
                    + "|" + result.reason.name()
                    + "|" + (result.processSealHandoff
                    ? "SEALED_EXIT_REQUIRED"
                    : "NO_SEAL");
        }

        static ConsumeResult reconcileConsume(
                String invocationId,
                boolean processSealed,
                String activeInvocationId,
                String lastConsumedInvocationId,
                Result beforeCommit,
                boolean commitSucceeded,
                Result afterCommit,
                boolean persistedSeal,
                String persistedActiveInvocationId,
                String persistedLastConsumedInvocationId
        ) {
            if (!isValidInvocationId(invocationId)) {
                return rejected(Reason.OTHER_REDACTED);
            }
            if (!processSealed) {
                if (invocationId.equals(lastConsumedInvocationId)) {
                    return new ConsumeResult(
                            ConsumeStatus.ALREADY_CONSUMED,
                            Reason.OK,
                            true
                    );
                }
                return rejected(Reason.PROCESS_NOT_SEALED);
            }
            if (!isValidInvocationId(activeInvocationId)
                    || !invocationId.equals(activeInvocationId)) {
                return sealed(Reason.NONCE_MISMATCH);
            }
            if (beforeCommit == null) {
                return sealed(Reason.OTHER_REDACTED);
            }
            if (beforeCommit.outcome != Outcome.EMPTY) {
                return sealed(beforeCommit.reason);
            }
            if (!commitSucceeded) {
                return sealed(Reason.DURABILITY_FAILURE);
            }
            if (afterCommit == null) {
                return sealed(Reason.OTHER_REDACTED);
            }
            if (afterCommit.outcome != Outcome.EMPTY) {
                return sealed(afterCommit.reason);
            }
            if (persistedSeal
                    || persistedActiveInvocationId == null
                    || !persistedActiveInvocationId.isEmpty()
                    || !invocationId.equals(persistedLastConsumedInvocationId)) {
                return sealed(Reason.DURABILITY_FAILURE);
            }
            return new ConsumeResult(ConsumeStatus.CONSUMED, Reason.OK, true);
        }

        static String consumeMarker(String invocationId, ConsumeResult result) {
            if (!isValidInvocationId(invocationId) || result == null) {
                return "";
            }
            String writerState;
            if (result.writerReleased) {
                writerState = "WRITER_RELEASED";
            } else if (result.status == ConsumeStatus.SEALED) {
                writerState = "WRITER_BLOCKED";
            } else {
                writerState = "WRITER_STATE_UNCHANGED";
            }
            return CONSUME_MARKER_PREFIX
                    + "|" + invocationId
                    + "|" + result.status.name()
                    + "|" + result.reason.name()
                    + "|" + writerState;
        }

        private static boolean isValidInvocationId(String value) {
            if (value == null || value.length() != 32) {
                return false;
            }
            for (int index = 0; index < value.length(); index++) {
                char character = value.charAt(index);
                if (!((character >= '0' && character <= '9')
                        || (character >= 'a' && character <= 'f'))) {
                    return false;
                }
            }
            return true;
        }

        private static Result unknown(Reason reason) {
            return new Result(Outcome.UNKNOWN, reason, false);
        }

        private static ConsumeResult sealed(Reason reason) {
            return new ConsumeResult(ConsumeStatus.SEALED, reason, false);
        }

        private static ConsumeResult rejected(Reason reason) {
            return new ConsumeResult(ConsumeStatus.REJECTED, reason, false);
        }

        private PromptDraftInstallSafetyAuthority() {
        }
    }

    /**
     * Pure-Java decision seam for deterministic rapid-Send behavior checks.
     *
     * <p>The Android owner still performs transport, UI, renderer, and preference
     * side effects. This seam owns only the decisions already made by the live
     * admission, drain, callback-ownership, and successful-draft paths so a
     * held-callback fixture can execute them without an APK or fake Android UI.
     */
    static final class PromptComposerRapidOrderedSendBehavior {
        interface Submit {
            String stableTargetKey();

            String submittedValue();

            String submitFingerprint();

            String intentId();

            String idempotencyRef();

            default String idempotencyKey() {
                return idempotencyRef();
            }
        }

        enum Admission {
            ADMITTED,
            QUEUED_BEHIND_IN_FLIGHT,
            DUPLICATE_REJECTED
        }

        static String intentFingerprint(
                String stableTargetKey,
                String submittedValue,
                String intentId
        ) {
            // WHY: duplicate ownership follows one generated user intent, not
            // target+body equality. Two deliberate taps may contain identical
            // text and must remain distinct, while every retry/callback for one
            // queued item keeps this same safe one-way intent reference.
            return safe(stableTargetKey)
                    + "\n" + (submittedValue == null ? "" : submittedValue)
                    + "\nintent:" + safe(intentId);
        }

        static boolean isDuplicate(
                Submit submit,
                boolean inFlight,
                String activeFingerprint,
                Iterable<? extends Submit> queuedSubmits
        ) {
            if (submit == null || submit.submitFingerprint().isEmpty()) {
                return false;
            }
            if (inFlight && submit.submitFingerprint().equals(safe(activeFingerprint))) {
                return true;
            }
            if (queuedSubmits != null) {
                for (Submit queuedSubmit : queuedSubmits) {
                    if (queuedSubmit != null
                            && submit.submitFingerprint().equals(queuedSubmit.submitFingerprint())) {
                        return true;
                    }
                }
            }
            return false;
        }

        static <T> T nextToDrain(boolean inFlight, ArrayDeque<T> queue) {
            if (inFlight || queue == null) {
                return null;
            }
            return queue.peek();
        }

        static boolean ownsCompletion(
                boolean inFlight,
                String activeFingerprint,
                Submit submit
        ) {
            return inFlight
                    && submit != null
                    && submit.submitFingerprint().equals(safe(activeFingerprint));
        }

        static boolean ownsFinalCallback(
                boolean inFlight,
                String activeFingerprint,
                Submit submit,
                Submit queueHead
        ) {
            // WHY: a transport callback may arrive after the same operation was
            // already failed, restored, or superseded by the next FIFO item.
            // Fingerprint ownership plus exact head identity is the one atomic
            // admission boundary before any clear/restore/toast callback effect.
            return ownsCompletion(inFlight, activeFingerprint, submit)
                    && queueHead == submit;
        }

        static boolean shouldForgetSuccessfulDraft(
                String persistedDraft,
                String submittedValue
        ) {
            // WHY: a later callback may belong to an older queued intent. It may
            // clear only its own still-current value (or an already-empty slot),
            // never a newer failure-restored draft for the same stable target.
            String persisted = safe(persistedDraft);
            String submitted = safe(submittedValue);
            return persisted.isEmpty() || persisted.equals(submitted);
        }

        static boolean shouldRestoreFailedDraft(
                String persistedDraft,
                String submittedValue
        ) {
            // WHY: a late failure may belong to A1 after the user has already
            // typed A2 on the same target. Restore only into an empty or still-A1
            // slot; a different nonempty value is newer user work and must win.
            String persisted = safe(persistedDraft);
            String submitted = safe(submittedValue);
            return persisted.isEmpty() || persisted.equals(submitted);
        }

        static boolean shouldForgetSuccessfulDraft(
                String persistedDraft,
                long persistedRevision,
                String submittedValue,
                long submittedRevision
        ) {
            // WHY: body equality cannot distinguish two separate same-target
            // Sends with identical text. Only the exact admission revision owns
            // the later success callback's right to clear durable user work.
            return submittedRevision > 0
                    && persistedRevision == submittedRevision
                    && shouldForgetSuccessfulDraft(persistedDraft, submittedValue);
        }

        static boolean shouldRestoreFailedDraft(
                String persistedDraft,
                long persistedRevision,
                String submittedValue,
                long submittedRevision
        ) {
            // WHY: a later identical draft or explicit Clear is newer user
            // intent even though text comparison alone cannot see the change.
            return submittedRevision > 0
                    && persistedRevision == submittedRevision
                    && shouldRestoreFailedDraft(persistedDraft, submittedValue);
        }

        private static String safe(String value) {
            return value == null ? "" : value;
        }

        private PromptComposerRapidOrderedSendBehavior() {
        }
    }

    static final class PromptComposerSubmitLedgerEntry {
        final String stableTargetKey;
        final String value;
        final long draftRevision;
        final String submitIdempotencyKey;
        final String submitIntentId;
        final String submitFingerprint;
        final String actionId;
        final String tapId;
        final String actionKind;
        final String state;

        PromptComposerSubmitLedgerEntry(
                String stableTargetKey,
                String value,
                long draftRevision,
                String submitIdempotencyKey,
                String submitIntentId,
                String submitFingerprint,
                String actionId,
                String tapId,
                String actionKind,
                String state
        ) {
            this.stableTargetKey = stableTargetKey == null ? "" : stableTargetKey.trim();
            this.value = value == null ? "" : value;
            this.draftRevision = Math.max(0L, draftRevision);
            this.submitIdempotencyKey =
                    submitIdempotencyKey == null ? "" : submitIdempotencyKey.trim();
            this.submitIntentId = submitIntentId == null ? "" : submitIntentId.trim();
            this.submitFingerprint = submitFingerprint == null ? "" : submitFingerprint;
            this.actionId = actionId == null ? "" : actionId.trim();
            this.tapId = tapId == null ? "" : tapId.trim();
            this.actionKind = actionKind == null ? "" : actionKind.trim();
            this.state = PROMPT_COMPOSER_SUBMIT_LEDGER_FAILED.equals(state)
                    ? PROMPT_COMPOSER_SUBMIT_LEDGER_FAILED
                    : PROMPT_COMPOSER_SUBMIT_LEDGER_PENDING;
        }

        PromptComposerSubmitLedgerEntry withState(String nextState) {
            return new PromptComposerSubmitLedgerEntry(
                    stableTargetKey,
                    value,
                    draftRevision,
                    submitIdempotencyKey,
                    submitIntentId,
                    submitFingerprint,
                    actionId,
                    tapId,
                    actionKind,
                    nextState
            );
        }

        boolean matches(PromptComposerRapidOrderedSendBehavior.Submit submit) {
            return submit != null
                    && submitIntentId.equals(submit.intentId())
                    && submitIdempotencyKey.equals(submit.idempotencyKey())
                    && submitFingerprint.equals(submit.submitFingerprint())
                    && stableTargetKey.equals(submit.stableTargetKey());
        }
    }

    /**
     * Pure ordered-ledger seam shared by production persistence and recreation tests.
     */
    static final class PromptComposerSubmitLedgerBehavior {
        static ArrayList<PromptComposerSubmitLedgerEntry> admit(
                List<PromptComposerSubmitLedgerEntry> current,
                PromptComposerSubmitLedgerEntry admitted
        ) {
            ArrayList<PromptComposerSubmitLedgerEntry> next = copy(current);
            if (admitted == null) {
                return next;
            }
            // WHY: deliberately resending a restored failed body creates a new
            // immutable operation. Consume only that matching failed recovery;
            // unrelated failures and every pending intent remain in FIFO order.
            for (int index = 0; index < next.size(); index++) {
                PromptComposerSubmitLedgerEntry entry = next.get(index);
                if (PROMPT_COMPOSER_SUBMIT_LEDGER_FAILED.equals(entry.state)
                        && entry.stableTargetKey.equals(admitted.stableTargetKey)
                        && entry.value.equals(admitted.value)) {
                    next.remove(index);
                    break;
                }
            }
            next.add(admitted.withState(PROMPT_COMPOSER_SUBMIT_LEDGER_PENDING));
            return next;
        }

        static ArrayList<PromptComposerSubmitLedgerEntry> removeExactSuccess(
                List<PromptComposerSubmitLedgerEntry> current,
                PromptComposerRapidOrderedSendBehavior.Submit succeeded
        ) {
            ArrayList<PromptComposerSubmitLedgerEntry> next = copy(current);
            for (int index = 0; index < next.size(); index++) {
                if (next.get(index).matches(succeeded)) {
                    next.remove(index);
                    break;
                }
            }
            return next;
        }

        static ArrayList<PromptComposerSubmitLedgerEntry> markExactFailure(
                List<PromptComposerSubmitLedgerEntry> current,
                PromptComposerRapidOrderedSendBehavior.Submit failed
        ) {
            ArrayList<PromptComposerSubmitLedgerEntry> next = copy(current);
            for (int index = 0; index < next.size(); index++) {
                PromptComposerSubmitLedgerEntry entry = next.get(index);
                if (entry.matches(failed)) {
                    next.set(
                            index,
                            entry.withState(PROMPT_COMPOSER_SUBMIT_LEDGER_FAILED)
                    );
                    break;
                }
            }
            return next;
        }

        static PromptComposerSubmitLedgerEntry exactEntry(
                List<PromptComposerSubmitLedgerEntry> current,
                PromptComposerRapidOrderedSendBehavior.Submit submit,
                String state
        ) {
            if (current == null) {
                return null;
            }
            for (PromptComposerSubmitLedgerEntry entry : current) {
                if (entry != null
                        && entry.matches(submit)
                        && entry.state.equals(state)) {
                    return entry;
                }
            }
            return null;
        }

        static boolean pendingOwnsPersistedDraft(
                List<PromptComposerSubmitLedgerEntry> current,
                String targetKey,
                String value,
                long draftRevision
        ) {
            if (current == null || draftRevision <= 0L) {
                return false;
            }
            String stableTargetKey = targetKey == null ? "" : targetKey.trim();
            String persistedValue = value == null ? "" : value;
            for (PromptComposerSubmitLedgerEntry entry : current) {
                if (entry != null
                        && PROMPT_COMPOSER_SUBMIT_LEDGER_PENDING.equals(entry.state)
                        && entry.draftRevision == draftRevision
                        && entry.stableTargetKey.equals(stableTargetKey)
                        && entry.value.equals(persistedValue)) {
                    return true;
                }
            }
            return false;
        }

        static PromptComposerSubmitLedgerEntry firstRestorableFailure(
                List<PromptComposerSubmitLedgerEntry> current,
                String targetKey,
                String persistedDraft
        ) {
            if (current == null) {
                return null;
            }
            String stableTargetKey = targetKey == null ? "" : targetKey.trim();
            String durableDraft = persistedDraft == null ? "" : persistedDraft;
            if (stableTargetKey.isEmpty() || !durableDraft.isEmpty()) {
                return null;
            }
            // WHY: a newer pending intent for this same target still owns the
            // durable draft slot. Restore an older failure only after every
            // pending successor reaches final truth, otherwise R2 can overwrite
            // R3 while the HTTP FIFO is still draining.
            for (PromptComposerSubmitLedgerEntry entry : current) {
                if (entry != null
                        && stableTargetKey.equals(entry.stableTargetKey)
                        && PROMPT_COMPOSER_SUBMIT_LEDGER_PENDING.equals(entry.state)) {
                    return null;
                }
            }
            for (PromptComposerSubmitLedgerEntry entry : current) {
                if (entry != null
                        && stableTargetKey.equals(entry.stableTargetKey)
                        && PROMPT_COMPOSER_SUBMIT_LEDGER_FAILED.equals(entry.state)) {
                    return entry;
                }
            }
            return null;
        }

        static ArrayList<PromptComposerSubmitLedgerEntry> copy(
                List<PromptComposerSubmitLedgerEntry> current
        ) {
            ArrayList<PromptComposerSubmitLedgerEntry> copy = new ArrayList<>();
            if (current == null) {
                return copy;
            }
            for (PromptComposerSubmitLedgerEntry entry : current) {
                if (entry != null) {
                    copy.add(entry.withState(entry.state));
                }
            }
            return copy;
        }

        private PromptComposerSubmitLedgerBehavior() {
        }
    }

