    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        pendingUploadPickerComposerState =
                UploadPickerComposerState.fromBundle(savedInstanceState);
        if (savedInstanceState != null) {
            pendingUploadPickerKind =
                    savedInstanceState.getString(STATE_UPLOAD_PICKER_KIND, "");
        }
        prefs = getSharedPreferences(PREFS, MODE_PRIVATE);
        canonicalTitleStore = new CanonicalTitleStore(prefs);
        loadRetainedActiveSessionsDisplaySnapshot();
        loadPromptDraftInstallSafetySeal();
        configureWindow();
        webView = new TerminalWebView(this);
        configureWebView(webView);
        setContentView(buildLayout(webView));
        applyPromptDraftInstallSafetySealToComposer();
        restorePromptComposerSubmitLedger();
        nativeHistoryScrollController = new NativeHistoryScrollController(
                this,
                this::applyNativeHistoryScrollPixels,
                this::handleNativeHistoryKineticStateChanged
        );
        if (getIntent().getBooleanExtra("pin_shortcut", false)) {
            requestHomeShortcutOnce();
        }
        hideNavigationDeadStrip("create");
        wakeLaptopForTerminal("app-open");
        prewarmActiveSessionsDisplaySnapshot("create");
        loadTerminal();
        drainPromptComposerSubmitQueue();
        handleIncomingMediaShare(getIntent());
    }

    @Override
    protected void onDestroy() {
        if (canonicalTitleStore != null) {
            canonicalTitleStore.close();
        }
        super.onDestroy();
    }

    @Override
    public void dump(String prefix, FileDescriptor fd, PrintWriter writer, String[] args) {
        boolean sealRequest = PromptDraftInstallSafetyAuthority.isExactSealRequest(args);
        boolean consumeRequest = PromptDraftInstallSafetyAuthority.isExactConsumeRequest(args);
        if (!sealRequest && !consumeRequest) {
            super.dump(prefix, fd, writer, args);
            return;
        }
        if (writer == null) {
            return;
        }
        if (consumeRequest) {
            PromptDraftInstallSafetyAuthority.ConsumeResult consumeResult =
                    consumePromptDraftInstallSafetyAuthority(args[1]);
            String consumeMarker = PromptDraftInstallSafetyAuthority.consumeMarker(
                    args[1],
                    consumeResult
            );
            if (consumeMarker.isEmpty()) {
                return;
            }
            writer.println(consumeMarker);
            writer.flush();
            return;
        }
        PromptDraftInstallSafetyAuthority.Result result =
                evaluatePromptDraftInstallSafetyAuthority(args[1]);
        String marker = PromptDraftInstallSafetyAuthority.marker(args[1], result);
        if (marker.isEmpty()) {
            return;
        }
        writer.println(marker);
        writer.flush();
        if (writer.checkError()) {
            return;
        }
        if (result.processSealHandoff) {
            android.os.Process.killProcess(android.os.Process.myPid());
        }
    }

    private PromptDraftInstallSafetyAuthority.Result evaluatePromptDraftInstallSafetyAuthority(
            String invocationId
    ) {
        if (Looper.myLooper() != Looper.getMainLooper()) {
            return new PromptDraftInstallSafetyAuthority.Result(
                    PromptDraftInstallSafetyAuthority.Outcome.UNKNOWN,
                    PromptDraftInstallSafetyAuthority.Reason.OTHER_REDACTED,
                    false
            );
        }
        synchronized (promptDraftInstallSafetyLock) {
            if (promptDraftInstallSafetySealed) {
                return new PromptDraftInstallSafetyAuthority.Result(
                        PromptDraftInstallSafetyAuthority.Outcome.UNKNOWN,
                        PromptDraftInstallSafetyAuthority.Reason.PROCESS_NOT_SEALED,
                        false
                );
            }
            if (promptDraftInstallSafetyAuthorityRunning) {
                return new PromptDraftInstallSafetyAuthority.Result(
                        PromptDraftInstallSafetyAuthority.Outcome.UNKNOWN,
                        PromptDraftInstallSafetyAuthority.Reason.PENDING_WRITER,
                        false
                );
            }
            promptDraftInstallSafetyAuthorityRunning = true;
            try {
                PromptDraftInstallSafetyAuthority.Result beforeCommit =
                        inspectPromptDraftInstallSafetyAuthority();
                if (beforeCommit.outcome
                        != PromptDraftInstallSafetyAuthority.Outcome.EMPTY) {
                    return beforeCommit;
                }

                // WHY: an EMPTY observation is not an install lease. Block every
                // central draft writer first, then use commit() as the durability
                // barrier for prior apply() writes and re-read all authority state.
                promptDraftInstallSafetySealed = true;
                promptDraftInstallSafetyActiveInvocationId = invocationId;
                boolean commitSucceeded;
                try {
                    commitSucceeded = prefs.edit()
                            .putBoolean(PREF_PROMPT_DRAFT_INSTALL_SAFETY_SEAL, true)
                            .putString(
                                    PREF_PROMPT_DRAFT_INSTALL_SAFETY_ACTIVE_ID,
                                    invocationId
                            )
                            .commit();
                } catch (RuntimeException failure) {
                    commitSucceeded = false;
                }
                applyPromptDraftInstallSafetySealToComposer();
                if (!commitSucceeded) {
                    return PromptDraftInstallSafetyAuthority.finalizeEmptySeal(
                            beforeCommit,
                            false,
                            null,
                            false,
                            null,
                            invocationId
                    );
                }

                PromptDraftInstallSafetyAuthority.Result afterCommit =
                        inspectPromptDraftInstallSafetyAuthority();
                boolean sealPresent;
                String activeInvocationId;
                try {
                    sealPresent = prefs.getBoolean(
                            PREF_PROMPT_DRAFT_INSTALL_SAFETY_SEAL,
                            false
                    );
                } catch (RuntimeException failure) {
                    sealPresent = false;
                }
                activeInvocationId = readPromptDraftInstallSafetyString(
                        PREF_PROMPT_DRAFT_INSTALL_SAFETY_ACTIVE_ID
                );
                return PromptDraftInstallSafetyAuthority.finalizeEmptySeal(
                        beforeCommit,
                        true,
                        afterCommit,
                        sealPresent,
                        activeInvocationId,
                        invocationId
                );
            } finally {
                promptDraftInstallSafetyAuthorityRunning = false;
            }
        }
    }

    private PromptDraftInstallSafetyAuthority.ConsumeResult
    consumePromptDraftInstallSafetyAuthority(String invocationId) {
        if (Looper.myLooper() != Looper.getMainLooper()) {
            return new PromptDraftInstallSafetyAuthority.ConsumeResult(
                    PromptDraftInstallSafetyAuthority.ConsumeStatus.REJECTED,
                    PromptDraftInstallSafetyAuthority.Reason.OTHER_REDACTED,
                    false
            );
        }
        synchronized (promptDraftInstallSafetyLock) {
            if (promptDraftInstallSafetyAuthorityRunning) {
                return new PromptDraftInstallSafetyAuthority.ConsumeResult(
                        promptDraftInstallSafetySealed
                                ? PromptDraftInstallSafetyAuthority.ConsumeStatus.SEALED
                                : PromptDraftInstallSafetyAuthority.ConsumeStatus.REJECTED,
                        PromptDraftInstallSafetyAuthority.Reason.PENDING_WRITER,
                        false
                );
            }
            if (!promptDraftInstallSafetySealed
                    || !invocationId.equals(promptDraftInstallSafetyActiveInvocationId)) {
                return PromptDraftInstallSafetyAuthority.reconcileConsume(
                        invocationId,
                        promptDraftInstallSafetySealed,
                        promptDraftInstallSafetyActiveInvocationId,
                        promptDraftInstallSafetyLastConsumedInvocationId,
                        null,
                        false,
                        null,
                        promptDraftInstallSafetySealed,
                        promptDraftInstallSafetyActiveInvocationId,
                        promptDraftInstallSafetyLastConsumedInvocationId
                );
            }

            promptDraftInstallSafetyAuthorityRunning = true;
            try {
                PromptDraftInstallSafetyAuthority.Result beforeCommit =
                        inspectPromptDraftInstallSafetyAuthority();
                if (beforeCommit.outcome
                        != PromptDraftInstallSafetyAuthority.Outcome.EMPTY) {
                    return PromptDraftInstallSafetyAuthority.reconcileConsume(
                            invocationId,
                            true,
                            promptDraftInstallSafetyActiveInvocationId,
                            promptDraftInstallSafetyLastConsumedInvocationId,
                            beforeCommit,
                            false,
                            null,
                            true,
                            promptDraftInstallSafetyActiveInvocationId,
                            promptDraftInstallSafetyLastConsumedInvocationId
                    );
                }

                String previousLastConsumedId =
                        promptDraftInstallSafetyLastConsumedInvocationId;
                boolean commitSucceeded;
                try {
                    commitSucceeded = prefs.edit()
                            .putBoolean(PREF_PROMPT_DRAFT_INSTALL_SAFETY_SEAL, false)
                            .remove(PREF_PROMPT_DRAFT_INSTALL_SAFETY_ACTIVE_ID)
                            .putString(
                                    PREF_PROMPT_DRAFT_INSTALL_SAFETY_LAST_CONSUMED_ID,
                                    invocationId
                            )
                            .commit();
                } catch (RuntimeException failure) {
                    commitSucceeded = false;
                }

                PromptDraftInstallSafetyAuthority.Result afterCommit =
                        commitSucceeded
                                ? inspectPromptDraftInstallSafetyAuthority()
                                : null;
                boolean persistedSeal = true;
                String persistedActiveInvocationId = null;
                String persistedLastConsumedInvocationId = null;
                if (commitSucceeded) {
                    try {
                        persistedSeal = prefs.getBoolean(
                                PREF_PROMPT_DRAFT_INSTALL_SAFETY_SEAL,
                                true
                        );
                    } catch (RuntimeException failure) {
                        persistedSeal = true;
                    }
                    persistedActiveInvocationId = readPromptDraftInstallSafetyString(
                            PREF_PROMPT_DRAFT_INSTALL_SAFETY_ACTIVE_ID
                    );
                    persistedLastConsumedInvocationId = readPromptDraftInstallSafetyString(
                            PREF_PROMPT_DRAFT_INSTALL_SAFETY_LAST_CONSUMED_ID
                    );
                }

                PromptDraftInstallSafetyAuthority.ConsumeResult consumeResult =
                        PromptDraftInstallSafetyAuthority.reconcileConsume(
                                invocationId,
                                true,
                                promptDraftInstallSafetyActiveInvocationId,
                                previousLastConsumedId,
                                beforeCommit,
                                commitSucceeded,
                                afterCommit,
                                persistedSeal,
                                persistedActiveInvocationId,
                                persistedLastConsumedInvocationId
                        );
                if (consumeResult.status
                        == PromptDraftInstallSafetyAuthority.ConsumeStatus.CONSUMED) {
                    promptDraftInstallSafetySealed = false;
                    promptDraftInstallSafetyActiveInvocationId = "";
                    promptDraftInstallSafetyLastConsumedInvocationId = invocationId;
                    releasePromptDraftInstallSafetyComposer();
                    return consumeResult;
                }

                // WHY: no failed consume may leave a durable writer release behind.
                // Restore the same nonce-bound seal even when commit() returned false,
                // because SharedPreferences may already have changed its in-memory map.
                if (!restorePromptDraftInstallSafetySeal(
                        invocationId,
                        previousLastConsumedId
                )) {
                    return new PromptDraftInstallSafetyAuthority.ConsumeResult(
                            PromptDraftInstallSafetyAuthority.ConsumeStatus.SEALED,
                            PromptDraftInstallSafetyAuthority.Reason.DURABILITY_FAILURE,
                            false
                    );
                }
                return consumeResult;
            } finally {
                promptDraftInstallSafetyAuthorityRunning = false;
            }
        }
    }

    private PromptDraftInstallSafetyAuthority.Result
    inspectPromptDraftInstallSafetyAuthority() {
        long revisionBefore = promptDraftInstallSafetyRevision;
        boolean composerAvailable = promptComposerInput != null;
        String visibleDraft = composerAvailable
                ? promptComposerInput.getText().toString()
                : null;
        boolean pendingWriter = promptComposerSubmitInFlight
                || !promptComposerSubmitQueue.isEmpty();
        Map<String, ?> preferenceSnapshot = null;
        boolean storeAvailable = prefs != null;
        if (storeAvailable) {
            try {
                preferenceSnapshot = prefs.getAll();
                storeAvailable = preferenceSnapshot != null;
            } catch (RuntimeException failure) {
                storeAvailable = false;
            }
        }
        long revisionAfter = promptDraftInstallSafetyRevision;
        return PromptDraftInstallSafetyAuthority.evaluate(
                visibleDraft,
                preferenceSnapshot,
                revisionBefore,
                revisionAfter,
                pendingWriter,
                composerAvailable,
                storeAvailable
        );
    }

    private boolean restorePromptDraftInstallSafetySeal(
            String invocationId,
            String previousLastConsumedId
    ) {
        if (prefs == null
                || !PromptDraftInstallSafetyAuthority.isValidInvocationId(invocationId)) {
            return false;
        }
        boolean commitSucceeded;
        try {
            SharedPreferences.Editor editor = prefs.edit()
                    .putBoolean(PREF_PROMPT_DRAFT_INSTALL_SAFETY_SEAL, true)
                    .putString(PREF_PROMPT_DRAFT_INSTALL_SAFETY_ACTIVE_ID, invocationId);
            if (PromptDraftInstallSafetyAuthority.isValidInvocationId(
                    previousLastConsumedId
            )) {
                editor.putString(
                        PREF_PROMPT_DRAFT_INSTALL_SAFETY_LAST_CONSUMED_ID,
                        previousLastConsumedId
                );
            } else {
                editor.remove(PREF_PROMPT_DRAFT_INSTALL_SAFETY_LAST_CONSUMED_ID);
            }
            commitSucceeded = editor.commit();
        } catch (RuntimeException failure) {
            commitSucceeded = false;
        }
        if (!commitSucceeded) {
            return false;
        }
        try {
            boolean sealPresent = prefs.getBoolean(
                    PREF_PROMPT_DRAFT_INSTALL_SAFETY_SEAL,
                    false
            );
            String activeInvocationId = readPromptDraftInstallSafetyString(
                    PREF_PROMPT_DRAFT_INSTALL_SAFETY_ACTIVE_ID
            );
            String lastConsumedId = readPromptDraftInstallSafetyString(
                    PREF_PROMPT_DRAFT_INSTALL_SAFETY_LAST_CONSUMED_ID
            );
            return sealPresent
                    && invocationId.equals(activeInvocationId)
                    && previousLastConsumedId.equals(lastConsumedId);
        } catch (RuntimeException failure) {
            return false;
        }
    }

    private String readPromptDraftInstallSafetyString(String key) {
        if (prefs == null) {
            return null;
        }
        try {
            if (!prefs.contains(key)) {
                return "";
            }
            return prefs.getString(key, null);
        } catch (RuntimeException failure) {
            return null;
        }
    }

    private void loadPromptDraftInstallSafetySeal() {
        synchronized (promptDraftInstallSafetyLock) {
            try {
                if (prefs == null) {
                    promptDraftInstallSafetySealed = true;
                    promptDraftInstallSafetyActiveInvocationId = "";
                    promptDraftInstallSafetyLastConsumedInvocationId = "";
                    return;
                }
                boolean persistedSeal = prefs.getBoolean(
                        PREF_PROMPT_DRAFT_INSTALL_SAFETY_SEAL,
                        false
                );
                String activeInvocationId = readPromptDraftInstallSafetyString(
                        PREF_PROMPT_DRAFT_INSTALL_SAFETY_ACTIVE_ID
                );
                String lastConsumedInvocationId = readPromptDraftInstallSafetyString(
                        PREF_PROMPT_DRAFT_INSTALL_SAFETY_LAST_CONSUMED_ID
                );
                boolean activeValid = activeInvocationId != null
                        && (activeInvocationId.isEmpty()
                        || PromptDraftInstallSafetyAuthority.isValidInvocationId(
                        activeInvocationId
                ));
                boolean lastConsumedValid = lastConsumedInvocationId != null
                        && (lastConsumedInvocationId.isEmpty()
                        || PromptDraftInstallSafetyAuthority.isValidInvocationId(
                        lastConsumedInvocationId
                ));
                if (persistedSeal) {
                    promptDraftInstallSafetySealed = true;
                    promptDraftInstallSafetyActiveInvocationId =
                            activeValid ? activeInvocationId : "";
                } else if (!activeValid
                        || !activeInvocationId.isEmpty()
                        || !lastConsumedValid) {
                    promptDraftInstallSafetySealed = true;
                    promptDraftInstallSafetyActiveInvocationId = "";
                } else {
                    promptDraftInstallSafetySealed = false;
                    promptDraftInstallSafetyActiveInvocationId = "";
                }
                promptDraftInstallSafetyLastConsumedInvocationId =
                        lastConsumedValid ? lastConsumedInvocationId : "";
            } catch (RuntimeException failure) {
                promptDraftInstallSafetySealed = true;
                promptDraftInstallSafetyActiveInvocationId = "";
                promptDraftInstallSafetyLastConsumedInvocationId = "";
            }
        }
    }

    private void applyPromptDraftInstallSafetySealToComposer() {
        if (promptDraftInstallSafetySealed && promptComposerInput != null) {
            promptComposerInput.setEnabled(false);
        }
    }

    private void releasePromptDraftInstallSafetyComposer() {
        if (!promptDraftInstallSafetySealed && promptComposerInput != null) {
            promptComposerInput.setEnabled(true);
        }
    }

    private boolean promptDraftInstallSafetyWriterBlocked() {
        return promptDraftInstallSafetySealed || promptDraftInstallSafetyAuthorityRunning;
    }

    @Override
    protected void onNewIntent(Intent intent) {
        super.onNewIntent(intent);
        setIntent(intent);
        if (Intent.ACTION_MAIN.equals(intent.getAction())
                && intent.hasCategory(Intent.CATEGORY_LAUNCHER)) {
            restorePreferredEndpointsOnLauncherReentry();
        }
        handleIncomingMediaShare(intent);
    }

    private void restorePreferredEndpointsOnLauncherReentry() {
        if (webView == null) {
            return;
        }
        // WHY: WEzterm is singleTask, so Android can bring an already-running
        // task forward without calling onCreate(). The 2026-06-17 failure left a
        // stale MagicDNS WebView/control endpoint on screen even after v2.04
        // preferred the direct Tailnet IP. A launcher re-entry is the user's
        // explicit reconnect path, so reset both endpoint owners to the proven
        // direct IP and reload only when the current WebView is not already there.
        terminalUrlIndex = 0;
        activeTerminalBaseUrl = TERMINAL_URL;
        activeControlBaseUrl = CONTROL_URL;
        wakeLaptopForTerminal("launcher-reentry");
        String currentUrl = webView.getUrl();
        if (currentUrl == null || !currentUrl.startsWith(TERMINAL_URL)) {
            loadTerminalAtIndex(0, "launcher-reentry");
        } else {
            pinTerminalViewportSoon("launcher-reentry");
            focusTerminalInputSoon(false);
            keepLiveInputVisibleSoon("launcher-reentry");
            scheduleBlankTerminalWatchdog("launcher-reentry");
        }
        scheduleToolbarStatusDotRefresh(0);
        prewarmLocalHistoryForVisibleTarget("resume");
        refreshActiveSessionsDialogIfShowing("resume");
    }

    @Override
    protected void onActivityResult(int requestCode, int resultCode, Intent data) {
        super.onActivityResult(requestCode, resultCode, data);
        if (requestCode == REQUEST_UPLOAD_MEDIA) {
            nativePickerQuietUntilMs = System.currentTimeMillis() + 8000;
        }
        if (requestCode == REQUEST_UPLOAD_MEDIA) {
            String pickerKind = pendingUploadPickerKind;
            pendingUploadPickerKind = "";
            UploadPickerComposerState pickerState = pendingUploadPickerComposerState;
            pendingUploadPickerComposerState = null;
            Log.i(UPLOAD_LOG_TAG, "picker-result kind=" + pickerKind
                    + " result=" + resultCode
                    + " hasData=" + (data != null)
                    + " hasClip=" + (data != null && data.getClipData() != null));
            restoreUploadPickerComposerState(pickerState, "picker-result");
            if (resultCode != RESULT_OK || data == null) {
                return;
            }
            List<Uri> uris = uploadUrisFromResult(data);
            if (uris.isEmpty()) {
                toast("No media selected");
                Log.w(UPLOAD_LOG_TAG, "picker-result-empty kind=" + pickerKind);
                return;
            }
            for (Uri uri : uris) {
                prepareReadAccessForUpload(data, uri);
            }
            uploadMediaUrisSequentially(uris, false, pickerState);
        }
    }

    @Override
    protected void onResume() {
        super.onResume();
        activityResumed = true;
        keepScreenAwakeForActiveTerminal();
        wakeLaptopForTerminal("resume");
        if (webView != null) {
            // WHY(v282 background live-stream pressure): WebView.onPause() does
            // not pause JavaScript. Resume the one app-owned WebView's timers
            // before its existing renderer/reconnect recovery is rearmed.
            webView.resumeTimers();
            webView.onResume();
            if (isDockedPromptComposerVisible()) {
                restoreDockedPromptComposerFocus("resume");
            } else {
                focusTerminalInputSoon(false);
            }
            forceCaptureRendererVisualCommit("resume");
            installCaptureRendererTelemetryHook("resume");
            scheduleCaptureRendererIdleRealtimeRefresh("resume");
            scheduleBlankTerminalWatchdog("resume");
            settleEntryLiveBottomSoon("resume");
            scheduleResumeStreamReconnectCheck("resume");
        }
        scheduleToolbarStatusDotRefresh(0);
        prewarmActiveSessionsDisplaySnapshot("resume");
        refreshActiveSessionsDialogIfShowing("resume");
    }

    @Override
    public void onConfigurationChanged(Configuration newConfig) {
        super.onConfigurationChanged(newConfig);
        if (promptComposerInput == null || !isDockedPromptComposerVisible()) {
            promptComposerConfigurationRecoveryGeneration = -1;
            return;
        }
        // WHY(v274 hidden-IME recovery): this Activity handles orientation
        // changes in place, so Gboard can rebuild the already-focused editor
        // connection later without another onResume/window-focus callback. Arm
        // exactly this visible composer generation; its replacement
        // InputConnection consumes the arm and performs one post-layout retry.
        promptComposerConfigurationRecoveryGeneration =
                promptComposerVisibilityGeneration;
        Log.i(CONTROL_LOG_TAG,
                "stage=prompt-composer-ime-recovery"
                        + " result=armed"
                        + " reason=configuration-changed"
                        + " generation="
                        + promptComposerConfigurationRecoveryGeneration
                        + " imeInsetBottom=" + lastImeInsetBottom);
    }

    @Override
    protected void onPause() {
        activityResumed = false;
        // WHY: Android can pause the APK while the native composer is hidden for
        // an in-flight Send or while the IME still owns text. Save the exact
        // visible draft before lifecycle churn so a timeout/unreachable callback
        // can restore the whole user message instead of a stale prefix.
        saveVisiblePromptComposerDraft();
        toolbarStatusGeneration++;
        promptComposerDraftLocalGeneration++;
        stopCaptureRendererIdleRealtimeRefresh("pause");
        stopStatusDotPulsesInTree(getWindow().getDecorView());
        if (webView != null) {
            webView.onPause();
            // WHY(v282 background live-stream pressure): the exact-bound
            // EventSource dirty handler kept draining /terminal-live-frame about
            // 3.27 times/second after the Activity left the foreground because
            // WebView.onPause() is only best effort and does not pause JavaScript.
            // This app owns one WebView, so the API's global timer scope is the
            // intended lifecycle boundary; onResume restores it above.
            webView.pauseTimers();
        }
        super.onPause();
    }

    @Override
    protected void onSaveInstanceState(Bundle outState) {
        // WHY: Android may recreate the Activity while the system picker owns the
        // screen. Carry the exact launch-time edit and target with the request;
        // the callback must not infer either from whichever session is current.
        if (pendingUploadPickerComposerState != null) {
            pendingUploadPickerComposerState.writeToBundle(outState);
            outState.putString(STATE_UPLOAD_PICKER_KIND, pendingUploadPickerKind);
        }
        super.onSaveInstanceState(outState);
    }

    @Override
    public void onWindowFocusChanged(boolean hasFocus) {
        super.onWindowFocusChanged(hasFocus);
        if (hasFocus && webView != null) {
            hideNavigationDeadStrip("window-focus");
            if (isDockedPromptComposerVisible()) {
                restoreDockedPromptComposerFocus("window-focus");
            } else {
                focusTerminalInputSoon(false);
            }
            scheduleBlankTerminalWatchdog("window-focus");
        }
    }

    @Override
    public boolean onKeyDown(int keyCode, KeyEvent event) {
        if (keyCode == KeyEvent.KEYCODE_BACK && isDockedPromptComposerVisible()) {
            // WHY: the docked composer intentionally has no extra Cancel button.
            // Android Back is the standard way to dismiss a focused text field, and
            // keeping dismissal here prevents a second row of hidden-looking buttons
            // from returning under the toolbar.
            hideDockedPromptComposer(false, false);
            return true;
        }
        if (keyCode == KeyEvent.KEYCODE_BACK && webView != null && webView.canGoBack()) {
            webView.goBack();
            return true;
        }
        if (handleViewerZoomKey(keyCode, event)) {
            return true;
        }
        return super.onKeyDown(keyCode, event);
    }

    private View buildLayout(WebView view) {
        LinearLayout root = new LinearLayout(this);
        root.setOrientation(LinearLayout.VERTICAL);
        root.setBackgroundColor(Color.rgb(30, 30, 46));
        root.setKeepScreenOn(true);
        LinearLayout toolbar = bottomBar();
        promptComposerBar = buildPromptComposer();
        sessionTitleStrip = buildSessionTitleStrip();
        applySystemBarPadding(root, toolbar);

        terminalFrame = new FrameLayout(this);
        terminalFrame.setKeepScreenOn(true);
        terminalFrame.setClipChildren(true);
        terminalFrame.addView(view, new FrameLayout.LayoutParams(
                FrameLayout.LayoutParams.MATCH_PARENT,
                FrameLayout.LayoutParams.MATCH_PARENT
        ));
        historyTouchOverlay = new View(this);
        historyTouchOverlay.setBackgroundColor(Color.TRANSPARENT);
        historyTouchOverlay.setVisibility(View.GONE);
        historyTouchOverlay.setOnTouchListener((touchedView, event) -> handleTerminalTouch(event));
        terminalFrame.addView(historyTouchOverlay, new FrameLayout.LayoutParams(
                FrameLayout.LayoutParams.MATCH_PARENT,
                FrameLayout.LayoutParams.MATCH_PARENT
        ));
        sessionSwitchPaintShield = new View(this);
        sessionSwitchPaintShield.setBackgroundColor(Color.BLACK);
        sessionSwitchPaintShield.setClickable(true);
        sessionSwitchPaintShield.setVisibility(View.GONE);
        sessionSwitchPaintShield.setAlpha(0f);
        terminalFrame.addView(sessionSwitchPaintShield, new FrameLayout.LayoutParams(
                FrameLayout.LayoutParams.MATCH_PARENT,
                FrameLayout.LayoutParams.MATCH_PARENT
        ));
        sessionSwitchLowerPaintShield = new View(this);
        sessionSwitchLowerPaintShield.setBackgroundColor(Color.BLACK);
        sessionSwitchLowerPaintShield.setClickable(false);
        sessionSwitchLowerPaintShield.setVisibility(View.GONE);
        sessionSwitchLowerPaintShield.setAlpha(0f);
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.LOLLIPOP) {
            sessionSwitchLowerPaintShield.setElevation(dp(24));
        }
        terminalFrame.addView(sessionSwitchLowerPaintShield, new FrameLayout.LayoutParams(
                FrameLayout.LayoutParams.MATCH_PARENT,
                FrameLayout.LayoutParams.MATCH_PARENT
        ));

        root.addView(terminalFrame, new LinearLayout.LayoutParams(
                LinearLayout.LayoutParams.MATCH_PARENT,
                0,
                1
        ));
        root.addView(promptComposerBar, new LinearLayout.LayoutParams(
                LinearLayout.LayoutParams.MATCH_PARENT,
                LinearLayout.LayoutParams.WRAP_CONTENT
        ));
        root.addView(sessionTitleStrip, new LinearLayout.LayoutParams(
                LinearLayout.LayoutParams.MATCH_PARENT,
                LinearLayout.LayoutParams.WRAP_CONTENT
        ));
        // WHY: the native composer must remain above the APK controls. A rejected
        // v2.63 attempt moved it below the toolbar, which made the expected phone
        // text board disappear from above the buttons. Keep the text line in the
        // established place, and reclaim space by tightening chrome instead of
        // moving typing below the controls.
        root.addView(toolbar, new LinearLayout.LayoutParams(
                LinearLayout.LayoutParams.MATCH_PARENT,
                dp(TOOLBAR_HEIGHT_DP)
        ));
        return root;
    }

    private long showSessionSwitchPaintShield(String reason) {
        long generation = ++sessionSwitchPaintShieldGeneration;
        if (sessionSwitchPaintShield == null) {
            return generation;
        }
        // WHY: v2.33 makes Active/Old switching render-owned instead of
        // mask-owned. A very short full-frame shield may hide the first broken
        // compositor frame, but the previous lower native/Popup/WebView shields
        // were able to turn the user's dotted-tail complaint into a black
        // lower-rectangle complaint. Clear those broad masks before each switch;
        // only xterm's bounded row scrubber may touch actual dotted rows.
        sessionSwitchPaintShield.animate().cancel();
        clearBroadSessionSwitchVisualMasks(reason + "-pre-switch");
        holdWebViewSoftwareLayerForSessionSwitch(reason, FULL_FRAME_SESSION_SWITCH_SHIELD_MAX_MS);
        sessionSwitchPaintShield.setAlpha(1f);
        sessionSwitchPaintShield.setVisibility(View.VISIBLE);
        sessionSwitchPaintShield.bringToFront();
        hideSessionSwitchPaintShieldSoon(reason + "-max-full-frame-native", generation,
                FULL_FRAME_SESSION_SWITCH_SHIELD_MAX_MS);
        return generation;
    }

    private long showSessionSwitchLowerPaintShield(String reason, float topFraction, long delayMs) {
        long generation = ++sessionSwitchLowerPaintShieldGeneration;
        // WHY: this helper is intentionally a no-op now. Keeping the method as a
        // cleanup boundary avoids risky call-site churn, but v2.33 must never show
        // a broad lower black shield as a "dot fix"; the proof now fails that
        // exact black-lower-terminal screenshot. Actual dotted glyph rows are
        // handled by the row scrubber and must be followed by real live-bottom
        // paint, not a native/WebView/PopupWindow cover.
        clearBroadSessionSwitchVisualMasks(reason + "-v233-disabled-lower-shield");
        return generation;
    }

    private void showSessionSwitchLowerPopupShield(String reason, float topFraction) {
        if (terminalFrame == null || !terminalFrame.isShown()) {
            return;
        }
        int frameWidth = terminalFrame.getWidth();
        int frameHeight = terminalFrame.getHeight();
        if (frameWidth <= 0 || frameHeight <= 0) {
            terminalFrame.post(() -> showSessionSwitchLowerPopupShield(reason, topFraction));
            return;
        }
        float boundedTopFraction = Math.max(0.30f, Math.min(0.58f, topFraction));
        int topPx = Math.round(frameHeight * boundedTopFraction);
        topPx = Math.max(dp(180), Math.min(frameHeight - dp(72), topPx));
        int popupHeight = Math.max(1, frameHeight - topPx);
        int[] location = new int[2];
        terminalFrame.getLocationOnScreen(location);
        if (sessionSwitchLowerPopupShield == null) {
            View popupView = new View(this);
            popupView.setBackgroundColor(Color.BLACK);
            popupView.setClickable(false);
            // WHY: v2.29 proved the normal native child shield can still miss the
            // readable proof frame over Android WebView. Use a separate PopupWindow
            // only during passive Active-switch settle so the lower stale dotted
            // raster is covered above WebView composition. This is still lower-area
            // only, non-touchable, short-lived, and dismissed by the same
            // typing/read/touch cleanup path; it does not touch title/session naming.
            sessionSwitchLowerPopupShield = new PopupWindow(popupView, frameWidth, popupHeight, false);
            sessionSwitchLowerPopupShield.setTouchable(false);
            sessionSwitchLowerPopupShield.setOutsideTouchable(false);
            sessionSwitchLowerPopupShield.setClippingEnabled(true);
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.LOLLIPOP) {
                sessionSwitchLowerPopupShield.setElevation(dp(96));
            }
        } else {
            sessionSwitchLowerPopupShield.setWidth(frameWidth);
            sessionSwitchLowerPopupShield.setHeight(popupHeight);
        }
        try {
            if (sessionSwitchLowerPopupShield.isShowing()) {
                sessionSwitchLowerPopupShield.update(location[0], location[1] + topPx, frameWidth, popupHeight, false);
            } else {
                sessionSwitchLowerPopupShield.showAtLocation(terminalFrame, android.view.Gravity.NO_GRAVITY,
                        location[0], location[1] + topPx);
            }
        } catch (WindowManager.BadTokenException exc) {
            // Activity is no longer in a state that can own a popup; the normal
            // cleanup path will remove any stale shield on the next transition.
        }
    }

    private void dismissSessionSwitchLowerPopupShield(String reason) {
        if (sessionSwitchLowerPopupShield == null) {
            return;
        }
        if (sessionSwitchLowerPopupShield.isShowing()) {
            sessionSwitchLowerPopupShield.dismiss();
        }
        sessionSwitchLowerPopupShield = null;
    }

    private void updateSessionSwitchLowerPaintShieldLayout(float topFraction) {
        if (terminalFrame == null || sessionSwitchLowerPaintShield == null) {
            return;
        }
        int frameHeight = terminalFrame.getHeight();
        if (frameHeight <= 0) {
            terminalFrame.post(() -> updateSessionSwitchLowerPaintShieldLayout(topFraction));
            return;
        }
        float boundedTopFraction = Math.max(0.30f, Math.min(0.55f, topFraction));
        int topPx = Math.round(frameHeight * boundedTopFraction);
        topPx = Math.max(dp(180), Math.min(frameHeight - dp(72), topPx));
        FrameLayout.LayoutParams params = new FrameLayout.LayoutParams(
                FrameLayout.LayoutParams.MATCH_PARENT,
                FrameLayout.LayoutParams.MATCH_PARENT
        );
        sessionSwitchLowerPaintShield.setLayoutParams(params);
        sessionSwitchLowerPaintShield.setTranslationY(topPx);
        sessionSwitchLowerPaintShield.requestLayout();
        sessionSwitchLowerPaintShield.invalidate();
    }

    private void hideSessionSwitchLowerPaintShieldSoon(String reason, long generation, long delayMs) {
        uiHandler.postDelayed(() -> hideSessionSwitchLowerPaintShield(reason, generation),
                Math.max(0, delayMs));
    }

    private void hideSessionSwitchLowerPaintShield(String reason, long generation) {
        if (sessionSwitchLowerPaintShield == null || generation != sessionSwitchLowerPaintShieldGeneration) {
            return;
        }
        sessionSwitchLowerPaintShield.animate().cancel();
        sessionSwitchLowerPaintShield.animate()
                .alpha(0f)
                .setDuration(120)
                .withEndAction(() -> {
                    if (sessionSwitchLowerPaintShield != null
                            && generation == sessionSwitchLowerPaintShieldGeneration) {
                        sessionSwitchLowerPaintShield.setVisibility(View.GONE);
                        sessionSwitchLowerPaintShield.setAlpha(0f);
                    }
                })
                .start();
        dismissSessionSwitchLowerPopupShield(reason);
    }

    private void forceHideSessionSwitchLowerPaintShield(String reason) {
        sessionSwitchLowerPaintShieldGeneration++;
        restoreWebViewLayerAfterSessionSwitch(reason);
        dismissSessionSwitchLowerPopupShield(reason);
        if (sessionSwitchLowerPaintShield == null) {
            removeActiveSwitchWebViewLowerDotShield(reason);
            removeBroadWebViewBlackMasks(reason);
            return;
        }
        sessionSwitchLowerPaintShield.animate().cancel();
        sessionSwitchLowerPaintShield.setVisibility(View.GONE);
        sessionSwitchLowerPaintShield.setAlpha(0f);
        removeActiveSwitchWebViewLowerDotShield(reason);
        removeBroadWebViewBlackMasks(reason);
    }

    private void clearBroadSessionSwitchVisualMasks(String reason) {
        forceHideSessionSwitchLowerPaintShield(reason);
        removeBroadWebViewBlackMasks(reason);
    }

    private void removeBroadWebViewBlackMasks(String reason) {
        if (webView == null || Build.VERSION.SDK_INT < Build.VERSION_CODES.KITKAT) {
            return;
        }
        // WHY: the v2.32 screenshot showed that lower black overlays can be just
        // as confusing as the dotted field they replaced. This cleanup removes
        // only broad mask elements/timers; the row-level dot scrubber can remain
        // active because it hides individual proven filler rows instead of
        // covering the readable terminal viewport.
        webView.evaluateJavascript(
                "(function(){"
                        + "try{"
                        + "window.__weztermBlankTailMaskExpiresAt=0;"
                        + "if(window.__weztermBlankTailMaskTimer){clearInterval(window.__weztermBlankTailMaskTimer);window.__weztermBlankTailMaskTimer=null;}"
                        + "if(window.__weztermBlankTailMaskObserver){try{window.__weztermBlankTailMaskObserver.disconnect();}catch(e){}window.__weztermBlankTailMaskObserver=null;}"
                        + "window.__weztermImmediateDotFillerShieldExpiresAt=0;"
                        + "if(window.__weztermImmediateDotFillerShieldTimer){clearTimeout(window.__weztermImmediateDotFillerShieldTimer);window.__weztermImmediateDotFillerShieldTimer=null;}"
                        + "window.__weztermActiveSwitchLowerDotShieldExpiresAt=0;"
                        + "if(window.__weztermActiveSwitchLowerDotShieldTimer){clearInterval(window.__weztermActiveSwitchLowerDotShieldTimer);window.__weztermActiveSwitchLowerDotShieldTimer=null;}"
                        + "var ids=['wezterm-blank-tail-mask','wezterm-immediate-dot-filler-shield','wezterm-active-switch-lower-dot-shield'];"
                        + "for(var i=0;i<ids.length;i++){var el=document.getElementById(ids[i]);if(el&&el.parentNode){el.parentNode.removeChild(el);}}"
                        + "return 'broad-black-masks-removed:" + sanitizeJavascriptReason(reason) + "';"
                        + "}catch(e){return 'err';}"
                + "})()",
                null
        );
    }

    private void holdWebViewSoftwareLayerForSessionSwitch(String reason, long delayMs) {
        if (webView == null) {
            return;
        }
        long generation = ++sessionSwitchWebViewLayerGeneration;
        // WHY: v2.27 proved the lower dotted field can survive DOM row hiding and
        // WebView-local overlays, which means the failing surface is Android's
        // WebView hardware-composited terminal raster. During passive session
        // switching only, hold WebView in a software layer long enough for the
        // UI-dump/readable screenshot path to repaint. Restore the default layer
        // afterward so normal terminal scrolling keeps its hardware path.
        webView.setLayerType(View.LAYER_TYPE_SOFTWARE, null);
        webView.invalidate();
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.JELLY_BEAN) {
            webView.postInvalidateOnAnimation();
        }
        uiHandler.postDelayed(() -> {
            if (generation == sessionSwitchWebViewLayerGeneration) {
                restoreWebViewLayerAfterSessionSwitch(reason);
            }
        }, Math.max(1000L, Math.min(9000L, delayMs)));
    }

    private void restoreWebViewLayerAfterSessionSwitch(String reason) {
        sessionSwitchWebViewLayerGeneration++;
        if (webView == null) {
            return;
        }
        webView.setLayerType(View.LAYER_TYPE_NONE, null);
        webView.invalidate();
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.JELLY_BEAN) {
            webView.postInvalidateOnAnimation();
        }
    }

    private void installActiveSwitchWebViewLowerDotShield(String reason, float topFraction, long delayMs) {
        // WHY: user proof on 2026-06-26 showed the old WebView-local lower shield
        // is the wrong layer for Active/zoom fixes: covering stale/dotted paint with
        // a fixed black rectangle can become the giant black bottom box. Keep this
        // helper as a cleanup boundary for old call sites, but permanently disable
        // creation; real repair must come from renderer/live-bottom paint and viewer
        // ownership guards, never from a broad lower mask.
        removeActiveSwitchWebViewLowerDotShield(reason + "-v279-disabled");
    }

    private void removeActiveSwitchWebViewLowerDotShield(String reason) {
        if (webView == null || Build.VERSION.SDK_INT < Build.VERSION_CODES.KITKAT) {
            return;
        }
        webView.evaluateJavascript(
                "(function(){"
                        + "try{"
                        + "window.__weztermActiveSwitchLowerDotShieldExpiresAt=0;"
                        + "if(window.__weztermActiveSwitchLowerDotShieldTimer){clearInterval(window.__weztermActiveSwitchLowerDotShieldTimer);window.__weztermActiveSwitchLowerDotShieldTimer=null;}"
                        + "var shield=document.getElementById('wezterm-active-switch-lower-dot-shield');"
                        + "if(shield&&shield.parentNode){shield.parentNode.removeChild(shield);}"
                        + "return 'active-switch-webview-lower-dot-shield-removed:" + sanitizeJavascriptReason(reason) + "';"
                        + "}catch(e){return 'err';}"
                + "})()",
                null
        );
    }

    private void hideSessionSwitchPaintShieldSoon(String reason, long generation, long delayMs) {
        uiHandler.postDelayed(() -> hideSessionSwitchPaintShield(reason, generation), Math.max(0, delayMs));
    }

    private void hideSessionSwitchPaintShield(String reason, long generation) {
        if (sessionSwitchPaintShield == null || generation != sessionSwitchPaintShieldGeneration) {
            return;
        }
        sessionSwitchPaintShield.animate().cancel();
        sessionSwitchPaintShield.animate()
                .alpha(0f)
                .setDuration(60)
                .withEndAction(() -> {
                    if (sessionSwitchPaintShield != null && generation == sessionSwitchPaintShieldGeneration) {
                        sessionSwitchPaintShield.setVisibility(View.GONE);
                        sessionSwitchPaintShield.setAlpha(0f);
                    }
                })
                .start();
    }

    private void forceHideSessionSwitchPaintShield(String reason) {
        sessionSwitchPaintShieldGeneration++;
        if (sessionSwitchPaintShield == null) {
            return;
        }
        sessionSwitchPaintShield.animate().cancel();
        sessionSwitchPaintShield.setVisibility(View.GONE);
        sessionSwitchPaintShield.setAlpha(0f);
        forceHideSessionSwitchLowerPaintShield(reason);
    }

    private LinearLayout buildPromptComposer() {
        LinearLayout composer = new LinearLayout(this);
        composer.setOrientation(LinearLayout.HORIZONTAL);
        // WHY: horizontal LinearLayout baseline alignment is enabled by default.
        // With a multiline EditText, that couples Upload/Resend to the first text
        // baseline and can lift their 48dp boxes even when every child requests
        // BOTTOM gravity. The composer is an edge-aligned control row, not a text
        // baseline row, so disable that hidden layout owner before adding children.
        composer.setBaselineAligned(false);
        // WHY: the editor grows upward from the fixed title/action chrome. Keep
        // attachment and resend anchored to that same lower edge so they remain
        // beside the active insertion line instead of drifting toward the first
        // line as wrapped text expands above the IME.
        composer.setGravity(android.view.Gravity.BOTTOM);
        composer.setVisibility(View.GONE);
        // WHY: the 2026-06-18 phone screenshot showed the empty native composer
        // consuming terminal space while the keyboard was already open. Keep the
        // native composer as the single typing owner, but make its idle row compact
        // so the terminal still has room to repaint above the IME.
        composer.setPadding(dp(8), dp(PROMPT_COMPOSER_VERTICAL_PADDING_DP),
                dp(8), dp(PROMPT_COMPOSER_VERTICAL_PADDING_DP));
        composer.setBackgroundColor(Color.rgb(24, 24, 37));

        promptComposerInput = new PromptComposerEditText(this);
        promptComposerInput.setSingleLine(false);
        promptComposerInput.setMinLines(1);
        promptComposerInput.setMaxLines(4);
        promptComposerInput.setTextSize(16);
        promptComposerInput.setTextColor(Color.rgb(205, 214, 244));
        promptComposerInput.setHintTextColor(Color.rgb(127, 132, 156));
        promptComposerInput.setHint("Type prompt - tap Send");
        promptComposerInput.setContentDescription("Type prompt");
        promptComposerInput.setInputType(TERMINAL_INPUT_TYPE);
        promptComposerInput.setImeOptions(TERMINAL_IME_OPTIONS);
        // WHY (#29 composer cursor cutoff): this editor grows through four wrapped
        // lines and then scrolls only itself. Centering a capped multiline layout
        // with zero vertical inset lets Samsung/Gboard's active cursor/composing
        // underline sit on the clipped bottom edge during IME/layout relayout.
        // Anchor text at the top, keep wrapping explicit, and reserve cursor-safe
        // pixels inside this EditText; terminal/WebView scrolling remains untouched.
        promptComposerInput.setGravity(
                android.view.Gravity.TOP | android.view.Gravity.START
        );
        promptComposerInput.setHorizontallyScrolling(false);
        promptComposerInput.setPadding(dp(10), dp(6), dp(10), dp(6));
        GradientDrawable inputBackground = new GradientDrawable();
        inputBackground.setColor(Color.rgb(30, 30, 46));
        inputBackground.setCornerRadius(dp(6));
        promptComposerInput.setBackground(inputBackground);
        promptComposerInput.setOnEditorActionListener((textView, actionId, event) -> {
            if (actionId == EditorInfo.IME_ACTION_SEND
                    || actionId == EditorInfo.IME_ACTION_DONE
                    || actionId == EditorInfo.IME_ACTION_GO) {
                // WHY: phone Enter/IME action must match the visible Send button,
                // just like desktop Enter submits the current prompt. Keep both
                // paths on the single `/submit-text` paste+Enter route so Enter
                // cannot become a raw tmux key while a native draft is visible.
                submitDockedPrompt();
                return true;
            }
            return false;
        });
        promptComposerInput.addTextChangedListener(new TextWatcher() {
            @Override
            public void beforeTextChanged(CharSequence s, int start, int count, int after) {
            }

            @Override
            public void onTextChanged(CharSequence s, int start, int before, int count) {
            }

            @Override
            public void afterTextChanged(Editable editable) {
                keepPromptComposerSelectionVisibleAfterLayout("text-changed");
                if (promptComposerProgrammaticTextChange || !isDockedPromptComposerVisible()) {
                    return;
                }
                // WHY: do not mirror every Android text change into tmux. That
                // old hidden `/draft-delta` mirror is the exact repeated regression:
                // Samsung/Gboard/voice composition could paste partial text into
                // tmux invisibly, duplicate words, leave Backspace with nothing
                // local to delete, or finish in the wrong tab after Active
                // switching. Normal phone typing is local-only until the visible
                // toolbar Send button calls the single `/submit-text` path.
                if (editable.length() == 0 || !hasStableWindowId(promptComposerDraftTargetKey)) {
                    // WHY: once a visible native draft has text, its target is
                    // pinned to the stable tmux `@windowId` where typing started.
                    // Toolbar `/active` polling can change `currentPhoneWindowId`
                    // while the composer is still open; retargeting on every edit
                    // is how a correction can paste into another session.
                    promptComposerDraftTargetKey = promptComposerTargetKey();
                }
                long draftRevision = rememberPromptComposerDraft(
                        promptComposerDraftTargetKey,
                        editable.toString()
                );
                rememberPromptComposerDraftSelection(
                        promptComposerDraftTargetKey,
                        draftRevision,
                        promptComposerInput.getSelectionStart(),
                        promptComposerInput.getSelectionEnd(),
                        editable.length()
                );
                promptComposerDraftLocalGeneration++;
            }
        });
        // WHY: do not add another Send/Cancel row below the existing toolbar. That
        // looked like hidden duplicate controls and made users think text was not
        // going into the terminal. The existing thumb-side Start button becomes Send
        // while this native composer is open, so there is one visible action path.
        // WHY: FEATURE give the input weighted width so a compact resend button
        // can share the same composer row without stealing the terminal's
        // vertical space (row height is unchanged). This is an inline composer
        // affordance, so it deliberately does NOT use toolbarNavigationButton
        // styling, which is reserved for the fixed toolbar action row.
        // WHY: LAYOUT REGRESSION FIX — a fixed dp(PROMPT_COMPOSER_INPUT_HEIGHT_DP)
        // height clamped the composer to a ~1-line sliver even as the user typed
        // multiple lines, so with the keyboard up they could not see what they were
        // composing (the reported "can't type" blocker). Grow with content
        // (minLines=1..maxLines=4) from a comfortable min tap-target height instead.
        // The row is above the title strip + action toolbar, so the box expands
        // upward into the terminal (weight=1 absorbs it) while staying anchored above
        // the keyboard — typing below the toolbar was already rejected (see
        // buildLayout WHY). Empty height is unchanged (min-height wins at 1 line).
        promptComposerInput.setMinHeight(dp(PROMPT_COMPOSER_INPUT_HEIGHT_DP));
        Button uploadButton = new Button(this);
        uploadButton.setText("+");
        uploadButton.setAllCaps(false);
        uploadButton.setTextSize(22);
        uploadButton.setTypeface(Typeface.create("sans-serif-medium", Typeface.NORMAL));
        uploadButton.setTextColor(Color.rgb(205, 214, 244));
        setTouchableBackground(uploadButton, Color.rgb(38, 41, 55), Color.rgb(137, 180, 250));
        uploadButton.setPadding(0, 0, 0, 0);
        uploadButton.setIncludeFontPadding(false);
        uploadButton.setMinWidth(0);
        uploadButton.setMinimumWidth(0);
        uploadButton.setMinHeight(0);
        uploadButton.setMinimumHeight(0);
        uploadButton.setContentDescription("Upload screenshot or file");
        uploadButton.setTooltipText("Upload screenshot or file");
        uploadButton.setOnClickListener(v -> {
            flashTap(v);
            pickMediaForUpload();
        });
        LinearLayout.LayoutParams uploadParams = new LinearLayout.LayoutParams(
                dp(48),
                dp(48)
        );
        uploadParams.gravity = android.view.Gravity.BOTTOM;
        uploadParams.setMargins(0, 0, dp(6), 0);
        // WHY (#30 missing Upload while typing): composer focus deliberately hides
        // the navigation row to protect the editor/cursor above the IME, and Upload
        // now lives only in that hidden row. Keep the six protected action-row
        // controls at their accepted widths and expose the existing picker through
        // one standard 48dp attachment target beside the editor. Do not hide or
        // rewrite the draft here: ACTION_OPEN_DOCUMENT/Photo Picker return, Android
        // share intents, and chunked upload continue through the existing owner.
        // This control never touches terminal/WebView focus, scrolling, or rendering.
        composer.addView(uploadButton, uploadParams);
        composer.addView(promptComposerInput, new LinearLayout.LayoutParams(
                0,
                LinearLayout.LayoutParams.WRAP_CONTENT,
                1f
        ));
        Button resendButton = new Button(this);
        resendButton.setText("⟲");
        resendButton.setAllCaps(false);
        resendButton.setTextSize(18);
        resendButton.setTypeface(Typeface.create("sans-serif-medium", Typeface.NORMAL));
        resendButton.setTextColor(Color.rgb(205, 214, 244));
        setTouchableBackground(resendButton, Color.rgb(38, 41, 55), Color.rgb(137, 180, 250));
        resendButton.setPadding(0, 0, 0, 0);
        resendButton.setIncludeFontPadding(false);
        resendButton.setContentDescription("Recent sent messages");
        resendButton.setOnClickListener(v -> {
            flashTap(v);
            showSentHistoryPicker();
        });
        LinearLayout.LayoutParams resendParams = new LinearLayout.LayoutParams(
                dp(48),
                dp(48)
        );
        // WHY: a 40x44dp resend target was smaller than Android's standard 48dp
        // touch target and detached from the newest line as the editor grew.
        // Match Upload's 48dp target and the composer's lower anchor; weighted
        // editor width still absorbs narrow mobile/desktop viewport differences.
        resendParams.gravity = android.view.Gravity.BOTTOM;
        resendParams.setMargins(dp(6), 0, 0, 0);
        composer.addView(resendButton, resendParams);

        return composer;
    }

    private TextView buildSessionTitleStrip() {
        TextView title = new TextView(this);
        // WHY: phone users lose the desktop tmux title bar but still need a
        // constant target check before typing/sending. The selected-session title
        // must wrap here instead of disappearing behind an ellipsis, because the
        // title is the user's last chance to catch wrong-session input before
        // Send/Close. Keep the strip native and read-only so it cannot resize tmux
        // or steal WebView focus; only the Android chrome grows to fit the label.
        title.setSingleLine(false);
        title.setMaxLines(Integer.MAX_VALUE);
        title.setEllipsize(null);
        title.setHorizontallyScrolling(false);
        title.setMinHeight(dp(TITLE_STRIP_MIN_HEIGHT_DP));
        title.setLineSpacing(dp(TITLE_STRIP_LINE_SPACING_DP), 1.0f);
        title.setGravity(android.view.Gravity.CENTER);
        title.setTextSize(12);
        title.setTypeface(Typeface.create("sans-serif-medium", Typeface.NORMAL));
        title.setTextColor(Color.rgb(224, 230, 247));
        title.setBackgroundColor(Color.rgb(17, 18, 24));
        title.setPadding(dp(8), dp(2), dp(8), dp(2));
        title.setText("");
        title.setContentDescription("Active session title unavailable");
        title.setOnClickListener(view -> showRememberedUploadForCurrentWindow());
        title.setOnLongClickListener(view -> pasteRememberedUploadForCurrentWindow());
        title.addOnLayoutChangeListener((view, left, top, right, bottom, oldLeft, oldTop, oldRight, oldBottom) -> {
            CharSequence text = title.getText();
            if (text != null && text.length() >= TITLE_STRIP_LONG_TEXT_MIN_CHARS) {
                ensureWrappedTitleFit(title, text.toString(), "session-title-strip");
            }
        });
        return title;
    }

    private LinearLayout bottomBar() {
        // WHY: keep field references to the toolbar container and navigation row
        // so IME/inset reconciliation can reassert the accepted two-row layout.
        // The composer + owns visible upload now; removing only the redundant
        // standalone Upload leaves New/Old/Active/Bottom wide enough to remain
        // visible and tappable while the user is typing.
        LinearLayout toolbar = (bottomToolbar = new LinearLayout(this));
        toolbar.setOrientation(LinearLayout.VERTICAL);
        toolbar.setPadding(dp(6), dp(5), dp(6), dp(5));
        toolbar.setBackgroundColor(Color.rgb(17, 18, 24));
        LinearLayout topRow = (toolbarNavRow = toolbarRow());
        LinearLayout bottomRow = toolbarRow();
        toolbarStatusDot = toolbarStatusDotView();
        topRow.addView(toolbarStatusDot, new LinearLayout.LayoutParams(
                dp(24),
                LinearLayout.LayoutParams.MATCH_PARENT
        ));
        // WHY: Active Sessions is the operator's most-used correction surface.
        // Keep it near the right thumb while New stays available for explicit
        // creation without changing either endpoint or click handler.
        topRow.addView(toolbarNavigationButton("New", v ->
                controlAndSettleLiveBottom("/new?fast=1", "", "new-session")));
        topRow.addView(toolbarNavigationButton("Old", v -> showOldSessions()));
        topRow.addView(toolbarNavigationButton("Active", v -> showActiveSessions()));
        // WHY: live-bottom is the user's most frequent recovery when one-finger
        // return-to-bottom still misses the final prompt line. Keep it as a one-tap
        // button on the right side of the top row instead of burying it in the
        // fallback Scroll dialog. This must call the fast `/live-bottom` path, not
        // the heavy proof `/scroll?where=bottom` path that caused refresh loops.
        topRow.addView(toolbarNavigationButton("Bottom", v -> goLiveBottom()));
        // WHY: phone paste must be a first-class action, not a keyboard long-press
        // trick. The button opens explicit copy/paste controls backed by Android
        // clipboard APIs and tmux paste buffers, so prompts can be moved between
        // phone apps and the exact active desktop pane.
        Button copyPasteButton = toolbarNavigationButton("Copy/Paste", v -> showCopyPasteControls());
        preventCopyPasteToolbarClipping(copyPasteButton);
        copyPasteButton.setOnLongClickListener(v -> {
            // WHY: upload is also available as its own toolbar button, but a
            // long-press here preserves muscle memory for "send phone content into
            // this terminal" without hiding the older copy/paste menu.
            hideDockedPromptComposerForNavigation("toolbar-copy-paste-long-press");
            pickMediaForUpload();
            return true;
        });
        bottomRow.addView(copyPasteButton);
        bottomRow.addView(toolbarNavigationButton("Workspace", v -> showWorkspaces()));
        // WHY: Settings is the right home for persistent APK preferences such as
        // Desktop/Mobile viewport mode, but the protected Refresh/Scroll recovery
        // actions still live here. This is a container rename, not a control
        // removal or gesture-owner change.
        Button settingsButton = toolbarNavigationButton("Settings", v -> showToolbarSettings());
        settingsButton.setOnLongClickListener(v -> {
            hideDockedPromptComposerForNavigation("toolbar-settings-long-press");
            showCommandPalette();
            return true;
        });
        bottomRow.addView(settingsButton);
        // WHY: Close kills the selected tmux window, but user proof showed red
        // Close beside red Stop made the toolbar read like two identical danger
        // controls. Keep the exact Close handler and stable target guard, while
        // tinting Close as a neutral slate action so red means only Stop.
        Button closeButton = toolbarNavigationButton("Close", v -> confirmClose());
        applyToolbarActionRole(closeButton,
                Color.rgb(48, 52, 70),
                Color.rgb(137, 180, 250),
                Color.rgb(232, 238, 255));
        bottomRow.addView(closeButton);
        // WHY: the user reported that a single smart combined button was not
        // predictable under pressure. Keep the two thumb-side actions separate:
        // Start always means "submit/send Enter", while Stop always means
        // "interrupt with Escape". Long-press Start opens the native composer so
        // a full prompt can be sent as one tmux paste when WebView/IME live typing
        // starts corrupting characters. Normal terminal-body taps now open the same
        // native typing layer instead of direct xterm IME input.
        startToolbarButton = toolbarButton("Start", v -> startCurrentTask());
        startToolbarButton.setOnLongClickListener(v -> {
            showSafePromptComposer();
            return true;
        });
        final boolean[] sendTouchGestureOwned = {false};
        // WHY (#27 Send-doesn't-submit): while the composer is open this button is
        // "Send", and Samsung's IME/composer relayout can cancel ACTION_UP before
        // onClick runs. Fire only the Send-mode action on ACTION_DOWN; preserve the
        // unchanged Start-mode click, long-press, and accessibility click paths.
        startToolbarButton.setOnTouchListener((view, event) -> {
            int action = event.getActionMasked();
            if (action == MotionEvent.ACTION_DOWN && isDockedPromptComposerVisible()) {
                sendTouchGestureOwned[0] = true;
                view.setPressed(true);
                flashTap(view);
                startCurrentTask();
                return true;
            }
            if (sendTouchGestureOwned[0]) {
                if (action == MotionEvent.ACTION_UP || action == MotionEvent.ACTION_CANCEL) {
                    sendTouchGestureOwned[0] = false;
                    view.setPressed(false);
                }
                // WHY: startCurrentTask hides the composer during ACTION_DOWN.
                // Keep ownership of this same gesture so its orphaned release
                // cannot reach the Start click path or leave the button pressed.
                return true;
            }
            if (action == MotionEvent.ACTION_UP || action == MotionEvent.ACTION_CANCEL) {
                view.setPressed(false);
            }
            return false;
        });
        // WHY: Start (and its visible `Send` state while the composer is open) is the
        // positive go action — tint it the green role plate. The Start<->Send toggle
        // only calls setText, never re-applies a background, so this single tint holds
        // for both labels.
        applyToolbarActionRole(startToolbarButton,
                Color.rgb(128, 217, 164),
                Color.rgb(166, 227, 161),
                Color.rgb(15, 38, 28));
        bottomRow.addView(startToolbarButton);
        Button stopButton = toolbarButton("Stop", v -> stopCurrentTask());
        stopButton.setOnLongClickListener(v -> {
            hideDockedPromptComposerForNavigation("toolbar-stop-long-press");
            showKeyControls();
            return true;
        });
        // WHY: Stop interrupts the running task (Escape) — tint it the red
        // destructive role so it reads as "stop/danger" at a glance, distinct from
        // the green Start beside it.
        applyToolbarActionRole(stopButton,
                Color.rgb(96, 54, 68),
                Color.rgb(203, 95, 120),
                Color.rgb(255, 228, 234));
        bottomRow.addView(stopButton);
        toolbar.addView(topRow, new LinearLayout.LayoutParams(
                LinearLayout.LayoutParams.MATCH_PARENT,
                0,
                1
        ));
        toolbar.addView(bottomRow, new LinearLayout.LayoutParams(
                LinearLayout.LayoutParams.MATCH_PARENT,
                0,
                1
        ));
        return toolbar;
    }

    private LinearLayout toolbarRow() {
        LinearLayout row = new LinearLayout(this);
        row.setOrientation(LinearLayout.HORIZONTAL);
        row.setPadding(0, dp(1), 0, dp(1));
        return row;
    }

    private Button toolbarButton(String label, View.OnClickListener listener) {
        Button button = button(label, listener);
        if (!"Settings".equals(label) && !"Copy/Paste".equals(label) && !"Start".equals(label)) {
            installPlainToolbarTapHandler(button);
        }
        // WHY: 10-11sp toolbar labels were a logged "font too small" complaint on
        // QHD, but real v2.62 proof showed `Workspace` clipping at 12sp inside
        // the six-column toolbar. Keep short commands large and step long labels
        // down so the visible APK button still says Workspace, not Workspac.
        button.setTextSize(label.length() >= 9 ? 11 : 13);
        button.setSingleLine(true);
        button.setIncludeFontPadding(false);
        button.setMinWidth(0);
        button.setMinimumWidth(0);
        // WHY: the 2026-06-23 bottom proof showed the fixed two-row toolbar had
        // become oversized phone chrome. Keep two thumb rows and the same buttons,
        // but cap each row to a compact 42dp target so the terminal can use the
        // viewport instead of losing it to button real estate.
        button.setMinHeight(dp(42));
        button.setGravity(android.view.Gravity.CENTER);
        button.setPadding(dp(3), 0, dp(3), 0);
        LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(
                0,
                LinearLayout.LayoutParams.MATCH_PARENT,
                1
        );
        params.setMargins(dp(3), 0, dp(3), 0);
        button.setLayoutParams(params);
        return button;
    }

    private void preventCopyPasteToolbarClipping(Button button) {
        // WHY: the fixed six-column bottom row has enough tap area but not enough
        // one-line text width for `Copy/Paste` on the real APK keyboard layout.
        // Keep the same handler/status label, but force the visible button text to
        // a measured two-line label so future toolbar edits cannot regress to
        // `Copy/Past` or other clipped bottom-button text.
        button.setText("Copy\nPaste");
        button.setSingleLine(false);
        button.setMaxLines(2);
        button.setTextSize(10);
        button.setLineSpacing(0f, 0.92f);
        button.setIncludeFontPadding(false);
        button.setGravity(android.view.Gravity.CENTER);
    }

    private Button toolbarNavigationButton(String label, View.OnClickListener listener) {
        return toolbarButton(label, view -> {
            showToolbarControlPending(label);
            hideDockedPromptComposerForNavigation("toolbar-" + label.toLowerCase(Locale.US));
            listener.onClick(view);
        });
    }

    // WHY: v2.05 rendered all toolbar buttons in identical flat slate chrome, but
    // the 2026-06-27 visual pass also found bright red Stop/Close too harsh. Keep
    // action-role color for one-handed scanning while muting destructive controls
    // and preserving the exact existing button handlers. Start and Stop stay
    // separate buttons (v1.54); this helper is visual-only and must never merge
    // them into one smart button.
    private void applyToolbarActionRole(Button button, int baseColor, int rippleColor, int textColor) {
        setTouchableBackground(button, baseColor, rippleColor);
        button.setTextColor(textColor);
    }

    private TextView toolbarStatusDotView() {
        TextView dot = new StatusDotTextView(this);
        dot.setText("●");
        // WHY: the always-visible status dot is the app's fastest state channel.
        // The 2026-06-27 visual pass raised it again for phone readability, while
        // preserving the dot-only/lifecycle-scoped alpha pulse from v1.93.
        dot.setTextSize(PREMIUM_STATUS_DOT_SP);
        dot.setGravity(android.view.Gravity.CENTER);
        dot.setIncludeFontPadding(false);
        dot.setContentDescription("Session status");
        // WHY: the user can spend minutes reading scrollback while a Codex tab
        // finishes or starts waiting for approval. This tiny dot reuses the same
        // control-server status evidence and colors as Active Sessions, but it lives
        // in the always-visible button area so the user does not need to open the
        // tab picker just to learn whether the current tab is Working/Ready/Done.
        dot.setOnTouchListener((view, event) -> {
            if (event != null
                    && event.getActionMasked() == MotionEvent.ACTION_DOWN) {
                markActiveSessionsActionDown(event);
            }
            return false;
        });
        dot.setOnClickListener(v -> showActiveSessions());
        applySessionStatusDot(dot, "unknown", false, "Unknown");
        return dot;
    }

    private void applySessionStatusDot(TextView dot, String status, boolean needsAttention, String statusLabel) {
        applySessionStatusDot(dot, status, needsAttention, statusLabel, "", true);
    }

    private void applySessionStatusDot(TextView dot, String status, boolean needsAttention, String statusLabel, String statusTone) {
        applySessionStatusDot(dot, status, needsAttention, statusLabel, statusTone, true);
    }

    private void applySessionStatusDot(TextView dot, String status, boolean needsAttention, String statusLabel, String statusTone, boolean activeSession) {
        if (dot == null) {
            return;
        }
        dot.setContentDescription(statusLabel == null || statusLabel.isEmpty() ? "Session status" : statusLabel);
        String normalizedStatus = status == null ? "" : status.trim().toLowerCase(Locale.US);
        String tone = statusTone == null ? "" : statusTone.trim().toLowerCase(Locale.US);
        // WHY: statusTone=healthy means "non-attention", not "working". The
        // APK regressed by painting Ready/Done rows green, so Active Sessions
        // looked all-good while only the running Codex panes were actually
        // working. Green is reserved for the central working/running state.
        boolean working = isWorkingSessionStatus(normalizedStatus, tone);
        if ("problem".equals(normalizedStatus) || "problem".equals(tone)) {
            stopStatusDotPulse(dot);
            dot.setTextColor(sessionStatusTextColor(normalizedStatus, needsAttention, tone));
        } else if (working) {
            // WHY: Active Sessions dots show live session state, not selected-tab
            // state. A background Codex pane that is still Working must stay
            // green, but Ready/Done rows are not working and must not look green.
            dot.setTextColor(sessionStatusTextColor(normalizedStatus, needsAttention, tone));
            startStatusDotPulse(dot);
        } else if (needsAttention || "warning".equals(tone) || "waiting".equals(normalizedStatus)) {
            stopStatusDotPulse(dot);
            dot.setTextColor(sessionStatusTextColor(normalizedStatus, needsAttention, tone));
        } else {
            stopStatusDotPulse(dot);
            dot.setTextColor(sessionStatusTextColor(normalizedStatus, needsAttention, tone));
        }
    }

    private boolean isWorkingSessionStatus(String status, String tone) {
        return "running".equals(status)
                || "working".equals(status)
                || "running".equals(tone)
                || "working".equals(tone);
    }

    private int sessionStatusTextColor(String status, boolean needsAttention, String statusTone) {
        String normalizedStatus = status == null ? "" : status.trim().toLowerCase(Locale.US);
        String tone = statusTone == null ? "" : statusTone.trim().toLowerCase(Locale.US);
        if ("problem".equals(normalizedStatus) || "problem".equals(tone)) {
            return Color.rgb(243, 139, 168);
        }
        if (isWorkingSessionStatus(normalizedStatus, tone)) {
            return Color.rgb(166, 227, 161);
        }
        if (needsAttention || "warning".equals(tone) || "waiting".equals(normalizedStatus)) {
            return Color.rgb(249, 226, 175);
        }
        return Color.rgb(127, 132, 156);
    }

    private void showToolbarControlPending(String label) {
        if (toolbarStatusDot == null) {
            return;
        }
        // WHY: endpoint timings on 2026-06-29 showed `/tabs?light=1` can take
        // 1.5s and `/live-bottom` can take 800ms. The phone must acknowledge the
        // tap locally before tmux/network confirmation arrives, or controls feel
        // dead even when the backend is healthy.
        String safeLabel = label == null || label.trim().isEmpty() ? "control" : label.trim();
        applySessionStatusDot(toolbarStatusDot, "running", false, safeLabel + " pending");
        // WHY(toolbar racing-writers 2026-07-28, holistic #8): the optimistic "running" dot is a
        // brief tap acknowledgement, but on a session that is actually stopped/Ready it sat GREEN
        // until the next scheduled /active poll (the user's "green should be yellow"). Immediately
        // reclaim the canonical /active status so the dot settles to the real state (yellow=Ready)
        // as soon as the network responds, not a poll cycle later. scheduleToolbarStatusDotRefresh
        // is generation-deduped, so rapid taps coalesce (no poll storm), and this remains the
        // SINGLE optimistic "running" writer (the toolbar guard's one-writer invariant is intact).
        scheduleToolbarStatusDotRefresh(0);
        Log.i(CONTROL_LOG_TAG,
                "stage=control-local"
                        + " control=" + safeLogToken(safeLabel)
                        + " result=pending-indicator");
    }

    private void startStatusDotPulse(TextView dot) {
        Object tag = dot.getTag();
        if (tag instanceof ObjectAnimator) {
            ObjectAnimator existing = (ObjectAnimator) tag;
            if (existing.isStarted() || existing.isRunning()) {
                return;
            }
        }
        stopStatusDotPulse(dot);
        // WHY: desktop tmux lag came from animating/redrawing more than the fixed
        // status dot. Keep the phone pulse on the tiny TextView's alpha property
        // only, reuse it while the state stays running, and cancel it on detach or
        // pause so background WEzTerm cannot keep invalidating the WebView surface.
        dot.setLayerType(View.LAYER_TYPE_HARDWARE, null);
        dot.setAlpha(STATUS_DOT_FULL_ALPHA);
        ObjectAnimator pulse = ObjectAnimator.ofFloat(
                dot,
                View.ALPHA,
                STATUS_DOT_DIM_ALPHA,
                STATUS_DOT_FULL_ALPHA
        );
        pulse.setDuration(STATUS_DOT_PULSE_MS);
        pulse.setRepeatMode(ValueAnimator.REVERSE);
        pulse.setRepeatCount(ValueAnimator.INFINITE);
        pulse.setInterpolator(new AccelerateDecelerateInterpolator());
        dot.setTag(pulse);
        pulse.start();
    }

    private void stopStatusDotPulse(TextView dot) {
        if (dot == null) {
            return;
        }
        Object tag = dot.getTag();
        if (tag instanceof ObjectAnimator) {
            ((ObjectAnimator) tag).cancel();
        }
        dot.setTag(null);
        dot.animate().cancel();
        dot.clearAnimation();
        dot.setLayerType(View.LAYER_TYPE_NONE, null);
        dot.setAlpha(STATUS_DOT_FULL_ALPHA);
    }

    private void stopStatusDotPulsesInTree(View root) {
        if (root == null) {
            return;
        }
        if (root instanceof StatusDotTextView) {
            stopStatusDotPulse((TextView) root);
        }
        if (!(root instanceof ViewGroup)) {
            return;
        }
        ViewGroup group = (ViewGroup) root;
        for (int index = 0; index < group.getChildCount(); index++) {
            stopStatusDotPulsesInTree(group.getChildAt(index));
        }
    }

    private void scheduleToolbarStatusDotRefresh(long delayMs) {
        if (toolbarStatusDot == null || !activityResumed) {
            return;
        }
        long generation = ++toolbarStatusGeneration;
        uiHandler.postDelayed(() -> {
            if (generation != toolbarStatusGeneration || !activityResumed) {
                return;
            }
            refreshToolbarStatusDot(generation);
        }, Math.max(0, delayMs));
    }

    private void refreshToolbarStatusDot(long generation) {
        if (toolbarStatusDot == null || !activityResumed || generation != toolbarStatusGeneration) {
            return;
        }
        // WHY: this poll only feeds the compact title strip/status dot. Keep it
        // on the read-only active endpoint so a stale APK cannot resize the
        // shared tmux window while desktop/web clients are open.
        getJson("/active?readOnly=1", payload -> {
            if (generation != toolbarStatusGeneration || !activityResumed) {
                return;
            }
            JSONObject window = payload.optJSONObject("window");
            if (window != null) {
                rememberActivePhoneWindow(window, "toolbar-status");
                if (activeStatusMatchesVisibleTarget(window)) {
                    updateSessionTitleStrip(window);
                    String statusWindowId = stableWindowIdFromPayload(
                            window,
                            "",
                            "displayWindowId",
                            "selectedWindowId",
                            "windowId"
                    );
                    if (activeSwitchTitleLifecycle.phase()
                            == ActiveSwitchPhase.BLOCKED_KEEP_LAST_GOOD
                            && activeSwitchTitleLifecycle.blocksSendFor(statusWindowId)) {
                        applySessionStatusDot(
                                toolbarStatusDot,
                                "blocked",
                                true,
                                "Waiting for matching session body",
                                "warning",
                                true
                        );
                    } else {
                        SendStatusRevisionFence.Status presentedStatus =
                                sessionStatusForDisplay(window);
                        applySessionStatusDot(
                                toolbarStatusDot,
                                presentedStatus.state,
                                presentedStatus.needsAttention,
                                presentedStatus.label.isEmpty()
                                        ? "Unknown"
                                        : presentedStatus.label,
                                presentedStatus.tone,
                                window.optBoolean("active", true)
                        );
                    }
                } else {
                    reconcileVisibleTargetAfterActiveMismatch(window, "toolbar-status");
                    // WHY: `/active` is process-global tmux state, while the APK
                    // body can be pinned to a selected read-only capture target.
                    // Do not paint the toolbar title/status for one `@windowId`
                    // over another session's renderer body; Active switching must
                    // keep title and capture target atomic.
                    updateSessionTitleStripFromVisibleRenderer("toolbar-status-visible-target-mismatch");
                    // WHY(toolbar dot green-should-be-yellow 2026-07-28): the /active
                    // visible-target MISMATCH branch repainted the title but left the toolbar
                    // status dot on its last optimistic paint (a frozen green on a stopped
                    // session). Repaint the dot from the VISIBLE window's canonical per-window
                    // typed status so a settled/stopped session shows YELLOW=Ready, never a
                    // stale green. Gate on !sessionSwitchInFlight so an in-flight switch keeps
                    // its transient pending dot until the switch settles (the settled painter
                    // reads serverConfirmedStatusByWindow for confirmedVisibleTerminalTargetKey).
                    if (!sessionSwitchInFlight) {
                        applySettledActiveSwitchStatusDot(confirmedVisibleTerminalTargetKey());
                    }
                    Log.i(CONTROL_LOG_TAG,
                            "stage=toolbar-status endpoint=/active result=visible-target-mismatch"
                                    + " activeWindowId=" + safeWindowIdForControlLog(window.optString("windowId", ""))
                                    + " visibleWindowId=" + safeWindowIdForControlLog(visibleTerminalTargetKey())
                                    + " selectedWindowId=" + safeWindowIdForControlLog(selectedPhoneWindowId)
                                    + " interactiveWindowId=" + safeWindowIdForControlLog(selectedPhoneInteractiveWindowId)
                                    + " currentWindowId=" + safeWindowIdForControlLog(currentPhoneWindowId)
                                    + " captureTargetWindowId=" + safeWindowIdForControlLog(captureRendererWindowTargetKey)
                                    + " confirmedTargetWindowId=" + safeWindowIdForControlLog(confirmedCaptureRendererWindowTargetKey)
                                    + " webViewWindowId=" + safeWindowIdForControlLog(currentWebViewWindowIdTargetKey())
                                    + " frameWindowId=" + safeWindowIdForControlLog(lastAcceptedCaptureRendererFrameWindowId)
                                    + " frameHash=" + safeLogToken(lastAcceptedCaptureRendererFrameHash)
                                    + " sessionSwitchInFlight=" + sessionSwitchInFlight);
                }
            }
            scheduleToolbarStatusDotRefresh(TOOLBAR_STATUS_POLL_MS);
        }, exc -> {
            if (generation != toolbarStatusGeneration || !activityResumed) {
                return;
            }
            keepSessionTitleOnControlFailure("toolbar-status-unreachable");
            applySessionStatusDot(toolbarStatusDot, "unknown", true, "Mantis Control unreachable");
            scheduleToolbarStatusDotRefresh(TOOLBAR_STATUS_POLL_MS);
        });
    }

    private Button button(String label, View.OnClickListener listener) {
        Button button = new Button(this);
        button.setText(label);
        button.setAllCaps(false);
        button.setTextSize(13);
        button.setTypeface(Typeface.create("sans-serif-medium", Typeface.NORMAL));
        button.setTextColor(Color.rgb(228, 233, 249));
        setTouchableBackground(button, Color.rgb(38, 41, 55), Color.rgb(137, 180, 250));
        button.setPadding(dp(4), 0, dp(4), 0);
        button.setOnClickListener(v -> {
            flashTap(v);
            if (listener != null) {
                listener.onClick(v);
            }
        });
        LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(
                0,
                LinearLayout.LayoutParams.MATCH_PARENT,
                1
        );
        params.setMargins(dp(4), 0, dp(4), 0);
        button.setLayoutParams(params);
        return button;
    }

    private void installPlainToolbarTapHandler(Button button, String label) {
        // WHY: real phone proof showed center taps on the `Active` toolbar button
        // could be ignored while an offset tap inside the same visible button
        // worked. Plain toolbar buttons have no protected long-press secondary
        // action, so fire on ACTION_DOWN before Samsung's IME/composer layout can
        // cancel or move the ACTION_UP. Do not install this on Scroll, Copy/Paste,
        // or Start; those buttons intentionally keep long-press behavior.
        button.setOnTouchListener((view, event) -> {
            switch (event.getActionMasked()) {
                case MotionEvent.ACTION_DOWN:
                    if ("Active".equals(label)) {
                        markActiveSessionsActionDown(event);
                    }
                    view.setPressed(true);
                    view.performClick();
                    return true;
                case MotionEvent.ACTION_UP:
                    view.setPressed(false);
                    return true;
                case MotionEvent.ACTION_CANCEL:
                    view.setPressed(false);
                    return true;
                default:
                    return true;
            }
        });
    }

    private void installPlainToolbarTapHandler(Button button) {
        String label = button == null || button.getText() == null
                ? ""
                : button.getText().toString();
        installPlainToolbarTapHandler(button, label);
    }

    private void markActiveSessionsActionDown(MotionEvent event) {
        pendingActiveSessionsActionDownUptimeMs =
                event == null ? 0 : Math.max(0, event.getEventTime());
    }

    private long consumeActiveSessionsActionDownUptimeMs() {
        long actionDownUptimeMs = pendingActiveSessionsActionDownUptimeMs;
        pendingActiveSessionsActionDownUptimeMs = 0;
        return actionDownUptimeMs;
    }

    private void bindActiveSessionsDialogDrawAction(
            String actionId,
            String tapId,
            String windowId,
            long actionDownUptimeMs,
            long dataRevision
    ) {
        activeSessionsDialogDrawActionId = actionId == null ? "" : actionId;
        activeSessionsDialogDrawTapId = tapId == null ? "" : tapId;
        activeSessionsDialogDrawWindowId =
                hasStableWindowId(windowId) ? windowId.trim() : "";
        activeSessionsDialogDrawActionDownUptimeMs =
                Math.max(0, actionDownUptimeMs);
        activeSessionsDialogDrawDataRevision = dataRevision;
    }

    private void setTouchableBackground(View view, int baseColor, int rippleColor) {
        GradientDrawable base = new GradientDrawable();
        base.setColor(baseColor);
        base.setCornerRadius(dp(PREMIUM_CONTROL_CORNER_RADIUS_DP));
        // WHY: the APK visual shell should feel like native app chrome, not a
        // flat debug panel. The stroke/elevation are visual-only and preserve the
        // exact click handlers, endpoints, and tmux targets attached to each view.
        base.setStroke(dp(1), PREMIUM_CONTROL_STROKE_COLOR);
        view.setBackground(new RippleDrawable(ColorStateList.valueOf(rippleColor), base, null));
        view.setHapticFeedbackEnabled(true);
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.LOLLIPOP) {
            view.setElevation(dp(PREMIUM_BUTTON_ELEVATION_DP));
        }
    }

    private GradientDrawable roundedFill(int color, int radiusDp, int strokeColor) {
        GradientDrawable drawable = new GradientDrawable();
        drawable.setColor(color);
        drawable.setCornerRadius(dp(radiusDp));
        drawable.setStroke(dp(1), strokeColor);
        return drawable;
    }

    private void flashTap(View view) {
        view.performHapticFeedback(HapticFeedbackConstants.VIRTUAL_KEY);
        view.animate().cancel();
        view.setAlpha(0.72f);
        view.animate().alpha(1f).setDuration(140).start();
    }

    private void configureWindow() {
        requestWindowFeature(Window.FEATURE_NO_TITLE);
        Window window = getWindow();
        // WHY: Android's `stateVisible` is an activity-start keyboard request.
        // This app must not open or reconnect by creating an IME/editor session;
        // only a deliberate tap, paste, safe prompt, or Start/Stop flow may ask
        // for terminal typing focus. Keeping adjustResize alone preserves the
        // "keyboard stays below the visible composer" layout without restarting
        // Samsung/Gboard composition when WEzterm resumes.
        window.setSoftInputMode(
                WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE
        );
        keepScreenAwakeForActiveTerminal();
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.LOLLIPOP) {
            window.setStatusBarColor(Color.rgb(16, 16, 20));
            // WHY: Samsung's three-button navigation area is outside the app's
            // clickable toolbar, but painting it black made it read as a giant dead
            // gap under WEzTerm's buttons. Match the toolbar plate so the system
            // nav strip is visually attached instead of a separate black spacer.
            window.setNavigationBarColor(Color.rgb(17, 18, 24));
        }
        hideNavigationDeadStrip("configure-window");
    }

    private void hideNavigationDeadStrip(String reason) {
        Window window = getWindow();
        if (window == null) {
            return;
        }
        View decor = window.getDecorView();
        if (decor == null) {
            return;
        }
        if (lastImeInsetBottom > 0 || isDockedPromptComposerVisible()) {
            // WHY: v2.80 keeps the bottom typing anchor stable while the keyboard or
            // native composer is visible. Hiding navigation bars and requesting fresh
            // insets during IME settle can move the visible bottom after Android has
            // already resized the activity, which reintroduced the black gap/slow
            // tap-to-type feel the old v1.65-v2.60 layout avoided.
            return;
        }
        // WHY: matching the navigation-bar color still left a full Android nav
        // region below the toolbar that the user read as wasted black space. Use
        // Android's immersive navigation-bar API with transient swipe reveal so
        // the APK buttons occupy the actual bottom without a permanent spacer.
        long now = System.currentTimeMillis();
        boolean requestInsets = now - lastNavigationHideAtMs > 900;
        lastNavigationHideAtMs = now;
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.R) {
            WindowInsetsController controller = window.getInsetsController();
            if (controller != null) {
                controller.setSystemBarsBehavior(
                        WindowInsetsController.BEHAVIOR_SHOW_TRANSIENT_BARS_BY_SWIPE
                );
                controller.hide(WindowInsets.Type.navigationBars());
            }
            if (requestInsets && lastImeInsetBottom == 0) {
                decor.post(decor::requestApplyInsets);
            }
            return;
        }
        decor.setSystemUiVisibility(
                View.SYSTEM_UI_FLAG_HIDE_NAVIGATION
                        | View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY
                        | View.SYSTEM_UI_FLAG_LAYOUT_HIDE_NAVIGATION
                        | View.SYSTEM_UI_FLAG_LAYOUT_STABLE
        );
    }

    private void keepScreenAwakeForActiveTerminal() {
        // WHY: real phone proof and real phone coding sessions are long-running.
        // If Android locks while WEzterm is the foreground terminal, ADB proof
        // falls onto the secure Bouncer and the user loses the live control
        // surface. Reassert the window flag on create/resume and set
        // keepScreenOn on the terminal views below; this prevents sleep only
        // while this activity is visible and does not bypass the lockscreen or
        // change any tmux/scroll/zoom behavior.
        getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);
        if (webView != null) {
            webView.setKeepScreenOn(true);
        }
        if (historyTouchOverlay != null) {
            historyTouchOverlay.setKeepScreenOn(true);
        }
    }

    private void configureWebView(WebView view) {
        view.setFocusable(true);
        view.setFocusableInTouchMode(true);
        view.setKeepScreenOn(true);
        view.addJavascriptInterface(new CaptureRendererBridge(), "WeztermCaptureBridge");
        // WHY: the terminal body must fail dark, not purple/blue, while xterm is
        // reconnecting or repainting. The real dotted-canvas regression was in
        // the WebView/xterm render layer, not tmux output; leaving the native
        // WebView background slate lets blank canvas cells show through during
        // session switches.
        view.setBackgroundColor(Color.BLACK);
        view.setVerticalScrollBarEnabled(false);
        view.setHorizontalScrollBarEnabled(false);
        view.setScrollBarStyle(View.SCROLLBARS_INSIDE_OVERLAY);
        view.setScrollContainer(false);
        // WHY: Android's edge effects can make a WebView pan look like the page
        // is refreshing or fighting the user's finger. The terminal already has
        // explicit Live/Read controls, so native overscroll feedback is noise.
        view.setOverScrollMode(View.OVER_SCROLL_NEVER);
        view.addOnLayoutChangeListener((changedView, left, top, right, bottom, oldLeft, oldTop, oldRight, oldBottom) -> {
            if ((right - left) == (oldRight - oldLeft) && (bottom - top) == (oldBottom - oldTop)) {
                return;
            }
            // WHY: Android can shrink the WebView for the native composer,
            // keyboard, or system bars without a ttyd page reload. If xterm keeps
            // painting against the previous row/canvas height, the phone exposes a
            // dotted blank field and a zoomed viewer cannot pan to the true prompt
            // bottom. Dispatch a lightweight resize/redraw only; do not revive
            // xterm scrollToBottom, WebView reload, or IME focus bursts here. v2.47
            // also keeps the row-level dot scrubber alive during composer/keyboard
            // layout shrink, because the uploaded 21:23 phone screenshot proved the
            // stale full-view dot grid can appear while the native composer is open,
            // not only after an Active Sessions switch.
            fitTerminalToCurrentViewSoon("webview-layout");
        });
        view.setOnScrollChangeListener((changedView, scrollX, scrollY, oldScrollX, oldScrollY) -> {
            if (scrollX != 0 || scrollY != 0) {
                if (isViewerPanAllowed()) {
                    // WHY: Android/WebView zoom is the viewer zoom layer. v1.41's
                    // unconditional scrollTo(0,0) fixed old blank-space drift, but
                    // it also erased zoomed left/right positioning and made pinch
                    // panning look broken. While zoomed, in a two-finger gesture, or
                    // in a deliberate horizontal pan, WebView owns positioning; one
                    // finger vertical history movement is still handled by tmux.
                    return;
                }
                // WHY: the visible terminal is xterm inside ttyd. Android
                // WebView document scroll is never the intended scroll layer and
                // creates the "below the text area" blank-space bug on older
                // tabs. Keep the browser viewport pinned while tmux/Codex owns
                // history movement.
                changedView.scrollTo(0, 0);
                pinTerminalViewportSoon("webview-scroll");
            }
        });
        view.setWebViewClient(new TerminalWebViewClient());
        view.setWebChromeClient(new WebChromeClient());
        terminalTouchSlop = ViewConfiguration.get(this).getScaledTouchSlop();
        view.setOnTouchListener((touchedView, event) -> handleTerminalTouch(event));

        WebSettings settings = view.getSettings();
        settings.setJavaScriptEnabled(true);
        settings.setDomStorageEnabled(true);
        settings.setDatabaseEnabled(true);
        settings.setLoadWithOverviewMode(true);
        settings.setUseWideViewPort(true);
        settings.setTextZoom(100);
        settings.setSupportZoom(true);
        settings.setBuiltInZoomControls(true);
        settings.setDisplayZoomControls(false);
        settings.setNeedInitialFocus(true);
        settings.setMediaPlaybackRequiresUserGesture(false);
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.LOLLIPOP) {
            settings.setMixedContentMode(WebSettings.MIXED_CONTENT_COMPATIBILITY_MODE);
        }
    }

    private boolean handleTerminalTouch(MotionEvent event) {
        int action = event.getActionMasked();
        boolean passiveNavigationTapSuppressed =
                System.currentTimeMillis() < terminalBodyTapSuppressedUntilMs;
        if (passiveNavigationTapSuppressed
                && action != MotionEvent.ACTION_DOWN
                && !terminalTouchStartedDuringPassiveSuppression
                && !terminalHistoryDragActive
                && !terminalMultiTouchGesture
                && !terminalHorizontalPanActive) {
            // WHY: passive tab-open suppression exists to swallow the stray
            // ACTION_UP from an Active/Old picker row so it cannot reopen the
            // native composer. It must not also block a real user scroll. If the
            // gesture did not start in this terminal view, consume only that
            // orphaned release/cancel path; terminal ACTION_DOWN below still owns
            // real scrolls so it can cancel black/dot masks and hide the keyboard.
            if (action == MotionEvent.ACTION_UP || action == MotionEvent.ACTION_CANCEL) {
                terminalHistoryDragActive = false;
                terminalMultiTouchGesture = false;
                terminalTouchExceededTapSlop = false;
                terminalHorizontalPanActive = false;
                terminalTouchReachedLiveBottom = false;
                terminalTouchSawUpwardHistoryIntent = false;
                terminalTouchStartedInHistoryViewport = false;
                terminalTouchContinuesReleasedReadHold = false;
                terminalTouchContinuesReleasedReadHoldPhysicalUpwardHistoryGesture = false;
                terminalTouchStartedDuringPassiveSuppression = false;
                terminalTouchStartedInTerminalBody = false;
                terminalTouchStartedInTypingBand = false;
                recycleTerminalVelocityTracker();
                recycleTerminalViewerDownEvent();
            }
            return true;
        }
        if (event.getPointerCount() > 1 || action == MotionEvent.ACTION_POINTER_DOWN) {
            // WHY: two-finger gestures belong to Android/WebView for viewer zoom
            // and positioning. The app must not consume them while trying to fix
            // tmux history, and the viewport pin must not snap them back to 0,0.
            // ACTION_DOWN is consumed so one-finger vertical scroll can stay tmux
            // owned from the start; when a second finger appears, replay the saved
            // DOWN into WebView before forwarding this event so native pinch zoom
            // has a complete gesture stream.
            if (!terminalMultiTouchGesture) {
                cancelCaptureRendererPointerForwarding(
                        event,
                        "multi-touch"
                );
                cancelPendingTerminalLongPressCopy("multi-touch");
                endTerminalSnapshotLease(
                        "viewer-multi-touch-handoff",
                        TerminalSnapshotEndMode.ABORT
                );
                // WHY: a second finger changes ownership from tmux history to the
                // Android/WebView viewer. Any outstanding one-finger scroll response
                // now belongs to an old gesture and must not later mark live-bottom
                // or replay queued movement after the user started zooming/panning.
                terminalTouchGestureGeneration++;
                terminalTouchReachedLiveBottom = false;
                terminalTouchSawUpwardHistoryIntent = false;
                terminalTouchPhysicalUpwardHistoryGesture = false;
                terminalTouchContinuesReleasedReadHold = false;
                terminalTouchContinuesReleasedReadHoldPhysicalUpwardHistoryGesture = false;
                terminalTouchStartedInTerminalBody = false;
                terminalTouchStartedInTypingBand = false;
                cancelHistoryMomentum("multi-touch");
                clearPendingHistoryScroll();
                clearCaptureRendererTouchNudge("multi-touch");
                cancelViewerTypingPositionRetries("multi-touch");
                cancelLiveInputVisibilityRetries("multi-touch");
            }
            terminalMultiTouchGesture = true;
            terminalHistoryDragActive = false;
            allowViewerPanBriefly();
            return forwardTouchToViewer(event);
        }
        if (action != MotionEvent.ACTION_DOWN && action != MotionEvent.ACTION_MOVE) {
            pinTerminalViewportLocal();
        }

        if (action == MotionEvent.ACTION_DOWN) {
            cancelCaptureRendererPointerForwarding(
                    event,
                    "superseded-by-new-down"
            );
            boolean startedInsidePassiveSuppression = passiveNavigationTapSuppressed;
            if (passiveNavigationTapSuppressed) {
                // WHY: passive tab/open suppression is for orphan releases from a disappearing picker,
                // not for the user's next real tap. Once a new
                // terminal ACTION_DOWN starts, let ACTION_UP open the native composer
                // promptly; otherwise repeated switch-settle calls can make typing
                // feel blocked for many seconds.
                terminalBodyTapSuppressedUntilMs = 0;
                passiveNavigationTapSuppressed = false;
            }
            if (!passiveNavigationTapSuppressed) {
                cancelXtermBlankTailMask("terminal-touch");
                cancelPassiveLiveBottomCallbacksForReadScroll("terminal-touch-down");
            }
            resetTerminalVelocityTracker(event);
            terminalTouchStartX = event.getX();
            terminalTouchStartY = event.getY();
            terminalLastHistoryDragY = terminalTouchStartY;
            terminalLastTouchVisualNudgeY = terminalTouchStartY;
            terminalLastViewerPanX = terminalTouchStartX;
            terminalLastHistoryDragEventAtMs = event.getEventTime();
            terminalTouchDownWallClockMs = System.currentTimeMillis();
            terminalHistoryDragActive = false;
            terminalMultiTouchGesture = false;
            terminalTouchExceededTapSlop = false;
            terminalTouchLoggedSubSlopMove = false;
            terminalHorizontalPanActive = false;
            terminalBottomRestoreInFlight = false;
            terminalForwardingTouchToViewer = false;
            terminalTouchStartedDuringPassiveSuppression = startedInsidePassiveSuppression;
            terminalTouchStartedInTerminalBody = isTerminalBodyScrollGestureTarget(event);
            terminalTouchStartedInTypingBand =
                    terminalTouchStartedInTerminalBody
                            && isTerminalTypingTapTarget(event);
            recycleTerminalViewerDownEvent();
            terminalViewerDownEvent = MotionEvent.obtain(event);
            // WHY(ROOT-B symmetric): a transcript TUI (histSize==0) leaves both read-mode
            // flags false even while scrolled up (enterReadMode bails at historySize<=0), so a
            // new gesture saw startedInHistory=false -> terminalTouchReachedLiveBottom inits true
            // below -> applyNativeHistoryScrollPixels refuses lineDown -> the user CANNOT scroll
            // down to the bottom (the "have to tap near the bottom" glitch). Treat a scrolled-up
            // local viewport as started-in-history: inits reachedLiveBottom=false (down allowed)
            // AND rebinds the held nudge below instead of wiping it.
            boolean startedInHistoryViewport = terminalHistoryViewportActive
                    || readModeSuppressesKeyboard
                    || localHistoryTouchViewportScrolledUpForReadHold()
                    // WHY(ROOT-C): a locked live-TUI is a held read — a tap must route to
                    // restoreLiveForTyping (return-to-live) which clears the lock via leaveReadModeForLiveInput.
                    || liveTuiScrollLockActive()
                    // WHY(v260 second-DOWN transfer): v260 correctly leaves the
                    // renderer's released offset held after native stale-read
                    // cleanup. Those native/local flags are therefore allowed to
                    // be false here. Transfer only the exact same-window,
                    // action-fenced renderer release token into v243's existing
                    // non-destructive rebind branch; never infer ownership from
                    // the Java transport residual, which release deliberately
                    // resets before the next physical DOWN.
                    || captureRendererReleasedReadHoldTargetsVisibleSurface();
            boolean continuesReleasedReadHold =
                    captureRendererReleasedReadHoldTargetsVisibleSurface();
            // WHY: when a drag starts from the live terminal, the first physical
            // lineDown sample is already at the bottom edge. Waiting for
            // `/touch-scroll` to report atLiveBottom lets the visual nudge expose
            // black space and then snap back, which is the bottom-stuck/up-jump
            // regression. If the drag starts from an existing history/reader
            // viewport, do not clamp lineDown; that path still owns returning
            // toward live bottom.
            terminalTouchReachedLiveBottom = !startedInHistoryViewport;
            terminalTouchSawUpwardHistoryIntent = false;
            // WHY(v283 single direction owner): a released hold transfers only
            // its exact visible anchor. It must never transfer the retired
            // live-bottom upward/pointer sign convention into a new gesture.
            terminalTouchPhysicalUpwardHistoryGesture = false;
            terminalTouchContinuesReleasedReadHold = continuesReleasedReadHold;
            terminalTouchContinuesReleasedReadHoldPhysicalUpwardHistoryGesture = false;
            terminalTouchReachedHistoryTop = false;
            terminalTouchStartedInHistoryViewport = startedInHistoryViewport;
            terminalTouchStableWindowId = touchScrollTargetKey();
            // WHY: APK-SCROLL-ONE-FINGER-DELAY-BOUNDARY-1537-A kept returning
            // after source/build fixes because logs could not prove whether the
            // visible movement happened before `/touch-scroll` or `/scrollback/chunk`
            // responses. Keep one safe action id from ACTION_DOWN through local
            // feedback, cache prefetch, backend request, visual commit, and release.
            activeTouchScrollActionId = newTouchScrollActionId();
            activeTouchScrollDownAtMs = SystemClock.elapsedRealtime();
            beginApkAction(
                    "one-finger-scroll",
                    terminalTouchStableWindowId,
                    activeTouchScrollActionId,
                    activeTouchScrollDownAtMs
            );
            activeTouchScrollFirstLocalFeedbackAtMs = 0;
            activeTouchScrollFirstLocalFeedbackKind = "";
            activeTouchScrollVisibleDistinctRowDisplacement = 0;
            activeTouchScrollFirstInlineLocalHistoryAtMs = 0;
            activeTouchScrollLocalHistoryBoundaryMergedAtMs = 0;
            activeTouchScrollLocalHistoryBoundaryActionId = "";
            activeTouchScrollLocalHistoryBoundaryRows = 0;
            resetLocalHistoryTouchAcceptedPaintTrack();
            boolean inheritedRendererSeamBlock =
                    captureRendererHistoryMovementBlocked;
            clearCaptureRendererBlockedFingerDelta("touch-start");
            clearNativeReadHoldForTouchScrollActionDown("touch-scroll-down");
            if (startedInHistoryViewport) {
                if (terminalTouchContinuesReleasedReadHold) {
                    consumeCaptureRendererReleasedReadHold(
                            "touch-start-history");
                }
                // WHY: [v243 second-DOWN snapback root] the renderer's OWN release
                // contract latches the held reading position (releaseTouchScrollNudge:
                // touchScrollNudgeHeldAfterRelease, "must stay latched until a new
                // touch, Bottom, live input, or session switch clears it") and its
                // clearTouchScrollNudge() does nudgePx=0 + applyScreenTransform() +
                // drainQueuedRefreshDemand() — i.e. it collapses the held offset to the
                // bottom-anchored baseline and drains the queued live refresh. Calling
                // it from a DOWN that CONTINUES a held history read is exactly the
                // installed "scroll up, hold, press again -> snaps back down" red
                // (first press from live bottom has no latch, so it never snapped).
                // Rebind the new gesture WITHOUT wiping the renderer's held nudge; the
                // new gesture's O(1) nudges continue from the held offset. Bottom,
                // live-input, session-switch, multi-touch, and pan clears are
                // untouched, so explicit returns to live bottom still fully clear.
                rebindCaptureRendererTouchNudgeForHeldHistoryStart("touch-start-history");
            } else {
                clearCaptureRendererTouchNudge("touch-start");
            }
            // WHY: v235 proved the Java snapshot cache can be absent while the
            // user is already looking at a valid renderer buffer: every real MOVE
            // then returned GESTURE_VIEWPORT_OWNER_MISSING. ACTION_DOWN now binds
            // that visible active buffer directly and commits only renderer-owned
            // READY seams in the same queued transaction, before any MOVE script.
            // No network response, stale Java generation, or duplicate stage result
            // is allowed to create or advance this gesture owner.
            boolean queuedGestureViewportOwner = beginCaptureRendererGestureViewportOwner();
            captureRendererGestureViewportOwnerQueued = queuedGestureViewportOwner;
            captureRendererGestureViewportOwnerActionId =
                    queuedGestureViewportOwner ? activeTouchScrollActionId : "";
            captureRendererGestureViewportOwnerWindowId =
                    queuedGestureViewportOwner ? terminalTouchStableWindowId : "";
            captureRendererGestureViewportOwnerLeaseSerial =
                    queuedGestureViewportOwner
                            ? captureRendererGestureViewportOwnerSerial
                            : 0;
            captureRendererGestureViewportRefillRequested = false;
            if (queuedGestureViewportOwner) {
                captureRendererHistoryMovementBlocked = false;
            } else if (inheritedRendererSeamBlock
                    && hasStableWindowId(terminalTouchStableWindowId)) {
                prewarmLocalHistoryForWindow(
                        terminalTouchStableWindowId,
                        "touch-start-owner-rebuild");
            }
            logTerminalTouchStage(
                    "down",
                    event,
                    "startedInHistory=" + startedInHistoryViewport
                            + " reachedLiveBottom=" + terminalTouchReachedLiveBottom
                            + " terminalBody=" + terminalTouchStartedInTerminalBody
                            + " readMode=" + readModeSuppressesKeyboard
            );
            // WHY: ACTION_DOWN must not commit a scroll visual-state frame before
            // the APK has a local pixel owner. The failed installed proof showed
            // `touch-scroll-down` completing with firstLocalFeedbackElapsedMs=-1,
            // then the first real cache paint snapped to the transition boundary.
            // Keep the request here as a scheduler nudge, but
            // requestCaptureRendererTouchVisualFrame defers it until MOVE feedback
            // has marked a capture/local-history owner.
            requestCaptureRendererTouchVisualFrame("touch-scroll-down");
            // WHY: touch-scroll HTTP responses can arrive after the finger has
            // already changed direction, released, or started a new gesture. Tagging
            // every request with this generation keeps stale server replies from
            // triggering the bottom restore/refresh jump on a later gesture.
            terminalTouchGestureGeneration++;
            terminalHistoryDragWhere = "";
            deferredHistoryScrollWhere = "";
            deferredHistoryScrollRepeats = 0;
            terminalHistoryDragDirectionGeneration++;
            scheduleTerminalLongPressCopy(event);
            cancelHistoryMomentum("new-down");
            clearPendingHistoryScroll();
            clearPostReleaseTouchScrollCommit();
            lastHistoryDragAtMs = 0;
            // WHY: v1.30 fixed tap-to-type by refocusing xterm on live taps,
            // but doing it on ACTION_DOWN races with a user's horizontal pan.
            // Samsung's keyboard/WebView focus can then snap the terminal back
            // left while the finger is trying to read a long line. Only refocus
            // after ACTION_UP proves this was a tap, not a pan or history drag.
            // WHY: when the terminal is in history/reader mode, a plain tap means
            // "return me to live input." If this ACTION_DOWN is allowed through to
            // WebView, xterm can open Samsung's keyboard before the server has
            // scrolled tmux/Codex back to the live bottom, recreating the bug where
            // the keyboard covers the composer and the user cannot see typing.
            // WHY: one-finger vertical history must be owned by WEzterm/tmux from
            // ACTION_DOWN. Letting WebView receive DOWN and then stealing MOVE for
            // `/touch-scroll` starts native document scroll, which the viewport pin
            // fights with `scrollTo(0,0)`, producing the repeated up/down refresh
            // loop. Taps, one-finger horizontal pan, and two-finger zoom are
            // forwarded back to WebView only after they are classified.
            return true;
        }

        if (action == MotionEvent.ACTION_MOVE) {
            addTerminalMovement(event);
            if (terminalMultiTouchGesture) {
                return forwardTouchToViewer(event);
            }
            if (terminalHorizontalPanActive) {
                panZoomedViewerHorizontally(event);
                return forwardTouchToViewer(event);
            }
            float dx = event.getX() - terminalTouchStartX;
            float dy = event.getY() - terminalTouchStartY;
            float absDx = Math.abs(dx);
            float absDy = Math.abs(dy);
            boolean verticalReadingIntent = terminalTouchStartedInTerminalBody
                    && isTerminalVerticalHistoryIntent(absDx, absDy);
            boolean preserveLongPressCopyWindow = shouldPreserveTerminalLongPressCopyWindow(absDx, absDy);
            if (!terminalTouchExceededTapSlop
                    && !preserveLongPressCopyWindow
                    && (absDx >= dp(HISTORY_DRAG_LONG_PRESS_CANCEL_DP)
                    || absDy >= dp(HISTORY_DRAG_LONG_PRESS_CANCEL_DP))) {
                // WHY: after the Android long-press tolerance window is no longer
                // plausible, a very slow reading drag can still move less than the
                // platform touch slop for longer than the hold timeout. That is a
                // moving finger, not a stationary copy gesture; otherwise the text
                // selection sheet opens before the scroll owner can engage.
                cancelPendingTerminalLongPressCopy("move-intent-before-slop");
            }
            if (absDx > terminalTouchSlop || absDy > terminalTouchSlop) {
                terminalTouchExceededTapSlop = true;
                cancelPendingTerminalLongPressCopy("move-past-slop");
            }
            if (!terminalHistoryDragActive && shouldHandOffToViewerHorizontalPan(absDx, absDy)) {
                // WHY: one-finger horizontal movement is the user's line-reading
                // pan inside ttyd/WebView. The app must not treat it as a live
                // tap or a server history gesture, or xterm focus will recenter
                // the viewport and recreate the "snaps back left" bug. Hand off
                // as soon as horizontal intent is clear; waiting for a large dx
                // swallows the first part of the native pan and kills momentum.
                terminalHorizontalPanActive = true;
                terminalLastViewerPanX = terminalTouchStartX;
                allowViewerPanBriefly();
                cancelPendingTerminalLongPressCopy("horizontal-pan");
                cancelViewerTypingPositionRetries("horizontal-pan");
                cancelLiveInputVisibilityRetries("horizontal-pan");
                clearCaptureRendererTouchNudge("horizontal-pan");
                panZoomedViewerHorizontally(event);
                return forwardTouchToViewer(event);
            }
            if (!terminalHistoryDragActive) {
                if (!terminalTouchStartedInTerminalBody) {
                    return true;
                }
                if ((absDy < terminalTouchSlop || absDy < absDx * 1.2f)
                        && !verticalReadingIntent) {
                    if (!terminalTouchLoggedSubSlopMove
                            && (absDx >= dp(HISTORY_DRAG_LONG_PRESS_CANCEL_DP)
                            || absDy >= dp(HISTORY_DRAG_LONG_PRESS_CANCEL_DP))) {
                        terminalTouchLoggedSubSlopMove = true;
                        logTerminalTouchStage(
                                "move-subslop",
                                event,
                                "dx=" + touchLogFloat(dx)
                                        + " dy=" + touchLogFloat(dy)
                                        + " slop=" + terminalTouchSlop
                                        + " copyHoldPreserved=" + preserveLongPressCopyWindow
                        );
                    }
                    return true;
                }
                // WHY: once a one-finger gesture is clearly vertical, WEzterm
                // must take ownership immediately. Letting WebView/xterm handle
                // the early part of a vertical swipe is what made old tabs page
                // scroll below the terminal text area before the tmux/Codex
                // history layer could take over.
                // WHY: the current phone contract is stricter than Android's
                // normal tap slop after copy-hold is no longer plausible: if the
                // user moves vertically by the small "reading intent" threshold,
                // they are trying to hold/read, not open the composer. Starting
                // history ownership here lets the renderer keep the exact sub-line
                // residual at finger-up instead of snapping or treating the tiny
                // drag as a tap.
                // WHY: FREEZE FIX #29(b) — a pane with zero tmux scrollback
                // (alt-screen TUI, e.g. Claude @6, historySize==0) has NOTHING to
                // scroll back through. Taking history ownership there latched
                // read-hold — the round-trip can never report "reached bottom", so the
                // native read-hold stuck and suppressed the live stream every ~2s =
                // the permanent "bottom freezes when I scroll" bug. Mirror the
                // enterReadMode precondition at the touch entry: on a KNOWN
                // zero-scrollback pane do NOT take history ownership — consume the
                // swipe and stay live so the stream never freezes and return-to-bottom
                // is unnecessary. Use ==0 (known zero) not <=0 so a not-yet-measured
                // (-1) pane is unaffected (no regression on normal panes). The broken
                // historySize>0 alt-screen proxy case (e.g. @42 hist=7) is left to the
                // local-buffer paint, not this guard.
                // WHY: SCROLL DEEP-HISTORY 2026-07-26 — EXCEPTION: a claude pane whose
                // live historySize is 0 but which carries transcriptScrollbackAvailable=true
                // DOES have deep re-anchored scrollback served via /scrollback/chunk
                // (e.g. @6 = 44k transcript rows). Take local-history ownership so it
                // routes to the local-buffer staged-nudge scroll (which paints/pages the
                // transcript) instead of the wheel-forward /touch-scroll that can never
                // move the alt-screen TUI. Non-transcript zero-scrollback panes still
                // bail here (no ownership, no read-hold freeze).
                if (lastAcceptedCaptureRendererHistorySize == 0 && !lastFrameTranscriptScrollbackAvailable) {
                    // WHY(ROOT-C live-TUI scroll-lock): #29(b) still holds — do NOT take history
                    // ownership here (the copy-mode round-trip never reports a detectable bottom, which
                    // latched the invisible-wall freeze). But bailing to a pure no-op let the
                    // idle-realtime-tick snap a deliberate scroll-up back to bottom every ~2s: this pane
                    // has NO server scroll position and NO ROOT-B offset, so every hold predicate reads
                    // it as "at live bottom" (and v256's stale-latch release would nuke the read-mode
                    // flags within one tick). On a DELIBERATE older-history drag engage a light window-scoped lock
                    // (no ownership/round-trip) so nativeReadHold()+tuiReadHold() both read true and the
                    // JS commit gate suppresses the live heartbeat until return-to-live. Toward-live drag clears
                    // here; tap/Send/Bottom clear via leaveReadModeForLiveInput; pane switch is
                    // neutralized by window scoping. Never walls like #29(b): sets only on a deliberate
                    // older-history drag, never at bottom / on a tap, and releases on the very next return-to-live.
                    float tuiScrollLockThreshold = Math.max(0.5f, dp(HISTORY_DRAG_LONG_PRESS_CANCEL_DP));
                    if (dy >= tuiScrollLockThreshold && hasStableWindowId(terminalTouchStableWindowId)) {
                        if (!liveTuiScrollLockActive
                                || !terminalTouchStableWindowId.equals(liveTuiScrollLockWindowId)) {
                            liveTuiScrollLockActive = true;
                            liveTuiScrollLockWindowId = terminalTouchStableWindowId;
                            syncCaptureRendererReadHold("live-tui-scroll-lock-engage");
                            Log.i(CONTROL_LOG_TAG,
                                    "stage=live-tui-scroll-lock endpoint=idle-realtime-tick result=engaged"
                                            + " windowId=" + safeWindowIdForControlLog(terminalTouchStableWindowId)
                                            + " dy=" + touchLogFloat(dy));
                        }
                    } else if (dy <= -tuiScrollLockThreshold) {
                        clearLiveTuiScrollLock("toward-live-return");
                    }
                    return true;
                }
                if (terminalTouchStartedDuringPassiveSuppression) {
                    hideDockedPromptComposerForNavigation("passive-nav-scroll-start");
                }
                suppressCopyPasteControlsForTerminalScroll("history-drag-start");
                cancelPendingTerminalLongPressCopy("history-drag-start");
                cancelPassiveLiveBottomCallbacksForReadScroll("history-drag-start");
                terminalTouchExceededTapSlop = true;
                terminalHistoryDragActive = true;
                // WHY: SCROLL DEEP-HISTORY 2026-07-26 — a new scroll gesture starts with a
                // full proactive look-ahead budget so its first fast fling stages deep
                // ahead of momentum instead of underrunning on the first frame.
                deepStagingLookAheadChunkCount = 0;
                // WHY(v283 rare inversion root): v270-v282 selected a second
                // renderer-pointer sign only for an upward gesture at live
                // bottom. The identical next gesture used this normal Java
                // owner, so direction and latency depended on prior state.
                // Keep every one-finger drag on the already accepted natural
                // mapping: finger down reads older; finger up returns liveward.
                terminalTouchPhysicalUpwardHistoryGesture = false;
                terminalLastHistoryDragY = terminalTouchStartY;
                terminalLastTouchVisualNudgeY = terminalLastHistoryDragY;
                logTerminalTouchStage(
                        "history-start",
                        event,
                        "dx=" + touchLogFloat(dx)
                                + " dy=" + touchLogFloat(dy)
                                + " slop=" + terminalTouchSlop
                                + " startedInHistory=" + terminalTouchStartedInHistoryViewport
                                + " reachedLiveBottom=" + terminalTouchReachedLiveBottom
                );
                enterReadMode();
                // WHY(ROOT-C v258 transcript/no-hist safety net): on a transcriptScrollbackAvailable or
                // histSize==0 pane enterReadMode() bailed (histSize<=0 -> no read-mode flags) and the
                // out-of-band /scrollback/chunk rows may never paint (firstLocalFeedback=-1), so neither
                // the read-mode flags nor ROOT-B engage and the idle/dom-apply/inset commits snap the
                // scrolled-up view to bottom (device @42). Engage the same window-scoped scroll-lock as
                // the #29(b) site, but for this transcript/no-scrollback class, on exactly this
                // deliberate older-history drag. Additive to any genuine hold that does engage; released on
                // the same return-to-live paths (tap/Send/Bottom/down-return/switch).
                if ((lastFrameTranscriptScrollbackAvailable
                        || lastAcceptedCaptureRendererHistorySize == 0)
                        && dy >= Math.max(0.5f, dp(HISTORY_DRAG_LONG_PRESS_CANCEL_DP))
                        && hasStableWindowId(terminalTouchStableWindowId)
                        && (!liveTuiScrollLockActive
                                || !terminalTouchStableWindowId.equals(liveTuiScrollLockWindowId))) {
                    liveTuiScrollLockActive = true;
                    liveTuiScrollLockWindowId = terminalTouchStableWindowId;
                    syncCaptureRendererReadHold("live-tui-scroll-lock-engage-transcript");
                    Log.i(CONTROL_LOG_TAG,
                            "stage=live-tui-scroll-lock endpoint=transcript-scrollback result=engaged"
                                    + " windowId=" + safeWindowIdForControlLog(terminalTouchStableWindowId)
                                    + " transcript=" + lastFrameTranscriptScrollbackAvailable
                                    + " histSize=" + lastAcceptedCaptureRendererHistorySize);
                }
                keepCaptureRendererPulsingDuringTouch("touch-scroll-start");
                // WHY(ROOT-A): keep the JS gesture-active latch continuously fresh for the
                // whole physical hold, not just 600ms after the last per-row MOVE sync.
                startGestureScrollHoldHeartbeat("touch-scroll-start");
            }

            // WHY(v283 single visual owner): do not forward this MOVE into the
            // renderer pointer path. processHistoryDragEventSamples owns both
            // the semantic direction and the one frame-paced visual nudge.
            processHistoryDragEventSamples(event);
            return true;
        }

        if (action == MotionEvent.ACTION_UP || action == MotionEvent.ACTION_CANCEL) {
            boolean consumed = terminalHistoryDragActive;
            boolean startedInHistoryViewport = terminalTouchStartedInHistoryViewport;
            boolean wasMultiTouch = terminalMultiTouchGesture;
            boolean wasHorizontalPan = terminalHorizontalPanActive;
            boolean movedPastTapSlop = terminalTouchExceededTapSlop;
            boolean reachedLiveBottom = terminalTouchReachedLiveBottom;
            boolean sawUpwardHistoryIntent = terminalTouchSawUpwardHistoryIntent;
            boolean continuedReleasedReadHold =
                    terminalTouchContinuesReleasedReadHold;
            boolean startedInTypingBand =
                    terminalTouchStartedInTypingBand;
            boolean preserveReleasedReadHoldOnNoDrag =
                    continuedReleasedReadHold && !startedInTypingBand;
            boolean wasForwardingTouchToViewer = terminalForwardingTouchToViewer;
            boolean startedDuringPassiveSuppression = terminalTouchStartedDuringPassiveSuppression;
            boolean longPressCopied = terminalLongPressCopyConsumed;
            if (action == MotionEvent.ACTION_CANCEL) {
                cancelCaptureRendererPointerForwarding(
                        event,
                        "gesture-cancel"
                );
                endTerminalSnapshotLease(
                        "gesture-cancel",
                        TerminalSnapshotEndMode.ABORT
                );
            }
            boolean releaseWithoutVisibleOwner = action == MotionEvent.ACTION_UP
                    && consumed
                    && activeTouchScrollFirstLocalFeedbackAtMs <= 0
                    && !activeTouchScrollHasExactLocalHistoryPaint()
                    && !activeCaptureRendererGestureViewportOwner();
            boolean releaseFlingStarted = false;
            if (action == MotionEvent.ACTION_UP && terminalHistoryDragActive) {
                lastHistoryDragReleaseAtMs = System.currentTimeMillis();
                clearPendingHistoryScroll();
                rememberPostReleaseTouchScrollCommitIfNeeded();
                releaseFlingStarted = dispatchHistoryReleaseFling(event);
                flushDeferredHistoryScrollOnRelease(releaseFlingStarted);
                finishCaptureRendererPointerForwarding(
                        event,
                        releaseFlingStarted
                );
                if (!releaseFlingStarted) {
                    // WHY: APK-SCROLL-POST-RELEASE-SNAP-2346 proved that a
                    // slow reading drag must stop at ACTION_UP. Do not let a
                    // stale in-flight `/touch-scroll` response drain one more row
                    // or trigger a bottom/top-edge refresh after the finger lifts;
                    // that is the user-visible random release jump.
                    // APK-SCROLL-DELTA-BLACKGAP-1831 re-accepts release inertia only through
                    // `dispatchHistoryReleaseFling`: slow reading drags still hard-stop at ACTION_UP,
                    // while quick high-velocity flicks may start bounded release momentum
                    // on the same stable target.
                    cancelHistoryMomentum("release-no-fling");
                    terminalTouchGestureGeneration++;
                }
                keepCaptureRendererPulsingDuringTouch("touch-scroll-release");
                if (releaseFlingStarted) {
                    deferCaptureRendererTouchNudgeReleaseForMomentum(
                            "touch-scroll-release");
                } else {
                    releaseCaptureRendererTouchNudge("touch-scroll-release");
                }
            }
            if ((action == MotionEvent.ACTION_UP || action == MotionEvent.ACTION_CANCEL)
                    && !consumed
                    && captureRendererGestureViewportOwnerLeaseSerial > 0) {
                // WHY: [gesture-viewport-owner leak] the lease is acquired on EVERY
                // terminal-body ACTION_DOWN (beginCaptureRendererGestureViewportOwner)
                // but released only inside the drag-active UP branch above. A tap /
                // sub-slop / live-bottom UP (movedPastTapSlop=false) never enters that
                // branch, so the lease + native-read-hold + deep-history prewarm leaked
                // and kept /active + 451KB /scrollback/chunk running >30s (device trace
                // scroll-3608618-33: ACQUIRED serials 1-37, zero RELEASED). Release the
                // lease exactly once here for the non-drag gesture end so its lifetime
                // matches the finger; CANCEL/multitouch/pan already clear it below.
                if (action == MotionEvent.ACTION_UP
                        && preserveReleasedReadHoldOnNoDrag
                        && captureRendererReleasedReadHoldTargetsVisibleSurface()) {
                    // WHY(v263/v270): a second no-drag contact outside the
                    // composer's explicit bottom strip is still a reading hold.
                    // Drop only the new gesture lease; the exact transferred
                    // renderer token remains the visible authority.
                    rebindCaptureRendererTouchNudgeForHeldHistoryStart(
                            "gesture-end-nondrag-hold");
                    Log.i(CONTROL_LOG_TAG,
                            "stage=touch-nudge-release endpoint=renderer"
                                    + " result=held-history-nondrag-preserved"
                                    + " actionId="
                                    + safeLogToken(activeTouchScrollActionId));
                } else {
                    clearCaptureRendererTouchNudge("gesture-end-nondrag-release");
                }
            }
            logTerminalTouchStage(
                    action == MotionEvent.ACTION_CANCEL ? "cancel" : "up",
                    event,
                    "consumed=" + consumed
                            + " movedPastTapSlop=" + movedPastTapSlop
                            + " reachedLiveBottom=" + reachedLiveBottom
                            + " releaseFlingStarted=" + releaseFlingStarted
                            + " historyWhere=" + safeLogToken(terminalHistoryDragWhere)
            );
            boolean shouldRestoreTyping = action == MotionEvent.ACTION_UP
                    && startedInHistoryViewport
                    && !terminalHistoryDragActive
                    && !wasMultiTouch
                    && !wasHorizontalPan
                    && !movedPastTapSlop
                    && (!continuedReleasedReadHold || startedInTypingBand);
            terminalHistoryDragActive = false;
            terminalMultiTouchGesture = false;
            terminalTouchExceededTapSlop = false;
            terminalHorizontalPanActive = false;
            terminalTouchReachedLiveBottom = false;
            terminalTouchSawUpwardHistoryIntent = false;
            terminalTouchPhysicalUpwardHistoryGesture = false;
            terminalTouchContinuesReleasedReadHold = false;
            terminalTouchContinuesReleasedReadHoldPhysicalUpwardHistoryGesture = false;
            terminalTouchReachedHistoryTop = false;
            terminalTouchStartedInHistoryViewport = false;
            terminalTouchStartedDuringPassiveSuppression = false;
            terminalTouchStartedInTerminalBody = false;
            terminalTouchStartedInTypingBand = false;
            clearTerminalLongPressCopyState();
            if (wasMultiTouch || wasHorizontalPan) {
                allowViewerPanBriefly();
                clearCaptureRendererTouchNudge("viewer-owned-release");
            } else if (action == MotionEvent.ACTION_CANCEL) {
                clearCaptureRendererTouchNudgeSoon("touch-end");
            }
            if (wasMultiTouch) {
                flushDeferredCaptureRendererScaleSync("multi-touch-release");
            }
            recycleTerminalVelocityTracker();
            if (wasForwardingTouchToViewer) {
                forwardTouchToViewer(event);
                recycleTerminalViewerDownEvent();
                return true;
            }
            if (longPressCopied) {
                recycleTerminalViewerDownEvent();
                return true;
            }
            if (releaseWithoutVisibleOwner) {
                releaseReadHoldAfterNoVisibleScrollOwner("touch-scroll-release");
                recycleTerminalViewerDownEvent();
                return true;
            }
            if (shouldRestoreTyping) {
                if (!startedInTypingBand && shouldKeepReadModeAfterRecentHistoryDragTap()) {
                    // WHY: after a real one-finger scroll, the user's next tiny
                    // contact is often a continuation/reading hold, not a request to
                    // type. The old read-mode tap shortcut immediately fired
                    // `/live-bottom`, so a slight no-slop touch after release snapped
                    // the viewport back to the bottom. Keep live cursor taps
                    // unchanged; only suppress this history-mode shortcut briefly
                    // after a consumed scroll release. The composer-height bottom
                    // strip is explicit typing intent and bypasses this ambiguity.
                    Log.i(CONTROL_LOG_TAG,
                            "stage=history-read-tap action=hold-read-mode result=recent-scroll-release");
                    keepReadModeIfCurrent(terminalModeGeneration);
                    recycleTerminalViewerDownEvent();
                    return true;
                }
                // WHY: the composer itself is the success signal. A tap-to-type
                // success Toast sits over the same bottom area the user is trying to
                // inspect, recreating the v2.57 popup-over-prompt regression while
                // the keyboard/composer is opening.
                restoreLiveForTyping("");
                recycleTerminalViewerDownEvent();
                return true;
            }
            if (startedDuringPassiveSuppression
                    && System.currentTimeMillis() < terminalBodyTapSuppressedUntilMs
                    && action == MotionEvent.ACTION_UP
                    && !consumed
                    && !wasMultiTouch
                    && !wasHorizontalPan
                    && !movedPastTapSlop) {
                // WHY: this is the protected passive-navigation tap swallow for
                // stale timed releases only. A fresh ACTION_DOWN now clears the
                // timeout so deliberate tap-to-type opens the native composer; a
                // simple tap right after a tab switch/Bottom should do nothing only
                // when it is that stale release without a fresh terminal down event;
                // a vertical drag from the same window already bypassed this and became
                // tmux history scroll above.
                recycleTerminalViewerDownEvent();
                return true;
            }
            // WHY(ROOT-B symmetric release): on a transcript TUI the local viewport offset is the
            // only bottom truth (the server's atLiveBottom arrives async, after this synchronous
            // release branch). If a downward drag left the viewport at its newest cached row
            // (offset>=maxOffset), the user has returned to the live tail: clear the hold and
            // restore live-follow with the SAME quiet path the near-bottom tap uses, so no tap is
            // needed. offset>=maxOffset cannot fire while genuinely scrolled up, and is scoped to
            // histSize==0 so histSize>0 release behavior is byte-identical.
            boolean tuiReturnedToLiveTail = action == MotionEvent.ACTION_UP
                    && consumed
                    && !wasMultiTouch
                    && !wasHorizontalPan
                    && lastAcceptedCaptureRendererHistorySize == 0
                    && localHistoryTouchViewportTargetsVisibleSurface()
                    && localHistoryTouchViewportMaxOffset() > 0
                    && localHistoryTouchViewportOffset >= localHistoryTouchViewportMaxOffset();
            if (tuiReturnedToLiveTail) {
                restoreTouchLiveBottomQuietly();
                recycleTerminalViewerDownEvent();
                return true;
            }
            boolean shouldRestoreLiveBottomAfterDrag = action == MotionEvent.ACTION_UP
                    && reachedLiveBottom
                    && consumed
                    && !sawUpwardHistoryIntent;
            if (shouldRestoreLiveBottomAfterDrag) {
                // WHY: the finger has reached tmux scroll position 0, but tmux is
                // still in copy-mode unless Android explicitly exits it. v1.56
                // avoided the old refresh loop by doing nothing here, but that left
                // the phone stranded at a `[0/N]` history footer instead of the live
                // composer. Use the lightweight tmux-only touch endpoint to cancel
                // copy-mode, and deliberately skip WebView reload, xterm
                // scrollToBottom, scrollIntoView, and IME focus helpers that caused
                // the repeated page-refresh/snap regression. Do not run this for a
                // no-drag live tap: the v2.96 live-bottom edge clamp also sets
                // `reachedLiveBottom`, and a plain cursor-area tap must still open
                // the native composer.
                // APK-ONE-FINGER-SNAP-BACK-BOTTOM-1506-T: an upward reading drag
                // that starts at live bottom can be sub-row before `/touch-scroll`
                // dispatches lineUp. That is still user intent to hold history, not
                // a downward return gesture; the guarded flag above prevents this
                // quiet bottom restore from forcing the view back to the prompt.
                restoreTouchLiveBottomQuietly();
                recycleTerminalViewerDownEvent();
                return true;
            }
            if (action == MotionEvent.ACTION_UP
                    && !startedInHistoryViewport
                    && !consumed
                    && !wasMultiTouch
                    && !wasHorizontalPan
                    && !movedPastTapSlop) {
                if (isTopTerminalTap(event)) {
                    // WHY: the tmux status/tab strip still needs the original
                    // browser tap stream so the user can use the top tab targets
                    // when zoomed in. Do not also request Android IME focus here:
                    // top-strip taps are navigation, not typing, and a second
                    // delayed editor focus can recommit Samsung/Gboard composition.
                    forwardTapToViewer(event);
                } else {
                    // WHY: terminal body taps open the native composer instead of
                    // focusing xterm's hidden textarea. Android Chrome/WebView plus
                    // xterm.js has a known mobile composition failure mode where the
                    // same composed word can be committed twice. WEzTerm's phone UI
                    // gives long-form typing to a native EditText composer and submits
                    // the finished prompt through the control server's single
                    // paste+Enter path. The top tmux/status strip still receives
                    // WebView taps.
                    // WHY(v275 streaming read-hold): this raw body tap is definitive
                    // live-input intent. Clear the prior renderer/read owners before
                    // opening the composer so accepted live frames can commit again.
                    leaveReadModeForLiveInput(false, "composer-tap-up");
                    showDockedPromptComposer("tap-up");
                }
            }
            recycleTerminalViewerDownEvent();
            return true;
        }

        return false;
    }

    private boolean shouldHoldLocalHistoryTouchTopEdge(LocalHistoryRequest request, String where) {
        if (!"lineUp".equals(where)
                || !localHistoryTouchViewportTargetsRequest(request)
                || localHistoryTouchViewportRows.isEmpty()) {
            return false;
        }
        int maxOffset = localHistoryTouchViewportMaxOffset();
        if (maxOffset <= 0 || localHistoryTouchViewportOffset > 0) {
            return false;
        }
        return !localHistoryTouchViewportHasOlderBoundaryCandidate(request);
    }

    private boolean localHistoryTouchViewportHasOlderBoundaryCandidate(LocalHistoryRequest request) {
        LocalHistoryChunk base = findCachedLocalHistoryChunk(request, "");
        LocalHistoryChunk boundary = localHistoryAdjacentPrefetchSourceChunk(request, base);
        if (boundary == null || boundary.payload == null) {
            return false;
        }
        return !localHistoryPreviousStartFromPayload(boundary.payload).isEmpty();
    }

    private String localHistoryPreviousStartFromPayload(JSONObject payload) {
        if (payload == null) {
            return "";
        }
        Object prevStart = payload.opt("prevStart");
        if (prevStart == null || prevStart == JSONObject.NULL) {
            return "";
        }
        return normalizeLocalHistoryStart(String.valueOf(prevStart));
    }

    private void recordLocalHistoryTouchTopEdgeHold(
            LocalHistoryRequest request,
            String where,
            int repeats,
            long requestSerial,
            String source
    ) {
        localHistoryTouchTopEdgeHold = true;
        localHistoryTouchTopEdgeHoldWindowId = request == null ? "" : request.windowId;
        localHistoryTouchTopEdgeHoldGenerationKey = localHistoryTouchViewportGenerationKey;
        localHistoryTouchTopEdgeHoldRequestSerial = requestSerial;
        // WHY: APK-SCROLLBACK-DIRECTION-REVERSED-RIGHT-CLIP-20260709-2258 showed
        // cached one-finger history continuing to repaint lineUp at its local minimum
        // offset. `/scrollback/chunk` rows are oldest-to-newest, so offset zero is
        // the top and maxOffset is the live/current end. Hold the APK-local top edge until an older chunk extends the
        // cache or the user's lineDown reversal clears it; do not queue stale
        // same-direction paints that feel like a late invisible boundary.
        Log.i(CONTROL_LOG_TAG,
                "stage=local-history-viewport endpoint=local-cache result=local-cache-top-edge-hold"
                        + " actionId=" + safeLogToken(activeTouchScrollActionId)
                        + " tapId=" + safeLogToken(currentApkTapIdForLog())
                        + " windowId=" + safeWindowIdForControlLog(localHistoryTouchTopEdgeHoldWindowId)
                        + " generationKey=" + safeLogToken(localHistoryTouchTopEdgeHoldGenerationKey)
                        + " where=" + safeLogToken(where)
                        + " repeats=" + Math.max(1, repeats)
                        + " currentOffset=" + localHistoryTouchViewportOffset
                        + " maxOffset=" + localHistoryTouchViewportMaxOffset()
                        + " hasMoreBefore=" + localHistoryBoundaryHasMoreBeforeForRequest(request)
                        + " suppressPrefetch=true"
                        + " suppressInlinePaint=true"
                        + " source=" + safeLogToken(source)
                        + " request=" + requestSerial);
    }

    private void clearLocalHistoryTouchTopEdgeHold(
            LocalHistoryRequest request,
            String reason,
            long requestSerial
    ) {
        if (!localHistoryTouchTopEdgeHold) {
            return;
        }
        String windowId = request == null ? "" : request.windowId;
        if (hasStableWindowId(windowId)
                && hasStableWindowId(localHistoryTouchTopEdgeHoldWindowId)
                && !windowId.equals(localHistoryTouchTopEdgeHoldWindowId)) {
            return;
        }
        Log.i(CONTROL_LOG_TAG,
                "stage=local-history-viewport endpoint=local-cache result=local-cache-top-edge-hold-cleared"
                        + " actionId=" + safeLogToken(activeTouchScrollActionId)
                        + " tapId=" + safeLogToken(currentApkTapIdForLog())
                        + " windowId=" + safeWindowIdForControlLog(localHistoryTouchTopEdgeHoldWindowId)
                        + " reason=" + safeLogToken(reason)
                        + " request=" + requestSerial);
        localHistoryTouchTopEdgeHold = false;
        localHistoryTouchTopEdgeHoldWindowId = "";
        localHistoryTouchTopEdgeHoldGenerationKey = "";
        localHistoryTouchTopEdgeHoldRequestSerial = -1;
    }

    private boolean shouldKeepReadModeAfterRecentHistoryDragTap() {
        if (!terminalHistoryViewportActive || !readModeSuppressesKeyboard) {
            return false;
        }
        long elapsedMs = System.currentTimeMillis() - lastHistoryDragReleaseAtMs;
        return elapsedMs >= 0 && elapsedMs <= HISTORY_READ_TAP_RESTORE_DEBOUNCE_MS;
    }

    private void scheduleTerminalLongPressCopy(MotionEvent event) {
        cancelPendingTerminalLongPressCopy("new-down");
        terminalLongPressCopyConsumed = false;
        if (event == null || isTopTerminalTap(event) || !terminalTouchStartedInTerminalBody) {
            return;
        }
        terminalLongPressCopyArmed = true;
        long generation = ++terminalLongPressCopyGeneration;
        // WHY: making the WebView itself selectable fights the custom tmux
        // scroll/pinch/pan owner paths. Long-press uses /copy-visible as the
        // text source, then opens a native selectable sheet so Android handles
        // highlight/copy without changing terminal gesture ownership.
        uiHandler.postDelayed(() -> {
            if (!terminalLongPressCopyArmed
                    || generation != terminalLongPressCopyGeneration
                    || terminalHistoryDragActive
                    || terminalMultiTouchGesture
                    || terminalHorizontalPanActive
                    || terminalTouchExceededTapSlop) {
                return;
            }
            terminalLongPressCopyArmed = false;
            terminalLongPressCopyConsumed = true;
            View feedbackTarget = terminalFrame != null ? terminalFrame : webView;
            if (feedbackTarget != null) {
                feedbackTarget.performHapticFeedback(HapticFeedbackConstants.LONG_PRESS);
            }
            Log.i(TERMINAL_COPY_LOG_TAG, "terminal-long-press-select trigger");
            showSelectableTerminalTextSheet();
        }, TERMINAL_LONG_PRESS_COPY_MS);
    }

    private void cancelPendingTerminalLongPressCopy(String reason) {
        if (!terminalLongPressCopyArmed) {
            return;
        }
        terminalLongPressCopyArmed = false;
        terminalLongPressCopyGeneration++;
    }

    private void clearTerminalLongPressCopyState() {
        terminalLongPressCopyArmed = false;
        terminalLongPressCopyConsumed = false;
        terminalLongPressCopyGeneration++;
    }

    private boolean shouldPreserveTerminalLongPressCopyWindow(float absDx, float absDy) {
        if (!terminalLongPressCopyArmed || terminalTouchDownWallClockMs <= 0) {
            return false;
        }
        if (isTerminalVerticalHistoryIntent(absDx, absDy)) {
            // WHY: installed T5 reproduced the old invisible-boundary row by
            // landing the gesture on native Copy/Paste instead of terminal
            // history. A dominant one-finger vertical move is scroll ownership,
            // even before Android's platform slop is crossed; only a stationary
            // hold keeps the selectable-copy owner armed.
            return false;
        }
        long heldForMs = System.currentTimeMillis() - terminalTouchDownWallClockMs;
        if (heldForMs < 0 || heldForMs >= TERMINAL_LONG_PRESS_COPY_MS) {
            return false;
        }
        return Math.max(absDx, absDy) < terminalLongPressCopyCancelSlopPx();
    }

    private boolean isTerminalVerticalHistoryIntent(float absDx, float absDy) {
        return absDy >= dp(HISTORY_DRAG_LONG_PRESS_CANCEL_DP)
                && absDy >= absDx * 1.2f;
    }

    private float terminalLongPressCopyCancelSlopPx() {
        // WHY: Android long-press gestures are allowed to wander inside the
        // platform-scaled touch slop. Using the 2dp reading-drag threshold here
        // made normal finger jitter start history scroll before the selectable
        // terminal text sheet could open.
        return Math.max(terminalTouchSlop, dp(HISTORY_DRAG_LONG_PRESS_CANCEL_DP));
    }

    private boolean shouldHandOffToViewerHorizontalPan(float absDx, float absDy) {
        if (isViewerZoomed()) {
            // WHY: zoomed horizontal point-of-view pan has natural thumb drift.
            // The old normal-scale dominance check let a mostly-right drag become
            // ambiguous and then tmux-owned vertical history, which is exactly the
            // user-reported "cannot move my point of view to the right" failure.
            // Keep clear vertical drags tmux-owned, but hand off zoomed side-pan
            // before the WebView loses the native gesture stream.
            return absDx >= terminalTouchSlop
                    && absDx >= absDy * ZOOMED_HORIZONTAL_PAN_DRIFT_RATIO;
        }
        return absDx >= terminalTouchSlop * 1.25f
                && absDx > absDy * 1.05f;
    }

    private void panZoomedViewerHorizontally(MotionEvent event) {
        if (webView == null || event == null || event.getPointerCount() != 1 || !isViewerZoomed()) {
            return;
        }
        float x = event.getX();
        int deltaX = Math.round(terminalLastViewerPanX - x);
        terminalLastViewerPanX = x;
        if (deltaX == 0) {
            return;
        }
        // WHY: v2.75 proved that replaying the original DOWN into WebView was
        // necessary but not sufficient once WEzTerm had already consumed the
        // gesture start. Keep zoomed one-finger horizontal reading viewer-owned by
        // directly scrolling the WebView's horizontal viewport; do not reroute this
        // through tmux history, `/touch-scroll`, font resize, or zoom reset.
        allowViewerPanBriefly();
        webView.scrollBy(deltaX, 0);
    }

    private void resetTerminalVelocityTracker(MotionEvent event) {
        recycleTerminalVelocityTracker();
        terminalVelocityTracker = VelocityTracker.obtain();
        terminalVelocityTracker.addMovement(event);
    }

    private void addTerminalMovement(MotionEvent event) {
        if (terminalVelocityTracker != null) {
            terminalVelocityTracker.addMovement(event);
        }
    }

    private void logTerminalTouchStage(String action, MotionEvent event, String detail) {
        if (event == null) {
            return;
        }
        // WHY: repeated snap/jump fixes failed when we inferred the owner layer
        // from screenshots alone. These safe logs prove whether the real phone
        // path is still tap/sub-slop, has entered tmux-owned history scroll, or
        // is releasing a consumed drag before any scroll-behavior patch is made.
        Log.i(CONTROL_LOG_TAG,
                "stage=terminal-touch"
                        + " actionId=" + safeLogToken(activeTouchScrollActionId)
                        + " action=" + safeLogToken(action)
                        + " windowId=" + safeWindowIdForControlLog(terminalTouchStableWindowId)
                        + " x=" + touchLogFloat(event.getX())
                        + " y=" + touchLogFloat(event.getY())
                        + " tapDownAtMs=" + activeTouchScrollDownAtMs
                        + " firstLocalFeedbackAtMs=" + activeTouchScrollFirstLocalFeedbackAtMs
                        + " firstLocalFeedbackElapsedMs=" + touchScrollFirstLocalFeedbackElapsedMs()
                        + " historyActive=" + terminalHistoryDragActive
                        + " readMode=" + readModeSuppressesKeyboard
                        + " composerVisible=" + isDockedPromptComposerVisible()
                        + " detail=" + safeLogToken(detail));
    }

    private String touchLogFloat(float value) {
        return String.format(Locale.US, "%.1f", value);
    }

    private String newTouchScrollActionId() {
        touchScrollActionSequence++;
        return "scroll-" + SystemClock.uptimeMillis() + "-" + touchScrollActionSequence;
    }

    private String beginApkAction(String actionKind, String windowId) {
        apkActionSequence++;
        String safeKind = safeLogToken(actionKind == null || actionKind.trim().isEmpty()
                ? "action"
                : actionKind.trim());
        String actionId = safeKind + "-" + SystemClock.uptimeMillis() + "-" + apkActionSequence;
        return beginApkAction(actionKind, windowId, actionId, SystemClock.elapsedRealtime());
    }

    private String beginApkAction(String actionKind, String windowId, String actionId, long startedAtMs) {
        currentApkActionKind = actionKind == null ? "" : actionKind.trim();
        currentApkActionId = actionId == null ? "" : actionId.trim();
        currentApkTapId = "tap-" + SystemClock.uptimeMillis() + "-" + Math.max(1, apkActionSequence + touchScrollActionSequence);
        currentApkActionStartedAtMs = Math.max(0, startedAtMs);
        currentApkFirstLocalFeedbackAtMs = 0;
        currentApkFirstPaintAtMs = 0;
        currentApkFirstReadableFrameAtMs = 0;
        currentApkFirstReadableFrameSource = "";
        Log.i(CONTROL_LOG_TAG,
                "stage=apk-action result=started"
                        + " actionId=" + safeLogToken(currentApkActionId)
                        + " tapId=" + safeLogToken(currentApkTapId)
                        + " actionKind=" + safeLogToken(currentApkActionKind)
                        + " windowId=" + safeWindowIdForControlLog(windowId)
                        + " startedAtMs=" + currentApkActionStartedAtMs);
        return currentApkActionId;
    }

    private String currentApkActionIdForLog() {
        if (currentApkActionOwnsActiveTouchScroll()) {
            return activeTouchScrollActionId.trim();
        }
        return currentApkActionId == null ? "" : currentApkActionId.trim();
    }

    private String currentApkTapIdForLog() {
        return currentApkTapId == null ? "" : currentApkTapId.trim();
    }

    private String currentApkActionKindForLog() {
        return currentApkActionKind == null ? "" : currentApkActionKind.trim();
    }

    private boolean isCurrentApkActionKind(String expectedKind) {
        String expected = expectedKind == null ? "" : expectedKind.trim();
        return !expected.isEmpty() && expected.equals(currentApkActionKindForLog());
    }

    private boolean currentApkActionOwnsActiveTouchScroll() {
        // WHY: the 18:40 installed proof showed Send/Active/keyboard work still
        // carrying a stale `scroll-*` actionId after the scroll lane ended. Only
        // the active one-finger-scroll action may borrow `activeTouchScrollActionId`;
        // every other APK action must keep its own generated id so proof windows
        // cannot be contaminated by composer or backend polling traffic.
        return isCurrentApkActionKind("one-finger-scroll")
                && activeTouchScrollActionId != null
                && !activeTouchScrollActionId.trim().isEmpty()
                && activeTouchScrollActionId.trim().equals(
                currentApkActionId == null ? "" : currentApkActionId.trim()
        );
    }

    private long currentApkActionElapsedMs() {
        long startedAtMs = currentApkActionStartedAtMs;
        if (startedAtMs <= 0) {
            return -1;
        }
        return Math.max(0, SystemClock.elapsedRealtime() - startedAtMs);
    }

    private long currentApkFirstLocalFeedbackElapsedMs() {
        long startedAtMs = currentApkActionStartedAtMs;
        long feedbackAtMs = currentApkFirstLocalFeedbackAtMs;
        if (startedAtMs <= 0 || feedbackAtMs <= 0) {
            return -1;
        }
        return Math.max(0, feedbackAtMs - startedAtMs);
    }

    private long currentApkFirstLocalFeedbackElapsedMsForLog() {
        if (currentApkActionOwnsActiveTouchScroll()) {
            return touchScrollFirstLocalFeedbackElapsedMs();
        }
        return currentApkFirstLocalFeedbackElapsedMs();
    }

    private void markApkFirstLocalFeedback(String source, String windowId) {
        if (currentApkFirstLocalFeedbackAtMs > 0 || currentApkActionIdForLog().isEmpty()) {
            return;
        }
        currentApkFirstLocalFeedbackAtMs = SystemClock.elapsedRealtime();
        Log.i(CONTROL_LOG_TAG,
                "stage=apk-local-feedback result=first-local-feedback"
                        + " actionId=" + safeLogToken(currentApkActionIdForLog())
                        + " tapId=" + safeLogToken(currentApkTapIdForLog())
                        + " actionKind=" + safeLogToken(currentApkActionKindForLog())
                        + " windowId=" + safeWindowIdForControlLog(windowId)
                        + " source=" + safeLogToken(source)
                        + " actionElapsedMs=" + currentApkActionElapsedMs()
                        + " firstLocalFeedbackElapsedMs=" + currentApkFirstLocalFeedbackElapsedMs());
    }

    private void markApkFirstPaint(String surface, String source) {
        if (currentApkFirstPaintAtMs > 0 || currentApkActionIdForLog().isEmpty()) {
            return;
        }
        currentApkFirstPaintAtMs = SystemClock.elapsedRealtime();
        Log.i(CONTROL_LOG_TAG,
                "stage=apk-first-paint result=first-paint"
                        + " actionId=" + safeLogToken(currentApkActionIdForLog())
                        + " tapId=" + safeLogToken(currentApkTapIdForLog())
                        + " actionKind=" + safeLogToken(currentApkActionKindForLog())
                        + " surface=" + safeLogToken(surface)
                        + " source=" + safeLogToken(source)
                        + " actionElapsedMs=" + currentApkActionElapsedMs()
                        + " firstLocalFeedbackElapsedMs=" + currentApkFirstLocalFeedbackElapsedMs());
    }

    private void markApkFirstPaint(
            String surface,
            String source,
            String actionId,
            String tapId,
            String windowId,
            long actionDownUptimeMs,
            long renderedFrameObservedAtUptimeMs
    ) {
        if (actionId == null
                || actionId.trim().isEmpty()
                || !actionId.equals(currentApkActionIdForLog())
                || tapId == null
                || !tapId.equals(currentApkTapIdForLog())
                || !hasStableWindowId(windowId)
                || !windowId.equals(activeSessionsDialogDrawWindowId)
                || !windowId.equals(visibleTerminalTargetKey())
                || currentApkFirstPaintAtMs > 0) {
            return;
        }
        long actionDownToFirstRenderedFrameMs =
                actionDownUptimeMs > 0
                        && renderedFrameObservedAtUptimeMs >= actionDownUptimeMs
                        ? renderedFrameObservedAtUptimeMs - actionDownUptimeMs
                        : -1;
        currentApkFirstPaintAtMs = SystemClock.elapsedRealtime();
        Log.i(CONTROL_LOG_TAG,
                "stage=apk-first-paint result=first-paint"
                        + " actionId=" + safeLogToken(actionId)
                        + " tapId=" + safeLogToken(tapId)
                        + " actionKind=" + safeLogToken(currentApkActionKindForLog())
                        + " windowId=" + safeWindowIdForControlLog(windowId)
                        + " surface=" + safeLogToken(surface)
                        + " source=" + safeLogToken(source)
                        + " actionElapsedMs=" + currentApkActionElapsedMs()
                        + " firstLocalFeedbackElapsedMs=" + currentApkFirstLocalFeedbackElapsedMs()
                        + " actionDownToFirstRenderedFrameMs="
                        + actionDownToFirstRenderedFrameMs);
    }

    private void logActiveSessionsDecorDrawDispatch(
            String actionId,
            String tapId,
            String windowId,
            long actionDownUptimeMs,
            long decorDrawDispatchAtUptimeMs
    ) {
        if (actionId == null
                || actionId.trim().isEmpty()
                || !actionId.equals(currentApkActionIdForLog())
                || tapId == null
                || !tapId.equals(currentApkTapIdForLog())
                || !hasStableWindowId(windowId)
                || !windowId.equals(activeSessionsDialogDrawWindowId)
                || !windowId.equals(visibleTerminalTargetKey())) {
            return;
        }
        long actionDownToDecorDrawDispatchMs =
                actionDownUptimeMs > 0
                        && decorDrawDispatchAtUptimeMs >= actionDownUptimeMs
                        ? decorDrawDispatchAtUptimeMs - actionDownUptimeMs
                        : -1;
        Log.i(CONTROL_LOG_TAG,
                "stage=apk-decor-draw result=first-decor-draw-dispatch"
                        + " actionId=" + safeLogToken(actionId)
                        + " tapId=" + safeLogToken(tapId)
                        + " actionKind=" + safeLogToken(currentApkActionKindForLog())
                        + " windowId=" + safeWindowIdForControlLog(windowId)
                        + " surface=active-sessions-dialog"
                        + " actionDownToDecorDrawDispatchMs="
                        + actionDownToDecorDrawDispatchMs);
    }

    private void maybeMarkApkFirstReadableFrame(JSONObject payload, String source) {
        if (payload == null || currentApkFirstReadableFrameAtMs > 0 || currentApkActionIdForLog().isEmpty()) {
            return;
        }
        int bodyLength = payload.optInt("bodyLength", -1);
        int rowCount = payload.optInt("rowCount", -1);
        boolean acceptedFrame = payload.optBoolean("acceptedFrame", false);
        if (!acceptedFrame || bodyLength <= 0 || rowCount <= 0) {
            return;
        }
        String skipReason = payload.optString("skipReason", "");
        if ("same-hash".equals(skipReason)
                || "unaccepted-frame".equals(skipReason)
                || "empty-rows".equals(skipReason)
                || "empty-body".equals(skipReason)) {
            return;
        }
        boolean scrollAction = "one-finger-scroll".equals(currentApkActionKindForLog());
        if (scrollAction && !captureRendererPayloadHasScrollBoundaryEvidence(payload)) {
            return;
        }
        currentApkFirstReadableFrameAtMs = SystemClock.elapsedRealtime();
        currentApkFirstReadableFrameSource = source == null ? "" : source.trim();
        Log.i(CONTROL_LOG_TAG,
                "stage=apk-readable-frame result=first-readable-frame"
                        + " actionId=" + safeLogToken(currentApkActionIdForLog())
                        + " tapId=" + safeLogToken(currentApkTapIdForLog())
                        + " actionKind=" + safeLogToken(currentApkActionKindForLog())
                        + " endpoint=" + safeLogToken(payload.optString("endpoint", "renderer"))
                        + " source=" + safeLogToken(currentApkFirstReadableFrameSource)
                        + " windowId=" + safeWindowIdForControlLog(payload.optString("windowId", ""))
                        + " frameWindowId=" + safeWindowIdForControlLog(payload.optString("frameWindowId", ""))
                        + " requestedWindowId=" + safeWindowIdForControlLog(payload.optString("requestedWindowId", ""))
                        + " displayWindowId=" + safeWindowIdForControlLog(payload.optString("displayWindowId", ""))
                        + " bodyLength=" + bodyLength
                        + " rowCount=" + rowCount
                        + " hash=" + safeLogToken(payload.optString("hash", payload.optString("frameHash", "")))
                        + " hasMoreBefore=" + payload.optBoolean("hasMoreBefore", false)
                        + " copyModeViewport=" + payload.optBoolean("copyModeViewport", false)
                        + " scrollPosition=" + payload.optInt("scrollPosition", -1)
                        + " historySize=" + payload.optInt("historySize", -1)
                        + " firstNewReadableRow=" + scrollAction
                        + " retainedLastAcceptedFrame=false"
                        + " actionElapsedMs=" + currentApkActionElapsedMs()
                        + " firstLocalFeedbackElapsedMs=" + currentApkFirstLocalFeedbackElapsedMs());
    }

    private boolean captureRendererPayloadHasScrollBoundaryEvidence(JSONObject payload) {
        if (payload == null) {
            return false;
        }
        if (payload.optBoolean("hasMoreBefore", false) || payload.optBoolean("copyModeViewport", false)) {
            return true;
        }
        return payload.optInt("scrollPosition", -1) >= 0 && payload.optInt("historySize", -1) >= 0;
    }

    private void markTouchScrollFirstLocalFeedback(String where, String feedbackKind) {
        if (activeTouchScrollFirstLocalFeedbackAtMs > 0 || activeTouchScrollActionId.isEmpty()) {
            return;
        }
        activeTouchScrollFirstLocalFeedbackAtMs = SystemClock.elapsedRealtime();
        activeTouchScrollFirstLocalFeedbackKind = feedbackKind == null ? "" : feedbackKind.trim();
        boolean alreadyRenderedOnly = "renderer-distinct-rows".equals(activeTouchScrollFirstLocalFeedbackKind)
                || "renderer-pointer".equals(activeTouchScrollFirstLocalFeedbackKind)
                || "local-history-finger-nudge".equals(activeTouchScrollFirstLocalFeedbackKind);
        markApkFirstLocalFeedback("touch-scroll-" + activeTouchScrollFirstLocalFeedbackKind, terminalTouchStableWindowId);
        // WHY: old-history one-finger scroll must move locally from already
        // rendered/cache-backed content before any `/touch-scroll` response, but
        // `visual-nudge` is only already-rendered movement. It must not be counted
        // as the first new readable row; that boundary is logged from accepted
        // `/terminal-frame`/DOM telemetry when body rows actually arrive.
        Log.i(CONTROL_LOG_TAG,
                "stage=touch-scroll-local-feedback endpoint=local-cache result=first-local-feedback"
                        + " actionId=" + safeLogToken(activeTouchScrollActionId)
                        + " tapId=" + safeLogToken(currentApkTapIdForLog())
                        + " windowId=" + safeWindowIdForControlLog(terminalTouchStableWindowId)
                        + " where=" + safeLogToken(where)
                        + " feedbackKind=" + safeLogToken(activeTouchScrollFirstLocalFeedbackKind)
                        + " alreadyRenderedOnly=" + alreadyRenderedOnly
                        + " firstNewReadableRow=false"
                        + " tapDownAtMs=" + activeTouchScrollDownAtMs
                        + " firstLocalFeedbackAtMs=" + activeTouchScrollFirstLocalFeedbackAtMs
                        + " firstLocalFeedbackElapsedMs=" + touchScrollFirstLocalFeedbackElapsedMs());
    }

    private long touchScrollFirstLocalFeedbackElapsedMs() {
        if (activeTouchScrollDownAtMs <= 0 || activeTouchScrollFirstLocalFeedbackAtMs <= 0) {
            return -1;
        }
        return Math.max(0, activeTouchScrollFirstLocalFeedbackAtMs - activeTouchScrollDownAtMs);
    }

    private boolean touchScrollAwaitingFirstLocalFeedback() {
        return currentApkActionOwnsActiveTouchScroll()
                && activeTouchScrollDownAtMs > 0
                && activeTouchScrollFirstLocalFeedbackAtMs <= 0
                && (terminalTouchStartedInTerminalBody
                || terminalHistoryDragActive
                || terminalTouchExceededTapSlop
                || terminalTouchStartedInHistoryViewport);
    }

    private void deferCaptureRendererTouchNudgeReleaseForMomentum(String reason) {
        if (!terminalHistoryMomentumActive
                || !activeCaptureRendererGestureViewportOwner()) {
            Log.i(CONTROL_LOG_TAG,
                    "stage=gesture-viewport-owner endpoint=renderer"
                            + " result=fling-release-not-deferred"
                            + " reason=" + safeLogToken(reason)
                            + " actionId="
                            + safeLogToken(activeTouchScrollActionId));
            releaseCaptureRendererTouchNudge("touch-scroll-release");
            return;
        }
        // WHY: v236 proved ACTION_UP was not the gesture's terminal event when
        // OverScroller accepted a fling. Releasing the JS/native owner here made
        // every subsequent kinetic nudge return GESTURE_VIEWPORT_OWNER_MISSING.
        // Bind the deferral to the exact action and owner serial so a late terminal
        // callback can never release a newer gesture that reused this WebView.
        captureRendererGestureViewportOwnerReleaseDeferredForMomentum = true;
        captureRendererGestureViewportOwnerDeferredActionId =
                captureRendererGestureViewportOwnerActionId;
        captureRendererGestureViewportOwnerDeferredSerial =
                captureRendererGestureViewportOwnerLeaseSerial;
        Log.i(CONTROL_LOG_TAG,
                "stage=gesture-viewport-owner endpoint=renderer"
                        + " result=release-deferred-for-fling"
                        + " reason=" + safeLogToken(reason)
                        + " actionId=" + safeLogToken(
                        captureRendererGestureViewportOwnerDeferredActionId)
                        + " serial="
                        + captureRendererGestureViewportOwnerDeferredSerial);
    }

    private void releaseDeferredCaptureRendererTouchNudgeAfterMomentum() {
        if (!captureRendererGestureViewportOwnerReleaseDeferredForMomentum) {
            return;
        }
        String deferredActionId =
                captureRendererGestureViewportOwnerDeferredActionId;
        long deferredSerial =
                captureRendererGestureViewportOwnerDeferredSerial;
        captureRendererGestureViewportOwnerReleaseDeferredForMomentum = false;
        captureRendererGestureViewportOwnerDeferredActionId = "";
        captureRendererGestureViewportOwnerDeferredSerial = 0;
        boolean exactDeferredOwner =
                activeCaptureRendererGestureViewportOwner()
                        && deferredSerial > 0
                        && deferredSerial
                        == captureRendererGestureViewportOwnerLeaseSerial
                        && deferredActionId.equals(
                        captureRendererGestureViewportOwnerActionId);
        if (!exactDeferredOwner) {
            // WHY: ACTION_DOWN can replace the owner before an aborted old fling's
            // false callback arrives. The old owner was already explicitly
            // cleared during handoff; never let that callback erase the new one.
            Log.i(CONTROL_LOG_TAG,
                    "stage=gesture-viewport-owner endpoint=renderer"
                            + " result=stale-fling-terminal-ignored"
                            + " actionId=" + safeLogToken(deferredActionId)
                            + " serial=" + deferredSerial);
            return;
        }
        releaseCaptureRendererTouchNudge("touch-scroll-fling-terminal");
    }

    private void handleNativeHistoryKineticStateChanged(boolean running) {
        boolean telemetryWasActive = nativeHistoryMomentumTelemetryActive;
        terminalHistoryMomentumActive = running;
        if (running) {
            nativeHistoryMomentumTelemetryActive = true;
            nativeHistoryMomentumTelemetryActionId = activeTouchScrollActionId == null
                    ? ""
                    : activeTouchScrollActionId.trim();
            nativeHistoryMomentumTelemetryWindowId = terminalTouchStableWindowId == null
                    ? ""
                    : terminalTouchStableWindowId.trim();
            nativeHistoryMomentumTelemetryOwnerSerial =
                    captureRendererGestureViewportOwnerLeaseSerial;
            nativeHistoryMomentumStartedAtMs = SystemClock.elapsedRealtime();
            nativeHistoryMomentumFirstFrameAtMs = -1;
            nativeHistoryMomentumLastFrameAtMs = -1;
            nativeHistoryMomentumFrameCount = 0;
            nativeHistoryMomentumTotalAbsPx = 0f;
            nativeHistoryMomentumCancelReason = "";
            Log.i(CONTROL_LOG_TAG,
                    "stage=history-momentum endpoint=renderer result=started"
                            + " actionId=" + safeLogToken(
                            nativeHistoryMomentumTelemetryActionId)
                            + " windowId=" + safeWindowIdForControlLog(
                            nativeHistoryMomentumTelemetryWindowId)
                            + " ownerSerial="
                            + nativeHistoryMomentumTelemetryOwnerSerial
                            + " monotonicMs="
                            + nativeHistoryMomentumStartedAtMs);
        } else if (telemetryWasActive) {
            long terminalAtMs = SystemClock.elapsedRealtime();
            boolean cancelled = nativeHistoryMomentumCancelReason != null
                    && !nativeHistoryMomentumCancelReason.isEmpty();
            Log.i(CONTROL_LOG_TAG,
                    "stage=history-momentum endpoint=renderer result="
                            + (cancelled ? "cancelled" : "terminal")
                            + " reason=" + safeLogToken(
                            cancelled ? nativeHistoryMomentumCancelReason : "natural")
                            + " actionId=" + safeLogToken(
                            nativeHistoryMomentumTelemetryActionId)
                            + " windowId=" + safeWindowIdForControlLog(
                            nativeHistoryMomentumTelemetryWindowId)
                            + " ownerSerial="
                            + nativeHistoryMomentumTelemetryOwnerSerial
                            + " startedAtMs=" + nativeHistoryMomentumStartedAtMs
                            + " firstFrameAtMs=" + nativeHistoryMomentumFirstFrameAtMs
                            + " lastFrameAtMs=" + nativeHistoryMomentumLastFrameAtMs
                            + " terminalAtMs=" + terminalAtMs
                            + " frameCount=" + nativeHistoryMomentumFrameCount
                            + " totalAbsPx=" + touchLogFloat(
                            nativeHistoryMomentumTotalAbsPx));
            nativeHistoryMomentumTelemetryActive = false;
            nativeHistoryMomentumTelemetryActionId = "";
            nativeHistoryMomentumTelemetryWindowId = "";
            nativeHistoryMomentumTelemetryOwnerSerial = -1;
            nativeHistoryMomentumStartedAtMs = -1;
            nativeHistoryMomentumFirstFrameAtMs = -1;
            nativeHistoryMomentumLastFrameAtMs = -1;
            nativeHistoryMomentumFrameCount = 0;
            nativeHistoryMomentumTotalAbsPx = 0f;
            nativeHistoryMomentumCancelReason = "";
        }
        if (!running) {
            // NativeHistoryScrollController publishes false only from its
            // terminal/cancel path. This is the first safe point to release the
            // exact viewport owner after ACTION_UP accepted a fling.
            releaseDeferredCaptureRendererTouchNudgeAfterMomentum();
            clearNativeHistoryMomentumFence();
        }
    }

    private void bindNativeHistoryMomentumFence() {
        nativeHistoryMomentumGestureGeneration = terminalTouchGestureGeneration;
        nativeHistoryMomentumActionId = activeTouchScrollActionId == null
                ? ""
                : activeTouchScrollActionId.trim();
        nativeHistoryMomentumWindowId = terminalTouchStableWindowId == null
                ? ""
                : terminalTouchStableWindowId.trim();
        nativeHistoryMomentumViewportOwnerSerial =
                captureRendererGestureViewportOwnerLeaseSerial;
    }

    private void clearNativeHistoryMomentumFence() {
        nativeHistoryMomentumGestureGeneration = -1;
        nativeHistoryMomentumActionId = "";
        nativeHistoryMomentumWindowId = "";
        nativeHistoryMomentumViewportOwnerSerial = -1;
    }

    private boolean nativeHistoryMomentumFenceMatchesActiveOwner() {
        return nativeHistoryMomentumGestureGeneration == terminalTouchGestureGeneration
                && nativeHistoryMomentumViewportOwnerSerial > 0
                && nativeHistoryMomentumViewportOwnerSerial
                == captureRendererGestureViewportOwnerLeaseSerial
                && !nativeHistoryMomentumActionId.isEmpty()
                && nativeHistoryMomentumActionId.equals(activeTouchScrollActionId)
                && hasStableWindowId(nativeHistoryMomentumWindowId)
                && nativeHistoryMomentumWindowId.equals(terminalTouchStableWindowId);
    }

    private void cancelHistoryMomentum(String reason) {
        // WHY: active post-release inertia must die when a new touch or pinch takes
        // over. Leaving stale momentum state alive can replay scroll movement after
        // the visible APK target has changed, and the user's stop touch must halt
        // the fling immediately like a native scroller. OverScroller owns velocity
        // and deceleration; no delayed row queue survives this cancellation.
        if (nativeHistoryMomentumTelemetryActive) {
            nativeHistoryMomentumCancelReason = reason == null ? "" : reason.trim();
        }
        terminalHistoryMomentumActive = false;
        if (nativeHistoryScrollController != null && nativeHistoryScrollController.isRunning()) {
            nativeHistoryScrollController.cancel();
        } else {
            releaseDeferredCaptureRendererTouchNudgeAfterMomentum();
            clearNativeHistoryMomentumFence();
        }
    }

    private boolean activeCaptureRendererGestureViewportOwner() {
        String activeActionId = activeTouchScrollActionId == null
                ? ""
                : activeTouchScrollActionId.trim();
        String activeWindowId = terminalTouchStableWindowId == null
                ? ""
                : terminalTouchStableWindowId.trim();
        return captureRendererGestureViewportOwnerQueued
                && captureRendererGestureViewportOwnerLeaseSerial > 0
                && !activeActionId.isEmpty()
                && activeActionId.equals(
                captureRendererGestureViewportOwnerActionId)
                && hasStableWindowId(activeWindowId)
                && activeWindowId.equals(
                captureRendererGestureViewportOwnerWindowId);
    }

    private boolean applyNativeHistoryScrollPixels(float deltaY, String direction) {
        if (terminalMultiTouchGesture || webView == null) {
            if (nativeHistoryMomentumTelemetryActive) {
                nativeHistoryMomentumCancelReason = "pixel-sink-unavailable";
            }
            return false;
        }
        if (nativeHistoryMomentumTelemetryActive) {
            long frameAtMs = SystemClock.elapsedRealtime();
            if (nativeHistoryMomentumFirstFrameAtMs < 0) {
                nativeHistoryMomentumFirstFrameAtMs = frameAtMs;
            }
            nativeHistoryMomentumLastFrameAtMs = frameAtMs;
            nativeHistoryMomentumFrameCount++;
            nativeHistoryMomentumTotalAbsPx += Math.abs(deltaY);
        }
        if (terminalHistoryMomentumActive
                && (!nativeHistoryMomentumFenceMatchesActiveOwner()
                || !activeCaptureRendererGestureViewportOwner())) {
            // WHY: a Choreographer callback can already be queued when DOWN,
            // Active/session replacement, or renderer-owner rotation supersedes
            // the fling. Reject that local pixel before it can move the new target;
            // returning false terminates OverScroller without replay or I/O.
            nativeHistoryMomentumCancelReason = "owner-fence-rejected";
            return false;
        }
        String where = "lineDown".equals(direction) ? "lineDown" : "lineUp";
        if ((terminalTouchReachedHistoryTop && "lineUp".equals(where))
                || (terminalTouchReachedLiveBottom && "lineDown".equals(where))) {
            if (nativeHistoryMomentumTelemetryActive) {
                nativeHistoryMomentumCancelReason = "renderer-boundary";
            }
            return false;
        }
        if (captureRendererHistoryMovementBlocked && !activeCaptureRendererGestureViewportOwner()) {
            // WHY: READY_GAP/underrun is a missing contiguous renderer range, not a
            // direction-specific edge. v216 cleared this latch merely because the
            // finger reversed to lineDown; the same empty seam then returned
            // CLAMPED on every MOVE, saturated WebView callbacks, and left the APK
            // looking frozen. Hold both directions until an accepted READY stage
            // or a genuinely applied renderer movement proves a usable range.
            holdCaptureRendererBlockedFingerDelta(deltaY, where);
            return true;
        }
        if (captureRendererHistoryMovementBlocked
                && activeCaptureRendererGestureViewportOwner()) {
            // WHY: this is not a blind latch clear. ACTION_DOWN already bound the
            // visible active renderer buffer and atomically committed its READY
            // seams before MOVE. Carry a zero-motion seam's pixels into the next
            // local nudge; never let an earlier gesture poison this canonical
            // owner or wait for an asynchronous stage callback to replay motion.
            float mergedDeltaY = deltaY;
            if (where.equals(captureRendererBlockedFingerWhere)
                    && activeTouchScrollActionId.equals(
                    captureRendererBlockedFingerActionId)
                    && terminalTouchStableWindowId.equals(
                    captureRendererBlockedFingerWindowId)) {
                mergedDeltaY += captureRendererBlockedFingerDeltaPx;
            }
            captureRendererHistoryMovementBlocked = false;
            clearCaptureRendererBlockedFingerDelta(
                    "gesture-owner-synchronous-seam-retry");
            nudgeCaptureRendererForTouch(mergedDeltaY, where);
            return true;
        }
        nudgeCaptureRendererForTouch(deltaY, where);
        return true;
    }

    private void holdCaptureRendererBlockedFingerDelta(float deltaY, String where) {
        if (Math.abs(deltaY) < 0.5f
                || !terminalHistoryDragActive
                || activeTouchScrollActionId == null
                || activeTouchScrollActionId.trim().isEmpty()
                || !hasStableWindowId(terminalTouchStableWindowId)) {
            return;
        }
        String heldWhere = "lineDown".equals(where) ? "lineDown" : "lineUp";
        String heldWindowId = terminalTouchStableWindowId.trim();
        String heldActionId = activeTouchScrollActionId.trim();
        boolean sameOwner = heldWindowId.equals(captureRendererBlockedFingerWindowId)
                && heldActionId.equals(captureRendererBlockedFingerActionId)
                && (captureRendererBlockedFingerWhere.isEmpty()
                || heldWhere.equals(captureRendererBlockedFingerWhere));
        if (!sameOwner) {
            captureRendererBlockedFingerDeltaPx = 0f;
        }
        captureRendererBlockedFingerWhere = heldWhere;
        captureRendererBlockedFingerWindowId = heldWindowId;
        captureRendererBlockedFingerActionId = heldActionId;
        float maxHeldPx = Math.max(
                dp(192),
                webView == null ? dp(192) : Math.max(1, webView.getHeight())
        );
        captureRendererBlockedFingerDeltaPx = Math.max(
                -maxHeldPx,
                Math.min(maxHeldPx, captureRendererBlockedFingerDeltaPx + deltaY)
        );
        Log.i(CONTROL_LOG_TAG,
                "stage=touch-nudge endpoint=renderer"
                        + " actionId=" + safeLogToken(heldActionId)
                        + " windowId=" + safeWindowIdForControlLog(heldWindowId)
                        + " where=" + safeLogToken(heldWhere)
                        + " heldPx=" + touchLogFloat(captureRendererBlockedFingerDeltaPx)
                        + " result=held-for-ready-owner");
    }

    private void clearCaptureRendererBlockedFingerDelta(String reason) {
        captureRendererBlockedFingerDeltaPx = 0f;
        captureRendererBlockedFingerWhere = "";
        captureRendererBlockedFingerWindowId = "";
        captureRendererBlockedFingerActionId = "";
        captureRendererBlockedFingerReplayInFlight = false;
    }

    private boolean exactReadyHistoryOwnerMatchesActiveTouch(
            LocalHistoryRequest request,
            LocalHistoryChunk chunk
    ) {
        if (!terminalHistoryDragActive
                || request == null
                || chunk == null
                || chunk.identity == null
                || !hasStableWindowId(terminalTouchStableWindowId)
                || activeTouchScrollActionId == null
                || activeTouchScrollActionId.trim().isEmpty()) {
            return false;
        }
        String activeWindowId = terminalTouchStableWindowId.trim();
        String activeActionId = activeTouchScrollActionId.trim();
        String generationKey = localHistoryViewportGenerationKey(chunk);
        boolean exactSession = request.sessionId.isEmpty()
                || chunk.identity.sessionId.isEmpty()
                || request.sessionId.equals(chunk.identity.sessionId);
        boolean exactThread = request.threadId.isEmpty()
                || chunk.identity.threadId.isEmpty()
                || request.threadId.equals(chunk.identity.threadId);
        boolean exactVisibleGeneration = localHistoryTouchViewportGenerationKey.isEmpty()
                || localHistoryTouchViewportGenerationKey.equals(generationKey);
        return activeWindowId.equals(captureRendererBlockedFingerWindowId)
                && activeActionId.equals(captureRendererBlockedFingerActionId)
                && activeWindowId.equals(request.windowId)
                && activeWindowId.equals(chunk.identity.requestedWindowId)
                && activeWindowId.equals(chunk.identity.windowId)
                && generationKey != null
                && !generationKey.trim().isEmpty()
                && generationKey.startsWith(activeWindowId + ":")
                && exactSession
                && exactThread
                && exactVisibleGeneration;
    }

    private void replayCaptureRendererBlockedFingerDelta(
            LocalHistoryRequest request,
            LocalHistoryChunk chunk,
            String source
    ) {
        if (captureRendererBlockedFingerReplayInFlight
                || Math.abs(captureRendererBlockedFingerDeltaPx) < 0.5f
                || !exactReadyHistoryOwnerMatchesActiveTouch(request, chunk)) {
            return;
        }
        float replayPx = captureRendererBlockedFingerDeltaPx;
        String replayWhere = captureRendererBlockedFingerWhere;
        String replayActionId = captureRendererBlockedFingerActionId;
        captureRendererBlockedFingerDeltaPx = 0f;
        captureRendererBlockedFingerReplayInFlight = true;
        captureRendererHistoryMovementBlocked = false;
        Log.i(CONTROL_LOG_TAG,
                "stage=touch-nudge endpoint=renderer"
                        + " actionId=" + safeLogToken(replayActionId)
                        + " windowId=" + safeWindowIdForControlLog(request.windowId)
                        + " generationKey=" + safeLogToken(localHistoryViewportGenerationKey(chunk))
                        + " where=" + safeLogToken(replayWhere)
                        + " deltaPx=" + touchLogFloat(replayPx)
                        + " source=" + safeLogToken(source)
                        + " result=replayed-ready-owner");
        nudgeCaptureRendererForTouch(replayPx, replayWhere);
    }

    private void beginCaptureRendererPointerForwarding(
            MotionEvent currentEvent
    ) {
        // WHY(v270 continued-drag first feedback): the released hold has already
        // rebound the renderer geometry to this new action. Synthesizing a pointer
        // DOWN from its first slop-crossing MOVE makes that coordinate the new
        // baseline and discards the user's first displacement. Keep fresh
        // physical-upward gestures on the exact pointer-identity path, but let a
        // held continuation use the existing synchronous Java/native nudge below.
        if (captureRendererPointerTouchForwarding
                || webView == null
                || terminalViewerDownEvent == null
                || currentEvent == null
                || terminalViewerDownEvent.getPointerCount() != 1
                || currentEvent.getPointerCount() != 1
                || !terminalHistoryDragActive
                || terminalTouchContinuesReleasedReadHold
                || !terminalTouchPhysicalUpwardHistoryGesture
                || !hasStableWindowId(terminalTouchStableWindowId)) {
            return;
        }
        String actionId = activeTouchScrollActionId == null
                ? ""
                : activeTouchScrollActionId.trim();
        if (actionId.isEmpty()) {
            return;
        }
        // WHY(v268 physical-source replay): v267 reused the viewer/pinch
        // handoff helper after touch slop was exceeded. That helper synthesized
        // a new DOWN at the first MOVE coordinate with different device/tool
        // identity, then Chromium received real touchscreen MOVEs and admitted
        // no DOM pointer owner. Clone the first classified physical MOVE and
        // change only its action: this keeps v267's current-point handoff
        // geometry while preserving pointer/tool/source/device identity. Keep
        // the viewer helper unchanged for its separate zoom/pan contract.
        MotionEvent downEvent = MotionEvent.obtainNoHistory(currentEvent);
        downEvent.setAction(MotionEvent.ACTION_DOWN);
        boolean exactPhysicalStream =
                downEvent.getActionMasked() == MotionEvent.ACTION_DOWN
                        && downEvent.getDownTime() == currentEvent.getDownTime()
                        && downEvent.getPointerId(0) == currentEvent.getPointerId(0)
                        && downEvent.getSource() == currentEvent.getSource()
                        && downEvent.getDeviceId() == currentEvent.getDeviceId()
                        && downEvent.getToolType(0) == currentEvent.getToolType(0);
        if (!exactPhysicalStream) {
            Log.i(CONTROL_LOG_TAG,
                    "stage=renderer-pointer-input endpoint=renderer"
                            + " result=down-rejected-physical-stream-mismatch"
                            + " actionId=" + safeLogToken(actionId));
            downEvent.recycle();
            return;
        }
        captureRendererPointerTouchForwarding = true;
        captureRendererPointerActionId = actionId;
        captureRendererPointerWindowId = terminalTouchStableWindowId.trim();
        captureRendererPointerVisualGeneration =
                touchScrollVisualNudgeGeneration;
        captureRendererPointerReleaseActionId = "";
        captureRendererPointerReleaseVisualGeneration = -1;
        captureRendererPointerReleaseDeferredForMomentum = false;
        boolean downForwarded = webView.onTouchEvent(downEvent);
        downEvent.recycle();
        if (!downForwarded) {
            captureRendererPointerTouchForwarding = false;
            captureRendererPointerActionId = "";
            captureRendererPointerWindowId = "";
            captureRendererPointerVisualGeneration = -1;
            Log.i(CONTROL_LOG_TAG,
                    "stage=renderer-pointer-input endpoint=renderer"
                            + " result=down-rejected-webview"
                            + " actionId=" + safeLogToken(actionId));
            return;
        }
        Log.i(CONTROL_LOG_TAG,
                "stage=renderer-pointer-input endpoint=renderer"
                        + " result=down-forwarded"
                        + " actionId=" + safeLogToken(actionId)
                        + " windowId=" + safeWindowIdForControlLog(
                        captureRendererPointerWindowId)
                        + " visualGeneration="
                        + captureRendererPointerVisualGeneration);
    }

    private void forwardCaptureRendererPointerMove(MotionEvent event) {
        if (!captureRendererPointerTouchForwarding
                || webView == null
                || event == null
                || event.getActionMasked() != MotionEvent.ACTION_MOVE) {
            return;
        }
        webView.onTouchEvent(event);
    }

    private void finishCaptureRendererPointerForwarding(
            MotionEvent event,
            boolean releaseDeferredForMomentum
    ) {
        if (!captureRendererPointerTouchForwarding
                || webView == null
                || event == null) {
            return;
        }
        captureRendererPointerReleaseActionId =
                captureRendererPointerActionId;
        captureRendererPointerReleaseVisualGeneration =
                captureRendererPointerVisualGeneration;
        captureRendererPointerReleaseDeferredForMomentum =
                releaseDeferredForMomentum;
        // The renderer's pointerup handler queries the immutable release
        // decision above, then either latches Claude's PRESERVE residual or
        // leaves it active for the existing bounded momentum owner.
        webView.onTouchEvent(event);
        captureRendererPointerTouchForwarding = false;
        Log.i(CONTROL_LOG_TAG,
                "stage=renderer-pointer-input endpoint=renderer"
                        + " result=up-forwarded"
                        + " actionId=" + safeLogToken(
                        captureRendererPointerReleaseActionId)
                        + " releaseDeferredForMomentum="
                        + releaseDeferredForMomentum
                        + " visualGeneration="
                        + captureRendererPointerReleaseVisualGeneration);
    }

    private void cancelCaptureRendererPointerForwarding(
            MotionEvent currentEvent,
            String reason
    ) {
        if (!captureRendererPointerTouchForwarding) {
            return;
        }
        captureRendererPointerReleaseActionId =
                captureRendererPointerActionId;
        captureRendererPointerReleaseVisualGeneration =
                captureRendererPointerVisualGeneration;
        captureRendererPointerReleaseDeferredForMomentum = false;
        if (webView != null && currentEvent != null) {
            MotionEvent cancelEvent = MotionEvent.obtain(currentEvent);
            cancelEvent.setAction(MotionEvent.ACTION_CANCEL);
            webView.onTouchEvent(cancelEvent);
            cancelEvent.recycle();
        }
        captureRendererPointerTouchForwarding = false;
        Log.i(CONTROL_LOG_TAG,
                "stage=renderer-pointer-input endpoint=renderer"
                        + " result=cancel-forwarded"
                        + " actionId=" + safeLogToken(
                        captureRendererPointerReleaseActionId)
                        + " reason=" + safeLogToken(reason));
    }

    private void recycleTerminalVelocityTracker() {
        if (terminalVelocityTracker != null) {
            terminalVelocityTracker.recycle();
            terminalVelocityTracker = null;
        }
    }

    private boolean forwardTouchToViewer(MotionEvent event) {
        if (webView == null) {
            return true;
        }
        beginForwardingTouchToViewer(event);
        webView.onTouchEvent(event);
        return true;
    }

    private void beginForwardingTouchToViewer(MotionEvent currentEvent) {
        if (terminalForwardingTouchToViewer || webView == null) {
            return;
        }
        terminalForwardingTouchToViewer = true;
        if (terminalViewerDownEvent != null) {
            // WHY: WEzterm consumes ACTION_DOWN until it knows whether the gesture
            // is vertical tmux scroll, a tap, horizontal viewer pan, or pinch. When
            // the gesture is not tmux-owned, replay the original DOWN into WebView
            // before forwarding MOVE/UP so top tmux tab clicks and Android zoom/pan
            // still see a complete touch stream.
            MotionEvent downEvent = downEventForViewerHandoff(currentEvent);
            webView.onTouchEvent(downEvent);
            downEvent.recycle();
        }
    }

    private void forwardTapToViewer(MotionEvent upEvent) {
        beginForwardingTouchToViewer(upEvent);
        if (webView != null) {
            webView.onTouchEvent(upEvent);
        }
    }

    private MotionEvent downEventForViewerHandoff(MotionEvent currentEvent) {
        if (currentEvent == null
                || currentEvent.getActionMasked() == MotionEvent.ACTION_UP
                || currentEvent.getPointerCount() < 1
                || (!terminalTouchExceededTapSlop && !terminalMultiTouchGesture && !terminalHorizontalPanActive)) {
            return MotionEvent.obtain(terminalViewerDownEvent);
        }
        if (terminalHorizontalPanActive && !terminalMultiTouchGesture) {
            // WHY: one-finger zoomed horizontal pan must replay the original DOWN.
            // v2.72 synthesized DOWN at the first MOVE point, which erased the
            // horizontal delta WebView needs to visually move the zoomed viewport.
            // Keep the synthetic-current handoff for pinch, but let one-finger
            // line-reading pan deliver the real down->move displacement.
            return MotionEvent.obtain(terminalViewerDownEvent);
        }
        // WHY: WEzterm holds ACTION_DOWN until it knows whether the gesture is
        // tmux-history or Android/WebView-owned. Replaying the original DOWN after
        // the finger has already moved makes native WebView pinch/pan reconcile a
        // stale start point with the current two-finger event, which feels like the
        // zoomed viewport jumps. For non-tap viewer handoff, synthesize the DOWN at
        // the current primary pointer so WebView starts the native gesture where
        // the user actually began panning/zooming.
        return MotionEvent.obtain(
                currentEvent.getDownTime(),
                currentEvent.getEventTime(),
                MotionEvent.ACTION_DOWN,
                currentEvent.getX(0),
                currentEvent.getY(0),
                currentEvent.getMetaState()
        );
    }

    private boolean isTopTerminalTap(MotionEvent event) {
        // WHY: only the tmux/ttyd chrome near the top needs a real WebView tap
        // after WEzterm consumes ACTION_DOWN for gesture classification. Terminal
        // body taps are typing-focus requests, so forwarding them to xterm and then
        // running a native focus fallback gives Android two competing IME owners.
        // WHY: the old 48dp strip included the first shell/prompt row on the
        // real phone. Tapping that row forwarded the gesture to xterm's hidden
        // textarea, bypassing the native composer and reviving duplicate-word
        // input. Only the actual tmux/ttyd tab strip is WebView-owned.
        return event.getY() <= dp(24);
    }

    private boolean isTerminalBodyScrollGestureTarget(MotionEvent event) {
        if (event == null) {
            return false;
        }
        View target = terminalFrame != null ? terminalFrame : webView;
        int height = target == null ? 0 : target.getHeight();
        float y = event.getY();
        if (height <= 0) {
            return y > dp(TERMINAL_BODY_TOUCH_TOP_CHROME_GUARD_DP);
        }
        int topGuard = dp(TERMINAL_BODY_TOUCH_TOP_CHROME_GUARD_DP);
        int bottomGuard = terminalBodyToolbarBoundaryGuardPx();
        return y >= topGuard && y <= Math.max(topGuard, height - bottomGuard);
    }

    private boolean isTerminalTypingTapTarget(MotionEvent event) {
        if (event == null || !isTerminalBodyScrollGestureTarget(event)) {
            return false;
        }
        View target = terminalFrame != null ? terminalFrame : webView;
        int height = target == null ? 0 : target.getHeight();
        if (height <= 0) {
            return false;
        }
        int bottomGuard = terminalBodyToolbarBoundaryGuardPx();
        int usableBottom = Math.max(0, height - bottomGuard);
        int topGuard = dp(TERMINAL_BODY_TOUCH_TOP_CHROME_GUARD_DP);
        int usableHeight = Math.max(0, usableBottom - topGuard);
        int typingBandHeight = Math.max(
                dp(PROMPT_COMPOSER_INPUT_HEIGHT_DP
                        + (2 * PROMPT_COMPOSER_VERTICAL_PADDING_DP)),
                Math.max(
                        terminalTouchSlop * 2,
                        Math.min(dp(144), usableHeight / 4)
                )
        );
        int typingBandTop = Math.max(
                topGuard,
                usableBottom - typingBandHeight
        );
        // WHY(v275): the visible Codex prompt/status block is taller than the
        // hidden editor row. Admit only the bounded lower quarter (capped at
        // 144dp) as explicit no-drag typing intent; upper retouches and every drag
        // continue to preserve the released reading position.
        float y = event.getY();
        return y >= typingBandTop && y <= usableBottom;
    }

    private int terminalBodyToolbarBoundaryGuardPx() {
        // WHY: the failed installed T5 gesture started near the terminal/toolbar
        // boundary and opened WEzTerm's native Copy/Paste menu instead of owning
        // terminal history. Keep terminal-body scroll classification inside a
        // body-safe rectangle that excludes the bottom toolbar/Copy/Paste controls;
        // toolbar buttons still work from their own views, but vertical terminal
        // drags cannot be reclassified into a modal after the gesture starts.
        return Math.max(dp(TERMINAL_BODY_TOUCH_BOTTOM_TOOLBAR_GUARD_DP), terminalTouchSlop);
    }

    private void suppressCopyPasteControlsForTerminalScroll(String reason) {
        terminalScrollSuppressCopyPasteUntilMs = Math.max(
                terminalScrollSuppressCopyPasteUntilMs,
                SystemClock.elapsedRealtime() + TERMINAL_SCROLL_COPY_PASTE_SUPPRESS_MS
        );
        Log.i(CONTROL_LOG_TAG,
                "stage=terminal-touch-copy-paste-suppression"
                        + " result=armed"
                        + " reason=" + safeLogToken(reason)
                        + " actionId=" + safeLogToken(activeTouchScrollActionId)
                        + " windowId=" + safeWindowIdForControlLog(terminalTouchStableWindowId));
    }

    private boolean isCopyPasteSuppressedByTerminalScroll() {
        long suppressUntilMs = terminalScrollSuppressCopyPasteUntilMs;
        return suppressUntilMs > 0 && SystemClock.elapsedRealtime() <= suppressUntilMs;
    }

    private void recycleTerminalViewerDownEvent() {
        if (terminalViewerDownEvent != null) {
            terminalViewerDownEvent.recycle();
            terminalViewerDownEvent = null;
        }
        terminalForwardingTouchToViewer = false;
    }

    private void processHistoryDragEventSamples(MotionEvent event) {
        // WHY: Android may batch multiple MOVE coordinates into one MotionEvent.
        // Using only the final point makes the laptop/tmux state look smooth while
        // the APK jumps in larger chunks. Process historical Y samples with their
        // own event times, but keep the protected `/touch-scroll` throttle and
        // repeat caps so a fast flick is still fast and a slow drag stays readable.
        int historySize = event.getHistorySize();
        for (int i = 0; i < historySize; i++) {
            processHistoryDragSample(event.getHistoricalY(i), event.getHistoricalEventTime(i));
        }
        processHistoryDragSample(event.getY(), event.getEventTime());
    }

    private void processHistoryDragSample(float y, long eventTimeMs) {
        // WHY: v1.42 used page-sized HTTP scrolls. That could not paint
        // continuously under a finger, so the screen appeared frozen and then
        // jumped to a random-looking page. Use line-sized tmux copy-mode movement
        // for drag; the explicit Scroll menu still owns jump-to-top, page-up/down,
        // reader, and live-bottom recovery.
        int lineThreshold = historyDragLineThresholdPx();
        // WHY: v2.8/v2.96 one-finger physics made the already-rendered terminal
        // layer follow every MOVE with a pixel delta, then let row commits catch
        // up behind it. The local-history cache must preserve that direct
        // manipulation contract. Do not replace a row-qualified MOVE with an
        // immediate cached-row repaint; inline cache paint already settles the
        // residual nudge through settleLocalHistoryFingerNudge(...). Skipping the
        // nudge here is the "small finger movement jumps massive amounts" loop.
        nudgeCaptureRendererForHistorySample(y, lineThreshold);
        float step = y - terminalLastHistoryDragY;
        markUpwardHistoryIntentIfNeeded(y, step);
        if (Math.abs(step) < lineThreshold) {
            return;
        }
        // WHY: Android screen Y increases when the finger moves down. The default
        // physical proof path treats terminal scroll like natural touch scrollback:
        // dragging the finger down moves into older tmux history (`lineUp`), while
        // dragging up returns toward live bottom (`lineDown`). A separate live-bottom
        // latch below handles the user-facing physical "scroll up" proof gesture, so
        // both historical proof directions can enter the same local-history source
        // without breaking lineDown/toward-live return once history is active.
        // APK-SCROLL-ONE-FINGER-DELAY-BOUNDARY-1537-A is the catastrophic
        // repeat-regression form: if this sign mapping drifts, live-bottom lineDown
        // clamps swallow the first real history drag, visual nudge and tmux commits
        // fight each other, and a delayed response looks like an invisible boundary.
        String where = step > 0 ? "lineUp" : "lineDown";
        boolean directionChanged = !terminalHistoryDragWhere.isEmpty()
                && !where.equals(terminalHistoryDragWhere);
        if (!terminalHistoryDragWhere.isEmpty()
                && !where.equals(terminalHistoryDragWhere)
                && Math.abs(step) < lineThreshold * HISTORY_DRAG_DIRECTION_REVERSAL_MIN_LINES) {
            // WHY: slow reading drags include small opposite-direction samples from
            // finger jitter and Android MOVE batching. Dispatching or nudging those
            // samples makes the phone visibly bounce backward while the laptop/tmux
            // scroll stays smooth. Swallow only tiny reversals; a deliberate reverse
            // over the line gate below changes direction immediately.
            // Do not advance the row baseline or throttle clock here. Consuming every
            // small reverse sample made a real slow direction change restart from zero
            // repeatedly, which felt like a two-second dead zone while old rows drained.
            return;
        }
        int repeats = historyDragRepeats(step, lineThreshold, eventTimeMs);
        long minDispatchMs = repeats <= HISTORY_DRAG_SLOW_MOVE_MAX_REPEATS
                ? HISTORY_DRAG_SLOW_ROW_COMMIT_MS
                : HISTORY_DRAG_THROTTLE_MS;
        if (!directionChanged && eventTimeMs - lastHistoryDragAtMs < minDispatchMs) {
            // WHY: slow drag keeps visual-continuous motion through the capture
            // renderer nudge. Tmux row commits are background catch-up work; sending
            // a row command every frame makes the visible phone surface step line by
            // line even though each command is only repeat=1.
            return;
        }
        terminalLastHistoryDragY = y;
        terminalLastHistoryDragEventAtMs = eventTimeMs;
        lastHistoryDragAtMs = eventTimeMs;
        if (!where.equals(terminalHistoryDragWhere)) {
            boolean hadPriorDirection = !terminalHistoryDragWhere.isEmpty();
            terminalHistoryDragWhere = where;
            terminalHistoryDragDirectionGeneration++;
            clearPendingHistoryScroll();
            if (hadPriorDirection) {
                supersedeHistoryScrollInFlightForDirectionChange();
                cancelHistoryMomentum("drag-direction-change");
                // WHY: the capture-renderer transform is the only pixel-continuous
                // thing under the finger. Clearing it on reversal snaps the text back
                // to the last committed tmux row exactly when the user expects the
                // content to reverse with their finger.
                repeats = HISTORY_DRAG_READING_MOVE_REPEATS;
            }
        }
        if (terminalTouchReachedLiveBottom && "lineDown".equals(where)) {
            // WHY: once tmux has hit the live bottom, extra lineDown/toward-live
            // finger-up motion has nowhere meaningful to go. Sending more lineDown
            // requests would re-enter/cancel copy-mode on every MOVE and looks like
            // a page refresh/bounce at the bottom. Swallow only the continued
            // toward-live edge; reversing into finger-down lineUp still immediately
            // re-enters tmux history.
            return;
        }
        if ("lineUp".equals(where)) {
            terminalTouchReachedLiveBottom = false;
        }
        if (terminalTouchReachedHistoryTop && "lineUp".equals(where)) {
            // WHY: APK-SCROLL-ONE-FINGER-DELAY-BOUNDARY-1537-A can also present as
            // a delayed top-edge "invisible boundary." Once tmux metadata says the
            // true history top is reached, continued active lineUp MOVE requests only
            // queue stale backend work with no rows behind it; a deliberate lineDown
            // below clears the latch and returns toward live bottom.
            return;
        }
        if ("lineDown".equals(where)) {
            terminalTouchReachedHistoryTop = false;
        }
        keepCaptureRendererPulsingDuringTouch("touch-scroll-move");
        // HISTORY_DRAG_MOVE_NETWORK_ENABLED intentionally remains a guard-visible
        // false invariant. MOVE only records the eventual reconciliation; it never
        // takes the network/tmux branch.
        deferHistoryScrollUntilRelease(where, repeats);
    }

    private void deferHistoryScrollUntilRelease(String where, int repeats) {
        String normalizedWhere = "lineDown".equals(where) ? "lineDown" : "lineUp";
        int boundedRepeats = Math.max(1, Math.min(HISTORY_DRAG_MAX_PAGES_PER_STEP, repeats));
        if (!normalizedWhere.equals(deferredHistoryScrollWhere)) {
            deferredHistoryScrollWhere = normalizedWhere;
            deferredHistoryScrollRepeats = boundedRepeats;
            return;
        }
        deferredHistoryScrollRepeats = Math.min(
                HISTORY_DRAG_MAX_PAGES_PER_STEP,
                deferredHistoryScrollRepeats + boundedRepeats
        );
    }

    private void flushDeferredHistoryScrollOnRelease(boolean releaseFlingStarted) {
        String where = deferredHistoryScrollWhere;
        int repeats = deferredHistoryScrollRepeats;
        deferredHistoryScrollWhere = "";
        deferredHistoryScrollRepeats = 0;
        // WHY: cached history is the one-finger visual owner. Replaying accumulated
        // MOVE distance through `/touch-scroll` after release caused the delayed
        // second burst. Bottom/live actions explicitly leave local read state.
    }

    private void markUpwardHistoryIntentIfNeeded(float y, float step) {
        if (terminalTouchStartedInHistoryViewport
                || terminalTouchSawUpwardHistoryIntent
                || step <= 0f) {
            return;
        }
        float historyIntentThreshold = Math.max(0.5f, dp(HISTORY_DRAG_LONG_PRESS_CANCEL_DP));
        boolean crossedHistoryIntentThreshold =
                y >= terminalTouchStartY + historyIntentThreshold;
        if (!crossedHistoryIntentThreshold) {
            return;
        }
        // WHY: APK-ONE-FINGER-SNAP-BACK-BOTTOM-1506-T reproduced a bottom snap
        // when a live-bottom finger-down history drag did not yet cross the row
        // dispatch threshold. The live-bottom latch is still correct for lineDown
        // toward-live edge clamps, but any real lineUp history intent must disable
        // automatic finger-up bottom restore before it can force the reader back down.
        terminalTouchSawUpwardHistoryIntent = true;
        terminalTouchReachedLiveBottom = false;
        cancelPassiveLiveBottomCallbacksForReadScroll("touch-scroll-upward-intent");
        Log.i(CONTROL_LOG_TAG,
                "stage=touch-scroll-upward-intent endpoint=/touch-scroll"
                        + " result=live-bottom-restore-blocked"
                        + " dy=" + touchLogFloat(y - terminalTouchStartY)
                        + " windowId=" + safeWindowIdForControlLog(terminalTouchStableWindowId));
    }

    private void nudgeCaptureRendererForHistorySample(float y, int lineThreshold) {
        float visualStep = y - terminalLastTouchVisualNudgeY;
        if (Math.abs(visualStep) < 0.5f) {
            return;
        }
        // WHY: APK-SCROLL-ONE-FINGER-DELAY-BOUNDARY-1537-A depends on the visual
        // residual and the server line command having one semantic direction.
        // Android screen Y decreases during a physical upward drag, but the
        // renderer contract uses positive pixels for lineUp. Forwarding the raw
        // Y sign after remapping only the label makes the compositor move toward
        // live bottom and clamp while old-history rows are being staged.
        String visualWhere = visualStep > 0 ? "lineUp" : "lineDown";
        float rendererStep = "lineUp".equals(visualWhere)
                ? Math.abs(visualStep)
                : -Math.abs(visualStep);
        if (!terminalHistoryDragWhere.isEmpty()
                && !visualWhere.equals(terminalHistoryDragWhere)
                && Math.abs(y - terminalLastHistoryDragY)
                < lineThreshold * HISTORY_DRAG_DIRECTION_REVERSAL_MIN_LINES) {
            int visualReversalSlop = Math.max(1, Math.min(
                    lineThreshold,
                    dp(HISTORY_DRAG_VISUAL_REVERSAL_SLOP_DP)
            ));
            if (Math.abs(y - terminalLastTouchVisualNudgeY) < visualReversalSlop) {
                return;
            }
            // WHY: sub-threshold visual nudges must follow real finger movement,
            // but tiny opposite-direction MOVE samples are Android jitter, not a
            // deliberate reverse. Hold only a couple pixels without consuming the
            // baseline; once the finger clearly reverses, apply the accumulated
            // visual residual immediately while tmux row dispatch remains line-gated.
        }
        if (terminalTouchReachedLiveBottom && "lineDown".equals(visualWhere)) {
            // WHY: a visual-only latency nudge has no row coverage past the live
            // bottom. Continuing to move it toward lineDown exposes the black WebView
            // background near the toolbar before tmux can report another bottom
            // response, which is the current slow-scroll screenshot regression.
            terminalLastTouchVisualNudgeY = y;
            return;
        }
        if (terminalTouchReachedLiveBottom
                && "lineUp".equals(visualWhere)
                && y <= terminalTouchStartY + 0.5f) {
            // WHY: live-bottom lineDown samples are intentionally swallowed above.
            // If the same finger reverses before crossing back past the original
            // bottom touch point, using that swallowed MOVE as the visual baseline
            // creates a fake positive history nudge while tmux is still at
            // scroll_position 0. That is the "invisible bottom section" snap: the
            // summary slides under the toolbar even though no real history row was
            // entered. Hold the visual baseline at the original bottom anchor until
            // the finger genuinely drags into history.
            terminalLastTouchVisualNudgeY = terminalTouchStartY;
            return;
        }
        if ("lineUp".equals(visualWhere)) {
            terminalTouchReachedLiveBottom = false;
        }
        if (terminalTouchReachedHistoryTop && "lineUp".equals(visualWhere)) {
            // WHY: top edge is also a real range boundary. Once tmux says the
            // copy-mode viewport is at history top, a visual-only lineUp/older-history
            // nudge has no backing rows and makes the scroll feel hung or rubber-banded.
            terminalLastTouchVisualNudgeY = y;
            return;
        }
        if ("lineDown".equals(visualWhere)) {
            terminalTouchReachedHistoryTop = false;
        }
        if (nativeHistoryScrollController != null) {
            nativeHistoryScrollController.dragBy(rendererStep, visualWhere);
        } else {
            nudgeCaptureRendererForTouch(rendererStep, visualWhere);
        }
        terminalLastTouchVisualNudgeY = y;
    }

    private int historyDragRepeats(float step, int lineThreshold, long eventTimeMs) {
        float velocity = 0f;
        if (terminalVelocityTracker != null) {
            terminalVelocityTracker.computeCurrentVelocity(1000);
            velocity = Math.abs(terminalVelocityTracker.getYVelocity());
        }
        long eventDeltaMs = Math.max(1, eventTimeMs - terminalLastHistoryDragEventAtMs);
        float segmentVelocity = Math.abs(step) * 1000f / eventDeltaMs;
        velocity = Math.max(velocity, segmentVelocity);
        float distanceLines = Math.abs(step) / Math.max(1f, lineThreshold);
        // WHY: this intentionally separates a controlled reading drag from an
        // explicit flick. Slow MOVE must stay one line-sized request at a time,
        // even when Android batches samples after the control server is busy; only
        // quick high-velocity gestures get acceleration while the finger is moving.
        // The cap prevents bad flicks from queuing huge delayed jumps that look
        // like freezing or restarting.
        // Android's VelocityTracker can under-report synthetic and WebView-routed
        // gestures, so this also checks the segment velocity since the last
        // dispatched history step. Distance alone must not promote a slow drag:
        // the latest P3 complaint was that slowed constants still felt jumpy
        // because backend cadence gaps turned one slow MOVE into a fast batch.
        long gestureWallMs = terminalTouchDownWallClockMs > 0
                ? Math.max(1, System.currentTimeMillis() - terminalTouchDownWallClockMs)
                : eventDeltaMs;
        boolean fastByVelocity = velocity >= HISTORY_DRAG_FAST_VELOCITY_PX_PER_SEC;
        boolean flingByVelocity = velocity >= HISTORY_DRAG_FLING_VELOCITY_PX_PER_SEC;
        int repeats = HISTORY_DRAG_READING_MOVE_REPEATS;
        if (gestureWallMs <= HISTORY_DRAG_RELEASE_LONG_GESTURE_MS) {
            if (flingByVelocity && distanceLines >= HISTORY_DRAG_FLING_DISTANCE_LINES) {
                repeats = HISTORY_DRAG_FLING_MOVE_REPEATS;
            } else if (fastByVelocity && distanceLines >= HISTORY_DRAG_FAST_DISTANCE_LINES) {
                repeats = HISTORY_DRAG_FAST_MOVE_REPEATS;
            }
        }
        int physicalLineRepeats = Math.max(1, Math.min(
                HISTORY_DRAG_MAX_PAGES_PER_STEP,
                (int) Math.floor(distanceLines)
        ));
        if (repeats > HISTORY_DRAG_READING_MOVE_REPEATS) {
            // WHY: Android can report a tiny physical slow-drag segment with a
            // high instantaneous velocity when MOVE samples are batched. Velocity
            // may choose the fast path, but it must not multiply the first
            // copy-mode step beyond the line distance the finger actually moved,
            // or a hundredth-inch drag jumps rows before the user can read them.
            repeats = Math.min(repeats, physicalLineRepeats);
        }
        return Math.max(1, Math.min(HISTORY_DRAG_MAX_PAGES_PER_STEP, repeats));
    }

    private boolean dispatchHistoryReleaseFling(MotionEvent event) {
        int minimumFlingVelocity = nativeHistoryScrollController == null
                ? -1
                : nativeHistoryScrollController.minimumFlingVelocityPxPerSecond();
        int maximumFlingVelocity = nativeHistoryScrollController == null
                ? -1
                : nativeHistoryScrollController.maximumFlingVelocityPxPerSecond();
        if (!historyDragReleaseMomentumEnabled()) {
            // WHY: APK-SCROLL-POST-RELEASE-SNAP-2346 proved unbounded
            // release/momentum could keep draining `/touch-scroll` after finger-up.
            // This kill switch is only for emergency disablement; the accepted path
            // below is gated to quick high-velocity flicks and bounded momentum.
            return logHistoryReleaseFlingDecision(
                    "disabled", false, 0f,
                    minimumFlingVelocity, maximumFlingVelocity,
                    "", false, false);
        }
        // WHY: cache is prepared data, never a second kinetic owner. Whether the
        // current rows came from live capture or READY history, the same renderer
        // viewport consumes OverScroller pixels. Platform touch slop and minimum
        // fling velocity—not a cache-specific hard stop or guessed multiplier—keep
        // small reading movements precise.
        float totalDy = event.getY() - terminalTouchStartY;
        float absDy = Math.abs(totalDy);
        if (!terminalTouchExceededTapSlop
                || absDy < terminalTouchSlop
                || terminalVelocityTracker == null
                || nativeHistoryScrollController == null) {
            return logHistoryReleaseFlingDecision(
                    "gesture-not-qualified", false, 0f,
                    minimumFlingVelocity, maximumFlingVelocity,
                    "", false, false);
        }
        // Android's tracker guidance calculates from the last collected MOVE;
        // ACTION_UP is deliberately not added because it can report zero velocity.
        terminalVelocityTracker.computeCurrentVelocity(1000, maximumFlingVelocity);
        float signedReleaseVelocity = terminalVelocityTracker.getYVelocity(event.getPointerId(0));
        float releaseVelocity = Math.abs(signedReleaseVelocity);
        // Same Android Y-axis contract as MOVE samples: default finger-down flicks
        // go to older history, default finger-up flicks return toward live bottom.
        String where = signedReleaseVelocity > 0 ? "lineUp" : "lineDown";
        boolean velocityQualified =
                nativeHistoryScrollController.isFlingVelocity(releaseVelocity);
        if (!velocityQualified) {
            return logHistoryReleaseFlingDecision(
                    "below-device-minimum", true, signedReleaseVelocity,
                    minimumFlingVelocity, maximumFlingVelocity,
                    where, false, false);
        }
        if (!releaseFlingDirectionMatchesDrag(
                terminalHistoryDragWhere,
                where)) {
            // WHY: VelocityTracker may weight the final UP sample opposite to
            // the last committed MOVE. Starting that candidate reverses the
            // rendered anchor after finger-up even though the user never dragged
            // back toward live bottom. A fling may extend the accepted drag
            // direction; it may never invent the opposite one.
            return logHistoryReleaseFlingDecision(
                    "opposite-drag-direction", true, signedReleaseVelocity,
                    minimumFlingVelocity, maximumFlingVelocity,
                    where, true, false);
        }
        if (terminalTouchReachedLiveBottom && "lineDown".equals(where)) {
            // WHY: a release fling in the same lineDown/toward-live direction after
            // tmux has already reported live bottom would queue extra lineDown
            // requests at the edge. That is the exact "refresh/bounce before I get
            // to the bottom" symptom; wait for finger-up restore instead.
            return logHistoryReleaseFlingDecision(
                    "live-bottom-boundary", true, signedReleaseVelocity,
                    minimumFlingVelocity, maximumFlingVelocity,
                    where, true, false);
        }
        if (terminalTouchReachedHistoryTop && "lineUp".equals(where)) {
            // WHY: the top latch is server-owned like live bottom. Letting a release
            // fling keep sending lineUp after tmux says "top" just queues delayed
            // no-op work and makes APK-SCROLL-ONE-FINGER-DELAY-BOUNDARY-1537-A look
            // like a frozen drag that later hits an invisible edge.
            return logHistoryReleaseFlingDecision(
                    "history-top-boundary", true, signedReleaseVelocity,
                    minimumFlingVelocity, maximumFlingVelocity,
                    where, true, false);
        }
        // WHY: fixed tmux repeats quantized release distance and made motion depend
        // on endpoint latency. OverScroller owns native relative-pixel decay; the
        // renderer keeps the absolute anchor through READY prepends and frame swaps.
        boolean started = nativeHistoryScrollController.fling(releaseVelocity, where);
        if (started) {
            // OverScroller posts its first Choreographer frame after this input
            // callback. Freeze the exact action/target/viewport owner now so every
            // kinetic pixel is rejected if a new touch or target supersedes it.
            bindNativeHistoryMomentumFence();
        }
        return logHistoryReleaseFlingDecision(
                started ? "started" : "controller-rejected",
                true, signedReleaseVelocity,
                minimumFlingVelocity, maximumFlingVelocity,
                where, true, started);
    }

    private boolean logHistoryReleaseFlingDecision(
            String decision,
            boolean velocityMeasured,
            float signedVelocityPxPerSecond,
            int minimumVelocityPxPerSecond,
            int maximumVelocityPxPerSecond,
            String where,
            boolean velocityQualified,
            boolean started
    ) {
        // WHY(T5 observability): one bounded decision receipt records Android's
        // actual device-scaled release admission. Never log each kinetic frame;
        // the terminal momentum summary below aggregates that hot path in memory.
        Log.i(CONTROL_LOG_TAG,
                "stage=history-release-fling endpoint=renderer"
                        + " result=" + (started ? "started" : "suppressed")
                        + " decision=" + safeLogToken(decision)
                        + " actionId=" + safeLogToken(activeTouchScrollActionId)
                        + " windowId=" + safeWindowIdForControlLog(
                        terminalTouchStableWindowId)
                        + " dragWhere=" + safeLogToken(terminalHistoryDragWhere)
                        + " candidateWhere=" + safeLogToken(where)
                        + " velocityMeasured=" + velocityMeasured
                        + " signedVelocityPxPerSecond="
                        + touchLogFloat(signedVelocityPxPerSecond)
                        + " absoluteVelocityPxPerSecond="
                        + touchLogFloat(Math.abs(signedVelocityPxPerSecond))
                        + " minimumVelocityPxPerSecond="
                        + minimumVelocityPxPerSecond
                        + " maximumVelocityPxPerSecond="
                        + maximumVelocityPxPerSecond
                        + " velocityQualified=" + velocityQualified
                        + " monotonicMs=" + SystemClock.elapsedRealtime());
        return started;
    }

    private boolean historyDragReleaseMomentumEnabled() {
        return HISTORY_DRAG_RELEASE_MOMENTUM_ENABLED;
    }

    private static boolean releaseFlingDirectionMatchesDrag(
            String dragWhere,
            String candidateWhere
    ) {
        String stableDragWhere =
                "lineDown".equals(dragWhere) ? "lineDown"
                        : ("lineUp".equals(dragWhere) ? "lineUp" : "");
        String stableCandidateWhere =
                "lineDown".equals(candidateWhere) ? "lineDown"
                        : ("lineUp".equals(candidateWhere) ? "lineUp" : "");
        return stableDragWhere.isEmpty()
                || stableDragWhere.equals(stableCandidateWhere);
    }

    private int historyDragLineThresholdPx() {
        int measuredRows = Math.max(
                lastAcceptedCaptureRendererRows.size(),
                lastAcceptedCaptureRendererPaintRows.size()
        );
        int viewportHeight = 0;
        if (terminalFrame != null && terminalFrame.getHeight() > 0) {
            viewportHeight = terminalFrame.getHeight();
        } else if (webView != null && webView.getHeight() > 0) {
            viewportHeight = webView.getHeight();
        }
        int measuredRowHeight = 0;
        if (viewportHeight > 0 && measuredRows > 0) {
            measuredRowHeight = Math.round(viewportHeight / Math.max(1f, (float) measuredRows));
        }
        int fallbackRowHeight = dp(Math.max(HISTORY_DRAG_LINE_THRESHOLD_DP, 12));
        int rowHeight = measuredRowHeight > 0 ? measuredRowHeight : fallbackRowHeight;
        int minRowHeight = dp(8);
        int maxRowHeight = dp(28);
        rowHeight = Math.max(minRowHeight, Math.min(maxRowHeight, rowHeight));
        // WHY: terminal scrollback row commits must be paced by terminal cell
        // height, not by Android tap slop. The old 5dp/touch-slop gate could
        // advance one tmux/cache row after much less than one visible row of
        // finger travel, so a tiny drag looked like it flew upward. Pixel nudges
        // handle sub-row movement; row commits only reconcile full-row distance.
        return Math.max(terminalTouchSlop, rowHeight);
    }

    private void scrollTerminalFromTouch(String where, int repeats) {
        scrollTerminalFromTouch(where, repeats, false, terminalTouchStableWindowId);
    }

    private void scrollTerminalFromTouch(String where, int repeats, boolean fromMomentum, String targetKey) {
        // WHY: normal WebView scrolling moves ttyd/xterm's browser scrollback,
        // which records tmux redraw artifacts instead of the real pane history
        // visible to Codex. Deliberate one-finger vertical drags use the server
        // history path, but now as small lineUp/lineDown commands so the screen
        // tracks the finger instead of jumping by whole pages.
        // WHY: keep one request in flight and coalesce by direction so stale
        // responses cannot fight the user's finger. v2.77 keeps the old "no
        // huge delayed catch-up burst" guard, but stops replacing every slow
        // sample with a single tiny pending step. The 2026-06-26 regression proof
        // showed a 1400 px slow drag moving only about 9 rows. Preserve enough
        // bounded distance inside one network/tmux request window for low-speed
        // tracking, while still capping the replay so slow reading cannot become
        // the old jumpy page-scroll failure.
        int maxRepeats = "lineDown".equals(where)
                ? HISTORY_DRAG_DOWN_MAX_REPEATS
                : HISTORY_DRAG_MAX_PAGES_PER_STEP;
        int boundedRepeats = Math.max(1, Math.min(maxRepeats, repeats));
        long gestureGeneration = terminalTouchGestureGeneration;
        long directionGeneration = terminalHistoryDragDirectionGeneration;
        String stableTargetKey = targetKey == null || targetKey.trim().isEmpty()
                ? terminalTouchStableWindowId
                : targetKey.trim();
        if (terminalTouchReachedLiveBottom && "lineDown".equals(where)) {
            return;
        }
        if ("lineUp".equals(where)) {
            terminalTouchReachedLiveBottom = false;
        }
        if (terminalTouchReachedHistoryTop && "lineUp".equals(where)) {
            return;
        }
        if ("lineDown".equals(where)) {
            terminalTouchReachedHistoryTop = false;
        }
        if (historyScrollRequestInFlight) {
            // WHY: old-history motion is APK-local cache owned. If a prior
            // `/touch-scroll` request is still in flight, keep moving the
            // target-bound cached viewport now and let the backend response
            // reconcile later; otherwise a slow connection recreates the
            // invisible chunk boundary while the finger is still moving.
            boolean suppressLocalHistoryPrefetch = updateLocalHistoryTouchViewportBeforeBackend(
                    stableTargetKey,
                    where,
                    boundedRepeats,
                    Math.max(1, activeHistoryScrollRequestSerial),
                    "touch-scroll-in-flight"
            );
            if (suppressLocalHistoryPrefetch) {
                return;
            }
            prefetchLocalHistoryForTouchScroll(
                    stableTargetKey,
                    where,
                    boundedRepeats,
                    Math.max(1, activeHistoryScrollRequestSerial)
            );
            if (where.equals(pendingHistoryScrollWhere)
                    && pendingHistoryScrollGeneration == gestureGeneration
                    && pendingHistoryScrollDirectionGeneration == directionGeneration
                    && pendingHistoryScrollTargetKey.equals(stableTargetKey)) {
                if (!fromMomentum && boundedRepeats <= HISTORY_DRAG_READING_MOVE_REPEATS) {
                    // WHY: APK-SCROLL-ONE-FINGER-DELAY-BOUNDARY-1537-A is the exact
                    // same-direction in-flight failure: a slow physical drag can keep
                    // moving while one `/touch-scroll` response is stuck behind backend
                    // or renderer work. Collapsing every same-direction sample back to
                    // one row made the phone look dead until the response returned. Keep
                    // only a tiny slow-read backlog, capped by the existing slow MOVE
                    // ceiling, so the next dispatch catches up with the finger without
                    // recreating the old delayed burst/page-scroll jump.
                    pendingHistoryScrollRepeats = Math.min(
                            HISTORY_DRAG_SLOW_MOVE_MAX_REPEATS,
                            pendingHistoryScrollRepeats + HISTORY_DRAG_READING_MOVE_REPEATS
                    );
                } else if ("lineDown".equals(where) || fromMomentum) {
                    // WHY: deliberate flick/momentum return toward live bottom still
                    // needs real acceleration. Accumulate only outside the slow-reading
                    // path and inside the existing per-request cap so this cannot
                    // replay an unbounded old gesture.
                    pendingHistoryScrollRepeats = Math.min(
                            maxRepeats,
                            pendingHistoryScrollRepeats + boundedRepeats
                    );
                } else if (boundedRepeats <= HISTORY_DRAG_SLOW_MOVE_MAX_REPEATS) {
                    // WHY: slow reading now uses the visual residual as the latency
                    // bridge. Queueing even a "small" upward burst while a frame is
                    // in flight was enough to make a tiny live-bottom drag replay
                    // rows after the finger barely moved. The earlier low-speed
                    // "finger moves but rows barely move" failure is handled by
                    // sub-line visual nudges and frame-paced repaint, not by
                    // accumulating slow pending rows.
                    pendingHistoryScrollRepeats = HISTORY_DRAG_READING_MOVE_REPEATS;
                } else {
                    // WHY: fast upward movement is a deliberate history flick, not
                    // slow reading. Keep bounded accumulation here so the latest
                    // fast-flick complaint does not regress into sluggish history
                    // movement while slow drags stay small above.
                    pendingHistoryScrollRepeats = Math.min(
                            maxRepeats,
                            pendingHistoryScrollRepeats + boundedRepeats
                    );
                }
            } else {
                pendingHistoryScrollWhere = where;
                pendingHistoryScrollRepeats = boundedRepeats;
                pendingHistoryScrollGeneration = gestureGeneration;
                pendingHistoryScrollDirectionGeneration = directionGeneration;
                pendingHistoryScrollTargetKey = stableTargetKey;
                syncCaptureRendererReadHold("touch-scroll-pending");
            }
            return;
        }
        sendHistoryScrollFromTouch(where, boundedRepeats, gestureGeneration, stableTargetKey, directionGeneration);
    }

    private void sendHistoryScrollFromTouch(String where, int repeats, long gestureGeneration, String targetKey, long directionGeneration) {
        long readModeGeneration = terminalHistoryViewportActive
                ? terminalModeGeneration
                : enterReadMode();
        historyScrollRequestInFlight = true;
        syncCaptureRendererReadHold("touch-scroll-dispatch");
        final long requestSerial = ++historyScrollRequestSerial;
        activeHistoryScrollRequestSerial = requestSerial;
        String path = appendStableWindowQuery("/touch-scroll?where=" + urlEncode(where)
                + "&repeat=" + Math.max(1, repeats), targetKey);
        boolean suppressLocalHistoryPrefetch = updateLocalHistoryTouchViewportBeforeBackend(
                targetKey,
                where,
                repeats,
                requestSerial,
                "touch-scroll-dispatch"
        );
        Log.i(CONTROL_LOG_TAG,
                "stage=touch-scroll-dispatch endpoint=/touch-scroll"
                        + " actionId=" + safeLogToken(activeTouchScrollActionId)
                        + " windowId=" + safeWindowIdForControlLog(targetKey)
                        + " where=" + safeLogToken(where)
                        + " repeats=" + Math.max(1, repeats)
                        + " gesture=" + gestureGeneration
                        + " direction=" + directionGeneration
                        + " tapDownAtMs=" + activeTouchScrollDownAtMs
                        + " firstLocalFeedbackAtMs=" + activeTouchScrollFirstLocalFeedbackAtMs
                        + " firstLocalFeedbackElapsedMs=" + touchScrollFirstLocalFeedbackElapsedMs()
                        + " feedbackKind=" + safeLogToken(activeTouchScrollFirstLocalFeedbackKind));
        if (!suppressLocalHistoryPrefetch) {
            prefetchLocalHistoryForTouchScroll(targetKey, where, repeats, requestSerial);
        }
        getJson(path, payload -> {
            if (requestSerial != activeHistoryScrollRequestSerial) {
                return;
            }
            historyScrollRequestInFlight = false;
            syncCaptureRendererReadHold("touch-scroll-response");
            boolean postReleaseCommitAllowed = shouldAcceptPostReleaseTouchScrollResponse(
                    gestureGeneration,
                    directionGeneration,
                    requestSerial,
                    targetKey,
                    where
            );
            Log.i(CONTROL_LOG_TAG,
                    "stage=touch-scroll-response endpoint=/touch-scroll"
                            + " actionId=" + safeLogToken(activeTouchScrollActionId)
                            + " windowId=" + safeWindowIdForControlLog(targetKey)
                            + " where=" + safeLogToken(where)
                            + " repeats=" + Math.max(1, repeats)
                            + " firstLocalFeedbackElapsedMs=" + touchScrollFirstLocalFeedbackElapsedMs()
                            + " atLiveBottom=" + payload.optBoolean("atLiveBottom", false)
                            + " atHistoryTop=" + payload.optBoolean("atHistoryTop", false)
                            + " scrollPosition=" + payload.optInt("scrollPosition", -1)
                            + " historySize=" + payload.optInt("historySize", -1)
                            + " paneMode=" + safeLogToken(payload.optString("paneMode", "")));
            if (gestureGeneration != terminalTouchGestureGeneration && !postReleaseCommitAllowed) {
                // WHY: delayed `/scroll` responses are expected on a mobile network.
                // They may still be valid tmux commands, but they no longer describe
                // the user's current finger gesture. Do not let them mark live-bottom
                // or keep the terminal in read mode for a newer touch/zoom/tap.
                drainPendingHistoryScroll();
                return;
            }
            if (directionGeneration != terminalHistoryDragDirectionGeneration && !postReleaseCommitAllowed) {
                // WHY: the user can reverse direction while the prior `/touch-scroll`
                // response is still in flight. That old response may be a valid tmux
                // command, but it must not repaint/refresh the phone as if it were
                // the current slow-reading direction.
                drainPendingHistoryScroll();
                return;
            }
            if (!touchScrollPayloadTargetsVisibleSurface(payload, targetKey)) {
                // WHY: `/touch-scroll` can be tmux-correct while Android is visibly
                // on a native dialog, system shade, or stale capture body. Do not let
                // a response-owned renderer commit or top/bottom latch report success
                // unless the payload still names the same visible terminal owner.
                Log.i(CONTROL_LOG_TAG,
                        "stage=touch-scroll-response endpoint=/touch-scroll result=wrong-surface-rejected"
                                + " actionId=" + safeLogToken(activeTouchScrollActionId)
                                + " targetWindowId=" + safeWindowIdForControlLog(targetKey)
                                + " visibleWindowId=" + safeWindowIdForControlLog(confirmedVisibleTerminalTargetKey())
                                + " frameWindowId=" + safeWindowIdForControlLog(payload.optString("frameWindowId", ""))
                                + " windowId=" + safeWindowIdForControlLog(payload.optString("windowId", ""))
                                + " requestedWindowId=" + safeWindowIdForControlLog(payload.optString("requestedWindowId", ""))
                                + " displayWindowId=" + safeWindowIdForControlLog(payload.optString("displayWindowId", ""))
                                + " resolvedWindowId=" + safeWindowIdForControlLog(payload.optString("resolvedWindowId", ""))
                                + " replacementWindowId=" + safeWindowIdForControlLog(payload.optString("replacementWindowId", ""))
                                + " interactiveTargetWindowId=" + safeWindowIdForControlLog(payload.optString("interactiveTargetWindowId", ""))
                                + " acceptedTarget=" + captureRendererAcceptedWindowIdsContain(payload, targetKey)
                                + " acceptedVisible=" + captureRendererAcceptedWindowIdsContain(payload, confirmedVisibleTerminalTargetKey())
                                + " where=" + safeLogToken(where)
                                + " repeats=" + Math.max(1, repeats));
                drainPendingHistoryScroll();
                return;
            }
            boolean exactLiveBottom = touchScrollReachedLiveBottom(payload);
            boolean releaseOnlyNearBottom = !terminalHistoryDragActive && isNearTmuxLiveBottom(payload);
            if ("lineDown".equals(where) && (exactLiveBottom || releaseOnlyNearBottom)) {
                // WHY: the server has reached tmux's real live bottom. During
                // ACTION_MOVE this must remain a stop signal, not a live-typing
                // restore, or the screen flips to the prompt before the user's
                // finger has finished scrolling down. Clear queued down-scrolls
                // and keep read-mode until ACTION_UP performs one explicit bottom
                // restore. v1.60 proved a fast physical return swipe could land a
                // a short bottom band and strand the phone in copy-mode, so
                // the tiny near-bottom band is now release-only. Treating
                // `scroll_position <= 3` as live bottom while the finger was still
                // down created the invisible floor a few rows above the prompt.
                terminalTouchReachedLiveBottom = true;
                cancelHistoryMomentum("backend-live-bottom");
                clearPendingHistoryScroll();
                if (!terminalHistoryDragActive) {
                    scheduleTouchLiveBottomReconcile("touch-scroll-release-lineDown");
                    return;
                }
                if (readModeGeneration == terminalModeGeneration) {
                    keepReadModeIfCurrent(readModeGeneration);
                }
                if (terminalHistoryDragActive) {
                    if (localHistoryTouchViewportOwnsVisibleSurfaceForNudge()) {
                        // WHY: cached local-history is the visible drag owner while
                        // the finger is down. Letting the backend `/touch-scroll`
                        // response also commit the live capture renderer repaints
                        // the prompt/live-bottom over the cached rows, which is the
                        // visible "history, bottom, history again" loop. The backend
                        // response still reconciles tmux state and drains pending
                        // work; it just must not repaint over the cache-owned
                        // surface during active direct manipulation.
                        Log.i(CONTROL_LOG_TAG,
                                "stage=touch-scroll-response endpoint=/touch-scroll"
                                        + " result=preserved-local-history-owner-at-bottom-edge"
                                        + " actionId=" + safeLogToken(activeTouchScrollActionId)
                                        + " windowId=" + safeWindowIdForControlLog(targetKey)
                                        + " where=" + safeLogToken(where)
                                        + " repeats=" + Math.max(1, repeats)
                                        + " localViewportOffset=" + localHistoryTouchViewportOffset
                                        + " localHistoryCachedRows=" + localHistoryTouchViewportRows.size());
                        drainPendingHistoryScroll();
                        return;
                    }
                    refreshCaptureRendererTouchEdge("touch-scroll-bottom-edge");
                    drainPendingHistoryScroll();
                    return;
                }
                refreshCaptureRendererSoon("touch-scroll-bottom-edge");
                return;
            }
            if ("lineUp".equals(where) && touchScrollReachedHistoryTop(payload)) {
                // WHY: tmux reports the history top when scroll_position reaches
                // history_size. Stop queueing lineUp at that boundary; otherwise
                // the APK keeps sending requests that cannot move and feels like
                // it hangs at the range limit until old responses drain.
                terminalTouchReachedHistoryTop = true;
                cancelHistoryMomentum("backend-history-top");
                clearPendingHistoryScroll();
                if (readModeGeneration == terminalModeGeneration) {
                    keepReadModeIfCurrent(readModeGeneration);
                }
                if (terminalHistoryDragActive) {
                    if (localHistoryTouchViewportOwnsVisibleSurfaceForNudge()) {
                        // WHY: same one-visible-owner rule as the normal response
                        // path. A true top edge can update latches, but it cannot
                        // repaint the live capture frame over cache-owned history
                        // while the user's finger is still down.
                        Log.i(CONTROL_LOG_TAG,
                                "stage=touch-scroll-response endpoint=/touch-scroll"
                                        + " result=preserved-local-history-owner-at-top-edge"
                                        + " actionId=" + safeLogToken(activeTouchScrollActionId)
                                        + " windowId=" + safeWindowIdForControlLog(targetKey)
                                        + " where=" + safeLogToken(where)
                                        + " repeats=" + Math.max(1, repeats)
                                        + " localViewportOffset=" + localHistoryTouchViewportOffset
                                        + " localHistoryCachedRows=" + localHistoryTouchViewportRows.size());
                        drainPendingHistoryScroll();
                        return;
                    }
                    refreshCaptureRendererTouchEdge("touch-scroll-top-edge");
                    return;
                }
                refreshCaptureRendererSoon("touch-scroll-top-edge");
                return;
            }
            if (readModeGeneration == terminalModeGeneration) {
                keepReadModeIfCurrent(readModeGeneration);
            }
            if (terminalHistoryDragActive) {
                if (localHistoryTouchViewportOwnsVisibleSurfaceForNudge()) {
                    // WHY: old-good drag behavior used the capture renderer nudge
                    // as the finger-down visual owner. The local-history cache keeps
                    // that same direct-manipulation contract by owning the visible
                    // rows locally; the backend response is state reconciliation
                    // only until release. Do not let it repaint the live capture
                    // surface over cached scrollback.
                    Log.i(CONTROL_LOG_TAG,
                            "stage=touch-scroll-response endpoint=/touch-scroll"
                                    + " result=preserved-local-history-owner"
                                    + " actionId=" + safeLogToken(activeTouchScrollActionId)
                                    + " windowId=" + safeWindowIdForControlLog(targetKey)
                                    + " where=" + safeLogToken(where)
                                    + " repeats=" + Math.max(1, repeats)
                                    + " localViewportOffset=" + localHistoryTouchViewportOffset
                                    + " localHistoryCachedRows=" + localHistoryTouchViewportRows.size());
                    drainPendingHistoryScroll();
                    return;
                }
                // WHY: while the finger is down, the capture renderer's transform
                // is the visible scroll. Committing every `/terminal-frame` row as
                // soon as tmux replies makes the phone move in row steps and makes
                // direction reversals feel like stale commands are draining.
                // A current `/touch-scroll` response is different from a blind pulse:
                // tmux has accepted same-gesture row movement, and the renderer still
                // enforces its same-direction stale-frame gate. Request one response-owned
                // commit so the visual residual does not hit its cap and load rows in chunks.
                refreshCaptureRendererTouchCommit("touch-scroll-response");
                drainPendingHistoryScroll();
                return;
            }
            if (postReleaseCommitAllowed) {
                // WHY: ACTION_UP still cancels momentum and stale queued commands, but
                // a fast down flick can have one already-dispatched same-gesture tmux
                // `lineDown` response return after finger-up. Dropping that proven row
                // commit leaves the renderer latched above the real prompt and feels
                // like an invisible bottom boundary. Paint this one response through
                // the renderer's release-held stale-frame gate; do not issue any new
                // post-release scroll work.
                if (readModeGeneration == terminalModeGeneration) {
                    keepReadModeIfCurrent(readModeGeneration);
                }
                refreshCaptureRendererTouchReleaseCommit("touch-scroll-release-response");
                clearPostReleaseTouchScrollCommit();
                return;
            }
            refreshCaptureRendererSoon("touch-scroll");
            keepCaptureRendererPulsingDuringTouch("touch-scroll-response");
            drainPendingHistoryScroll();
        }, exc -> {
            if (requestSerial != activeHistoryScrollRequestSerial) {
                return;
            }
            historyScrollRequestInFlight = false;
            syncCaptureRendererReadHold("touch-scroll-error");
            clearPostReleaseTouchScrollCommit();
            toast("Mantis Control is not reachable");
            drainPendingHistoryScroll();
        });
    }

    private boolean touchScrollReachedLiveBottom(JSONObject payload) {
        // WHY: APK-SCROLL-ONE-FINGER-DELAY-BOUNDARY-1537-A must not let Android
        // viewport geometry, title refresh, Send/Stop state, or delayed renderer
        // settlement decide a scroll boundary. Only tmux `/touch-scroll` metadata
        // can close the live-bottom/top latches; broad client-side clamps recreated
        // the delayed "nothing happens, then it hits an invisible boundary" failure.
        if (payload == null) {
            return false;
        }
        return (payload.optBoolean("atLiveBottom", false)
                && "tmux".equals(payload.optString("layer", ""))
                && "tmux-linedown".equals(payload.optString("action", "")))
                || isAtTmuxLiveBottom(payload);
    }

    private boolean touchScrollPayloadTargetsVisibleSurface(JSONObject payload, String targetKey) {
        if (payload == null || !hasStableWindowId(targetKey)) {
            return false;
        }
        String stableTargetKey = targetKey.trim();
        String visibleWindowId = confirmedVisibleTerminalTargetKey();
        if (!hasStableWindowId(visibleWindowId)) {
            visibleWindowId = visibleTerminalTargetKey();
        }
        String stableVisibleWindowId = hasStableWindowId(visibleWindowId)
                ? visibleWindowId.trim()
                : "";
        boolean sameVisibleTarget = stableTargetKey.equals(stableVisibleWindowId);
        if (sameVisibleTarget && targetHasUsableAcceptedBodyFrame(stableTargetKey)) {
            return true;
        }
        if (!touchScrollPayloadNamesWindow(payload, stableTargetKey)) {
            return false;
        }
        if (stableVisibleWindowId.isEmpty()) {
            return true;
        }
        if (sameVisibleTarget) {
            return true;
        }
        if (captureRendererAcceptedWindowIdsPresent(payload)) {
            return captureRendererAcceptedWindowIdsContain(payload, stableTargetKey)
                    && captureRendererAcceptedWindowIdsContain(payload, stableVisibleWindowId);
        }
        String displayWindowId = stableWindowIdFromPayload(
                payload,
                "",
                "displayWindowId",
                "requestedWindowId",
                "selectedWindowId"
        );
        String requestedWindowId = stableWindowIdFromPayload(
                payload,
                "",
                "requestedWindowId",
                "displayWindowId",
                "selectedWindowId"
        );
        String resolvedWindowId = stableWindowIdFromPayload(
                payload,
                "",
                "frameWindowId",
                "resolvedWindowId",
                "replacementWindowId",
                "interactiveTargetWindowId",
                "targetWindowId",
                "windowId"
        );
        boolean metadataLinksVisible = stableVisibleWindowId.equals(displayWindowId)
                || stableVisibleWindowId.equals(requestedWindowId);
        boolean targetMatchesResolved = stableTargetKey.equals(resolvedWindowId);
        boolean retargeted = payload.optBoolean("retargeted", false)
                || hasStableWindowId(payload.optString("replacementWindowId", ""))
                || hasStableWindowId(payload.optString("interactiveTargetWindowId", ""))
                || hasStableWindowId(payload.optString("resolvedWindowId", ""));
        return retargeted && metadataLinksVisible && targetMatchesResolved;
    }

    private boolean touchScrollPayloadNamesWindow(JSONObject payload, String windowId) {
        if (payload == null || !hasStableWindowId(windowId)) {
            return false;
        }
        String stableWindowId = windowId.trim();
        String[] keys = new String[] {
                "windowId",
                "targetWindowId",
                "interactiveTargetWindowId",
                "resolvedWindowId",
                "replacementWindowId",
                "frameWindowId",
                "requestedWindowId",
                "displayWindowId",
                "selectedWindowId"
        };
        for (String key : keys) {
            if (stableWindowId.equals(stableWindowIdFromText(payload.optString(key, "")))) {
                return true;
            }
        }
        return captureRendererAcceptedWindowIdsContain(payload, stableWindowId);
    }

    private boolean isAtTmuxLiveBottom(JSONObject payload) {
        if (payload == null
                || !"tmux".equals(payload.optString("layer", ""))
                || !"tmux-linedown".equals(payload.optString("action", ""))) {
            return false;
        }
        if (!payload.has("scrollPosition")) {
            return false;
        }
        int scrollPosition = payload.optInt("scrollPosition", Integer.MAX_VALUE);
        return scrollPosition == 0;
    }

    private boolean isNearTmuxLiveBottom(JSONObject payload) {
        if (payload == null
                || !"tmux".equals(payload.optString("layer", ""))
                || !"tmux-linedown".equals(payload.optString("action", ""))) {
            return false;
        }
        if (!payload.has("scrollPosition")) {
            return false;
        }
        int scrollPosition = payload.optInt("scrollPosition", Integer.MAX_VALUE);
        return scrollPosition >= 0 && scrollPosition <= TOUCH_SCROLL_LIVE_BOTTOM_SNAP_LINES;
    }

    private boolean touchScrollReachedHistoryTop(JSONObject payload) {
        if (payload == null
                || !"tmux".equals(payload.optString("layer", ""))
                || !"tmux-lineup".equals(payload.optString("action", ""))) {
            return false;
        }
        if (!payload.has("scrollPosition") || !payload.has("historySize")) {
            return false;
        }
        int scrollPosition = payload.optInt("scrollPosition", -1);
        int historySize = payload.optInt("historySize", -1);
        return historySize > 0 && scrollPosition >= historySize;
    }

    private void drainPendingHistoryScroll() {
        if (pendingHistoryScrollWhere.isEmpty()
                || historyScrollRequestInFlight
                || !terminalHistoryViewportActive
                || !readModeSuppressesKeyboard) {
            return;
        }
        String nextWhere = pendingHistoryScrollWhere;
        int nextRepeats = pendingHistoryScrollRepeats;
        long nextGeneration = pendingHistoryScrollGeneration;
        long nextDirectionGeneration = pendingHistoryScrollDirectionGeneration;
        String nextTargetKey = pendingHistoryScrollTargetKey;
        clearPendingHistoryScroll();
        if (nextGeneration != terminalTouchGestureGeneration
                || nextDirectionGeneration != terminalHistoryDragDirectionGeneration) {
            return;
        }
        sendHistoryScrollFromTouch(nextWhere, Math.max(1, nextRepeats), nextGeneration, nextTargetKey, nextDirectionGeneration);
    }

    private void keepCaptureRendererPulsingDuringTouch(String reason) {
        if (webView == null || Build.VERSION.SDK_INT < Build.VERSION_CODES.KITKAT) {
            return;
        }
        // WHY: the phone-visible terminal is a read-only capture renderer. Tmux can
        // scroll smoothly on the laptop while the APK looks choppy if the renderer
        // waits for the 550 ms poll or a single delayed refresh. Keep `/touch-scroll` itself lightweight,
        // but run a frame-rate bounded repaint loop during an
        // active finger gesture so slow drags show intermediate rows and fast
        // movement still accelerates while the finger is physically down. Do not
        // use this pulse train as permission for slow-drag post-release inertia;
        // only the explicit quick-flick release gate may start bounded momentum.
        long now = System.currentTimeMillis();
        touchScrollRenderPulseUntilMs = Math.max(
                touchScrollRenderPulseUntilMs,
                now + TOUCH_SCROLL_RENDER_PULSE_WINDOW_MS
        );
        if (touchScrollRenderPulseScheduled) {
            return;
        }
        touchScrollRenderPulseScheduled = true;
        postCaptureRendererPulseFrame(reason);
    }

    private void prepareTerminalSnapshotOffMainThread(
            JSONObject framePayload,
            JSONArray readyBatches,
            String reason
    ) {
        if (framePayload == null || webView == null
                || Build.VERSION.SDK_INT < Build.VERSION_CODES.KITKAT) {
            return;
        }
        final long prepareSerial = ++terminalSnapshotPrepareSerial;
        final JSONObject immutableFramePayload = framePayload;
        final JSONArray immutableReadyBatches = readyBatches;
        new Thread(() -> {
            try {
                JSONArray rows = immutableFramePayload.optJSONArray("rows");
                if (rows == null || rows.length() == 0) {
                    return;
                }
                String windowId = immutableFramePayload.optString(
                        "frameWindowId",
                        immutableFramePayload.optString("windowId", "")
                ).trim();
                String generationKey =
                        immutableFramePayload.optString("generationKey", "").trim();
                if (!hasStableWindowId(windowId) || generationKey.isEmpty()) {
                    return;
                }
                JSONArray htmlRows = immutableFramePayload.optJSONArray("rowsHtml");
                JSONArray rowKeys = immutableFramePayload.optJSONArray("rowKeys");
                JSONArray copiedRows = new JSONArray(rows.toString());
                JSONArray copiedHtmlRows = htmlRows == null
                        ? new JSONArray()
                        : new JSONArray(htmlRows.toString());
                JSONArray copiedRowKeys = rowKeys == null
                        ? new JSONArray()
                        : new JSONArray(rowKeys.toString());
                while (copiedRowKeys.length() < copiedRows.length()) {
                    copiedRowKeys.put(
                            "snapshot:" + windowId + ":" + generationKey
                                    + ":" + copiedRowKeys.length()
                    );
                }
                StringBuilder plainRows = new StringBuilder();
                StringBuilder rendered = new StringBuilder();
                for (int index = 0; index < copiedRows.length(); index++) {
                    if (index > 0) {
                        plainRows.append('\n');
                        rendered.append('\n');
                    }
                    plainRows.append(copiedRows.optString(index, ""));
                    rendered.append(copiedHtmlRows.length() > index
                            ? copiedHtmlRows.optString(index, "")
                            : copiedRows.optString(index, ""));
                }
                if (plainRows.toString().trim().isEmpty()) {
                    return;
                }
                int cols = immutableFramePayload.optInt(
                        "requestedCols",
                        immutableFramePayload.optInt(
                                "renderCols",
                                Math.max(20, lastAcceptedCaptureRendererCols)
                        )
                );
                int frameRows = immutableFramePayload.optInt(
                        "requestedRows",
                        copiedRows.length()
                );
                JSONObject frameGeometry = new JSONObject();
                frameGeometry.put("rows", Math.max(1, frameRows));
                frameGeometry.put("cols", Math.max(20, cols));
                JSONObject snapshot = new JSONObject();
                snapshot.put("windowId", windowId);
                snapshot.put("generationKey", generationKey);
                snapshot.put("plainRows", plainRows.toString());
                snapshot.put("rendered", rendered.toString());
                snapshot.put("htmlRows", copiedHtmlRows);
                snapshot.put("rowKeys", copiedRowKeys);
                snapshot.put("frameGeometry", frameGeometry);
                snapshot.put("frameHash", immutableFramePayload.optString("frameHash",
                        immutableFramePayload.optString("hash", "")));
                snapshot.put("historySize", immutableFramePayload.optInt("historySize", -1));
                snapshot.put("liveRowFrontier",
                        immutableFramePayload.optInt("liveRowFrontier", -1));
                snapshot.put("scrollPosition",
                        immutableFramePayload.optInt("scrollPosition", -1));
                snapshot.put("readyBatches", immutableReadyBatches == null
                        ? new JSONArray()
                        : new JSONArray(immutableReadyBatches.toString()));
                snapshot.put("sequence", prepareSerial);
                String snapshotJson = snapshot.toString();
                String frameHash = snapshot.optString("frameHash", "");
                int rowCount = copiedRows.length();
                uiHandler.post(() -> {
                    if (webView == null || !activityResumed) {
                        return;
                    }
                    webView.evaluateJavascript(
                            "(function(){try{var r=window.__mantisCaptureRenderer;"
                                    + "if(r&&typeof r.prepareTerminalSnapshot==='function'){"
                                    + "return r.prepareTerminalSnapshot(" + snapshotJson + ");}"
                                    + "return {status:'RENDERER_MISSING'};"
                                    + "}catch(e){return {status:'RENDERER_ERROR',error:String(e&&e.message||e)};}})()",
                            value -> {
                                JSONObject result = parseJavascriptObjectResult(value);
                                if (result == null
                                        || !"PREPARED".equals(
                                        result.optString("status", ""))) {
                                    return;
                                }
                                TerminalSnapshot prepared = new TerminalSnapshot(
                                        windowId,
                                        generationKey,
                                        result.optString("geometryKey", ""),
                                        frameHash,
                                        SystemClock.elapsedRealtime(),
                                        rowCount
                                );
                                rememberPreparedTerminalSnapshot(prepared);
                                Log.i(CONTROL_LOG_TAG,
                                        "stage=terminal-snapshot endpoint=renderer"
                                                + " result=prepared"
                                                + " windowId="
                                                + safeWindowIdForControlLog(windowId)
                                                + " generationKey="
                                                + safeLogToken(generationKey)
                                                + " geometryKey="
                                                + safeLogToken(prepared.geometryKey)
                                                + " rowCount=" + rowCount
                                                + " reason=" + safeLogToken(reason));
                            }
                    );
                });
            } catch (Exception exc) {
                Log.i(CONTROL_LOG_TAG,
                        "stage=terminal-snapshot endpoint=prepare result=rejected"
                                + " reason=" + safeLogToken(reason)
                                + " error=" + safeLogToken(
                                exc.getClass().getSimpleName()));
            }
        }, "terminal-snapshot-prepare").start();
    }

    private void rememberPreparedTerminalSnapshot(TerminalSnapshot snapshot) {
        if (snapshot == null
                || !hasStableWindowId(snapshot.windowId)
                || snapshot.generationKey.isEmpty()
                || snapshot.geometryKey.isEmpty()
                || snapshot.rowCount <= 0) {
            return;
        }
        terminalSnapshotCache.remove(snapshot.key());
        terminalSnapshotCache.put(snapshot.key(), snapshot);
        terminalSnapshotByOwner.put(snapshot.ownerKey(), snapshot);
        latestTerminalSnapshotByWindow.put(snapshot.windowId, snapshot);
        while (terminalSnapshotCache.size() > TERMINAL_SNAPSHOT_CACHE_MAX_ENTRIES) {
            String oldestKey = terminalSnapshotCache.keySet().iterator().next();
            TerminalSnapshot removed = terminalSnapshotCache.remove(oldestKey);
            if (removed == null) {
                continue;
            }
            if (terminalSnapshotByOwner.get(removed.ownerKey()) == removed) {
                terminalSnapshotByOwner.remove(removed.ownerKey());
            }
            if (latestTerminalSnapshotByWindow.get(removed.windowId) == removed) {
                latestTerminalSnapshotByWindow.remove(removed.windowId);
            }
        }
    }

    private boolean beginCaptureRendererGestureViewportOwner() {
        String windowId = terminalTouchStableWindowId == null
                ? ""
                : terminalTouchStableWindowId.trim();
        String actionId = activeTouchScrollActionId == null
                ? ""
                : activeTouchScrollActionId.trim();
        if (webView == null
                || Build.VERSION.SDK_INT < Build.VERSION_CODES.KITKAT
                || !hasStableWindowId(windowId)
                || actionId.isEmpty()) {
            return false;
        }
        long serial = ++captureRendererGestureViewportOwnerSerial;
        String identityJson = "{\"windowId\":" + JSONObject.quote(windowId)
                + ",\"actionId\":" + JSONObject.quote(actionId)
                + ",\"serial\":" + serial + "}";
        webView.evaluateJavascript(
                "(function(){try{"
                        + "var identity=" + identityJson + ";"
                        + "var r=window.__mantisCaptureRenderer;"
                        + "if(!r||typeof r.state!=='function'||typeof r.nudgeTouchScroll!=='function'||typeof r.prependReadyHistoryAtBoundary!=='function'){return {status:'RENDERER_MISSING'};}"
                        + "var before=r.state();"
                        + "if(String(before&&before.windowId||'')!==identity.windowId){return {status:'REJECTED_WINDOW',rendererWindowId:String(before&&before.windowId||'')};}"
                        // WHY: the 10.5s /scrollback/chunk response observed in v235
                        // cannot own finger motion. Consume only immutable READY
                        // intervals already inside this renderer, using its public
                        // COMMITTED result as the handoff authority. The fixed bound
                        // prevents ACTION_DOWN from becoming an unbounded DOM loop.
                        + "var precommittedSeams=0,commitStatuses=[];"
                        + "while(precommittedSeams<"
                        + TOUCH_SCROLL_READY_SEAM_PRECOMMIT_LIMIT + "){"
                        + "var staged=r.state();"
                        + "if((Number(staged&&staged.readyHistoryBatches)||0)<=0){break;}"
                        + "var committed=r.prependReadyHistoryAtBoundary('up',0,0,true);"
                        + "var commitStatus=String(committed&&committed.status||'UNKNOWN');"
                        + "commitStatuses.push(commitStatus);"
                        + "if(commitStatus!=='COMMITTED'){break;}"
                        + "precommittedSeams++;"
                        + "}"
                        + "function visibleAnchors(){"
                        + "var buffer=document.querySelector('#screen[data-active=\"1\"],#screenNext[data-active=\"1\"]');"
                        + "var rows=buffer?Array.prototype.slice.call(buffer.querySelectorAll('.captureRenderRow,.readyHistoryRow')):[];"
                        + "var vv=window.visualViewport;"
                        + "var top=vv?Number(vv.offsetTop)||0:0;"
                        + "var height=vv?Number(vv.height)||0:Number(window.innerHeight)||0;"
                        + "var bottom=top+height;"
                        + "var first=null,last=null,firstIndex=-1,lastIndex=-1;"
                        + "for(var i=0;i<rows.length;i++){var rect=rows[i].getBoundingClientRect();if(rect.bottom>top&&rect.top<bottom){if(!first){first=rows[i];firstIndex=i;}last=rows[i];lastIndex=i;}}"
                        + "return {buffer:buffer,rows:rows,firstVisibleRowKey:String(first&&first.dataset&&first.dataset.renderRowKey||''),lastVisibleRowKey:String(last&&last.dataset&&last.dataset.renderRowKey||''),firstIndex:firstIndex,lastIndex:lastIndex};"
                        + "}"
                        + "var anchors=visibleAnchors();"
                        + "if(!anchors.buffer||!anchors.firstVisibleRowKey||!anchors.lastVisibleRowKey){return {status:'VISIBLE_ANCHORS_MISSING',precommittedSeams:precommittedSeams,commitStatuses:commitStatuses};}"
                        + "window.__weztermCanonicalGestureViewportOwner={"
                        + "active:true,actionId:identity.actionId,windowId:identity.windowId,leaseSerial:identity.serial,"
                        + "buffer:anchors.buffer,"
                        + "baselineFirstVisibleRowKey:anchors.firstVisibleRowKey,baselineLastVisibleRowKey:anchors.lastVisibleRowKey,"
                        + "lastFirstVisibleRowKey:anchors.firstVisibleRowKey,lastLastVisibleRowKey:anchors.lastVisibleRowKey,"
                        + "firstAnchorRowDisplacement:0,lastAnchorRowDisplacement:0,visibleDistinctRowDisplacement:0,"
                        + "cumulativeAppliedPx:0,heldAfterRelease:false,acquiredAt:Date.now(),"
                        + "precommittedSeams:precommittedSeams,commitStatuses:commitStatuses};"
                        + "window.__weztermTouchScrollTraversal=null;"
                        + "return {status:'ACQUIRED',touchActionId:identity.actionId,leaseSerial:identity.serial,baselineFirstVisibleRowKey:anchors.firstVisibleRowKey,baselineLastVisibleRowKey:anchors.lastVisibleRowKey,precommittedSeams:precommittedSeams,commitStatuses:commitStatuses,readyHistoryBatchesBefore:Number(before&&before.readyHistoryBatches)||0,readyHistoryBatchesAfter:Number(r.state().readyHistoryBatches)||0};"
                        + "}catch(e){return {status:'RENDERER_ERROR',error:String(e&&e.message||e)};}})()",
                value -> {
                    if (captureRendererGestureViewportOwnerLeaseSerial
                            != serial) {
                        return;
                    }
                    JSONObject result = parseJavascriptObjectResult(value);
                    String status = result == null
                            ? "UNPARSEABLE_RESULT"
                            : result.optString("status", "UNKNOWN");
                    if (!"ACQUIRED".equals(status)) {
                        captureRendererGestureViewportOwnerQueued = false;
                        captureRendererGestureViewportOwnerActionId = "";
                        captureRendererGestureViewportOwnerWindowId = "";
                        captureRendererGestureViewportOwnerLeaseSerial = 0;
                        captureRendererHistoryMovementBlocked = true;
                    } else {
                        captureRendererHistoryMovementBlocked = false;
                        captureRendererGestureViewportRefillRequested = false;
                    }
                    Log.i(CONTROL_LOG_TAG,
                            "stage=gesture-viewport-owner endpoint=renderer"
                                    + " result=" + safeLogToken(status)
                                    + " actionId=" + safeLogToken(actionId)
                                    + " windowId="
                                    + safeWindowIdForControlLog(windowId)
                                    + " serial=" + serial
                                    + " precommittedSeams="
                                    + (result == null
                                    ? 0
                                    : result.optInt("precommittedSeams", 0))
                                    + " readyHistoryBatchesBefore="
                                    + (result == null
                                    ? 0
                                    : result.optInt(
                                            "readyHistoryBatchesBefore",
                                            0))
                                    + " readyHistoryBatchesAfter="
                                    + (result == null
                                    ? 0
                                    : result.optInt(
                                            "readyHistoryBatchesAfter",
                                            0)));
                }
        );
        return true;
    }

    private boolean beginTerminalSnapshotLease() {
        String windowId = terminalTouchStableWindowId == null
                ? ""
                : terminalTouchStableWindowId.trim();
        String generationKey = localHistoryTouchViewportGenerationKey == null
                ? ""
                : localHistoryTouchViewportGenerationKey.trim();
        if (!hasStableWindowId(windowId)) {
            return false;
        }
        TerminalSnapshot snapshot = generationKey.isEmpty()
                ? latestTerminalSnapshotByWindow.get(windowId)
                : terminalSnapshotByOwner.get(windowId + "|" + generationKey);
        if (snapshot == null
                || SystemClock.elapsedRealtime() - snapshot.preparedAtMs
                > ACTIVE_SWITCH_SELECTED_BODY_CACHE_MAX_AGE_MS) {
            return false;
        }
        long serial = ++terminalSnapshotLeaseSerial;
        TerminalSnapshotLease lease = new TerminalSnapshotLease(
                serial,
                activeTouchScrollActionId,
                snapshot
        );
        terminalSnapshotLease = lease;
        latestQueuedFrame = null;
        String identityJson = "{\"windowId\":" + JSONObject.quote(lease.windowId)
                + ",\"generationKey\":" + JSONObject.quote(lease.generationKey)
                + ",\"geometryKey\":" + JSONObject.quote(lease.geometryKey)
                + ",\"serial\":" + lease.serial
                + ",\"actionId\":" + JSONObject.quote(lease.actionId) + "}";
        webView.evaluateJavascript(
                "(function(){try{"
                        + "var identity=" + identityJson + ";"
                        + "var r=window.__mantisCaptureRenderer;"
                        + "if(!r||typeof r.activateTerminalSnapshot!=='function'||typeof r.beginTerminalSnapshotLease!=='function'){return {status:'RENDERER_MISSING'};}"
                        + "var activation=r.activateTerminalSnapshot(identity);"
                        + "if(!activation||activation.status!=='ACTIVATED'){return {status:'ACTIVATION_REJECTED',activationStatus:String(activation&&activation.status||'UNKNOWN')};}"
                        + "var acquired=r.beginTerminalSnapshotLease(identity);"
                        + "if(!acquired||acquired.status!=='ACQUIRED'){return Object.assign({activationStatus:'ACTIVATED'},acquired||{status:'LEASE_REJECTED'});}"
                        + "function visibleAnchors(){"
                        + "var buffer=document.querySelector('#screen[data-active=\"1\"],#screenNext[data-active=\"1\"]');"
                        + "var rows=buffer?Array.prototype.slice.call(buffer.querySelectorAll('.captureRenderRow,.readyHistoryRow')):[];"
                        + "var vv=window.visualViewport;"
                        + "var top=vv?Number(vv.offsetTop)||0:0;"
                        + "var height=vv?Number(vv.height)||0:Number(window.innerHeight)||0;"
                        + "var bottom=top+height;"
                        + "var first=null,last=null,firstIndex=-1,lastIndex=-1;"
                        + "for(var i=0;i<rows.length;i++){var rect=rows[i].getBoundingClientRect();if(rect.bottom>top&&rect.top<bottom){if(!first){first=rows[i];firstIndex=i;}last=rows[i];lastIndex=i;}}"
                        + "return {buffer:buffer,rows:rows,firstVisibleRowKey:String(first&&first.dataset&&first.dataset.renderRowKey||''),lastVisibleRowKey:String(last&&last.dataset&&last.dataset.renderRowKey||''),firstIndex:firstIndex,lastIndex:lastIndex};"
                        + "}"
                        + "var anchors=visibleAnchors();"
                        + "if(!anchors.buffer||!anchors.firstVisibleRowKey||!anchors.lastVisibleRowKey){return {status:'VISIBLE_ANCHORS_MISSING',activationStatus:'ACTIVATED'};}"
                        + "window.__weztermCanonicalGestureViewportOwner={"
                        + "active:true,actionId:identity.actionId,windowId:identity.windowId,leaseSerial:identity.serial,"
                        + "buffer:anchors.buffer,"
                        + "baselineFirstVisibleRowKey:anchors.firstVisibleRowKey,baselineLastVisibleRowKey:anchors.lastVisibleRowKey,"
                        + "lastFirstVisibleRowKey:anchors.firstVisibleRowKey,lastLastVisibleRowKey:anchors.lastVisibleRowKey,"
                        + "firstAnchorRowDisplacement:0,lastAnchorRowDisplacement:0,visibleDistinctRowDisplacement:0,"
                        + "cumulativeAppliedPx:0,heldAfterRelease:false,acquiredAt:Date.now()};"
                        + "window.__weztermTouchScrollTraversal=null;"
                        + "return Object.assign({activationStatus:'ACTIVATED',baselineFirstVisibleRowKey:anchors.firstVisibleRowKey,baselineLastVisibleRowKey:anchors.lastVisibleRowKey},acquired);"
                        + "}catch(e){return {status:'RENDERER_ERROR'};}})()",
                value -> {
                    if (!terminalSnapshotLeaseMatchesSerial(serial)) {
                        return;
                    }
                    JSONObject result = parseJavascriptObjectResult(value);
                    if (result == null
                            || !"ACQUIRED".equals(result.optString("status", ""))) {
                        terminalSnapshotLease = null;
                        latestQueuedFrame = null;
                        if (captureRendererGestureViewportOwnerLeaseSerial
                                == serial) {
                            captureRendererGestureViewportOwnerQueued = false;
                            captureRendererGestureViewportOwnerActionId = "";
                            captureRendererGestureViewportOwnerWindowId = "";
                            captureRendererGestureViewportOwnerLeaseSerial = 0;
                            captureRendererHistoryMovementBlocked = true;
                        }
                        syncCaptureRendererReadHold("terminal-snapshot-lease-rejected");
                        return;
                    }
                    lease.anchorKey = result.optString("anchorKey", "");
                    lease.viewportOffsetPx =
                            (float) result.optDouble("viewportOffsetPx", 0);
                    syncCaptureRendererReadHold("terminal-snapshot-lease-acquired");
                }
        );
        return true;
    }

    private boolean terminalSnapshotLeaseMatchesSerial(long expectedSerial) {
        return expectedSerial > 0
                && terminalSnapshotLease != null
                && terminalSnapshotLease.serial == expectedSerial
                && terminalSnapshotLeaseSerial == expectedSerial;
    }

    private boolean queueLatestTerminalSnapshotFrame(TerminalSnapshotFrame frame) {
        TerminalSnapshotLease lease = terminalSnapshotLease;
        if (lease == null
                || frame == null
                || !lease.windowId.equals(frame.windowId)
                || !lease.generationKey.equals(frame.generationKey)
                || !lease.geometryKey.equals(frame.geometryKey)
                || frame.plainRows.trim().isEmpty()
                || frame.htmlRows == null
                || frame.htmlRows.length() == 0
                || frame.rowKeys == null
                || frame.rowKeys.length() == 0
                || frame.frameGeometry == null
                || (latestQueuedFrame != null
                && frame.sequence <= latestQueuedFrame.sequence)) {
            return false;
        }
        latestQueuedFrame = frame;
        return true;
    }

    private boolean applyLatestQueuedTerminalSnapshotFrame(String reason) {
        // Renderer endTerminalSnapshotLease owns the one actual full-frame apply.
        // Java retains no terminal bytes after that typed transition.
        boolean hadLatestFullFrame = latestQueuedFrame != null;
        latestQueuedFrame = null;
        Log.i(CONTROL_LOG_TAG,
                "stage=terminal-snapshot endpoint=renderer"
                        + " result=reconcile-requested"
                        + " reason=" + safeLogToken(reason)
                        + " hadLatestFullFrame=" + hadLatestFullFrame);
        return hadLatestFullFrame;
    }

    private boolean endTerminalSnapshotLease(
            String reason,
            TerminalSnapshotEndMode mode
    ) {
        TerminalSnapshotLease lease = terminalSnapshotLease;
        if (lease == null) {
            return false;
        }
        boolean reconcile = mode == TerminalSnapshotEndMode.RECONCILE;
        if (reconcile) {
            applyLatestQueuedTerminalSnapshotFrame(reason);
        } else {
            latestQueuedFrame = null;
        }
        terminalSnapshotLease = null;
        String modeValue = reconcile ? "RECONCILE" : "ABORT";
        if (webView != null && Build.VERSION.SDK_INT >= Build.VERSION_CODES.KITKAT) {
            webView.evaluateJavascript(
                    "(function(){try{var r=window.__mantisCaptureRenderer;"
                            + "if(r&&typeof r.endTerminalSnapshotLease==='function'){"
                            + "return r.endTerminalSnapshotLease(" + lease.serial + ","
                            + JSONObject.quote(modeValue) + ","
                            + JSONObject.quote(reason) + ");}"
                            + "return {status:'RENDERER_MISSING'};"
                            + "}catch(e){return {status:'RENDERER_ERROR'};}})()",
                    null
            );
        }
        syncCaptureRendererReadHold("terminal-snapshot-lease-end-" + reason);
        return true;
    }

    private boolean paintTerminalSnapshotFromCache(String windowId) {
        String stableWindowId = hasStableWindowId(windowId)
                ? windowId.trim()
                : "";
        TerminalSnapshot snapshot =
                latestTerminalSnapshotByWindow.get(stableWindowId);
        if (snapshot == null
                || webView == null
                || Build.VERSION.SDK_INT < Build.VERSION_CODES.KITKAT
                || SystemClock.elapsedRealtime() - snapshot.preparedAtMs
                > ACTIVE_SWITCH_SELECTED_BODY_CACHE_MAX_AGE_MS) {
            return false;
        }
        String identityJson = "{\"windowId\":"
                + JSONObject.quote(snapshot.windowId)
                + ",\"generationKey\":" + JSONObject.quote(snapshot.generationKey)
                + ",\"geometryKey\":" + JSONObject.quote(snapshot.geometryKey)
                + "}";
        webView.evaluateJavascript(
                "(function(){try{var r=window.__mantisCaptureRenderer;"
                        + "if(r&&typeof r.activateTerminalSnapshot==='function'){"
                        + "var activation=r.activateTerminalSnapshot(" + identityJson + ");"
                        + "if(activation&&activation.status==='ACTIVATED'){"
                        + RESET_RENDERER_EPHEMERAL_SCROLL_OWNER_JS
                        + "}"
                        + "return activation;}"
                        + "return {status:'RENDERER_MISSING'};"
                        + "}catch(e){return {status:'RENDERER_ERROR'};}})()",
                value -> {
                    JSONObject result = parseJavascriptObjectResult(value);
                    if (result == null
                            || !"ACTIVATED".equals(result.optString("status", ""))) {
                        return;
                    }
                    Log.i(CONTROL_LOG_TAG,
                            "stage=terminal-snapshot endpoint=renderer"
                                    + " result=terminal-snapshot-swapped"
                                    + " windowId="
                                    + safeWindowIdForControlLog(snapshot.windowId)
                                    + " generationKey="
                                    + safeLogToken(snapshot.generationKey)
                                    + " snapshotSwapElapsedMs="
                                    + result.optDouble("snapshotSwapElapsedMs", -1));
                }
        );
        return true;
    }

	    private void nudgeCaptureRendererForTouch(float deltaY, String visualWhere) {
	        if (webView == null || Build.VERSION.SDK_INT < Build.VERSION_CODES.KITKAT
	                || Math.abs(deltaY) < 0.5f) {
	            return;
	        }
	        // WHY: SCROLL DEEP-HISTORY 2026-07-26 — every visual scroll movement (drag
	        // sample and momentum pixel) funnels through here. Stamp gesture activity so
	        // the resulting staged/scrolled frame commits through read-hold, and the
	        // settle window keeps the final resting frame from being dropped.
	        lastGestureScrollActivityAtMs = SystemClock.elapsedRealtime();
            String nudgeWhere = "lineUp".equals(visualWhere) || "lineDown".equals(visualWhere)
                    ? visualWhere
                    : (deltaY > 0f ? "lineUp" : "lineDown");
        if (captureRendererPointerTouchForwarding) {
            // WHY(v267 renderer pointer owner): the renderer receives this same
            // classified physical stream through WebView.onTouchEvent and applies
            // its existing O(1) nudge inside pointermove. Keep Java's residual for
            // release admission, but do not enqueue any per-MOVE JS or duplicate
            // local-history transform while that input owner is active.
            captureRendererTouchFingerNudgeResidualPx += deltaY;
            return;
        }
	        if (localHistoryTouchViewportOwnsVisibleSurfaceForNudge()) {
	            // WHY: once cached local-history rows own the viewport, both the live
	            // capture renderer nudge and the cached row-offset paint would move the
	            // same #screenStack. That double ownership reproduced as "normal scroll,
	            // then opposite direction at the transition." Do not drop the finger
                // delta, though: the cache-owned surface still needs a same-frame
                // transform on its active buffer, otherwise the first visible movement
                // is an async row paint and the scroll feels like a delayed jump.
	            pendingTouchVisualNudgePx = 0f;
                captureRendererTouchFingerNudgeResidualPx = 0f;
                nudgeLocalHistoryInlineForTouch(deltaY, nudgeWhere);
	            Log.i(CONTROL_LOG_TAG,
	                    "stage=touch-nudge endpoint=renderer"
	                            + " actionId=" + safeLogToken(activeTouchScrollActionId)
	                            + " deltaPx=" + touchLogFloat(deltaY)
                                + " where=" + safeLogToken(nudgeWhere)
	                            + " result=redirected-local-history-owner"
	                            + " windowId=" + safeWindowIdForControlLog(localHistoryTouchViewportWindowId)
	                            + " localViewportOffset=" + localHistoryTouchViewportOffset
	                            + " localHistoryCachedRows=" + localHistoryTouchViewportRows.size());
	            return;
	        }
	        // WHY: this does not change tmux scroll distance, ratio, or flick speed.
	        // It only moves the already-rendered capture layer by the physical finger
	        // delta for the current frame so the phone does not look frozen while the
	        // lightweight `/touch-scroll` command and `/terminal-frame` repaint catch up.
        // WHY: the bottom-to-cache handoff happens after a few pixel nudges have
        // already moved the live capture renderer. Keep the same residual in Java
        // so the first cached-history paint can inherit the finger anchor instead
        // of snapping to the prewarmed cache row boundary.
	        captureRendererTouchFingerNudgeResidualPx += deltaY;
	        pendingTouchVisualNudgePx += deltaY;
        scheduleCaptureRendererTouchNudgeIfNeeded();
    }

    private void scheduleCaptureRendererTouchNudgeIfNeeded() {
        if (webView == null
                || Build.VERSION.SDK_INT < Build.VERSION_CODES.KITKAT
                || Math.abs(pendingTouchVisualNudgePx) < 0.5f
                || touchScrollVisualNudgeScheduled
                || touchScrollVisualNudgeInFlight) {
            return;
        }
        TerminalSnapshotLease activeSnapshotLease = terminalSnapshotLease;
        long expectedLeaseSerial = activeSnapshotLease == null
                ? 0
                : activeSnapshotLease.serial;
        String anchorKey = activeSnapshotLease == null
                ? ""
                : activeSnapshotLease.anchorKey;
        float viewportOffsetPx = activeSnapshotLease == null
                ? 0f
                : activeSnapshotLease.viewportOffsetPx;
        if (expectedLeaseSerial > 0
                && !terminalSnapshotLeaseMatchesSerial(expectedLeaseSerial)) {
            return;
        }
        touchScrollVisualNudgeScheduled = true;
        long visualGeneration = touchScrollVisualNudgeGeneration;
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.JELLY_BEAN) {
            Choreographer.getInstance().postFrameCallback(frameTimeNanos ->
                    runCaptureRendererTouchNudge(
                            visualGeneration,
                            expectedLeaseSerial
                    ));
        } else {
            uiHandler.post(() -> runCaptureRendererTouchNudge(
                        visualGeneration,
                        expectedLeaseSerial
                ));
        }
    }

		    private boolean localHistoryTouchViewportOwnsVisibleSurfaceForNudge() {
		        if (localHistoryTouchViewportAlreadyRenderedOnly) {
		            return false;
		        }
		        return localHistoryTouchViewportTargetsVisibleSurface();
		    }

    private boolean activeTouchScrollLocalFeedbackOwner() {
        return currentApkActionOwnsActiveTouchScroll()
                && activeTouchScrollDownAtMs > 0
                && activeTouchScrollFirstLocalFeedbackAtMs > 0
                && (terminalTouchStartedInTerminalBody
                || terminalHistoryDragActive
                || terminalTouchExceededTapSlop
                || terminalTouchStartedInHistoryViewport);
    }

    private boolean isLocalHistoryBoundaryCacheSource(String source) {
        String rawSource = source == null ? "" : source.trim();
        return rawSource.indexOf("boundary") >= 0;
    }

    private boolean shouldDeferLocalHistoryAsyncPaintDuringActiveTouch(String source) {
        String inlineSource = inlineLocalHistorySource(source);
        String rawSource = source == null ? "" : source.trim();
        if ("inline-local-history-viewport".equals(rawSource)) {
            return false;
        }
        boolean boundarySource = isLocalHistoryBoundaryCacheSource(rawSource);
        boolean activeFeedbackOwner = activeTouchScrollLocalFeedbackOwner();
        boolean boundaryMergedDuringTouch = localHistoryBoundaryMergedDuringScrollAction();
        if (boundarySource) {
            // WHY: boundary fills are preloaded cache rows, not the compositor.
            // The 2026-07-10 installed rawSource proof caught a boundary-fill JS
            // callback repainting rows after the finger/release handoff. Keep
            // those rows in memory only; the next controlled viewport commit is
            // the only source allowed to mutate the visible renderer.
            Log.i(CONTROL_LOG_TAG,
                    "stage=local-history-owner endpoint=local-cache"
                            + " result=async-paint-deferred-boundary-source-memory-only"
                            + " actionId=" + safeLogToken(activeTouchScrollActionId)
                            + " tapId=" + safeLogToken(currentApkTapIdForLog())
                            + " windowId=" + safeWindowIdForControlLog(localHistoryTouchViewportWindowId)
                            + " source=" + safeLogToken(inlineSource)
                            + " rawSource=" + safeLogToken(rawSource)
                            + " boundarySource=" + boundarySource
                            + " boundaryMergedDuringTouch=" + boundaryMergedDuringTouch
                            + " activeFeedbackOwner=" + activeFeedbackOwner
                            + " firstLocalFeedbackAtMs=" + activeTouchScrollFirstLocalFeedbackAtMs
                            + " localViewportOffset=" + localHistoryTouchViewportOffset
                            + " localHistoryCachedRows=" + localHistoryTouchViewportRows.size()
                            + " boundaryRows=" + activeTouchScrollLocalHistoryBoundaryRows);
            return true;
        }
        boolean activeDragOwner = activeFeedbackOwner
                || (terminalHistoryDragActive && localHistoryTouchViewportOwnsVisibleSurfaceForNudge());
        boolean releaseSettleOwner = localHistoryBoundaryMergedDuringScrollAction();
        if (!activeDragOwner && !releaseSettleOwner) {
            return false;
        }
        // WHY: `/scrollback/chunk` and cache-boundary callbacks are data feeds,
        // not the finger-owned compositor. The 2026-07-10 T5 proof showed a tiny
        // drag repainting offsets 1 -> 397 -> 805 -> 1193 while the finger was
        // still down. A later installed proof showed the first pending cache
        // paint can also be stale if a boundary prepend landed after Java queued
        // the WebView mutation but before the JS paint callback. Once the first
        // local feedback pixel has moved for the active one-finger scroll, cache
        // fills may update memory only; only the controlled viewport source may
        // commit rows to the renderer until the finger/release-settle owner ends.
        // Extend this through the read-hold/release-settle window too; slow
        // ACTION_UP must stay visually stopped instead of
        // repainting a boundary-fill chunk after the finger lifts. The boundary
        // action id resets on the next touch/bottom/live owner, so this does not
        // block future independent reads. The visible paint during an active
        // local-history drag must come from the controlled viewport commit path
        // after the finger residual covers the visual rows.
        Log.i(CONTROL_LOG_TAG,
                "stage=local-history-owner endpoint=local-cache"
                        + " result=async-paint-deferred-active-touch"
                        + " actionId=" + safeLogToken(activeTouchScrollActionId)
                        + " tapId=" + safeLogToken(currentApkTapIdForLog())
                        + " windowId=" + safeWindowIdForControlLog(localHistoryTouchViewportWindowId)
                        + " source=" + safeLogToken(inlineSource)
                        + " rawSource=" + safeLogToken(rawSource)
                        + " boundarySource=" + boundarySource
                        + " boundaryMergedDuringTouch=" + boundaryMergedDuringTouch
                        + " activeFeedbackOwner=" + activeFeedbackOwner
                        + " activeDragOwner=" + activeDragOwner
                        + " releaseSettleOwner=" + releaseSettleOwner
                        + " firstInlineLocalHistoryPainted=" + (activeTouchScrollFirstInlineLocalHistoryAtMs > 0)
                        + " firstLocalFeedbackAtMs=" + activeTouchScrollFirstLocalFeedbackAtMs
                        + " localViewportOffset=" + localHistoryTouchViewportOffset
                        + " localHistoryCachedRows=" + localHistoryTouchViewportRows.size()
                        + " boundaryRows=" + activeTouchScrollLocalHistoryBoundaryRows);
        return true;
    }

    private boolean allowInlineLocalHistoryPaintFromRenderer(
            String source,
            String dispatchActionId,
            long requestSerial,
            String where,
            int localViewportOffset,
            int localHistoryCachedRows
    ) {
        String rawSource = source == null ? "" : source.trim();
        if ("inline-local-history-viewport".equals(rawSource)) {
            return allowMonotonicLocalHistoryViewportPaintFromRenderer(
                    dispatchActionId,
                    requestSerial,
                    where,
                    localViewportOffset,
                    localHistoryCachedRows,
                    rawSource
            );
        }
        if (isLocalHistoryBoundaryCacheSource(rawSource)) {
            return false;
        }
        String dispatch = dispatchActionId == null ? "" : dispatchActionId.trim();
        String active = activeTouchScrollActionId == null ? "" : activeTouchScrollActionId.trim();
        boolean staleAction = !dispatch.isEmpty()
                && !dispatch.equals(active)
                && (terminalHistoryDragActive
                || terminalHistoryMomentumActive
                || localHistoryBoundaryMergedDuringScrollAction()
                || localHistoryTouchViewportOwnsVisibleSurfaceForReadHold());
        if (staleAction) {
            Log.i(CONTROL_LOG_TAG,
                    "stage=local-history-owner endpoint=renderer"
                            + " result=js-paint-deferred-stale-action"
                            + " actionId=" + safeLogToken(active)
                            + " dispatchActionId=" + safeLogToken(dispatch)
                            + " tapId=" + safeLogToken(currentApkTapIdForLog())
                            + " source=" + safeLogToken(inlineLocalHistorySource(rawSource))
                            + " rawSource=" + safeLogToken(rawSource)
                            + " request=" + requestSerial);
            return false;
        }
        return !shouldDeferLocalHistoryAsyncPaintDuringActiveTouch(rawSource);
    }

    private void resetLocalHistoryTouchAcceptedPaintTrack() {
        localHistoryTouchLastPaintActionId = "";
        localHistoryTouchLastPaintWindowId = "";
        localHistoryTouchLastPaintGenerationKey = "";
        localHistoryTouchLastPaintWhere = "";
        localHistoryTouchLastPaintRows = 0;
        localHistoryTouchLastPaintOffset = -1;
    }

    private synchronized boolean allowMonotonicLocalHistoryViewportPaintFromRenderer(
            String dispatchActionId,
            long requestSerial,
            String where,
            int localViewportOffset,
            int localHistoryCachedRows,
            String rawSource
    ) {
        String dispatch = dispatchActionId == null ? "" : dispatchActionId.trim();
        String active = activeTouchScrollActionId == null ? "" : activeTouchScrollActionId.trim();
        String safeWhere = where == null ? "" : where.trim();
        if (!dispatch.isEmpty() && !active.isEmpty() && !dispatch.equals(active)) {
            Log.i(CONTROL_LOG_TAG,
                    "stage=local-history-owner endpoint=renderer"
                            + " result=js-paint-deferred-stale-action"
                            + " actionId=" + safeLogToken(active)
                            + " dispatchActionId=" + safeLogToken(dispatch)
                            + " tapId=" + safeLogToken(currentApkTapIdForLog())
                            + " source=" + safeLogToken(inlineLocalHistorySource(rawSource))
                            + " rawSource=" + safeLogToken(rawSource)
                            + " request=" + requestSerial);
            return false;
        }
        if (!"lineUp".equals(safeWhere) && !"lineDown".equals(safeWhere)) {
            return true;
        }
        int queuedOffset = Math.max(0, localViewportOffset);
        int ownerOffset = Math.max(0, localHistoryTouchViewportOffset);
        int cachedRows = Math.max(0, localHistoryCachedRows);
        String windowId = localHistoryTouchViewportWindowId == null
                ? ""
                : localHistoryTouchViewportWindowId.trim();
        String generationKey = localHistoryTouchViewportGenerationKey == null
                ? ""
                : localHistoryTouchViewportGenerationKey.trim();
        boolean sameTrack = dispatch.equals(localHistoryTouchLastPaintActionId)
                && windowId.equals(localHistoryTouchLastPaintWindowId)
                && generationKey.equals(localHistoryTouchLastPaintGenerationKey)
                && safeWhere.equals(localHistoryTouchLastPaintWhere)
                && cachedRows == localHistoryTouchLastPaintRows;
        int lastOffset = sameTrack ? localHistoryTouchLastPaintOffset : -1;
        boolean rewindsOwner = ("lineUp".equals(safeWhere) && queuedOffset > ownerOffset)
                || ("lineDown".equals(safeWhere) && queuedOffset < ownerOffset);
        boolean rewindsLastAccepted = lastOffset >= 0
                && (("lineUp".equals(safeWhere) && queuedOffset > lastOffset)
                || ("lineDown".equals(safeWhere) && queuedOffset < lastOffset));
        if (rewindsOwner || rewindsLastAccepted) {
            // WHY: the WebView can execute an older queued cached-history repaint
            // after native already accepted a newer one-finger offset. Allowing
            // that stale paint makes the transcript jump backward at the
            // live-to-local transition even though the finger delta math was
            // correct. Viewport paints may lag, but they must not rewind the
            // visible local-history offset for the same active drag.
            Log.i(CONTROL_LOG_TAG,
                    "stage=local-history-owner endpoint=renderer"
                            + " result=non-monotonic-viewport-paint-suppressed"
                            + " actionId=" + safeLogToken(active)
                            + " dispatchActionId=" + safeLogToken(dispatch)
                            + " tapId=" + safeLogToken(currentApkTapIdForLog())
                            + " windowId=" + safeWindowIdForControlLog(windowId)
                            + " where=" + safeLogToken(safeWhere)
                            + " queuedOffset=" + queuedOffset
                            + " ownerOffset=" + ownerOffset
                            + " lastAcceptedOffset=" + lastOffset
                            + " localHistoryCachedRows=" + cachedRows
                            + " generationKey=" + safeLogToken(generationKey)
                            + " rewindsOwner=" + rewindsOwner
                            + " rewindsLastAccepted=" + rewindsLastAccepted
                            + " source=" + safeLogToken(inlineLocalHistorySource(rawSource))
                            + " rawSource=" + safeLogToken(rawSource)
                            + " request=" + requestSerial);
            return false;
        }
        localHistoryTouchLastPaintActionId = dispatch;
        localHistoryTouchLastPaintWindowId = windowId;
        localHistoryTouchLastPaintGenerationKey = generationKey;
        localHistoryTouchLastPaintWhere = safeWhere;
        localHistoryTouchLastPaintRows = cachedRows;
        localHistoryTouchLastPaintOffset = queuedOffset;
        return true;
    }

    private boolean localHistoryBoundaryMergedDuringScrollAction() {
        return activeTouchScrollLocalHistoryBoundaryMergedAtMs > 0
                && !activeTouchScrollActionId.isEmpty()
                && activeTouchScrollActionId.equals(activeTouchScrollLocalHistoryBoundaryActionId);
    }

    private boolean liveTuiScrollLockActive() {
        // WHY(ROOT-C): active only while the lock targets the currently visible "unreliable-frontier"
        // pane, so a stale lock from a switched-away or now-normal-scrollback pane can never wall live
        // follow. The class = a no-scrollback histSize==0 pane (@8) OR any transcriptScrollbackAvailable
        // pane (@6/@42, whose deep scrollback is served out-of-band via /scrollback/chunk so tmux reports
        // at-bottom and enterReadMode/v256 never see the scroll). No-op firewall: false for a normal
        // histSize>0 tmux-scrollback pane (genuine read-hold owns it) and for any non-visible pane, so
        // every `|| liveTuiScrollLockActive()` clause changes behavior ONLY on that pane class.
        if (!liveTuiScrollLockActive
                || !(lastAcceptedCaptureRendererHistorySize == 0
                        || lastFrameTranscriptScrollbackAvailable)) {
            return false;
        }
        if (!hasStableWindowId(liveTuiScrollLockWindowId)) {
            return false;
        }
        String lockWindowId = liveTuiScrollLockWindowId.trim();
        return lockWindowId.equals(confirmedVisibleTerminalTargetKey())
                || lockWindowId.equals(visibleTerminalTargetKey())
                || lockWindowId.equals(currentWebViewWindowIdTargetKey());
    }

    private void clearLiveTuiScrollLock(String reason) {
        if (!liveTuiScrollLockActive) {
            return;
        }
        liveTuiScrollLockActive = false;
        liveTuiScrollLockWindowId = "";
        // WHY(ROOT-C): republish so nativeReadHold()/tuiReadHold() drop and the next idle tick commits
        // the live tail again (resume follow, catches up instantly).
        syncCaptureRendererReadHold("live-tui-scroll-lock-clear-" + reason);
    }

	    private boolean localHistoryTouchViewportScrolledUpForReadHold() {
	        // WHY(ROOT-B): the transcript-TUI "user is holding a scrolled-up read position"
	        // predicate. Scoped to histSize==0 — the ONLY case enterReadMode() bails, leaving
	        // terminalHistoryViewportActive/readModeSuppressesKeyboard unset, so this offset is the
	        // sole hold truth. offset==maxOffset is the live tail; offset<maxOffset is scrolled up
	        // (a DETECTABLE bottom => auto-clears at the tail, can never wall forever). histSize>0
	        // panes keep their existing terminalHistoryViewportActive read-hold and are unaffected.
	        return lastAcceptedCaptureRendererHistorySize == 0
	                && localHistoryTouchViewportTargetsVisibleSurface()
	                && localHistoryTouchViewportMaxOffset() > 0
	                && localHistoryTouchViewportOffset < localHistoryTouchViewportMaxOffset();
	    }

	    private boolean localHistoryTouchViewportOwnsVisibleSurfaceForReadHold() {
	        if (!localHistoryTouchViewportTargetsVisibleSurface()) {
	            return false;
	        }
	        // WHY: cached/inline local-history rows are the visual scroll owner
	        // while read mode, a MOVE, momentum, or queued `/touch-scroll` reconcile
	        // is active. Idle `/terminal-frame` may update caches behind this state,
	        // but it must not repaint/recenter the DOM until explicit Bottom/live
	        // recovery or a new non-scroll action clears read hold.
	        return readModeSuppressesKeyboard
	                || terminalHistoryViewportActive
	                || terminalHistoryDragActive
	                || terminalHistoryMomentumActive
	                || historyScrollRequestInFlight
	                || !pendingHistoryScrollWhere.isEmpty()
	                // WHY(ROOT-B): hold the scrolled-up transcript-TUI position across finger
	                // release (no active-gesture flag survives release and enterReadMode bailed).
	                || localHistoryTouchViewportScrolledUpForReadHold();
	    }

	    private boolean localHistoryTouchViewportTargetsVisibleSurface() {
	        if (!LOCAL_HISTORY_INLINE_GESTURE_PAINT_ENABLED) {
	            // Cached rows are data-only. Claiming this surface also suppresses
	            // capture refresh/read-hold and redirects finger pixels into the
	            // divergent DOM renderer, which caused the installed jump/color red.
	            return false;
	        }
		        if (localHistoryTouchViewportRows.isEmpty()
		                || !hasStableWindowId(localHistoryTouchViewportWindowId)) {
		            return false;
		        }
	        String viewportWindowId = localHistoryTouchViewportWindowId.trim();
	        return viewportWindowId.equals(confirmedVisibleTerminalTargetKey())
	                || viewportWindowId.equals(visibleTerminalTargetKey())
	                || viewportWindowId.equals(currentWebViewWindowIdTargetKey());
	    }

    private void transferCaptureRendererTouchNudgeToLocalHistoryHandoff(
            LocalHistoryRequest request,
            String where,
            long requestSerial,
            String source
    ) {
        if (!localHistoryTouchViewportTargetsRequest(request)
                || localHistoryTouchViewportAlreadyRenderedOnly
                || Math.abs(captureRendererTouchFingerNudgeResidualPx) < 0.5f) {
            return;
        }
        float transferredPx = captureRendererTouchFingerNudgeResidualPx;
        localHistoryTouchFingerNudgeResidualPx += transferredPx;
        captureRendererTouchFingerNudgeResidualPx = 0f;
        clearCaptureRendererTouchNudgeForLocalHistoryHandoff(
                "local-history-handoff-" + safeLogToken(source)
        );
        // WHY: one-finger live-bottom scroll starts on the live capture renderer,
        // then materializes cached ANSI rows. If the cached surface does not
        // inherit the exact live pixel residual, the first row paint snaps to the
        // cache transition point above the bottom. The local-history row commit
        // below settles this residual after measuring consumed visual rows.
        Log.i(CONTROL_LOG_TAG,
                "stage=local-history-handoff endpoint=renderer"
                        + " result=transferred-capture-nudge"
                        + " actionId=" + safeLogToken(activeTouchScrollActionId)
                        + " tapId=" + safeLogToken(currentApkTapIdForLog())
                        + " windowId=" + safeWindowIdForControlLog(request == null ? "" : request.windowId)
                        + " where=" + safeLogToken(where)
                        + " transferredPx=" + touchLogFloat(transferredPx)
                        + " localResidualPx=" + touchLogFloat(localHistoryTouchFingerNudgeResidualPx)
                        + " source=" + safeLogToken(source)
                        + " request=" + requestSerial);
    }

    private void clearCaptureRendererTouchNudgeForLocalHistoryHandoff(String reason) {
        pendingTouchVisualNudgePx = 0f;
        touchScrollVisualNudgeScheduled = false;
        touchScrollVisualNudgeGeneration++;
        Log.i(CONTROL_LOG_TAG,
                "stage=touch-nudge-clear endpoint=renderer"
                        + " reason=" + safeLogToken(reason)
                        + " result=deferred-to-local-history-paint");
    }

    private void nudgeLocalHistoryInlineForTouch(float deltaY, String visualWhere) {
        if (webView == null || Build.VERSION.SDK_INT < Build.VERSION_CODES.KITKAT
                || Math.abs(deltaY) < 0.5f) {
            return;
        }
        pendingLocalHistoryTouchVisualNudgePx += deltaY;
        localHistoryTouchFingerNudgeResidualPx += deltaY;
        if (localHistoryTouchVisualNudgeScheduled) {
            return;
        }
        localHistoryTouchVisualNudgeScheduled = true;
        long visualGeneration = localHistoryTouchVisualNudgeGeneration;
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.JELLY_BEAN) {
            Choreographer.getInstance().postFrameCallback(frameTimeNanos ->
                    runLocalHistoryInlineTouchNudge(visualGeneration, visualWhere));
        } else {
            uiHandler.post(() -> runLocalHistoryInlineTouchNudge(visualGeneration, visualWhere));
        }
    }

    private void runLocalHistoryInlineTouchNudge(long visualGeneration, String visualWhere) {
        localHistoryTouchVisualNudgeScheduled = false;
        if (visualGeneration != localHistoryTouchVisualNudgeGeneration
                || webView == null
                || Build.VERSION.SDK_INT < Build.VERSION_CODES.KITKAT) {
            pendingLocalHistoryTouchVisualNudgePx = 0f;
            return;
        }
        float deltaY = pendingLocalHistoryTouchVisualNudgePx;
        pendingLocalHistoryTouchVisualNudgePx = 0f;
        if (Math.abs(deltaY) < 0.5f) {
            return;
        }
        String where = "lineUp".equals(visualWhere) || "lineDown".equals(visualWhere)
                ? visualWhere
                : (deltaY > 0f ? "lineUp" : "lineDown");
        String deltaLiteral = String.format(Locale.US, "%.2f", deltaY);
        webView.evaluateJavascript(
                "(function(){"
                        + "try{"
                        + "var delta=" + deltaLiteral + ";"
                        + "var nudgeWhere='" + safeLogToken(where) + "';"
                        + "var active=document.querySelector('[data-wezterm-inline-local-history=\"1\"][data-active=\"1\"],#screen[data-wezterm-inline-local-history=\"1\"],#screenNext[data-wezterm-inline-local-history=\"1\"]');"
                        + "if(!active){return 'local-history-finger-nudge-missing';}"
                        + "function n(v){v=Number(v);return isFinite(v)?v:0;}"
                        + "function px(v){v=parseFloat(v);return isFinite(v)?v:0;}"
                        + "var current=n(active.getAttribute('data-wezterm-local-history-finger-nudge-px'));"
                        + "var next=current+delta;"
                        + "var vv=window.visualViewport;"
                        + "var viewportHeight=vv?n(vv.height):(window.innerHeight||0);"
                        + "var style=window.getComputedStyle?getComputedStyle(active):null;"
                        + "var lineHeight=style?px(style.lineHeight):0;if(!(lineHeight>0)){lineHeight=14;}"
                        + "var cap=nudgeWhere==='lineUp'?Math.max(96,Math.min(900,Math.floor(viewportHeight*0.90))):Math.max(18,Math.min(96,Math.floor(lineHeight*2.25)));"
                        + "next=Math.max(-cap,Math.min(cap,next));"
                        + "if(Math.abs(next)<0.5){next=0;}"
                        + "active.setAttribute('data-wezterm-local-history-finger-nudge-px',String(next));"
                        + "active.style.willChange=Math.abs(next)>=0.5?'transform':'';"
                        + "active.style.transform=Math.abs(next)>=0.5?'translateY('+Math.round(next)+'px)':'none';"
                        + "return 'local-history-finger-nudge:applied:deltaPx='+Math.round(delta)+':nudgePx='+Math.round(next)+':scale=unchanged';"
                        + "}catch(e){return 'local-history-finger-nudge-error';}"
                + "})()",
                result -> {
                    boolean applied = String.valueOf(result).contains("local-history-finger-nudge:applied");
                    if (applied) {
                        markTouchScrollFirstLocalFeedback(where, "local-history-finger-nudge");
                    }
                    Log.i(CONTROL_LOG_TAG,
                            "stage=local-history-finger-nudge endpoint=renderer"
                                    + " actionId=" + safeLogToken(activeTouchScrollActionId)
                                    + " deltaPx=" + safeLogToken(deltaLiteral)
                                    + " where=" + safeLogToken(where)
                                    + " firstLocalFeedbackElapsedMs=" + touchScrollFirstLocalFeedbackElapsedMs()
                                    + " result=" + safeLogToken(String.valueOf(result)));
                }
        );
    }

    private void flushLocalHistoryInlineTouchNudgeBeforeRowPaint(String where, String source) {
        if (!localHistoryTouchVisualNudgeScheduled
                && Math.abs(pendingLocalHistoryTouchVisualNudgePx) < 0.5f) {
            return;
        }
        // WHY: WebView JS calls are ordered, but Choreographer-delayed local
        // history nudges can otherwise run after the row viewport repaint queued
        // by the same MOVE. That makes a tiny finger move look like a row/chunk
        // jump. Flush the pending pixel delta first so cached row paint settles
        // against the actual finger residual.
        Log.i(CONTROL_LOG_TAG,
                "stage=local-history-finger-nudge endpoint=renderer"
                        + " result=flushed-before-row-paint"
                        + " actionId=" + safeLogToken(activeTouchScrollActionId)
                        + " pendingDeltaPx=" + touchLogFloat(pendingLocalHistoryTouchVisualNudgePx)
                        + " where=" + safeLogToken(where)
                        + " source=" + safeLogToken(source));
        runLocalHistoryInlineTouchNudge(localHistoryTouchVisualNudgeGeneration, where);
    }

    private void clearLocalHistoryInlineTouchNudge(String reason) {
        pendingLocalHistoryTouchVisualNudgePx = 0f;
        localHistoryTouchFingerNudgeResidualPx = 0f;
        localHistoryTouchVisualNudgeScheduled = false;
        localHistoryTouchVisualNudgeGeneration++;
        if (webView == null || Build.VERSION.SDK_INT < Build.VERSION_CODES.KITKAT) {
            return;
        }
        webView.evaluateJavascript(
                "(function(){"
                        + "try{"
                        + "var nodes=document.querySelectorAll('[data-wezterm-inline-local-history=\"1\"]');"
                        + "for(var i=0;i<nodes.length;i++){var node=nodes[i];node.removeAttribute('data-wezterm-local-history-finger-nudge-px');node.style.transform='none';node.style.willChange='';}"
                        + "return 'local-history-finger-nudge-clear';"
                        + "}catch(e){return 'local-history-finger-nudge-clear-error';}"
                + "})()",
                result -> Log.i(CONTROL_LOG_TAG,
                        "stage=local-history-finger-nudge-clear endpoint=renderer"
                                + " reason=" + safeLogToken(reason)
                                + " result=" + safeLogToken(String.valueOf(result)))
        );
    }

    private String captureRendererTouchNudgeJavascript(
            String deltaLiteral,
            String actionLiteral,
            long visualGeneration
    ) {
        return "(function(){"
                + "try{"
                + "var actionId=" + actionLiteral
                + ",visualGeneration=" + visualGeneration + ";"
                + "var r=window.__mantisCaptureRenderer,bridge=window.WeztermCaptureBridge;"
                + "if(!r||typeof r.nudgeTouchScroll!=='function'){return {status:'RENDERER_MISSING',appliedPx:0,touchActionId:actionId,visibleDistinctRowDisplacement:0,visibleTraversalSameRenderer:false};}"
                + "var owner=window.__weztermCanonicalGestureViewportOwner;"
                + "if(!owner||!owner.active||owner.actionId!==actionId){return {status:'GESTURE_VIEWPORT_OWNER_MISSING',appliedPx:0,touchActionId:actionId,visibleDistinctRowDisplacement:0,visibleTraversalSameRenderer:false};}"
                // WHY(v264 post-UP hard stop): evaluateJavascript calls already
                // queued in Chromium can run after ACTION_UP. The JS owner cannot
                // observe Java's synchronous generation increment, so ask the
                // volatile native owner immediately before the geometry write.
                + "if(!bridge||typeof bridge.allowCaptureRendererTouchNudge!=='function'||!bridge.allowCaptureRendererTouchNudge(actionId,visualGeneration)){return {status:'STALE_TOUCH_NUDGE_FENCED',appliedPx:0,touchActionId:actionId,visibleDistinctRowDisplacement:0,visibleTraversalSameRenderer:false};}"
                // WHY: [v227 O(1) restore] the per-MOVE nudge is a CONSTANT-TIME scalar
                // call to the renderer's own O(1) nudgeTouchScroll — NOT a DOM-wide
                // getBoundingClientRect scan over every row per finger sample. The removed
                // visibleAnchors() before/after scan + baseline row-index loop forced a
                // synchronous reflow on each MOVE and is the physically-reported scroll lag
                // (v240 red). The renderer still returns status/appliedPx/seamStatus/anchorKey,
                // so READY seam + deep-cache handling in runCaptureRendererTouchNudge is
                // preserved. visibleDistinctRowDisplacement / row-key proof is no longer
                // computed on the hot path (the release latch + telemetry own it off-path).
                + "var truth=r.nudgeTouchScroll(" + deltaLiteral + ");"
                + "var appliedPx=Number(truth&&truth.appliedPx)||0;"
                + "owner.cumulativeAppliedPx=(Number(owner.cumulativeAppliedPx)||0)+appliedPx;"
                + "owner.heldAfterRelease=false;"
                + "var result=Object.assign({},truth||{});"
                + "result.touchActionId=actionId;"
                + "result.visibleTraversalSameRenderer=true;"
                + "return result;"
                + "}catch(e){return {status:'RENDERER_ERROR',appliedPx:0,error:String(e&&e.message||e),visibleDistinctRowDisplacement:0,visibleTraversalSameRenderer:false};}"
                + "})()";
    }

    private void runCaptureRendererTouchNudge(
            long visualGeneration,
            long expectedLeaseSerial
    ) {
        touchScrollVisualNudgeScheduled = false;
        if (visualGeneration != touchScrollVisualNudgeGeneration
                || webView == null
                || Build.VERSION.SDK_INT < Build.VERSION_CODES.KITKAT) {
            pendingTouchVisualNudgePx = 0f;
            return;
        }
        float deltaY = pendingTouchVisualNudgePx;
        pendingTouchVisualNudgePx = 0f;
        if (Math.abs(deltaY) < 0.5f) {
            return;
        }
        String deltaLiteral = String.format(Locale.US, "%.2f", deltaY);
        String actionLiteral = JSONObject.quote(
                activeTouchScrollActionId == null
                        ? ""
                        : activeTouchScrollActionId.trim()
        );
        touchScrollVisualNudgeInFlight = true;
        webView.evaluateJavascript(
                captureRendererTouchNudgeJavascript(
                        deltaLiteral,
                        actionLiteral,
                        visualGeneration
                ),
                result -> {
                    touchScrollVisualNudgeInFlight = false;
                    scheduleCaptureRendererTouchNudgeIfNeeded();
                    if (expectedLeaseSerial > 0
                            && !terminalSnapshotLeaseMatchesSerial(
                            expectedLeaseSerial)) {
                        return;
                    }
                    JSONObject truth = parseJavascriptObjectResult(result);
                    String status = truth == null ? "UNPARSEABLE_RESULT" : truth.optString("status", "UNKNOWN");
                    double appliedPx = truth == null ? 0 : truth.optDouble("appliedPx", 0);
                    String traversalActionId = truth == null
                            ? ""
                            : truth.optString("touchActionId", "");
                    boolean activeTraversalAction = activeTouchScrollActionId != null
                            && activeTouchScrollActionId.trim().equals(traversalActionId);
                    int visibleDistinctRowDisplacement = truth == null
                            ? 0
                            : truth.optInt("visibleDistinctRowDisplacement", 0);
                    boolean visibleTraversalSameRenderer = truth != null
                            && truth.optBoolean("visibleTraversalSameRenderer", false);
                    boolean deterministicGestureViewportOwner =
                            activeTraversalAction
                                    && activeCaptureRendererGestureViewportOwner();
                    if (activeTraversalAction) {
                        activeTouchScrollVisibleDistinctRowDisplacement = Math.max(
                                activeTouchScrollVisibleDistinctRowDisplacement,
                                visibleDistinctRowDisplacement
                        );
                        visibleDistinctRowDisplacement =
                                activeTouchScrollVisibleDistinctRowDisplacement;
                    }
                    if (expectedLeaseSerial > 0 && terminalSnapshotLease != null) {
                        terminalSnapshotLease.anchorKey =
                                truth == null
                                        ? terminalSnapshotLease.anchorKey
                                        : truth.optString(
                                                "anchorKey",
                                                terminalSnapshotLease.anchorKey
                                        );
                        terminalSnapshotLease.viewportOffsetPx =
                                truth == null
                                        ? terminalSnapshotLease.viewportOffsetPx
                                        : (float) truth.optDouble(
                                                "viewportOffsetPx",
                                                terminalSnapshotLease.viewportOffsetPx
                                        );
                    }
                    String seamStatus = truth == null ? "" : truth.optString("seamStatus", "");
                    boolean rendererLiveBottom = truth != null
                            && (truth.optBoolean("liveBottomReached", false)
                            || "LIVE_BOTTOM".equals(status));
                    boolean seamBlocked = "READY_UNDERRUN_BEFORE_TRUE_TOP".equals(seamStatus)
                            || "READY_GAP".equals(seamStatus);
                    boolean rendererMotionAbsent = Math.abs(appliedPx) < 0.5;
                    boolean seamBlockedWithoutMotion = seamBlocked && rendererMotionAbsent;
                    boolean statusBlockedWithoutMotion = rendererMotionAbsent
                            && ("READY_UNDERRUN_BEFORE_TRUE_TOP".equals(status)
                            || "READY_GAP".equals(status));
                    boolean clampedWithoutBoundary = "CLAMPED".equals(status)
                            && rendererMotionAbsent
                            && !terminalTouchReachedHistoryTop
                            && !terminalTouchReachedLiveBottom;
                    boolean blocked = !rendererLiveBottom && (statusBlockedWithoutMotion
                            || seamBlockedWithoutMotion
                            || clampedWithoutBoundary
                            || "CACHE_COLS_DIVERGE_LIVE_COLS".equals(status)
                            || "REJECTED_GENERATION".equals(status)
                            || "REJECTED_WINDOW".equals(status));
                    if (rendererLiveBottom
                            && activeTraversalAction
                            && deltaY < -0.5f) {
                        // WHY(v284 single-owner live-bottom): zero is the capture
                        // renderer's exact live-frame baseline. Once a lineDown
                        // delta reaches it, do not enter the READY-seam recovery
                        // path (which stages older rows and can never move toward
                        // live). Latch the existing quiet bottom reconcile and
                        // stop all remaining same-direction MOVE work.
                        terminalTouchReachedLiveBottom = true;
                        terminalTouchReachedHistoryTop = false;
                        captureRendererTouchFingerNudgeResidualPx = 0f;
                        clearCaptureRendererBlockedFingerDelta(
                                "renderer-live-bottom");
                        captureRendererHistoryMovementBlocked = false;
                        captureRendererGestureViewportRefillRequested = false;
                        cancelHistoryMomentum("renderer-live-bottom");
                        clearPendingHistoryScroll();
                        if (!terminalHistoryDragActive) {
                            restoreTouchLiveBottomQuietly();
                        }
                    }
                    if ("TRUE_HISTORY_TOP".equals(status)) {
                        terminalTouchReachedHistoryTop = true;
                        blocked = true;
                    }
                    if (blocked) {
                        boolean freshUnderrun = !captureRendererHistoryMovementBlocked;
                        captureRendererBlockedFingerReplayInFlight = false;
                        String blockedWhere = terminalHistoryDragWhere == null
                                || terminalHistoryDragWhere.trim().isEmpty()
                                ? (deltaY > 0f ? "lineUp" : "lineDown")
                                : terminalHistoryDragWhere;
                        holdCaptureRendererBlockedFingerDelta(
                                deltaY,
                                blockedWhere);
                        captureRendererHistoryMovementBlocked = true;
                        if (nativeHistoryScrollController != null && nativeHistoryScrollController.isRunning()) {
                            cancelHistoryMomentum("renderer-seam-blocked");
                        }
                        if (deterministicGestureViewportOwner
                                && !captureRendererGestureViewportRefillRequested
                                && captureRendererGestureScrollActive()
                                && hasStableWindowId(
                                terminalTouchStableWindowId)) {
                            captureRendererGestureViewportRefillRequested = true;
                            deepStagingLookAheadChunkCount = 0;
                            prewarmLocalHistoryForWindow(
                                    terminalTouchStableWindowId,
                                    "gesture-owner-seam-rebuild");
                        }
                        // WHY: SCROLL DEEP-HISTORY 2026-07-26 — seam HOLD + recovery.
                        // The latch above STOPS advancing (keeps the last committed frame,
                        // never scrolls into un-staged blank). But the refill pump is
                        // stage-driven. Installed v216 proved READY_GAP can occur with
                        // needsReady=false/nextStart empty at the FIRST seam: only ~21 px
                        // moved, every later MOVE returned CLAMPED, and read-mode then
                        // vetoed live repaint forever. A fresh GAP must re-anchor from the
                        // verified stable window's cached/base chunk; a normal underrun
                        // continues from its adjacent cursor. Both paths are single-shot
                        // behind this fresh latch and clear only when renderer staging
                        // accepts READY, preventing a request or callback storm.
                        if (!deterministicGestureViewportOwner
                                && freshUnderrun
                                && captureRendererGestureScrollActive()
                                && hasStableWindowId(terminalTouchStableWindowId)) {
                            deepStagingLookAheadChunkCount = 0;
                            boolean readyGap = "READY_GAP".equals(status)
                                    || "READY_GAP".equals(seamStatus)
                                    || clampedWithoutBoundary;
                            if (readyGap) {
                                prewarmLocalHistoryForWindow(
                                        terminalTouchStableWindowId,
                                        "ready-gap-reanchor");
                            } else {
                                prefetchLocalHistoryForTouchScroll(
                                        terminalTouchStableWindowId,
                                        "lineUp",
                                        1,
                                        Math.max(1, activeHistoryScrollRequestSerial));
                            }
                        }
                    } else if (Math.abs(appliedPx) >= 0.5) {
                        clearCaptureRendererBlockedFingerDelta("renderer-applied");
                        captureRendererHistoryMovementBlocked = false;
                        captureRendererGestureViewportRefillRequested = false;
                        // WHY: v233's single 26 px nudge changed a transform while
                        // the user still saw the same row. Keep consuming MOVE in
                        // this canonical renderer across a partial READY gap, but
                        // grant viewport ownership only after twenty stable row keys
                        // have visibly traversed; cache offsets and one-row nudges
                        // cannot pass this boundary.
                        if (deterministicGestureViewportOwner
                                && visibleTraversalSameRenderer
                                && visibleDistinctRowDisplacement >= TOUCH_SCROLL_MIN_VISIBLE_DISTINCT_ROWS) {
                            markTouchScrollFirstLocalFeedback("renderer", "renderer-distinct-rows");
                        }
                    }
                    Log.i(CONTROL_LOG_TAG,
                            "stage=touch-nudge endpoint=renderer"
                                    + " actionId=" + safeLogToken(activeTouchScrollActionId)
                                    + " deltaPx=" + safeLogToken(deltaLiteral)
                                    + " firstLocalFeedbackElapsedMs=" + touchScrollFirstLocalFeedbackElapsedMs()
                                    + " result=" + safeLogToken(status)
                                    + " appliedPx=" + touchLogFloat((float) appliedPx)
                                    + " visibleDistinctRowDisplacement="
                                    + visibleDistinctRowDisplacement
                                    + " visibleTraversalSameRenderer="
                                    + visibleTraversalSameRenderer
                                    + " firstAnchorRowDisplacement="
                                    + (truth == null ? 0 : truth.optInt(
                                    "firstAnchorRowDisplacement", 0))
                                    + " lastAnchorRowDisplacement="
                                    + (truth == null ? 0 : truth.optInt(
                                    "lastAnchorRowDisplacement", 0))
                                    + " needsReady=" + (truth != null && truth.optBoolean("needsReady", false))
                                    + " trueTop=" + (truth != null && truth.optBoolean("trueTopReached", false))
                                    + " liveBottomReached=" + rendererLiveBottom
                                    + " nextStart=" + safeLogToken(truth == null ? "" : truth.optString("nextStart", "")));
                    if (Math.abs(appliedPx) >= 0.5) {
                        requestCaptureRendererTouchVisualFrame("touch-nudge");
                    }
                }
        );
    }

    private void clearCaptureRendererTouchNudgeSoon(String reason) {
        clearCaptureRendererReleasedReadHold(reason + "-scheduled-clear");
        long visualGeneration = ++touchScrollVisualNudgeGeneration;
        pendingTouchVisualNudgePx = 0f;
        uiHandler.postDelayed(() -> {
            if (visualGeneration == touchScrollVisualNudgeGeneration) {
                clearCaptureRendererTouchNudge(reason);
            }
        }, TOUCH_SCROLL_VISUAL_NUDGE_CLEAR_MS);
    }

    private void releaseCaptureRendererTouchNudge(String reason) {
        armCaptureRendererReleasedReadHoldForRelease(reason);
        long releaseVisualGeneration = touchScrollVisualNudgeGeneration;
        if (Math.abs(pendingTouchVisualNudgePx) >= 0.5f
                && webView != null
                && Build.VERSION.SDK_INT >= Build.VERSION_CODES.KITKAT) {
            // WHY(v284 release FIFO): ACTION_UP must close the gesture after every
            // MOVE already accepted from Android, not invalidate the last
            // frame-paced delta before Chromium executes it. Queue any residual
            // now; WebView executes it before the release script below. A new
            // ACTION_DOWN still increments the generation synchronously and fences
            // the old action, preserving the v264 stale-gesture hard stop.
            runCaptureRendererTouchNudge(releaseVisualGeneration, 0);
        }
        pendingTouchVisualNudgePx = 0f;
        captureRendererTouchFingerNudgeResidualPx = 0f;
        touchScrollVisualNudgeScheduled = false;
        if (localHistoryTouchViewportOwnsVisibleSurfaceForNudge()
                || "local-history-finger-nudge".equals(activeTouchScrollFirstLocalFeedbackKind)) {
            clearLocalHistoryInlineTouchNudge(reason + "-local-history-release");
        }
        if (webView == null || Build.VERSION.SDK_INT < Build.VERSION_CODES.KITKAT) {
            touchScrollVisualNudgeGeneration++;
            return;
        }
        String releaseActionId =
                activeTouchScrollActionId == null
                        ? ""
                        : activeTouchScrollActionId.trim();
        String releaseWhere =
                "lineDown".equals(terminalHistoryDragWhere)
                        ? "lineDown"
                        : "lineUp";
        String actionLiteral = JSONObject.quote(releaseActionId);
        String whereLiteral = JSONObject.quote(releaseWhere);
        // WHY: rendererHeld is bookkeeping, not visible proof. Capture the exact
        // row identities and compositor coordinates under the finger before
        // release, then verify them again after two rendered frames.
        webView.evaluateJavascript(
                "(function(){try{"
                        // WHY: APK-SCROLL-RELEASE-SNAPBACK — releaseCaptureRendererTouchNudge
                        // fires exactly once at the TRUE end of a history gesture: immediately
                        // for a slow read at ACTION_UP, and only after momentum terminates for a
                        // fling (via releaseDeferredCaptureRendererTouchNudgeAfterMomentum). Close
                        // the gesture-scroll commit window here so readHoldCommitAllowed() returns
                        // to known-good the instant the finger is truly up: no idle live-tail
                        // frame can re-pin the held reading position to Bottom. Kept off any
                        // fling-continuing path, so momentum still commits its own frames.
                        + "window.__weztermGestureScroll={activeUntil:0};"
                        + "var actionId=" + actionLiteral + ",releaseWhere=" + whereLiteral + ";"
                        + "var r=window.__mantisCaptureRenderer,owner=window.__weztermCanonicalGestureViewportOwner;"
                        + "var actionMatches=!!owner&&owner.actionId===actionId;"
                        + "var distinct=actionMatches?Math.max(0,Number(owner.visibleDistinctRowDisplacement)||0):0;"
                        + "function anchors(){var buffer=document.querySelector('#screen[data-active=\"1\"],#screenNext[data-active=\"1\"]');var rows=buffer?Array.prototype.slice.call(buffer.querySelectorAll('.captureRenderRow,.readyHistoryRow')):[];var vv=window.visualViewport,top=vv?Number(vv.offsetTop)||0:0,height=vv?Number(vv.height)||0:Number(window.innerHeight)||0,bottom=top+height,first=null,last=null;for(var i=0;i<rows.length;i++){var rect=rows[i].getBoundingClientRect();if(rect.bottom>top&&rect.top<bottom){if(!first)first=rows[i];last=rows[i];}}var firstRect=first?first.getBoundingClientRect():null,lastRect=last?last.getBoundingClientRect():null;return {firstVisibleRowKey:String(first&&first.dataset&&first.dataset.renderRowKey||''),lastVisibleRowKey:String(last&&last.dataset&&last.dataset.renderRowKey||''),firstVisibleRowTopPx:firstRect?Number(firstRect.top):NaN,lastVisibleRowTopPx:lastRect?Number(lastRect.top):NaN};}"
                        + "var releaseAnchors=anchors();"
                        + "if(!r||typeof r.releaseTouchScrollNudge!=='function'||!actionMatches||!releaseAnchors.firstVisibleRowKey){return {status:'touch-nudge-release-missing',touchActionId:actionId,heldAfterRelease:false,actualAnchorHeld:false,visibleDistinctRowDisplacement:distinct};}"
                        + "var released=!!r.releaseTouchScrollNudge(),state=typeof r.state==='function'?r.state():null,rendererHeld=!!state&&state.heldAfterRelease===true;"
                        + "window.__weztermTouchScrollReleaseAnchor={actionId:actionId,releaseWhere:releaseWhere,firstVisibleRowKey:releaseAnchors.firstVisibleRowKey,lastVisibleRowKey:releaseAnchors.lastVisibleRowKey,firstVisibleRowTopPx:releaseAnchors.firstVisibleRowTopPx,lastVisibleRowTopPx:releaseAnchors.lastVisibleRowTopPx,visibleDistinctRowDisplacement:distinct};"
                        + "owner.active=false;owner.heldAfterRelease=false;"
                        + "return {status:released&&rendererHeld?'visible-owner-release-pending':'touch-nudge-release-insufficient',touchActionId:actionId,heldAfterRelease:false,actualAnchorHeld:false,releaseVerificationQueued:true,visibleDistinctRowDisplacement:distinct,firstVisibleRowTopPx:releaseAnchors.firstVisibleRowTopPx};"
                        + "}catch(e){return {status:'touch-nudge-release-error',heldAfterRelease:false,actualAnchorHeld:false,error:String(e&&e.message||e)};}})()",
                result -> {
                    if (releaseVisualGeneration == touchScrollVisualNudgeGeneration) {
                        // The release script is FIFO-after every accepted MOVE.
                        // Invalidate only now; a newer touch already changed the
                        // generation and therefore owns this field.
                        touchScrollVisualNudgeGeneration++;
                    }
                    JSONObject truth = parseJavascriptObjectResult(result);
                    String status = truth == null
                            ? "unparseable"
                            : truth.optString("status", "unknown");
                    settleCaptureRendererReleasedReadHoldFromReleaseResult(
                            releaseActionId,
                            status
                    );
                    Log.i(CONTROL_LOG_TAG,
                            "stage=touch-nudge-release endpoint=renderer"
                                    + " actionId=" + safeLogToken(
                                    truth == null
                                            ? releaseActionId
                                            : truth.optString(
                                                    "touchActionId",
                                                    releaseActionId))
                                    + " reason=" + safeLogToken(reason)
                                    + " result=" + safeLogToken(status)
                                    + " heldAfterRelease=false"
                                    + " actualAnchorHeld=false"
                                    + " visibleDistinctRowDisplacement="
                                    + (truth == null
                                    ? 0
                                    : truth.optInt(
                                            "visibleDistinctRowDisplacement",
                                            0)));
                    if (truth != null
                            && truth.optBoolean(
                                    "releaseVerificationQueued",
                                    false)) {
                        postCaptureRendererReleaseAnchorVerification(
                                releaseActionId,
                                releaseWhere,
                                reason
                        );
                    }
                }
        );
        captureRendererGestureViewportOwnerQueued = false;
        captureRendererGestureViewportOwnerActionId = "";
        captureRendererGestureViewportOwnerWindowId = "";
        captureRendererGestureViewportOwnerLeaseSerial = 0;
        captureRendererGestureViewportOwnerReleaseDeferredForMomentum = false;
        captureRendererGestureViewportOwnerDeferredActionId = "";
        captureRendererGestureViewportOwnerDeferredSerial = 0;
        captureRendererGestureViewportRefillRequested = false;
        captureRendererHistoryMovementBlocked = false;
        clearCaptureRendererBlockedFingerDelta("gesture-owner-release");
    }

    private void armCaptureRendererReleasedReadHoldForRelease(String reason) {
        String actionId = activeTouchScrollActionId == null
                ? ""
                : activeTouchScrollActionId.trim();
        String windowId = captureRendererGestureViewportOwnerWindowId == null
                ? ""
                : captureRendererGestureViewportOwnerWindowId.trim();
        boolean rendererResidualMatchesDirection =
                ("lineUp".equals(terminalHistoryDragWhere)
                        && captureRendererTouchFingerNudgeResidualPx > 0f)
                || ("lineDown".equals(terminalHistoryDragWhere)
                        && captureRendererTouchFingerNudgeResidualPx < 0f);
        boolean exactVisibleOwner = activeCaptureRendererGestureViewportOwner()
                && hasStableWindowId(windowId)
                && windowId.equals(terminalTouchStableWindowId)
                && rendererResidualMatchesDirection
                && !terminalTouchReachedLiveBottom;
        if (!exactVisibleOwner) {
            clearCaptureRendererReleasedReadHold(reason + "-no-visible-owner");
            return;
        }
        // WHY(v260 second-DOWN transfer): arm synchronously before the async
        // renderer release callback. The O(1) compositor path can move before
        // its asynchronous visible-row callback records first feedback, so the
        // exact action/window owner plus direction-matched nonzero renderer
        // residual is the synchronous admission receipt. A human can start the
        // next gesture before the callback returns; the callback below still
        // rejects the token if the renderer did not retain the released offset.
        captureRendererReleasedReadHoldActive = true;
        captureRendererReleasedReadHoldWindowId = windowId;
        captureRendererReleasedReadHoldActionId = actionId;
        captureRendererReleasedReadHoldPhysicalUpwardHistoryGesture = false;
        Log.i(CONTROL_LOG_TAG,
                "stage=released-read-hold endpoint=renderer result=armed"
                        + " reason=" + safeLogToken(reason)
                        + " actionId=" + safeLogToken(actionId)
                        + " windowId=" + safeWindowIdForControlLog(windowId));
    }

    private void settleCaptureRendererReleasedReadHoldFromReleaseResult(
            String actionId,
            String status
    ) {
        String expectedActionId = actionId == null ? "" : actionId.trim();
        if (!captureRendererReleasedReadHoldActive
                || !expectedActionId.equals(
                captureRendererReleasedReadHoldActionId)) {
            // A new gesture may already have consumed this token. Never let a
            // late callback from the previous release clear newer ownership.
            return;
        }
        if (!"visible-owner-release-pending".equals(status)) {
            clearCaptureRendererReleasedReadHold(
                    "renderer-release-" + safeLogToken(status)
            );
        }
    }

    private boolean captureRendererReleasedReadHoldTargetsVisibleSurface() {
        if (!captureRendererReleasedReadHoldActive
                || !hasStableWindowId(
                captureRendererReleasedReadHoldWindowId)) {
            return false;
        }
        String visibleWindowId = touchScrollTargetKey();
        return hasStableWindowId(visibleWindowId)
                && visibleWindowId.equals(
                captureRendererReleasedReadHoldWindowId);
    }

    private void consumeCaptureRendererReleasedReadHold(
            String reason
    ) {
        if (!captureRendererReleasedReadHoldActive) {
            return;
        }
        String nextActionId = activeTouchScrollActionId == null
                ? ""
                : activeTouchScrollActionId.trim();
        String nextWindowId = terminalTouchStableWindowId == null
                ? ""
                : terminalTouchStableWindowId.trim();
        if (nextActionId.isEmpty()
                || !hasStableWindowId(nextWindowId)
                || !captureRendererReleasedReadHoldTargetsVisibleSurface()) {
            clearCaptureRendererReleasedReadHold(
                    reason + "-transfer-invalid");
            return;
        }
        // WHY(v267 guard reconciliation): consuming the prior gesture token
        // means transferring its exact visible hold to this new action, not
        // clearing the renderer offset that the reader is still touching.
        captureRendererReleasedReadHoldActionId = nextActionId;
        captureRendererReleasedReadHoldWindowId = nextWindowId;
        Log.i(CONTROL_LOG_TAG,
                "stage=released-read-hold endpoint=renderer result=transferred"
                        + " reason=" + safeLogToken(reason)
                        + " actionId=" + safeLogToken(
                        captureRendererReleasedReadHoldActionId)
                        + " windowId=" + safeWindowIdForControlLog(
                        captureRendererReleasedReadHoldWindowId));
    }

    private void clearCaptureRendererReleasedReadHold(String reason) {
        if (captureRendererReleasedReadHoldActive) {
            Log.i(CONTROL_LOG_TAG,
                    "stage=released-read-hold endpoint=renderer result=cleared"
                            + " reason=" + safeLogToken(reason)
                            + " actionId=" + safeLogToken(
                            captureRendererReleasedReadHoldActionId)
                            + " windowId=" + safeWindowIdForControlLog(
                            captureRendererReleasedReadHoldWindowId));
        }
        captureRendererReleasedReadHoldActive = false;
        captureRendererReleasedReadHoldWindowId = "";
        captureRendererReleasedReadHoldActionId = "";
        captureRendererReleasedReadHoldPhysicalUpwardHistoryGesture = false;
    }

    private void postCaptureRendererReleaseAnchorVerification(
            String actionId,
            String releaseWhere,
            String reason
    ) {
        // WHY: [v227 O(1) restore] the post-UP corrective re-nudge is removed. The old
        // two-frame (double-Choreographer) release-anchor verification did a DOM-wide
        // getBoundingClientRect scan and then called r.nudgeTouchScroll(correctionPx) to
        // "correct" the anchor after the finger lifted — a post-release scan + re-nudge
        // that both lagged and reintroduced the illusion the receipts reject. The renderer
        // owns the released anchor; no corrective re-nudge runs. Intentionally a no-op
        // (verifyCaptureRendererTouchNudgeReleaseAnchor is retired off the hot path).
    }

    private void verifyCaptureRendererTouchNudgeReleaseAnchor(
            String actionId,
            String releaseWhere,
            String reason
    ) {
        if (webView == null
                || Build.VERSION.SDK_INT < Build.VERSION_CODES.KITKAT) {
            return;
        }
        String actionLiteral = JSONObject.quote(
                actionId == null ? "" : actionId.trim()
        );
        String whereLiteral = JSONObject.quote(
                "lineDown".equals(releaseWhere) ? "lineDown" : "lineUp"
        );
        webView.evaluateJavascript(
                "(function(){try{"
                        + "var actionId=" + actionLiteral + ",releaseWhere=" + whereLiteral + ";"
                        + "var r=window.__mantisCaptureRenderer,owner=window.__weztermCanonicalGestureViewportOwner,release=window.__weztermTouchScrollReleaseAnchor;"
                        + "if(!r||!release||release.actionId!==actionId||!owner||owner.actionId!==actionId){return {status:'release-anchor-stale',touchActionId:actionId,actualAnchorHeld:false};}"
                        + "var buffer=document.querySelector('#screen[data-active=\"1\"],#screenNext[data-active=\"1\"]'),rows=buffer?Array.prototype.slice.call(buffer.querySelectorAll('.captureRenderRow,.readyHistoryRow')):[];"
                        + "function row(key){for(var i=0;i<rows.length;i++){if(String(rows[i]&&rows[i].dataset&&rows[i].dataset.renderRowKey||'')===key)return rows[i];}return null;}"
                        + "function measure(){var first=row(release.firstVisibleRowKey),last=row(release.lastVisibleRowKey),firstRect=first?first.getBoundingClientRect():null,lastRect=last?last.getBoundingClientRect():null;return {sameRowIdentity:!!first&&!!last,firstTop:firstRect?Number(firstRect.top):NaN,lastTop:lastRect?Number(lastRect.top):NaN};}"
                        + "function held(m){var firstDrift=Number(m.firstTop)-Number(release.firstVisibleRowTopPx),lastDrift=Number(m.lastTop)-Number(release.lastVisibleRowTopPx);return m.sameRowIdentity&&Number.isFinite(firstDrift)&&Number.isFinite(lastDrift)&&Math.abs(firstDrift)<="
                        + TOUCH_SCROLL_RELEASE_ANCHOR_TOLERANCE_PX
                        + "&&Math.abs(lastDrift)<="
                        + TOUCH_SCROLL_RELEASE_ANCHOR_TOLERANCE_PX + ";}"
                        + "var measured=measure(),actualAnchorHeld=held(measured),correctionPx=Number(release.firstVisibleRowTopPx)-Number(measured.firstTop),reconciled=false,anchorResult='release-anchor-verified';"
                        + "var correctionAllowed=measured.sameRowIdentity&&Number.isFinite(correctionPx)&&Math.abs(correctionPx)>"
                        + TOUCH_SCROLL_RELEASE_ANCHOR_TOLERANCE_PX
                        + "&&(releaseWhere==='lineDown'||correctionPx>0);"
                        + "if(!actualAnchorHeld&&correctionAllowed&&typeof r.nudgeTouchScroll==='function'&&typeof r.releaseTouchScrollNudge==='function'){r.nudgeTouchScroll(correctionPx);r.releaseTouchScrollNudge();measured=measure();actualAnchorHeld=held(measured);reconciled=actualAnchorHeld;anchorResult=reconciled?'release-anchor-reconciled':'release-anchor-reconcile-failed';}"
                        + "var state=typeof r.state==='function'?r.state():null,rendererHeld=!!state&&state.heldAfterRelease===true,distinct=Math.max(0,Number(release.visibleDistinctRowDisplacement)||0);"
                        + "var heldAfterRelease=actualAnchorHeld&&rendererHeld&&distinct>="
                        + TOUCH_SCROLL_MIN_VISIBLE_DISTINCT_ROWS + ";"
                        + "var sequence=window.__weztermTouchScrollGestureSequence||{lastActionId:'',lastAccepted:false,consecutiveHeldGestures:0};"
                        + "if(sequence.lastActionId!==actionId){sequence.consecutiveHeldGestures=heldAfterRelease?(sequence.lastAccepted?sequence.consecutiveHeldGestures+1:1):0;sequence.lastActionId=actionId;sequence.lastAccepted=heldAfterRelease;}window.__weztermTouchScrollGestureSequence=sequence;owner.heldAfterRelease=heldAfterRelease;"
                        + "var firstDriftPx=Number(measured.firstTop)-Number(release.firstVisibleRowTopPx),lastDriftPx=Number(measured.lastTop)-Number(release.lastVisibleRowTopPx);"
                        + "return {status:heldAfterRelease?'visible-owner-held':'release-anchor-drift',anchorResult:anchorResult,touchActionId:actionId,heldAfterRelease:heldAfterRelease,actualAnchorHeld:actualAnchorHeld,reconciled:reconciled,correctionPx:correctionPx,firstDriftPx:firstDriftPx,lastDriftPx:lastDriftPx,visibleDistinctRowDisplacement:distinct,consecutiveHeldGestures:sequence.consecutiveHeldGestures};"
                        + "}catch(e){return {status:'release-anchor-error',actualAnchorHeld:false,error:String(e&&e.message||e)};}})()",
                result -> {
                    JSONObject truth = parseJavascriptObjectResult(result);
                    Log.i(CONTROL_LOG_TAG,
                            "stage=touch-nudge-release-anchor endpoint=renderer"
                                    + " actionId=" + safeLogToken(
                                    truth == null
                                            ? actionId
                                            : truth.optString(
                                                    "touchActionId",
                                                    actionId))
                                    + " reason=" + safeLogToken(reason)
                                    + " result=" + safeLogToken(
                                    truth == null
                                            ? "unparseable"
                                            : truth.optString(
                                                    "status",
                                                    "unknown"))
                                    + " anchorResult=" + safeLogToken(
                                    truth == null
                                            ? ""
                                            : truth.optString(
                                                    "anchorResult",
                                                    ""))
                                    + " actualAnchorHeld="
                                    + (truth != null
                                    && truth.optBoolean(
                                            "actualAnchorHeld",
                                            false))
                                    + " heldAfterRelease="
                                    + (truth != null
                                    && truth.optBoolean(
                                            "heldAfterRelease",
                                            false))
                                    + " correctionPx="
                                    + touchLogFloat((float) (
                                    truth == null
                                            ? 0d
                                            : truth.optDouble(
                                                    "correctionPx",
                                                    0d)))
                                    + " visibleDistinctRowDisplacement="
                                    + (truth == null
                                    ? 0
                                    : truth.optInt(
                                            "visibleDistinctRowDisplacement",
                                            0))
                                    + " consecutiveHeldGestures="
                                    + (truth == null
                                    ? 0
                                    : truth.optInt(
                                            "consecutiveHeldGestures",
                                            0)));
                }
        );
    }

    private void rebindCaptureRendererTouchNudgeForHeldHistoryStart(String reason) {
        // WHY: [v243] new-gesture Java resets WITHOUT the renderer wipe. This is
        // clearCaptureRendererTouchNudge minus (a) r.clearTouchScrollNudge() — which
        // zeroes the held reading offset and applyScreenTransform()s the viewport
        // back to the bottom baseline (the second-DOWN snapback writer), and minus
        // (b) clearLocalHistoryInlineTouchNudge — which wipes the cache-owned held
        // transform the same way. The gesture owner object is re-bound immediately
        // after by beginCaptureRendererGestureViewportOwner, so only the traversal
        // bookkeeping is reset here. Removing this method re-introduces the
        // "press again to keep scrolling -> snaps to bottom" installed red.
        pendingTouchVisualNudgePx = 0f;
        captureRendererTouchFingerNudgeResidualPx = 0f;
        touchScrollVisualNudgeScheduled = false;
        touchScrollVisualNudgeGeneration++;
        captureRendererGestureViewportOwnerQueued = false;
        captureRendererGestureViewportOwnerActionId = "";
        captureRendererGestureViewportOwnerWindowId = "";
        captureRendererGestureViewportOwnerLeaseSerial = 0;
        captureRendererGestureViewportOwnerReleaseDeferredForMomentum = false;
        captureRendererGestureViewportOwnerDeferredActionId = "";
        captureRendererGestureViewportOwnerDeferredSerial = 0;
        captureRendererGestureViewportRefillRequested = false;
        if (webView == null || Build.VERSION.SDK_INT < Build.VERSION_CODES.KITKAT) {
            return;
        }
        webView.evaluateJavascript(
                "(function(){try{"
                        + "var owner=window.__weztermCanonicalGestureViewportOwner;"
                        + "if(owner){owner.active=false;}"
                        + "window.__weztermTouchScrollTraversal=null;"
                        + "return 'held-history-rebind';"
                        + "}catch(e){return 'held-history-rebind-error';}})()",
                null
        );
        Log.i(CONTROL_LOG_TAG,
                "stage=touch-nudge-rebind endpoint=renderer result=held-history-preserved"
                        + " reason=" + safeLogToken(reason)
                        + " actionId=" + safeLogToken(activeTouchScrollActionId));
    }

    private void clearCaptureRendererTouchNudge(String reason) {
        clearCaptureRendererReleasedReadHold(reason);
        pendingTouchVisualNudgePx = 0f;
        captureRendererTouchFingerNudgeResidualPx = 0f;
        touchScrollVisualNudgeScheduled = false;
        touchScrollVisualNudgeGeneration++;
        captureRendererGestureViewportOwnerQueued = false;
        captureRendererGestureViewportOwnerActionId = "";
        captureRendererGestureViewportOwnerWindowId = "";
        captureRendererGestureViewportOwnerLeaseSerial = 0;
        captureRendererGestureViewportOwnerReleaseDeferredForMomentum = false;
        captureRendererGestureViewportOwnerDeferredActionId = "";
        captureRendererGestureViewportOwnerDeferredSerial = 0;
        captureRendererGestureViewportRefillRequested = false;
        clearLocalHistoryInlineTouchNudge(reason);
        if (webView == null || Build.VERSION.SDK_INT < Build.VERSION_CODES.KITKAT) {
            return;
        }
        webView.evaluateJavascript(
                "(function(){"
                        + "try{"
                        + "var r=window.__mantisCaptureRenderer;"
                        + "var cleared=r&&typeof r.clearTouchScrollNudge==='function'?r.clearTouchScrollNudge():false;"
                        + "window.__weztermTouchScrollTraversal=null;"
                        + "window.__weztermCanonicalGestureViewportOwner=null;"
                        + "if(r&&typeof r.clearTouchScrollNudge==='function'){return cleared?'touch-nudge-clear':'touch-nudge-clear-skip';}"
                        + "return 'touch-nudge-clear-missing';"
                        + "}catch(e){return 'touch-nudge-clear-error';}"
                + "})()",
                null
        );
    }

    private void postCaptureRendererPulseFrame(String reason) {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.JELLY_BEAN) {
            Choreographer.getInstance().postFrameCallback(frameTimeNanos ->
                    runCaptureRendererTouchPulse(reason));
            return;
        }
        uiHandler.post(() -> runCaptureRendererTouchPulse(reason));
    }

    private void runCaptureRendererTouchPulse(String reason) {
        touchScrollRenderPulseScheduled = false;
        if (webView == null || Build.VERSION.SDK_INT < Build.VERSION_CODES.KITKAT) {
            return;
        }
        long now = System.currentTimeMillis();
        if (now > touchScrollRenderPulseUntilMs) {
            return;
        }
        requestCaptureRendererTouchVisualFrame(reason);
        refreshCaptureRendererPulse(reason);
        boolean stillTouchScrolling = terminalHistoryDragActive
                || terminalHistoryMomentumActive
                || historyScrollRequestInFlight
                || !pendingHistoryScrollWhere.isEmpty()
                || terminalBottomRestoreInFlight;
        if (!stillTouchScrolling) {
            return;
        }
        touchScrollRenderPulseScheduled = true;
        uiHandler.postDelayed(
                () -> postCaptureRendererPulseFrame(reason),
                TOUCH_SCROLL_RENDER_PULSE_MS
        );
    }

    private void startGestureScrollHoldHeartbeat(String reason) {
        // WHY(ROOT-A): idempotent start; keeps the JS gestureScrollActive() latch fresh so
        // no idle live frame commits mid-hold on a histSize==0 TUI.
        if (gestureScrollHoldHeartbeatScheduled
                || webView == null
                || Build.VERSION.SDK_INT < Build.VERSION_CODES.KITKAT) {
            return;
        }
        gestureScrollHoldHeartbeatScheduled = true;
        uiHandler.postDelayed(
                () -> runGestureScrollHoldHeartbeat(reason),
                GESTURE_SCROLL_HOLD_HEARTBEAT_MS);
    }

    private void runGestureScrollHoldHeartbeat(String reason) {
        gestureScrollHoldHeartbeatScheduled = false;
        // WHY(ROOT-A): bounded strictly by the physical gesture. When the finger lifts
        // (ACTION_UP clears terminalHistoryDragActive) and momentum/in-flight/pending all
        // clear, this predicate goes false and the heartbeat STOPS, so activeUntil decays
        // within CAPTURE_RENDERER_GESTURE_SCROLL_SETTLE_MS and live follow resumes -> can
        // NEVER re-create the invisible scroll wall. Re-uses the SAME commit-window
        // predicate syncCaptureRendererReadHold() uses to compute gestureScroll.
        if (webView == null
                || Build.VERSION.SDK_INT < Build.VERSION_CODES.KITKAT
                || !captureRendererGestureScrollCommitWindowActive()) {
            return;
        }
        syncCaptureRendererReadHold("gesture-hold-heartbeat");
        gestureScrollHoldHeartbeatScheduled = true;
        uiHandler.postDelayed(
                () -> runGestureScrollHoldHeartbeat(reason),
                GESTURE_SCROLL_HOLD_HEARTBEAT_MS);
    }

    private void clearPendingHistoryScroll() {
        pendingHistoryScrollWhere = "";
        pendingHistoryScrollRepeats = 0;
        pendingHistoryScrollGeneration = 0;
        pendingHistoryScrollDirectionGeneration = 0;
        pendingHistoryScrollTargetKey = "";
        syncCaptureRendererReadHold("clear-pending-history-scroll");
    }

    private void clearPostReleaseTouchScrollCommit() {
        postReleaseTouchScrollCommitGestureGeneration = -1;
        postReleaseTouchScrollCommitDirectionGeneration = -1;
        postReleaseTouchScrollCommitRequestSerial = -1;
        postReleaseTouchScrollCommitWhere = "";
        postReleaseTouchScrollCommitTargetKey = "";
    }

    private void rememberPostReleaseTouchScrollCommitIfNeeded() {
        clearPostReleaseTouchScrollCommit();
        if (!historyScrollRequestInFlight || !"lineDown".equals(terminalHistoryDragWhere)) {
            return;
        }
        // WHY: slow ACTION_UP releases still generation-cancel new post-lift work,
        // but the current in-flight down-return request was already dispatched
        // while the finger was physically down. Remember only that exact response
        // so the renderer can paint the tmux row commit instead of leaving the
        // phone visually stuck above the bottom.
        postReleaseTouchScrollCommitGestureGeneration = terminalTouchGestureGeneration;
        postReleaseTouchScrollCommitDirectionGeneration = terminalHistoryDragDirectionGeneration;
        postReleaseTouchScrollCommitRequestSerial = activeHistoryScrollRequestSerial;
        postReleaseTouchScrollCommitWhere = terminalHistoryDragWhere;
        postReleaseTouchScrollCommitTargetKey = terminalTouchStableWindowId == null
                ? ""
                : terminalTouchStableWindowId.trim();
    }

    private boolean shouldAcceptPostReleaseTouchScrollResponse(
            long gestureGeneration,
            long directionGeneration,
            long requestSerial,
            String targetKey,
            String where
    ) {
        String stableTargetKey = targetKey == null ? "" : targetKey.trim();
        return requestSerial == postReleaseTouchScrollCommitRequestSerial
                && gestureGeneration == postReleaseTouchScrollCommitGestureGeneration
                && directionGeneration == postReleaseTouchScrollCommitDirectionGeneration
                && "lineDown".equals(where)
                && where.equals(postReleaseTouchScrollCommitWhere)
                && stableTargetKey.equals(postReleaseTouchScrollCommitTargetKey);
    }

    private void supersedeHistoryScrollInFlightForDirectionChange() {
        if (!historyScrollRequestInFlight) {
            return;
        }
        // WHY: HTTP cannot recall the tmux command that is already in flight, but
        // a deliberate finger reversal must not wait for that old direction to
        // repaint or drain its pending queue. Mark the old response as superseded
        // and allow the reverse direction to dispatch immediately.
        historyScrollRequestInFlight = false;
        activeHistoryScrollRequestSerial = -1;
        clearPostReleaseTouchScrollCommit();
    }

    private void refreshCaptureRendererPulse(String reason) {
        if (webView == null || Build.VERSION.SDK_INT < Build.VERSION_CODES.KITKAT) {
            return;
        }
        if (reason != null && reason.startsWith("touch-scroll")) {
            requestCaptureRendererTouchVisualFrame(reason);
        }
        if (shouldHoldCaptureRendererPulseForReadMode(reason)) {
            Log.i(CONTROL_LOG_TAG,
                    "stage=capture-renderer endpoint=refresh-pulse result=skipped"
                            + " reason=" + safeLogToken(reason)
                            + " skipReason=read-mode-hold"
                            + " windowId=" + safeWindowIdForControlLog(confirmedVisibleTerminalTargetKey()));
            return;
        }
        if (terminalHistoryDragActive
                && reason != null
                && reason.startsWith("touch-scroll")
                && !reason.contains("release")) {
            // WHY: slow drag is visual-continuous while the finger is down. A
            // frame-pulse fetch during that interval turns tmux's line commits into
            // visible row-step motion. Release/bottom/control paths still refresh
            // explicitly after the finger stops.
            return;
        }
        // WHY: one-finger touch-scroll can pulse once per display frame while
        // `/terminal-frame` is still network/tmux-bound. Use the renderer's
        // idle-only refresh so pulse frames cannot stack async WebView JS and
        // flicker black, while explicit Bottom/send/tab-switch/Refresh still
        // use the full refresh path.
        webView.evaluateJavascript(
                "(function(){"
                        + "try{"
                        + "var r=window.__mantisCaptureRenderer;"
                        + "if(r&&typeof r.refreshIfIdle==='function'){return r.refreshIfIdle('" + sanitizeJavascriptReason(reason) + "')?'capture-refresh-idle':'capture-refresh-busy';}"
                        + "if(r&&typeof r.refresh==='function'){r.refresh(false,'" + sanitizeJavascriptReason(reason) + "');return 'capture-refresh-fallback';}"
                        + "return 'not-capture';"
                        + "}catch(e){return 'err';}"
                + "})()",
                null
        );
    }

    private boolean shouldHoldCaptureRendererPulseForReadMode(String reason) {
        if (reason == null || !reason.startsWith("touch-scroll")) {
            return false;
        }
        if (terminalHistoryDragActive || terminalHistoryMomentumActive) {
            return false;
        }
        if (historyScrollRequestInFlight || !pendingHistoryScrollWhere.isEmpty()) {
            return true;
        }
        return readModeSuppressesKeyboard || terminalHistoryViewportActive;
    }

    private void refreshCaptureRendererTouchEdge(String reason) {
        if (webView == null || Build.VERSION.SDK_INT < Build.VERSION_CODES.KITKAT) {
            return;
        }
        String safeReason = sanitizeJavascriptReason(reason);
        // WHY: normal finger-down touch-scroll pulses intentionally suppress
        // renderer commits so slow drags do not turn into row-step jitter. The
        // true tmux top/live-bottom edge is different: if Android keeps suppressing
        // that final edge frame, the user hits a visual wall above the real range
        // edge even though `/touch-scroll` already reached it. Force exactly one
        // edge fetch, but leave the renderer's same-direction/stale-frame gate in
        // control of whether rows may swap.
        webView.evaluateJavascript(
                "(function(){"
                        + "try{"
                        + "var r=window.__mantisCaptureRenderer;"
                        + "if(r&&typeof r.refreshTouchScrollEdge==='function'){return r.refreshTouchScrollEdge('" + safeReason + "')?'touch-edge-refresh':'touch-edge-busy';}"
                        + "if(r&&typeof r.refresh==='function'){r.refresh(true,'" + safeReason + "');return 'touch-edge-refresh-fallback';}"
                        + "return 'not-capture';"
                        + "}catch(e){return 'err';}"
                + "})()",
                null
        );
    }

    private void refreshCaptureRendererTouchCommit(String reason) {
        if (webView == null || Build.VERSION.SDK_INT < Build.VERSION_CODES.KITKAT) {
            return;
        }
        String safeReason = sanitizeJavascriptReason(reason);
        // WHY: normal finger-down pulses stay gated to avoid row-step jitter. A
        // successful current `/touch-scroll` response is the safe handoff point:
        // renderer-side same-direction proof decides whether the frame can swap,
        // while this prevents the touch nudge from freezing at its local cap.
        webView.evaluateJavascript(
                "(function(){"
                        + "try{"
                        + "var r=window.__mantisCaptureRenderer;"
                        + "if(r&&typeof r.refreshTouchScrollCommit==='function'){return r.refreshTouchScrollCommit('" + safeReason + "')?'touch-commit-refresh':'touch-commit-busy';}"
                        + "if(r&&typeof r.refresh==='function'){r.refresh(true,'" + safeReason + "');return 'touch-commit-refresh-fallback';}"
                        + "return 'not-capture';"
                        + "}catch(e){return 'err';}"
                + "})()",
                null
        );
    }

    private void refreshCaptureRendererTouchReleaseCommit(String reason) {
        if (webView == null || Build.VERSION.SDK_INT < Build.VERSION_CODES.KITKAT) {
            return;
        }
        String safeReason = sanitizeJavascriptReason(reason);
        webView.evaluateJavascript(
                "(function(){"
                        + "try{"
                        + "var r=window.__mantisCaptureRenderer;"
                        + "if(r&&typeof r.refreshTouchScrollReleaseCommit==='function'){return r.refreshTouchScrollReleaseCommit('" + safeReason + "')?'touch-release-commit-refresh':'touch-release-commit-busy';}"
                        + "if(r&&typeof r.refreshTouchScrollCommit==='function'){return r.refreshTouchScrollCommit('" + safeReason + "')?'touch-release-commit-fallback':'touch-release-commit-skip';}"
                        + "return 'not-capture';"
                        + "}catch(e){return 'err';}"
                + "})()",
                null
        );
    }

    private void loadTerminal() {
        loadTerminalAtIndex(0, "load");
    }

    private void loadTerminalRendererUrl(String url) {
        if (webView == null || url == null || url.trim().isEmpty()) {
            return;
        }
        Map<String, String> headers = new LinkedHashMap<>();
        // WHY: the renderer's SSE bootstrap distinguishes the native APK with
        // this non-secret client identity. Funnel every initial and recovery
        // navigation through one helper so reconnects retain the same contract.
        headers.put("X-Mantis-Client", CONTROL_CLIENT_VALUE);
        webView.loadUrl(url, headers);
    }

    private void loadTerminalAtIndex(int index, String reason) {
        terminalUrlIndex = Math.max(0, Math.min(index, TERMINAL_URLS.length - 1));
        activeTerminalBaseUrl = TERMINAL_URLS[terminalUrlIndex];
        int fontSize = prefs.getInt(PREF_FONT_SIZE, DEFAULT_FONT_SIZE);
        markTerminalLoadStarted();
        // WHY: the live host currently answers immediately on the direct Tailnet
        // IP while the MagicDNS name can stall before the phone reaches the
        // control server. Prefer the proven IP and keep MagicDNS only as a
        // fallback so Active/Old titles and the visual renderer come from the
        // same shared server.
        // WHY: the 2026-06-22 gap/black-box regression proved raw ttyd is the
        // wrong visual owner for APK/web: fitting ttyd mutates shared tmux
        // geometry, while not fitting leaves a huge bottom gap. The APK renders
        // the control server's read-only capture stream and keeps tmux commands
        // on stable @windowId control endpoints.
        loadTerminalRendererUrl(terminalUrlWithOptions(activeTerminalBaseUrl, fontSize));
        pinTerminalViewportSoon(reason);
        focusTerminalInputSoon(false);
        keepLiveInputVisibleSoon(reason);
        scheduleBlankTerminalWatchdog(reason);
    }

    private String terminalUrlWithOptions(String baseUrl) {
        return terminalUrlWithOptions(baseUrl, prefs.getInt(PREF_FONT_SIZE, DEFAULT_FONT_SIZE));
    }

    private String terminalUrlWithOptions(String baseUrl, int fontSize) {
        String targetKey = visibleTerminalTargetKey();
        if (hasStableWindowId(targetKey)) {
            String stableTarget = targetKey.trim();
            if (updateCaptureRendererWindowTargetKey(
                    stableTarget,
                    "terminal-url-options",
                    false
            )) {
                confirmedCaptureRendererWindowTargetKey = "";
            }
        } else {
            updateCaptureRendererWindowTargetKey(
                    "",
                    "terminal-url-options-empty",
                    false
            );
            confirmedCaptureRendererWindowTargetKey = "";
        }
        String targetQuery = hasStableWindowId(targetKey)
                ? "&windowId=" + urlEncode(targetKey.trim())
                : "";
        String viewportMode = currentViewportMode();
        boolean mobileViewport = VIEWPORT_MODE_MOBILE.equals(viewportMode);
        String colsQuery = mobileViewport
                ? ""
                : "&cols=" + APK_CAPTURE_RENDERER_COLS;
        int rendererFontSize = rendererFontSizeForViewportMode(fontSize, viewportMode);
        return baseUrl
                + "?fontSize=" + rendererFontSize
                + "&viewportMode=" + urlEncode(viewportMode)
                // WHY: Desktop mode is the protected current APK behavior: the
                // capture renderer emulates the old readable 132-column grid
                // without resizing tmux. Mobile mode intentionally omits `cols`
                // so the existing read-only renderer measures Android width and
                // wraps to the phone viewport without touching shared tmux
                // geometry, pinch ownership, or the 132-column Desktop path.
                + colsQuery
                + targetQuery
                + "&disableLeaveAlert=true"
                + "&rendererType=dom"
                + "&customGlyphs=false"
                + "&scrollOnUserInput=true";
    }

    private String currentViewportMode() {
        // WHY: SCROLL acceptance #4/#5 — MOBILE re-wrap (phone width; the renderer's
        // `-J` logical lines wrapped to the Android viewport) is now the DEFAULT so
        // text never renders at the desktop 132-col width (no tiny text / no
        // horizontal scroll). Desktop 132-col is preserved but demoted to an opt-in
        // Settings control (setViewportMode persists PREF_VIEWPORT_MODE + reloads the
        // renderer query). A user who explicitly chose Desktop keeps it; only the
        // unset default flips to mobile. Live + scrollback share this one query
        // contract via measured.cols, so they cannot diverge in width mode.
        if (prefs == null) {
            return VIEWPORT_MODE_MOBILE;
        }
        String mode = prefs.getString(PREF_VIEWPORT_MODE, VIEWPORT_MODE_MOBILE);
        return VIEWPORT_MODE_DESKTOP.equals(mode) ? VIEWPORT_MODE_DESKTOP : VIEWPORT_MODE_MOBILE;
    }

    private int rendererFontSizeForViewportMode(int fontSize, String viewportMode) {
        int bounded = Math.max(MIN_FONT_SIZE, Math.min(MAX_FONT_SIZE, fontSize));
        if (VIEWPORT_MODE_MOBILE.equals(viewportMode)) {
            return Math.max(MOBILE_VIEWPORT_MIN_FONT_SIZE, bounded);
        }
        return bounded;
    }

    private String viewportModeLabel() {
        return VIEWPORT_MODE_MOBILE.equals(currentViewportMode()) ? "Mobile" : "Desktop";
    }

    private boolean isKnownTerminalUrl(String url) {
        if (url == null) {
            return false;
        }
        for (String baseUrl : TERMINAL_URLS) {
            if (url.startsWith(baseUrl)) {
                return true;
            }
        }
        return false;
    }

    private void handleTerminalLoadFailure(String failedUrl) {
        wakeLaptopForTerminal("terminal-load-failed");
        if (webView == null || !isKnownTerminalUrl(failedUrl)) {
            scheduleTerminalWakeRetry("terminal-load-failed");
            return;
        }
        if (terminalUrlIndex + 1 < TERMINAL_URLS.length) {
            loadTerminalAtIndex(terminalUrlIndex + 1, "terminal-url-fallback");
            return;
        }
        scheduleTerminalWakeRetry("terminal-load-failed");
    }

    private void scheduleTerminalWakeRetry(String reason) {
        long generation = ++terminalWakeRetryGeneration;
        uiHandler.postDelayed(() -> {
            if (generation != terminalWakeRetryGeneration || webView == null || !activityResumed) {
                return;
            }
            // WHY: after a real sleep/wake, retry the proven direct Tailnet IP
            // first. Retrying whatever failed last can leave the phone stuck on a
            // stale MagicDNS URL even after Wake-on-LAN brings the laptop back.
            loadTerminalAtIndex(0, reason + "-wake-retry");
        }, TERMINAL_WAKE_RETRY_DELAY_MS);
    }

    private void wakeLaptopForTerminal(String reason) {
        long now = System.currentTimeMillis();
        if (now - lastWakeOnLanAtMs < WOL_COOLDOWN_MS) {
            return;
        }
        lastWakeOnLanAtMs = now;
        new Thread(() -> sendWakeOnLanPackets()).start();
    }

    private void sendWakeOnLanPackets() {
        try (DatagramSocket socket = new DatagramSocket()) {
            socket.setBroadcast(true);
            for (String macAddress : WOL_MAC_ADDRESSES) {
                byte[] packet = wakeOnLanPacket(macAddress);
                for (String target : WOL_TARGETS) {
                    InetAddress address = InetAddress.getByName(target);
                    for (int port : WOL_PORTS) {
                        socket.send(new DatagramPacket(packet, packet.length, address, port));
                    }
                }
            }
        } catch (Exception ignored) {
            // WHY: Wake-on-LAN is a best-effort preflight for the sleeping-laptop
            // case. It must never block app open, WebView reconnect, toolbar
            // actions, or the title/control API when the phone is off the home LAN
            // or Android refuses local broadcast traffic.
        }
    }

    private byte[] wakeOnLanPacket(String macAddress) throws Exception {
        String normalized = macAddress.replace(":", "").replace("-", "").trim();
        if (normalized.length() != 12) {
            throw new IllegalArgumentException("Bad MAC address");
        }
        byte[] macBytes = new byte[6];
        for (int i = 0; i < 6; i++) {
            macBytes[i] = (byte) Integer.parseInt(normalized.substring(i * 2, i * 2 + 2), 16);
        }
        byte[] packet = new byte[6 + 16 * macBytes.length];
        for (int i = 0; i < 6; i++) {
            packet[i] = (byte) 0xff;
        }
        for (int i = 6; i < packet.length; i += macBytes.length) {
            System.arraycopy(macBytes, 0, packet, i, macBytes.length);
        }
        return packet;
    }

    private void adjustFont(int delta) {
        int current = prefs.getInt(PREF_FONT_SIZE, DEFAULT_FONT_SIZE);
        int next = Math.max(MIN_FONT_SIZE, Math.min(MAX_FONT_SIZE, current + delta));
        if (next == current) {
            toast("Font size " + next);
            return;
        }
        prefs.edit().putInt(PREF_FONT_SIZE, next).apply();
        loadTerminal();
        toast("Font size " + next);
    }

    private void resetFont() {
        prefs.edit().putInt(PREF_FONT_SIZE, DEFAULT_FONT_SIZE).apply();
        loadTerminal();
        toast("Font size " + DEFAULT_FONT_SIZE);
    }

    private void scrollTerminal(String where, String message) {
        scrollTerminal(where, message, true);
    }

    private void scrollTerminal(String where, String message, boolean refocusTerminal) {
        // WHY: The phone WebView is only the transport. The control server now
        // chooses the correct scroll layer: the read-only full-session reader,
        // Codex transcript-pager keys for old alt-screen panes, or tmux
        // copy-mode for plain shell panes. Both toolbar buttons and one-finger
        // drags use this server path now; do not replace it with WebView scroll
        // because that only moves the browser viewport and brought back the
        // "can't reach the real top" loop.
        // WHY: visible Scroll menu actions must target the same stable tmux
        // window as touch-scroll. A bare `/scroll` follows whichever pane
        // `main_phone` currently selected and reintroduces the cross-lane
        // scroll drift that made Page up/Page down look broken on the APK.
        String path = appendStableWindowQuery("/scroll?where=" + urlEncode(where), visibleTerminalTargetKey());
        control(path, message, refocusTerminal);
    }

    private void openFullSessionReader() {
        String sourceTargetKey = readerSourceTargetKey("full-session-reader");
        enterReadMode();
        // WHY: the user needs the true beginning of a Codex session, not just
        // whatever tmux scrollback retained. The server opens a generated
        // read-only transcript tab from Codex's persisted JSONL and places it
        // at the top, while Live returns to the original running tab. Include
        // the stable reader source id so delayed reader requests cannot follow
        // a different tmux focus after Active/Old switching or stale selected
        // transcript-like body drift.
        control(appendStableWindowQuery("/read-session", sourceTargetKey), "Session reader", false);
    }

    private void goLiveBottom() {
        // WHY: Bottom is visual recovery. A success Toast sits over the live
        // prompt area on the APK and recreated the "can't see bottom text"
        // regression; failures still toast from the HTTP control callback.
        restoreLiveForViewing("");
    }

    private void refreshTerminalTransport() {
        // WHY: Android package updates and ttyd reconnects can leave a stale
        // WebView transport even while the tmux session is still healthy. This
        // is deliberately not Activity.recreate(), not tab close/open, and not
        // a tmux restart. The current window stays selected; only the browser
        // connection is reloaded and then focused again.
        long generation = leaveReadModeForLiveInput(false);
        getJsonWithRetry("/fix-view", payload -> {
            if (generation != terminalModeGeneration) {
                return;
            }
            if (!payload.optBoolean("ok", false)) {
                toast(payload.optString("error", "Refresh failed"));
                return;
            }
            // WHY: Refresh is a visual transport repair. A normal success Toast
            // covers the live prompt/native composer just like the old Bottom,
            // Send, and Active-open popups. The repaint itself is the success
            // signal; keep only real failure Toasts on this path.
            reloadTerminalTransportOnly("fix-view");
        }, exc -> {
            reloadTerminalTransportOnly("fix-view");
        });
    }

    private void reloadTerminalTransportOnly(String reason) {
        if (webView == null) {
            return;
        }
        String currentUrl = webView.getUrl();
        markTerminalLoadStarted();
        loadTerminalRendererUrl(isKnownTerminalUrl(currentUrl)
                ? currentUrl
                : terminalUrlWithOptions(activeTerminalBaseUrl));
        pinTerminalViewportSoon(reason);
        focusTerminalInputSoon();
        keepLiveInputVisibleSoon(reason);
        scheduleBlankTerminalWatchdog(reason);
    }

    private void refreshActiveSwitchTransportOnceSoon(String reason, long generation) {
        uiHandler.postDelayed(() -> {
            if (webView == null
                    || generation != terminalModeGeneration
                    || readModeSuppressesKeyboard
                    || terminalHistoryViewportActive
                    || isDockedPromptComposerVisible()) {
                return;
            }
            // WHY: v2.31 proved shields, DOM row clamps, software layers, and the
            // automatic Bottom-core settle could all leave the real phone readable
            // frame dotted, while one manual Refresh cleared the same WebView. This
            // is a single passive transport refresh after Active switching only:
            // keep the same tmux window, do not restart ttyd/control/title lanes,
            // do not open the keyboard, and do not loop reloads.
            reloadTerminalTransportOnly(reason + "-one-shot-active-refresh");
        }, 420);
    }

    private void settleEntryLiveBottomSoon(String reason) {
        if (webView == null) {
            return;
        }
        long generation = ++entryLiveBottomSettleGeneration;
        long bottomCoreGeneration = ++entryBottomCoreGeneration;
        settleEntryLiveBottom(reason, generation, bottomCoreGeneration, 120);
        settleEntryLiveBottom(reason, generation, bottomCoreGeneration, 520);
        settleEntryLiveBottom(reason, generation, bottomCoreGeneration, 1100);
        settleEntryLiveBottom(reason, generation, bottomCoreGeneration, 2300);
    }

    private void settleEntryLiveBottom(String reason, long generation, long bottomCoreGeneration, long delayMs) {
        uiHandler.postDelayed(() -> {
            if (webView == null
                    || !activityResumed
                    || generation != entryLiveBottomSettleGeneration
                    || bottomCoreGeneration != entryBottomCoreGeneration
                    || isDockedPromptComposerVisible()
                    || isTerminalGestureRecoveryActive()
                    || isViewerPanAllowed()) {
                return;
            }
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.KITKAT) {
                webView.evaluateJavascript(terminalDomReadyScript(), value -> {
                    if (!javascriptBoolean(value)
                            || generation != entryLiveBottomSettleGeneration
                            || bottomCoreGeneration != entryBottomCoreGeneration) {
                        return;
                    }
                    runEntryBottomCoreRecovery(reason, generation, bottomCoreGeneration);
                });
                return;
            }
            runEntryBottomCoreRecovery(reason, generation, bottomCoreGeneration);
        }, Math.max(0, delayMs));
    }

    private void runEntryBottomCoreRecovery(String reason, long generation, long bottomCoreGeneration) {
        if (webView == null
                || !activityResumed
                || generation != entryLiveBottomSettleGeneration
                || bottomCoreGeneration != entryBottomCoreGeneration
                || isDockedPromptComposerVisible()
                || isTerminalGestureRecoveryActive()
                || isViewerPanAllowed()) {
            return;
        }
            long now = System.currentTimeMillis();
            if (now - lastEntryLiveBottomSettleAtMs < ENTRY_LIVE_BOTTOM_SETTLE_MIN_INTERVAL_MS) {
                return;
            }
            lastEntryLiveBottomSettleAtMs = now;
            long modeGeneration = leaveReadModeForLiveInput(false);
            // WHY: The user-proven Android APK failure is that first entry and tab
            // return can show xterm's dotted or black stale rows until the toolbar
            // Bottom button is pressed. Reuse the exact Bottom-core helper only after
            // ttyd/xterm exists so the repaint work has a DOM to operate on, but keep
            // this as passive navigation: no native composer, no keyboard, no WebView
            // reload, and no hidden xterm typing focus.
            runBottomButtonLiveBottomRecovery(
                    reason + "-entry-bottom-core",
                    modeGeneration,
                    "",
                    false,
                    true,
                    null
            );
    }

    private String terminalDomReadyScript() {
        return "(function(){"
                + "try{"
                + "return !!(document.querySelector('[data-mantis-capture-renderer=\"1\"]')||window.term||window.terminal||document.querySelector('.xterm-rows,.xterm-screen,.xterm-helper-textarea,canvas'));"
                + "}catch(e){return false;}"
                + "})()";
    }

    private boolean javascriptBoolean(String value) {
        return "true".equals(String.valueOf(value));
    }

    private void openInstallPage() {
        // WHY: future APK updates must not depend on USB. The install page is
        // served from the desktop's Tailscale IP, so the phone can fetch the
        // current APK while it is away from the cable.
        try {
            startActivity(new Intent(Intent.ACTION_VIEW, Uri.parse(INSTALL_URL)));
        } catch (Exception exc) {
            toast("Could not open install page");
        }
    }

    private void createBugReport() {
        try {
            JSONObject client = new JSONObject();
            client.put("appVersion", APP_VERSION_NAME);
            client.put("webViewUrl", webView == null ? "" : webView.getUrl());
            client.put("readMode", readModeSuppressesKeyboard);
            client.put("historyViewport", terminalHistoryViewportActive);
            client.put("nativeComposerVisible", promptComposerBar != null
                    && promptComposerBar.getVisibility() == View.VISIBLE);
            client.put("lastTerminalLoadAtMs", lastTerminalLoadAtMs);
            client.put("webViewScale", webViewScale);
            client.put("webViewScrollX", webView == null ? 0 : webView.getScrollX());
            client.put("webViewScrollY", webView == null ? 0 : webView.getScrollY());
            postText("/bug-report", client.toString(), payload -> {
                if (!payload.optBoolean("ok", false)) {
                    toast(payload.optString("error", "Bug report failed"));
                    return;
                }
                String path = payload.optString("path", "");
                ClipboardManager clipboardManager =
                        (ClipboardManager) getSystemService(Context.CLIPBOARD_SERVICE);
                if (clipboardManager != null && !path.isEmpty()) {
                    clipboardManager.setPrimaryClip(
                            ClipData.newPlainText("WEzterm bug report", path)
                    );
                }
                toast(path.isEmpty() ? "Bug report created" : "Bug report path copied");
            }, exc -> toast("Mantis Control is not reachable"));
        } catch (Exception exc) {
            toast("Bug report failed");
        }
    }

    private void startCurrentTask() {
        if (promptComposerBar != null
                && promptComposerBar.getVisibility() == View.VISIBLE
                && promptComposerInput != null) {
            if (promptComposerInput.getText().toString().trim().length() == 0) {
                // WHY: Codex/Claude terminal menus often show a highlighted
                // choice and ask for plain Enter to confirm. With an empty native
                // composer, the obvious Start/Send control must confirm the
                // terminal menu instead of silently hiding the composer and making
                // the numbered prompt feel dead.
                sendEnterToTerminal();
                return;
            }
            // WHY: Start sits under the user's thumb and now doubles as "send the
            // visible native composer" when that composer is open. Otherwise the
            // user could type a full prompt safely, tap the obvious Start button,
            // and send only a raw Enter to xterm while leaving the prompt unsent.
            submitDockedPrompt();
            return;
        }
        // WHY: Start is deliberately not "smart". It sends Enter regardless of
        // whether the pane looks idle or running, matching the desktop habit of
        // pressing Enter to submit the prompt currently visible in the composer.
        // Stop remains a separate explicit interrupt button beside it.
        sendEnterToTerminal();
    }

    private void stopCurrentTask() {
        // WHY: Stop is the phone equivalent of the desktop Escape key. Do not
        // submit drafts, queue second-press state, or invent a phone-only stop
        // flow here; Send/Enter owns prompt submission and Stop owns one Escape.
        sendStopInterrupt(promptComposerTargetKey());
        showPromptComposerSubmitTouchOverlay("stop-current-task");
    }

    private void sendEnterToTerminal() {
        // WHY: FIX C added a target-explicit overload. The pasted-but-not-entered
        // recovery must press Enter on the exact window the /submit-text pasted
        // into (its stableTargetKey), which can differ from the visible composer
        // target if the visible session drifted while the POST was in flight. The
        // no-arg default keeps existing callers on the current composer target.
        sendEnterToTerminal(promptComposerTargetKey());
    }

    private void sendEnterToTerminal(String targetKey) {
        if (blockSendForExplicitSessionInteractionState(targetKey, "send-enter")) {
            return;
        }
        long generation = leaveReadModeForLiveInput();
        getJson(appendStableWindowQuery("/send-enter", targetKey), payload -> {
            if (generation != terminalModeGeneration) {
                return;
            }
            if (!payload.optBoolean("ok", false)) {
                toast(payload.optString("error", "Send failed"));
                return;
            }
            // WHY: success Toasts sit directly over the live prompt/native
            // composer on the phone. Start/Send success is already visible in the
            // terminal state; keep error Toasts, but do not cover typing with a
            // redundant "Sent" popup.
            hideDockedPromptComposer(false, true);
            focusTerminalInputSoon(false);
            settleLiveBottomAfterSend("send-enter");
        }, exc -> toast("Mantis Control is not reachable"));
    }

    private void sendStopInterrupt(String targetKey) {
        // WHY: Stop must be an instant interrupt, not a modal confirmation. The
        // toolbar flash/status is enough local feedback; a success Toast can cover
        // the same terminal area the user is trying to keep scrolling while the
        // backend Escape request completes. Errors still surface through control().
        control(appendStableWindowQuery("/stop", targetKey), "", true);
    }

    private void showSafePromptComposer() {
        final EditText input = new EditText(this);
        input.setSingleLine(false);
        input.setMinLines(3);
        input.setMaxLines(8);
        // WHY: the native prompt must support phone dictation. v1.54 forced
        // visible-password and no-personalized-learning flags to fight
        // autocorrect, but Samsung/Gboard can treat those as private/incognito
        // entry and remove the mic. Keep the controlled paste+Enter submit path
        // for correctness, while advertising normal visible text to the IME so
        // voice input stays available.
        input.setInputType(TERMINAL_INPUT_TYPE);
        input.setImeOptions(TERMINAL_IME_OPTIONS);
        int pad = dp(10);
        input.setPadding(pad, pad, pad, pad);
        new AlertDialog.Builder(this)
                .setTitle("Type prompt")
                .setView(input)
                .setPositiveButton("Send", (dialog, which) -> {
                    String text = input.getText().toString();
                    submitSafePrompt(text);
                })
                .setNegativeButton("Cancel", null)
                .show();
    }

    private void showDockedPromptComposer(String reason) {
        if (promptComposerBar == null || promptComposerInput == null) {
            showSafePromptComposer();
            return;
        }
        if ("tap-up".equals(reason) && System.currentTimeMillis() < terminalBodyTapSuppressedUntilMs) {
            // WHY: the real-phone Active Sessions proof for v2.13 still showed the
            // docked composer reopening as `Send` after a row tap. That happens when
            // the dialog's release lands on the terminal body after the picker closes.
            // Active switching is navigation, not typing, so swallow only an orphan
            // tap-up that has no fresh terminal ACTION_DOWN. A real new tap clears
            // the passive suppression in handleTerminalTouch and must open the native composer promptly.
            // normal deliberate terminal taps after the suppression window still open the composer.
            hideDockedPromptComposerForSessionSwitch("passive-switch-tap-up-block");
            return;
        }
        // WHY REGRESSION LOCK APK-SEND-ALWAYS-QUEUE-2326-A: opening the native
        // composer is local queue preparation, not delivery. The user must always
        // be able to type and tap Send from the APK, even while the central target
        // is `target-visible-body-not-proven`, fresh-shell/no-transcript, title
        // error, OAuth repair, busy, or usage-limited. The central /submit-text
        // route still owns safe delivery and can return a same-target blocker
        // before tmux paste/Enter; blocking the composer here made the APK look
        // frozen and left text in the raw terminal prompt instead of the local queue.
        boolean wasVisible = promptComposerBar.getVisibility() == View.VISIBLE;
        cancelXtermBlankTailMask("composer-" + reason);
        // WHY: this native composer is the default phone typing surface. It avoids
        // the fragile Android WebView/xterm hidden-textarea IME path that repeatedly
        // duplicated Samsung/Gboard/voice input in real use, while keeping voice
        // dictation available through normal visible text flags.
        hideHistoryTouchOverlayQuietly();
        terminalHistoryViewportActive = false;
        readModeSuppressesKeyboard = false;
        terminalModeGeneration++;
        terminalTouchGestureGeneration++;
        terminalFocusGeneration++;
        liveInputVisibilityGeneration++;
        long composerGeneration = ++promptComposerVisibilityGeneration;
        if (!wasVisible) {
            resetPromptComposerLocalDraftForCurrentTarget();
        }
        promptComposerBar.setVisibility(View.VISIBLE);
        updateStartButtonLabel();
        restoreDockedPromptComposerFocus(reason);
        reassertDockedPromptComposerFocus(reason, composerGeneration, 120);
        reassertDockedPromptComposerFocus(reason, composerGeneration, 360);
        if ("tap-up".equals(reason) || "tap-to-type".equals(reason)) {
            // WHY(v280 first-open IME recovery): the existing hidden-IME retry was
            // reachable only after a configuration rebuild or a tap inside an
            // already-visible editor. A normal terminal tap can create and focus
            // the composer while Samsung/Gboard rejects that first show request.
            // Reuse the same delayed, generation/inset-fenced one-shot so the
            // literal first tap cannot strand a focused composer without an IME.
            schedulePromptComposerHiddenImeRecovery(
                    "composer-open-" + reason,
                    PROMPT_COMPOSER_TAP_IME_RECOVERY_DELAY_MS
            );
        }
        refreshCaptureRendererForComposerTransition("composer-" + reason);
        alignViewerForComposerReason(reason);
        // WHY: do not arm a WebView bitmap reload when opening the native
        // composer. v1.85 proved that low-paint sampling during this resize can
        // reload a healthy mostly-black terminal while the user is typing, leaving
        // the app black with only a cursor. Composer proof now lives in the
        // real-phone UI harness; runtime recovery stays explicit through Refresh.
    }

    private void alignViewerForComposerReason(String reason) {
        if ("tap-up".equals(reason)) {
            // WHY: a plain terminal-body tap should only put the cursor into the
            // native composer. Running the zoomed true-bottom scroll helper here
            // made a tap look like the same rapid up/down refresh as the Bottom
            // button. Explicit Bottom and finger-up bottom recovery still own
            // bottom alignment; tap-to-type must stay visually calm.
            cancelViewerTypingPositionRetries("composer-tap-up");
            return;
        }
        if ("live-bottom".equals(reason)) {
            scrollViewerToTypingPositionOnce("composer-live-bottom", 260);
            return;
        }
        scrollViewerToTypingPositionSoon("composer-" + reason);
    }

    private void resetPromptComposerLocalDraftForCurrentTarget() {
        if (promptComposerInput == null) {
            promptComposerDraftTargetKey = promptComposerTargetKey();
            promptComposerDraftLocalGeneration++;
            return;
        }
        String targetKey = promptComposerTargetKey();
        if (!TextUtils.equals(targetKey, promptComposerDraftTargetKey)) {
            saveVisiblePromptComposerDraft();
        }
        // WHY: BUG #23 (draft refilled after send) — the durable SharedPreferences
        // draft was re-painted into the composer on every target-reset/open, so a
        // just-sent body reappeared in the box (the v210/v211 "forget" was a no-op
        // behind the install-safety seal early-return). Open EMPTY on target-reset:
        // the durable store is still written elsewhere for crash-safety, but this
        // restore path no longer re-shows an already-handled body. The queue-admission
        // handling below is preserved (an empty draft is never treated as queued).
        String targetDraft = "";
        long targetDraftRevision = rememberedPromptComposerDraftRevision(targetKey);
        boolean queuedPlaceholder = promptComposerDraftIsAlreadyQueued(
                targetKey,
                targetDraft,
                targetDraftRevision
        );
        if (queuedPlaceholder) {
            // WHY: queue admission clears only the visible editor. Keep the
            // SharedPreferences copy until server truth, but do not
            // repaint that same queued body as a fresh draft while this process
            // still owns its immutable operation.
            targetDraft = "";
        }
        PromptComposerDraftSelection selection = rememberedPromptComposerDraftSelection(
                targetKey,
                targetDraftRevision,
                targetDraft.length()
        );
        PromptComposerDraftRestore restore = new PromptComposerDraftRestore(
                targetKey,
                targetDraft,
                targetDraftRevision,
                queuedPlaceholder ? 0 : selection.start,
                queuedPlaceholder ? 0 : selection.end,
                queuedPlaceholder
        );
        applyPromptComposerDraftRestore(restore, "target-reset");
    }

    private boolean applyPromptComposerDraftRestore(
            PromptComposerDraftRestore restore,
            String reason
    ) {
        if (promptComposerInput == null || restore == null || !hasStableWindowId(restore.targetKey)) {
            return false;
        }
        String visibleDraft = promptComposerInput.getText().toString();
        boolean sameTargetAndBody = PromptComposerImeStatePolicy.sameTargetAndBody(
                promptComposerDraftTargetKey,
                restore.targetKey,
                visibleDraft,
                restore.displayDraft
        );
        if (sameTargetAndBody) {
            // WHY: resume and delayed focus reassertions must be state-neutral.
            // Keeping the same Editable untouched preserves its selection and
            // any IME-owned composing spans instead of collapsing the cursor.
            pendingPromptComposerDraftRestore = null;
            return true;
        }
        Editable editable = promptComposerInput.getText();
        if (PromptComposerImeStatePolicy.shouldDeferRestore(
                promptComposerHasActiveComposition(editable),
                sameTargetAndBody
        )) {
            // WHY: composing spans belong to the IME and current target. Never
            // transplant or destroy them while switching drafts; the real input
            // connection releases this exact target revision after composition.
            pendingPromptComposerDraftRestore = restore;
            Log.i(SEND_LOG_TAG,
                    "stage=composer-draft-restore result=deferred-composition"
                            + " target=" + safePromptSendTargetForLog(restore.targetKey)
                            + " reason=" + safeLogToken(reason));
            return false;
        }
        if (!promptComposerDraftRestoreStillCurrent(restore)) {
            if (pendingPromptComposerDraftRestore == restore) {
                pendingPromptComposerDraftRestore = null;
            }
            return false;
        }
        promptComposerProgrammaticTextChange = true;
        promptComposerInput.beginBatchEdit();
        try {
            // WHY: v2.80 cleared the native composer whenever Active switched.
            // Restore only the still-current target revision so per-window drafts
            // survive navigation without reviving wrong-window submission.
            // WHY: mutate the existing Editable rather than TextView.setText().
            // The IME retains one editor object; only a composition-free target
            // boundary may replace its characters and restore target-local range.
            if (!TextUtils.equals(editable.toString(), restore.displayDraft)) {
                editable.replace(0, editable.length(), restore.displayDraft);
            }
            int selectionStart = PromptComposerImeStatePolicy.clampSelection(
                    restore.selectionStart,
                    editable.length()
            );
            int selectionEnd = PromptComposerImeStatePolicy.clampSelection(
                    restore.selectionEnd,
                    editable.length()
            );
            Selection.setSelection(editable, selectionStart, selectionEnd);
        } finally {
            promptComposerInput.endBatchEdit();
            promptComposerProgrammaticTextChange = false;
        }
        promptComposerDraftTargetKey = restore.targetKey;
        promptComposerDraftLocalGeneration++;
        keepPromptComposerSelectionVisibleAfterLayout("draft-restore");
        if (pendingPromptComposerDraftRestore == restore) {
            pendingPromptComposerDraftRestore = null;
        }
        return true;
    }

    private boolean promptComposerDraftRestoreStillCurrent(
            PromptComposerDraftRestore restore
    ) {
        if (restore == null
                || !restore.targetKey.equals(promptComposerTargetKey())
                || !PromptComposerImeStatePolicy.callbackOwnsRestore(
                        restore.targetKey,
                        promptComposerTargetKey(),
                        restore.draftRevision,
                        rememberedPromptComposerDraftRevision(restore.targetKey)
                )) {
            return false;
        }
        String durableDraft = rememberedPromptComposerDraft(restore.targetKey);
        if (restore.queuedPlaceholder) {
            return restore.displayDraft.isEmpty()
                    && promptComposerDraftIsAlreadyQueued(
                            restore.targetKey,
                            durableDraft,
                            restore.draftRevision
                    );
        }
        return TextUtils.equals(durableDraft, restore.displayDraft);
    }

    private boolean promptComposerHasActiveComposition(Editable editable) {
        if (editable == null) {
            return false;
        }
        return BaseInputConnection.getComposingSpanStart(editable) >= 0
                || BaseInputConnection.getComposingSpanEnd(editable) >= 0;
    }

    private void releasePendingPromptComposerDraftRestoreAfterIme(String reason) {
        PromptComposerDraftRestore restore = pendingPromptComposerDraftRestore;
        if (restore == null || promptComposerInput == null) {
            return;
        }
        promptComposerInput.post(() -> {
            if (pendingPromptComposerDraftRestore != restore
                    || promptComposerHasActiveComposition(promptComposerInput.getText())) {
                return;
            }
            applyPromptComposerDraftRestore(restore, reason);
        });
    }

    private boolean promptComposerDraftIsAlreadyQueued(
            String targetKey,
            String targetDraft,
            long targetDraftRevision
    ) {
        if (!hasStableWindowId(targetKey)
                || targetDraft == null
                || targetDraft.isEmpty()
                || targetDraftRevision <= 0) {
            return false;
        }
        String stableTargetKey = targetKey.trim();
        for (PromptComposerQueuedSubmit submit : promptComposerSubmitQueue) {
            if (submit != null
                    && stableTargetKey.equals(submit.stableTargetKey)
                    && targetDraft.equals(submit.value)
                    && submit.draftRevision == targetDraftRevision) {
                return true;
            }
        }
        return false;
    }

    private void clearUnsentDraft() {
        if (promptComposerInput == null) {
            toast("No draft to clear");
            return;
        }
        String visibleDraft = promptComposerInput.getText().toString();
        if (visibleDraft.isEmpty()) {
            toast("No draft to clear");
            return;
        }
        promptComposerDraftLocalGeneration++;
        promptComposerProgrammaticTextChange = true;
        try {
            promptComposerInput.setText("");
        } finally {
            promptComposerProgrammaticTextChange = false;
        }
        forgetPromptComposerDraft(promptComposerDraftTargetKey);
        promptComposerDraftTargetKey = promptComposerTargetKey();
        // WHY: Clear now only clears the visible native composer. It must not send
        // a calculated `/draft-delta` backspace into tmux, because normal phone typing is local-only now
        // and is no longer mirrored there. If a stale tmux prompt exists from
        // an older build or hidden xterm path, empty-composer Backspace/Delete and
        // Option keys send literal tmux keys as an explicit recovery action.
        toast("Draft cleared");
    }

    private void saveVisiblePromptComposerDraft() {
        if (promptComposerInput == null) {
            return;
        }
        String targetKey = hasStableWindowId(promptComposerDraftTargetKey)
                ? promptComposerDraftTargetKey
                : promptComposerTargetKey();
        String visibleDraft = promptComposerInput.getText().toString();
        String persistedDraft = rememberedPromptComposerDraft(targetKey);
        long persistedRevision = rememberedPromptComposerDraftRevision(targetKey);
        if (TextUtils.equals(visibleDraft, persistedDraft)) {
            rememberPromptComposerDraftSelection(
                    targetKey,
                    persistedRevision,
                    promptComposerInput.getSelectionStart(),
                    promptComposerInput.getSelectionEnd(),
                    visibleDraft.length()
            );
            return;
        }
        if (visibleDraft.isEmpty()
                && promptComposerDraftIsAlreadyQueued(
                        targetKey,
                        persistedDraft,
                        persistedRevision
                )) {
            // WHY: reopening an in-flight Send deliberately renders an empty
            // editor so the user can type the next prompt. Hiding or switching
            // that untouched placeholder must not erase the queued draft before
            // acknowledged server truth.
            return;
        }
        long draftRevision = rememberPromptComposerDraft(targetKey, visibleDraft);
        rememberPromptComposerDraftSelection(
                targetKey,
                draftRevision,
                promptComposerInput.getSelectionStart(),
                promptComposerInput.getSelectionEnd(),
                visibleDraft.length()
        );
    }

    private long rememberPromptComposerDraft(String targetKey, String text) {
        if (prefs == null || !hasStableWindowId(targetKey)) {
            return 0L;
        }
        synchronized (promptDraftInstallSafetyLock) {
            if (promptDraftInstallSafetyWriterBlocked()) {
                return 0L;
            }
            String value = text == null ? "" : text;
            String key = promptComposerDraftPrefsKey(targetKey);
            long draftRevision = nextPromptComposerDraftRevisionLocked(targetKey);
            if (draftRevision <= 0L) {
                return 0L;
            }
            promptDraftInstallSafetyRevision++;
            SharedPreferences.Editor editor = prefs.edit();
            if (value.isEmpty()) {
                editor.remove(key);
            } else {
                editor.putString(key, value);
            }
            editor.putLong(promptComposerDraftRevisionPrefsKey(targetKey), draftRevision);
            editor.apply();
            return draftRevision;
        }
    }

    private long rememberPromptComposerDraftForSubmit(String targetKey, String text) {
        if (prefs == null || !hasStableWindowId(targetKey)) {
            return 0L;
        }
        synchronized (promptDraftInstallSafetyLock) {
            if (promptDraftInstallSafetyWriterBlocked()) {
                return 0L;
            }
            long currentRevision = rememberedPromptComposerDraftRevision(targetKey);
            if (currentRevision < 0L || currentRevision >= Long.MAX_VALUE - 1L) {
                return 0L;
            }
            // Reentrant lock ownership makes the revision reservation and the
            // body write one atomic admission step. MAX_VALUE remains available
            // for the definitive success/failure callback to consume ownership.
            return rememberPromptComposerDraft(targetKey, text);
        }
    }

    private String rememberedPromptComposerDraft(String targetKey) {
        if (prefs == null || !hasStableWindowId(targetKey)) {
            return "";
        }
        return prefs.getString(promptComposerDraftPrefsKey(targetKey), "");
    }

    private long rememberedPromptComposerDraftRevision(String targetKey) {
        if (prefs == null || !hasStableWindowId(targetKey)) {
            return -1L;
        }
        try {
            long revision = prefs.getLong(promptComposerDraftRevisionPrefsKey(targetKey), 0L);
            return revision < 0L ? -1L : revision;
        } catch (ClassCastException malformedRevision) {
            return -1L;
        }
    }

    private void rememberPromptComposerDraftSelection(
            String targetKey,
            long draftRevision,
            int selectionStart,
            int selectionEnd,
            int textLength
    ) {
        if (prefs == null || !hasStableWindowId(targetKey) || draftRevision < 0L) {
            return;
        }
        synchronized (promptDraftInstallSafetyLock) {
            if (promptDraftInstallSafetyWriterBlocked()) {
                return;
            }
            int start = PromptComposerImeStatePolicy.clampSelection(
                    selectionStart,
                    textLength
            );
            int end = PromptComposerImeStatePolicy.clampSelection(
                    selectionEnd,
                    textLength
            );
            promptDraftInstallSafetyRevision++;
            prefs.edit()
                    .putInt(promptComposerDraftSelectionStartPrefsKey(targetKey), start)
                    .putInt(promptComposerDraftSelectionEndPrefsKey(targetKey), end)
                    .putLong(
                            promptComposerDraftSelectionRevisionPrefsKey(targetKey),
                            draftRevision
                    )
                    .apply();
        }
    }

    private PromptComposerDraftSelection rememberedPromptComposerDraftSelection(
            String targetKey,
            long draftRevision,
            int textLength
    ) {
        int fallback = Math.max(0, textLength);
        if (prefs == null || !hasStableWindowId(targetKey) || draftRevision < 0L) {
            return new PromptComposerDraftSelection(draftRevision, fallback, fallback);
        }
        try {
            long selectionRevision = prefs.getLong(
                    promptComposerDraftSelectionRevisionPrefsKey(targetKey),
                    -1L
            );
            if (selectionRevision != draftRevision) {
                return new PromptComposerDraftSelection(draftRevision, fallback, fallback);
            }
            return new PromptComposerDraftSelection(
                    draftRevision,
                    PromptComposerImeStatePolicy.clampSelection(
                            prefs.getInt(promptComposerDraftSelectionStartPrefsKey(targetKey), fallback),
                            textLength
                    ),
                    PromptComposerImeStatePolicy.clampSelection(
                            prefs.getInt(promptComposerDraftSelectionEndPrefsKey(targetKey), fallback),
                            textLength
                    )
            );
        } catch (ClassCastException malformedSelection) {
            return new PromptComposerDraftSelection(draftRevision, fallback, fallback);
        }
    }

    private boolean forgetPromptComposerDraft(String targetKey) {
        if (prefs == null || !hasStableWindowId(targetKey)) {
            return false;
        }
        synchronized (promptDraftInstallSafetyLock) {
            if (promptDraftInstallSafetyWriterBlocked()) {
                return false;
            }
            long draftRevision = nextPromptComposerDraftRevisionLocked(targetKey);
            if (draftRevision <= 0L) {
                return false;
            }
            promptDraftInstallSafetyRevision++;
            prefs.edit()
                    .remove(promptComposerDraftPrefsKey(targetKey))
                    .remove(promptComposerDraftSelectionStartPrefsKey(targetKey))
                    .remove(promptComposerDraftSelectionEndPrefsKey(targetKey))
                    .remove(promptComposerDraftSelectionRevisionPrefsKey(targetKey))
                    .putLong(promptComposerDraftRevisionPrefsKey(targetKey), draftRevision)
                    .apply();
            return true;
        }
    }

    private long nextPromptComposerDraftRevisionLocked(String targetKey) {
        long currentRevision = rememberedPromptComposerDraftRevision(targetKey);
        if (currentRevision < 0L || currentRevision >= Long.MAX_VALUE) {
            return 0L;
        }
        return currentRevision + 1L;
    }

    private String promptComposerDraftPrefsKey(String targetKey) {
        return PREF_PROMPT_DRAFT_PREFIX + targetKey.trim();
    }

    private String promptComposerDraftRevisionPrefsKey(String targetKey) {
        return PREF_PROMPT_DRAFT_REVISION_PREFIX + targetKey.trim();
    }

    private String promptComposerDraftSelectionStartPrefsKey(String targetKey) {
        return PREF_PROMPT_DRAFT_SELECTION_START_PREFIX + targetKey.trim();
    }

    private String promptComposerDraftSelectionEndPrefsKey(String targetKey) {
        return PREF_PROMPT_DRAFT_SELECTION_END_PREFIX + targetKey.trim();
    }

    private String promptComposerDraftSelectionRevisionPrefsKey(String targetKey) {
        return PREF_PROMPT_DRAFT_SELECTION_REVISION_PREFIX + targetKey.trim();
    }

    private void submitDockedPromptText(String text) {
        submitDockedPromptText(text, "");
    }

    private void submitDockedPromptText(String text, String successToast) {
        submitDockedPromptText(text, successToast, promptComposerDraftSubmitTargetKey());
    }

    private void submitDockedPromptText(String text, String successToast, String targetKey) {
        submitDockedPromptText(text, successToast, targetKey, null, null);
    }

    private void submitDockedPromptText(
            String text,
            String successToast,
            String targetKey,
            Runnable afterSuccess,
            Runnable afterFailure
    ) {
        String value = text == null ? "" : text;
        if (value.trim().isEmpty()) {
            toast("Prompt is empty");
            if (afterFailure != null) {
                afterFailure.run();
            }
            return;
        }
        // WHY: toolbar Send is the only submit owner for phone text. The previous
        // live-mirror design pasted drafts through `/draft-delta` while the user
        // was still composing, then only sent Enter here; that repeatedly caused
        // duplicate words, invisible stale tmux drafts, and wrong-tab paste after
        // Active switching. Send must paste the complete visible native composer
        // text once through `/submit-text`, which also presses Enter once.
        submitSafePrompt(value, successToast, targetKey, afterSuccess, afterFailure);
    }

    private void settleLiveBottomAfterSend(String reason) {
        long generation = terminalModeGeneration;
        long touchGeneration = terminalTouchGestureGeneration;
        liveInputVisibilityGeneration++;
        cancelViewerTypingPositionRetries(reason);
        uiHandler.postDelayed(() -> {
            if (!shouldRunPostSendRendererSettle(generation, touchGeneration)) {
                return;
            }
            // WHY: `/submit-text?resize=0` and `/send-enter` already move tmux to
            // live bottom before pressing Enter. A second delayed `/live-bottom`
            // request here timed out for several seconds and could still complete
            // after the user started one-finger reading, snapping the viewport back
            // to the bottom and raising false unreachable toasts. Post-Send settle is
            // therefore renderer-only and is canceled by any newer terminal touch.
            Log.i(CONTROL_LOG_TAG,
                    "stage=post-send-settle endpoint=renderer"
                            + " reason=" + safeLogToken(reason)
                            + " result=renderer-only");
            pinTerminalViewportLocal();
            refreshCaptureRendererForPostSendTransition(reason + "-post-send", generation, touchGeneration);
            if (shouldPreserveZoomedViewerForPassiveBottom(reason)) {
                cancelViewerTypingPositionRetries(reason + "-preserve-zoomed-send");
            } else {
                scrollViewerToTypingPositionOnce(reason, 180);
            }
            scheduleToolbarStatusDotRefresh(150);
        }, 120);
    }

    private boolean shouldRunPostSendRendererSettle(long generation, long touchGeneration) {
        return generation == terminalModeGeneration
                && touchGeneration == terminalTouchGestureGeneration
                && !readModeSuppressesKeyboard
                && !terminalHistoryViewportActive
                && !terminalHistoryDragActive;
    }

    private void refreshCaptureRendererForPostSendTransition(String reason, long generation, long touchGeneration) {
        refreshCaptureRendererPulseIfPostSendCurrent(reason, generation, touchGeneration);
        uiHandler.postDelayed(
                () -> refreshCaptureRendererPulseIfPostSendCurrent(
                        reason + "-composer-settle-1",
                        generation,
                        touchGeneration
                ),
                180
        );
        uiHandler.postDelayed(
                () -> refreshCaptureRendererPulseIfPostSendCurrent(
                        reason + "-composer-settle-2",
                        generation,
                        touchGeneration
                ),
                520
        );
    }

    private void refreshCaptureRendererPulseIfPostSendCurrent(String reason, long generation, long touchGeneration) {
        if (!shouldRunPostSendRendererSettle(generation, touchGeneration)) {
            return;
        }
        refreshCaptureRendererPulse(reason);
    }

    private void submitDockedPrompt() {
        if (promptComposerInput == null || !isDockedPromptComposerVisible()) {
            // WHY: IMEs may deliver a stale editor-action callback after the
            // first callback synchronously hides the composer. Hidden editor
            // state is not a new user activation and must never become raw Enter
            // or allocate another POST identity.
            Log.i(SEND_LOG_TAG, "stage=hidden-composer-submit-rejected");
            return;
        }
        String text = promptComposerInput.getText().toString();
        if (text.trim().length() == 0) {
            // WHY: empty native composer Send/Enter confirms terminal menus.
            // The real APK screenshot showed a Codex numbered prompt waiting for
            // Enter while Samsung Enter and the visible Send button appeared to do
            // nothing. Nonempty text still uses `/submit-text`; only an empty
            // composer maps to the terminal's plain Enter confirmation.
            sendEnterToTerminal();
            return;
        }
        String stableTargetKey = promptComposerDraftSubmitTargetKey();
        PromptComposerVisibleSubmitIntent submitIntent =
                visiblePromptComposerSubmitIntent(stableTargetKey);
        if (submitIntent == null) {
            toast("Session target is not ready");
            return;
        }
        submitDockedPromptText(
                text,
                "",
                stableTargetKey,
                null,
                null
        );
    }

    private PromptComposerVisibleSubmitIntent visiblePromptComposerSubmitIntent(
            String targetKey
    ) {
        if (!isDockedPromptComposerVisible() || !hasStableWindowId(targetKey)) {
            return null;
        }
        String stableTargetKey = targetKey.trim();
        long draftGeneration = promptComposerDraftLocalGeneration;
        if (promptComposerVisibleSubmitIntent != null
                && promptComposerVisibleSubmitIntent.owns(
                        draftGeneration,
                        stableTargetKey
                )) {
            return promptComposerVisibleSubmitIntent;
        }
        // WHY: one visible draft generation can surface through both an IME
        // editor action and a toolbar callback. Allocate one immutable UI intent
        // and one POST idempotency key for that generation so duplicate callbacks
        // converge; a later edit/reopen advances draftGeneration and gets a
        // distinct operation even when target and text happen to match.
        promptComposerVisibleSubmitIntent = createPromptComposerSubmitIntent(
                draftGeneration,
                stableTargetKey
        );
        return promptComposerVisibleSubmitIntent;
    }

    private PromptComposerVisibleSubmitIntent createPromptComposerSubmitIntent(
            long draftGeneration,
            String stableTargetKey
    ) {
        beginApkAction("send", stableTargetKey);
        String intentId = "composer-intent-" + UUID.randomUUID().toString();
        String idempotencyKey = "phone-submit-" + UUID.randomUUID().toString();
        return new PromptComposerVisibleSubmitIntent(
                draftGeneration,
                stableTargetKey,
                intentId,
                idempotencyKey,
                currentApkActionIdForLog(),
                currentApkTapIdForLog(),
                currentApkActionKindForLog()
        );
    }

    private void hideDockedPromptComposer(boolean clearText, boolean keepKeyboardState) {
        if (promptComposerBar == null || promptComposerInput == null) {
            return;
        }
        if (clearText) {
            forgetPromptComposerDraft(promptComposerDraftTargetKey);
            promptComposerProgrammaticTextChange = true;
            try {
                promptComposerInput.setText("");
            } finally {
                promptComposerProgrammaticTextChange = false;
            }
            promptComposerDraftTargetKey = promptComposerTargetKey();
            promptComposerDraftLocalGeneration++;
        } else {
            saveVisiblePromptComposerDraft();
        }
        promptComposerVisibilityGeneration++;
        promptComposerInput.clearFocus();
        promptComposerBar.setVisibility(View.GONE);
        updateStartButtonLabel();
        if (!keepKeyboardState) {
            InputMethodManager inputMethodManager =
                    (InputMethodManager) getSystemService(Context.INPUT_METHOD_SERVICE);
            if (inputMethodManager != null) {
                inputMethodManager.hideSoftInputFromWindow(promptComposerInput.getWindowToken(), 0);
            }
            hideTerminalKeyboardQuietly("composer-hide");
        }
        refreshCaptureRendererForComposerTransition("composer-hide");
    }

    private void updateStartButtonLabel() {
        if (startToolbarButton == null || promptComposerBar == null) {
            return;
        }
        startToolbarButton.setText(promptComposerBar.getVisibility() == View.VISIBLE ? "Send" : "Start");
        boolean composerVisible = promptComposerBar.getVisibility() == View.VISIBLE;
        String targetKey = composerVisible ? promptComposerTargetKey() : "";
        boolean sendControlEnabled = ActiveSwitchTitleLifecycle.promptComposerLocalSendControlEnabled(
                composerVisible,
                hasStableWindowId(targetKey)
        );
        startToolbarButton.setEnabled(sendControlEnabled);
        if (!composerVisible) {
            promptComposerSendControlEnabledKnown = false;
            promptComposerSendControlEnabled = true;
        } else if (!promptComposerSendControlEnabledKnown
                || promptComposerSendControlEnabled != sendControlEnabled) {
            PromptComposerSendLifecycle lifecycle = PromptComposerSendLifecycle.start(
                    targetKey,
                    SystemClock.elapsedRealtime()
            );
            recordPromptComposerSendLifecycle(
                    lifecycle,
                    PromptComposerSendLifecyclePhase.CONTROL_ENTRY,
                    sendControlEnabled
                            ? PromptComposerSendLifecycleDisposition.CONTROL_ENABLED
                            : PromptComposerSendLifecycleDisposition.CONTROL_DISABLED,
                    promptComposerSubmitInFlight,
                    promptComposerSubmitQueue.size(),
                    promptComposerSubmitInFlight,
                    promptComposerSubmitQueue.size(),
                    ""
            );
            promptComposerSendControlEnabledKnown = true;
            promptComposerSendControlEnabled = sendControlEnabled;
        }
        // WHY: keep the toolbar layout in lock-step with composer visibility. The
        // Send/Start label already toggles here after every composer show/hide
        // (setVisibility is always followed by updateStartButtonLabel), so this is
        // the single chokepoint that reasserts both action rows after every IME or
        // title/session relayout.
        applyToolbarComposerLayout();
    }

    private void applyToolbarComposerLayout() {
        // WHY: v226 hid New/Old/Active/Bottom whenever the IME opened, forcing the
        // user to back out of a draft just to switch sessions or return to Bottom.
        // Keep both toolbar rows at the accepted 92dp during typing; adjustResize
        // already owns the keyboard pixels. The composer + replaces only the old
        // standalone Upload button, while every other action remains visible.
        if (bottomToolbar == null) {
            return;
        }
        toolbarBaseHeightDp = TOOLBAR_HEIGHT_DP;
        if (toolbarNavRow != null && toolbarNavRow.getVisibility() != View.VISIBLE) {
            toolbarNavRow.setVisibility(View.VISIBLE);
        }
        int desiredHeightPx = dp(toolbarBaseHeightDp) + lastNavigationBarInsetBottom;
        ViewGroup.LayoutParams params = bottomToolbar.getLayoutParams();
        if (params != null && params.height != desiredHeightPx) {
            params.height = desiredHeightPx;
            bottomToolbar.setLayoutParams(params);
        }
    }

    private boolean isDockedPromptComposerVisible() {
        return promptComposerBar != null && promptComposerBar.getVisibility() == View.VISIBLE;
    }

    private void restoreDockedPromptComposerFocus(String reason) {
        if (promptComposerBar == null || promptComposerInput == null || !isDockedPromptComposerVisible()) {
            return;
        }
        // WHY: Android only honors soft-input requests for the focused view in a
        // focused window. Resume/window-focus/page-finished callbacks used to probe
        // xterm after the native composer was visible, which could leave typing
        // attached to a hidden WebView textarea while the phone composer looked
        // missing or stale. Preserve the native EditText as the single typing owner.
        promptComposerBar.setVisibility(View.VISIBLE);
        updateStartButtonLabel();
        boolean alreadyFocused = promptComposerInput.hasFocus();
        boolean imeAlreadyVisibleForComposer = alreadyFocused && lastImeInsetBottom > 0;
        if (!alreadyFocused) {
            promptComposerInput.requestFocus();
        }
        InputMethodManager inputMethodManager =
                (InputMethodManager) getSystemService(Context.INPUT_METHOD_SERVICE);
        long now = System.currentTimeMillis();
        if (inputMethodManager != null
                && !imeAlreadyVisibleForComposer
                && now - lastPromptComposerShowSoftInputAtMs >= PROMPT_COMPOSER_SOFT_INPUT_MIN_INTERVAL_MS) {
            // WHY: the native composer owns phone typing, but repeated `showSoftInput` calls
            // during the 120/360 ms settle callbacks can still ask Samsung/Gboard/voice
            // input to reconnect to the same visible editor.
            // That is the same duplicate-composition class the old xterm textarea
            // focus loop caused, so one bounded request is enough while the IME is
            // already visible or was just requested.
            lastPromptComposerShowSoftInputAtMs = now;
            inputMethodManager.showSoftInput(promptComposerInput, InputMethodManager.SHOW_IMPLICIT);
        }
        keepPromptComposerSelectionVisibleAfterLayout("focus-" + reason);
    }

    private void schedulePromptComposerHiddenImeRecovery(String reason) {
        schedulePromptComposerHiddenImeRecovery(reason, 0);
    }

    private void schedulePromptComposerHiddenImeRecovery(String reason, long delayMs) {
        EditText expectedInput = promptComposerInput;
        if (expectedInput == null) {
            return;
        }
        long composerGeneration = promptComposerVisibilityGeneration;
        long recoverySerial = ++promptComposerHiddenImeRecoverySerial;
        Runnable recovery = () -> runPromptComposerHiddenImeRecovery(
                expectedInput,
                reason,
                composerGeneration,
                recoverySerial
        );
        if (delayMs > 0) {
            expectedInput.postDelayed(recovery, delayMs);
        } else {
            expectedInput.postOnAnimation(recovery);
        }
    }

    private void runPromptComposerHiddenImeRecovery(
            EditText expectedInput,
            String reason,
            long composerGeneration,
            long recoverySerial
    ) {
        if (recoverySerial != promptComposerHiddenImeRecoverySerial
                || composerGeneration != promptComposerVisibilityGeneration) {
            return;
        }
        Window window = getWindow();
        View decor = window == null ? null : window.getDecorView();
        boolean inputCurrent = promptComposerInput == expectedInput;
        boolean composerVisible = inputCurrent
                && isDockedPromptComposerVisible()
                && expectedInput.isShown();
        boolean inputAttached = expectedInput.getWindowToken() != null;
        boolean windowFocused = decor != null && decor.hasWindowFocus();
        boolean inputFocused = expectedInput.hasFocus();
        int imeInsetBottom = lastImeInsetBottom;
        if (!activityResumed
                || !composerVisible
                || !inputAttached
                || !windowFocused
                || !inputFocused
                || imeInsetBottom > 0) {
            Log.i(CONTROL_LOG_TAG,
                    "stage=prompt-composer-ime-recovery"
                            + " result=skipped"
                            + " reason=" + safeLogToken(reason)
                            + " generation=" + composerGeneration
                            + " imeInsetBottom=" + imeInsetBottom
                            + " activityResumed=" + activityResumed
                            + " composerVisible=" + composerVisible
                            + " inputAttached=" + inputAttached
                            + " windowFocused=" + windowFocused
                            + " inputFocused=" + inputFocused);
            return;
        }
        InputMethodManager inputMethodManager =
                (InputMethodManager) getSystemService(Context.INPUT_METHOD_SERVICE);
        if (inputMethodManager == null) {
            Log.i(CONTROL_LOG_TAG,
                    "stage=prompt-composer-ime-recovery"
                            + " result=skipped-no-input-method"
                            + " reason=" + safeLogToken(reason)
                            + " generation=" + composerGeneration
                            + " imeInsetBottom=" + imeInsetBottom);
            return;
        }
        // WHY(v274 hidden-IME recovery): only this proven focused-editor/hidden-
        // inset boundary may invalidate the stale 900 ms request timestamp. Re-arm
        // it immediately after one show request so no settle callback can loop or
        // create a second IME/composition owner.
        lastPromptComposerShowSoftInputAtMs = 0;
        boolean showAccepted = inputMethodManager.showSoftInput(
                expectedInput,
                InputMethodManager.SHOW_IMPLICIT
        );
        lastPromptComposerShowSoftInputAtMs = System.currentTimeMillis();
        Log.i(CONTROL_LOG_TAG,
                "stage=prompt-composer-ime-recovery"
                        + " result=requested"
                        + " reason=" + safeLogToken(reason)
                        + " generation=" + composerGeneration
                        + " imeInsetBottom=" + imeInsetBottom
                        + " showAccepted=" + showAccepted);
    }

    private void keepPromptComposerSelectionVisibleAfterLayout(String reason) {
        if (!(promptComposerInput instanceof PromptComposerEditText)) {
            return;
        }
        ((PromptComposerEditText) promptComposerInput)
                .keepActiveSelectionVisibleAfterLayout(reason);
    }

    private void reassertDockedPromptComposerFocus(String reason, long composerGeneration, long delayMs) {
        uiHandler.postDelayed(() -> {
            if (composerGeneration != promptComposerVisibilityGeneration
                    || !activityResumed
                    || !isDockedPromptComposerVisible()) {
                return;
            }
            restoreDockedPromptComposerFocus(reason + "-settle");
        }, delayMs);
    }

    private void hideDockedPromptComposerForSessionSwitch(String reason) {
        if (!isDockedPromptComposerVisible()) {
            hideTerminalKeyboardQuietly(reason);
            return;
        }
        // WHY: Active Sessions row taps are navigation, not typing. If the
        // docked native composer stays focused while Android switches tabs, the
        // IME keeps WebView resized and the toolbar remains in Send mode, exposing
        // the dotted xterm canvas the user reported. Hide the composer and IME on
        // successful selection, but do not clear text; an unsent draft is user
        // input and must not be destroyed by a tab switch.
        liveInputVisibilityGeneration++;
        cancelViewerTypingPositionRetries(reason);
        hideDockedPromptComposer(false, false);
    }

    private void settlePassiveNavigationInputIfStillOwned(String reason) {
        boolean composerVisible = isDockedPromptComposerVisible();
        if (terminalTouchStartedInTerminalBody || composerVisible) {
            // WHY(v274 passive-input ownership): delayed session-switch cleanup
            // belongs only to the navigation action that scheduled it. A fresh
            // terminal DOWN or a newly visible composer proves that local input
            // has taken ownership, so the old callback may not hide its IME or
            // re-arm the passive body-tap suppression window.
            Log.i(CONTROL_LOG_TAG,
                    "stage=passive-input-cleanup"
                            + " result=skipped-fresh-input"
                            + " reason=" + safeLogToken(reason)
                            + " terminalBodyTouch="
                            + terminalTouchStartedInTerminalBody
                            + " composerVisible=" + composerVisible);
            return;
        }
        hideDockedPromptComposerForSessionSwitch(reason);
        suppressTerminalBodyTapForPassiveNavigation(reason);
    }

    private void suppressTerminalBodyTapForPassiveNavigation(String reason) {
        // WHY: opening Active/Old/Crashed/New is navigation, not typing. The
        // recurring real-phone failure was one passive tab switch bringing back
        // three separate bugs at once: ACTION_UP fell through from the picker and
        // reopened the native composer, the toolbar stayed on Send/keyboard, and
        // xterm painted dotted stale rows instead of the same full-height bottom
        // state the manual Bottom button gives. Suppress stale terminal-body
        // releases and hidden-textarea focus callbacks through the async select +
        // bottom settle window; a fresh terminal ACTION_DOWN clears this timeout so
        // the next deliberate tap still opens the native composer normally.
        terminalBodyTapSuppressedUntilMs = Math.max(
                terminalBodyTapSuppressedUntilMs,
                System.currentTimeMillis() + PASSIVE_NAVIGATION_TOUCH_SUPPRESS_MS
        );
        terminalFocusGeneration++;
        hideTerminalKeyboardQuietly(reason);
    }

    private void hideDockedPromptComposerForReadMode(String reason) {
        if (!isDockedPromptComposerVisible()) {
            hideTerminalKeyboardQuietly(reason);
            return;
        }
        // WHY: scrollback/history is reading, not typing. Leaving the docked
        // composer visible while tmux is in copy-mode shrinks the terminal,
        // leaves Start labeled as Send, and makes the phone look like the
        // scrollback area is not displaying properly. Hide the composer and IME
        // before read mode takes over, but keep any draft text for the next
        // deliberate typing action.
        liveInputVisibilityGeneration++;
        cancelViewerTypingPositionRetries(reason);
        hideDockedPromptComposer(false, false);
    }

    private void hideDockedPromptComposerForNavigation(String reason) {
        if (!isDockedPromptComposerVisible()) {
            hideTerminalKeyboardQuietly(reason);
            return;
        }
        // WHY: picker/dialog actions are navigation or reading, not prompt
        // composition. If Active/Old/Scroll opens while the native composer is
        // focused, Android keeps the IME up, shrinks the terminal/dialog, and can
        // make session rows or scrollback look clipped. Hide the composer before
        // opening the dialog, but preserve the draft so the user's typed text
        // returns on the next deliberate typing tap.
        terminalFocusGeneration++;
        liveInputVisibilityGeneration++;
        cancelViewerTypingPositionRetries(reason);
        hideDockedPromptComposer(false, false);
    }

    private PromptComposerSendLifecycle recordPromptComposerSendLifecycle(
            PromptComposerSendLifecycle lifecycle,
            PromptComposerSendLifecyclePhase phase,
            PromptComposerSendLifecycleDisposition disposition,
            boolean inFlightBefore,
            int queueSizeBefore,
            boolean inFlightAfter,
            int queueSizeAfter,
            String idempotencyRef
    ) {
        if (lifecycle == null) {
            return null;
        }
        // WHY: a controller-absent second Send cannot be repaired safely until
        // Android gives every user event one immutable, evaluable disposition.
        // This telemetry never owns delivery or clears/resets the queue; it only
        // snapshots the state that the existing Send owner already chose.
        PromptComposerSendLifecycle next = lifecycle.transition(
                phase,
                disposition,
                inFlightBefore,
                queueSizeBefore,
                inFlightAfter,
                queueSizeAfter,
                idempotencyRef,
                SystemClock.elapsedRealtime()
        );
        Log.i(SEND_LOG_TAG, next.lastRecord.toSafeLogFields());
        return next;
    }

    private void submitSafePrompt(String text) {
        submitSafePrompt(text, "");
    }

    private void submitSafePrompt(String text, String successToast) {
        submitSafePrompt(text, successToast, promptComposerTargetKey());
    }

    private void submitSafePrompt(String text, String successToast, String targetKey) {
        submitSafePrompt(text, successToast, targetKey, null, null);
    }

    private void submitSafePrompt(
            String text,
            String successToast,
            String targetKey,
            Runnable afterSuccess,
            Runnable afterFailure
    ) {
        String value = text == null ? "" : text;
        String lifecycleTargetKey = hasStableWindowId(targetKey) ? targetKey.trim() : "unstable";
        PromptComposerSendLifecycle sendLifecycle = PromptComposerSendLifecycle.start(
                lifecycleTargetKey,
                SystemClock.elapsedRealtime()
        );
        int entryQueueSize = promptComposerSubmitQueue.size();
        sendLifecycle = recordPromptComposerSendLifecycle(
                sendLifecycle,
                PromptComposerSendLifecyclePhase.CONTROL_ENTRY,
                PromptComposerSendLifecycleDisposition.ENTERED,
                promptComposerSubmitInFlight,
                entryQueueSize,
                promptComposerSubmitInFlight,
                entryQueueSize,
                ""
        );
        if (value.trim().isEmpty()) {
            sendLifecycle = recordPromptComposerSendLifecycle(
                    sendLifecycle,
                    PromptComposerSendLifecyclePhase.PRE_GATE,
                    PromptComposerSendLifecycleDisposition.EMPTY_BLOCKED,
                    promptComposerSubmitInFlight,
                    promptComposerSubmitQueue.size(),
                    promptComposerSubmitInFlight,
                    promptComposerSubmitQueue.size(),
                    ""
            );
            toast("Prompt is empty");
            if (afterFailure != null) {
                afterFailure.run();
            }
            return;
        }
        String stableTargetKey = hasStableWindowId(targetKey) ? targetKey.trim() : promptComposerTargetKey();
        PromptComposerVisibleSubmitIntent resolvedSubmitIntent =
                promptComposerVisibleSubmitIntent;
        if (resolvedSubmitIntent == null
                || !resolvedSubmitIntent.owns(
                        promptComposerDraftLocalGeneration,
                        stableTargetKey
                )) {
            resolvedSubmitIntent = createPromptComposerSubmitIntent(
                    promptComposerDraftLocalGeneration,
                    stableTargetKey
            );
        }
        String submitIdempotencyKey = resolvedSubmitIntent.idempotencyKey;
        if (activeSwitchSendNeedsBackendGate(stableTargetKey)) {
            sendLifecycle = recordPromptComposerSendLifecycle(
                    sendLifecycle,
                    PromptComposerSendLifecyclePhase.PRE_GATE,
                    PromptComposerSendLifecycleDisposition.ACTIVE_SWITCH_BLOCKED,
                    promptComposerSubmitInFlight,
                    promptComposerSubmitQueue.size(),
                    promptComposerSubmitInFlight,
                    promptComposerSubmitQueue.size(),
                    ""
            );
            Log.i(CONTROL_LOG_TAG,
                    "stage=queued endpoint=/submit-text"
                            + " reason=active-switch-delivery-backend-gated"
                            + " transitionGeneration=" + activeSwitchTitleLifecycle.generation()
                            + " windowId=" + safeWindowIdForControlLog(stableTargetKey)
                            + " disposition=" + safeLogToken(activeSwitchTitleLifecycle.disposition()));
        }
        // WHY: a stable row tap already pins target/body/key identity. Admit it
        // locally before frame settling so the user receives immediate feedback;
        // the central /submit-text owner still fails closed before paste+Enter
        // while the selected target is genuinely incoherent.
        markApkFirstLocalFeedback("send-local-queue", stableTargetKey);
        PromptComposerRequestContext requestContext = PromptComposerRequestContext.capture(
                resolvedSubmitIntent.actionId,
                resolvedSubmitIntent.tapId,
                resolvedSubmitIntent.actionKind,
                stableTargetKey,
                submitIdempotencyKey
        );
        if (sessionInteractionBlocksSend(stableTargetKey)) {
            sendLifecycle = recordPromptComposerSendLifecycle(
                    sendLifecycle,
                    PromptComposerSendLifecyclePhase.PRE_GATE,
                    PromptComposerSendLifecycleDisposition.SESSION_INTERACTION_BACKEND_GATED,
                    promptComposerSubmitInFlight,
                    promptComposerSubmitQueue.size(),
                    promptComposerSubmitInFlight,
                    promptComposerSubmitQueue.size(),
                    ""
            );
            // WHY REGRESSION LOCK: once the user has typed and tapped Send, APK
            // feedback must be immediate. Do not pre-block the local submit
            // queue from stale title/OAuth/session metadata; `/submit-text` is
            // the central sendability owner and still fails closed before tmux
            // paste/Enter if body/session continuity is unsafe. This preserves
            // wrong-pane safety without making the phone feel stuck before the
            // queued request even leaves Android.
            Log.i(CONTROL_LOG_TAG,
                    "stage=queued endpoint=/submit-text"
                            + " actionId=" + requestContext.actionId
                            + " tapId=" + requestContext.tapId
                            + " reason=session-interaction-state-backend-gated"
                            + " windowId=" + safeWindowIdForControlLog(stableTargetKey)
                            + " state=" + safeLogToken(lastSessionInteractionState)
                            + " sendableKnown=" + lastSessionInteractionSendableKnown
                            + " sendable=" + lastSessionInteractionSendable
                            + " blockedReason=" + safeLogToken(lastSessionInteractionBlockedReason));
        }
        // WHY REGRESSION LOCK: Send runs after this tap on background threads and
        // delayed retry callbacks. Reading process-global action/tap fields there
        // relabeled real `/submit-text` attempts as later scroll/Active work. Pin
        // only safe generated correlation plus the stable target and a one-way key
        // reference on the queued item; never copy prompt text or the raw key into
        // logs. PromptComposerImmutableRequestContextTest protects this boundary.
        String submitFingerprint = PromptComposerRapidOrderedSendBehavior.intentFingerprint(
                stableTargetKey,
                value,
                resolvedSubmitIntent.intentId
        );
        long generation = leaveReadModeForLiveInput();
        long sendStartedAtMs = SystemClock.elapsedRealtime();
        int submitChars = value.length();
        PromptComposerQueuedSubmit submit = new PromptComposerQueuedSubmit(
                stableTargetKey,
                value,
                0L,
                submitIdempotencyKey,
                resolvedSubmitIntent.intentId,
                submitFingerprint,
                successToast,
                afterSuccess,
                afterFailure,
                generation,
                sendStartedAtMs,
                submitChars,
                requestContext,
                sendLifecycle
        );
        enqueuePromptComposerSubmit(submit);
    }

    private boolean activeSwitchSendNeedsBackendGate(String targetKey) {
        return activeSwitchTitleLifecycle.blocksSendFor(targetKey);
    }

    private PromptComposerSubmitLedgerEntry promptComposerSubmitLedgerEntry(
            PromptComposerQueuedSubmit submit
    ) {
        if (submit == null || submit.requestContext == null) {
            return null;
        }
        return new PromptComposerSubmitLedgerEntry(
                submit.stableTargetKey,
                submit.value,
                submit.draftRevision,
                submit.submitIdempotencyKey,
                submit.submitIntentId,
                submit.submitFingerprint,
                submit.requestContext.actionId,
                submit.requestContext.tapId,
                submit.requestContext.actionKind,
                PROMPT_COMPOSER_SUBMIT_LEDGER_PENDING
        );
    }

    private boolean validPromptComposerSubmitLedgerEntry(
            PromptComposerSubmitLedgerEntry entry
    ) {
        if (entry == null
                || !entry.stableTargetKey.matches("^@[0-9]+$")
                || entry.value.trim().isEmpty()
                || entry.draftRevision <= 0L
                || !entry.submitIdempotencyKey.matches("^[A-Za-z0-9._:@-]{1,160}$")
                || !entry.submitIntentId.matches("^[A-Za-z0-9._:@-]{1,160}$")
                || entry.submitFingerprint.isEmpty()
                || !entry.actionId.matches("^[A-Za-z0-9._:@-]{1,96}$")
                || !entry.tapId.matches("^[A-Za-z0-9._:@-]{1,96}$")
                || !entry.actionKind.matches("^[A-Za-z0-9._:@-]{1,96}$")
                || (!PROMPT_COMPOSER_SUBMIT_LEDGER_PENDING.equals(entry.state)
                        && !PROMPT_COMPOSER_SUBMIT_LEDGER_FAILED.equals(entry.state))) {
            return false;
        }
        return entry.submitFingerprint.equals(
                PromptComposerRapidOrderedSendBehavior.intentFingerprint(
                        entry.stableTargetKey,
                        entry.value,
                        entry.submitIntentId
                )
        );
    }

    private void replacePromptComposerSubmitLedger(
            List<PromptComposerSubmitLedgerEntry> next
    ) {
        promptComposerSubmitLedger.clear();
        promptComposerSubmitLedger.addAll(
                PromptComposerSubmitLedgerBehavior.copy(next)
        );
    }

    private boolean persistPromptComposerSubmitLedger(
            List<PromptComposerSubmitLedgerEntry> next,
            PromptComposerQueuedSubmit successfulSubmit
    ) {
        if (prefs == null
                || next == null
                || next.size() > PROMPT_COMPOSER_SUBMIT_LEDGER_MAX_ENTRIES) {
            promptComposerSubmitLedgerBlocked = true;
            Log.e(SEND_LOG_TAG,
                    "stage=submit-ledger result=persist-blocked reason=invalid-size-or-store");
            return false;
        }
        JSONObject root = new JSONObject();
        JSONArray entries = new JSONArray();
        LinkedHashMap<String, Boolean> seenIntentIds = new LinkedHashMap<>();
        LinkedHashMap<String, Boolean> seenIdempotencyKeys = new LinkedHashMap<>();
        try {
            for (PromptComposerSubmitLedgerEntry entry : next) {
                if (!validPromptComposerSubmitLedgerEntry(entry)
                        || seenIntentIds.put(entry.submitIntentId, true) != null
                        || seenIdempotencyKeys.put(entry.submitIdempotencyKey, true) != null) {
                    promptComposerSubmitLedgerBlocked = true;
                    Log.e(SEND_LOG_TAG,
                            "stage=submit-ledger result=persist-blocked"
                                    + " reason=invalid-or-duplicate-entry");
                    return false;
                }
                JSONObject encoded = new JSONObject();
                encoded.put("target", entry.stableTargetKey);
                encoded.put("value", entry.value);
                encoded.put("draftRevision", entry.draftRevision);
                encoded.put("idempotencyKey", entry.submitIdempotencyKey);
                encoded.put("intentId", entry.submitIntentId);
                encoded.put("fingerprint", entry.submitFingerprint);
                encoded.put("actionId", entry.actionId);
                encoded.put("tapId", entry.tapId);
                encoded.put("actionKind", entry.actionKind);
                encoded.put("state", entry.state);
                entries.put(encoded);
            }
            root.put("version", PROMPT_COMPOSER_SUBMIT_LEDGER_VERSION);
            root.put("entries", entries);
        } catch (Exception encodeFailure) {
            promptComposerSubmitLedgerBlocked = true;
            Log.e(SEND_LOG_TAG,
                    "stage=submit-ledger result=persist-blocked reason=encode-failed",
                    encodeFailure);
            return false;
        }

        boolean committed = false;
        boolean draftClearedInCommit = false;
        synchronized (promptDraftInstallSafetyLock) {
            if (promptDraftInstallSafetyWriterBlocked()) {
                return false;
            }
            try {
                SharedPreferences.Editor editor = prefs.edit();
                if (next.isEmpty()) {
                    editor.remove(PREF_PROMPT_COMPOSER_SUBMIT_LEDGER);
                } else {
                    editor.putString(PREF_PROMPT_COMPOSER_SUBMIT_LEDGER, root.toString());
                }
                if (successfulSubmit != null) {
                    String stableTargetKey = successfulSubmit.stableTargetKey;
                    String persistedDraft =
                            rememberedPromptComposerDraft(stableTargetKey);
                    long persistedRevision =
                            rememberedPromptComposerDraftRevision(stableTargetKey);
                    if (PromptComposerRapidOrderedSendBehavior.shouldForgetSuccessfulDraft(
                            persistedDraft,
                            persistedRevision,
                            successfulSubmit.value,
                            successfulSubmit.draftRevision
                    )) {
                        long nextDraftRevision =
                                nextPromptComposerDraftRevisionLocked(stableTargetKey);
                        if (nextDraftRevision <= 0L) {
                            return false;
                        }
                        // WHY: success-ledger removal and its exactly-owned draft
                        // are one SharedPreferences transaction. Process death
                        // may observe both old or both new, never a delivered
                        // pending entry removed while its stale draft strands an
                        // older failed middle intent.
                        editor.remove(promptComposerDraftPrefsKey(stableTargetKey))
                                .remove(promptComposerDraftSelectionStartPrefsKey(
                                        stableTargetKey
                                ))
                                .remove(promptComposerDraftSelectionEndPrefsKey(
                                        stableTargetKey
                                ))
                                .remove(promptComposerDraftSelectionRevisionPrefsKey(
                                        stableTargetKey
                                ))
                                .putLong(
                                        promptComposerDraftRevisionPrefsKey(stableTargetKey),
                                        nextDraftRevision
                                );
                        draftClearedInCommit = true;
                    }
                }
                // WHY: this is the write-ahead boundary for an immutable Send.
                // A bounded synchronous commit must reach durable storage before
                // the HTTP queue can paste/Enter, so process recreation retries
                // only the same target/body/key instead of minting a duplicate.
                promptDraftInstallSafetyRevision++;
                committed = editor.commit();
            } catch (RuntimeException persistenceFailure) {
                Log.e(SEND_LOG_TAG,
                        "stage=submit-ledger result=persist-blocked"
                                + " reason=commit-exception",
                        persistenceFailure);
            }
        }
        if (!committed) {
            promptComposerSubmitLedgerBlocked = true;
            Log.e(SEND_LOG_TAG,
                    "stage=submit-ledger result=persist-blocked reason=commit-failed");
            return false;
        }
        if (successfulSubmit != null) {
            successfulSubmit.draftClearedInLedgerCommit = draftClearedInCommit;
        }
        return true;
    }

    private boolean persistPromptComposerSubmitLedger(
            List<PromptComposerSubmitLedgerEntry> next
    ) {
        return persistPromptComposerSubmitLedger(next, null);
    }

    private void restorePromptComposerSubmitLedger() {
        if (prefs == null) {
            promptComposerSubmitLedgerBlocked = true;
            return;
        }
        String encoded;
        try {
            encoded = prefs.getString(PREF_PROMPT_COMPOSER_SUBMIT_LEDGER, "");
        } catch (RuntimeException malformedPreference) {
            promptComposerSubmitLedgerBlocked = true;
            Log.e(SEND_LOG_TAG,
                    "stage=submit-ledger result=restore-blocked reason=wrong-pref-type",
                    malformedPreference);
            return;
        }
        if (encoded == null || encoded.trim().isEmpty()) {
            promptComposerSubmitLedgerBlocked = false;
            return;
        }

        ArrayList<PromptComposerSubmitLedgerEntry> restored = new ArrayList<>();
        LinkedHashMap<String, Boolean> seenIntentIds = new LinkedHashMap<>();
        LinkedHashMap<String, Boolean> seenIdempotencyKeys = new LinkedHashMap<>();
        try {
            Object parsed = new JSONTokener(encoded).nextValue();
            if (!(parsed instanceof JSONObject)) {
                throw new IllegalArgumentException("ledger-root");
            }
            JSONObject root = (JSONObject) parsed;
            if (root.optInt("version", -1)
                    != PROMPT_COMPOSER_SUBMIT_LEDGER_VERSION) {
                throw new IllegalArgumentException("ledger-version");
            }
            JSONArray entries = root.optJSONArray("entries");
            if (entries == null
                    || entries.length() > PROMPT_COMPOSER_SUBMIT_LEDGER_MAX_ENTRIES) {
                throw new IllegalArgumentException("ledger-size");
            }
            for (int index = 0; index < entries.length(); index++) {
                JSONObject stored = entries.optJSONObject(index);
                if (stored == null) {
                    throw new IllegalArgumentException("ledger-entry");
                }
                String state = stored.optString("state", "");
                if (!PROMPT_COMPOSER_SUBMIT_LEDGER_PENDING.equals(state)
                        && !PROMPT_COMPOSER_SUBMIT_LEDGER_FAILED.equals(state)) {
                    throw new IllegalArgumentException("ledger-state");
                }
                PromptComposerSubmitLedgerEntry entry =
                        new PromptComposerSubmitLedgerEntry(
                                stored.optString("target", ""),
                                stored.optString("value", ""),
                                stored.optLong("draftRevision", -1L),
                                stored.optString("idempotencyKey", ""),
                                stored.optString("intentId", ""),
                                stored.optString("fingerprint", ""),
                                stored.optString("actionId", ""),
                                stored.optString("tapId", ""),
                                stored.optString("actionKind", ""),
                                state
                        );
                if (!validPromptComposerSubmitLedgerEntry(entry)
                        || seenIntentIds.put(entry.submitIntentId, true) != null
                        || seenIdempotencyKeys.put(entry.submitIdempotencyKey, true) != null) {
                    throw new IllegalArgumentException("ledger-identity");
                }
                restored.add(entry);
            }
        } catch (Exception malformedLedger) {
            // WHY: malformed local recovery state cannot authorize a target,
            // body, or key. Keep every ordinary target-local draft intact and
            // fail closed instead of guessing or silently dropping an intent.
            promptComposerSubmitLedgerBlocked = true;
            Log.e(SEND_LOG_TAG,
                    "stage=submit-ledger result=restore-blocked reason=malformed",
                    malformedLedger);
            return;
        }

        replacePromptComposerSubmitLedger(restored);
        promptComposerSubmitLedgerBlocked = false;
        for (PromptComposerSubmitLedgerEntry entry : restored) {
            if (!PROMPT_COMPOSER_SUBMIT_LEDGER_PENDING.equals(entry.state)) {
                continue;
            }
            long startedAtMs = SystemClock.elapsedRealtime();
            PromptComposerRequestContext requestContext =
                    PromptComposerRequestContext.capture(
                            entry.actionId,
                            entry.tapId,
                            entry.actionKind,
                            entry.stableTargetKey,
                            entry.submitIdempotencyKey
                    );
            PromptComposerQueuedSubmit restoredSubmit = new PromptComposerQueuedSubmit(
                    entry.stableTargetKey,
                    entry.value,
                    entry.draftRevision,
                    entry.submitIdempotencyKey,
                    entry.submitIntentId,
                    entry.submitFingerprint,
                    "",
                    null,
                    null,
                    terminalModeGeneration,
                    startedAtMs,
                    entry.value.length(),
                    requestContext,
                    PromptComposerSendLifecycle.start(entry.stableTargetKey, startedAtMs)
            );
            promptComposerSubmitQueue.add(restoredSubmit);
            beginPromptComposerStatusFence(restoredSubmit);
        }
        LinkedHashMap<String, Boolean> failedTargets = new LinkedHashMap<>();
        for (PromptComposerSubmitLedgerEntry entry : restored) {
            if (PROMPT_COMPOSER_SUBMIT_LEDGER_FAILED.equals(entry.state)
                    && failedTargets.put(entry.stableTargetKey, true) == null) {
                restorePromptComposerFailedLedgerDraftIfAvailable(
                        entry.stableTargetKey,
                        "activity-recreation"
                );
            }
        }
        Log.i(SEND_LOG_TAG,
                "stage=submit-ledger result=restored"
                        + " entries=" + restored.size()
                        + " pending=" + promptComposerSubmitQueue.size());
    }

    private void enqueuePromptComposerSubmit(PromptComposerQueuedSubmit submit) {
        if (submit == null) {
            return;
        }
        boolean inFlightBefore = promptComposerSubmitInFlight;
        int queueSizeBefore = promptComposerSubmitQueue.size();
        if (isDuplicatePromptComposerSubmit(submit)) {
            // WHY: IME action and toolbar click can both fire for one visible Send.
            // Android IMEs can deliver both an editor-action callback and an
            // Enter key event for one visible Send.
            // Stacked-send support must accept distinct prompts while still ignoring
            // the same target+body+UI-intent fingerprint already active or queued, otherwise
            // one tap can paste the same text twice into Codex.
            submit.sendLifecycle = recordPromptComposerSendLifecycle(
                    submit.sendLifecycle,
                    PromptComposerSendLifecyclePhase.QUEUE_ADMISSION,
                    PromptComposerSendLifecycleDisposition.DUPLICATE_REJECTED,
                    inFlightBefore,
                    queueSizeBefore,
                    promptComposerSubmitInFlight,
                    promptComposerSubmitQueue.size(),
                    submit.requestContext.idempotencyRef
            );
            showToolbarControlPending(promptComposerSubmitPendingLabel());
            logPromptSendStage("duplicate-ignored",
                    submit.stableTargetKey,
                    submit.sendStartedAtMs,
                    submit.submitChars,
                    submit.requestContext);
            return;
        }
        if (promptComposerSubmitLedgerBlocked) {
            submit.sendLifecycle = recordPromptComposerSendLifecycle(
                    submit.sendLifecycle,
                    PromptComposerSendLifecyclePhase.QUEUE_ADMISSION,
                    PromptComposerSendLifecycleDisposition.CONTROL_DISABLED,
                    inFlightBefore,
                    queueSizeBefore,
                    promptComposerSubmitInFlight,
                    promptComposerSubmitQueue.size(),
                    submit.requestContext.idempotencyRef
            );
            toast("Send recovery is blocked; draft kept");
            if (submit.afterFailure != null) {
                submit.afterFailure.run();
            }
            return;
        }
        long submitDraftRevision = rememberPromptComposerDraftForSubmit(submit.stableTargetKey, submit.value);
        if (submitDraftRevision <= 0L) {
            submit.sendLifecycle = recordPromptComposerSendLifecycle(
                    submit.sendLifecycle,
                    PromptComposerSendLifecyclePhase.QUEUE_ADMISSION,
                    PromptComposerSendLifecycleDisposition.CONTROL_DISABLED,
                    inFlightBefore,
                    queueSizeBefore,
                    promptComposerSubmitInFlight,
                    promptComposerSubmitQueue.size(),
                    submit.requestContext.idempotencyRef
            );
            logPromptSendStage(
                    "draft-persistence-blocked",
                    submit.stableTargetKey,
                    submit.sendStartedAtMs,
                    submit.submitChars,
                    submit.requestContext
            );
            toast("Draft could not be saved; Send not started");
            if (submit.afterFailure != null) {
                submit.afterFailure.run();
            }
            return;
        }
        submit = submit.withDraftRevision(submitDraftRevision);
        PromptComposerSubmitLedgerEntry admittedLedgerEntry =
                promptComposerSubmitLedgerEntry(submit);
        ArrayList<PromptComposerSubmitLedgerEntry> nextLedger =
                PromptComposerSubmitLedgerBehavior.admit(
                        promptComposerSubmitLedger,
                        admittedLedgerEntry
                );
        if (admittedLedgerEntry == null
                || nextLedger.size() > PROMPT_COMPOSER_SUBMIT_LEDGER_MAX_ENTRIES
                || !persistPromptComposerSubmitLedger(nextLedger)) {
            submit.sendLifecycle = recordPromptComposerSendLifecycle(
                    submit.sendLifecycle,
                    PromptComposerSendLifecyclePhase.QUEUE_ADMISSION,
                    PromptComposerSendLifecycleDisposition.CONTROL_DISABLED,
                    inFlightBefore,
                    queueSizeBefore,
                    promptComposerSubmitInFlight,
                    promptComposerSubmitQueue.size(),
                    submit.requestContext.idempotencyRef
            );
            toast("Send recovery could not be saved; draft kept");
            if (submit.afterFailure != null) {
                submit.afterFailure.run();
            }
            return;
        }
        replacePromptComposerSubmitLedger(nextLedger);
        promptComposerSubmitQueue.add(submit);
        beginPromptComposerStatusFence(submit);
        submit.sendLifecycle = recordPromptComposerSendLifecycle(
                submit.sendLifecycle,
                PromptComposerSendLifecyclePhase.QUEUE_ADMISSION,
                inFlightBefore
                        ? PromptComposerSendLifecycleDisposition.QUEUED_BEHIND_IN_FLIGHT
                        : PromptComposerSendLifecycleDisposition.ADMITTED,
                inFlightBefore,
                queueSizeBefore,
                promptComposerSubmitInFlight,
                promptComposerSubmitQueue.size(),
                submit.requestContext.idempotencyRef
        );
        logPromptSendStage(promptComposerSubmitInFlight ? "queued-stacked" : "queued",
                submit.stableTargetKey,
                submit.sendStartedAtMs,
                submit.submitChars,
                submit.requestContext);
        if (isDockedPromptComposerVisible()) {
            // WHY: APK-STACKED-SEND-LAG-1135 needs the visible composer to
            // acknowledge immediately and become available for the next prompt even
            // while an older POST/model turn is still busy.
            // WHY: local Send acknowledgement cannot wait for network latency.
            // WHY: touch/scroll/send/stop are independent phone input lanes, so a
            // slow `/submit-text` must not make one-finger scroll, Stop, or another
            // prompt look blocked.
            // WHY: draft text and idempotency key are the safety boundary. The
            // draft survives failed sends without keeping the phone visually stuck;
            // its persisted per-window copy survives until definitive truth, while
            // the queued object suppresses that same text from looking unsent
            // when the user immediately opens a clean composer for the next prompt.
            hideDockedPromptComposerAfterQueuedSubmit(submit.stableTargetKey, submit.value);
            submit.sendLifecycle = recordPromptComposerSendLifecycle(
                    submit.sendLifecycle,
                    PromptComposerSendLifecyclePhase.LOCAL_FEEDBACK,
                    PromptComposerSendLifecycleDisposition.LOCAL_HIDDEN,
                    promptComposerSubmitInFlight,
                    promptComposerSubmitQueue.size(),
                    promptComposerSubmitInFlight,
                    promptComposerSubmitQueue.size(),
                    submit.requestContext.idempotencyRef
            );
            logPromptSendStage("local-hide",
                    submit.stableTargetKey,
                    submit.sendStartedAtMs,
                    submit.submitChars,
                    submit.requestContext);
        }
        showToolbarControlPending(promptComposerSubmitPendingLabel());
        drainPromptComposerSubmitQueue();
    }

    private boolean isDuplicatePromptComposerSubmit(PromptComposerQueuedSubmit submit) {
        return PromptComposerRapidOrderedSendBehavior.isDuplicate(
                submit,
                promptComposerSubmitInFlight,
                promptComposerSubmitFingerprint,
                promptComposerSubmitQueue
        );
    }

    private String promptComposerSubmitPendingLabel() {
        return promptComposerSubmitQueue.size() > 1 ? "Send queued" : "Send prompt";
    }

    private String promptComposerStatusOperationId(PromptComposerQueuedSubmit submit) {
        if (submit == null) {
            return "";
        }
        if (submit.requestContext != null
                && submit.requestContext.idempotencyRef != null
                && !submit.requestContext.idempotencyRef.trim().isEmpty()) {
            return submit.requestContext.idempotencyRef.trim();
        }
        return submit.submitIdempotencyKey == null
                ? ""
                : submit.submitIdempotencyKey.trim();
    }

    private void beginPromptComposerStatusFence(PromptComposerQueuedSubmit submit) {
        if (submit == null || !hasStableWindowId(submit.stableTargetKey)) {
            return;
        }
        String windowId = submit.stableTargetKey.trim();
        String baselineRevision = serverConfirmedStatusRevisionByWindow.get(windowId);
        if (baselineRevision == null || baselineRevision.trim().isEmpty()) {
            baselineRevision = sendStatusRevisionFence.lastAcceptedRevision(windowId);
        }
        // WHY: admission is the exact local event the user judges. Install this
        // target/idempotency fence before showToolbarControlPending schedules its
        // immediate /active reclaim, so a 67 ms pre-Send Ready response cannot
        // win either the toolbar or a newly opened Active Sessions row.
        sendStatusRevisionFence.begin(
                windowId,
                promptComposerStatusOperationId(submit),
                baselineRevision,
                submit.sendStartedAtMs
        );
    }

    private void hideDockedPromptComposerAfterQueuedSubmit(String stableTargetKey, String submittedValue) {
        if (promptComposerBar == null || promptComposerInput == null) {
            return;
        }
        String visibleValue = promptComposerInput.getText().toString();
        if (submittedValue != null && submittedValue.equals(visibleValue)) {
            promptComposerDraftLocalGeneration++;
            promptComposerProgrammaticTextChange = true;
            try {
                promptComposerInput.setText("");
            } finally {
                promptComposerProgrammaticTextChange = false;
            }
            // WHY: the post-send visible clear must ALSO forget the persisted
            // per-window draft for the just-submitted target. Without this, the
            // composer-transition target-reset (refreshCaptureRendererForComposerTransition
            // below -> resetPromptComposerLocalDraftForCurrentTarget) re-reads the
            // still-persisted draft body and repaints the sent text back into the
            // composer (the "draft reappears on send" regression). Kept INSIDE the
            // submittedValue.equals(visibleValue) guard so a NEW draft typed after
            // Send is preserved; failed-send recovery is unaffected because it
            // re-restores from the submit ledger (restorePromptComposerAfterFailedSubmit
            // -> restorePromptComposerFailedLedgerDraftIfAvailable). Mirrors the two
            // sibling clear paths: hideDockedPromptComposer (~8702) and
            // clearUnsentDraft (~8280). Uses stableTargetKey (the immutable target
            // this submit was created for; equals promptComposerDraftTargetKey.trim()
            // here via promptComposerDraftSubmitTargetKey since the composer had text),
            // so it forgets exactly the draft slot the target-reset would re-read.
            forgetPromptComposerDraft(stableTargetKey);
        }
        promptComposerDraftTargetKey = promptComposerTargetKey();
        promptComposerVisibilityGeneration++;
        promptComposerInput.clearFocus();
        promptComposerBar.setVisibility(View.GONE);
        // WHY: Send delivery/echo observation is asynchronous data work, not a
        // modal touch owner. Keep the normal terminal listener available so a
        // new scroll can supersede Send immediately, before terminal echo.
        hideHistoryTouchOverlayQuietly();
        updateStartButtonLabel();
        InputMethodManager inputMethodManager =
                (InputMethodManager) getSystemService(Context.INPUT_METHOD_SERVICE);
        if (inputMethodManager != null) {
            inputMethodManager.hideSoftInputFromWindow(promptComposerInput.getWindowToken(), 0);
        }
        hideTerminalKeyboardQuietly("composer-queued-submit");
        refreshCaptureRendererForComposerTransition("composer-queued-submit");
    }

    private void drainPromptComposerSubmitQueue() {
        if (promptComposerSubmitInFlight) {
            PromptComposerQueuedSubmit waitingSubmit = promptComposerSubmitQueue.peekLast();
            if (waitingSubmit != null) {
                waitingSubmit.sendLifecycle = recordPromptComposerSendLifecycle(
                        waitingSubmit.sendLifecycle,
                        PromptComposerSendLifecyclePhase.DRAIN,
                        PromptComposerSendLifecycleDisposition.DRAIN_BLOCKED_IN_FLIGHT,
                        true,
                        promptComposerSubmitQueue.size(),
                        true,
                        promptComposerSubmitQueue.size(),
                        waitingSubmit.requestContext.idempotencyRef
                );
            }
            return;
        }
        PromptComposerQueuedSubmit submit = PromptComposerRapidOrderedSendBehavior.nextToDrain(
                promptComposerSubmitInFlight,
                promptComposerSubmitQueue
        );
        if (submit == null) {
            return;
        }
        boolean inFlightBefore = promptComposerSubmitInFlight;
        int queueSizeBefore = promptComposerSubmitQueue.size();
        if (!beginPromptComposerSubmit(submit.submitFingerprint)) {
            submit.sendLifecycle = recordPromptComposerSendLifecycle(
                    submit.sendLifecycle,
                    PromptComposerSendLifecyclePhase.DRAIN,
                    PromptComposerSendLifecycleDisposition.DRAIN_BLOCKED_IN_FLIGHT,
                    inFlightBefore,
                    queueSizeBefore,
                    promptComposerSubmitInFlight,
                    promptComposerSubmitQueue.size(),
                    submit.requestContext.idempotencyRef
            );
            return;
        }
        submit.sendLifecycle = recordPromptComposerSendLifecycle(
                submit.sendLifecycle,
                PromptComposerSendLifecyclePhase.DRAIN,
                PromptComposerSendLifecycleDisposition.IN_FLIGHT_STARTED,
                inFlightBefore,
                queueSizeBefore,
                promptComposerSubmitInFlight,
                promptComposerSubmitQueue.size(),
                submit.requestContext.idempotencyRef
        );
        postPromptComposerSubmit(submit);
    }

    // WHY: callback-local clear/restore/toast hooks may run only when this
    // exact immutable FIFO head wins finalization. A boolean result keeps a
    // late duplicate from continuing after the finalizer's ownership recheck.
    private boolean completePromptComposerSubmit(PromptComposerQueuedSubmit submit) {
        if (submit == null) {
            return false;
        }
        boolean inFlightBefore = promptComposerSubmitInFlight;
        boolean ownedBefore = PromptComposerRapidOrderedSendBehavior.ownsFinalCallback(
                inFlightBefore,
                promptComposerSubmitFingerprint,
                submit,
                promptComposerSubmitQueue.peek()
        );
        int queueSizeBefore = promptComposerSubmitQueue.size();
        if (!ownedBefore) {
            submit.sendLifecycle = recordPromptComposerSendLifecycle(
                    submit.sendLifecycle,
                    PromptComposerSendLifecyclePhase.FINAL,
                    PromptComposerSendLifecycleDisposition.FINAL_STATE_MISMATCH,
                    inFlightBefore,
                    queueSizeBefore,
                    promptComposerSubmitInFlight,
                    promptComposerSubmitQueue.size(),
                    submit.requestContext.idempotencyRef
            );
            return false;
        }
        ArrayList<PromptComposerSubmitLedgerEntry> nextLedger =
                PromptComposerSubmitLedgerBehavior.removeExactSuccess(
                        promptComposerSubmitLedger,
                        submit
                );
        if (PromptComposerSubmitLedgerBehavior.exactEntry(
                promptComposerSubmitLedger,
                submit,
                PROMPT_COMPOSER_SUBMIT_LEDGER_PENDING
        ) == null || !persistPromptComposerSubmitLedger(nextLedger, submit)) {
            showToolbarControlPending("Saving send result");
            return false;
        }
        replacePromptComposerSubmitLedger(nextLedger);
        finishPromptComposerSubmit(submit.submitFingerprint);
        promptComposerSubmitQueue.remove(submit);
        submit.sendLifecycle = recordPromptComposerSendLifecycle(
                submit.sendLifecycle,
                PromptComposerSendLifecyclePhase.FINAL,
                PromptComposerSendLifecycleDisposition.SUCCEEDED,
                inFlightBefore,
                queueSizeBefore,
                promptComposerSubmitInFlight,
                promptComposerSubmitQueue.size(),
                submit.requestContext.idempotencyRef
        );
        if (!promptComposerSubmitQueue.isEmpty()) {
            showToolbarControlPending(promptComposerSubmitPendingLabel());
        }
        drainPromptComposerSubmitQueue();
        return true;
    }

    private boolean failPromptComposerSubmit(PromptComposerQueuedSubmit submit) {
        if (submit == null) {
            return false;
        }
        boolean inFlightBefore = promptComposerSubmitInFlight;
        boolean ownedBefore = PromptComposerRapidOrderedSendBehavior.ownsFinalCallback(
                inFlightBefore,
                promptComposerSubmitFingerprint,
                submit,
                promptComposerSubmitQueue.peek()
        );
        int queueSizeBefore = promptComposerSubmitQueue.size();
        if (!ownedBefore) {
            submit.sendLifecycle = recordPromptComposerSendLifecycle(
                    submit.sendLifecycle,
                    PromptComposerSendLifecyclePhase.FINAL,
                    PromptComposerSendLifecycleDisposition.FINAL_STATE_MISMATCH,
                    inFlightBefore,
                    queueSizeBefore,
                    promptComposerSubmitInFlight,
                    promptComposerSubmitQueue.size(),
                    submit.requestContext.idempotencyRef
            );
            return false;
        }
        ArrayList<PromptComposerSubmitLedgerEntry> nextLedger =
                PromptComposerSubmitLedgerBehavior.markExactFailure(
                        promptComposerSubmitLedger,
                        submit
                );
        if (PromptComposerSubmitLedgerBehavior.exactEntry(
                promptComposerSubmitLedger,
                submit,
                PROMPT_COMPOSER_SUBMIT_LEDGER_PENDING
        ) == null || !persistPromptComposerSubmitLedger(nextLedger)) {
            showToolbarControlPending("Saving failed send");
            return false;
        }
        replacePromptComposerSubmitLedger(nextLedger);
        finishPromptComposerSubmit(submit.submitFingerprint);
        promptComposerSubmitQueue.remove(submit);
        sendStatusRevisionFence.definitiveFailure(
                submit.stableTargetKey,
                promptComposerStatusOperationId(submit)
        );
        submit.sendLifecycle = recordPromptComposerSendLifecycle(
                submit.sendLifecycle,
                PromptComposerSendLifecyclePhase.FINAL,
                PromptComposerSendLifecycleDisposition.FAILED,
                inFlightBefore,
                queueSizeBefore,
                promptComposerSubmitInFlight,
                promptComposerSubmitQueue.size(),
                submit.requestContext.idempotencyRef
        );
        if (!promptComposerSubmitQueue.isEmpty()) {
            showToolbarControlPending(promptComposerSubmitPendingLabel());
        } else {
            scheduleToolbarStatusDotRefresh(0);
            refreshActiveSessionsDialogIfShowing("send-definitive-failure");
        }
        drainPromptComposerSubmitQueue();
        return true;
    }

    private boolean failPromptComposerDeliveryBlockOnce(
            PromptComposerQueuedSubmit submit
    ) {
        if (submit == null
                || !PromptComposerRapidOrderedSendBehavior.ownsCompletion(
                        promptComposerSubmitInFlight,
                        promptComposerSubmitFingerprint,
                        submit
                )
                || promptComposerSubmitQueue.peek() != submit) {
            return false;
        }
        // WHY: delivery-block exhaustion may restore only the exact admission
        // revision while this immutable operation still owns the FIFO head.
        // The main-thread callback then releases/drains that head once; a stale
        // duplicate callback fails this ownership check and cannot repeat either.
        if (!failPromptComposerSubmit(submit)) {
            return false;
        }
        restorePromptComposerAfterFailedSubmit(
                submit.stableTargetKey,
                submit.value,
                submit.draftRevision
        );
        return true;
    }

    private void postPromptComposerSubmit(PromptComposerQueuedSubmit submit) {
        if (submit == null) {
            return;
        }
        String stableTargetKey = submit.stableTargetKey;
        String value = submit.value;
        long submittedDraftRevision = submit.draftRevision;
        String submitIdempotencyKey = submit.submitIdempotencyKey;
        String submitFingerprint = submit.submitFingerprint;
        String successToast = submit.successToast;
        Runnable afterSuccess = submit.afterSuccess;
        Runnable afterFailure = submit.afterFailure;
        long generation = submit.generation;
        long sendStartedAtMs = submit.sendStartedAtMs;
        int submitChars = submit.submitChars;
        int inProgressRetryCount = submit.inProgressRetryCount;
        PromptComposerRequestContext requestContext = submit.requestContext.withTraceId(
                "trace-send-" + UUID.randomUUID().toString()
        );
        // WHY: visible phone drafts are local-only until Send, so the submit
        // request must use the draft's pinned `@windowId`, not a later `/active`
        // value. This is the durable guard against prompts being pasted into a
        // different active session after tab switches, polling, or proof setup.
        // WHY: native APK Send already renders through the capture renderer and
        // must not take the old phone resize/release branch on every tap. That
        // branch is now a legacy escape hatch; leaving it in the hot Send path
        // made some submits wait on tmux size bookkeeping before the user saw a
        // response. Keep the same stable @windowId, idempotency key, and server
        // paste+Enter, but explicitly use the non-resizing submit mode.
        if (!promptComposerSubmitInFlight || !submitFingerprint.equals(promptComposerSubmitFingerprint)) {
            submit.sendLifecycle = recordPromptComposerSendLifecycle(
                    submit.sendLifecycle,
                    PromptComposerSendLifecyclePhase.REQUEST_START,
                    PromptComposerSendLifecycleDisposition.REQUEST_SUPPRESSED_STATE_MISMATCH,
                    promptComposerSubmitInFlight,
                    promptComposerSubmitQueue.size(),
                    promptComposerSubmitInFlight,
                    promptComposerSubmitQueue.size(),
                    requestContext.idempotencyRef
            );
            return;
        }
        submit.sendLifecycle = recordPromptComposerSendLifecycle(
                submit.sendLifecycle,
                PromptComposerSendLifecyclePhase.REQUEST_START,
                PromptComposerSendLifecycleDisposition.REQUEST_STARTED,
                promptComposerSubmitInFlight,
                promptComposerSubmitQueue.size(),
                promptComposerSubmitInFlight,
                promptComposerSubmitQueue.size(),
                requestContext.idempotencyRef
        );
        logPromptSendStage("request", stableTargetKey, sendStartedAtMs, submitChars, requestContext);
        postTextWithIdempotency(
                appendStableWindowQuery("/submit-text?resize=0", stableTargetKey),
                value,
                submitIdempotencyKey,
                requestContext,
                payload -> {
            if (!PromptComposerRapidOrderedSendBehavior.ownsFinalCallback(
                    promptComposerSubmitInFlight,
                    promptComposerSubmitFingerprint,
                    submit,
                    promptComposerSubmitQueue.peek()
            )) {
                submit.sendLifecycle = recordPromptComposerSendLifecycle(
                        submit.sendLifecycle,
                        PromptComposerSendLifecyclePhase.CALLBACK,
                        PromptComposerSendLifecycleDisposition.FINAL_STATE_MISMATCH,
                        promptComposerSubmitInFlight,
                        promptComposerSubmitQueue.size(),
                        promptComposerSubmitInFlight,
                        promptComposerSubmitQueue.size(),
                        requestContext.idempotencyRef
                );
                return;
            }
            submit.sendLifecycle = recordPromptComposerSendLifecycle(
                    submit.sendLifecycle,
                    PromptComposerSendLifecyclePhase.CALLBACK,
                    PromptComposerSendLifecycleDisposition.RESPONSE_RECEIVED,
                    promptComposerSubmitInFlight,
                    promptComposerSubmitQueue.size(),
                    promptComposerSubmitInFlight,
                    promptComposerSubmitQueue.size(),
                    requestContext.idempotencyRef
            );
            logPromptSendStage("response", stableTargetKey, sendStartedAtMs, submitChars, requestContext);
            if (isPromptSubmitIdempotencyInProgress(payload)) {
                submit.sendLifecycle = recordPromptComposerSendLifecycle(
                        submit.sendLifecycle,
                        PromptComposerSendLifecyclePhase.CALLBACK,
                        PromptComposerSendLifecycleDisposition.IDEMPOTENCY_IN_PROGRESS,
                        promptComposerSubmitInFlight,
                        promptComposerSubmitQueue.size(),
                        promptComposerSubmitInFlight,
                        promptComposerSubmitQueue.size(),
                        requestContext.idempotencyRef
                );
                logPromptSendStage(
                        "idempotency-in-progress",
                        stableTargetKey,
                        sendStartedAtMs,
                        submitChars,
                        requestContext
                );
                submit.inProgressRetryCount = inProgressRetryCount + 1;
                schedulePromptComposerSubmitInProgressRetry(submit, requestContext);
                return;
            }
            if (isPromptSubmitDeliveryBlocked(payload)) {
                holdPromptComposerSubmitForDeliveryBlock(submit, payload, requestContext);
                return;
            }
            if (payload.optBoolean("pasted", false)
                    && !payload.optBoolean("enterSent", true)) {
                // WHY: FIX C — pasted-but-not-submitted recovery. /submit-text is a
                // tmux load-buffer -> paste -> Enter group; when the HTTP deadline
                // lands after paste but before Enter the server returns ok=true/2xx
                // with pasted=true and enterSent=false, leaving the prompt text
                // pasted into tmux but never submitted. Recover deterministically by
                // pressing Enter EXACTLY ONCE on the exact paste target
                // (stableTargetKey) via the existing /send-enter path — never a
                // /submit-text retry, which would re-paste and duplicate the text.
                // Gate on final-callback ownership first so a duplicate/late callback
                // cannot press Enter twice; then finalize this submit as complete and
                // clear the composer WITHOUT restoring the draft (the text already
                // reached tmux) and WITHOUT re-POSTing /submit-text. This branch sits
                // before the generic success/fail branches because the tightened
                // isSuccessfulPromptSubmitResponse now treats enterSent=false as a
                // failure, which would otherwise restore the draft and mislead.
                if (!PromptComposerRapidOrderedSendBehavior.ownsFinalCallback(
                        promptComposerSubmitInFlight,
                        promptComposerSubmitFingerprint,
                        submit,
                        promptComposerSubmitQueue.peek()
                )) {
                    submit.sendLifecycle = recordPromptComposerSendLifecycle(
                            submit.sendLifecycle,
                            PromptComposerSendLifecyclePhase.CALLBACK,
                            PromptComposerSendLifecycleDisposition.FINAL_STATE_MISMATCH,
                            promptComposerSubmitInFlight,
                            promptComposerSubmitQueue.size(),
                            promptComposerSubmitInFlight,
                            promptComposerSubmitQueue.size(),
                            requestContext.idempotencyRef
                    );
                    return;
                }
                sendEnterToTerminal(stableTargetKey);
                if (!completePromptComposerSubmit(submit)) {
                    return;
                }
                logPromptSendStage(
                        "enter-recovery",
                        stableTargetKey,
                        sendStartedAtMs,
                        submitChars,
                        requestContext
                );
                boolean recoveredDraftCleared = clearPromptComposerAfterSuccessfulSubmit(
                        stableTargetKey,
                        value,
                        submit.draftClearedInLedgerCommit
                );
                if (recoveredDraftCleared && isDockedPromptComposerVisible()) {
                    hideDockedPromptComposer(false, false);
                }
                settleLiveBottomAfterSend("submit-text-enter-recovery");
                forceCaptureRendererVisualCommit("submit-text-enter-recovery");
                if (afterSuccess != null) {
                    afterSuccess.run();
                }
                return;
            }
            if (!isSuccessfulPromptSubmitResponse(payload)) {
                if (!failPromptComposerSubmit(submit)) {
                    return;
                }
                restorePromptComposerAfterFailedSubmit(
                        stableTargetKey,
                        value,
                        submittedDraftRevision
                );
                toast(payload.optString("error", "Send failed"));
                return;
            }
            if (!completePromptComposerSubmit(submit)) {
                return;
            }
            // WHY: FEATURE single choke point for a fully confirmed real send.
            // `value` is the exact submitted text; record it in the global
            // sent-history ring so the composer resend picker can recall past
            // prompts. This runs only after the submit is committed complete, so
            // drafts, queued sends, idempotency-in-progress retries, and failed
            // sends are never recorded here.
            rememberSentPromptHistory(value);
            if (successToast != null && !successToast.trim().isEmpty()) {
                toast(successToast);
            }
            boolean submittedDraftCleared = clearPromptComposerAfterSuccessfulSubmit(
                    stableTargetKey,
                    value,
                    submit.draftClearedInLedgerCommit
            );
            logPromptSendStage("success", stableTargetKey, sendStartedAtMs, submitChars, requestContext);
            if (submittedDraftCleared && isDockedPromptComposerVisible()) {
                hideDockedPromptComposer(false, false);
            }
            boolean failedLedgerDraftShown =
                    restorePromptComposerFailedLedgerDraftIfAvailable(
                            stableTargetKey,
                            "newer-submit-success"
                    );
            if (generation != terminalModeGeneration) {
                return;
            }
            if (!failedLedgerDraftShown) {
                focusTerminalInputSoon(false);
            }
            settleLiveBottomAfterSend("submit-text");
            forceCaptureRendererVisualCommit("submit-text-success");
            if (afterSuccess != null) {
                afterSuccess.run();
            }
        }, exc -> {
            if (!PromptComposerRapidOrderedSendBehavior.ownsFinalCallback(
                    promptComposerSubmitInFlight,
                    promptComposerSubmitFingerprint,
                    submit,
                    promptComposerSubmitQueue.peek()
            )) {
                submit.sendLifecycle = recordPromptComposerSendLifecycle(
                        submit.sendLifecycle,
                        PromptComposerSendLifecyclePhase.CALLBACK,
                        PromptComposerSendLifecycleDisposition.FINAL_STATE_MISMATCH,
                        promptComposerSubmitInFlight,
                        promptComposerSubmitQueue.size(),
                        promptComposerSubmitInFlight,
                        promptComposerSubmitQueue.size(),
                        requestContext.idempotencyRef
                );
                return;
            }
            submit.sendLifecycle = recordPromptComposerSendLifecycle(
                    submit.sendLifecycle,
                    PromptComposerSendLifecyclePhase.CALLBACK,
                    PromptComposerSendLifecycleDisposition.TRANSPORT_FAILURE,
                    promptComposerSubmitInFlight,
                    promptComposerSubmitQueue.size(),
                    promptComposerSubmitInFlight,
                    promptComposerSubmitQueue.size(),
                    requestContext.idempotencyRef
            );
            if (!failPromptComposerSubmit(submit)) {
                return;
            }
            logPromptSendStage("failure", stableTargetKey, sendStartedAtMs, submitChars, requestContext);
            restorePromptComposerAfterFailedSubmit(
                    stableTargetKey,
                    value,
                    submittedDraftRevision
            );
            toast("Mantis Control is not reachable");
            if (afterFailure != null) {
                afterFailure.run();
            }
        });
    }

    private boolean isPromptSubmitIdempotencyInProgress(JSONObject payload) {
        if (payload == null || payload.optBoolean("ok", false)) {
            return false;
        }
        // WHY(409 in-progress structured signal 2026-07-28, control-send-oauth #SEND): the
        // control server returns HTTP 409 {inProgress:true, retryable:true} when /submit-text
        // exceeds its ~0.20s synchronous budget -- the send WAS ACCEPTED and is still executing
        // under the SAME Idempotency-Key. The APK must poll/retry that key for the cached 200,
        // never treat it as a failure: failing here restores the draft and invites a duplicate
        // re-send (double-send, violates P6) and reads to the user as "sent but never appeared".
        // v75's submit verify-retry RAISES 409 frequency, so recognize the STRUCTURED field
        // first; the legacy message-text match below stays for older servers that only emit
        // "... idempotency ... already in progress". Delivery-block 409s (sendable:false,
        // submit-text-blocked) do NOT set inProgress and still route to the hold path, which is
        // checked after this in the response callback.
        if (payload.optInt("httpStatus", -1) == 409
                && payload.optBoolean("inProgress", false)) {
            return true;
        }
        String message = (
                payload.optString("error", "")
                        + " " + payload.optString("message", "")
                        + " " + payload.optString("detail", "")
        ).toLowerCase(Locale.US);
        return message.contains("already in progress") && message.contains("idempotency");
    }

    private boolean isSuccessfulPromptSubmitResponse(JSONObject payload) {
        if (payload == null || !payload.optBoolean("ok", false)) {
            return false;
        }
        int code = payload.optInt("httpStatus", -1);
        // WHY: FIX C — a /submit-text turn is only truly submitted once Enter was
        // pressed. The tmux load-buffer -> paste -> Enter group can return
        // ok=true/2xx with enterSent=false when the HTTP deadline lands after paste
        // but before Enter, leaving text pasted-but-un-submitted. Require enterSent,
        // defaulting to true so older servers that never emit the field keep passing
        // (no regression). The pasted-but-!enterSent case is recovered by a one-shot
        // /send-enter in the response callback BEFORE this check is reached, so
        // reaching here with enterSent=false means paste itself did not land -> fail.
        return code >= 200 && code < 300 && payload.optBoolean("enterSent", true);
    }

    private boolean isPromptSubmitDeliveryBlocked(JSONObject payload) {
        if (payload == null || payload.optBoolean("ok", false)) {
            return false;
        }
        String detail = (
                payload.optString("action", "")
                        + " " + payload.optString("error", "")
                        + " " + payload.optString("message", "")
                        + " " + payload.optString("detail", "")
                        + " " + payload.optString("blockedReason", "")
                        + " " + String.valueOf(payload.opt("sessionInteractionState"))
                        + " " + String.valueOf(payload.opt("targetProofGaps"))
                        + " " + String.valueOf(payload.opt("interactionBlockers"))
        ).toLowerCase(Locale.US);
        if (detail.contains("target-visible-body-not-proven")
                || detail.contains("fresh-codex-shell-no-transcript-continuity")
                || detail.contains("selected session is not currently sendable")
                || detail.contains("body-continuity-unproven")) {
            return true;
        }
        return payload.optInt("httpStatus", -1) == 409
                && payload.optBoolean("sendable", true) == false
                && detail.contains("submit-text-blocked");
    }

    private void holdPromptComposerSubmitForDeliveryBlock(
            PromptComposerQueuedSubmit submit,
            JSONObject payload,
            PromptComposerRequestContext requestContext
    ) {
        if (submit == null) {
            return;
        }
        String submitFingerprint = submit.submitFingerprint;
        String stableTargetKey = submit.stableTargetKey;
        long sendStartedAtMs = submit.sendStartedAtMs;
        int submitChars = submit.submitChars;
        if (!promptComposerSubmitInFlight || !submitFingerprint.equals(promptComposerSubmitFingerprint)) {
            submit.sendLifecycle = recordPromptComposerSendLifecycle(
                    submit.sendLifecycle,
                    PromptComposerSendLifecyclePhase.CALLBACK,
                    PromptComposerSendLifecycleDisposition.RETRY_SUPPRESSED_STATE_MISMATCH,
                    promptComposerSubmitInFlight,
                    promptComposerSubmitQueue.size(),
                    promptComposerSubmitInFlight,
                    promptComposerSubmitQueue.size(),
                    requestContext.idempotencyRef
            );
            return;
        }
        if (submit.deliveryBlockRetryCount
                >= PROMPT_COMPOSER_DELIVERY_BLOCK_MAX_RETRIES) {
            // WHY: a backend safety block is not open-ended transport. After the
            // initial attempt plus three same-key retries spaced at 1700ms, the
            // 5100ms terminal horizon cannot precede the 5000ms Active-switch
            // title deadline. Restore this exact admission revision and release
            // the FIFO head once; a later draft never inherits this operation.
            if (failPromptComposerDeliveryBlockOnce(submit)) {
                Log.i(SEND_LOG_TAG,
                        "stage=delivery-block-terminal"
                                + requestContext.toSafeLogFields()
                                + " retryCount=" + Math.max(
                                        0,
                                        submit.deliveryBlockRetryCount
                                )
                                + " textChars=" + Math.max(0, submitChars)
                                + " elapsedMs=" + Math.max(
                                        0,
                                        SystemClock.elapsedRealtime() - sendStartedAtMs
                                ));
                toast("Send remained blocked; draft restored");
                if (submit.afterFailure != null) {
                    submit.afterFailure.run();
                }
            }
            return;
        }
        submit.deliveryBlockRetryCount += 1;
        submit.sendLifecycle = recordPromptComposerSendLifecycle(
                submit.sendLifecycle,
                PromptComposerSendLifecyclePhase.CALLBACK,
                PromptComposerSendLifecycleDisposition.DELIVERY_BLOCKED_RETRYING,
                promptComposerSubmitInFlight,
                promptComposerSubmitQueue.size(),
                promptComposerSubmitInFlight,
                promptComposerSubmitQueue.size(),
                requestContext.idempotencyRef
        );
        // WHY REGRESSION LOCK APK-COMPOSER-FOCUS-FREEZE-2346-A: backend
        // body/session safety can delay delivery, but it cannot become a local
        // typing failure. Exact codes such as target-visible-body-not-proven,
        // fresh-codex-shell-no-transcript-continuity, and "Selected session is
        // not currently sendable." stay as drain metadata; do not toast them,
        // restore a failed draft, hide a newer composer, or block stacking more
        // queued prompts. /submit-text gets at most three retries with the same
        // immutable idempotency key before exact-revision recovery releases FIFO.
        showToolbarControlPending("Queued for send");
        Log.i(SEND_LOG_TAG,
                "stage=delivery-block-queued"
                        + requestContext.toSafeLogFields()
                        + " retryCount=" + Math.max(0, submit.deliveryBlockRetryCount)
                        + " textChars=" + Math.max(0, submitChars)
                        + " elapsedMs=" + Math.max(0, SystemClock.elapsedRealtime() - sendStartedAtMs)
                        + " status=" + (payload == null ? -1 : payload.optInt("httpStatus", -1))
                        + " composerVisible=" + isDockedPromptComposerVisible());
        submit.sendLifecycle = recordPromptComposerSendLifecycle(
                submit.sendLifecycle,
                PromptComposerSendLifecyclePhase.CALLBACK,
                PromptComposerSendLifecycleDisposition.RETRY_SCHEDULED,
                promptComposerSubmitInFlight,
                promptComposerSubmitQueue.size(),
                promptComposerSubmitInFlight,
                promptComposerSubmitQueue.size(),
                requestContext.idempotencyRef
        );
        uiHandler.postDelayed(() -> {
                    if (!promptComposerSubmitInFlight
                            || !submitFingerprint.equals(promptComposerSubmitFingerprint)) {
                        submit.sendLifecycle = recordPromptComposerSendLifecycle(
                                submit.sendLifecycle,
                                PromptComposerSendLifecyclePhase.CALLBACK,
                                PromptComposerSendLifecycleDisposition.RETRY_SUPPRESSED_STATE_MISMATCH,
                                promptComposerSubmitInFlight,
                                promptComposerSubmitQueue.size(),
                                promptComposerSubmitInFlight,
                                promptComposerSubmitQueue.size(),
                                requestContext.idempotencyRef
                        );
                        return;
                    }
                    postPromptComposerSubmit(submit);
                },
                PROMPT_COMPOSER_DELIVERY_BLOCK_RETRY_MS
        );
    }

    private void schedulePromptComposerSubmitInProgressRetry(
            PromptComposerQueuedSubmit submit,
            PromptComposerRequestContext requestContext
    ) {
        if (submit == null) {
            return;
        }
        String stableTargetKey = submit.stableTargetKey;
        String submitFingerprint = submit.submitFingerprint;
        long sendStartedAtMs = submit.sendStartedAtMs;
        int submitChars = submit.submitChars;
        int inProgressRetryCount = submit.inProgressRetryCount;
        if (!promptComposerSubmitInFlight || !submitFingerprint.equals(promptComposerSubmitFingerprint)) {
            submit.sendLifecycle = recordPromptComposerSendLifecycle(
                    submit.sendLifecycle,
                    PromptComposerSendLifecyclePhase.CALLBACK,
                    PromptComposerSendLifecycleDisposition.RETRY_SUPPRESSED_STATE_MISMATCH,
                    promptComposerSubmitInFlight,
                    promptComposerSubmitQueue.size(),
                    promptComposerSubmitInFlight,
                    promptComposerSubmitQueue.size(),
                    requestContext.idempotencyRef
            );
            return;
        }
        if (inProgressRetryCount >= PROMPT_COMPOSER_SUBMIT_IN_PROGRESS_MAX_RETRIES) {
            // WHY: an in-progress idempotency response means the central submit
            // owner may still be pasting/pressing Enter for the same visible
            // Send. Keep the same in-flight idempotency key.
            // Guard phrase: do not restore the preserved draft.
            // Restoring here creates a duplicate draft that can be submitted
            // under a new UUID while the first Send is uncertain.
            if (!promptComposerSubmitInFlight || !submitFingerprint.equals(promptComposerSubmitFingerprint)) {
                submit.sendLifecycle = recordPromptComposerSendLifecycle(
                        submit.sendLifecycle,
                        PromptComposerSendLifecyclePhase.CALLBACK,
                        PromptComposerSendLifecycleDisposition.RETRY_SUPPRESSED_STATE_MISMATCH,
                        promptComposerSubmitInFlight,
                        promptComposerSubmitQueue.size(),
                        promptComposerSubmitInFlight,
                        promptComposerSubmitQueue.size(),
                        requestContext.idempotencyRef
                );
                return;
            }
            // `keepPromptComposerSubmitChecking` must call showToolbarControlPending("Checking send status")
            // for this capped uncertain state, not a false generic Send failed.
            keepPromptComposerSubmitChecking(
                    submit,
                    stableTargetKey,
                    sendStartedAtMs,
                    submitChars,
                    inProgressRetryCount,
                    requestContext
            );
            return;
        }
        // WHY: the control server's idempotency guard can report that this same
        // Send is already being processed after Android retries a timed-out POST.
        // That is not a failed user draft. Keep the local composer hidden, keep
        // the same in-flight fingerprint/key, and poll the same key until the
        // server returns the cached success/failure instead of restoring a
        // stale duplicate draft that the user can send again.
        if (isDockedPromptComposerVisible()) {
            hideDockedPromptComposer(false, false);
        }
        showToolbarControlPending("Send prompt");
        Log.i(SEND_LOG_TAG,
                "stage=idempotency-in-progress-retry"
                        + requestContext.toSafeLogFields()
                        + " retryCount=" + Math.max(0, inProgressRetryCount)
                        + " elapsedMs=" + Math.max(0, SystemClock.elapsedRealtime() - sendStartedAtMs)
                        + " composerVisible=" + isDockedPromptComposerVisible());
        submit.sendLifecycle = recordPromptComposerSendLifecycle(
                submit.sendLifecycle,
                PromptComposerSendLifecyclePhase.CALLBACK,
                PromptComposerSendLifecycleDisposition.RETRY_SCHEDULED,
                promptComposerSubmitInFlight,
                promptComposerSubmitQueue.size(),
                promptComposerSubmitInFlight,
                promptComposerSubmitQueue.size(),
                requestContext.idempotencyRef
        );
        uiHandler.postDelayed(() -> postPromptComposerSubmit(
                        submit
                ),
                PROMPT_COMPOSER_SUBMIT_IN_PROGRESS_RETRY_MS
        );
    }

    private void keepPromptComposerSubmitChecking(
            PromptComposerQueuedSubmit submit,
            String stableTargetKey,
            long sendStartedAtMs,
            int submitChars,
            int inProgressRetryCount,
            PromptComposerRequestContext requestContext
    ) {
        if (!PromptComposerRapidOrderedSendBehavior.ownsFinalCallback(
                promptComposerSubmitInFlight,
                promptComposerSubmitFingerprint,
                submit,
                promptComposerSubmitQueue.peek()
        )) {
            if (submit != null) {
                submit.sendLifecycle = recordPromptComposerSendLifecycle(
                        submit.sendLifecycle,
                        PromptComposerSendLifecyclePhase.FINAL,
                        PromptComposerSendLifecycleDisposition.FINAL_STATE_MISMATCH,
                        promptComposerSubmitInFlight,
                        promptComposerSubmitQueue.size(),
                        promptComposerSubmitInFlight,
                        promptComposerSubmitQueue.size(),
                        requestContext.idempotencyRef
                );
            }
            return;
        }
        submit.sendLifecycle = recordPromptComposerSendLifecycle(
                submit.sendLifecycle,
                PromptComposerSendLifecyclePhase.FINAL,
                PromptComposerSendLifecycleDisposition.CAPPED_UNKNOWN,
                promptComposerSubmitInFlight,
                promptComposerSubmitQueue.size(),
                promptComposerSubmitInFlight,
                promptComposerSubmitQueue.size(),
                requestContext.idempotencyRef
        );
        if (isDockedPromptComposerVisible()) {
            hideDockedPromptComposer(false, false);
        }
        showToolbarControlPending("Checking send status");
        Log.i(SEND_LOG_TAG,
                "stage=idempotency-in-progress-capped"
                        + requestContext.toSafeLogFields()
                        + " retryCount=" + Math.max(0, inProgressRetryCount)
                        + " finalTruthRetryCount=" + Math.max(0, submit.cappedFinalTruthRetryCount)
                        + " textChars=" + Math.max(0, submitChars)
                        + " elapsedMs=" + Math.max(0, SystemClock.elapsedRealtime() - sendStartedAtMs)
                        + " composerVisible=" + isDockedPromptComposerVisible());
        if (submit.cappedFinalTruthRetryCount
                < PROMPT_COMPOSER_CAPPED_FINAL_TRUTH_MAX_RETRIES) {
            submit.cappedFinalTruthRetryCount += 1;
            // WHY: an accepted idempotency owner can outlive Android's ordinary
            // retry window. Probe only that same immutable operation; a distinct
            // queued Send must never inherit its target, body, or key.
            schedulePromptComposerCappedFinalTruthReconciliation(submit, requestContext);
            return;
        }
        // WHY: bounded reconciliation must not leave the FIFO latch permanent.
        // A still-unknown operation becomes an explicit terminal local failure:
        // preserve its target-local draft, release the next normal Send exactly
        // once, and never manufacture a second request key automatically.
        if (!failPromptComposerSubmit(submit)) {
            return;
        }
        restorePromptComposerAfterFailedSubmit(
                stableTargetKey,
                submit.value,
                submit.draftRevision
        );
        toast("Send status could not be confirmed; draft restored");
        if (submit.afterFailure != null) {
            submit.afterFailure.run();
        }
    }

    private void schedulePromptComposerCappedFinalTruthReconciliation(
            PromptComposerQueuedSubmit submit,
            PromptComposerRequestContext requestContext
    ) {
        if (submit == null) {
            return;
        }
        String submitFingerprint = submit.submitFingerprint;
        submit.sendLifecycle = recordPromptComposerSendLifecycle(
                submit.sendLifecycle,
                PromptComposerSendLifecyclePhase.CALLBACK,
                PromptComposerSendLifecycleDisposition.RETRY_SCHEDULED,
                promptComposerSubmitInFlight,
                promptComposerSubmitQueue.size(),
                promptComposerSubmitInFlight,
                promptComposerSubmitQueue.size(),
                requestContext.idempotencyRef
        );
        uiHandler.postDelayed(() -> {
                    if (!promptComposerSubmitInFlight
                            || !submitFingerprint.equals(promptComposerSubmitFingerprint)) {
                        submit.sendLifecycle = recordPromptComposerSendLifecycle(
                                submit.sendLifecycle,
                                PromptComposerSendLifecyclePhase.CALLBACK,
                                PromptComposerSendLifecycleDisposition.RETRY_SUPPRESSED_STATE_MISMATCH,
                                promptComposerSubmitInFlight,
                                promptComposerSubmitQueue.size(),
                                promptComposerSubmitInFlight,
                                promptComposerSubmitQueue.size(),
                                requestContext.idempotencyRef
                        );
                        return;
                    }
                    postPromptComposerSubmit(submit);
                },
                PROMPT_COMPOSER_CAPPED_FINAL_TRUTH_RETRY_MS
        );
    }

    private boolean clearPromptComposerAfterSuccessfulSubmit(
            String targetKey,
            String submittedValue,
            boolean draftClearedInLedgerCommit
    ) {
        if (!hasStableWindowId(targetKey)) {
            return false;
        }
        String stableTargetKey = targetKey.trim();
        String visibleTargetKey = hasStableWindowId(promptComposerDraftTargetKey)
                ? promptComposerDraftTargetKey.trim()
                : "";
        // WHY: Send success belongs to the submitted stable `@windowId`, not the
        // visible target at callback time. Active/session refresh can drift while
        // the POST is in flight; atomically forget only the exact submitted
        // target/revision, and clear the visible editor only when both its target
        // and text still belong to that submit. Equal text on a newer target is
        // a distinct draft and must survive the older callback.
        // Durable ownership was decided inside the same synchronous preference
        // transaction that removed the success ledger entry. A second async
        // draft removal here would reopen the process-death split transaction.
        boolean submittedDraftForgotten = draftClearedInLedgerCommit;
        if (!submittedDraftForgotten) {
            Log.i(SEND_LOG_TAG,
                    "stage=success-draft-preserved target="
                            + safePromptSendTargetForLog(stableTargetKey)
                            + " reason=newer-draft-revision-wins");
        }
        if (promptComposerInput == null) {
            return false;
        }
        if (!stableTargetKey.equals(visibleTargetKey)) {
            return false;
        }
        if (!submittedDraftForgotten) {
            return false;
        }
        String visibleValue = promptComposerInput.getText().toString();
        if (!submittedValue.equals(visibleValue)) {
            return false;
        }
        promptComposerProgrammaticTextChange = true;
        try {
            promptComposerInput.setText("");
        } finally {
            promptComposerProgrammaticTextChange = false;
        }
        promptComposerDraftTargetKey = promptComposerTargetKey();
        promptComposerDraftLocalGeneration++;
        return true;
    }

    private void restorePromptComposerAfterFailedSubmit(
            String targetKey,
            String submittedValue,
            long submittedDraftRevision
    ) {
        if (!hasStableWindowId(targetKey)) {
            return;
        }
        String stableTargetKey = targetKey.trim();
        boolean submittedDraftRestored = false;
        synchronized (promptDraftInstallSafetyLock) {
            String persistedDraft = rememberedPromptComposerDraft(stableTargetKey);
            long persistedRevision = rememberedPromptComposerDraftRevision(stableTargetKey);
            if (!promptDraftInstallSafetyWriterBlocked()
                    && PromptComposerRapidOrderedSendBehavior.shouldRestoreFailedDraft(
                            persistedDraft,
                            persistedRevision,
                            submittedValue,
                            submittedDraftRevision
                    )) {
                // Reentrant lock ownership keeps comparison and restoration
                // atomic; the write advances revision so this callback cannot
                // claim the same user work a second time.
                submittedDraftRestored =
                        rememberPromptComposerDraft(stableTargetKey, submittedValue) > 0L;
            }
        }
        if (!submittedDraftRestored) {
            restorePromptComposerFailedLedgerDraftIfAvailable(
                    stableTargetKey,
                    "submit-failed"
            );
            Log.i(SEND_LOG_TAG,
                    "stage=failure-draft-preserved target="
                            + safePromptSendTargetForLog(stableTargetKey)
                            + " reason=newer-draft-revision-wins");
            return;
        }
        if (!stableTargetKey.equals(promptComposerTargetKey())) {
            // WHY: the failed submit's target-local draft is now durable, but a
            // newer visible target owns the editor. Rebinding that editor would
            // make its next keystroke or Send route to the failed target.
            Log.i(SEND_LOG_TAG,
                    "stage=failure-draft-preserved target=" + safePromptSendTargetForLog(stableTargetKey)
                            + " reason=target-drift");
            return;
        }
        promptComposerDraftTargetKey = stableTargetKey;
        showDockedPromptComposer("submit-failed");
    }

    private boolean restorePromptComposerFailedLedgerDraftIfAvailable(
            String targetKey,
            String reason
    ) {
        if (promptComposerSubmitLedgerBlocked || !hasStableWindowId(targetKey)) {
            return false;
        }
        String stableTargetKey = targetKey.trim();
        boolean restored;
        synchronized (promptDraftInstallSafetyLock) {
            String persistedDraft = rememberedPromptComposerDraft(stableTargetKey);
            PromptComposerSubmitLedgerEntry restorable =
                    PromptComposerSubmitLedgerBehavior.firstRestorableFailure(
                            promptComposerSubmitLedger,
                            stableTargetKey,
                            persistedDraft
                    );
            if (restorable == null || promptDraftInstallSafetyWriterBlocked()) {
                return false;
            }
            // WHY: a failed middle FIFO item can outlive a newer pending Send
            // and even Activity recreation. Restore its body only after the
            // target has no pending successor and its durable draft slot is
            // empty; never overwrite newer typing or another target's editor.
            restored = rememberPromptComposerDraft(
                    stableTargetKey,
                    restorable.value
            ) > 0L;
        }
        if (!restored) {
            return false;
        }
        Log.i(SEND_LOG_TAG,
                "stage=submit-ledger result=failed-draft-restored"
                        + " target=" + safePromptSendTargetForLog(stableTargetKey)
                        + " reason=" + safeLogToken(reason));
        if (!stableTargetKey.equals(promptComposerTargetKey())) {
            return false;
        }
        promptComposerDraftTargetKey = stableTargetKey;
        showDockedPromptComposer("submit-ledger-recovery");
        return true;
    }

    private void logPromptSendStage(
            String stage,
            String targetKey,
            long startedAtMs,
            int textChars,
            PromptComposerRequestContext requestContext
    ) {
        long elapsedMs = startedAtMs > 0 ? Math.max(0, SystemClock.elapsedRealtime() - startedAtMs) : 0;
        Log.i(SEND_LOG_TAG,
                "stage=" + stage
                        + " actionId=" + requestContext.actionId
                        + " tapId=" + requestContext.tapId
                        + " actionKind=" + requestContext.actionKind
                        + " traceId=" + requestContext.traceId
                        + " target=" + requestContext.target
                        + " idempotencyRef=" + requestContext.idempotencyRef
                        + " textChars=" + Math.max(0, textChars)
                        + " elapsedMs=" + elapsedMs
                        + " blackRefreshGuard=retained-last-accepted-frame"
                        + " composerVisible=" + isDockedPromptComposerVisible());
    }

    private String safePromptSendTargetForLog(String targetKey) {
        return hasStableWindowId(targetKey) ? targetKey.trim() : "unstable";
    }

    private boolean beginPromptComposerSubmit(String fingerprint) {
        if (promptComposerSubmitInFlight) {
            // Distinct stacked prompts are accepted by enqueuePromptComposerSubmit().
            // The active slot only drains one idempotent POST at a time. Android
            // can fire both an editor-action callback and an obvious toolbar tap;
            // this guard prevents pasting the same draft twice while the queue
            // remains open for genuinely new stacked prompts.
            return false;
        }
        promptComposerSubmitInFlight = true;
        promptComposerSubmitFingerprint = fingerprint;
        return true;
    }

    private void finishPromptComposerSubmit(String fingerprint) {
        if (!promptComposerSubmitInFlight || !fingerprint.equals(promptComposerSubmitFingerprint)) {
            return;
        }
        promptComposerSubmitInFlight = false;
        promptComposerSubmitFingerprint = "";
    }

    private long enterReadMode() {
        // WHY: read-hold exists ONLY to protect tmux copy-mode scrollback from live repaints during a
        // read-scroll. A session with zero scrollback (alt-screen, e.g. the Claude Code TUI @6) has
        // NOTHING to protect, yet enterReadMode would still latch terminalHistoryViewportActive + the
        // capture read-hold and never release (reachedLiveBottom can never become true with no history)
        // -> the live stream, poll, switch and scroll ALL freeze on the next touch until "Bottom" is
        // tapped (device-repro: skipReason=read-mode-hold repeating every 2s). Guard: if the visible
        // session has no accepted scrollback (<=0), do NOT enter read-mode / do NOT set the read-hold
        // -> stay live. Normal-history sessions (historySize>0) are unchanged, so real scrollback
        // protection is preserved. This is the missing precondition, not a re-tune of read-hold.
        // Falsifier: device-proof.sh test_stream_under_touch on an alt-screen session.
        if (lastAcceptedCaptureRendererHistorySize <= 0) {
            return terminalModeGeneration;
        }
        long generation = ++terminalModeGeneration;
        cancelXtermBlankTailMask("enter-read-mode");
        cancelPassiveLiveBottomCallbacksForReadScroll("enter-read-mode");
        hideDockedPromptComposerForReadMode("read-mode");
        terminalHistoryViewportActive = true;
        readModeSuppressesKeyboard = true;
        syncCaptureRendererReadHold("enter-read-mode");
        showHistoryTouchOverlay();
        hideKeyboardForReadMode();
        uiHandler.postDelayed(() -> {
            if (generation == terminalModeGeneration && readModeSuppressesKeyboard) {
                hideKeyboardForReadMode();
            }
        }, 150);
        uiHandler.postDelayed(() -> {
            if (generation == terminalModeGeneration && readModeSuppressesKeyboard) {
                hideKeyboardForReadMode();
            }
        }, 600);
        return generation;
    }

    private void keepReadModeIfCurrent(long generation) {
        if (generation != terminalModeGeneration || !readModeSuppressesKeyboard) {
            return;
        }
        syncCaptureRendererReadHold("keep-read-mode");
        hideKeyboardForReadMode();
        uiHandler.postDelayed(() -> {
            if (generation == terminalModeGeneration && readModeSuppressesKeyboard) {
                hideKeyboardForReadMode();
            }
        }, 150);
        uiHandler.postDelayed(() -> {
            if (generation == terminalModeGeneration && readModeSuppressesKeyboard) {
                hideKeyboardForReadMode();
            }
        }, 600);
    }

    private void restoreLiveForTyping(String message) {
        long generation = leaveReadModeForLiveInput();
        // WHY REGRESSION LOCK APK-COMPOSER-FOCUS-FREEZE-2346-A: tap-to-type is
        // local input ownership, not backend delivery. Exact central diagnostics
        // like target-visible-body-not-proven, fresh-codex-shell-no-transcript-
        // continuity, and "Selected session is not currently sendable." must not
        // toast over the typing area or return before the native EditText opens.
        // Delivery remains fail-closed in /submit-text; the APK must always let
        // the user draft/queue text without close/reopen or visible lag.
        showDockedPromptComposer("tap-to-type");
        runBottomButtonLiveBottomRecovery("live-bottom", generation, message, true, false, null);
    }

    private void restoreLiveForViewing(String message) {
        long generation = leaveReadModeForLiveInput(false, "explicit-bottom");
        clearLocalHistoryTouchViewportForLiveBottom("live-bottom-view");
        pinTerminalViewportLocal();
        // WHY: the visible Bottom toolbar button is navigation/readability: a one-tap live-bottom recovery, not a typing command or a scroll/touch-scroll reconcile.
        // Keep it on the fast `/live-bottom` owner, full-screen and passive;
        // tapping the terminal body is the deliberate request to type. If a
        // previous live-bottom confirmation is still in flight, queue the same
        // Bottom request instead of evaporating into a second user tap.
        runBottomButtonLiveBottomRecovery("live-bottom-view", generation, message, false, false, null);
    }

    private void restoreLiveAfterTabOpen(String reason, long generation, long paintShieldGeneration) {
        Runnable afterSuccess = paintShieldGeneration > 0
                ? () -> {
                    // WHY: v2.22 moved the long-lived dotted-field protection out of
                    // the full-frame native shield. Extending this layer back to the
                    // old 2200 ms window recreates the all-black Active-switch failure;
                    // delayed xterm dots are handled by the bounded WebView lower-area
                    // shield and glyph scrubbers instead.
                    hideSessionSwitchPaintShieldSoon(reason + "-bottom-core-painted",
                            paintShieldGeneration, FULL_FRAME_SESSION_SWITCH_SHIELD_MAX_MS);
                }
                : null;
        // WHY: v2.06 proved tab-open must reuse Bottom-core to clear dotted/black
        // xterm rows, but the next real-phone screenshots showed auto-opening the
        // composer/keyboard revived duplicate typing and made Backspace useless
        // while Android was still settling. Tab-open is navigation; the user taps
        // the terminal body when they actually want the native composer.
        runBottomButtonLiveBottomRecovery(reason + "-tab-open-bottom", generation, "", false, true, afterSuccess);
    }

    private void runBottomButtonLiveBottomRecovery(
            String reason,
            long generation,
            String message,
            boolean showComposer,
            boolean quietFailure,
            Runnable afterSuccess
    ) {
        runBottomButtonLiveBottomRecovery(
                reason,
                generation,
                message,
                showComposer,
                quietFailure,
                afterSuccess,
                0
        );
    }

    private void runBottomButtonLiveBottomRecovery(
            String reason,
            long generation,
            String message,
            boolean showComposer,
            boolean quietFailure,
            Runnable afterSuccess,
            int retryCount
    ) {
        boolean explicitBottomView = reason != null && reason.startsWith("live-bottom-view");
        if (liveRestoreInFlight) {
            if (explicitBottomView) {
                // WHY: explicit Bottom is the user's emergency escape from a
                // cache/read viewport. A slow passive tab-open `/live-bottom`
                // request must never consume that tap for its finite retry window.
                // Supersede the older visual callback and issue the idempotent
                // `/live-bottom` request now; the request serial below prevents the
                // stale callback from repainting after this explicit owner.
                Log.i(CONTROL_LOG_TAG,
                        "stage=live-bottom endpoint=/live-bottom result=explicit-bottom-supersedes-in-flight"
                                + " reason=" + safeLogToken(reason)
                                + " retry=" + retryCount);
            } else {
            if (!showComposer
                    && !quietFailure
                    && explicitBottomView
                    && retryCount < PASSIVE_TAB_OPEN_BOTTOM_RETRY_LIMIT) {
                // WHY: explicit Bottom is a one-tap live-bottom recovery. If a previous `/live-bottom` confirmation is still in flight, the tap must queue the same Bottom request instead of being dropped and forcing a second tap. Keep the retry on the same `/live-bottom` owner; do not reroute through `/scroll` or the touch-scroll reconcile path.
                uiHandler.postDelayed(() -> runBottomButtonLiveBottomRecovery(
                        reason,
                        generation,
                        message,
                        false,
                        false,
                        afterSuccess,
                        retryCount + 1
                ), PASSIVE_TAB_OPEN_BOTTOM_RETRY_MS);
                return;
            }
            if (!showComposer
                    && quietFailure
                    && reason.contains("tab-open")
                    && retryCount < PASSIVE_TAB_OPEN_BOTTOM_RETRY_LIMIT) {
                // WHY: Active/Old/Crashed/New tab-open is supposed to behave as
                // though the user pressed Bottom immediately after opening the
                // tab. If a previous `/live-bottom` confirmation is still in
                // flight, returning here silently skips that automatic Bottom and
                // recreates the user-reported "I have to hit Bottom myself" bug.
                // Retry only passive tab-open recoveries; deliberate Bottom/tap to
                // type keeps the existing single-owner liveRestoreInFlight guard.
                uiHandler.postDelayed(() -> runBottomButtonLiveBottomRecovery(
                        reason,
                        generation,
                        message,
                        false,
                        true,
                        afterSuccess,
                        retryCount + 1
                ), PASSIVE_TAB_OPEN_BOTTOM_RETRY_MS);
            }
            return;
            }
        }
        // WHY: history paging and one-finger swipe requests are asynchronous HTTP
        // calls. A stale pageUp/pageDown response used to arrive after Live/tap and
        // put the app back into keyboard-suppressed read mode. Bottom and tab-open
        // now share this exact `/live-bottom` core because the real APK dot-grid
        // regression only cleared after pressing Bottom manually. Do not split this
        // back into a second "almost Bottom" tab-open path.
        final long restoreRequestSerial = ++liveRestoreRequestSerial;
        liveRestoreInFlight = true;
        // WHY: this is a normal user recovery/tap-to-type action, not a proof
        // capture. The full `/scroll?where=bottom` endpoint gathers visible pane
        // evidence and Android then ran xterm.scrollToBottom/scrollIntoView, which
        // created the rapid top/bottom refresh loop at the exact moment the user
        // wanted to type. `/live-bottom` uses the server's fast tmux/Codex/reader
        // live-return primitive and leaves WebView's transport alone.
        getJsonWithRetry(appendStableWindowQuery("/live-bottom"), payload -> {
            if (restoreRequestSerial != liveRestoreRequestSerial) {
                return;
            }
            liveRestoreInFlight = false;
            if (generation != terminalModeGeneration) {
                return;
            }
            if (!payload.optBoolean("ok", false)) {
                String error = payload.optString("error", "Command failed");
                toast(error);
                return;
            }
            if (message != null && !message.isEmpty()) {
                toast(message);
            }
            rememberReaderReturnFromPayload(payload, reason);
            pinTerminalViewportLocal();
            if (explicitBottomView) {
                refreshCaptureRendererForImmediateBottom(reason + "-live-bottom");
            } else {
                refreshCaptureRendererForLayoutChange(reason + "-live-bottom");
            }
            if (showComposer) {
                showDockedPromptComposer("live-bottom");
            } else {
                // WHY: real-phone v2.11 proof started from a bad `Send`/composer
                // state and Active switching selected the new tmux tab but could
                // leave Android's IME/composer snapshot alive afterward. Passive
                // tab-open must finish like Start-toolbar navigation: preserve any
                // draft for the next deliberate tap, but do not leave the keyboard,
                // native composer, or hidden xterm focus attached to the selected
                // session.
                clearBroadSessionSwitchVisualMasks(reason + "-live-bottom-confirmed");
                settlePassiveNavigationInputIfStillOwned(reason + "-post-bottom");
                keepPassiveTabOpenPlainSoon(reason);
                if (explicitBottomView) {
                    refreshCaptureRendererForImmediateBottom(reason + "-post-bottom");
                } else {
                    fitTerminalToCurrentViewSoon(reason);
                    keepToolbarOnlyXtermSettleAlive(reason);
                }
                alignLiveBottomViewportForPassiveEntrySoon(reason);
                // WHY: explicit Bottom confirms tmux is at live bottom, but a
                // zoomed Android WebView can still be panned above the final prompt.
                // Use bounded viewer-only retries after the Bottom core settles so
                // one skipped frame cannot strand the user above the text. Preserve
                // scrollX and do not resize tmux, reset pinch zoom, or revive the old
                // scrollToBottom/scrollIntoView loop.
                if (shouldPreserveZoomedViewerForPassiveBottom(reason)) {
                    cancelViewerTypingPositionRetries(reason + "-preserve-zoomed-viewer");
                } else {
                    scrollViewerToTypingPositionAfterBottom(reason);
                }
                if (!explicitBottomView) {
                    normalizeXtermCanvasAfterSessionSwitch(reason);
                }
                scheduleToolbarStatusDotRefresh(150);
            }
            if (afterSuccess != null) {
                afterSuccess.run();
            }
        }, exc -> {
            if (restoreRequestSerial != liveRestoreRequestSerial) {
                return;
            }
            liveRestoreInFlight = false;
            if (!quietFailure) {
                toast("Mantis Control is not reachable");
            }
        });
    }

    private void keepPassiveTabOpenPlainSoon(String reason) {
        long generation = terminalModeGeneration;
        keepPassiveTabOpenPlain(reason, generation, 140);
        keepPassiveTabOpenPlain(reason, generation, 520);
        keepPassiveTabOpenPlain(reason, generation, 1100);
    }

    private void keepPassiveTabOpenPlain(String reason, long generation, long delayMs) {
        uiHandler.postDelayed(() -> {
            if (generation != terminalModeGeneration || readModeSuppressesKeyboard || terminalHistoryViewportActive) {
                return;
            }
            settlePassiveNavigationInputIfStillOwned(reason + "-plain");
        }, Math.max(0, delayMs));
    }

    private void restoreTouchLiveBottomQuietly() {
        if (terminalBottomRestoreInFlight) {
            return;
        }
        terminalBottomRestoreInFlight = true;
        long gestureGeneration = terminalTouchGestureGeneration;
        // WHY: this path is only for the end of a one-finger down-scroll. It must
        // exit tmux copy-mode so the real live bottom/composer is visible, but it
        // must not run the heavier `/scroll?where=bottom` recovery or reload/focus
        // helpers. Those helpers are still available through explicit Scroll ->
        // live bottom and Refresh, where a visible recovery jump is intentional.
        getJson(appendStableWindowQuery("/touch-scroll?where=bottom&repeat=1", terminalTouchStableWindowId), payload -> {
            terminalBottomRestoreInFlight = false;
            if (gestureGeneration != terminalTouchGestureGeneration) {
                return;
            }
            if (!payload.optBoolean("ok", false)) {
                toast(payload.optString("error", "Bottom restore failed"));
                return;
            }
            leaveReadModeAfterTouchBottom();
            pinTerminalViewportLocal();
            refreshCaptureRendererForTouchBottomRestore("touch-bottom");
            fitTerminalToCurrentViewSoon("touch-bottom");
            keepToolbarOnlyXtermSettleAliveAfterControlAction("touch-bottom");
            scrollViewerToTypingPositionAfterBottom("touch-bottom");
        }, exc -> {
            terminalBottomRestoreInFlight = false;
            toast("Mantis Control is not reachable");
        });
    }

    private void scheduleTouchLiveBottomReconcile(String reason) {
        long gestureGeneration = terminalTouchGestureGeneration;
        String stableTargetKey = terminalTouchStableWindowId == null
                ? ""
                : terminalTouchStableWindowId.trim();
        // WHY: copy-mode after a hard down flick can leave tmux above the prompt,
        // exposing a black bottom gap. Reconcile only that release/downward
        // live-bottom path through the quiet touch-bottom owner; do not run broad
        // focus, reload, scrollToBottom, IME, or row-refetch recovery here.
        uiHandler.post(() -> {
            if (gestureGeneration != terminalTouchGestureGeneration
                    || terminalHistoryDragActive
                    || terminalMultiTouchGesture
                    || terminalHorizontalPanActive
                    || !stableTargetKey.equals(terminalTouchStableWindowId == null
                            ? ""
                            : terminalTouchStableWindowId.trim())) {
                return;
            }
            Log.i(CONTROL_LOG_TAG,
                    "stage=touch-scroll-reconcile endpoint=/touch-scroll"
                            + " result=scheduled"
                            + " reason=" + safeLogToken(reason)
                            + " windowId=" + safeWindowIdForControlLog(stableTargetKey));
            restoreTouchLiveBottomQuietly();
        });
    }

    private void leaveReadModeAfterTouchBottom() {
        // WHY: quiet touch-bottom restore is not a typing/focus command. It only
        // reconciles Android's read-mode overlay with tmux after the server exits
        // copy-mode. Calling the normal live-input method here would re-run
        // viewport pin JS, xterm focus probes, IME show calls, and scrollIntoView,
        // recreating the bottom-edge refresh loop this path exists to avoid.
        terminalModeGeneration++;
        terminalHistoryViewportActive = false;
        terminalTouchStartedInHistoryViewport = false;
        terminalTouchReachedLiveBottom = false;
        readModeSuppressesKeyboard = false;
        // WHY(ROOT-C v258): the quiet touch-bottom return (down-drag / reconcile) is @42's return-to-
        // live path that does NOT funnel through leaveReadModeForLiveInput; drop the scroll-lock here
        // too so the existing sync below resumes follow. No-op if the lock was never engaged.
        liveTuiScrollLockActive = false;
        liveTuiScrollLockWindowId = "";
        clearPendingHistoryScroll();
        clearCaptureRendererTouchNudge("touch-bottom");
        syncCaptureRendererReadHold("touch-bottom");
        hideHistoryTouchOverlayQuietly();
    }

    private boolean activeTouchScrollHasExactLocalHistoryPaint() {
        return activeTouchScrollFirstInlineLocalHistoryAtMs > 0
                && activeTouchScrollActionId != null
                && activeTouchScrollActionId.equals(localHistoryTouchLastPaintActionId)
                && terminalTouchStableWindowId != null
                && terminalTouchStableWindowId.equals(localHistoryTouchLastPaintWindowId)
                && localHistoryTouchLastPaintGenerationKey != null
                && !localHistoryTouchLastPaintGenerationKey.trim().isEmpty();
    }

    private void releaseReadHoldAfterNoVisibleScrollOwner(String reason) {
        // WHY: entering native read-hold without one accepted renderer/cache
        // pixel freezes subsequent realtime frames. If a consumed gesture
        // releases with no exact visible owner, fail safe to the live stream;
        // cached rows stay staged and the next gesture may reacquire them.
        terminalModeGeneration++;
        terminalTouchGestureGeneration++;
        terminalHistoryDragActive = false;
        terminalHistoryMomentumActive = false;
        captureRendererHistoryMovementBlocked = false;
        terminalHistoryViewportActive = false;
        terminalTouchStartedInHistoryViewport = false;
        terminalTouchReachedLiveBottom = false;
        readModeSuppressesKeyboard = false;
        cancelHistoryMomentum("no-visible-scroll-owner");
        clearPendingHistoryScroll();
        clearCaptureRendererBlockedFingerDelta(reason);
        // WHY(stick-bottom cutover, task #21): never wipe the renderer-owned
        // release hold from this no-visible-owner cleanup. The transport
        // residual is reset before the asynchronous renderer release result,
        // so residual==0 cannot prove that the renderer has no held reading
        // position. The old check cleared an accepted hold on the next idle
        // stale-latch tick and snapped the phone to live bottom ~2s after UP.
        // Explicit Bottom/live-input/session-switch and non-drag tap paths
        // still clear their exact owners; a zero renderer nudge self-releases.
        syncCaptureRendererReadHold(reason);
        hideHistoryTouchOverlayQuietly();
        Log.i(CONTROL_LOG_TAG,
                "stage=touch-scroll-release endpoint=local"
                        + " actionId=" + safeLogToken(activeTouchScrollActionId)
                        + " windowId=" + safeWindowIdForControlLog(terminalTouchStableWindowId)
                        + " firstLocalFeedbackElapsedMs=" + touchScrollFirstLocalFeedbackElapsedMs()
                        + " result=no-visible-owner-release"
                        + " reason=" + safeLogToken(reason));
    }

    private long leaveReadModeForLiveInput() {
        return leaveReadModeForLiveInput(true, "user-live-follow");
    }

    private long leaveReadModeForLiveInput(boolean pinAfterOverlay) {
        return leaveReadModeForLiveInput(pinAfterOverlay, "user-live-follow");
    }

    private long leaveReadModeForLiveInput(
            boolean pinAfterOverlay,
            String terminalSnapshotReason
    ) {
        endTerminalSnapshotLease(
                terminalSnapshotReason,
                TerminalSnapshotEndMode.RECONCILE
        );
        long generation = ++terminalModeGeneration;
        terminalHistoryViewportActive = false;
        terminalTouchStartedInHistoryViewport = false;
        terminalTouchReachedLiveBottom = false;
        terminalTouchGestureGeneration++;
        readModeSuppressesKeyboard = false;
        // WHY(ROOT-C): every go-live path (tap-to-type, Send, Bottom, tab-open — 11 callers) funnels
        // here; drop the live-TUI scroll-lock so the existing sync below resumes follow. Covers the
        // cases the MOVE-handler down-drag doesn't (Send/Bottom without touching the terminal body).
        liveTuiScrollLockActive = false;
        liveTuiScrollLockWindowId = "";
        clearPendingHistoryScroll();
        clearCaptureRendererTouchNudge("live-input");
        syncCaptureRendererReadHold("live-input");
        if (pinAfterOverlay) {
            hideHistoryTouchOverlay();
        } else {
            // WHY: tap-to-type and Scroll -> live-bottom already wait for the
            // server's fast `/live-bottom` recovery. Running the full document
            // scroll pin here, before that recovery finishes, made the phone look
            // like it was refreshing up/down when the user tapped to place the
            // cursor. The success callback still does the cheap local pin.
            hideHistoryTouchOverlayQuietly();
        }
        return generation;
    }

    private void clearLocalHistoryTouchViewportForLiveBottom(String reason) {
        // WHY: explicit Bottom is the user's escape hatch from read/old-history
        // mode. `/touch-scroll` can take close to a second, so waiting for its
        // callback leaves native read-hold active and makes Bottom feel stuck.
        // Clear only the APK-local scrollback owner and inline paint surface here;
        // the server `/live-bottom` call below still reconciles authoritative tmux
        // state.
        terminalHistoryDragActive = false;
        terminalHistoryMomentumActive = false;
        captureRendererHistoryMovementBlocked = false;
        historyScrollRequestInFlight = false;
        activeHistoryScrollRequestSerial = -1;
        // WHY: WebView JS and `/scrollback/chunk` callbacks are asynchronous.
        // Give explicit Bottom a new action owner before clearing rows so every
        // queued history paint fails the bridge action/serial gate instead of
        // repainting the old cache over the live-bottom result.
        activeTouchScrollActionId = newTouchScrollActionId();
        activeTouchScrollVisibleDistinctRowDisplacement = 0;
        touchScrollVisualNudgeGeneration++;
        localHistoryTouchVisualNudgeGeneration++;
        pendingTouchVisualNudgePx = 0f;
        pendingLocalHistoryTouchVisualNudgePx = 0f;
        touchScrollVisualNudgeScheduled = false;
        localHistoryTouchVisualNudgeScheduled = false;
        terminalHistoryViewportActive = false;
        terminalTouchStartedInHistoryViewport = false;
        terminalTouchReachedLiveBottom = false;
        readModeSuppressesKeyboard = false;
        clearPendingHistoryScroll();
        clearPostReleaseTouchScrollCommit();
        clearCaptureRendererTouchNudge("live-bottom-clear-inline-local-history");
        localHistoryTouchViewportRows.clear();
        localHistoryTouchViewportWindowId = "";
        localHistoryTouchViewportGenerationKey = "";
        resetCaptureRendererReadyHistoryLiveRowFrontier(
                "live-bottom");
        localHistoryTouchViewportStart = "";
        localHistoryTouchViewportActionId = "";
        localHistoryTouchViewportOffset = 0;
        resetLocalHistoryTouchAcceptedPaintTrack();
        localHistoryTouchViewportLastVisualRowsConsumed = 0;
        localHistoryTouchViewportPaintFingerNudgePx = 0f;
        captureRendererTouchFingerNudgeResidualPx = 0f;
        localHistoryTouchFingerNudgeResidualPx = 0f;
        localHistoryTouchViewportAlreadyRenderedOnly = false;
        localHistoryTouchViewportUpdatedAtMs = 0;
        syncCaptureRendererReadHold("live-bottom-clear-inline-local-history");
        if (webView != null && Build.VERSION.SDK_INT >= Build.VERSION_CODES.KITKAT) {
            webView.evaluateJavascript(
                    "(function(){"
                            + "try{"
                            + "var renderer=window.__mantisCaptureRenderer;"
                            + "if(renderer&&typeof renderer.resetReadyHistoryForBottom==='function'){renderer.resetReadyHistoryForBottom();}"
                            + "var snapshot=window.__weztermLiveCaptureSnapshot;"
                            + "if(snapshot&&snapshot.html!=null){"
                            + "var restored=snapshot.screenId?document.getElementById(snapshot.screenId):null;"
                            + "if(!restored){restored=document.querySelector('#screen[data-active=\"1\"],#screenNext[data-active=\"1\"]');}"
                            + "if(restored){restored.innerHTML=snapshot.html;restored.style.transform=snapshot.transform||'none';restored.style.willChange=snapshot.willChange||'';}"
                            + "}"
                            + "var screens=document.querySelectorAll('[data-wezterm-inline-local-history]');"
                            + "for(var i=0;i<screens.length;i++){"
                            + "screens[i].removeAttribute('data-wezterm-inline-local-history');"
                            + "screens[i].removeAttribute('data-wezterm-local-history-paint');"
                            + "screens[i].removeAttribute('data-wezterm-local-history-window');"
                            + "}"
                            + "delete window.__weztermInlineLocalHistory;"
                            + "delete window.__weztermLiveCaptureSnapshot;"
                            + "return 'clear-inline-local-history';"
                            + "}catch(e){return 'clear-inline-local-history-error';}"
                    + "})()",
                    result -> Log.i(CONTROL_LOG_TAG,
                            "stage=local-history-owner endpoint=/live-bottom result=clear-inline-local-history"
                                    + " actionId=" + safeLogToken(activeTouchScrollActionId)
                                    + " reason=" + safeLogToken(reason)
                                    + " jsResult=" + safeLogToken(String.valueOf(result)))
            );
        }
        Log.i(CONTROL_LOG_TAG,
                "stage=local-history-owner endpoint=/live-bottom result=local-history-read-hold-cleared"
                        + " actionId=" + safeLogToken(activeTouchScrollActionId)
                        + " reason=" + safeLogToken(reason));
    }

    private void showHistoryTouchOverlay() {
        if (historyTouchOverlay == null) {
            return;
        }
        // WHY: Android WebView/xterm can swallow synthetic and real touch
        // gestures in different horizontal zones while the terminal is in
        // history mode. A transparent overlay only during read/history mode
        // makes swiping deterministic across the whole terminal pane without
        // interfering with normal live typing, link taps, or the xterm textarea.
        historyTouchOverlay.setVisibility(View.VISIBLE);
        historyTouchOverlay.bringToFront();
    }

    private void showPromptComposerSubmitTouchOverlay(String reason) {
        if (historyTouchOverlay == null) {
            return;
        }
        long generation = ++promptComposerSubmitTouchOwnerGeneration;
        promptComposerSubmitTouchOverlayVisible = true;
        // WHY: Send/Stop are remote-control actions, not modal app states. Android
        // can spend a few frames tearing down the native EditText/IME after local
        // Send acknowledgement, and the backend POST/GET can finish later. Keep the
        // transparent terminal touch owner above WebView during that bounded window
        // so a one-finger scroll starts in `handleTerminalTouch()` immediately
        // instead of waiting for `/submit-text` or `/stop` callbacks. The overlay is
        // bounded touch ownership, not a loading lock: touch/scroll/send/stop remain
        // independent while each network request settles on its own callback path.
        historyTouchOverlay.setVisibility(View.VISIBLE);
        historyTouchOverlay.bringToFront();
        Log.i(CONTROL_LOG_TAG,
                "stage=send-touch-owner endpoint=overlay result=armed"
                        + " reason=" + safeLogToken(reason));
        uiHandler.postDelayed(
                () -> hidePromptComposerSubmitTouchOverlayIfCurrent(reason + "-timeout", generation),
                PROMPT_COMPOSER_SUBMIT_TOUCH_OWNER_MS
        );
    }

    private boolean isPromptComposerSubmitTouchOverlayActive() {
        return promptComposerSubmitTouchOverlayVisible
                && historyTouchOverlay != null
                && historyTouchOverlay.getVisibility() == View.VISIBLE
                && !terminalHistoryViewportActive
                && !readModeSuppressesKeyboard;
    }

    private void hidePromptComposerSubmitTouchOverlayIfCurrent(String reason, long generation) {
        if (generation != promptComposerSubmitTouchOwnerGeneration) {
            return;
        }
        promptComposerSubmitTouchOverlayVisible = false;
        if (historyTouchOverlay != null
                && !terminalHistoryViewportActive
                && !readModeSuppressesKeyboard) {
            historyTouchOverlay.setVisibility(View.GONE);
        }
        Log.i(CONTROL_LOG_TAG,
                "stage=send-touch-owner endpoint=overlay result=hidden"
                        + " reason=" + safeLogToken(reason));
    }

    private void hideHistoryTouchOverlay() {
        hideHistoryTouchOverlayQuietly();
        pinTerminalViewportSoon("leave-read-mode");
    }

    private void hideHistoryTouchOverlayQuietly() {
        promptComposerSubmitTouchOverlayVisible = false;
        if (historyTouchOverlay != null) {
            historyTouchOverlay.setVisibility(View.GONE);
        }
    }

    private void pinTerminalViewportLocal() {
        if (webView == null) {
            return;
        }
        if (webView.getScrollX() != 0 || webView.getScrollY() != 0) {
            if (isViewerPanAllowed()) {
                return;
            }
            webView.scrollTo(0, 0);
        }
    }

    private void pinTerminalViewportSoon(String reason) {
        if (webView == null || Build.VERSION.SDK_INT < Build.VERSION_CODES.KITKAT) {
            return;
        }
        if (isTerminalGestureRecoveryActive()) {
            return;
        }
        if (isViewerPanAllowed()) {
            // WHY: this pin exists only to clean up accidental document scroll.
            // During zoomed/two-finger/horizontal positioning, native WebView
            // scroll is the user's viewport, so pinning here recreates the exact
            // "I can zoom but cannot move left/right" regression.
            return;
        }
        long now = System.currentTimeMillis();
        if (now - lastViewportPinAtMs < 80) {
            return;
        }
        lastViewportPinAtMs = now;
        pinTerminalViewportLocal();
        // WHY: ttyd/xterm has its own scrollback, but the surrounding HTML
        // document can still acquire a scroll offset after tab switches, older
        // sessions, IME resizes, or WebView gesture handoff. If the document
        // scrolls, the phone shows blank space below the prompt and it feels
        // like the page is refreshing. Pin html/body to the viewport and reset
        // document scroll without touching xterm's internal history buffer.
        webView.evaluateJavascript(
                "(function(){"
                        + "try{"
                        + captureRendererGeometryOnlyReturnScript("pin-" + reason)
                        + "var html=document.documentElement;"
                        + "var body=document.body;"
                        + "if(html){html.style.overflow='hidden';html.style.height='100%';html.style.overscrollBehavior='none';html.scrollTop=0;html.scrollLeft=0;}"
                        + "if(body){body.style.overflow='hidden';body.style.height='100%';body.style.margin='0';body.style.overscrollBehavior='none';body.scrollTop=0;body.scrollLeft=0;}"
                        + "var scrolling=document.scrollingElement;"
                        + "if(scrolling){scrolling.scrollTop=0;scrolling.scrollLeft=0;}"
                        + "window.scrollTo(0,0);"
                        + "return 'pinned';"
                        + "}catch(e){return 'err';}"
                + "})()",
                null
        );
        uiHandler.postDelayed(() -> {
            if (webView != null && !isTerminalGestureRecoveryActive()) {
                pinTerminalViewportLocal();
            }
        }, 120);
    }

    private String captureRendererGeometryOnlyReturnScript(String reason) {
        String safeReason = sanitizeJavascriptReason(reason);
        // WHY: the visible terminal is now the control-server capture renderer,
        // not ttyd/xterm, when this marker exists. Old xterm settle scripts
        // must not reset document scroll, rewrite html/body height, dispatch
        // resize, or scrub canvas layers on capture pages; that is what made
        // tap/send/down-scroll repaint black while the accepted visualViewport
        // anchor was already correct.
        return "var capture=document.querySelector('[data-mantis-capture-renderer=\"1\"]');"
                + "if(capture){"
                + "var r=window.__mantisCaptureRenderer;"
                + "if(r&&typeof r.measure==='function'){r.measure();}"
                + "return 'capture-renderer:" + safeReason + "';"
                + "}";
    }

    private void hideKeyboardForReadMode() {
        // WHY: reader/page controls are navigation, not input. Delayed xterm
        // focus retries can otherwise reopen Samsung's keyboard and cover the
        // transcript. This blur path must stay paired with the touch handler's
        // two-finger pass-through and tap-to-Live restore; otherwise fixing
        // scrollback reintroduces the older "cannot see what I am typing" bug.
        hideTerminalKeyboardQuietly("read-mode");
    }

    private void hideTerminalKeyboardQuietly(String reason) {
        InputMethodManager inputMethodManager =
                (InputMethodManager) getSystemService(Context.INPUT_METHOD_SERVICE);
        if (webView != null) {
            // WHY: hiding the native composer must not leave Android serving
            // xterm's hidden textarea. That state shows the keyboard while the
            // toolbar says Start and makes the terminal look vertically clipped.
            // Blur xterm and hide IME from both WebView and decor tokens.
            webView.evaluateJavascript(
                    "(function(){"
                            + "try{"
                            + "var el=document.querySelector('.xterm-helper-textarea, .xterm textarea, textarea');"
                            + "if(el&&typeof el.blur==='function'){el.blur();}"
                            + "if(document.activeElement&&typeof document.activeElement.blur==='function'){document.activeElement.blur();}"
                            + "return 'blurred';"
                            + "}catch(e){return 'err';}"
                    + "})()",
                    null
            );
            webView.clearFocus();
            if (inputMethodManager != null) {
                inputMethodManager.hideSoftInputFromWindow(webView.getWindowToken(), 0);
            }
        }
        View decor = getWindow().getDecorView();
        if (inputMethodManager != null && decor != null) {
            inputMethodManager.hideSoftInputFromWindow(decor.getWindowToken(), 0);
        }
    }

    private void showToolbarSettings() {
        hideDockedPromptComposerForNavigation("toolbar-settings-dialog");
        beginApkAction("settings-open", visibleTerminalTargetKey());
        markApkFirstLocalFeedback("settings-dialog-local", visibleTerminalTargetKey());
        boolean mobileViewport = VIEWPORT_MODE_MOBILE.equals(currentViewportMode());
        final String[] labels = {
                mobileViewport ? "Switch to Desktop viewport" : "Switch to Mobile viewport",
                "Refresh",
                "Scroll",
                "Option keys",
                "Codex account",
                "Title authority…",
                "Needs Attention"
        };
        new AlertDialog.Builder(this)
                .setTitle("Settings")
                .setItems(labels, (dialog, which) -> {
                    if (which == 0) {
                        // WHY: a status-looking "Viewport mode: Mobile" row
                        // failed real-phone proof because it did not read like
                        // a switch-back control. Keep an explicit first-row
                        // action so Mobile can always return to protected
                        // Desktop without resizing tmux or using Active.
                        setViewportMode(mobileViewport ? VIEWPORT_MODE_DESKTOP : VIEWPORT_MODE_MOBILE);
                    } else if (which == 1) {
                        refreshTerminalTransport();
                    } else if (which == 2) {
                        showViewControls();
                    } else if (which == 3) {
                        showKeyControls();
                    } else if (which == 4) {
                        showCodexAccountSettings();
                    } else if (which == 5) {
                        // WHY: FEATURE phone-side title-authority toggle. Opens the
                        // custom Codex/Claude control that round-trips
                        // /api/title-provider so the daemon re-reads the provider
                        // live each cycle and both the APK title and the PC tmux
                        // titles follow the phone selection.
                        showTitleAuthorityControls();
                    } else if (which == 6) {
                        showNeedsAttention();
                    }
                })
                .setNegativeButton("Cancel", null)
                .show();
        markApkFirstPaint("settings-dialog", "local-alert-dialog");
    }

    private void showTitleAuthorityControls() {
        hideDockedPromptComposerForNavigation("title-authority");
        // WHY: FEATURE mirror showKeyControls' persistent custom setView grid,
        // NOT a one-shot setItems list. The active provider must show a checkmark
        // and be repainted in place from the authoritative server round-trip,
        // which a fire-and-forget setItems list cannot express.
        LinearLayout grid = new LinearLayout(this);
        grid.setOrientation(LinearLayout.VERTICAL);
        grid.setPadding(dp(14), dp(10), dp(14), dp(8));
        final Button codexRow = button("Codex", null);
        final Button claudeRow = button("Claude", null);
        codexRow.setOnClickListener(v -> {
            flashTap(v);
            selectTitleAuthority("codex", codexRow, claudeRow);
        });
        claudeRow.setOnClickListener(v -> {
            flashTap(v);
            selectTitleAuthority("claude", codexRow, claudeRow);
        });
        // WHY: paint instantly from the prefs-cached last-known provider so the
        // checkmark is never blank while the authoritative GET is in flight; the
        // GET below corrects it if the live server disagrees.
        applyTitleAuthorityActiveRow(codexRow, claudeRow,
                prefs != null ? prefs.getString(PREF_TITLE_PROVIDER_LAST_KNOWN, "") : "");
        LinearLayout.LayoutParams codexParams = new LinearLayout.LayoutParams(
                LinearLayout.LayoutParams.MATCH_PARENT, dp(52));
        codexParams.setMargins(0, dp(4), 0, dp(4));
        grid.addView(codexRow, codexParams);
        LinearLayout.LayoutParams claudeParams = new LinearLayout.LayoutParams(
                LinearLayout.LayoutParams.MATCH_PARENT, dp(52));
        claudeParams.setMargins(0, dp(4), 0, dp(4));
        grid.addView(claudeRow, claudeParams);
        AlertDialog dialog = new AlertDialog.Builder(this)
                .setTitle("Title authority")
                .setView(grid)
                .setNegativeButton("Done", null)
                .create();
        // WHY: authoritative source of truth. On open, read /api/title-provider
        // and mark active from payload.titleProvider. Fail-closed: on GET failure
        // keep whatever the prefs-cache painted and toast the error; never guess.
        getJson("/api/title-provider", payload -> {
            String provider = normalizeTitleProvider(payload.optString("titleProvider", ""));
            if (provider.isEmpty()) {
                return;
            }
            rememberTitleProviderLastKnown(provider);
            applyTitleAuthorityActiveRow(codexRow, claudeRow, provider);
        }, exc -> toast("Title authority unavailable"));
        dialog.show();
    }

    private void selectTitleAuthority(String provider, Button codexRow, Button claudeRow) {
        String normalized = normalizeTitleProvider(provider);
        if (normalized.isEmpty()) {
            return;
        }
        // WHY: POST the selection and adopt the checkmark from the RESPONSE's
        // titleProvider only (authoritative round-trip). Do NOT optimistically
        // flip: if the server rejects or omits a provider, the visible active row
        // must stay on the prior confirmed state. Fail-closed on POST failure by
        // keeping the prior rows and toasting the error.
        String body = "{\"provider\":\"" + normalized + "\"}";
        postJson("/api/title-provider", body, payload -> {
            String applied = normalizeTitleProvider(payload.optString("titleProvider", ""));
            if (applied.isEmpty()) {
                toast("Title authority unchanged");
                return;
            }
            rememberTitleProviderLastKnown(applied);
            applyTitleAuthorityActiveRow(codexRow, claudeRow, applied);
            toast("Title authority: " + applied);
        }, exc -> toast("Title authority change failed"));
    }

    private void applyTitleAuthorityActiveRow(Button codexRow, Button claudeRow, String active) {
        String normalized = normalizeTitleProvider(active);
        // WHY: the checkmark marks the single active provider; the other row stays
        // a plain label so the phone shows exactly one authority at a glance.
        codexRow.setText("codex".equals(normalized) ? "✓ Codex" : "Codex");
        claudeRow.setText("claude".equals(normalized) ? "✓ Claude" : "Claude");
    }

    private String normalizeTitleProvider(String value) {
        if (value == null) {
            return "";
        }
        String normalized = value.trim().toLowerCase(Locale.US);
        // WHY: only the two known authorities are valid. Anything else (empty,
        // error text, a future provider the APK does not model) normalizes to ""
        // so callers fail closed instead of painting a bogus checkmark.
        if (normalized.equals("codex") || normalized.equals("claude")) {
            return normalized;
        }
        return "";
    }

    private void rememberTitleProviderLastKnown(String provider) {
        String normalized = normalizeTitleProvider(provider);
        if (normalized.isEmpty() || prefs == null) {
            return;
        }
        prefs.edit().putString(PREF_TITLE_PROVIDER_LAST_KNOWN, normalized).apply();
    }

    private void setViewportMode(String nextMode) {
        String normalized = VIEWPORT_MODE_MOBILE.equals(nextMode)
                ? VIEWPORT_MODE_MOBILE
                : VIEWPORT_MODE_DESKTOP;
        String current = currentViewportMode();
        if (normalized.equals(current)) {
            toast("Viewport mode " + viewportModeLabel());
            return;
        }
        prefs.edit().putString(PREF_VIEWPORT_MODE, normalized).apply();
        // WHY: viewport mode is a renderer query contract only. Reload the
        // capture page with the same stable target, but never resize tmux or
        // alter the touch/zoom handlers that protect Desktop mode.
        loadTerminal();
        toast("Viewport mode " + viewportModeLabel());
    }

    private void showViewControls() {
        hideDockedPromptComposerForNavigation("scroll-dialog");
        String[] labels = new String[]{
                "Go to live bottom / type",
                "Go to history top",
                "Read current session",
                "Local history search",
                "Page up",
                "Page down"
        };
        new AlertDialog.Builder(this)
                .setTitle("Scroll")
                .setItems(labels, (dialog, which) -> {
                    if (which == 0) {
                        goLiveBottom();
                    } else if (which == 1) {
                        enterReadMode();
                        // WHY: success Toasts for visual scroll controls cover
                        // the terminal bottom/prompt on Android; errors still toast.
                        scrollTerminal("top", "", false);
                    } else if (which == 2) {
                        openFullSessionReader();
                    } else if (which == 3) {
                        showLocalHistoryViewer();
                    } else if (which == 4) {
                        enterReadMode();
                        scrollTerminal("pageUp", "", false);
                    } else if (which == 5) {
                        enterReadMode();
                        scrollTerminal("pageDown", "", false);
                    }
                })
                .setNegativeButton("Cancel", null)
                .show();
    }

    private LocalHistoryRequest localHistoryRequestForVisibleTarget() {
        // WHY: local history must bind to the terminal body Android is already
        // showing, not process-global `/active`. Other lanes can retarget tmux
        // `main_phone` while this APK is still displaying a previous pane; a
        // history cache keyed from `/active` would show stale/wrong-session rows
        // and could tempt future fixes to reload WebView or disturb Send.
        String windowId = confirmedVisibleTerminalTargetKey();
        if (!hasStableWindowId(windowId)) {
            windowId = visibleTerminalTargetKey();
        }
        String visibleFrameHash = "";
        if (hasStableWindowId(windowId)
                && (windowId.equals(lastAcceptedCaptureRendererFrameWindowId)
                || windowId.equals(confirmedCaptureRendererFrameWindowTargetKey))
                && lastAcceptedCaptureRendererFrameHash != null
                && !lastAcceptedCaptureRendererFrameHash.trim().isEmpty()) {
            visibleFrameHash = lastAcceptedCaptureRendererFrameHash.trim();
        }
        String interactiveWindowId = "";
        if (hasStableWindowId(windowId) && windowId.equals(selectedPhoneWindowId)) {
            interactiveWindowId = selectedPhoneInteractiveWindowId;
        }
        String sessionInteractionState = "";
        if (hasStableWindowId(windowId) && windowId.equals(lastSessionInteractionWindowId)) {
            sessionInteractionState = lastSessionInteractionState;
        }
        return new LocalHistoryRequest(
                windowId,
                visibleFrameHash,
                interactiveWindowId,
                "",
                "",
                sessionInteractionState
        );
    }

    private LocalHistoryRequest localHistoryRequestForTouchTarget(String targetKey) {
        LocalHistoryRequest request = localHistoryRequestForVisibleTarget();
        String stableTargetKey = targetKey == null ? "" : targetKey.trim();
        if (!hasStableWindowId(stableTargetKey) || stableTargetKey.equals(request.windowId)) {
            return request;
        }
        return new LocalHistoryRequest(
                stableTargetKey,
                request.visibleFrameHash,
                request.interactiveWindowId,
                request.sessionId,
                request.threadId,
                request.sessionInteractionState
        );
    }

    private void showLocalHistoryViewer() {
        hideDockedPromptComposerForNavigation("local-history");
        LocalHistoryRequest request = localHistoryRequestForVisibleTarget();
        if (!hasStableWindowId(request.windowId)) {
            toast("Visible session id missing");
            return;
        }
        fetchLocalHistoryChunk(request, "");
    }

    private void fetchLocalHistoryChunk(LocalHistoryRequest request, String start) {
        if (request == null || !hasStableWindowId(request.windowId)) {
            toast("Visible session id missing");
            return;
        }
        LocalHistoryChunk cached = findCachedLocalHistoryChunk(request, start);
        if (cached != null) {
            try {
                showLocalHistoryDialog(request, localHistoryPayloadForDisplay(cached, true));
            } catch (Exception exc) {
                toast("Local history failed: " + exc.getMessage());
            }
            return;
        }
        String normalizedStart = normalizeLocalHistoryStart(start);
        // WHY: SCROLL #29 wrap-parity — request the SAME measured cols the
        // touch-scroll prefetch uses (mobile → the phone's measured width) so the
        // server wraps these rows identically to live; the touch paths already do
        // this via localHistoryRendererColsForRequest. Fall back to the Desktop 132
        // grid when the renderer width isn't measured yet, never an invalid width.
        int dialogCols = localHistoryRendererColsForRequest(request);
        if (dialogCols < 20) {
            dialogCols = APK_CAPTURE_RENDERER_COLS;
        }
        String path = "/scrollback/chunk?windowId=" + urlEncode(request.windowId)
                + "&lines=" + LOCAL_HISTORY_CHUNK_LINES
                + "&cols=" + dialogCols;
        if (!normalizedStart.isEmpty()) {
            path += "&start=" + urlEncode(normalizedStart);
        }
        getJsonWithRetry(path, payload -> {
            if (!payload.optBoolean("ok", false)) {
                toast(payload.optString("error", "Local history unavailable"));
                return;
            }
            LocalHistoryChunk chunk = rememberLocalHistoryChunk(request, start, payload);
            if (chunk == null) {
                toast("Local history identity mismatch");
                return;
            }
            try {
                showLocalHistoryDialog(request, localHistoryPayloadForDisplay(chunk, false));
            } catch (Exception exc) {
                toast("Local history failed: " + exc.getMessage());
            }
        }, exc -> toast("Mantis Control is not reachable"));
    }

    private int localHistoryRendererColsForRequest(LocalHistoryRequest request) {
        if (!VIEWPORT_MODE_MOBILE.equals(currentViewportMode())) {
            return APK_CAPTURE_RENDERER_COLS;
        }
        // WHY: Mobile live rows are measured by the actual generated renderer.
        // Reusing Desktop's 132 columns for cache rows changes wrapping/right bounds
        // at the seam even though both row classes share the same DOM and CSS.
        if (request != null
                && request.windowId.equals(lastAcceptedCaptureRendererFrameWindowId)
                && lastAcceptedCaptureRendererCols >= 20) {
            return lastAcceptedCaptureRendererCols;
        }
        return -1;
    }

    private void prefetchLocalHistoryForTouchScroll(String targetKey, String where, int repeats, long requestSerial) {
        // WHY: APK-TRANSCRIPT-HISTORY-CACHE-VIRTUALIZED-2032-A splits ownership:
        // one-finger historical reading warms target-bound local `/scrollback/chunk`
        // rows, while fresh bottom/live content stays streamed by the capture
        // renderer. Without this cache warmup, read-mode falls back to visible
        // capture-frame chunks and the phone feels like it hits invisible
        // section boundaries even though tmux moved into older history.
        LocalHistoryRequest request = localHistoryRequestForTouchTarget(targetKey);
        String stableTargetKey = targetKey == null ? "" : targetKey.trim();
        if (!hasStableWindowId(request.windowId)) {
            Log.i(CONTROL_LOG_TAG,
                    "stage=local-history-cache endpoint=/scrollback/chunk result=prefetch-skipped"
                            + " actionId=" + safeLogToken(activeTouchScrollActionId)
                            + " reason=missing-window"
                            + " windowId=" + safeWindowIdForControlLog(stableTargetKey)
                            + " where=" + safeLogToken(where));
            return;
        }
        int renderCols = localHistoryRendererColsForRequest(request);
        if (renderCols < 20) {
            Log.i(CONTROL_LOG_TAG,
                    "stage=local-history-cache endpoint=/scrollback/chunk result=prefetch-skipped"
                            + " actionId=" + safeLogToken(activeTouchScrollActionId)
                            + " reason=renderer-cols-unavailable"
                            + " windowId=" + safeWindowIdForControlLog(request.windowId));
            return;
        }
        if (shouldBlockLocalHistoryTouchForRequest(request)
                && shouldBlockLocalHistoryTouchForTarget(request.windowId)) {
            Log.i(CONTROL_LOG_TAG,
                    "stage=local-history-cache endpoint=/scrollback/chunk result=prefetch-skipped"
                            + " actionId=" + safeLogToken(activeTouchScrollActionId)
                            + " reason=" + localHistoryTouchBlockReason(request.windowId)
                            + " windowId=" + safeWindowIdForControlLog(request.windowId)
                            + " visibleWindowId=" + safeWindowIdForControlLog(visibleTerminalTargetKey())
                            + " currentWindowId=" + safeWindowIdForControlLog(currentPhoneWindowId)
                            + " frameWindowId=" + safeWindowIdForControlLog(lastAcceptedCaptureRendererFrameWindowId)
                            + " state=" + safeLogToken(lastSessionInteractionState)
                            + " blockedReason=" + safeLogToken(lastSessionInteractionBlockedReason)
                            + " where=" + safeLogToken(where)
                            + " request=" + requestSerial);
            return;
        }
        if (canPrefetchLocalHistoryBeforeAcceptedFrame(request)) {
            Log.i(CONTROL_LOG_TAG,
                    "stage=local-history-cache endpoint=/scrollback/chunk result=prefetch-allowed"
                            + " actionId=" + safeLogToken(activeTouchScrollActionId)
                            + " reason=stable-visible-target-before-accepted-frame"
                            + " windowId=" + safeWindowIdForControlLog(request.windowId)
                            + " visibleWindowId=" + safeWindowIdForControlLog(visibleTerminalTargetKey())
                            + " currentWindowId=" + safeWindowIdForControlLog(currentPhoneWindowId)
                            + " frameWindowId=" + safeWindowIdForControlLog(lastAcceptedCaptureRendererFrameWindowId)
                            + " where=" + safeLogToken(where)
                            + " request=" + requestSerial);
        }
        LocalHistoryChunk cached = findCachedLocalHistoryChunk(request, "");
        if (cached != null) {
            LocalHistoryChunk adjacentSource = localHistoryAdjacentPrefetchSourceChunk(request, cached);
            stageReadyLocalHistoryBatchForRenderer(
                    request,
                    cached,
                    "touch-cache-hit",
                    result -> {
                        if (readyHistoryStageRequestsNext(result, adjacentSource)) {
                            prefetchAdjacentLocalHistoryChunkForTouch(
                                    request,
                                    adjacentSource.payload,
                                    requestSerial
                            );
                        }
                    }
            );
            Log.i(CONTROL_LOG_TAG,
                    "stage=local-history-cache endpoint=/scrollback/chunk result=prefetch-hit"
                            + " actionId=" + safeLogToken(activeTouchScrollActionId)
                            + " windowId=" + safeWindowIdForControlLog(request.windowId)
                            + " where=" + safeLogToken(where)
                            + " firstLocalFeedbackElapsedMs=" + touchScrollFirstLocalFeedbackElapsedMs()
                            + " repeats=" + Math.max(1, repeats)
                            + " request=" + requestSerial);
            renderInlineLocalHistoryRowsForTouch(
                    request,
                    cached,
                    where,
                    repeats,
                    requestSerial,
                    "inline-local-history-cache",
                    true
            );
            return;
        }
        String normalizedStart = "";
        String prefetchKey = localHistoryTouchPrefetchKey(request, normalizedStart);
        if (localHistoryTouchPrefetchInFlight.containsKey(prefetchKey)) {
            Log.i(CONTROL_LOG_TAG,
                    "stage=local-history-cache endpoint=/scrollback/chunk result=prefetch-in-flight"
                            + " actionId=" + safeLogToken(activeTouchScrollActionId)
                            + " windowId=" + safeWindowIdForControlLog(request.windowId)
                            + " where=" + safeLogToken(where)
                            + " request=" + requestSerial);
            return;
        }
        localHistoryTouchPrefetchInFlight.put(prefetchKey, SystemClock.elapsedRealtime());
        evictLocalHistoryTouchPrefetchIfNeeded();
        String path = "/scrollback/chunk?windowId=" + urlEncode(request.windowId)
                + "&lines=" + LOCAL_HISTORY_CHUNK_LINES
                + "&cols=" + renderCols;
        Log.i(CONTROL_LOG_TAG,
                "stage=local-history-cache endpoint=/scrollback/chunk result=prefetch-scheduled"
                        + " actionId=" + safeLogToken(activeTouchScrollActionId)
                        + " windowId=" + safeWindowIdForControlLog(request.windowId)
                        + " where=" + safeLogToken(where)
                        + " firstLocalFeedbackElapsedMs=" + touchScrollFirstLocalFeedbackElapsedMs()
                        + " repeats=" + Math.max(1, repeats)
                        + " request=" + requestSerial);
        seedInlineLocalHistoryRowsForTouch(request, where, repeats, requestSerial);
        LocalHistoryRequest finalRequest = request;
        getJson(path, payload -> {
            Long startedAtMs = localHistoryTouchPrefetchInFlight.remove(prefetchKey);
            annotateLocalHistoryPrepareElapsed(payload, startedAtMs);
            if (!payload.optBoolean("ok", false)) {
                Log.i(CONTROL_LOG_TAG,
                        "stage=local-history-cache endpoint=/scrollback/chunk result=prefetch-rejected"
                                + " actionId=" + safeLogToken(activeTouchScrollActionId)
                                + " reason=not-ok"
                                + " windowId=" + safeWindowIdForControlLog(finalRequest.windowId)
                                + " request=" + requestSerial);
                return;
            }
            LocalHistoryChunk chunk = rememberLocalHistoryChunk(finalRequest, "", payload);
            if (chunk == null) {
                Log.i(CONTROL_LOG_TAG,
                        "stage=local-history-cache endpoint=/scrollback/chunk result=prefetch-rejected"
                                + " actionId=" + safeLogToken(activeTouchScrollActionId)
                                + " reason=identity-mismatch"
                                + " windowId=" + safeWindowIdForControlLog(finalRequest.windowId)
                                + " request=" + requestSerial);
                return;
            }
            Log.i(CONTROL_LOG_TAG,
                    "stage=local-history-cache endpoint=/scrollback/chunk result=prefetch-stored"
                            + " actionId=" + safeLogToken(activeTouchScrollActionId)
                            + " windowId=" + safeWindowIdForControlLog(finalRequest.windowId)
                            + " generationKey=" + safeLogToken(chunk.identity.generationKey)
                            + " firstLocalFeedbackElapsedMs=" + touchScrollFirstLocalFeedbackElapsedMs()
                            + " request=" + requestSerial);
            renderInlineLocalHistoryRowsForTouch(
                    finalRequest,
                    chunk,
                    where,
                    repeats,
                    requestSerial,
                    "inline-local-history-cache-fill",
                    false
            );
            LocalHistoryChunk adjacentSource = localHistoryAdjacentPrefetchSourceChunk(finalRequest, chunk);
            stageReadyLocalHistoryBatchForRenderer(
                    finalRequest,
                    chunk,
                    "touch-cache-fill",
                    result -> {
                        if (readyHistoryStageRequestsNext(result, adjacentSource)) {
                            prefetchAdjacentLocalHistoryChunkForTouch(finalRequest, adjacentSource.payload, requestSerial);
                        }
                    }
            );
        }, exc -> {
            localHistoryTouchPrefetchInFlight.remove(prefetchKey);
            notifyReadyHistoryRefillFailed("touch-cache-fetch-failed");
            Log.i(CONTROL_LOG_TAG,
                    "stage=local-history-cache endpoint=/scrollback/chunk result=prefetch-failed"
                            + " actionId=" + safeLogToken(activeTouchScrollActionId)
                            + " windowId=" + safeWindowIdForControlLog(finalRequest.windowId)
                            + " request=" + requestSerial
                            + " error=" + safeLogToken(exc.getClass().getSimpleName()));
        });
    }

    private void prewarmLocalHistoryForVisibleTarget(String reason) {
        prewarmLocalHistoryForRequest(localHistoryRequestForVisibleTarget(), reason);
    }

    private void prewarmLocalHistoryForWindow(String windowId, String reason) {
        if (!hasStableWindowId(windowId)) {
            return;
        }
        prewarmLocalHistoryForRequest(localHistoryRequestForTouchTarget(windowId.trim()), reason);
    }

    private void prewarmLocalHistoryForRequest(LocalHistoryRequest request, String reason) {
        if (!activityResumed || request == null || !hasStableWindowId(request.windowId)) {
            return;
        }
        int renderCols = localHistoryRendererColsForRequest(request);
        if (renderCols < 20) {
            Log.i(CONTROL_LOG_TAG,
                    "stage=local-history-cache endpoint=/scrollback/chunk result=prewarm-skipped"
                            + " reason=renderer-cols-unavailable"
                            + " source=" + safeLogToken(reason)
                            + " windowId=" + safeWindowIdForControlLog(request.windowId));
            return;
        }
        if (targetHasConfirmedTranscriptBodyBlock(request.windowId)) {
            Log.i(CONTROL_LOG_TAG,
                    "stage=local-history-cache endpoint=/scrollback/chunk result=prewarm-skipped"
                            + " reason=confirmed-transcript-block"
                            + " source=" + safeLogToken(reason)
                            + " windowId=" + safeWindowIdForControlLog(request.windowId));
            return;
        }
        LocalHistoryChunk cachedPrewarm = findCachedLocalHistoryChunk(request, "");
        if (cachedPrewarm != null) {
            Log.i(CONTROL_LOG_TAG,
                    "stage=local-history-cache endpoint=/scrollback/chunk result=prewarm-hit"
                            + " reason=" + safeLogToken(reason)
                            + " windowId=" + safeWindowIdForControlLog(request.windowId));
            stageReadyLocalHistoryBatchForRenderer(request, cachedPrewarm, "prewarm-hit-" + reason);
            return;
        }
        String normalizedStart = "";
        String prewarmKey = localHistoryTouchPrefetchKey(request, normalizedStart);
        long now = SystemClock.elapsedRealtime();
        if (prewarmKey.equals(lastLocalHistoryPrewarmKey)
                && now - lastLocalHistoryPrewarmAtMs < LOCAL_HISTORY_PREWARM_MIN_INTERVAL_MS) {
            return;
        }
        if (localHistoryTouchPrefetchInFlight.containsKey(prewarmKey)) {
            Log.i(CONTROL_LOG_TAG,
                    "stage=local-history-cache endpoint=/scrollback/chunk result=prewarm-in-flight"
                            + " reason=" + safeLogToken(reason)
                            + " windowId=" + safeWindowIdForControlLog(request.windowId));
            return;
        }
        lastLocalHistoryPrewarmKey = prewarmKey;
        lastLocalHistoryPrewarmAtMs = now;
        localHistoryTouchPrefetchInFlight.put(prewarmKey, now);
        evictLocalHistoryTouchPrefetchIfNeeded();
        String path = "/scrollback/chunk?windowId=" + urlEncode(request.windowId)
                + "&lines=" + LOCAL_HISTORY_CHUNK_LINES
                + "&cols=" + renderCols;
        LocalHistoryRequest finalRequest = request;
        String safeReason = reason == null ? "" : reason;
        Log.i(CONTROL_LOG_TAG,
                "stage=local-history-cache endpoint=/scrollback/chunk result=prewarm-scheduled"
                        + " reason=" + safeLogToken(safeReason)
                        + " windowId=" + safeWindowIdForControlLog(finalRequest.windowId));
        getJson(path, payload -> {
            Long startedAtMs = localHistoryTouchPrefetchInFlight.remove(prewarmKey);
            annotateLocalHistoryPrepareElapsed(payload, startedAtMs);
            if (!payload.optBoolean("ok", false)) {
                Log.i(CONTROL_LOG_TAG,
                        "stage=local-history-cache endpoint=/scrollback/chunk result=prewarm-rejected"
                                + " reason=not-ok"
                                + " source=" + safeLogToken(safeReason)
                                + " windowId=" + safeWindowIdForControlLog(finalRequest.windowId));
                return;
            }
            LocalHistoryChunk chunk = rememberLocalHistoryChunk(finalRequest, "", payload);
            if (chunk == null) {
                Log.i(CONTROL_LOG_TAG,
                        "stage=local-history-cache endpoint=/scrollback/chunk result=prewarm-rejected"
                                + " reason=identity-mismatch"
                                + " source=" + safeLogToken(safeReason)
                                + " windowId=" + safeWindowIdForControlLog(finalRequest.windowId));
                return;
            }
            Log.i(CONTROL_LOG_TAG,
                    "stage=local-history-cache endpoint=/scrollback/chunk result=prewarm-stored"
                            + " reason=" + safeLogToken(safeReason)
                            + " windowId=" + safeWindowIdForControlLog(finalRequest.windowId)
                            + " generationKey=" + safeLogToken(chunk.identity.generationKey));
            maybeRenderPrewarmedLocalHistoryForActiveTouch(finalRequest, chunk, safeReason);
            LocalHistoryChunk adjacentSource = localHistoryAdjacentPrefetchSourceChunk(finalRequest, chunk);
            stageReadyLocalHistoryBatchForRenderer(
                    finalRequest,
                    chunk,
                    "prewarm-fill-" + safeReason,
                    result -> {
                        if (readyHistoryStageRequestsNext(result, adjacentSource)) {
                            prefetchAdjacentLocalHistoryChunkForTouch(finalRequest, adjacentSource.payload, activeHistoryScrollRequestSerial);
                        }
                    }
            );
        }, exc -> {
            localHistoryTouchPrefetchInFlight.remove(prewarmKey);
            notifyReadyHistoryRefillFailed("prewarm-fetch-failed");
            Log.i(CONTROL_LOG_TAG,
                    "stage=local-history-cache endpoint=/scrollback/chunk result=prewarm-failed"
                            + " reason=" + safeLogToken(safeReason)
                            + " windowId=" + safeWindowIdForControlLog(finalRequest.windowId)
                            + " error=" + safeLogToken(exc.getClass().getSimpleName()));
        });
    }

    private void maybeRenderPrewarmedLocalHistoryForActiveTouch(
            LocalHistoryRequest request,
            LocalHistoryChunk chunk,
            String reason
    ) {
        if (!LOCAL_HISTORY_INLINE_GESTURE_PAINT_ENABLED) {
            // Cache prewarm still supplies target-bound data. It must not turn an
            // async response into a second visible surface during the gesture.
            return;
        }
        if (request == null || chunk == null || activeHistoryScrollRequestSerial <= 0) {
            return;
        }
        String activeWhere = !terminalHistoryDragWhere.isEmpty()
                ? terminalHistoryDragWhere
                : pendingHistoryScrollWhere;
        if (!"lineUp".equals(activeWhere) && !"lineDown".equals(activeWhere)) {
            return;
        }
        LocalHistoryRequest activeRequest = localHistoryRequestForTouchTarget(terminalTouchStableWindowId);
        if (!request.windowId.equals(activeRequest.windowId)) {
            return;
        }
        int repeats = Math.max(1, pendingHistoryScrollRepeats);
        renderInlineLocalHistoryRowsForTouch(
                request,
                chunk,
                activeWhere,
                repeats,
                activeHistoryScrollRequestSerial,
                "inline-local-history-cache-prewarm-fill-" + reason,
                false
        );
    }

    private boolean updateLocalHistoryTouchViewportBeforeBackend(
            String targetKey,
            String where,
            int repeats,
            long requestSerial,
            String source
    ) {
        if (!LOCAL_HISTORY_INLINE_GESTURE_PAINT_ENABLED) {
            // The capture renderer moves physical pixels now; advancing a cached
            // row offset before tmux/frame reconciliation recreates row stepping.
            Log.i(CONTROL_LOG_TAG,
                    "stage=local-history-viewport endpoint=local-cache"
                            + " result=data-only-single-renderer"
                            + " actionId=" + safeLogToken(activeTouchScrollActionId)
                            + " windowId=" + safeWindowIdForControlLog(targetKey)
                            + " where=" + safeLogToken(where)
                            + " request=" + requestSerial);
            return false;
        }
        if (!"lineUp".equals(where) && !"lineDown".equals(where)) {
            logLocalHistoryTouchViewportNoop(
                    null,
                    "skipped",
                    "unsupported-where",
                    where,
                    repeats,
                    requestSerial,
                    source,
                    -1
            );
            return false;
        }
        LocalHistoryRequest request = localHistoryRequestForTouchTarget(targetKey);
        if (!hasStableWindowId(request.windowId)) {
            logLocalHistoryTouchViewportNoop(
                    request,
                    "skipped",
                    "missing-window",
                    where,
                    repeats,
                    requestSerial,
                    source,
                    -1
            );
            return false;
        }
        if ("lineDown".equals(where)) {
            clearLocalHistoryTouchTopEdgeHold(request, "lineDown", requestSerial);
        }
        if (shouldBlockLocalHistoryTouchForRequest(request)) {
            logLocalHistoryTouchViewportNoop(
                    request,
                    "skipped",
                    localHistoryTouchBlockReason(request.windowId),
                    where,
                    repeats,
                    requestSerial,
                    source,
                    -1
            );
            return false;
        }
        LocalHistoryChunk cached = findCachedLocalHistoryChunk(request, "");
        if (cached != null) {
            try {
                List<LocalHistoryPaintRow> rows = localHistoryPaintRowsFromPayload(cached.payload, true);
                String rejectReason = localHistoryPaintRowsRejectReason(rows, true);
                if (rejectReason.isEmpty()) {
                    ensureLocalHistoryTouchViewportRows(
                            request,
                            cached,
                            rows,
                            false,
                            false,
                            false,
                            "inline-local-history-viewport-cache",
                            requestSerial
                    );
                } else {
                    logInlineLocalHistoryRejected(request, source, rejectReason, where, repeats, requestSerial);
                    logLocalHistoryTouchViewportNoop(
                            request,
                            "cache-rejected",
                            rejectReason,
                            where,
                            repeats,
                            requestSerial,
                            source,
                            rows == null ? -1 : rows.size()
                    );
                }
            } catch (Exception exc) {
                Log.i(CONTROL_LOG_TAG,
                        "stage=local-history-viewport endpoint=local-cache result=cache-parse-failed"
                                + " actionId=" + safeLogToken(activeTouchScrollActionId)
                                + " tapId=" + safeLogToken(currentApkTapIdForLog())
                                + " windowId=" + safeWindowIdForControlLog(request.windowId)
                                + " exception=" + safeLogToken(exc.getClass().getSimpleName())
                                + " cacheRows=-1"
                                + " viewportRows=" + localHistoryTouchViewportRows.size()
                                + " renderRows=" + localHistoryTouchInlineFeedbackRows()
                                + " currentOffset=" + localHistoryTouchViewportOffset
                                + " maxOffset=" + localHistoryTouchViewportMaxOffset()
                                + " hasMoreBefore=" + localHistoryBoundaryHasMoreBeforeForRequest(request)
                                + " copyModeViewport=" + localHistoryBoundaryCopyModeForRequest(request)
                                + " scrollPosition=" + localHistoryBoundaryScrollPositionForRequest(request)
                                + " historySize=" + localHistoryBoundaryHistorySizeForRequest(request)
                                + " paneInMode=" + localHistoryBoundaryPaneInModeForRequest(request)
                                + " targetBodyContinuityProven=" + targetHasUsableAcceptedBodyFrame(request.windowId)
                                + " state=" + safeLogToken(lastSessionInteractionState)
                                + " blockedReason=" + safeLogToken(lastSessionInteractionBlockedReason)
                                + " beforeTouchScrollResponse=true"
                                + " beforeScrollbackChunkResponse=true"
                                + " beforeTerminalFrameResponse=true"
                                + " source=" + safeLogToken(source)
                                + " request=" + requestSerial);
            }
        } else if (!localHistoryTouchViewportWindowId.equals(request.windowId)
                || localHistoryTouchViewportRows.isEmpty()) {
            logLocalHistoryTouchViewportNoop(
                    request,
                    "cache-miss",
                    "no-cached-scrollback-chunk",
                    where,
                    repeats,
                    requestSerial,
                    source,
                    -1
            );
            seedLocalHistoryTouchViewportFromAcceptedFrame(request, where, repeats, requestSerial);
        }
        if (!localHistoryTouchViewportWindowId.equals(request.windowId)
                || localHistoryTouchViewportRows.isEmpty()) {
            logLocalHistoryTouchViewportNoop(
                    request,
                    localHistoryBoundaryEvidenceForRequest(request)
                            ? "needs-local-history-cache-seed"
                            : "no-local-viewport",
                    "empty-or-target-mismatched-viewport",
                    where,
                    repeats,
                    requestSerial,
                    source,
                    cached == null ? -1 : localHistoryTouchViewportRows.size()
            );
            return false;
        }
        int previousOffset = localHistoryTouchViewportOffset;
        int step = Math.max(1, repeats);
        int maxOffset = localHistoryTouchViewportMaxOffset();
        int nextOffset = previousOffset;
        if ("lineUp".equals(where)) {
            nextOffset -= step;
        } else {
            nextOffset += step;
        }
        nextOffset = Math.max(0, Math.min(nextOffset, maxOffset));
        int visualRowsConsumed = localHistoryEstimatedVisualRowsBetweenOffsets(previousOffset, nextOffset);
        if (previousOffset != nextOffset
                && shouldHoldLocalHistoryLogicalRowCommitForFingerResidual(
                request,
                where,
                step,
                visualRowsConsumed,
                requestSerial,
                source)) {
            // WHY: hold-before-transfer/no-clear-before-hold. A visual-row hold
            // means local-history will not paint this MOVE; clearing the live
            // capture nudge here would remove the only visible pixel owner and
            // snap to the bottom-to-cache transition boundary.
            paintHeldLocalHistoryViewportBeforeRowCommit(
                    request,
                    where,
                    repeats,
                    requestSerial,
                    source
            );
            return false;
        }
        transferCaptureRendererTouchNudgeToLocalHistoryHandoff(
                request,
                where,
                requestSerial,
                source
        );
        localHistoryTouchViewportPaintFingerNudgePx = localHistoryTouchFingerNudgeResidualPx;
        localHistoryTouchViewportOffset = nextOffset;
        localHistoryTouchViewportLastVisualRowsConsumed = visualRowsConsumed;
        settleLocalHistoryFingerResidualAfterVisualRows(visualRowsConsumed);
        if (previousOffset == localHistoryTouchViewportOffset) {
            if (shouldHoldLocalHistoryTouchTopEdge(request, where)) {
                recordLocalHistoryTouchTopEdgeHold(request, where, repeats, requestSerial, source);
                return true;
            }
            logLocalHistoryTouchViewportNoop(
                    request,
                    localHistoryBoundaryEvidenceForRequest(request)
                            ? "needs-local-history-cache-seed"
                            : "viewport-unmovable",
                    "offset-unchanged-after-clamp",
                    where,
                    repeats,
                    requestSerial,
                    source,
                    localHistoryTouchViewportRows.size()
            );
            return false;
        }
        clearLocalHistoryTouchTopEdgeHold(request, "offset-updated", requestSerial);
        localHistoryTouchViewportUpdatedAtMs = SystemClock.elapsedRealtime();
        syncCaptureRendererReadHold("local-history-viewport-offset-updated");
        Log.i(CONTROL_LOG_TAG,
                "stage=local-history-viewport endpoint=local-cache result=offset-updated-before-touch-scroll"
                        + " actionId=" + safeLogToken(activeTouchScrollActionId)
                        + " tapId=" + safeLogToken(currentApkTapIdForLog())
                        + " windowId=" + safeWindowIdForControlLog(request.windowId)
                        + " where=" + safeLogToken(where)
                        + " repeats=" + Math.max(1, repeats)
                        + " visualRowsConsumed=" + Math.max(0, visualRowsConsumed)
                        + " previousOffset=" + previousOffset
                        + " viewportOffset=" + localHistoryTouchViewportOffset
                        + " viewportRows=" + localHistoryTouchViewportRows.size()
                        + " generationKey=" + safeLogToken(localHistoryTouchViewportGenerationKey)
                        + " renderRows=" + localHistoryTouchInlineFeedbackRows()
                        + " currentOffset=" + localHistoryTouchViewportOffset
                        + " maxOffset=" + localHistoryTouchViewportMaxOffset()
                        + " hasMoreBefore=" + localHistoryBoundaryHasMoreBeforeForRequest(request)
                        + " copyModeViewport=" + localHistoryBoundaryCopyModeForRequest(request)
                        + " scrollPosition=" + localHistoryBoundaryScrollPositionForRequest(request)
                        + " historySize=" + localHistoryBoundaryHistorySizeForRequest(request)
                        + " paneInMode=" + localHistoryBoundaryPaneInModeForRequest(request)
                        + " targetBodyContinuityProven=" + targetHasUsableAcceptedBodyFrame(request.windowId)
                        + " beforeTouchScrollResponse=true"
                        + " beforeScrollbackChunkResponse=true"
                        + " beforeTerminalFrameResponse=true"
                        + " source=" + safeLogToken(source)
                        + " request=" + requestSerial);
        paintLocalHistoryTouchViewport(
                request,
                null,
                where,
                repeats,
                requestSerial,
                "inline-local-history-viewport",
                true
        );
        return false;
    }

    private void paintHeldLocalHistoryViewportBeforeRowCommit(
            LocalHistoryRequest request,
            String where,
            int repeats,
            long requestSerial,
            String source
    ) {
        if (request == null || !localHistoryTouchViewportTargetsRequest(request)) {
            return;
        }
        // WHY: the clean-transition falsifier showed the cached owner existed in
        // Java, but the DOM had no inline local-history surface yet. The code then
        // kept dispatching row/viewport commits while
        // `local-history-finger-nudge-missing` meant the finger had no visible
        // local surface. Paint the current cached viewport with the live residual
        // before advancing the logical row offset; later MOVE samples can then
        // apply same-frame local-history nudges instead of waiting and jumping.
        if (Math.abs(captureRendererTouchFingerNudgeResidualPx) >= 0.5f) {
            localHistoryTouchFingerNudgeResidualPx += captureRendererTouchFingerNudgeResidualPx;
            captureRendererTouchFingerNudgeResidualPx = 0f;
            clearCaptureRendererTouchNudgeForLocalHistoryHandoff(
                    "local-history-hold-surface-before-row-commit"
            );
        }
        localHistoryTouchViewportPaintFingerNudgePx = localHistoryTouchFingerNudgeResidualPx;
        Log.i(CONTROL_LOG_TAG,
                "stage=local-history-viewport endpoint=local-cache"
                        + " result=hold-surface-painted-before-row-commit"
                        + " actionId=" + safeLogToken(activeTouchScrollActionId)
                        + " tapId=" + safeLogToken(currentApkTapIdForLog())
                        + " windowId=" + safeWindowIdForControlLog(request.windowId)
                        + " where=" + safeLogToken(where)
                        + " repeats=" + Math.max(1, repeats)
                        + " localResidualPx=" + touchLogFloat(localHistoryTouchFingerNudgeResidualPx)
                        + " source=" + safeLogToken(source)
                        + " request=" + requestSerial);
        paintLocalHistoryTouchViewport(
                request,
                null,
                where,
                repeats,
                requestSerial,
                "inline-local-history-viewport",
                true
        );
    }

    private void seedLocalHistoryTouchViewportFromAcceptedFrame(
            LocalHistoryRequest request,
            String where,
            int repeats,
            long requestSerial
    ) {
        if (request == null || !hasStableWindowId(request.windowId)) {
            logLocalHistoryTouchViewportNoop(
                    request,
                    "seed-skipped",
                    "missing-window",
                    where,
                    repeats,
                    requestSerial,
                    "inline-local-history-viewport-seed",
                    -1
            );
            return;
        }
        if (!request.windowId.equals(lastAcceptedCaptureRendererFrameWindowId)
                && !request.windowId.equals(confirmedCaptureRendererFrameWindowTargetKey)) {
            logLocalHistoryTouchViewportNoop(
                    request,
                    "seed-skipped",
                    "accepted-frame-mismatch",
                    where,
                    repeats,
                    requestSerial,
                    "inline-local-history-viewport-seed",
                    -1
            );
            return;
        }
        List<LocalHistoryPaintRow> rows = lastAcceptedCaptureRendererPaintRowsForLocalHistorySeed();
        if (rows.isEmpty()) {
            logLocalHistoryTouchViewportNoop(
                    request,
                    localHistoryBoundaryEvidenceForRequest(request)
                            ? "needs-local-history-cache-seed"
                            : "seed-skipped",
                    "no-accepted-frame-rows",
                    where,
                    repeats,
                    requestSerial,
                    "inline-local-history-viewport-seed",
                    0
            );
            return;
        }
        String rejectReason = localHistoryPaintRowsRejectReason(rows, true);
        if (!rejectReason.isEmpty()) {
            logInlineLocalHistoryRejected(
                    request,
                    "inline-local-history-viewport-seed",
                    rejectReason,
                    where,
                    repeats,
                    requestSerial
            );
            logLocalHistoryTouchViewportNoop(
                    request,
                    localHistoryBoundaryEvidenceForRequest(request)
                            ? "needs-local-history-cache-seed"
                            : "seed-rejected",
                    rejectReason,
                    where,
                    repeats,
                    requestSerial,
                    "inline-local-history-viewport-seed",
                    rows.size()
            );
            return;
        }
        replaceLocalHistoryTouchViewportRows(
                request.windowId,
                request.visibleFrameHash,
                "",
                rows,
                true,
                "inline-local-history-viewport-seed",
                requestSerial
        );
    }

    private void logLocalHistoryTouchViewportNoop(
            LocalHistoryRequest request,
            String result,
            String reason,
            String where,
            int repeats,
            long requestSerial,
            String source,
            int cacheRows
    ) {
        String windowId = request == null ? "" : request.windowId;
        // WHY: the installed 2256c9e4 regression had tmux/copy-mode evidence that
        // older rows existed, but the APK local viewport could silently return
        // before seed/cache movement. Keep every no-op action-correlated so T5
        // proof fails on the missing local owner instead of appearing green.
        Log.i(CONTROL_LOG_TAG,
                "stage=local-history-viewport endpoint=local-cache"
                        + " result=" + safeLogToken(result)
                        + " actionId=" + safeLogToken(activeTouchScrollActionId)
                        + " tapId=" + safeLogToken(currentApkTapIdForLog())
                        + " windowId=" + safeWindowIdForControlLog(windowId)
                        + " reason=" + safeLogToken(reason)
                        + " where=" + safeLogToken(where)
                        + " repeats=" + Math.max(1, repeats)
                        + " request=" + requestSerial
                        + " cacheRows=" + cacheRows
                        + " viewportRows=" + localHistoryTouchViewportRows.size()
                        + " renderRows=" + localHistoryTouchInlineFeedbackRows()
                        + " currentOffset=" + localHistoryTouchViewportOffset
                        + " maxOffset=" + localHistoryTouchViewportMaxOffset()
                        + " hasMoreBefore=" + localHistoryBoundaryHasMoreBeforeForRequest(request)
                        + " copyModeViewport=" + localHistoryBoundaryCopyModeForRequest(request)
                        + " scrollPosition=" + localHistoryBoundaryScrollPositionForRequest(request)
                        + " historySize=" + localHistoryBoundaryHistorySizeForRequest(request)
                        + " paneInMode=" + localHistoryBoundaryPaneInModeForRequest(request)
                        + " targetBodyContinuityProven=" + targetHasUsableAcceptedBodyFrame(windowId)
                        + " state=" + safeLogToken(lastSessionInteractionState)
                        + " blockedReason=" + safeLogToken(lastSessionInteractionBlockedReason)
                        + " beforeTouchScrollResponse=true"
                        + " beforeScrollbackChunkResponse=true"
                        + " beforeTerminalFrameResponse=true"
                        + " source=" + safeLogToken(source));
    }

    private int localHistoryTouchViewportMaxOffset() {
        int maxRows = localHistoryTouchInlineFeedbackRows();
        return Math.max(0, localHistoryTouchViewportRows.size() - maxRows);
    }

    private int localHistoryTouchInlineFeedbackRows() {
        int acceptedRendererRows = Math.max(
                lastAcceptedCaptureRendererRows.size(),
                lastAcceptedCaptureRendererPaintRows.size()
        );
        if (acceptedRendererRows <= 0) {
            return Math.max(1, LOCAL_HISTORY_TOUCH_INLINE_FEEDBACK_ROWS);
        }
        // WHY: cached scrollback paints into the same bottom-anchored capture
        // renderer as live mode. Desktop mode scales the 132-column layer down,
        // so the old fixed 96-row cache slice can cover only a bottom strip and
        // leave a black top box. Use the live renderer's measured row request as
        // the local-history viewport height, bounded by the existing cache cap,
        // so scrollback and live fit the phone viewport the same way.
        return Math.max(
                LOCAL_HISTORY_TOUCH_INLINE_FEEDBACK_ROWS,
                Math.min(LOCAL_HISTORY_TOUCH_VIEWPORT_MAX_ROWS, acceptedRendererRows)
        );
    }

    private boolean shouldHoldLocalHistoryLogicalRowCommitForFingerResidual(
            LocalHistoryRequest request,
            String where,
            int logicalRows,
            int visualRowsConsumed,
            long requestSerial,
            String source
    ) {
        if (visualRowsConsumed <= Math.max(1, logicalRows)) {
            return false;
        }
        int lineHeightPx = localHistoryEstimatedLineHeightPx();
        float requiredPx = visualRowsConsumed * Math.max(1, lineHeightPx);
        float localResidualPx = localHistoryTouchFingerNudgeResidualPx;
        float captureResidualPx = captureRendererTouchFingerNudgeResidualPx;
        float projectedResidualPx = localResidualPx + captureResidualPx;
        float residualPx = Math.abs(projectedResidualPx);
        if (residualPx + 0.5f >= requiredPx) {
            return false;
        }
        // WHY: cached local-history offsets are logical tmux/cache rows, but the
        // phone renderer wraps long source/output rows into multiple visible
        // terminal lines. Advancing `localHistoryTouchViewportOffset` by one
        // logical row before the finger has moved through that row's wrapped visual height
        // is the tiny-drag massive-jump regression. Hold the row
        // repaint and let the pixel nudge continue until the finger covers the
        // visual-row distance. Include the still-live capture residual in this
        // check without clearing it; if the hold wins, that live nudge remains
        // the visual owner until a later row commit can paint local history.
        Log.i(CONTROL_LOG_TAG,
                "stage=local-history-viewport endpoint=local-cache result=visual-row-hold"
                        + " actionId=" + safeLogToken(activeTouchScrollActionId)
                        + " tapId=" + safeLogToken(currentApkTapIdForLog())
                        + " windowId=" + safeWindowIdForControlLog(request == null ? "" : request.windowId)
                        + " where=" + safeLogToken(where)
                        + " logicalRows=" + Math.max(1, logicalRows)
                        + " visualRowsConsumed=" + Math.max(1, visualRowsConsumed)
                        + " residualPx=" + touchLogFloat(projectedResidualPx)
                        + " localResidualPx=" + touchLogFloat(localResidualPx)
                        + " captureResidualPx=" + touchLogFloat(captureResidualPx)
                        + " projectedResidualPx=" + touchLogFloat(projectedResidualPx)
                        + " requiredPx=" + touchLogFloat(requiredPx)
                        + " wrapCols=" + localHistoryEstimatedWrapCols()
                        + " handoff=no-clear-before-hold"
                        + " source=" + safeLogToken(source)
                        + " request=" + requestSerial);
        return true;
    }

    private int localHistoryEstimatedVisualRowsBetweenOffsets(int previousOffset, int nextOffset) {
        if (previousOffset == nextOffset || localHistoryTouchViewportRows.isEmpty()) {
            return 0;
        }
        int from = Math.max(0, Math.min(previousOffset, nextOffset));
        int to = Math.max(0, Math.max(previousOffset, nextOffset));
        to = Math.min(to, localHistoryTouchViewportRows.size());
        if (from >= to) {
            return 0;
        }
        int wrapCols = localHistoryEstimatedWrapCols();
        int visualRows = 0;
        for (int index = from; index < to; index++) {
            visualRows += localHistoryEstimatedVisualRows(localHistoryTouchViewportRows.get(index), wrapCols);
        }
        return Math.max(1, visualRows);
    }

    private int localHistoryEstimatedVisualRows(LocalHistoryPaintRow row, int wrapCols) {
        if (row == null) {
            return 1;
        }
        String value = row.text == null ? "" : row.text;
        if (value.isEmpty() && row.ansi != null && !row.ansi.isEmpty()) {
            value = stripAnsiForLocalHistory(row.ansi);
        }
        if (value.isEmpty()) {
            return 1;
        }
        int cols = Math.max(12, wrapCols);
        int visualRows = 0;
        String[] parts = value.split("\\n", -1);
        for (String part : parts) {
            int length = part == null ? 0 : part.length();
            visualRows += Math.max(1, (int) Math.ceil(length / (double) cols));
        }
        return Math.max(1, visualRows);
    }

    private int localHistoryEstimatedWrapCols() {
        int lineHeightPx = localHistoryEstimatedLineHeightPx();
        int widthPx = 0;
        if (terminalFrame != null && terminalFrame.getWidth() > 0) {
            widthPx = terminalFrame.getWidth();
        } else if (webView != null && webView.getWidth() > 0) {
            widthPx = webView.getWidth();
        }
        if (widthPx <= 0) {
            return 80;
        }
        int charWidthPx = Math.max(6, Math.round(lineHeightPx * 0.56f));
        return Math.max(24, Math.min(160, Math.max(1, widthPx - dp(12)) / charWidthPx));
    }

    private int localHistoryEstimatedLineHeightPx() {
        return Math.max(dp(8), historyDragLineThresholdPx());
    }

    private int localHistoryTouchCommitVisualRowsForPaint(int repeats, String source) {
        int fallback = Math.max(1, repeats);
        if (!"inline-local-history-viewport".equals(source)) {
            return fallback;
        }
        return Math.max(fallback, localHistoryTouchViewportLastVisualRowsConsumed);
    }

    private void settleLocalHistoryFingerResidualAfterVisualRows(int visualRowsConsumed) {
        if (visualRowsConsumed <= 0 || Math.abs(localHistoryTouchFingerNudgeResidualPx) < 0.5f) {
            return;
        }
        float commitPx = localHistoryEstimatedLineHeightPx() * Math.max(1, visualRowsConsumed);
        if (localHistoryTouchFingerNudgeResidualPx > 0f) {
            localHistoryTouchFingerNudgeResidualPx -= commitPx;
        } else {
            localHistoryTouchFingerNudgeResidualPx += commitPx;
        }
        if (Math.abs(localHistoryTouchFingerNudgeResidualPx) < 0.5f) {
            localHistoryTouchFingerNudgeResidualPx = 0f;
        }
    }

    private boolean localHistoryBoundaryEvidenceForRequest(LocalHistoryRequest request) {
        return localHistoryBoundaryHasMoreBeforeForRequest(request)
                || localHistoryBoundaryCopyModeForRequest(request);
    }

    private boolean localHistoryBoundaryHasMoreBeforeForRequest(LocalHistoryRequest request) {
        return localHistoryBoundaryMetadataTargetsRequest(request)
                && lastAcceptedCaptureRendererHasMoreBefore;
    }

    private boolean localHistoryBoundaryCopyModeForRequest(LocalHistoryRequest request) {
        return localHistoryBoundaryMetadataTargetsRequest(request)
                && (lastAcceptedCaptureRendererCopyModeViewport
                || lastAcceptedCaptureRendererPaneInMode > 0);
    }

    private int localHistoryBoundaryScrollPositionForRequest(LocalHistoryRequest request) {
        return localHistoryBoundaryMetadataTargetsRequest(request)
                ? lastAcceptedCaptureRendererScrollPosition
                : -1;
    }

    private int localHistoryBoundaryHistorySizeForRequest(LocalHistoryRequest request) {
        return localHistoryBoundaryMetadataTargetsRequest(request)
                ? lastAcceptedCaptureRendererHistorySize
                : -1;
    }

    private int localHistoryBoundaryPaneInModeForRequest(LocalHistoryRequest request) {
        return localHistoryBoundaryMetadataTargetsRequest(request)
                ? lastAcceptedCaptureRendererPaneInMode
                : -1;
    }

    private boolean localHistoryBoundaryMetadataTargetsRequest(LocalHistoryRequest request) {
        if (request == null || !hasStableWindowId(request.windowId)) {
            return false;
        }
        String windowId = request.windowId.trim();
        return windowId.equals(lastAcceptedCaptureRendererFrameWindowId)
                || windowId.equals(confirmedCaptureRendererFrameWindowTargetKey);
    }

    private void ensureLocalHistoryTouchViewportRows(
            LocalHistoryRequest request,
            LocalHistoryChunk chunk,
            List<LocalHistoryPaintRow> rows,
            boolean mergeBoundary,
            boolean prependBoundary,
            boolean alreadyRenderedOnly,
            String source,
            long requestSerial
    ) {
        if (request == null || chunk == null || chunk.identity == null || rows == null || rows.isEmpty()) {
            return;
        }
        String generationKey = localHistoryViewportGenerationKey(chunk);
        boolean sameOwner = localHistoryTouchViewportWindowId.equals(request.windowId)
                && localHistoryTouchViewportGenerationKey.equals(generationKey);
        if (!sameOwner || localHistoryTouchViewportRows.isEmpty()) {
            String nextKey = localHistoryTouchViewportKey(
                    request.windowId,
                    generationKey,
                    chunk.identity.start
            );
            if (shouldPreserveLocalHistoryTouchViewportTrackForAction(
                    request.windowId,
                    nextKey,
                    source,
                    alreadyRenderedOnly,
                    requestSerial,
                    "ensure-viewport")) {
                return;
            }
            replaceLocalHistoryTouchViewportRows(
                    request.windowId,
                    generationKey,
                    chunk.identity.start,
                    rows,
                    alreadyRenderedOnly,
                    source,
                    requestSerial
            );
            return;
        }
        if (!mergeBoundary || chunk.identity.start.equals(localHistoryTouchViewportStart)) {
            return;
        }
        int beforeRows = localHistoryTouchViewportRows.size();
        if (prependBoundary) {
            prependLocalHistoryTouchViewportRows(rows);
        } else {
            appendLocalHistoryTouchViewportRows(rows);
        }
        localHistoryTouchViewportStart = chunk.identity.start;
        localHistoryTouchViewportActionId = currentLocalHistoryTouchViewportActionId();
        localHistoryTouchViewportAlreadyRenderedOnly = alreadyRenderedOnly;
        localHistoryTouchViewportUpdatedAtMs = SystemClock.elapsedRealtime();
        clampLocalHistoryTouchViewportOffset();
        if (terminalHistoryDragActive && !activeTouchScrollActionId.isEmpty()) {
            activeTouchScrollLocalHistoryBoundaryMergedAtMs = localHistoryTouchViewportUpdatedAtMs;
            activeTouchScrollLocalHistoryBoundaryActionId = activeTouchScrollActionId;
            activeTouchScrollLocalHistoryBoundaryRows = localHistoryTouchViewportRows.size();
        }
        syncCaptureRendererReadHold("local-history-boundary-merge");
        Log.i(CONTROL_LOG_TAG,
                "stage=local-history-viewport endpoint=/scrollback/chunk"
                        + " result=" + (prependBoundary ? "boundary-prepended" : "boundary-appended")
                        + " actionId=" + safeLogToken(activeTouchScrollActionId)
                        + " windowId=" + safeWindowIdForControlLog(request.windowId)
                        + " start=" + safeLogToken(chunk.identity.start)
                        + " boundary=" + safeLogToken(prependBoundary ? "prepend" : "append")
                        + " beforeRows=" + beforeRows
                        + " viewportRows=" + localHistoryTouchViewportRows.size()
                        + " source=" + safeLogToken(source)
                        + " activeTouchBoundaryMerged=true"
                        + " request=" + requestSerial);
    }

    private void replaceLocalHistoryTouchViewportRows(
            String windowId,
            String generationKey,
            String start,
            List<LocalHistoryPaintRow> rows,
            boolean alreadyRenderedOnly,
            String source,
            long requestSerial
    ) {
        String normalizedWindowId = windowId == null ? "" : windowId.trim();
        String normalizedGenerationKey = generationKey == null ? "" : generationKey.trim();
        String normalizedStart = start == null ? "" : start.trim();
        String nextKey = localHistoryTouchViewportKey(
                normalizedWindowId,
                normalizedGenerationKey,
                normalizedStart
        );
        if (shouldPreserveLocalHistoryTouchViewportTrackForAction(
                normalizedWindowId,
                nextKey,
                source,
                alreadyRenderedOnly,
                requestSerial,
                "replace-viewport")) {
            return;
        }
        localHistoryTouchViewportRows.clear();
        appendLocalHistoryTouchViewportRows(rows);
        localHistoryTouchViewportWindowId = normalizedWindowId;
        localHistoryTouchViewportGenerationKey = normalizedGenerationKey;
        localHistoryTouchViewportStart = normalizedStart;
        localHistoryTouchViewportActionId = currentLocalHistoryTouchViewportActionId();
        // WHY: `/scrollback/chunk` is oldest-to-newest. The first finger MOVE
        // must begin beside the latest visible output at maxOffset; starting at
        // zero replaces the live rows with the oldest part of a 500-row chunk.
        localHistoryTouchViewportOffset = localHistoryTouchViewportMaxOffset();
        resetLocalHistoryTouchAcceptedPaintTrack();
        localHistoryTouchViewportLastVisualRowsConsumed = 0;
        localHistoryTouchViewportPaintFingerNudgePx = 0f;
        localHistoryTouchViewportAlreadyRenderedOnly = alreadyRenderedOnly;
        localHistoryTouchViewportUpdatedAtMs = SystemClock.elapsedRealtime();
        syncCaptureRendererReadHold("local-history-viewport-replaced");
        Log.i(CONTROL_LOG_TAG,
                "stage=local-history-viewport endpoint=local-cache result=viewport-replaced"
                        + " actionId=" + safeLogToken(activeTouchScrollActionId)
                        + " windowId=" + safeWindowIdForControlLog(localHistoryTouchViewportWindowId)
                        + " generationKey=" + safeLogToken(localHistoryTouchViewportGenerationKey)
                        + " viewportRows=" + localHistoryTouchViewportRows.size()
                        + " renderRows=" + localHistoryTouchInlineFeedbackRows()
                        + " source=" + safeLogToken(source)
                        + " request=" + requestSerial);
    }

    private void appendLocalHistoryTouchViewportRows(List<LocalHistoryPaintRow> rows) {
        if (rows == null || rows.isEmpty()) {
            return;
        }
        for (LocalHistoryPaintRow row : rows) {
            if (row != null) {
                localHistoryTouchViewportRows.add(row);
            }
        }
        while (localHistoryTouchViewportRows.size() > LOCAL_HISTORY_TOUCH_VIEWPORT_MAX_ROWS) {
            localHistoryTouchViewportRows.remove(0);
            if (localHistoryTouchViewportOffset > 0) {
                localHistoryTouchViewportOffset--;
            }
        }
    }

    private void prependLocalHistoryTouchViewportRows(List<LocalHistoryPaintRow> rows) {
        if (rows == null || rows.isEmpty()) {
            return;
        }
        List<LocalHistoryPaintRow> mergedRows = new ArrayList<>();
        for (LocalHistoryPaintRow row : rows) {
            if (row != null) {
                mergedRows.add(row);
            }
        }
        if (mergedRows.isEmpty()) {
            return;
        }
        mergedRows.addAll(localHistoryTouchViewportRows);
        localHistoryTouchViewportRows.clear();
        localHistoryTouchViewportRows.addAll(mergedRows);
        localHistoryTouchViewportOffset += rows.size();
        while (localHistoryTouchViewportRows.size() > LOCAL_HISTORY_TOUCH_VIEWPORT_MAX_ROWS) {
            localHistoryTouchViewportRows.remove(localHistoryTouchViewportRows.size() - 1);
        }
    }

    private void paintLocalHistoryTouchViewport(
            LocalHistoryRequest request,
            LocalHistoryChunk chunk,
            String where,
            int repeats,
            long requestSerial,
            String source,
            boolean beforeScrollbackChunkResponse
    ) {
        if (request == null
                || !request.windowId.equals(localHistoryTouchViewportWindowId)
                || localHistoryTouchViewportRows.isEmpty()) {
            return;
        }
        LocalHistoryViewportSlice viewportSlice = localHistoryTouchViewportSlice();
        if (viewportSlice.rows.isEmpty()) {
            return;
        }
        paintInlineLocalHistoryRowsInRenderer(
                viewportSlice,
                request,
                chunk,
                where,
                repeats,
                requestSerial,
                source,
                beforeScrollbackChunkResponse
        );
    }

    private LocalHistoryViewportSlice localHistoryTouchViewportSlice() {
        List<LocalHistoryPaintRow> visibleRows = new ArrayList<>();
        if (localHistoryTouchViewportRows.isEmpty()) {
            return new LocalHistoryViewportSlice(
                    visibleRows,
                    localHistoryTouchViewportKey(),
                    0,
                    0,
                    localHistoryTouchViewportAlreadyRenderedOnly
            );
        }
        clampLocalHistoryTouchViewportOffset();
        int maxRows = localHistoryTouchInlineFeedbackRows();
        int start = Math.max(0, Math.min(localHistoryTouchViewportOffset, localHistoryTouchViewportRows.size() - 1));
        int end = Math.min(localHistoryTouchViewportRows.size(), start + maxRows);
        for (int index = start; index < end; index++) {
            visibleRows.add(localHistoryTouchViewportRows.get(index));
        }
        return new LocalHistoryViewportSlice(
                visibleRows,
                localHistoryTouchViewportKey(),
                start,
                localHistoryTouchViewportRows.size(),
                localHistoryTouchViewportAlreadyRenderedOnly
        );
    }

    private void clampLocalHistoryTouchViewportOffset() {
        int maxRows = localHistoryTouchInlineFeedbackRows();
        int maxOffset = Math.max(0, localHistoryTouchViewportRows.size() - maxRows);
        localHistoryTouchViewportOffset = Math.max(0, Math.min(localHistoryTouchViewportOffset, maxOffset));
    }

    private String localHistoryViewportGenerationKey(LocalHistoryChunk chunk) {
        if (chunk == null || chunk.identity == null) {
            return "";
        }
        if (!chunk.identity.generationKey.isEmpty()) {
            return chunk.identity.generationKey;
        }
        return chunk.identity.paneId + ":" + chunk.identity.generation;
    }

    private void renderInlineLocalHistoryRowsForTouch(
            LocalHistoryRequest request,
            LocalHistoryChunk chunk,
            String where,
            int repeats,
            long requestSerial,
            String source,
            boolean beforeScrollbackChunkResponse
    ) {
        if (request == null || chunk == null || !"lineUp".equals(where)) {
            return;
        }
        if (shouldDeferLocalHistoryAsyncPaintDuringActiveTouch(source)) {
            return;
        }
        List<LocalHistoryPaintRow> paintRows;
        try {
            paintRows = localHistoryPaintRowsFromPayload(chunk.payload, true);
        } catch (Exception exc) {
            Log.i(CONTROL_LOG_TAG,
                    "stage=local-history-inline endpoint=local-cache result=skipped"
                            + " actionId=" + safeLogToken(activeTouchScrollActionId)
                            + " reason=row-parse-failed"
                            + " exception=" + safeLogToken(exc.getClass().getSimpleName())
                            + " request=" + requestSerial);
            return;
        }
        String rejectReason = localHistoryPaintRowsRejectReason(paintRows, true);
        if (!rejectReason.isEmpty()) {
            logInlineLocalHistoryRejected(request, source, rejectReason, where, repeats, requestSerial);
            return;
        }
        LocalHistoryViewportSlice viewportSlice = localHistoryViewportSliceForTouchPaint(
                paintRows,
                request,
                chunk,
                where,
                repeats,
                source,
                false
        );
        if (viewportSlice.rows.isEmpty()) {
            return;
        }
        if (shouldDeferLocalHistoryAsyncPaintDuringActiveTouch(source)) {
            // WHY: boundary chunks can merge while this synchronous renderer
            // preparation is already in progress. Re-check immediately before
            // mutating WebView so an older prepared slice cannot repaint after
            // the boundary action owner has taken over the visible viewport.
            return;
        }
        paintInlineLocalHistoryRowsInRenderer(
                viewportSlice,
                request,
                chunk,
                where,
                repeats,
                requestSerial,
                source,
                beforeScrollbackChunkResponse
        );
    }

    private void seedInlineLocalHistoryRowsForTouch(
            LocalHistoryRequest request,
            String where,
            int repeats,
            long requestSerial
    ) {
        if (request == null || !"lineUp".equals(where) || !hasStableWindowId(request.windowId)) {
            return;
        }
        if (!request.windowId.equals(lastAcceptedCaptureRendererFrameWindowId)
                && !request.windowId.equals(confirmedCaptureRendererFrameWindowTargetKey)) {
            return;
        }
        if (localHistoryTouchViewportHasCanonicalRowsFor(request)) {
            // WHY: cache-miss seed is continuity-only. Once a target-bound canonical
            // old-history viewport exists, a later seed callback must not clear that
            // viewport back to the currently visible frame and yank the row under the
            // user's finger.
            paintLocalHistoryTouchViewport(
                    request,
                    null,
                    where,
                    repeats,
                    requestSerial,
                    "inline-local-history-seed-canonical",
                    true
            );
            Log.i(CONTROL_LOG_TAG,
                    "stage=local-history-owner endpoint=local-cache result=seed-suppressed-canonical-owner"
                            + " actionId=" + safeLogToken(activeTouchScrollActionId)
                            + " tapId=" + safeLogToken(currentApkTapIdForLog())
                            + " windowId=" + safeWindowIdForControlLog(request.windowId)
                            + " source=inline-local-history-seed"
                            + " localViewportOffset=" + localHistoryTouchViewportOffset
                            + " localHistoryCachedRows=" + localHistoryTouchViewportRows.size()
                            + " where=" + safeLogToken(where)
                            + " repeats=" + Math.max(1, repeats)
                            + " request=" + requestSerial);
            return;
        }
        List<LocalHistoryPaintRow> paintRows = lastAcceptedCaptureRendererPaintRowsForLocalHistorySeed();
        if (paintRows.isEmpty()) {
            Log.i(CONTROL_LOG_TAG,
                    "stage=local-history-inline endpoint=local-cache result=seed-skipped"
                            + " actionId=" + safeLogToken(activeTouchScrollActionId)
                            + " reason=no-accepted-frame-rows"
                            + " windowId=" + safeWindowIdForControlLog(request.windowId)
                            + " request=" + requestSerial);
            return;
        }
        // WHY: one-finger old-history seed is a terminal renderer surface, not
        // a plain transcript/source text fallback. If the accepted capture frame
        // has no ANSI rows yet, skip seed and wait for cache fill. Seed paint is
        // already-rendered continuity only; cached scrollback rows below are the
        // first-new-readable local old-history owner.
        String rejectReason = localHistoryPaintRowsRejectReason(paintRows, true);
        if (!rejectReason.isEmpty()) {
            logInlineLocalHistoryRejected(
                    request,
                    "inline-local-history-seed",
                    rejectReason,
                    where,
                    repeats,
                    requestSerial
            );
            return;
        }
        LocalHistoryViewportSlice viewportSlice = inlineLocalHistoryPaintRowsForTouch(
                paintRows,
                request,
                null,
                where,
                repeats,
                "inline-local-history-seed",
                true
        );
        if (viewportSlice.rows.isEmpty()) {
            return;
        }
        Log.i(CONTROL_LOG_TAG,
                "stage=local-history-inline endpoint=local-cache result=seeded-before-network"
                        + " actionId=" + safeLogToken(activeTouchScrollActionId)
                        + " tapId=" + safeLogToken(currentApkTapIdForLog())
                        + " windowId=" + safeWindowIdForControlLog(request.windowId)
                        + " source=inline-local-history-seed"
                        + " firstNewReadableRow=false"
                        + " alreadyRenderedOnly=true"
                        + " localViewportOffset=" + Math.max(0, viewportSlice.firstRow)
                        + " rows=" + viewportSlice.rows.size()
                        + " where=" + safeLogToken(where)
                        + " repeats=" + Math.max(1, repeats)
                        + " request=" + requestSerial);
        paintInlineLocalHistoryRowsInRenderer(
                viewportSlice,
                request,
                null,
                where,
                repeats,
                requestSerial,
                "inline-local-history-seed",
                true
        );
    }

    private LocalHistoryViewportSlice localHistoryViewportSliceForTouchPaint(
            List<LocalHistoryPaintRow> rows,
            LocalHistoryRequest request,
            LocalHistoryChunk chunk,
            String where,
            int repeats,
            String source,
            boolean alreadyRenderedOnly
    ) {
        // WHY: APK-SCROLLBACK-FINGER-ANCHOR-BOTTOM-LAG-20260709-2226 showed the
        // same action/request painting two coordinate systems: first the merged
        // canonical viewport (for example offset 410 of 814 rows), then a cached
        // chunk-local viewport (offset 1 of 406 rows). WebView `evaluateJavascript`
        // callbacks are async, so that second paint visually jumps away from the
        // finger. Cached chunks may seed or merge the canonical viewport, but once
        // canonical target-bound rows exist they must not replace the viewport owner.
        if (localHistoryTouchViewportCanOwnChunk(request, chunk)) {
            LocalHistoryViewportSlice viewportSlice = localHistoryTouchViewportSlice();
            Log.i(CONTROL_LOG_TAG,
                    "stage=local-history-owner endpoint=local-cache result=canonical-viewport-preserved"
                            + " actionId=" + safeLogToken(activeTouchScrollActionId)
                            + " tapId=" + safeLogToken(currentApkTapIdForLog())
                            + " windowId=" + safeWindowIdForControlLog(request == null ? "" : request.windowId)
                            + " source=" + inlineLocalHistorySource(source)
                            + " firstNewReadableRow=" + (!viewportSlice.alreadyRenderedOnly)
                            + " alreadyRenderedOnly=" + viewportSlice.alreadyRenderedOnly
                            + " beforeTouchScrollResponse=true"
                            + " localViewportOffset=" + Math.max(0, viewportSlice.firstRow)
                            + " localViewportRows=" + viewportSlice.rows.size()
                            + " localHistoryCachedRows=" + viewportSlice.totalRows
                            + " localHistoryChunkLines=" + LOCAL_HISTORY_CHUNK_LINES
                            + " where=" + safeLogToken(where)
                            + " repeats=" + Math.max(1, repeats));
            return viewportSlice;
        }
        if (localHistoryTouchViewportHasCanonicalRowsFor(request)) {
            Log.i(CONTROL_LOG_TAG,
                    "stage=local-history-owner endpoint=local-cache result=chunk-local-paint-suppressed"
                            + " actionId=" + safeLogToken(activeTouchScrollActionId)
                            + " tapId=" + safeLogToken(currentApkTapIdForLog())
                            + " windowId=" + safeWindowIdForControlLog(request == null ? "" : request.windowId)
                            + " reason=canonical-owner-active"
                            + " source=" + inlineLocalHistorySource(source)
                            + " chunkGenerationKey=" + safeLogToken(chunk == null || chunk.identity == null ? "" : chunk.identity.generationKey)
                            + " canonicalGenerationKey=" + safeLogToken(localHistoryTouchViewportGenerationKey)
                            + " localViewportOffset=" + localHistoryTouchViewportOffset
                            + " localHistoryCachedRows=" + localHistoryTouchViewportRows.size()
                            + " where=" + safeLogToken(where)
                            + " repeats=" + Math.max(1, repeats));
            return new LocalHistoryViewportSlice(new ArrayList<>(), localHistoryTouchViewportKey(), 0, 0, alreadyRenderedOnly);
        }
        return inlineLocalHistoryPaintRowsForTouch(
                rows,
                request,
                chunk,
                where,
                repeats,
                source,
                alreadyRenderedOnly
        );
    }

    private boolean localHistoryTouchViewportHasCanonicalRowsFor(LocalHistoryRequest request) {
        return localHistoryTouchViewportTargetsRequest(request)
                && !localHistoryTouchViewportAlreadyRenderedOnly;
    }

    private boolean localHistoryTouchViewportTargetsRequest(LocalHistoryRequest request) {
        return request != null
                && hasStableWindowId(request.windowId)
                && request.windowId.equals(localHistoryTouchViewportWindowId)
                && !localHistoryTouchViewportRows.isEmpty();
    }

    private boolean localHistoryTouchViewportCanOwnChunk(LocalHistoryRequest request, LocalHistoryChunk chunk) {
        if (!localHistoryTouchViewportTargetsRequest(request)
                || chunk == null
                || chunk.identity == null) {
            return false;
        }
        String generationKey = localHistoryViewportGenerationKey(chunk);
        return !generationKey.isEmpty()
                && generationKey.equals(localHistoryTouchViewportGenerationKey);
    }

    private LocalHistoryViewportSlice inlineLocalHistoryPaintRowsForTouch(
            List<LocalHistoryPaintRow> rows,
            LocalHistoryRequest request,
            LocalHistoryChunk chunk,
            String where,
            int repeats,
            String source,
            boolean alreadyRenderedOnly
    ) {
        List<LocalHistoryPaintRow> visibleRows = new ArrayList<>();
        if (rows == null || rows.isEmpty()) {
            return new LocalHistoryViewportSlice(visibleRows, "", 0, 0, alreadyRenderedOnly);
        }
        int maxRows = Math.max(1, Math.min(
                localHistoryTouchInlineFeedbackRows(),
                LOCAL_HISTORY_TOUCH_VIEWPORT_MAX_ROWS
        ));
        int viewportRows = Math.max(1, Math.min(rows.size(), maxRows));
        int maxOffset = Math.max(0, rows.size() - viewportRows);
        String cacheKey = localHistoryTouchViewportKey(request, chunk, source, alreadyRenderedOnly);
        if (!cacheKey.equals(localHistoryTouchViewportKey())) {
            if (shouldPreserveLocalHistoryTouchViewportTrackForAction(
                    request == null ? "" : request.windowId,
                    cacheKey,
                    source,
                    alreadyRenderedOnly,
                    0,
                    "inline-paint")) {
                LocalHistoryViewportSlice viewportSlice = localHistoryTouchViewportSlice();
                if (!viewportSlice.rows.isEmpty()) {
                    return viewportSlice;
                }
            }
            localHistoryTouchViewportRows.clear();
            localHistoryTouchViewportRows.addAll(rows);
            localHistoryTouchViewportWindowId = request == null ? "" : request.windowId;
            localHistoryTouchViewportGenerationKey = chunk == null || chunk.identity == null
                    ? ""
                    : localHistoryViewportGenerationKey(chunk);
            localHistoryTouchViewportStart = chunk == null || chunk.identity == null
                    ? ""
                    : chunk.identity.start;
            localHistoryTouchViewportActionId = currentLocalHistoryTouchViewportActionId();
            // WHY: cached rows are chronological. Anchor a new cache surface at
            // the newest/live end, then let lineUp reduce the offset into older
            // output. The inverse mapping caused the first-drag 500-row jump.
            localHistoryTouchViewportOffset = maxOffset;
            resetLocalHistoryTouchAcceptedPaintTrack();
            localHistoryTouchViewportAlreadyRenderedOnly = alreadyRenderedOnly;
        } else {
            localHistoryTouchViewportRows.clear();
            localHistoryTouchViewportRows.addAll(rows);
            localHistoryTouchViewportActionId = currentLocalHistoryTouchViewportActionId();
            localHistoryTouchViewportAlreadyRenderedOnly = alreadyRenderedOnly;
        }
        int deltaRows = Math.max(1, repeats);
        if ("lineUp".equals(where)) {
            localHistoryTouchViewportOffset = Math.max(0, localHistoryTouchViewportOffset - deltaRows);
        } else if ("lineDown".equals(where)) {
            localHistoryTouchViewportOffset = Math.min(maxOffset, localHistoryTouchViewportOffset + deltaRows);
        }
        localHistoryTouchViewportUpdatedAtMs = SystemClock.elapsedRealtime();
        syncCaptureRendererReadHold("local-history-inline-viewport-moved");
        int start = Math.max(0, Math.min(localHistoryTouchViewportOffset, maxOffset));
        int end = Math.min(rows.size(), start + viewportRows);
        for (int index = start; index < end; index++) {
            visibleRows.add(rows.get(index));
        }
        Log.i(CONTROL_LOG_TAG,
                "stage=local-history-owner endpoint=local-cache result=viewport-moved"
                        + " actionId=" + safeLogToken(activeTouchScrollActionId)
                        + " tapId=" + safeLogToken(currentApkTapIdForLog())
                        + " windowId=" + safeWindowIdForControlLog(request == null ? "" : request.windowId)
                        + " source=" + inlineLocalHistorySource(source)
                        + " firstNewReadableRow=" + (!alreadyRenderedOnly)
                        + " alreadyRenderedOnly=" + alreadyRenderedOnly
                        + " beforeTouchScrollResponse=true"
                        + " localViewportOffset=" + start
                        + " localViewportRows=" + visibleRows.size()
                        + " localHistoryCachedRows=" + rows.size()
                        + " localHistoryChunkLines=" + LOCAL_HISTORY_CHUNK_LINES
                        + " where=" + safeLogToken(where)
                        + " repeats=" + deltaRows);
        return new LocalHistoryViewportSlice(visibleRows, cacheKey, start, rows.size(), alreadyRenderedOnly);
    }

    private String localHistoryTouchViewportKey() {
        return localHistoryTouchViewportWindowId
                + "|" + localHistoryTouchViewportGenerationKey
                + "|start=" + localHistoryTouchViewportStart;
    }

    private String localHistoryTouchViewportKey(
            String windowId,
            String generationKey,
            String start
    ) {
        return (windowId == null ? "" : windowId.trim())
                + "|" + (generationKey == null ? "" : generationKey.trim())
                + "|start=" + (start == null ? "" : start.trim());
    }

    private String localHistoryTouchViewportKey(
            LocalHistoryRequest request,
            LocalHistoryChunk chunk,
            String source,
            boolean alreadyRenderedOnly
    ) {
        String windowId = request == null ? "" : request.windowId;
        if (chunk != null && chunk.identity != null) {
            return chunk.identity.windowId
                    + "|" + localHistoryViewportGenerationKey(chunk)
                    + "|start=" + chunk.identity.start;
        }
        return windowId
                + "|seed:" + inlineLocalHistorySource(source)
                + ":" + (request == null ? "" : request.visibleFrameHash)
                + "|alreadyRenderedOnly=" + alreadyRenderedOnly;
    }

    private String currentLocalHistoryTouchViewportActionId() {
        return activeTouchScrollActionId == null ? "" : activeTouchScrollActionId.trim();
    }

    private boolean shouldPreserveLocalHistoryTouchViewportTrackForAction(
            String windowId,
            String nextViewportKey,
            String source,
            boolean nextAlreadyRenderedOnly,
            long requestSerial,
            String reason
    ) {
        String actionId = currentLocalHistoryTouchViewportActionId();
        String normalizedWindowId = windowId == null ? "" : windowId.trim();
        String nextKey = nextViewportKey == null ? "" : nextViewportKey.trim();
        String currentKey = localHistoryTouchViewportKey();
        if (actionId.isEmpty()
                || !actionId.equals(localHistoryTouchViewportActionId)
                || !hasStableWindowId(normalizedWindowId)
                || !normalizedWindowId.equals(localHistoryTouchViewportWindowId)
                || localHistoryTouchViewportRows.isEmpty()
                || currentKey.isEmpty()
                || nextKey.isEmpty()
                || currentKey.equals(nextKey)) {
            return false;
        }
        // WHY: APK-SCROLLBACK-FINGER-ANCHOR-BOTTOM-LAG-20260709-2226 showed one
        // physical gesture alternating an established 814-row chunk viewport with
        // a 406-row seed/chunk-local track before backend reconciliation. A
        // finger-owned viewport may extend at boundaries, but same-action
        // alternate tracks must wait for the next gesture or backend reconcile.
        Log.i(CONTROL_LOG_TAG,
                "stage=local-history-owner endpoint=local-cache result=track-switch-suppressed"
                        + " actionId=" + safeLogToken(actionId)
                        + " tapId=" + safeLogToken(currentApkTapIdForLog())
                        + " windowId=" + safeWindowIdForControlLog(normalizedWindowId)
                        + " reason=" + safeLogToken(reason)
                        + " source=" + inlineLocalHistorySource(source)
                        + " currentViewportKey=" + safeLogToken(currentKey)
                        + " nextViewportKey=" + safeLogToken(nextKey)
                        + " currentAlreadyRenderedOnly=" + localHistoryTouchViewportAlreadyRenderedOnly
                        + " nextAlreadyRenderedOnly=" + nextAlreadyRenderedOnly
                        + " localViewportOffset=" + localHistoryTouchViewportOffset
                        + " localHistoryCachedRows=" + localHistoryTouchViewportRows.size()
                        + " request=" + requestSerial);
        return true;
    }

    private List<LocalHistoryPaintRow> localHistoryPaintRowsFromPayload(
            JSONObject payload,
            boolean requireAnsiRows
    ) throws Exception {
        List<LocalHistoryPaintRow> rows = new ArrayList<>();
        if (payload == null) {
            return rows;
        }
        JSONArray ansiRows = payload.optJSONArray("ansiRows");
        JSONArray plainRows = payload.optJSONArray("rows");
        if (requireAnsiRows && (ansiRows == null || ansiRows.length() == 0)) {
            return rows;
        }
        int count = ansiRows == null ? 0 : ansiRows.length();
        if (!requireAnsiRows && plainRows != null) {
            count = Math.max(count, plainRows.length());
        }
        for (int index = 0; index < count; index++) {
            String ansi = ansiRows == null ? "" : ansiRows.optString(index, "");
            String text = plainRows == null ? "" : plainRows.optString(index, "");
            if (text.isEmpty() && !ansi.isEmpty()) {
                text = stripAnsiForLocalHistory(ansi);
            }
            if (!requireAnsiRows || !ansi.isEmpty() || !text.isEmpty()) {
                rows.add(new LocalHistoryPaintRow(text, ansi));
            }
        }
        return rows;
    }

    private List<LocalHistoryPaintRow> plainLocalHistoryPaintRows(List<String> rows) {
        List<LocalHistoryPaintRow> paintRows = new ArrayList<>();
        if (rows == null) {
            return paintRows;
        }
        for (String row : rows) {
            paintRows.add(new LocalHistoryPaintRow(row == null ? "" : row, ""));
        }
        return paintRows;
    }

    private String stripAnsiForLocalHistory(String value) {
        if (value == null || value.isEmpty()) {
            return "";
        }
        return value.replaceAll(String.valueOf((char) 27) + "\\[[0-9;]*m", "");
    }

    private String localHistoryPaintRowsRejectReason(
            List<LocalHistoryPaintRow> rows,
            boolean requireAnsiRows
    ) {
        if (rows == null || rows.isEmpty()) {
            return requireAnsiRows ? "missing-ansiRows" : "empty-rows";
        }
        boolean hasAnsi = false;
        StringBuilder joined = new StringBuilder();
        for (LocalHistoryPaintRow row : rows) {
            if (row == null) {
                continue;
            }
            if (row.hasAnsi()) {
                hasAnsi = true;
            }
            joined.append(row.text).append('\n');
        }
        if (requireAnsiRows && !hasAnsi) {
            return "missing-ansiRows";
        }
        if (requireAnsiRows && rows.size() >= Math.max(12, localHistoryTouchInlineFeedbackRows() / 2)) {
            int meaningfulRows = meaningfulLocalHistoryPaintRowCount(rows);
            int minimumMeaningfulRows = Math.max(
                    LOCAL_HISTORY_TOUCH_MIN_MEANINGFUL_ROWS,
                    (int) Math.ceil(rows.size() * LOCAL_HISTORY_TOUCH_MIN_MEANINGFUL_ROW_RATIO)
            );
            if (meaningfulRows < minimumMeaningfulRows) {
                return "mostly-blank-ansiRows";
            }
        }
        // WHY: the installed scrollback proof showed real Codex terminal output
        // containing AGENTS/board/proof filenames. ANSI-backed `/scrollback/chunk`
        // rows are still the terminal surface; only plain fallback bodies should
        // be rejected by source/proof text markers.
        boolean ansiBackedRows = requireAnsiRows && hasAnsi;
        String lower = joined.toString().toLowerCase(Locale.US);
        if (!ansiBackedRows && (lower.contains("codex session reader")
                || lower.contains("end of readable transcript")
                || lower.contains("/read-session")
                || lower.contains("visible_transcript_body_as_normal_scroll")
                || lower.contains("target-visible-body-not-proven")
                || lower.contains("fresh-codex-shell-no-transcript-continuity")
                || lower.contains("body-continuity-unproven"))) {
            return "transcript-read-session-body";
        }
        boolean receiptPath = lower.contains("source-receipt.md")
                || lower.contains("worker-receipt.md")
                || lower.contains("hybrid-coordinator-board")
                || lower.contains("post-install hash integration");
        boolean receiptFields = lower.contains("regression_family_id:")
                || lower.contains("required_proof_tier:")
                || lower.contains("closeout fields")
                || lower.contains("old_failure_signature:");
        if (!ansiBackedRows && (receiptPath || receiptFields)) {
            return "proof-source-body";
        }
        return "";
    }

    private int meaningfulLocalHistoryPaintRowCount(List<LocalHistoryPaintRow> rows) {
        if (rows == null || rows.isEmpty()) {
            return 0;
        }
        int count = 0;
        for (LocalHistoryPaintRow row : rows) {
            if (row == null) {
                continue;
            }
            String text = row.text == null ? "" : row.text;
            if (text.trim().isEmpty() && row.ansi != null && !row.ansi.isEmpty()) {
                text = stripAnsiForLocalHistory(row.ansi);
            }
            if (!text.trim().isEmpty()) {
                count++;
            }
        }
        return count;
    }

