    private String localHistoryPaintGenerationKey(LocalHistoryChunk chunk) {
        if (!localHistoryTouchViewportRows.isEmpty()) {
            return localHistoryTouchViewportGenerationKey;
        }
        if (chunk != null && chunk.identity != null) {
            return localHistoryViewportGenerationKey(chunk);
        }
        return localHistoryTouchViewportGenerationKey;
    }

    private boolean inlineLocalHistoryRendererPainted(String result) {
        return result != null && result.contains("inline-local-history-painted");
    }

    private String inlineLocalHistorySource(String source) {
        String value = source == null ? "" : source.trim();
        if ("inline-local-history-seed".equals(value)) {
            return value;
        }
        return "inline-local-history-cache";
    }

    private LocalHistoryChunk localHistoryAdjacentPrefetchSourceChunk(
            LocalHistoryRequest request,
            LocalHistoryChunk fallback
    ) {
        if (request == null || !localHistoryTouchViewportTargetsRequest(request)) {
            return fallback;
        }
        String start = normalizeLocalHistoryStart(localHistoryTouchViewportStart);
        if (start.isEmpty()) {
            return fallback;
        }
        LocalHistoryChunk boundary = findCachedLocalHistoryChunk(request, start);
        if (boundary == null) {
            return fallback;
        }
        // WHY: after the first older `/scrollback/chunk` is prepended, asking the
        // base chunk for `prevStart` again only rediscovers the same boundary and
        // leaves the APK-local viewport capped at the old rows. Chain from the
        // current oldest cached boundary so one-finger history is warmed before the
        // finger reaches the next local edge.
        Log.i(CONTROL_LOG_TAG,
                "stage=local-history-cache endpoint=/scrollback/chunk result=prefetch-adjacent-source"
                        + " actionId=" + safeLogToken(activeTouchScrollActionId)
                        + " windowId=" + safeWindowIdForControlLog(request.windowId)
                        + " baseStart=" + safeLogToken(fallback == null || fallback.identity == null ? "" : fallback.identity.start)
                        + " sourceStart=" + safeLogToken(boundary.identity.start)
                        + " nextPrevStart=" + safeLogToken(localHistoryPreviousStartFromPayload(boundary.payload)));
        return boundary;
    }

    private synchronized int freezeCaptureRendererReadyHistoryLiveRowFrontier(
            String windowId,
            String generationKey,
            int responseLiveRowFrontier
    ) {
        String stableWindowId = windowId == null ? "" : windowId.trim();
        String stableGenerationKey =
                generationKey == null ? "" : generationKey.trim();
        if (!hasStableWindowId(stableWindowId)
                || stableGenerationKey.isEmpty()
                || responseLiveRowFrontier < 0) {
            return responseLiveRowFrontier;
        }
        boolean sameGenerationOwner =
                stableWindowId.equals(
                        captureRendererReadyHistoryFrontierWindowId)
                        && stableGenerationKey.equals(
                        captureRendererReadyHistoryFrontierGenerationKey)
                        && captureRendererReadyHistoryLiveRowFrontier >= 0;
        if (!sameGenerationOwner) {
            captureRendererReadyHistoryFrontierWindowId = stableWindowId;
            captureRendererReadyHistoryFrontierGenerationKey =
                    stableGenerationKey;
            captureRendererReadyHistoryLiveRowFrontier =
                    responseLiveRowFrontier;
        }
        // WHY: the producer generation is stable while live output appends.
        // Letting each asynchronous chunk replace liveRowFrontier shifts the
        // renderer's expectedEnd by a few rows and strands three otherwise READY
        // intervals behind a permanent 43-row seam. Freeze the immutable
        // generation boundary that staged the first interval; later responses
        // remain data for that same absolute row coordinate system.
        return captureRendererReadyHistoryLiveRowFrontier;
    }

    private synchronized void resetCaptureRendererReadyHistoryLiveRowFrontier(
            String reason
    ) {
        captureRendererReadyHistoryFrontierWindowId = "";
        captureRendererReadyHistoryFrontierGenerationKey = "";
        captureRendererReadyHistoryLiveRowFrontier = -1;
    }

    private void stageReadyLocalHistoryBatchForRenderer(
            LocalHistoryRequest request,
            LocalHistoryChunk chunk,
            String source
    ) {
        stageReadyLocalHistoryBatchForRenderer(
                request,
                chunk,
                source,
                result -> continueReadyHistoryRefillAfterStage(request, chunk, source, result)
        );
    }

    private void stageReadyLocalHistoryBatchForRenderer(
            LocalHistoryRequest request,
            LocalHistoryChunk chunk,
            String source,
            ReadyHistoryStageCallback callback
    ) {
        long expectedLeaseSerial = terminalSnapshotLease == null
                ? 0
                : terminalSnapshotLease.serial;
        prepareTerminalSnapshotOffMainThread(
                request,
                chunk,
                source,
                expectedLeaseSerial,
                callback
        );
        if (expectedLeaseSerial > 0
                && !terminalSnapshotLeaseMatchesSerial(expectedLeaseSerial)) {
            return;
        }
    }

    private void prepareTerminalSnapshotOffMainThread(
            LocalHistoryRequest request,
            LocalHistoryChunk chunk,
            String source,
            long expectedLeaseSerial,
            ReadyHistoryStageCallback callback
    ) {
        if (webView == null
                || Build.VERSION.SDK_INT < Build.VERSION_CODES.KITKAT
                || request == null
                || chunk == null
                || chunk.identity == null
                || chunk.payload == null
                || !request.windowId.equals(chunk.identity.windowId)) {
            notifyReadyHistoryStageCallback(
                    callback,
                    readyHistoryResult("REJECTED_OWNER")
            );
            return;
        }
        String generationKey = localHistoryViewportGenerationKey(chunk);
        int responseLiveRowFrontier =
                chunk.payload.optInt("liveRowFrontier", -1);
        int frozenLiveRowFrontier =
                freezeCaptureRendererReadyHistoryLiveRowFrontier(
                        request.windowId,
                        generationKey,
                        responseLiveRowFrontier
                );
        List<String> frameRows = new ArrayList<>(
                lastAcceptedCaptureRendererRows
        );
        List<LocalHistoryPaintRow> framePaintRows = new ArrayList<>(
                lastAcceptedCaptureRendererPaintRows
        );
        int frameCols = Math.max(
                20,
                chunk.payload.optInt(
                        "renderCols",
                        lastAcceptedCaptureRendererCols
                )
        );
        new Thread(() -> {
            try {
                JSONArray renderRows =
                        chunk.payload.optJSONArray("renderRows");
                int start = chunk.payload.optInt("start", -1);
                int end = chunk.payload.optInt("end", -1);
                if (renderRows == null
                        || renderRows.length() == 0
                        || start < 0
                        || end < start) {
                    uiHandler.post(() -> notifyReadyHistoryStageCallback(
                            callback,
                            readyHistoryResult("REJECTED_PAYLOAD")
                    ));
                    return;
                }
                JSONObject batch = new JSONObject();
                batch.put("state", "READY");
                batch.put("windowId", chunk.identity.windowId);
                batch.put("generationKey", generationKey);
                batch.put("start", start);
                batch.put("end", end);
                batch.put("renderCols", frameCols);
                batch.put(
                        "hasMoreBefore",
                        chunk.payload.optBoolean("hasMoreBefore", false)
                );
                if (chunk.payload.has("prevStart")
                        && !chunk.payload.isNull("prevStart")) {
                    batch.put(
                            "prevStart",
                            chunk.payload.optInt("prevStart", -1)
                    );
                }
                batch.put(
                        "prepareElapsedMs",
                        chunk.payload.optLong("clientPrepareElapsedMs", 0)
                );
                batch.put(
                        "renderRows",
                        new JSONArray(renderRows.toString())
                );
                JSONArray batchRowsHtml =
                        chunk.payload.optJSONArray(LOCAL_HISTORY_HTML_ROWS_KEY);
                if (batchRowsHtml != null && batchRowsHtml.length() > 0) {
                    batch.put(
                            "rowsHtml",
                            new JSONArray(batchRowsHtml.toString())
                    );
                }
                JSONArray batchRowKeys =
                        chunk.payload.optJSONArray("rowKeys");
                if (batchRowKeys != null && batchRowKeys.length() > 0) {
                    batch.put(
                            "rowKeys",
                            new JSONArray(batchRowKeys.toString())
                    );
                }
                if (frozenLiveRowFrontier >= 0) {
                    batch.put(
                            "liveRowFrontier",
                            frozenLiveRowFrontier
                    );
                }
                String batchJson = batch.toString();
                JSONArray readyBatches = new JSONArray();
                readyBatches.put(new JSONObject(batchJson));
                JSONObject preparedFrame = null;
                if (!frameRows.isEmpty()) {
                    preparedFrame = new JSONObject();
                    preparedFrame.put("windowId", chunk.identity.windowId);
                    preparedFrame.put("generationKey", generationKey);
                    preparedFrame.put("requestedRows", frameRows.size());
                    preparedFrame.put("requestedCols", frameCols);
                    preparedFrame.put(
                            "historySize",
                            lastAcceptedCaptureRendererHistorySize
                    );
                    preparedFrame.put(
                            "liveRowFrontier",
                            frozenLiveRowFrontier
                    );
                    JSONArray currentRows = new JSONArray();
                    JSONArray currentHtmlRows = new JSONArray();
                    JSONArray currentRowKeys = new JSONArray();
                    for (int index = 0; index < frameRows.size(); index++) {
                        currentRows.put(frameRows.get(index));
                        LocalHistoryPaintRow paintRow =
                                index < framePaintRows.size()
                                        ? framePaintRows.get(index)
                                        : null;
                        currentHtmlRows.put(
                                paintRow != null && paintRow.hasHtml()
                                        ? paintRow.html
                                        : frameRows.get(index)
                        );
                        currentRowKeys.put(
                                "snapshot:" + chunk.identity.windowId
                                        + ":" + generationKey + ":" + index
                        );
                    }
                    preparedFrame.put("rows", currentRows);
                    preparedFrame.put("rowsHtml", currentHtmlRows);
                    preparedFrame.put("rowKeys", currentRowKeys);
                }
                JSONObject immutablePreparedFrame = preparedFrame;
                uiHandler.post(() -> {
                    if (immutablePreparedFrame != null) {
                        prepareTerminalSnapshotOffMainThread(
                                immutablePreparedFrame,
                                readyBatches,
                                "history-prewarm-" + source
                        );
                    }
                    webView.evaluateJavascript(
                            "(function(){try{var r=window.__mantisCaptureRenderer;"
                                    + "if(r&&typeof r.stageReadyHistoryBatch==='function'){"
                                    + "return r.stageReadyHistoryBatch("
                                    + batchJson + ");}"
                                    + "return {status:'RENDERER_MISSING'};"
                                    + "}catch(e){return {status:'RENDERER_ERROR',error:String(e&&e.message||e)};}})()",
                            value -> {
                                JSONObject result =
                                        parseJavascriptObjectResult(value);
                                if (result == null) {
                                    result = readyHistoryResult(
                                            "UNPARSEABLE_RESULT"
                                    );
                                }
                                String status =
                                        result.optString("status", "UNKNOWN");
                                if (rendererStageClosesBlockedSeam(status)) {
                                    captureRendererHistoryMovementBlocked =
                                            false;
                                    captureRendererGestureViewportRefillRequested =
                                            false;
                                    if (!activeCaptureRendererGestureViewportOwner()
                                            && terminalSnapshotLeaseMatchesSerial(
                                            expectedLeaseSerial)
                                            && exactReadyHistoryOwnerMatchesActiveTouch(
                                            request,
                                            chunk)) {
                                        replayCaptureRendererBlockedFingerDelta(
                                                request,
                                                chunk,
                                                source
                                        );
                                    }
                                }
                                Log.i(CONTROL_LOG_TAG,
                                        "stage=local-history-ready endpoint=renderer"
                                                + " result="
                                                + safeLogToken(status)
                                                + " windowId="
                                                + safeWindowIdForControlLog(
                                                request.windowId)
                                                + " generationKey="
                                                + safeLogToken(generationKey)
                                                + " start=" + start
                                                + " end=" + end
                                                + " responseLiveRowFrontier="
                                                + responseLiveRowFrontier
                                                + " frozenLiveRowFrontier="
                                                + frozenLiveRowFrontier
                                                + " renderRows="
                                                + renderRows.length()
                                                + " renderCols=" + frameCols
                                                + " measuredCols="
                                                + result.optInt(
                                                "measuredCols",
                                                -1)
                                                + " needsReady="
                                                + result.optBoolean(
                                                "needsReady",
                                                false)
                                                + " trueTopPrepared="
                                                + result.optBoolean(
                                                "trueTopPrepared",
                                                false)
                                                + " source="
                                                + safeLogToken(source));
                                notifyReadyHistoryStageCallback(
                                        callback,
                                        result
                                );
                            }
                    );
                });
            } catch (Exception exc) {
                uiHandler.post(() -> {
                    Log.i(CONTROL_LOG_TAG,
                            "stage=local-history-ready endpoint=local-cache"
                                    + " result=rejected"
                                    + " windowId="
                                    + safeWindowIdForControlLog(
                                    request.windowId)
                                    + " source=" + safeLogToken(source)
                                    + " error=" + safeLogToken(
                                    exc.getClass().getSimpleName()));
                    notifyReadyHistoryStageCallback(
                            callback,
                            readyHistoryResult("STAGING_EXCEPTION")
                    );
                });
            }
        }, "terminal-snapshot-ready").start();
    }

    private boolean rendererStageClosesBlockedSeam(String status) {
        // WHY: a duplicate confirms only that the same batch was seen; it does
        // not prove the missing contiguous seam closed. Replaying held pixels on
        // duplicate callbacks caused v228's READY-gap replay storm.
        return "READY".equals(status);
    }

    private JSONObject parseJavascriptObjectResult(String value) {
        if (value == null || value.trim().isEmpty() || "null".equals(value.trim())) {
            return null;
        }
        try {
            Object parsed = new JSONTokener(value).nextValue();
            if (parsed instanceof JSONObject) {
                return (JSONObject) parsed;
            }
            if (parsed instanceof String) {
                return new JSONObject((String) parsed);
            }
        } catch (Exception ignored) {
            return null;
        }
        return null;
    }

    private JSONObject readyHistoryResult(String status) {
        JSONObject result = new JSONObject();
        try {
            result.put("status", status == null ? "UNKNOWN" : status);
        } catch (Exception ignored) {
        }
        return result;
    }

    private void notifyReadyHistoryStageCallback(ReadyHistoryStageCallback callback, JSONObject result) {
        if (callback != null) {
            callback.onResult(result == null ? readyHistoryResult("UNKNOWN") : result);
        }
    }

    private void continueReadyHistoryRefillAfterStage(
            LocalHistoryRequest request,
            LocalHistoryChunk chunk,
            String source,
            JSONObject result
    ) {
        if (readyHistoryStageRequestsNext(result, chunk)) {
            // WHY: each completed background stage advances exactly one producer
            // `prevStart`. The renderer explicitly needs the next older chunk here, so
            // re-arm the proactive look-ahead budget to keep ~N chunks staged ahead of
            // this new consumption point. This pump is not called by the gesture/kinetic
            // frame path.
            deepStagingLookAheadChunkCount = 0;
            prefetchAdjacentLocalHistoryChunkForTouch(
                    request,
                    chunk.payload,
                    activeHistoryScrollRequestSerial
            );
            return;
        }
        // WHY: SCROLL DEEP-HISTORY 2026-07-26 — PROACTIVE look-ahead. The renderer pulls
        // one chunk per needsReady, which underruns under a FAST fling (device:
        // READY_UNDERRUN -> blank until Bottom). While a gesture owns the surface, pre-fill
        // up to LOCAL_HISTORY_DEEP_STAGING_LOOKAHEAD_CHUNKS chunks AHEAD of needsReady so
        // staging stays ahead of momentum and a fast fling can travel ~1000 lines. Bounded
        // per catch-up cycle (reset on the needsReady pull above, on gesture start, and on
        // underrun); gated on captureRendererGestureScrollActive() so IDLE cost is
        // unchanged. Only chains from an accepted-owner stage with more history left; every
        // staged chunk clears the movement-blocked latch, so this deepens the staged buffer
        // and never changes the single capture-renderer owner.
        String lookAheadStatus = result == null ? "" : result.optString("status", "");
        boolean lookAheadAcceptedOwner = "READY".equals(lookAheadStatus)
                || "QUEUED_DUPLICATE".equals(lookAheadStatus)
                || "COMMITTED_DUPLICATE".equals(lookAheadStatus);
        if (captureRendererGestureScrollActive()
                && lookAheadAcceptedOwner
                && deepStagingLookAheadChunkCount < LOCAL_HISTORY_DEEP_STAGING_LOOKAHEAD_CHUNKS
                && chunk != null
                && chunk.payload != null
                && chunk.payload.optBoolean("hasMoreBefore", false)
                && !result.optBoolean("trueTopPrepared", false)) {
            deepStagingLookAheadChunkCount++;
            prefetchAdjacentLocalHistoryChunkForTouch(
                    request,
                    chunk.payload,
                    activeHistoryScrollRequestSerial
            );
        }
    }

    private boolean readyHistoryStageRequestsNext(JSONObject result, LocalHistoryChunk chunk) {
        if (result == null || chunk == null || chunk.payload == null) {
            return false;
        }
        String status = result.optString("status", "");
        boolean acceptedOwner = "READY".equals(status)
                || "QUEUED_DUPLICATE".equals(status)
                || "COMMITTED_DUPLICATE".equals(status);
        return acceptedOwner
                && result.optBoolean("needsReady", false)
                && !result.optBoolean("trueTopPrepared", false)
                && chunk.payload.optBoolean("hasMoreBefore", false);
    }

    private void notifyReadyHistoryRefillFailed(String reason) {
        if (webView == null || Build.VERSION.SDK_INT < Build.VERSION_CODES.KITKAT) {
            return;
        }
        webView.evaluateJavascript(
                "(function(){try{var r=window.__mantisCaptureRenderer;"
                        + "return r&&typeof r.noteReadyHistoryRefillFailure==='function'"
                        + "?r.noteReadyHistoryRefillFailure('" + safeLogToken(reason) + "')"
                        + ":{status:'RENDERER_MISSING'};}catch(e){return {status:'RENDERER_ERROR'};}})()",
                null
        );
    }

    private void prefetchAdjacentLocalHistoryChunkForTouch(
            LocalHistoryRequest request,
            JSONObject payload,
            long requestSerial
    ) {
        if (request == null || payload == null || !hasStableWindowId(request.windowId)) {
            return;
        }
        int renderCols = localHistoryRendererColsForRequest(request);
        if (renderCols < 20) {
            notifyReadyHistoryRefillFailed("renderer-cols-unavailable");
            return;
        }
        String start = localHistoryPreviousStartFromPayload(payload);
        if (start.isEmpty()) {
            return;
        }
        LocalHistoryChunk cachedBoundary = findCachedLocalHistoryChunk(request, start);
        if (cachedBoundary != null) {
            stageReadyLocalHistoryBatchForRenderer(request, cachedBoundary, "adjacent-cache-hit");
            mergeLocalHistoryTouchViewportBoundary(
                    request,
                    cachedBoundary,
                    true,
                    requestSerial,
                    "inline-local-history-cache-boundary-hit"
            );
            return;
        }
        String prefetchKey = localHistoryTouchPrefetchKey(
                request,
                firstLocalHistoryPayloadString(payload, "generationKey", "cacheKey"),
                start
        );
        if (localHistoryTouchPrefetchInFlight.containsKey(prefetchKey)) {
            return;
        }
        localHistoryTouchPrefetchInFlight.put(prefetchKey, SystemClock.elapsedRealtime());
        evictLocalHistoryTouchPrefetchIfNeeded();
        String path = "/scrollback/chunk?windowId=" + urlEncode(request.windowId)
                + "&lines=" + LOCAL_HISTORY_CHUNK_LINES
                + "&cols=" + renderCols
                + "&start=" + urlEncode(start);
        Log.i(CONTROL_LOG_TAG,
                "stage=local-history-cache endpoint=/scrollback/chunk result=prefetch-adjacent-scheduled"
                        + " actionId=" + safeLogToken(activeTouchScrollActionId)
                        + " windowId=" + safeWindowIdForControlLog(request.windowId)
                        + " start=" + safeLogToken(start)
                        + " request=" + requestSerial);
        getJson(path, adjacentPayload -> {
            Long startedAtMs = localHistoryTouchPrefetchInFlight.remove(prefetchKey);
            annotateLocalHistoryPrepareElapsed(adjacentPayload, startedAtMs);
            if (!adjacentPayload.optBoolean("ok", false)) {
                notifyReadyHistoryRefillFailed("adjacent-not-ok");
                return;
            }
            LocalHistoryChunk chunk = rememberLocalHistoryChunk(request, start, adjacentPayload);
            if (chunk == null) {
                // WHY: the renderer latched this refill before Java fetched it.
                // Identity rejection is a terminal completion, so explicitly
                // release that latch instead of waiting forever for a stage.
                notifyReadyHistoryRefillFailed("adjacent-identity-mismatch");
                return;
            }
            stageReadyLocalHistoryBatchForRenderer(request, chunk, "adjacent-cache-fill");
            Log.i(CONTROL_LOG_TAG,
                    "stage=local-history-cache endpoint=/scrollback/chunk result=prefetch-adjacent-stored"
                            + " actionId=" + safeLogToken(activeTouchScrollActionId)
                            + " windowId=" + safeWindowIdForControlLog(request.windowId)
                            + " start=" + safeLogToken(start)
                            + " generationKey=" + safeLogToken(chunk.identity.generationKey)
                            + " request=" + requestSerial);
            mergeLocalHistoryTouchViewportBoundary(
                    request,
                    chunk,
                    true,
                    requestSerial,
                    "inline-local-history-cache-boundary-fill"
            );
        }, exc -> {
            localHistoryTouchPrefetchInFlight.remove(prefetchKey);
            notifyReadyHistoryRefillFailed("adjacent-fetch-failed");
            Log.i(CONTROL_LOG_TAG,
                    "stage=local-history-cache endpoint=/scrollback/chunk result=prefetch-adjacent-failed"
                            + " actionId=" + safeLogToken(activeTouchScrollActionId)
                            + " windowId=" + safeWindowIdForControlLog(request.windowId)
                            + " start=" + safeLogToken(start)
                            + " request=" + requestSerial
                            + " error=" + safeLogToken(exc.getClass().getSimpleName()));
        });
    }

    private void mergeLocalHistoryTouchViewportBoundary(
            LocalHistoryRequest request,
            LocalHistoryChunk chunk,
            boolean prependBoundary,
            long requestSerial,
            String source
    ) {
        if (request == null || chunk == null || chunk.identity == null) {
            return;
        }
        try {
            List<LocalHistoryPaintRow> rows = localHistoryPaintRowsFromPayload(chunk.payload, true);
            String rejectReason = localHistoryPaintRowsRejectReason(rows, true);
            if (!rejectReason.isEmpty()) {
                logInlineLocalHistoryRejected(
                        request,
                        source,
                        rejectReason,
                        "lineUp",
                        1,
                        requestSerial
                );
                return;
            }
            // WHY: `/scrollback/chunk` is a cache-boundary fill, not the frame
            // owner. Merge older adjacent ANSI rows into the APK-local viewport so
            // the next finger sample can keep moving locally while `/touch-scroll`
            // and `/terminal-frame` reconcile authoritative tmux state later.
            ensureLocalHistoryTouchViewportRows(
                    request,
                    chunk,
                    rows,
                    true,
                    prependBoundary,
                    false,
                    source,
                    requestSerial
            );
            clearLocalHistoryTouchTopEdgeHold(request, "boundary-extended", requestSerial);
            if (shouldDeferLocalHistoryAsyncPaintDuringActiveTouch(source)) {
                return;
            }
            paintLocalHistoryTouchViewport(
                    request,
                    chunk,
                    prependBoundary ? "lineUp" : "lineDown",
                    1,
                    requestSerial,
                    source,
                    false
            );
        } catch (Exception exc) {
            Log.i(CONTROL_LOG_TAG,
                    "stage=local-history-viewport endpoint=/scrollback/chunk result=boundary-parse-failed"
                            + " actionId=" + safeLogToken(activeTouchScrollActionId)
                            + " windowId=" + safeWindowIdForControlLog(request.windowId)
                            + " start=" + safeLogToken(chunk.identity.start)
                            + " source=" + safeLogToken(source)
                            + " request=" + requestSerial
                            + " error=" + safeLogToken(exc.getClass().getSimpleName()));
        }
    }

    private String localHistoryTouchPrefetchKey(LocalHistoryRequest request, String start) {
        return localHistoryTouchPrefetchKey(request, "", start);
    }

    private String localHistoryTouchPrefetchKey(
            LocalHistoryRequest request,
            String generationKey,
            String start
    ) {
        if (request == null) {
            return "";
        }
        int renderCols = localHistoryRendererColsForRequest(request);
        // WHY: accepted-frame hashes change on ordinary repaint and cannot own
        // refill single-flight. Bind it to producer generation/cursor/width so
        // the same request stays single-flight while different generations split.
        String stableGenerationKey = generationKey == null ? "" : generationKey.trim();
        return request.windowId
                + "|generation=" + stableGenerationKey
                + "|start=" + normalizeLocalHistoryStart(start)
                + "|cols=" + renderCols;
    }

    private void annotateLocalHistoryPrepareElapsed(JSONObject payload, Long startedAtMs) {
        if (payload == null || startedAtMs == null || startedAtMs <= 0) {
            return;
        }
        try {
            payload.put(
                    "clientPrepareElapsedMs",
                    Math.max(1, SystemClock.elapsedRealtime() - startedAtMs)
            );
        } catch (Exception ignored) {
        }
    }

    private void evictLocalHistoryTouchPrefetchIfNeeded() {
        while (localHistoryTouchPrefetchInFlight.size() > LOCAL_HISTORY_CACHE_MAX_ENTRIES) {
            String oldestKey = localHistoryTouchPrefetchInFlight.keySet().iterator().next();
            localHistoryTouchPrefetchInFlight.remove(oldestKey);
        }
    }

    private LocalHistoryChunk findCachedLocalHistoryChunk(LocalHistoryRequest request, String start) {
        String normalizedStart = normalizeLocalHistoryStart(start);
        int expectedRenderCols = localHistoryRendererColsForRequest(request);
        long now = SystemClock.elapsedRealtime();
        LocalHistoryChunk best = null;
        boolean frameHashFallback = false;
        List<String> expiredKeys = new ArrayList<>();
        List<String> staleBaseKeys = new ArrayList<>();
        for (Map.Entry<String, LocalHistoryChunk> entry : localHistoryChunkCache.entrySet()) {
            LocalHistoryChunk chunk = entry.getValue();
            if (chunk == null || chunk.identity == null) {
                expiredKeys.add(entry.getKey());
                continue;
            }
            if (now - chunk.fetchedAtMs > LOCAL_HISTORY_CACHE_MAX_AGE_MS) {
                expiredKeys.add(entry.getKey());
                continue;
            }
            LocalHistoryChunkIdentity identity = chunk.identity;
            if (!identity.requestedWindowId.equals(request.windowId)
                    || !identity.windowId.equals(request.windowId)
                    || !identity.start.equals(normalizedStart)
                    || identity.lines != LOCAL_HISTORY_CHUNK_LINES
                    || expectedRenderCols < 20
                    || chunk.payload.optInt("renderCols", -1) != expectedRenderCols) {
                continue;
            }
            boolean exactVisibleFrame = !request.visibleFrameHash.isEmpty()
                    && request.visibleFrameHash.equals(identity.visibleFrameHash);
            if (normalizedStart.isEmpty()
                    && !exactVisibleFrame
                    && !localHistoryBaseChunkAnchorsAcceptedTail(request, chunk)) {
                staleBaseKeys.add(entry.getKey());
                continue;
            }
            if (!request.visibleFrameHash.isEmpty()
                    && !request.visibleFrameHash.equals(identity.visibleFrameHash)) {
                boolean sameLocalHistoryGeneration = sameLocalHistoryGeneration(request, identity);
                if (!sameLocalHistoryGeneration) {
                    continue;
                }
                frameHashFallback = true;
            }
            best = chunk;
            break;
        }
        for (String key : expiredKeys) {
            localHistoryChunkCache.remove(key);
        }
        for (String key : staleBaseKeys) {
            invalidateStaleLocalHistoryBaseChunk(key, request);
        }
        if (best != null) {
            String cacheHitResult = frameHashFallback
                    ? "stage=local-history-cache endpoint=/scrollback/chunk result=hit-framehash-fallback"
                    : "stage=local-history-cache endpoint=/scrollback/chunk result=hit";
            Log.i(CONTROL_LOG_TAG,
                    cacheHitResult
                            + " windowId=" + safeWindowIdForControlLog(best.identity.windowId)
                            + " generationKey=" + safeLogToken(best.identity.generationKey)
                            + " frameHash=" + safeLogToken(best.identity.visibleFrameHash)
                            + (frameHashFallback ? " frameHashFallback=true" : " frameHashFallback=false"));
        }
        return best;
    }

    private void invalidateStaleLocalHistoryBaseChunk(String cacheKey, LocalHistoryRequest request) {
        if (cacheKey == null || cacheKey.isEmpty()) {
            return;
        }
        // WHY: the pane generation is stable while history grows. Leaving a base
        // whose absolute end trails the accepted frame tail in the cache made every
        // MOVE rediscover/log `base-tail-stale` without creating a READY prepend.
        // Evict once; the existing in-flight key coalesces the replacement fetch.
        LocalHistoryChunk removed = localHistoryChunkCache.remove(cacheKey);
        if (removed != null) {
            Log.i(CONTROL_LOG_TAG,
                    "stage=local-history-cache endpoint=/scrollback/chunk result=base-tail-invalidated"
                            + " windowId=" + safeWindowIdForControlLog(request == null ? "" : request.windowId)
                            + " generationKey=" + safeLogToken(removed.identity == null ? "" : removed.identity.generationKey));
        }
    }

    private boolean localHistoryBaseChunkAnchorsAcceptedTail(
            LocalHistoryRequest request,
            LocalHistoryChunk chunk
    ) {
        if (request == null
                || chunk == null
                || chunk.identity == null
                || chunk.payload == null
                || !request.windowId.equals(chunk.identity.windowId)) {
            return false;
        }
        int chunkEnd = chunk.payload.optInt("end", -1);
        int acceptedHistorySize = lastAcceptedCaptureRendererHistorySize;
        boolean acceptedTarget = request.windowId.equals(lastAcceptedCaptureRendererFrameWindowId)
                || request.windowId.equals(confirmedCaptureRendererFrameWindowTargetKey);
        boolean anchored = acceptedTarget
                && chunkEnd >= 0
                && acceptedHistorySize >= 0
                && chunkEnd >= acceptedHistorySize;
        if (!anchored) {
            // WHY: a pane generation remains stable while terminal rows append.
            // Generation-only fallback accepted base `end=3957` against live
            // `historySize=4539`, so the first MOVE looked random. Boundary chunks
            // may extend an established viewport, but a base chunk may replace live
            // pixels only when its tail overlaps the accepted live tail.
            Log.i(CONTROL_LOG_TAG,
                    "stage=local-history-cache endpoint=/scrollback/chunk result=base-tail-stale"
                            + " actionId=" + safeLogToken(activeTouchScrollActionId)
                            + " windowId=" + safeWindowIdForControlLog(request.windowId)
                            + " chunkEnd=" + chunkEnd
                            + " acceptedHistorySize=" + acceptedHistorySize
                            + " acceptedTarget=" + acceptedTarget
                            + " generationKey=" + safeLogToken(chunk.identity.generationKey));
        }
        return anchored;
    }

    private boolean sameLocalHistoryGeneration(
            LocalHistoryRequest request,
            LocalHistoryChunkIdentity identity
    ) {
        if (request == null || identity == null || !identity.requestedWindowId.equals(request.windowId)) {
            return false;
        }
        if (!identity.windowId.equals(request.windowId)) {
            return false;
        }
        if (!identity.generationKey.isEmpty()) {
            return true;
        }
        return !identity.paneId.isEmpty() && !identity.generation.isEmpty();
    }

    private LocalHistoryChunk rememberLocalHistoryChunk(
            LocalHistoryRequest request,
            String start,
            JSONObject payload
    ) {
        LocalHistoryChunkIdentity identity = localHistoryIdentityForPayload(request, start, payload);
        if (identity == null) {
            return null;
        }
        JSONObject stored = localHistoryPayloadForStorage(payload, identity);
        LocalHistoryChunk chunk = new LocalHistoryChunk(identity, stored, SystemClock.elapsedRealtime());
        localHistoryChunkCache.put(identity.cacheKey(), chunk);
        evictLocalHistoryCacheIfNeeded();
        Log.i(CONTROL_LOG_TAG,
                "stage=local-history-cache endpoint=/scrollback/chunk result=stored"
                        + " windowId=" + safeWindowIdForControlLog(identity.windowId)
                        + " paneId=" + safeLogToken(identity.paneId)
                        + " generationKey=" + safeLogToken(identity.generationKey)
                        + " sessionId=" + safeLogToken(identity.sessionId)
                        + " threadId=" + safeLogToken(identity.threadId)
                        + " frameHash=" + safeLogToken(identity.visibleFrameHash));
        return chunk;
    }

    private LocalHistoryChunkIdentity localHistoryIdentityForPayload(
            LocalHistoryRequest request,
            String start,
            JSONObject payload
    ) {
        if (request == null || payload == null || !hasStableWindowId(request.windowId)) {
            return null;
        }
        String requestedWindowId = request.windowId;
        String payloadWindowId = stableWindowIdFromPayload(
                payload,
                requestedWindowId,
                "windowId",
                "requestedWindowId",
                "displayWindowId",
                "selectedWindowId"
        );
        if (!payloadWindowId.equals(request.windowId)) {
            Log.i(CONTROL_LOG_TAG,
                    "stage=local-history-cache endpoint=/scrollback/chunk result=rejected-window"
                            + " requestedWindowId=" + safeWindowIdForControlLog(requestedWindowId)
                            + " windowId=" + safeWindowIdForControlLog(payloadWindowId));
            return null;
        }
        String paneId = firstLocalHistoryPayloadString(payload, "paneId", "pane", "ptyId");
        String panePid = firstLocalHistoryPayloadString(payload, "panePid", "pid");
        String generation = firstLocalHistoryPayloadString(payload, "generation", "historyGeneration");
        String generationKey = firstLocalHistoryPayloadString(payload, "generationKey", "cacheKey");
        String sessionId = firstLocalHistoryPayloadString(
                payload,
                "sessionId",
                "targetSessionId",
                "conversationId"
        );
        if (sessionId.isEmpty()) {
            sessionId = request.sessionId;
        }
        String threadId = firstLocalHistoryPayloadString(
                payload,
                "threadId",
                "targetThreadId",
                "conversationThreadId"
        );
        if (threadId.isEmpty()) {
            threadId = request.threadId;
        }
        String visibleFrameHash = request.visibleFrameHash;
        if (visibleFrameHash.isEmpty()) {
            visibleFrameHash = firstLocalHistoryPayloadString(payload, "visibleFrameHash", "frameHash", "hash");
        }
        if (generationKey.isEmpty() && (paneId.isEmpty() || generation.isEmpty())) {
            Log.i(CONTROL_LOG_TAG,
                    "stage=local-history-cache endpoint=/scrollback/chunk result=rejected-weak-identity"
                            + " requestedWindowId=" + safeWindowIdForControlLog(requestedWindowId)
                            + " paneId=" + safeLogToken(paneId)
                            + " generation=" + safeLogToken(generation)
                            + " generationKey=" + safeLogToken(generationKey));
            return null;
        }
        return new LocalHistoryChunkIdentity(
                requestedWindowId,
                payloadWindowId,
                paneId,
                panePid,
                generation,
                generationKey,
                sessionId,
                threadId,
                visibleFrameHash,
                normalizeLocalHistoryStart(start),
                LOCAL_HISTORY_CHUNK_LINES
        );
    }

    private String firstLocalHistoryPayloadString(JSONObject payload, String... keys) {
        if (payload == null || keys == null) {
            return "";
        }
        for (String key : keys) {
            if (key == null || key.trim().isEmpty() || !payload.has(key)) {
                continue;
            }
            String value = payload.optString(key, "").trim();
            if (!value.isEmpty()) {
                return value;
            }
        }
        return "";
    }

    private String normalizeLocalHistoryStart(String start) {
        return start == null ? "" : start.trim();
    }

    private JSONObject localHistoryPayloadForStorage(
            JSONObject payload,
            LocalHistoryChunkIdentity identity
    ) {
        JSONObject stored;
        try {
            stored = new JSONObject(payload == null ? "{}" : payload.toString());
        } catch (Exception ignored) {
            stored = payload == null ? new JSONObject() : payload;
        }
        try {
            stored.put("requestedWindowId", identity.requestedWindowId);
            stored.put("visibleFrameHash", identity.visibleFrameHash);
            stored.put("localCacheIdentity", identity.cacheKey());
        } catch (Exception ignored) {
        }
        return stored;
    }

    private JSONObject localHistoryPayloadForDisplay(LocalHistoryChunk chunk, boolean cacheHit) {
        JSONObject payload;
        try {
            payload = new JSONObject(chunk.payload == null ? "{}" : chunk.payload.toString());
        } catch (Exception ignored) {
            payload = chunk.payload == null ? new JSONObject() : chunk.payload;
        }
        try {
            payload.put("localCacheHit", cacheHit);
            payload.put("requestedWindowId", chunk.identity.requestedWindowId);
            payload.put("visibleFrameHash", chunk.identity.visibleFrameHash);
            payload.put("localCacheIdentity", chunk.identity.cacheKey());
        } catch (Exception ignored) {
        }
        return payload;
    }

    private void evictLocalHistoryCacheIfNeeded() {
        while (localHistoryChunkCache.size() > LOCAL_HISTORY_CACHE_MAX_ENTRIES) {
            String oldestKey = localHistoryChunkCache.keySet().iterator().next();
            localHistoryChunkCache.remove(oldestKey);
        }
    }

    private void showLocalHistoryDialog(LocalHistoryRequest request, JSONObject payload) throws Exception {
        // WHY: C5 local history is intentionally a read-only local history
        // viewer. It consumes the C4 `/scrollback/chunk` cache contract
        // (`windowId:paneId:generation`) and the newer stronger cache key, and
        // keys rows by requested/returned window, pane, pid, generation, optional
        // session/thread ids, and the last accepted visible body hash. It must
        // not select tmux windows, enter copy-mode, send keys, reload WebView,
        // focus xterm, or touch the live Bottom/Send/composer owners that keep
        // current output and queued prompts realtime.
        List<String> rows = rowsFromPayload(payload);

        LinearLayout container = new LinearLayout(this);
        container.setOrientation(LinearLayout.VERTICAL);
        container.setPadding(dp(12), dp(8), dp(12), dp(4));
        container.setBackgroundColor(Color.rgb(8, 8, 10));

        TextView statusText = new TextView(this);
        statusText.setTextColor(Color.rgb(205, 214, 244));
        statusText.setTextSize(12);
        statusText.setPadding(0, 0, 0, dp(6));

        EditText search = new EditText(this);
        search.setSingleLine(true);
        search.setHint("Search cached history");
        search.setContentDescription("Search cached history");
        search.setInputType(InputType.TYPE_CLASS_TEXT);
        search.setTextColor(Color.rgb(245, 245, 245));
        search.setHintTextColor(Color.rgb(127, 132, 156));
        search.setTextSize(14);

        TextView historyText = new TextView(this);
        historyText.setTextColor(Color.rgb(225, 225, 225));
        historyText.setBackgroundColor(Color.BLACK);
        historyText.setTypeface(Typeface.MONOSPACE);
        historyText.setTextSize(11);
        historyText.setTextIsSelectable(true);
        historyText.setPadding(dp(8), dp(8), dp(8), dp(8));

        ScrollView scrollView = new ScrollView(this);
        scrollView.setFillViewport(false);
        scrollView.addView(historyText, new ScrollView.LayoutParams(
                ScrollView.LayoutParams.MATCH_PARENT,
                ScrollView.LayoutParams.WRAP_CONTENT
        ));

        container.addView(statusText, new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT,
                ViewGroup.LayoutParams.WRAP_CONTENT
        ));
        container.addView(search, new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT,
                ViewGroup.LayoutParams.WRAP_CONTENT
        ));
        LinearLayout.LayoutParams scrollParams = new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT,
                dp(420)
        );
        scrollParams.setMargins(0, dp(8), 0, 0);
        container.addView(scrollView, scrollParams);

        updateLocalHistoryText(historyText, statusText, rows, "", payload);
        search.addTextChangedListener(new TextWatcher() {
            @Override
            public void beforeTextChanged(CharSequence text, int start, int count, int after) {
            }

            @Override
            public void onTextChanged(CharSequence text, int start, int before, int count) {
                updateLocalHistoryText(historyText, statusText, rows, text.toString(), payload);
                scrollView.post(() -> scrollView.scrollTo(0, 0));
            }

            @Override
            public void afterTextChanged(Editable text) {
            }
        });

        AlertDialog dialog = new AlertDialog.Builder(this)
                .setTitle("Local history")
                .setView(container)
                .setPositiveButton("Older", null)
                .setNeutralButton("Latest", null)
                .setNegativeButton("Close", null)
                .create();
        dialog.setOnShowListener(shown -> {
            Button olderButton = dialog.getButton(AlertDialog.BUTTON_POSITIVE);
            Button latestButton = dialog.getButton(AlertDialog.BUTTON_NEUTRAL);
            Object prevStart = payload.opt("prevStart");
            boolean hasOlder = prevStart != null && prevStart != JSONObject.NULL;
            olderButton.setEnabled(hasOlder);
            olderButton.setOnClickListener(view -> {
                if (!hasOlder) {
                    toast("No older cached rows");
                    return;
                }
                dialog.dismiss();
                fetchLocalHistoryChunk(request, String.valueOf(prevStart));
            });
            latestButton.setOnClickListener(view -> {
                dialog.dismiss();
                fetchLocalHistoryChunk(request, "");
            });
            Window window = dialog.getWindow();
            if (window != null) {
                window.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN);
            }
        });
        dialog.show();
    }

    private List<String> rowsFromPayload(JSONObject payload) throws Exception {
        List<String> rows = new ArrayList<>();
        JSONArray array = payload.optJSONArray("rows");
        if (array == null) {
            return rows;
        }
        for (int index = 0; index < array.length(); index++) {
            rows.add(array.optString(index, ""));
        }
        return rows;
    }

    private void updateLocalHistoryText(
            TextView historyText,
            TextView statusText,
            List<String> rows,
            String query,
            JSONObject payload
    ) {
        String rendered = renderLocalHistoryRows(rows, query);
        historyText.setText(rendered);
        String cleanQuery = query == null ? "" : query.trim();
        int matchCount = cleanQuery.isEmpty() ? rows.size() : countLocalHistoryMatches(rows, cleanQuery);
        String start = payload.optString("start", "?");
        String end = payload.optString("end", "?");
        String generationKey = payload.optString("generationKey", "windowId:paneId:generation");
        String localCacheIdentity = payload.optString("localCacheIdentity", generationKey);
        String cacheSource = payload.optBoolean("localCacheHit", false) ? "local" : "remote";
        statusText.setText(titleForLocalHistory(payload)
                + "\nCached rows: " + rows.size()
                + (cleanQuery.isEmpty() ? "" : " - Matches: " + matchCount)
                + " - Range: " + start + "-" + end
                + "\nCache key: " + localCacheIdentity
                + "\nCache source: " + cacheSource);
    }

    private String titleForLocalHistory(JSONObject payload) {
        String windowId = payload.optString("windowId", "");
        String paneId = payload.optString("paneId", "");
        return "Read-only local history"
                + (windowId.isEmpty() ? "" : " - " + windowId)
                + (paneId.isEmpty() ? "" : " " + paneId);
    }

    private int countLocalHistoryMatches(List<String> rows, String query) {
        String needle = query.toLowerCase();
        int count = 0;
        for (String row : rows) {
            if (row.toLowerCase().contains(needle)) {
                count++;
            }
        }
        return count;
    }

    private String renderLocalHistoryRows(List<String> rows, String query) {
        String cleanQuery = query == null ? "" : query.trim();
        if (cleanQuery.isEmpty()) {
            return trimLocalHistoryText(joinRows(rows));
        }
        String needle = cleanQuery.toLowerCase();
        List<String> matches = new ArrayList<>();
        for (String row : rows) {
            if (row.toLowerCase().contains(needle)) {
                matches.add(row);
            }
        }
        if (matches.isEmpty()) {
            return "No cached history matches: " + cleanQuery;
        }
        return trimLocalHistoryText(joinRows(matches));
    }

    private String joinRows(List<String> rows) {
        if (rows.isEmpty()) {
            return "No cached history rows available.";
        }
        StringBuilder builder = new StringBuilder();
        for (String row : rows) {
            builder.append(row).append('\n');
        }
        return builder.toString();
    }

    private String trimLocalHistoryText(String text) {
        if (text.length() <= LOCAL_HISTORY_MAX_DISPLAY_CHARS) {
            return text;
        }
        int omitted = text.length() - LOCAL_HISTORY_MAX_DISPLAY_CHARS;
        return text.substring(text.length() - LOCAL_HISTORY_MAX_DISPLAY_CHARS)
                + "\n\n[trimmed " + omitted + " older characters from this Android view]";
    }

