    private void showKeyControls() {
        hideDockedPromptComposerForNavigation("key-controls");
        // WHY: CLI option pickers can expose any number of choices, so fixed
        // one/two/three shortcuts are the wrong phone model. This dialog stays
        // open while the user taps Move up/down, Backspace, Delete, Home, or End,
        // making arbitrary Claude/Codex option lists usable without reopening a
        // one-shot list for every arrow key. Select/Escape/Done are the deliberate
        // close points.
        LinearLayout grid = new LinearLayout(this);
        grid.setOrientation(LinearLayout.VERTICAL);
        grid.setPadding(dp(14), dp(10), dp(14), dp(8));
        AlertDialog dialog = new AlertDialog.Builder(this)
                .setTitle("Option keys")
                .setView(grid)
                .setNegativeButton("Done", null)
                .create();
        // WHY: this must remain a custom persistent grid, not a one-shot
        // setItems list. CLI prompts often need several navigation/edit keys in
        // a row, and reopening the Copy/Paste menu after every Up/Down/Home/End
        // tap is the regression that made phone option pickers unusable.
        addKeyControlRow(grid, new String[]{"Move up", "Move down", "Select"}, new String[]{"Up", "Down", "Enter"}, dialog);
        addKeyControlRow(grid, new String[]{"Backspace", "Delete", "Tab"}, new String[]{"Backspace", "Delete", "Tab"}, dialog);
        addKeyControlRow(grid, new String[]{"Home", "End", "Escape"}, new String[]{"Home", "End", "Escape"}, dialog);
        dialog.show();
    }

    private void addKeyControlRow(LinearLayout grid, String[] labels, String[] keys, AlertDialog dialog) {
        LinearLayout row = new LinearLayout(this);
        row.setOrientation(LinearLayout.HORIZONTAL);
        row.setPadding(0, dp(3), 0, dp(3));
        for (int i = 0; i < labels.length; i++) {
            final String label = labels[i];
            final String key = keys[i];
            Button button = toolbarButton(label, v -> {
                // WHY: the real APK proof showed Delete could be lost when a
                // Backspace toast/focus transition was still settling. Persistent
                // Option Keys already give visible feedback by staying open, so
                // do not show per-key toasts for Backspace/Delete/Home/End/Tab/
                // Up/Down. Keep only Select's closing confirmation.
                enqueueOptionTerminalKey(key, "Enter".equals(key) ? "Selected" : "");
                if ("Enter".equals(key) || "Escape".equals(key)) {
                    dialog.dismiss();
                }
            });
            LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(
                    0,
                    dp(52),
                    1
            );
            params.setMargins(dp(3), 0, dp(3), 0);
            row.addView(button, params);
        }
        grid.addView(row, new LinearLayout.LayoutParams(
                LinearLayout.LayoutParams.MATCH_PARENT,
                LinearLayout.LayoutParams.WRAP_CONTENT
        ));
    }

    private List<String> readSentPromptHistory() {
        ArrayList<String> history = new ArrayList<>();
        if (prefs == null) {
            return history;
        }
        String encoded;
        try {
            encoded = prefs.getString(PREF_PROMPT_SENT_HISTORY, "");
        } catch (RuntimeException malformedPreference) {
            // WHY: a wrong-typed pref blob must never crash a read; fail to empty.
            return history;
        }
        if (encoded == null || encoded.trim().isEmpty()) {
            return history;
        }
        try {
            Object parsed = new JSONTokener(encoded).nextValue();
            if (!(parsed instanceof JSONArray)) {
                // WHY: malformed blob (not a JSON array) resets to empty history.
                return new ArrayList<>();
            }
            JSONArray array = (JSONArray) parsed;
            for (int i = 0; i < array.length() && history.size() < PROMPT_SENT_HISTORY_MAX; i++) {
                String item = array.optString(i, "");
                if (item == null || item.trim().isEmpty()) {
                    continue;
                }
                history.add(item);
            }
        } catch (Exception malformedBlob) {
            // WHY: any parse failure resets to empty rather than surfacing a crash.
            return new ArrayList<>();
        }
        return history;
    }

    private void rememberSentPromptHistory(String text) {
        if (prefs == null || text == null || text.trim().isEmpty()) {
            return;
        }
        // WHY: FEATURE mirror the submit-ledger JSON persistence: read-modify-write
        // a JSON array of strings. Skip empty, dedupe the newest (consecutive)
        // entry, move any earlier identical entry to the front (newest-first), and
        // cap at PROMPT_SENT_HISTORY_MAX. Store the exact submitted text so a
        // resend repopulates the composer byte-for-byte.
        List<String> history = readSentPromptHistory();
        if (!history.isEmpty() && history.get(0).equals(text)) {
            return;
        }
        history.remove(text);
        history.add(0, text);
        while (history.size() > PROMPT_SENT_HISTORY_MAX) {
            history.remove(history.size() - 1);
        }
        JSONArray array = new JSONArray();
        for (String item : history) {
            array.put(item);
        }
        try {
            prefs.edit().putString(PREF_PROMPT_SENT_HISTORY, array.toString()).apply();
        } catch (RuntimeException persistFailure) {
            // WHY: a successful send must never be undone by a history-write
            // failure; this ring is a convenience, not delivery state.
            Log.e(SEND_LOG_TAG,
                    "stage=sent-history result=persist-failed",
                    persistFailure);
        }
    }

    private void showSentHistoryPicker() {
        hideDockedPromptComposerForNavigation("sent-history");
        List<String> history = readSentPromptHistory();
        if (history.isEmpty()) {
            toast("No sent messages yet");
            return;
        }
        // WHY: FEATURE mirror showKeyControls' custom setView, not setItems, so
        // each recalled prompt renders as a small multi-line, ellipsized row that
        // long prompts cannot blow up into a full-screen list item.
        LinearLayout list = new LinearLayout(this);
        list.setOrientation(LinearLayout.VERTICAL);
        list.setPadding(dp(14), dp(10), dp(14), dp(8));
        ScrollView scroll = new ScrollView(this);
        scroll.addView(list, new LinearLayout.LayoutParams(
                LinearLayout.LayoutParams.MATCH_PARENT,
                LinearLayout.LayoutParams.WRAP_CONTENT
        ));
        AlertDialog dialog = new AlertDialog.Builder(this)
                .setTitle("Recent sent messages")
                .setView(scroll)
                .setNegativeButton("Done", null)
                .create();
        for (String msg : history) {
            addSentHistoryRow(list, msg, dialog);
        }
        dialog.show();
    }

    private void addSentHistoryRow(LinearLayout list, String msg, AlertDialog dialog) {
        TextView row = new TextView(this);
        row.setText(msg);
        row.setTextSize(12);
        row.setMaxLines(2);
        row.setEllipsize(TextUtils.TruncateAt.END);
        row.setTextColor(Color.rgb(205, 214, 244));
        row.setPadding(dp(10), dp(10), dp(10), dp(10));
        setTouchableBackground(row, Color.rgb(30, 30, 46), Color.rgb(137, 180, 250));
        row.setOnClickListener(v -> {
            flashTap(v);
            // WHY: resend POPULATES the composer for review; it never auto-sends.
            populateComposerForResend(msg);
            dialog.dismiss();
        });
        LinearLayout.LayoutParams rowParams = new LinearLayout.LayoutParams(
                LinearLayout.LayoutParams.MATCH_PARENT,
                LinearLayout.LayoutParams.WRAP_CONTENT
        );
        rowParams.setMargins(0, dp(3), 0, dp(3));
        list.addView(row, rowParams);
    }

    private void populateComposerForResend(String msg) {
        if (msg == null || msg.isEmpty()) {
            return;
        }
        if (promptComposerBar == null || promptComposerInput == null) {
            focusTerminalInputSoon(false);
            return;
        }
        // WHY: FEATURE mirrors stageUploadedMediaPathForSend exactly. A recalled
        // prompt must land in the same native composer that Send submits, staged
        // as the current draft so the user can review/edit and then tap Send. It
        // must NOT auto-send and must NOT touch the single /submit-text delivery
        // path. The programmatic setText is fenced so the composer's
        // afterTextChanged watcher does not treat this recall as live user typing.
        showDockedPromptComposer("resend-history");
        promptComposerProgrammaticTextChange = true;
        try {
            promptComposerInput.setText(msg);
            promptComposerInput.setSelection(promptComposerInput.getText().length());
        } finally {
            promptComposerProgrammaticTextChange = false;
        }
        promptComposerDraftTargetKey = promptComposerTargetKey();
        rememberPromptComposerDraft(promptComposerDraftTargetKey, msg);
        promptComposerDraftLocalGeneration++;
        updateStartButtonLabel();
        restoreDockedPromptComposerFocus("resend-history");
    }

    private void enqueueOptionTerminalKey(String key, String message) {
        // WHY: Option Keys are quick repeated taps from the phone. The real APK
        // proof showed Backspace could reach tmux while the Android HTTP
        // callback was still settling, then the next Delete tap was lost. Keep
        // these control keys ordered on the UI thread so Backspace/Delete/Home/
        // End/Up/Down/Enter arrive at tmux in the same sequence the user tapped.
        optionKeyDispatchQueue.add(new OptionKeyDispatch(key, message, optionKeyTargetKey()));
        drainOptionTerminalKeyQueue();
    }

    private String optionKeyTargetKey() {
        // WHY: selectedPhoneWindowId is also the protected Close target, so it
        // can intentionally outlive a later active-window refresh. Option Keys
        // are live input for the window the phone is currently controlling; if
        // they prefer the stale close target, Backspace/Delete can look tapped
        // while landing in an older tab. Prefer the current phone window and only
        // fall back to selected row memory when active state is unavailable.
        if (hasStableWindowId(currentPhoneWindowId)) {
            return currentPhoneWindowId.trim();
        }
        if (hasStableWindowId(selectedPhoneWindowId)) {
            return selectedPhoneWindowId.trim();
        }
        return "unknown:" + terminalModeGeneration;
    }

    private void drainOptionTerminalKeyQueue() {
        if (optionKeyDispatchInFlight) {
            return;
        }
        OptionKeyDispatch dispatch = optionKeyDispatchQueue.poll();
        if (dispatch == null) {
            return;
        }
        optionKeyDispatchInFlight = true;
        sendTerminalKey(dispatch.key, dispatch.message, dispatch.targetKey, () -> {
            optionKeyDispatchInFlight = false;
            drainOptionTerminalKeyQueue();
        });
    }

    private void sendTerminalKey(String key, String message) {
        sendTerminalKey(key, message, null);
    }

    private void sendTerminalKey(String key, String message, Runnable after) {
        sendTerminalKey(key, message, promptComposerTargetKey(), after);
    }

    private void sendTerminalKey(String key, String message, String targetKey, Runnable after) {
        // WHY: Claude/Codex option pickers need arrow/select keys that are not
        // text composition. Route them through tmux `send-keys` after a Bottom-like
        // live restore, without focusing the hidden xterm textarea or asking the
        // Android IME to reconnect to the native composer.
        long generation = leaveReadModeForLiveInput(false);
        getJson(appendStableWindowQuery("/send-key?key=" + urlEncode(key), targetKey), payload -> {
            try {
                if (generation != terminalModeGeneration) {
                    return;
                }
                if (!payload.optBoolean("ok", false)) {
                    toast(payload.optString("error", "Key failed"));
                    return;
                }
                if (message != null && !message.isEmpty()) {
                    toast(message);
                }
                pinTerminalViewportLocal();
                fitTerminalToCurrentViewSoon("send-key");
                keepToolbarOnlyXtermSettleAliveAfterControlAction("send-key");
                alignLiveBottomViewportForPassiveEntrySoon("send-key");
            } finally {
                if (after != null) {
                    after.run();
                }
            }
        }, exc -> {
            try {
                toast("Mantis Control is not reachable");
            } finally {
                if (after != null) {
                    after.run();
                }
            }
        });
    }

    private boolean nativeComposerVisibleTextEmpty() {
        return isDockedPromptComposerVisible()
                && promptComposerInput != null
                && promptComposerInput.getText().toString().isEmpty();
    }

    private void sendEmptyComposerBackspaceToTerminal() {
        // WHY: the real-phone failure can leave tmux/Codex containing draft text
        // that arrived through xterm's hidden textarea while the visible native
        // composer is empty. In that state Android Backspace has nothing local to
        // delete, so the user is stuck with prompt text they cannot remove. Route
        // empty-composer Backspace to tmux BSpace; once v2.07's top-tap and IME
        // ownership fixes prevent new hidden-xterm drafts, this remains a safe
        // recovery for inherited stale prompt text.
        sendTerminalKey("Backspace", "");
    }

    private void sendEmptyComposerDeleteToTerminal() {
        // WHY: Backspace was already guarded, but hardware/Gboard forward-delete
        // can arrive as KEYCODE_FORWARD_DEL or deleteSurroundingText afterLength.
        // When the visible native composer is empty, route that explicit recovery
        // key to tmux instead of making the user unable to delete stale text that
        // already reached the pane.
        sendTerminalKey("Delete", "");
    }

    private void pasteClipboardIntoTerminal() {
        ClipboardManager clipboardManager =
                (ClipboardManager) getSystemService(Context.CLIPBOARD_SERVICE);
        if (clipboardManager == null || !clipboardManager.hasPrimaryClip()) {
            toast("Phone clipboard is empty");
            return;
        }
        ClipData clip = clipboardManager.getPrimaryClip();
        if (clip == null || clip.getItemCount() == 0) {
            toast("Phone clipboard is empty");
            return;
        }
        String clipboardText = clipboardTextFromClip(clip);
        if (clipboardText.isEmpty()) {
            toast("Phone clipboard is empty");
            return;
        }
        // WHY: pasting is a live-input action. Clear local read-mode flags before
        // the server forces tmux/Codex to live bottom, or delayed read-mode focus
        // guards can hide the keyboard immediately after the paste.
        long generation = leaveReadModeForLiveInput();
        postText(appendStableWindowQuery("/paste"), clipboardText, payload -> {
            if (generation != terminalModeGeneration) {
                return;
            }
            if (!payload.optBoolean("ok", false)) {
                toast(payload.optString("error", "Paste failed"));
                return;
            }
            settleLiveBottomAfterPaste("clipboard-paste");
            hideDockedPromptComposer(false, true);
            focusTerminalInputSoon(false);
        }, exc -> toast("Mantis Control is not reachable"));
    }

    private void settleLiveBottomAfterPaste(String reason) {
        long generation = terminalModeGeneration;
        // WHY: upload/clipboard paste success is visible as text in the terminal.
        // A normal success Toast covers the exact bottom prompt/attachment path the
        // phone workflow needs to inspect, so paste success must settle the live
        // viewer quietly while keeping error Toasts for real failures.
        uiHandler.postDelayed(() -> {
            if (generation != terminalModeGeneration || readModeSuppressesKeyboard || terminalHistoryViewportActive) {
                return;
            }
            getJsonWithRetry(appendStableWindowQuery("/live-bottom"), payload -> {
                if (generation != terminalModeGeneration) {
                    return;
                }
                pinTerminalViewportLocal();
                fitTerminalToCurrentViewSoon(reason);
                keepToolbarOnlyXtermSettleAliveAfterControlAction(reason);
                scrollViewerToTypingPositionOnce(reason, 180);
                scheduleToolbarStatusDotRefresh(150);
            }, exc -> toast("Mantis Control is not reachable"));
        }, 180);
    }

    private String clipboardTextFromClip(ClipData clip) {
        StringBuilder builder = new StringBuilder();
        for (int index = 0; index < clip.getItemCount(); index++) {
            ClipData.Item item = clip.getItemAt(index);
            if (item == null) {
                continue;
            }
            // WHY: Android clipboards may carry multiple items, and some apps expose
            // raw text while others expose URI-backed or styled text. Reading only
            // item 0 made phone paste look like it dropped everything after the first
            // selected fragment. Prefer raw text when present, then use Android's
            // documented coercion path for the rest, preserving spaces/newlines and
            // joining multi-item clips with newlines before the tmux paste-buffer hop.
            CharSequence itemText = item.getText();
            if (itemText == null) {
                itemText = item.coerceToText(this);
            }
            if (itemText == null || itemText.length() == 0) {
                continue;
            }
            if (builder.length() > 0) {
                builder.append('\n');
            }
            builder.append(itemText);
        }
        return builder.toString();
    }

    private void copyVisibleTerminalToClipboard() {
        getJson("/copy-visible", payload -> {
            if (!payload.optBoolean("ok", false)) {
                toast(payload.optString("error", "Copy failed"));
                return;
            }
            String text = payload.optString("text", "");
            if (text.isEmpty()) {
                toast("Nothing visible to copy");
                return;
            }
            ClipboardManager clipboardManager =
                    (ClipboardManager) getSystemService(Context.CLIPBOARD_SERVICE);
            if (clipboardManager == null) {
                toast("Phone clipboard is not available");
                return;
            }
            clipboardManager.setPrimaryClip(
                    ClipData.newPlainText("WEzterm visible terminal", text)
            );
            Log.i(TERMINAL_COPY_LOG_TAG, "visible-copy-success chars=" + text.length());
            toast("Copied visible terminal");
        });
    }

    private void showSelectableTerminalTextSheet() {
        getJson("/copy-visible", payload -> {
            if (!payload.optBoolean("ok", false)) {
                toast(payload.optString("error", "Copy failed"));
                return;
            }
            String text = payload.optString("text", "");
            if (text.isEmpty()) {
                toast("Nothing visible to copy");
                return;
            }
            ScrollView scrollView = new ScrollView(this);
            LinearLayout content = new LinearLayout(this);
            content.setOrientation(LinearLayout.VERTICAL);
            content.setPadding(dp(8), dp(6), dp(8), dp(6));
            scrollView.addView(content);
            final AlertDialog[] dialogRef = new AlertDialog[1];

            LinearLayout actions = new LinearLayout(this);
            actions.setOrientation(LinearLayout.HORIZONTAL);
            actions.setPadding(0, 0, 0, dp(10));
            actions.addView(activeDialogActionButton("Close", v -> {
                if (dialogRef[0] != null) {
                    dialogRef[0].dismiss();
                }
            }));
            content.addView(actions);

            TextView terminalText = new TextView(this);
            terminalText.setText(text);
            terminalText.setTextIsSelectable(true);
            terminalText.setFocusable(true);
            terminalText.setFocusableInTouchMode(true);
            terminalText.setContentDescription("Selectable terminal text");
            terminalText.setTextSize(13);
            terminalText.setTypeface(Typeface.MONOSPACE);
            terminalText.setTextColor(Color.rgb(244, 246, 252));
            terminalText.setPadding(dp(12), dp(10), dp(12), dp(10));
            terminalText.setHorizontallyScrolling(false);
            terminalText.setSingleLine(false);
            setTouchableBackground(terminalText, Color.rgb(32, 35, 48), Color.rgb(137, 180, 250));
            content.addView(terminalText, new LinearLayout.LayoutParams(
                    LinearLayout.LayoutParams.MATCH_PARENT,
                    LinearLayout.LayoutParams.WRAP_CONTENT
            ));

            dialogRef[0] = new AlertDialog.Builder(this)
                    .setView(premiumDialogShell("Terminal text", "", scrollView))
                    .show();
            // WHY: the sheet opens while the user's finger may still be down on
            // the terminal. A release outside the new dialog must not dismiss the
            // selectable text and fall through like a normal terminal tap.
            dialogRef[0].setCanceledOnTouchOutside(false);
            stylePremiumDialogWindow(dialogRef[0]);
            Log.i(TERMINAL_COPY_LOG_TAG, "selectable-terminal-text chars=" + text.length());
            terminalText.postDelayed(() -> {
                terminalText.requestFocus();
                terminalText.performLongClick();
            }, 250);
        });
    }

    private void pickMediaForUpload() {
        // WHY: screenshots/media should move from the phone to the desktop over
        // the same Tailscale control channel as Copy/Paste. Android's Photo
        // Picker returns user-selected URIs without broad storage access. The
        // multi-upload flow needs images, videos, and generic files in one picker,
        // so ACTION_OPEN_DOCUMENT is primary and Photo Picker remains the
        // media-only fallback when DocumentsUI cannot handle the request.
        // WHY: launching Android's document picker pauses/resumes the Activity.
        // Treat the return as a native-dialog transition, not a terminal failure,
        // so the blank watchdog and passive page lifecycle probes cannot reload
        // or scroll the WebView while the user is trying to attach media.
        pendingUploadPickerComposerState = captureUploadPickerComposerState();
        nativePickerQuietUntilMs = System.currentTimeMillis() + 8000;
        if (!launchUploadPicker(uploadDocumentPickerIntent(), "document-picker")) {
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU
                    && launchUploadPicker(uploadPhotoPickerIntent(), "photo-picker")) {
                return;
            }
            nativePickerQuietUntilMs = 0;
            pendingUploadPickerComposerState = null;
            toast("No Android file picker available");
        }
    }

    private UploadPickerComposerState captureUploadPickerComposerState() {
        String targetWindowId = promptComposerDraftSubmitTargetKey();
        if (!hasStableWindowId(targetWindowId)) {
            targetWindowId = uploadAssociationWindowId();
        }
        String draftText = promptComposerInput == null
                ? ""
                : promptComposerInput.getText().toString();
        int selectionStart = promptComposerInput == null
                ? 0
                : promptComposerInput.getSelectionStart();
        int selectionEnd = promptComposerInput == null
                ? 0
                : promptComposerInput.getSelectionEnd();
        return new UploadPickerComposerState(
                targetWindowId,
                draftText,
                selectionStart,
                selectionEnd,
                isDockedPromptComposerVisible()
        );
    }

    private void restoreUploadPickerComposerState(
            UploadPickerComposerState pickerState,
            String reason
    ) {
        if (pickerState == null
                || promptComposerInput == null
                || !hasStableWindowId(pickerState.targetWindowId)) {
            return;
        }
        String currentTarget = promptComposerTargetKey();
        if (!pickerState.targetWindowId.equals(currentTarget)) {
            long draftRevision = rememberPromptComposerDraft(
                    pickerState.targetWindowId,
                    pickerState.draftText
            );
            rememberPromptComposerDraftSelection(
                    pickerState.targetWindowId,
                    draftRevision,
                    pickerState.selectionStart,
                    pickerState.selectionEnd,
                    pickerState.draftText.length()
            );
            Log.i(UPLOAD_LOG_TAG, "picker-state-restored result=target-local"
                    + " reason=" + safeLogToken(reason)
                    + " targetWindow=" + pickerState.targetWindowId);
            return;
        }
        if (pickerState.composerVisible && !isDockedPromptComposerVisible()) {
            showDockedPromptComposer("picker-result");
        }
        Editable editable = promptComposerInput.getText();
        int selectionStart = PromptComposerImeStatePolicy.clampSelection(
                pickerState.selectionStart,
                pickerState.draftText.length()
        );
        int selectionEnd = PromptComposerImeStatePolicy.clampSelection(
                pickerState.selectionEnd,
                pickerState.draftText.length()
        );
        promptComposerProgrammaticTextChange = true;
        promptComposerInput.beginBatchEdit();
        try {
            if (!TextUtils.equals(editable.toString(), pickerState.draftText)) {
                editable.replace(0, editable.length(), pickerState.draftText);
            }
            Selection.setSelection(editable, selectionStart, selectionEnd);
        } finally {
            promptComposerInput.endBatchEdit();
            promptComposerProgrammaticTextChange = false;
        }
        promptComposerDraftTargetKey = pickerState.targetWindowId;
        long draftRevision = rememberPromptComposerDraft(
                pickerState.targetWindowId,
                pickerState.draftText
        );
        rememberPromptComposerDraftSelection(
                pickerState.targetWindowId,
                draftRevision,
                pickerState.selectionStart,
                pickerState.selectionEnd,
                pickerState.draftText.length()
        );
        promptComposerDraftLocalGeneration++;
        updateStartButtonLabel();
        keepPromptComposerSelectionVisibleAfterLayout("picker-result");
        if (pickerState.composerVisible) {
            restoreDockedPromptComposerFocus("picker-result");
        }
        Log.i(UPLOAD_LOG_TAG, "picker-state-restored result=visible"
                + " reason=" + safeLogToken(reason)
                + " targetWindow=" + pickerState.targetWindowId
                + " selectionStart=" + selectionStart
                + " selectionEnd=" + selectionEnd);
    }

    private boolean launchUploadPicker(Intent intent, String pickerKind) {
        pendingUploadPickerKind = pickerKind == null ? "" : pickerKind;
        try {
            startActivityForResult(intent, REQUEST_UPLOAD_MEDIA);
            Log.i(UPLOAD_LOG_TAG, "picker-launch kind=" + pendingUploadPickerKind
                    + " action=" + intent.getAction());
            return true;
        } catch (Exception exc) {
            Log.w(UPLOAD_LOG_TAG, "picker-launch-failed kind=" + pendingUploadPickerKind
                    + " error=" + exc.getClass().getSimpleName());
            pendingUploadPickerKind = "";
            return false;
        }
    }

    private Intent uploadDocumentPickerIntent() {
        Intent intent = new Intent(Intent.ACTION_OPEN_DOCUMENT);
        intent.addCategory(Intent.CATEGORY_OPENABLE);
        intent.setType("*/*");
        intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);
        intent.addFlags(Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);
        intent.putExtra(Intent.EXTRA_ALLOW_MULTIPLE, true);
        intent.putExtra(Intent.EXTRA_MIME_TYPES, new String[]{
                "image/*",
                "video/*",
                "application/pdf",
                "text/*",
                "application/octet-stream"
        });
        return intent;
    }

    private Intent uploadPhotoPickerIntent() {
        Intent photoPicker = new Intent(MediaStore.ACTION_PICK_IMAGES);
        photoPicker.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            int maxItems = Math.min(MAX_UPLOAD_PICKER_ITEMS, MediaStore.getPickImagesMaxLimit());
            if (maxItems > 1) {
                photoPicker.putExtra(MediaStore.EXTRA_PICK_IMAGES_MAX, maxItems);
            }
        }
        return photoPicker;
    }

    private void handleIncomingMediaShare(Intent intent) {
        if (intent == null) {
            return;
        }
        String action = intent.getAction();
        if (Intent.ACTION_SEND.equals(action)) {
            List<Uri> uris = uploadUrisFromShareIntent(intent);
            for (Uri uri : uris) {
                prepareReadAccessForUpload(intent, uri);
            }
            uploadMediaUrisSequentially(uris, true, null);
        } else if (Intent.ACTION_SEND_MULTIPLE.equals(action)) {
            List<Uri> uris = uploadUrisFromShareIntent(intent);
            for (Uri uri : uris) {
                prepareReadAccessForUpload(intent, uri);
            }
            uploadMediaUrisSequentially(uris, true, null);
        }
    }

    private List<Uri> uploadUrisFromResult(Intent data) {
        List<Uri> uris = new ArrayList<>();
        if (data == null) {
            return uris;
        }
        addUploadUriIfMissing(uris, data.getData());
        ClipData clipData = data.getClipData();
        if (clipData != null) {
            for (int index = 0; index < clipData.getItemCount(); index++) {
                ClipData.Item item = clipData.getItemAt(index);
                if (item != null) {
                    addUploadUriIfMissing(uris, item.getUri());
                }
            }
        }
        return uris;
    }

    private List<Uri> uploadUrisFromShareIntent(Intent intent) {
        List<Uri> uris = new ArrayList<>();
        if (intent == null) {
            return uris;
        }
        Uri single = intent.getParcelableExtra(Intent.EXTRA_STREAM);
        addUploadUriIfMissing(uris, single);
        ArrayList<Uri> extraUris = intent.getParcelableArrayListExtra(Intent.EXTRA_STREAM);
        if (extraUris != null) {
            for (Uri uri : extraUris) {
                addUploadUriIfMissing(uris, uri);
            }
        }
        ClipData clipData = intent.getClipData();
        if (clipData != null) {
            for (int index = 0; index < clipData.getItemCount(); index++) {
                ClipData.Item item = clipData.getItemAt(index);
                if (item != null) {
                    addUploadUriIfMissing(uris, item.getUri());
                }
            }
        }
        Log.i(UPLOAD_LOG_TAG, "share-uris count=" + uris.size()
                + " action=" + intent.getAction());
        return uris;
    }

    private void addUploadUriIfMissing(List<Uri> uris, Uri uri) {
        if (uri == null) {
            return;
        }
        String value = uri.toString();
        for (Uri existing : uris) {
            if (existing != null && existing.toString().equals(value)) {
                return;
            }
        }
        uris.add(uri);
    }

    private void prepareReadAccessForUpload(Intent data, Uri uri) {
        if (data == null || uri == null) {
            return;
        }
        int takeFlags = data.getFlags() & Intent.FLAG_GRANT_READ_URI_PERMISSION;
        if (takeFlags == 0) {
            return;
        }
        try {
            getContentResolver().takePersistableUriPermission(uri, takeFlags);
            Log.i(UPLOAD_LOG_TAG, "uri-read-persisted scheme=" + uri.getScheme()
                    + " authority=" + uri.getAuthority());
        } catch (Exception exc) {
            // Photo Picker grants transient read access and does not always allow
            // persistable permissions. The upload happens immediately, so this is
            // diagnostic only; do not block a valid one-tap media selection.
            Log.i(UPLOAD_LOG_TAG, "uri-read-transient scheme=" + uri.getScheme()
                    + " authority=" + uri.getAuthority()
                    + " reason=" + exc.getClass().getSimpleName());
        }
    }

    private void uploadMediaUri(Uri uri, boolean fromShare) {
        List<Uri> uris = new ArrayList<>();
        addUploadUriIfMissing(uris, uri);
        uploadMediaUrisSequentially(uris, fromShare, null);
    }

    private void uploadMediaUrisSequentially(
            List<Uri> uris,
            boolean fromShare,
            UploadPickerComposerState pickerState
    ) {
        if (uris == null || uris.isEmpty()) {
            return;
        }
        // WHY: a multi-select picker can return several files at once, but each
        // returned desktop path must be appended to the same native composer in a
        // stable order. Uploading one selected URI per HTTP thread races composer
        // staging and can make the last-finished file look like the only upload.
        final List<Uri> uploadUris = new ArrayList<>(uris);
        final String uploadTargetWindowId = pickerState != null
                && hasStableWindowId(pickerState.targetWindowId)
                ? pickerState.targetWindowId
                : uploadAssociationWindowId();
        Log.i(UPLOAD_LOG_TAG, "upload-batch-start source=" + (fromShare ? "share" : "picker")
                + " count=" + uploadUris.size()
                + " targetWindow=" + uploadTargetWindowId);
        new Thread(() -> {
            int successCount = 0;
            for (Uri uri : uploadUris) {
                try {
                    JSONObject payload = performMediaUploadWithRetry(
                            uri,
                            fromShare,
                            uploadTargetWindowId
                    );
                    successCount++;
                    uiHandler.post(() -> showUploadedMediaResult(
                            payload,
                            uploadTargetWindowId,
                            pickerState
                    ));
                } catch (Exception exc) {
                    Log.e(UPLOAD_LOG_TAG, "upload-failed source=" + (fromShare ? "share" : "picker")
                            + " scheme=" + (uri == null ? "" : uri.getScheme())
                            + " authority=" + (uri == null ? "" : uri.getAuthority())
                            + " error=" + exc.getClass().getSimpleName(), exc);
                    wakeLaptopForTerminal("upload-unreachable");
                    scheduleTerminalWakeRetry("upload-unreachable");
                    uiHandler.post(() -> toast("Media upload failed: " + exc.getMessage()));
                }
            }
            Log.i(UPLOAD_LOG_TAG, "upload-batch-complete source=" + (fromShare ? "share" : "picker")
                    + " count=" + uploadUris.size()
                    + " success=" + successCount
                    + " targetWindow=" + uploadTargetWindowId);
        }).start();
    }

    private JSONObject performMediaUploadWithRetry(
            Uri uri,
            boolean fromShare,
            String uploadTargetWindowId
    ) throws Exception {
        IOException lastFailure = null;
        for (int attempt = 1; attempt <= MEDIA_UPLOAD_MAX_ATTEMPTS; attempt++) {
            try {
                return performMediaUploadAttempt(
                        uri,
                        fromShare,
                        uploadTargetWindowId,
                        attempt
                );
            } catch (IOException exc) {
                lastFailure = exc;
                if (!MediaUploadRetryPolicy.shouldRetry(attempt, exc)) {
                    throw exc;
                }
                // WHY: the v226 two-file picker old-red completed and staged item
                // one, then Android's pooled HTTP/1 socket returned an unexpected
                // EOF before item two's response headers. Retry ownership belongs
                // inside this URI only: replaying the batch would duplicate the
                // already-successful first item, while staging remains outside this
                // loop and therefore occurs exactly once after one resolved payload.
                Log.w(UPLOAD_LOG_TAG, "upload-retry source="
                        + (fromShare ? "share" : "picker")
                        + " completedAttempt=" + attempt
                        + " nextAttempt=" + (attempt + 1)
                        + " error=" + exc.getClass().getSimpleName());
            }
        }
        throw lastFailure == null
                ? new IOException("Media upload failed before a response")
                : lastFailure;
    }

    private JSONObject performMediaUploadAttempt(
            Uri uri,
            boolean fromShare,
            String uploadTargetWindowId,
            int attempt
    ) throws Exception {
        String displayName = queryMediaDisplayName(uri);
        String contentType = getContentResolver().getType(uri);
        if (contentType == null || contentType.trim().isEmpty()) {
            contentType = "application/octet-stream";
        }
        long declaredSize = queryMediaSize(uri);
        if (declaredSize > MAX_MEDIA_UPLOAD_BYTES) {
            throw new IllegalArgumentException("Media is too large for phone upload: " + humanBytes(declaredSize));
        }
        String finalContentType = contentType;
        Log.i(UPLOAD_LOG_TAG, "upload-start source=" + (fromShare ? "share" : "picker")
                + " scheme=" + uri.getScheme()
                + " authority=" + uri.getAuthority()
                + " mime=" + finalContentType
                + " declaredSize=" + declaredSize
                + " attempt=" + attempt
                + " targetWindow=" + uploadTargetWindowId);
        HttpURLConnection connection = null;
        try {
            URL url = new URL(controlUrlForPath("/upload-media?filename=" + urlEncode(displayName)));
            connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("POST");
            connection.setDoOutput(true);
            connection.setConnectTimeout(10000);
            connection.setReadTimeout(10 * 60 * 1000);
            applyControlRequestHeaders(connection);
            connection.setRequestProperty("Content-Type", finalContentType);
            connection.setRequestProperty("X-WEzTerm-Filename", displayName);
            // WHY: Android's platform HttpURLConnection is backed by an OkHttp
            // connection pool. The desktop control server closes HTTP/1 upload
            // responses, and v226 proved the next streamed POST can otherwise
            // inherit that stale socket and EOF before response headers. A
            // per-request close keeps large streaming intact without globally
            // disabling pooling for latency-sensitive control reads.
            connection.setRequestProperty("Connection", "close");
            if (declaredSize >= 0) {
                // WHY: Android's HttpURLConnection docs warn that POST bodies are
                // buffered in memory unless a streaming mode is selected. For
                // videos, fixed-length streaming is the fastest safe path when
                // OpenableColumns.SIZE is available because it sends the selected
                // URI straight to the desktop without building a giant byte[].
                connection.setFixedLengthStreamingMode(declaredSize);
            } else {
                // WHY: some content providers do not expose a size. Chunked
                // streaming keeps the upload video-safe instead of falling back
                // to HttpURLConnection's full-body memory buffer.
                connection.setChunkedStreamingMode(MEDIA_UPLOAD_STREAM_CHUNK_BYTES);
            }
            long uploadedBytes;
            try (OutputStream outputStream = connection.getOutputStream()) {
                uploadedBytes = streamUriToOutput(uri, outputStream);
            }
            if (uploadedBytes <= 0) {
                throw new IllegalArgumentException("Selected media is empty");
            }
            int code = connection.getResponseCode();
            InputStream stream = code >= 200 && code < 400
                    ? connection.getInputStream()
                    : connection.getErrorStream();
            String body;
            try (InputStream responseStream = stream) {
                body = readAll(responseStream);
            }
            Log.i(UPLOAD_LOG_TAG, "upload-response code=" + code
                    + " bytes=" + uploadedBytes
                    + " attempt=" + attempt
                    + " bodyChars=" + (body == null ? 0 : body.length()));
            return new JSONObject(body);
        } finally {
            if (connection != null) {
                connection.disconnect();
            }
        }
    }

    private long streamUriToOutput(Uri uri, OutputStream outputStream) throws Exception {
        InputStream inputStream = getContentResolver().openInputStream(uri);
        if (inputStream == null) {
            throw new IllegalArgumentException("Cannot open selected media");
        }
        try (InputStream input = inputStream) {
            byte[] buffer = new byte[MEDIA_UPLOAD_STREAM_CHUNK_BYTES];
            int read;
            long total = 0;
            while ((read = input.read(buffer)) != -1) {
                total += read;
                if (total > MAX_MEDIA_UPLOAD_BYTES) {
                    throw new IllegalArgumentException("Media is too large for phone upload");
                }
                outputStream.write(buffer, 0, read);
            }
            outputStream.flush();
            return total;
        }
    }

    private String queryMediaDisplayName(Uri uri) {
        String name = queryOpenableColumn(uri, OpenableColumns.DISPLAY_NAME);
        if (name == null || name.trim().isEmpty()) {
            String lastSegment = uri.getLastPathSegment();
            name = lastSegment == null || lastSegment.trim().isEmpty()
                    ? "phone-media"
                    : lastSegment;
        }
        return name;
    }

    private long queryMediaSize(Uri uri) {
        String value = queryOpenableColumn(uri, OpenableColumns.SIZE);
        if (value == null || value.trim().isEmpty()) {
            return -1;
        }
        try {
            return Long.parseLong(value);
        } catch (NumberFormatException ignored) {
            return -1;
        }
    }

    private String queryOpenableColumn(Uri uri, String column) {
        Cursor cursor = null;
        try {
            cursor = getContentResolver().query(uri, new String[]{column}, null, null, null);
            if (cursor != null && cursor.moveToFirst()) {
                int index = cursor.getColumnIndex(column);
                if (index >= 0 && !cursor.isNull(index)) {
                    return cursor.getString(index);
                }
            }
        } catch (Exception ignored) {
            return null;
        } finally {
            if (cursor != null) {
                cursor.close();
            }
        }
        return null;
    }

    private void showUploadedMediaResult(
            JSONObject payload,
            String targetWindowId,
            UploadPickerComposerState pickerState
    ) {
        if (!payload.optBoolean("ok", false)) {
            Log.w(UPLOAD_LOG_TAG, "upload-result-error error=" + payload.optString("error", ""));
            toast(payload.optString("error", "Media upload failed"));
            return;
        }
        String path = payload.optString("path", "");
        if (path.isEmpty()) {
            Log.w(UPLOAD_LOG_TAG, "upload-result-missing-path");
            toast("Media uploaded, but no path returned");
            return;
        }
        ClipboardManager clipboardManager =
                (ClipboardManager) getSystemService(Context.CLIPBOARD_SERVICE);
        if (clipboardManager != null) {
            clipboardManager.setPrimaryClip(ClipData.newPlainText("WEzterm uploaded media path", path));
        }
        String filename = payload.optString("filename", "uploaded media");
        long bytes = payload.optLong("bytes", 0);
        UploadAssociation upload = rememberUploadedMediaResult(targetWindowId, path, filename, bytes);
        if (upload == null) {
            upload = new UploadAssociation("", path, filename, bytes, System.currentTimeMillis());
        }
        Log.i(UPLOAD_LOG_TAG, "upload-result-ok bytes=" + bytes
                + " filename=" + filename
                + " targetWindow=" + targetWindowId);
        showUploadedMediaInline(upload, pickerState);
    }

    private void showUploadedMediaInline(
            UploadAssociation upload,
            UploadPickerComposerState pickerState
    ) {
        // WHY: the v2.57 upload "success" dialog was still a foreground modal over
        // the exact post-upload typing area. Keep normal upload completion silent
        // and reuse the protected title strip/clipboard/composer path instead;
        // real upload errors still use Toasts so failures remain visible.
        copyUploadPathToClipboard(upload);
        updateSessionTitleStrip(visibleBodyTitleBinding);
        if (pickerState == null) {
            stageUploadedMediaPathForSend(upload);
        } else {
            stageUploadedMediaPathForSend(upload, pickerState);
        }
        settleLiveBottomAfterPaste("upload-result");
    }

    private void stageUploadedMediaPathForSend(
            UploadAssociation upload,
            UploadPickerComposerState pickerState
    ) {
        if (upload == null
                || upload.path == null
                || upload.path.trim().isEmpty()
                || pickerState == null
                || !hasStableWindowId(pickerState.targetWindowId)) {
            return;
        }
        String uploadPath = upload.path.trim();
        String baseText = pickerState.stagedText;
        int selectionStart = pickerState.nextSelectionStart;
        int selectionEnd = pickerState.nextSelectionEnd;
        boolean targetStillVisible =
                pickerState.targetWindowId.equals(promptComposerTargetKey());
        if (targetStillVisible
                && promptComposerInput != null
                && !TextUtils.equals(promptComposerInput.getText().toString(), baseText)) {
            // WHY: an upload can finish after the user resumes typing. Rebase the
            // insertion to the live range instead of overwriting newer draft bytes.
            baseText = promptComposerInput.getText().toString();
            selectionStart = promptComposerInput.getSelectionStart();
            selectionEnd = promptComposerInput.getSelectionEnd();
        }
        PromptComposerPickerEdit edit = PromptComposerPickerEdit.apply(
                baseText,
                selectionStart,
                selectionEnd,
                uploadPath
        );
        pickerState.advance(edit);
        if (!targetStillVisible || promptComposerInput == null || promptComposerBar == null) {
            long draftRevision = rememberPromptComposerDraft(
                    pickerState.targetWindowId,
                    edit.text
            );
            rememberPromptComposerDraftSelection(
                    pickerState.targetWindowId,
                    draftRevision,
                    edit.cursor,
                    edit.cursor,
                    edit.text.length()
            );
            Log.i(UPLOAD_LOG_TAG, "upload-staged-for-send result=target-local"
                    + " pathChars=" + uploadPath.length()
                    + " targetWindow=" + pickerState.targetWindowId);
            return;
        }
        showDockedPromptComposer("upload-result");
        Editable editable = promptComposerInput.getText();
        promptComposerProgrammaticTextChange = true;
        promptComposerInput.beginBatchEdit();
        try {
            editable.replace(0, editable.length(), edit.text);
            Selection.setSelection(editable, edit.cursor, edit.cursor);
        } finally {
            promptComposerInput.endBatchEdit();
            promptComposerProgrammaticTextChange = false;
        }
        promptComposerDraftTargetKey = pickerState.targetWindowId;
        long draftRevision = rememberPromptComposerDraft(
                promptComposerDraftTargetKey,
                edit.text
        );
        rememberPromptComposerDraftSelection(
                promptComposerDraftTargetKey,
                draftRevision,
                edit.cursor,
                edit.cursor,
                edit.text.length()
        );
        promptComposerDraftLocalGeneration++;
        updateStartButtonLabel();
        keepPromptComposerSelectionVisibleAfterLayout("upload-result");
        restoreDockedPromptComposerFocus("upload-result");
        Log.i(UPLOAD_LOG_TAG, "upload-staged-for-send result=picker-range"
                + " pathChars=" + uploadPath.length()
                + " targetWindow=" + promptComposerDraftTargetKey
                + " cursor=" + edit.cursor);
    }

    private void stageUploadedMediaPathForSend(UploadAssociation upload) {
        if (upload == null || upload.path == null || upload.path.trim().isEmpty()) {
            return;
        }
        if (promptComposerBar == null || promptComposerInput == null) {
            focusTerminalInputSoon(false);
            return;
        }
        String uploadPath = upload.path.trim();
        showDockedPromptComposer("upload-result");
        String existingText = promptComposerInput.getText().toString();
        String nextText;
        if (existingText.trim().isEmpty()) {
            nextText = uploadPath;
        } else if (existingText.contains(uploadPath)) {
            nextText = existingText;
        } else {
            nextText = existingText + (existingText.endsWith("\n") ? "" : "\n") + uploadPath;
        }
        // WHY: choosing a phone image is the user's attach step. The returned
        // desktop path must be visible in the same native composer that Send
        // submits, not only hidden in the title strip or clipboard.
        promptComposerProgrammaticTextChange = true;
        try {
            promptComposerInput.setText(nextText);
            promptComposerInput.setSelection(promptComposerInput.getText().length());
        } finally {
            promptComposerProgrammaticTextChange = false;
        }
        promptComposerDraftTargetKey = hasStableWindowId(upload.windowId)
                ? upload.windowId.trim()
                : promptComposerTargetKey();
        rememberPromptComposerDraft(promptComposerDraftTargetKey, nextText);
        promptComposerDraftLocalGeneration++;
        updateStartButtonLabel();
        restoreDockedPromptComposerFocus("upload-result");
        Log.i(UPLOAD_LOG_TAG, "upload-staged-for-send pathChars=" + uploadPath.length()
                + " targetWindow=" + promptComposerDraftTargetKey);
    }

    private UploadAssociation rememberUploadedMediaResult(String targetWindowId, String path, String filename, long bytes) {
        String stableWindowId = targetWindowId;
        if (!hasStableWindowId(stableWindowId)) {
            stableWindowId = uploadAssociationWindowId();
        }
        if (!hasStableWindowId(stableWindowId) || prefs == null || path == null || path.trim().isEmpty()) {
            return null;
        }
        UploadAssociation upload = new UploadAssociation(
                stableWindowId.trim(),
                path.trim(),
                filename,
                bytes,
                System.currentTimeMillis()
        );
        // WHY: the server upload endpoint only returns a transient result payload.
        // Persist the last upload by immutable tmux `@windowId` so refresh, Active
        // navigation, app return, or an in-flight upload completion cannot make the
        // attachment/path look randomly detached from the session that owns it.
        prefs.edit()
                .putString(uploadPrefsKey(PREF_UPLOAD_PATH_PREFIX, upload.windowId), upload.path)
                .putString(uploadPrefsKey(PREF_UPLOAD_FILENAME_PREFIX, upload.windowId), upload.filename)
                .putLong(uploadPrefsKey(PREF_UPLOAD_BYTES_PREFIX, upload.windowId), upload.bytes)
                .putLong(uploadPrefsKey(PREF_UPLOAD_UPDATED_PREFIX, upload.windowId), upload.updatedAtMs)
                .apply();
        if (upload.windowId.equals(uploadAssociationWindowId())) {
            updateSessionTitleStrip(visibleBodyTitleBinding);
        }
        return upload;
    }

    private UploadAssociation rememberedUploadForWindow(String windowId) {
        if (!hasStableWindowId(windowId) || prefs == null) {
            return null;
        }
        String stableWindowId = windowId.trim();
        String path = prefs.getString(uploadPrefsKey(PREF_UPLOAD_PATH_PREFIX, stableWindowId), "");
        if (path == null || path.trim().isEmpty()) {
            return null;
        }
        String filename = prefs.getString(uploadPrefsKey(PREF_UPLOAD_FILENAME_PREFIX, stableWindowId), "uploaded media");
        long bytes = prefs.getLong(uploadPrefsKey(PREF_UPLOAD_BYTES_PREFIX, stableWindowId), 0);
        long updatedAtMs = prefs.getLong(uploadPrefsKey(PREF_UPLOAD_UPDATED_PREFIX, stableWindowId), 0);
        return new UploadAssociation(stableWindowId, path.trim(), filename, bytes, updatedAtMs);
    }

    private UploadAssociation currentRememberedUpload() {
        return rememberedUploadForWindow(uploadAssociationWindowId());
    }

    private String uploadPrefsKey(String prefix, String windowId) {
        return prefix + (windowId == null ? "" : windowId.trim());
    }

    private String uploadAssociationWindowId() {
        if (hasStableWindowId(currentPhoneWindowId)) {
            return currentPhoneWindowId.trim();
        }
        if (hasStableWindowId(selectedPhoneWindowId)) {
            return selectedPhoneWindowId.trim();
        }
        return "";
    }

    private void clearRememberedUploadForWindow(String windowId, String reason) {
        if (!hasStableWindowId(windowId) || prefs == null) {
            return;
        }
        String stableWindowId = windowId.trim();
        prefs.edit()
                .remove(uploadPrefsKey(PREF_UPLOAD_PATH_PREFIX, stableWindowId))
                .remove(uploadPrefsKey(PREF_UPLOAD_FILENAME_PREFIX, stableWindowId))
                .remove(uploadPrefsKey(PREF_UPLOAD_BYTES_PREFIX, stableWindowId))
                .remove(uploadPrefsKey(PREF_UPLOAD_UPDATED_PREFIX, stableWindowId))
                .apply();
    }

    private void showRememberedUploadForCurrentWindow() {
        UploadAssociation upload = currentRememberedUpload();
        if (upload == null) {
            toast("No upload associated with this session");
            return;
        }
        copyUploadPathToClipboard(upload);
        updateSessionTitleStrip(visibleBodyTitleBinding);
        focusTerminalInputSoon(false);
    }

    private boolean pasteRememberedUploadForCurrentWindow() {
        UploadAssociation upload = currentRememberedUpload();
        if (upload == null) {
            toast("No upload associated with this session");
            return true;
        }
        pasteUploadedMediaPath(upload);
        return true;
    }

    private void copyUploadPathToClipboard(UploadAssociation upload) {
        if (upload == null || upload.path == null || upload.path.trim().isEmpty()) {
            return;
        }
        ClipboardManager clipboardManager =
                (ClipboardManager) getSystemService(Context.CLIPBOARD_SERVICE);
        if (clipboardManager != null) {
            clipboardManager.setPrimaryClip(ClipData.newPlainText("WEzterm uploaded media path", upload.path));
        }
    }

    private void pasteUploadedMediaPath(UploadAssociation upload) {
        if (upload == null || upload.path == null || upload.path.trim().isEmpty()) {
            toast("No upload path available");
            return;
        }
        postText(appendStableWindowQuery("/paste", upload.windowId), upload.path, pastePayload -> {
            if (!pastePayload.optBoolean("ok", false)) {
                toast(pastePayload.optString("error", "Paste path failed"));
                return;
            }
            settleLiveBottomAfterPaste("upload-paste");
            hideDockedPromptComposer(false, true);
            focusTerminalInputSoon(false);
        }, exc -> toast("Mantis Control is not reachable"));
    }

    private String humanBytes(long bytes) {
        if (bytes < 0) {
            return "unknown size";
        }
        if (bytes < 1024) {
            return bytes + " B";
        }
        double kib = bytes / 1024.0;
        if (kib < 1024) {
            return String.format("%.1f KB", kib);
        }
        double mib = kib / 1024.0;
        if (mib < 1024) {
            return String.format("%.1f MB", mib);
        }
        return String.format("%.1f GB", mib / 1024.0);
    }

    private void showTabs() {
        showActiveSessions();
    }

    private void showActiveSessions() {
        hideDockedPromptComposerForNavigation("active-dialog");
        String visibleWindowId = visibleTerminalTargetKey();
        long actionDownUptimeMs = consumeActiveSessionsActionDownUptimeMs();
        String actionId = beginApkAction("active-open", visibleWindowId);
        String tapId = currentApkTapIdForLog();
        // WHY: each physical Active open owns one immutable async generation.
        // Selection already advances this revision; advancing it here also
        // prevents an older open/fallback/timeout from borrowing a newer tap.
        long responseRevision = ++activeSessionsDataRevision;
        bindActiveSessionsDialogDrawAction(
                actionId,
                tapId,
                visibleWindowId,
                actionDownUptimeMs,
                responseRevision
        );
        showToolbarControlPending("Active Sessions");
        markApkFirstLocalFeedback("toolbar-pending", visibleWindowId);
        String recentProjectionWindowId = recentActiveSwitchProjectionWindowId;
        if (recentActiveSwitchProjectionUsableFor(recentProjectionWindowId)) {
            paintRecentActiveSwitchProjection(recentProjectionWindowId, "active-open");
        }
        boolean showedCachedDialog = false;
        if (recentActiveSessionsDialogUsableFor(visibleWindowId)) {
            showedCachedDialog = showRecentActiveSessionsDialog(
                    visibleWindowId,
                    actionId,
                    tapId,
                    actionDownUptimeMs,
                    responseRevision
            );
        }
        if (!showedCachedDialog
                && retainedActiveSessionsDisplayUsableFor(visibleWindowId)) {
            showedCachedDialog = showRetainedActiveSessionsDisplayDialog(
                    visibleWindowId,
                    actionId,
                    tapId,
                    actionDownUptimeMs,
                    responseRevision
            );
        }
        if (!showedCachedDialog && activeSessionsCacheFresh()) {
            try {
                // WHY: Active Sessions is the most common correction path and the
                // measured `/tabs?light=1` p95 is too slow to be the first visible
                // response. Reuse only a very recent immutable @windowId payload for
                // an instant reopen, then refresh the cache in the background. This
                // cached Active payload is display-only acceleration, not title/session
                // authority; row titles still come from central fields and successful
                // selection drops the cache. Older cached lists can outlive tmux
                // recovery/restarts and show dead rows such as @46; those must wait for
                // fresh `/tabs` rather than brick the live Codex target with stale
                // selection attempts.
                JSONObject cachedDisplayPayload =
                        activeSessionsCanonicalDisplayCopy(
                                cachedActiveSessionsPayload,
                                "cached-dialog"
                        );
                if (cachedDisplayPayload == null) {
                    throw new IllegalStateException(
                            "cached title references could not be resolved"
                    );
                }
                showActiveSessionsDialog(
                        cachedDisplayPayload,
                        "Active Sessions",
                        true,
                        actionId,
                        tapId,
                        visibleWindowId,
                        actionDownUptimeMs,
                        responseRevision
                );
                showedCachedDialog = true;
                Log.i(CONTROL_LOG_TAG,
                        "stage=control-local control=active-sessions result=cached-dialog"
                                + " actionId=" + safeLogToken(currentApkActionIdForLog())
                                + " tapId=" + safeLogToken(currentApkTapIdForLog())
                                + " cacheAgeMs=" + Math.max(0, SystemClock.elapsedRealtime() - cachedActiveSessionsPayloadAtMs));
            } catch (Exception exc) {
                clearActiveSessionsCache("cached-dialog-failed");
                Log.w(CONTROL_LOG_TAG, "stage=control-local control=active-sessions result=cached-dialog-failed", exc);
            }
        }
        final boolean cachedDialogVisible = showedCachedDialog;
        if (activeSessionsDisplayPrewarmInFlight && cachedDialogVisible) {
            // WHY: onCreate already owns the identical light request. Joining it
            // avoids a cold-start duplicate whose two 160KB responses compete
            // with the terminal renderer when a retained dialog is already
            // visible. A first-ever cacheless open still owns its normal
            // foreground request so prewarm failure cannot strand the tap.
            Log.i(CONTROL_LOG_TAG,
                    "stage=control-local control=active-sessions"
                            + " result=joined-prewarm"
                            + " actionId=" + safeLogToken(actionId)
                            + " windowId=" + safeWindowIdForControlLog(visibleWindowId));
            return;
        }
        // WHY: Active Sessions is the phone's hot tab switcher. It must not wait
        // for `/sessions`, which also scans old Codex sessions and heavier
        // per-window pane status. Use the light `/tabs` payload for immediate
        // stable `@windowId` Open/Close; Old Sessions has its own old-only
        // saved-session endpoint so it cannot inherit live-window rows or broad
        // `/sessions` latency.
        getJsonWithRetry("/tabs?light=1", payload -> {
            if (!activeSessionsResponseRevisionCurrent(
                    responseRevision,
                    "initial-tabs-light"
            )) {
                return;
            }
            if (rejectActiveSessionsPayloadIfUnstable(payload, "tabs-light")) {
                if (showBoundedStaleActiveSessionsDialog(
                        payload,
                        cachedDialogVisible,
                        visibleWindowId,
                        actionId,
                        tapId,
                        actionDownUptimeMs,
                        responseRevision,
                        "tabs-light-rejected"
                )) {
                    return;
                }
                if (!cachedDialogVisible) {
                    requestFullActiveSessionsPayload(
                            cachedDialogVisible,
                            "tabs-light-rejected",
                            responseRevision,
                            actionId,
                            tapId,
                            visibleWindowId,
                            actionDownUptimeMs
                    );
                }
                return;
            }
            String payloadActiveWindowId =
                    payload.optString("activeWindowId", "").trim();
            if (!hasStableWindowId(payloadActiveWindowId)
                    || !activeSessionsPayloadHasExactlyOneActiveWindow(
                            payload,
                            payloadActiveWindowId
                    )) {
                if (showBoundedStaleActiveSessionsDialog(
                        payload,
                        cachedDialogVisible,
                        visibleWindowId,
                        actionId,
                        tapId,
                        actionDownUptimeMs,
                        responseRevision,
                        "tabs-light-target-mismatch"
                )) {
                    return;
                }
                if (!cachedDialogVisible) {
                    requestFullActiveSessionsPayload(
                            cachedDialogVisible,
                            "tabs-light-target-mismatch",
                            responseRevision,
                            actionId,
                            tapId,
                            visibleWindowId,
                            actionDownUptimeMs
                    );
                }
                return;
            }
            if (hasStableWindowId(visibleWindowId)
                    && !visibleWindowId.equals(payloadActiveWindowId)) {
                // WHY: Active Sessions is the recovery surface for selection
                // drift. The terminal body can still display the prior target
                // while the server's one canonical selection has advanced.
                // Open the first valid canonical list immediately; waiting for
                // the old visible target makes switching impossible and adds a
                // redundant full /tabs request to the hot tap path.
                Log.i(CONTROL_LOG_TAG,
                        "stage=control-local control=active-sessions"
                                + " result=canonical-selection-drift-recovery"
                                + " visibleWindowId="
                                + safeWindowIdForControlLog(visibleWindowId)
                                + " selectedWindowId="
                                + safeWindowIdForControlLog(payloadActiveWindowId));
            }
            rememberActiveSessionsPayload(payload, "tabs-light");
            if (cachedDialogVisible) {
                refreshActiveSessionsDialogPayloadIfShowing(
                        payload,
                        "initial-tabs-light"
                );
                // WHY(fresh dialog supersedes projection clock): the retained
                // or recent picker may have armed a bounded stale-expiry task.
                // Once this exact live response repaints the same native dialog,
                // that old task must lose ownership; otherwise it dismisses the
                // fully refreshed picker a few seconds later and makes rows seem
                // to disappear. The live payload/cache remains authoritative.
                clearRecentActiveSessionsDialogProjection(
                        "initial-live-payload-replaced"
                );
            } else {
                showActiveSessionsDialog(
                        payload,
                        "Active Sessions",
                        true,
                        actionId,
                        tapId,
                        payloadActiveWindowId,
                        actionDownUptimeMs,
                        responseRevision
                );
            }
        }, exc -> {
            if (!activeSessionsResponseRevisionCurrent(
                    responseRevision,
                    "initial-tabs-light-failed"
            )) {
                return;
            }
            if (!cachedDialogVisible) {
                requestFullActiveSessionsPayload(
                        cachedDialogVisible,
                        "tabs-light-failed",
                        responseRevision,
                        actionId,
                        tapId,
                        visibleWindowId,
                        actionDownUptimeMs
                );
            }
        });
    }

    private boolean showBoundedStaleActiveSessionsDialog(
            JSONObject payload,
            boolean cachedDialogVisible,
            String visibleWindowId,
            String actionId,
            String tapId,
            long actionDownUptimeMs,
            long responseRevision,
            String reason
    ) {
        if (payload == null
                || payload.optBoolean("snapshotEmergency", false)
                || !payload.optBoolean("snapshotStale", false)
                || activeSessionsPayloadRowCount(payload) <= 0
                || !hasStableWindowId(visibleWindowId)
                || !activeSessionsPayloadContainsExactWindow(payload, visibleWindowId)) {
            return false;
        }
        long ageMs = payload.optLong("snapshotAgeMs", Long.MAX_VALUE);
        if (ageMs < 0 || ageMs > ACTIVE_SESSIONS_DISPLAY_ONLY_STALE_MAX_AGE_MS) {
            return false;
        }
        try {
            JSONObject displayPayload = new JSONObject(payload.toString());
            // WHY: title bytes do not participate in Active list freshness.
            // Rebase stable rows to the exact body already visible on this phone;
            // each row resolves independently through its persisted exact-binding
            // canonical envelope.
            // Row Open still targets a stable @windowId and /select-live performs
            // the server-side mutation/identity validation.
            if (!rebaseActiveSessionsPayloadForWindow(displayPayload, visibleWindowId)
                    || !activeSessionsPayloadHasExactlyOneActiveWindow(
                    displayPayload,
                    visibleWindowId
            )) {
                return false;
            }
            rememberRetainedActiveSessionsDisplayPayload(
                    displayPayload,
                    visibleWindowId,
                    reason
            );
            if (cachedDialogVisible) {
                refreshActiveSessionsDialogPayloadIfShowing(
                        displayPayload,
                        reason + "-display-only"
                );
            } else {
                showActiveSessionsDialog(
                        displayPayload,
                        "Active Sessions",
                        true,
                        actionId,
                        tapId,
                        visibleWindowId,
                        actionDownUptimeMs,
                        responseRevision
                );
            }
            Log.i(CONTROL_LOG_TAG,
                    "stage=control-local control=active-sessions"
                            + " result=bounded-stale-display"
                            + " reason=" + safeLogToken(reason)
                            + " windowId=" + safeWindowIdForControlLog(visibleWindowId)
                            + " snapshotAgeMs=" + ageMs);
            return true;
        } catch (Exception exc) {
            Log.w(CONTROL_LOG_TAG,
                    "stage=control-local control=active-sessions"
                            + " result=bounded-stale-display-failed"
                            + " reason=" + safeLogToken(reason),
                    exc);
            return false;
        }
    }

    private void requestFullActiveSessionsPayload(
            boolean cachedDialogVisible,
            String reason,
            long responseRevision,
            String actionId,
            String tapId,
            String targetWindowId,
            long actionDownUptimeMs
    ) {
        getJsonWithRetry("/tabs", payload -> {
            if (!activeSessionsResponseRevisionCurrent(
                    responseRevision,
                    reason + "-tabs-full"
            )) {
                return;
            }
            if (rejectActiveSessionsPayloadIfUnstable(payload, reason + "-tabs-full")) {
                if (!cachedDialogVisible) {
                    toast("Active Sessions is waiting for fresh data");
                }
                return;
            }
            String payloadActiveWindowId =
                    payload.optString("activeWindowId", "").trim();
            if (!hasStableWindowId(payloadActiveWindowId)
                    || !activeSessionsPayloadHasExactlyOneActiveWindow(
                            payload,
                            payloadActiveWindowId
                    )) {
                if (!cachedDialogVisible) {
                    toast("Active Sessions is waiting for fresh data");
                }
                return;
            }
            if (hasStableWindowId(targetWindowId)
                    && !targetWindowId.equals(payloadActiveWindowId)) {
                Log.i(CONTROL_LOG_TAG,
                        "stage=control-local control=active-sessions"
                                + " result=canonical-selection-drift-recovery"
                                + " visibleWindowId="
                                + safeWindowIdForControlLog(targetWindowId)
                                + " selectedWindowId="
                                + safeWindowIdForControlLog(payloadActiveWindowId)
                                + " source=tabs-full");
            }
            rememberActiveSessionsPayload(payload, reason + "-tabs-full");
            if (cachedDialogVisible) {
                refreshActiveSessionsDialogPayloadIfShowing(
                        payload,
                        reason + "-initial-tabs-full"
                );
            } else {
                showActiveSessionsDialog(
                        payload,
                        "Active Sessions",
                        true,
                        actionId,
                        tapId,
                        payloadActiveWindowId,
                        actionDownUptimeMs,
                        responseRevision
                );
            }
        }, fallbackExc -> {
            if (!activeSessionsResponseRevisionCurrent(
                    responseRevision,
                    reason + "-tabs-full-failed"
            )) {
                return;
            }
            if (!cachedDialogVisible) {
                toast("Mantis Control is not reachable");
            }
        });
    }

    private boolean activeSessionsResponseRevisionCurrent(
            long expectedRevision,
            String reason
    ) {
        if (expectedRevision == activeSessionsDataRevision) {
            return true;
        }
        // WHY: a slow pre-selection `/tabs` response describes the old active
        // target. It must never overwrite the exact post-confirmation 3s rebase
        // or refill the broad 30s cache after a newer A-B-A selection.
        Log.i(CONTROL_LOG_TAG,
                "stage=control-local control=active-sessions"
                        + " result=stale-response-ignored"
                        + " reason=" + safeLogToken(reason)
                        + " expectedRevision=" + expectedRevision
                        + " currentRevision=" + activeSessionsDataRevision);
        return false;
    }

    private boolean activeSessionsCacheFresh() {
        if (cachedActiveSessionsPayload == null) {
            return false;
        }
        String rejectReason = activeSessionsPayloadRejectReason(cachedActiveSessionsPayload);
        if (!rejectReason.isEmpty()) {
            // WHY: Active can reopen immediately after Old/session recovery. A
            // cached emergency/stale snapshot would paint the pre-selection title
            // and color table, then flip a few seconds later after fresh `/tabs`.
            clearActiveSessionsCache("cached-" + rejectReason);
            return false;
        }
        long ageMs = SystemClock.elapsedRealtime() - cachedActiveSessionsPayloadAtMs;
        if (ageMs >= 0 && ageMs <= ACTIVE_SESSIONS_CACHE_MAX_AGE_MS) {
            return true;
        }
        clearActiveSessionsCache("stale-cache");
        return false;
    }

    private JSONObject activeSessionsCanonicalDisplayCopy(
            JSONObject payload,
            String reason
    ) {
        if (payload == null) {
            return null;
        }
        try {
            JSONObject displayPayload = new JSONObject(payload.toString());
            if (canonicalTitleStore != null) {
                // A live payload may already carry the full envelope, while a
                // cached payload deliberately stores only the exact binding.
                // Ingest first, then resolve either shape through the same LKG.
                ingestCanonicalTitleEnvelopes(
                        displayPayload,
                        "active-display-" + reason
                );
                canonicalTitleStore.restoreRetainedProjectionReferences(
                        displayPayload
                );
            }
            return displayPayload;
        } catch (Exception exc) {
            Log.w(CONTROL_LOG_TAG,
                    "stage=canonical-title-store"
                            + " result=display-copy-failed"
                            + " reason=" + safeLogToken(reason),
                    exc);
            return null;
        }
    }

    private void rememberActiveSessionsPayload(JSONObject payload, String reason) {
        if (rejectActiveSessionsPayloadIfUnstable(payload, reason)) {
            return;
        }
        JSONObject cachePayload = null;
        try {
            // WHY(Active cache seam): cache only stable row/status/layout data.
            // Ingest every nested outward envelope first, then erase all embedded
            // title bytes from a private copy so neither the 30s cache nor
            // retained projection can silently become a second title authority.
            // Stripping the caller's live object blanked the exact payload that
            // show/refresh rendered, so APK rows displayed only Working/Ready
            // while `/tabs` and tmux already had valid canonical titles.
            // Guard: test_live_payload_cache_copy.py.
            ingestCanonicalTitleEnvelopes(
                    payload,
                    "active-cache-" + reason
            );
            cachePayload = new JSONObject(payload.toString());
            if (canonicalTitleStore != null) {
                canonicalTitleStore.stripEmbeddedTitleBytes(cachePayload);
            }
        } catch (Exception exc) {
            Log.w(CONTROL_LOG_TAG,
                    "stage=canonical-title-store result=active-cache-strip-failed"
                            + " reason=" + safeLogToken(reason),
                    exc);
        }
        if (cachePayload == null) {
            clearActiveSessionsCache(reason + "-copy-failed");
            return;
        }
        cachedActiveSessionsPayload = cachePayload;
        cachedActiveSessionsPayloadAtMs = SystemClock.elapsedRealtime();
        try {
            String activeWindowId = cachePayload.optString(
                    "activeWindowId",
                    ""
            ).trim();
            if (hasStableWindowId(activeWindowId)) {
                rememberRetainedActiveSessionsDisplayPayload(
                        cachePayload,
                        activeWindowId,
                        reason + "-accepted"
                );
                rememberRecentActiveSessionsDialogProjection(
                        new RecentActiveSessionsDialogSnapshot(
                                new JSONObject(cachePayload.toString()),
                                activeWindowId,
                                cachedActiveSessionsPayloadAtMs,
                                cachedActiveSessionsPayloadAtMs,
                                false
                        ),
                        activeWindowId,
                        reason + "-accepted",
                        false
                );
            }
        } catch (Exception exc) {
            clearRecentActiveSessionsDialogProjection(reason + "-copy-failed");
            Log.w(CONTROL_LOG_TAG,
                    "stage=control-local control=active-sessions"
                            + " result=recent-dialog-copy-failed"
                            + " reason=" + safeLogToken(reason),
                    exc);
        }
        Log.i(CONTROL_LOG_TAG,
                "stage=control-local control=active-sessions result=cache-updated"
                        + " reason=" + safeLogToken(reason)
                        + " rows=" + activeSessionsPayloadRowCount(cachePayload));
    }

    private boolean rememberRetainedActiveSessionsDisplayPayload(
            JSONObject payload,
            String windowId,
            String reason
    ) {
        if (payload == null
                || !hasStableWindowId(windowId)
                || payload.optBoolean("snapshotEmergency", false)
                || activeSessionsPayloadRowCount(payload) <= 0) {
            return false;
        }
        boolean stale = payload.optBoolean("snapshotStale", false);
        long snapshotAgeMs = payload.optLong("snapshotAgeMs", stale ? Long.MAX_VALUE : 0);
        if (stale
                && (snapshotAgeMs < 0
                        || snapshotAgeMs
                        > ACTIVE_SESSIONS_DISPLAY_ONLY_STALE_MAX_AGE_MS)) {
            return false;
        }
        try {
            JSONObject displayPayload = new JSONObject(payload.toString());
            if (!rebaseActiveSessionsPayloadForWindow(displayPayload, windowId)
                    || !activeSessionsPayloadHasExactlyOneActiveWindow(
                            displayPayload,
                            windowId
                    )) {
                return false;
            }
            retainedActiveSessionsDisplayPayload = displayPayload;
            retainedActiveSessionsDisplayWindowId = windowId.trim();
            retainedActiveSessionsDisplaySavedAtWallMs =
                    System.currentTimeMillis();
            persistRetainedActiveSessionsDisplaySnapshot();
            Log.i(CONTROL_LOG_TAG,
                    "stage=control-local control=active-sessions"
                            + " result=retained-display-updated"
                            + " reason=" + safeLogToken(reason)
                            + " windowId=" + safeWindowIdForControlLog(windowId)
                            + " rows=" + activeSessionsPayloadRowCount(displayPayload));
            return true;
        } catch (Exception exc) {
            Log.w(CONTROL_LOG_TAG,
                    "stage=control-local control=active-sessions"
                            + " result=retained-display-copy-failed"
                            + " reason=" + safeLogToken(reason),
                    exc);
            return false;
        }
    }

    private boolean retainedActiveSessionsDisplayUsableFor(String windowId) {
        if (retainedActiveSessionsDisplayPayload == null
                || !hasStableWindowId(windowId)
                || !windowId.equals(retainedActiveSessionsDisplayWindowId)
                || retainedActiveSessionsDisplaySavedAtWallMs <= 0) {
            return false;
        }
        long ageMs = System.currentTimeMillis()
                - retainedActiveSessionsDisplaySavedAtWallMs;
        if (ageMs < 0 || ageMs > ACTIVE_SESSIONS_RETAINED_DISPLAY_MAX_AGE_MS) {
            clearRetainedActiveSessionsDisplaySnapshot("expired");
            return false;
        }
        if (retainedActiveSessionsDisplayPayload.optBoolean(
                "snapshotEmergency",
                false
        )) {
            return false;
        }
        return activeSessionsPayloadContainsExactWindow(
                        retainedActiveSessionsDisplayPayload,
                        windowId
                )
                && activeSessionsPayloadHasExactlyOneActiveWindow(
                        retainedActiveSessionsDisplayPayload,
                        windowId
                );
    }

    private boolean showRetainedActiveSessionsDisplayDialog(
            String windowId,
            String actionId,
            String tapId,
            long actionDownUptimeMs,
            long responseRevision
    ) {
        if (!retainedActiveSessionsDisplayUsableFor(windowId)) {
            return false;
        }
        try {
            JSONObject displayPayload = activeSessionsCanonicalDisplayCopy(
                    retainedActiveSessionsDisplayPayload,
                    "retained-dialog"
            );
            if (displayPayload == null) {
                throw new IllegalStateException(
                        "retained title references could not be resolved"
                );
            }
            showActiveSessionsDialog(
                    displayPayload,
                    "Active Sessions",
                    true,
                    actionId,
                    tapId,
                    windowId,
                    actionDownUptimeMs,
                    responseRevision
            );
            Log.i(CONTROL_LOG_TAG,
                    "stage=control-local control=active-sessions"
                            + " result=retained-native-dialog"
                            + " actionId=" + safeLogToken(actionId)
                            + " tapId=" + safeLogToken(tapId)
                            + " windowId=" + safeWindowIdForControlLog(windowId)
                            + " ageMs="
                            + Math.max(
                                    0,
                                    System.currentTimeMillis()
                                            - retainedActiveSessionsDisplaySavedAtWallMs
                            ));
            return true;
        } catch (Exception exc) {
            clearRetainedActiveSessionsDisplaySnapshot("show-failed");
            return false;
        }
    }

    private void rebaseRetainedActiveSessionsDisplayAfterSelection(
            String windowId,
            String reason
    ) {
        if (retainedActiveSessionsDisplayPayload == null
                || !hasStableWindowId(windowId)) {
            return;
        }
        try {
            JSONObject rebased =
                    new JSONObject(retainedActiveSessionsDisplayPayload.toString());
            if (!rebaseActiveSessionsPayloadForWindow(rebased, windowId)
                    || !activeSessionsPayloadHasExactlyOneActiveWindow(
                            rebased,
                            windowId
                    )) {
                clearRetainedActiveSessionsDisplaySnapshot(
                        reason + "-target-missing"
                );
                return;
            }
            retainedActiveSessionsDisplayPayload = rebased;
            retainedActiveSessionsDisplayWindowId = windowId.trim();
            // Preserve the original freshness clock. Server confirmation makes
            // the active marker safe; it does not make old row titles new.
            persistRetainedActiveSessionsDisplaySnapshot();
            Log.i(CONTROL_LOG_TAG,
                    "stage=control-local control=active-sessions"
                            + " result=retained-display-rebased"
                            + " reason=" + safeLogToken(reason)
                            + " windowId=" + safeWindowIdForControlLog(windowId));
        } catch (Exception exc) {
            clearRetainedActiveSessionsDisplaySnapshot(
                    reason + "-copy-failed"
            );
        }
    }

    private JSONObject compactRetainedActiveSessionsDisplaySnapshot(
            JSONObject payload
    ) throws Exception {
        JSONObject compact = new JSONObject();
        for (String key : new String[]{
                "session",
                "viewSession",
                "activeWindowId",
                "snapshotStale",
                "snapshotEmergency",
                "snapshotAgeMs",
                "snapshotSource"
        }) {
            if (payload.has(key)) {
                compact.put(key, payload.get(key));
            }
        }
        JSONArray groups = payload.optJSONArray("groups");
        if (groups != null && groups.length() > 0) {
            compact.put("groups", new JSONArray(groups.toString()));
        } else {
            JSONArray windows = payload.optJSONArray("displayWindows");
            if (windows == null) {
                windows = payload.optJSONArray("windows");
            }
            if (windows == null) {
                throw new IllegalStateException("missing retained display rows");
            }
            compact.put("displayWindows", new JSONArray(windows.toString()));
        }
        return compact;
    }

    private JSONObject expandRetainedActiveSessionsDisplaySnapshot(
            JSONObject compact
    ) throws Exception {
        JSONObject payload = new JSONObject(compact.toString());
        List<JSONObject> rendered = activeSessionsPayloadRenderedWindows(payload);
        if (rendered.isEmpty()) {
            throw new IllegalStateException("empty retained display rows");
        }
        JSONArray flat = new JSONArray();
        for (JSONObject window : rendered) {
            flat.put(new JSONObject(window.toString()));
        }
        payload.put("tabs", new JSONArray(flat.toString()));
        payload.put("windows", new JSONArray(flat.toString()));
        payload.put("displayWindows", new JSONArray(flat.toString()));
        return payload;
    }

    private void persistRetainedActiveSessionsDisplaySnapshot() {
        if (prefs == null
                || retainedActiveSessionsDisplayPayload == null
                || retainedActiveSessionsDisplaySavedAtWallMs <= 0) {
            return;
        }
        try {
            JSONObject compact = compactRetainedActiveSessionsDisplaySnapshot(
                    retainedActiveSessionsDisplayPayload
            );
            // WHY(retained Active boundary): archived row/layout state may be
            // reused offline, but title bytes have exactly one durable owner.
            // Persist only titleTransportBinding here; CanonicalTitleStore persists
            // the monotonic exact envelope asynchronously under its thread key.
            if (canonicalTitleStore != null) {
                canonicalTitleStore.stripEmbeddedTitleBytes(compact);
            }
            prefs.edit()
                    .putString(
                            PREF_ACTIVE_SESSIONS_RETAINED_DISPLAY_JSON,
                            compact.toString()
                    )
                    .putLong(
                            PREF_ACTIVE_SESSIONS_RETAINED_DISPLAY_SAVED_AT_MS,
                            retainedActiveSessionsDisplaySavedAtWallMs
                    )
                    .apply();
        } catch (Exception exc) {
            Log.w(CONTROL_LOG_TAG,
                    "stage=control-local control=active-sessions"
                            + " result=retained-display-persist-failed",
                    exc);
        }
    }

    private void loadRetainedActiveSessionsDisplaySnapshot() {
        if (prefs == null) {
            return;
        }
        String encoded = prefs.getString(
                PREF_ACTIVE_SESSIONS_RETAINED_DISPLAY_JSON,
                ""
        );
        long savedAtMs = prefs.getLong(
                PREF_ACTIVE_SESSIONS_RETAINED_DISPLAY_SAVED_AT_MS,
                0
        );
        long nowMs = System.currentTimeMillis();
        long ageMs = nowMs - savedAtMs;
        if (encoded == null
                || encoded.trim().isEmpty()
                || savedAtMs <= 0
                || ageMs < 0
                || ageMs > ACTIVE_SESSIONS_RETAINED_DISPLAY_MAX_AGE_MS) {
            clearRetainedActiveSessionsDisplaySnapshot("load-expired-or-empty");
            return;
        }
        try {
            JSONObject payload = expandRetainedActiveSessionsDisplaySnapshot(
                    new JSONObject(encoded)
            );
            if (canonicalTitleStore != null) {
                canonicalTitleStore.restoreRetainedProjectionReferences(
                        payload
                );
            }
            String windowId = payload.optString("activeWindowId", "").trim();
            if (!hasStableWindowId(windowId)
                    || payload.optBoolean("snapshotEmergency", false)
                    || !activeSessionsPayloadHasExactlyOneActiveWindow(
                            payload,
                            windowId
                    )) {
                clearRetainedActiveSessionsDisplaySnapshot("load-invalid");
                return;
            }
            retainedActiveSessionsDisplayPayload = payload;
            retainedActiveSessionsDisplayWindowId = windowId;
            retainedActiveSessionsDisplaySavedAtWallMs = savedAtMs;
            Log.i(CONTROL_LOG_TAG,
                    "stage=control-local control=active-sessions"
                            + " result=retained-display-loaded"
                            + " windowId=" + safeWindowIdForControlLog(windowId)
                            + " ageMs=" + ageMs);
        } catch (Exception exc) {
            clearRetainedActiveSessionsDisplaySnapshot("load-parse-failed");
        }
    }

    private void clearRetainedActiveSessionsDisplaySnapshot(String reason) {
        retainedActiveSessionsDisplayPayload = null;
        retainedActiveSessionsDisplayWindowId = "";
        retainedActiveSessionsDisplaySavedAtWallMs = 0;
        if (prefs != null) {
            prefs.edit()
                    .remove(PREF_ACTIVE_SESSIONS_RETAINED_DISPLAY_JSON)
                    .remove(PREF_ACTIVE_SESSIONS_RETAINED_DISPLAY_SAVED_AT_MS)
                    .apply();
        }
        Log.i(CONTROL_LOG_TAG,
                "stage=control-local control=active-sessions"
                        + " result=retained-display-cleared"
                        + " reason=" + safeLogToken(reason));
    }

    // WHY: FIX PREWARM (switch latency) — warm the server's per-window
    // /terminal-frame visual cache for the sessions currently listed in the Active
    // dialog, using the phone's own measured geometry so the warmed cache entry
    // matches the switch's own frame fetch (server keys the visual cache by
    // windowId + index + rows + cols). This runs while the user reads the list, so a
    // subsequent tap resolves from warm cache (~0.02s) instead of a cold first-frame
    // build (~4s). Speculative only: rendererDemand=passive marks it as
    // non-visible-demand warming and readOnly=1 guarantees no tmux mutation, so it
    // cannot move the visible viewport, scrollback, or Active/Send/Stop lanes.
    private void prewarmListedSessionFramesForSwitch(JSONObject payload, String reason) {
        if (payload == null || webView == null || !activityResumed) {
            return;
        }
        // Measured phone geometry is identical for every listed window (same
        // viewport), so the visible target's last accepted rows/cols are the right
        // key for warming the others. Skip until a real frame has proven geometry.
        int measuredRows = lastAcceptedCaptureRendererRows.size();
        int measuredCols = lastAcceptedCaptureRendererCols;
        if (measuredRows <= 0 || measuredCols < 20) {
            return;
        }
        long now = SystemClock.elapsedRealtime();
        if (now - lastCaptureRendererFramePrewarmAtMs < CAPTURE_RENDERER_FRAME_PREWARM_THROTTLE_MS) {
            return;
        }
        lastCaptureRendererFramePrewarmAtMs = now;
        String visibleWindowId = confirmedVisibleTerminalTargetKey();
        List<String> windowIds = collectListedSessionWindowIds(payload);
        int warmed = 0;
        for (String windowId : windowIds) {
            if (warmed >= CAPTURE_RENDERER_FRAME_PREWARM_MAX_WINDOWS) {
                break;
            }
            if (!hasStableWindowId(windowId) || windowId.equals(visibleWindowId)) {
                // The visible window is already warm and actively polled.
                continue;
            }
            Long inFlightAt = captureRendererFramePrewarmInFlight.get(windowId);
            if (inFlightAt != null && now - inFlightAt < CAPTURE_RENDERER_FRAME_PREWARM_TTL_MS) {
                continue;
            }
            captureRendererFramePrewarmInFlight.put(windowId, now);
            warmed++;
            final String stableWindowId = windowId;
            final int warmRows = measuredRows;
            final int warmCols = measuredCols;
            // WHY: rendererDemand=passive marks this as speculative cache warming
            // (not a visible-frame demand); readOnly=1 forbids any tmux mutation.
            // rows/cols are the phone's measured grid so the warmed entry keys the
            // same visual-cache slot the switch will read.
            String path = "/terminal-frame?windowId=" + urlEncode(stableWindowId)
                    + "&rows=" + warmRows
                    + "&cols=" + warmCols
                    + "&rendererDemand=passive"
                    + "&readOnly=1";
            getJsonDirectOnce(path, warmPayload -> {
                captureRendererFramePrewarmInFlight.remove(stableWindowId);
                prepareTerminalSnapshotOffMainThread(
                        warmPayload,
                        null,
                        "active-prewarm-" + reason
                );
                Log.i(CONTROL_LOG_TAG,
                        "stage=capture-renderer endpoint=/terminal-frame result=prewarmed"
                                + " windowId=" + safeWindowIdForControlLog(stableWindowId)
                                + " rows=" + warmRows
                                + " cols=" + warmCols
                                + " reason=" + safeLogToken(reason));
            }, exc -> {
                // WHY: speculative warming never owns user-visible retry or error UI;
                // the real foreground switch runs its own bounded request.
                captureRendererFramePrewarmInFlight.remove(stableWindowId);
                Log.i(CONTROL_LOG_TAG,
                        "stage=capture-renderer endpoint=/terminal-frame result=prewarm-failed"
                                + " windowId=" + safeWindowIdForControlLog(stableWindowId)
                                + " reason=" + safeLogToken(reason));
            });
        }
    }

    // WHY: FIX PREWARM — enumerate the stable @windowIds currently listed in the
    // Active dialog payload, mirroring populateActiveSessionsList's own source
    // precedence (grouped windows first, else displayWindows/topWindows/windows).
    private List<String> collectListedSessionWindowIds(JSONObject payload) {
        List<String> windowIds = new ArrayList<>();
        if (payload == null) {
            return windowIds;
        }
        JSONArray groups = payload.optJSONArray("groups");
        if (groups != null && groups.length() > 0) {
            for (int i = 0; i < groups.length(); i++) {
                JSONObject group = groups.optJSONObject(i);
                if (group == null) {
                    continue;
                }
                collectWindowIdsFromArray(group.optJSONArray("windows"), windowIds);
            }
            if (!windowIds.isEmpty()) {
                return windowIds;
            }
        }
        JSONArray windows = payload.optJSONArray("displayWindows");
        if (windows == null) {
            windows = payload.optJSONArray("topWindows");
        }
        if (windows == null) {
            windows = payload.optJSONArray("windows");
        }
        collectWindowIdsFromArray(windows, windowIds);
        return windowIds;
    }

    private void collectWindowIdsFromArray(JSONArray windows, List<String> out) {
        if (windows == null) {
            return;
        }
        for (int i = 0; i < windows.length(); i++) {
            JSONObject window = windows.optJSONObject(i);
            if (window == null) {
                continue;
            }
            String windowId = window.optString("windowId", "").trim();
            if (hasStableWindowId(windowId) && !out.contains(windowId)) {
                out.add(windowId);
            }
        }
    }

    private void prewarmActiveSessionsDisplaySnapshot(String reason) {
        if (activeSessionsDisplayPrewarmInFlight
                || activeSessionsDialogRefreshInFlight) {
            scheduleActiveSessionsDialogLiveRefresh(
                    "prewarm-coalesced-" + reason
            );
            return;
        }
        activeSessionsDisplayPrewarmInFlight = true;
        getJsonDirectOnce("/tabs?light=1", payload -> {
            activeSessionsDisplayPrewarmInFlight = false;
            String windowId = payload.optString("activeWindowId", "").trim();
            if (hasStableWindowId(windowId)) {
                rememberRetainedActiveSessionsDisplayPayload(
                        payload,
                        windowId,
                        "prewarm-" + reason
                );
            }
            String visibleWindowId = visibleTerminalTargetKey();
            if (activeSessionsDialog != null
                    && activeSessionsDialog.isShowing()
                    && retainedActiveSessionsDisplayUsableFor(visibleWindowId)) {
                JSONObject displayPayload = activeSessionsCanonicalDisplayCopy(
                        retainedActiveSessionsDisplayPayload,
                        "prewarm-" + reason
                );
                if (displayPayload != null) {
                    refreshActiveSessionsDialogPayloadIfShowing(
                            displayPayload,
                            "prewarm-" + reason
                    );
                }
                scheduleActiveSessionsDialogLiveRefresh(
                        "prewarm-visible-" + reason
                );
                return;
            }
            if ((activeSessionsDialog == null
                            || !activeSessionsDialog.isShowing())
                    && activeSessionsDialogDrawDataRevision
                            == activeSessionsDataRevision
                    && "active-open".equals(currentApkActionKindForLog())
                    && retainedActiveSessionsDisplayUsableFor(
                            activeSessionsDialogDrawWindowId
                    )) {
                showRetainedActiveSessionsDisplayDialog(
                        activeSessionsDialogDrawWindowId,
                        activeSessionsDialogDrawActionId,
                        activeSessionsDialogDrawTapId,
                        activeSessionsDialogDrawActionDownUptimeMs,
                        activeSessionsDialogDrawDataRevision
                );
            }
            scheduleActiveSessionsDialogLiveRefresh(
                    "prewarm-complete-" + reason
            );
        }, exc -> {
            activeSessionsDisplayPrewarmInFlight = false;
            // WHY: speculative prewarm never owns user-visible retry, wake, or
            // full-tabs fallback. Existing retained rows remain usable and a
            // cacheless foreground Active tap runs its own bounded request.
            Log.i(CONTROL_LOG_TAG,
                    "stage=control-local control=active-sessions"
                            + " result=prewarm-failed"
                            + " reason=" + safeLogToken(reason));
            scheduleActiveSessionsDialogLiveRefresh(
                    "prewarm-failed-" + reason
            );
        });
    }

    private RecentActiveSessionsDialogSnapshot recentActiveSessionsDialogSnapshot() {
        if (recentActiveSessionsDialogPayload == null) {
            return new RecentActiveSessionsDialogSnapshot(
                    null,
                    recentActiveSessionsDialogWindowId,
                    recentActiveSessionsDialogPayloadFetchedAtMs,
                    recentActiveSessionsDialogAtMs,
                    recentActiveSessionsDialogSelectionRebased
            );
        }
        try {
            return new RecentActiveSessionsDialogSnapshot(
                    new JSONObject(recentActiveSessionsDialogPayload.toString()),
                    recentActiveSessionsDialogWindowId,
                    recentActiveSessionsDialogPayloadFetchedAtMs,
                    recentActiveSessionsDialogAtMs,
                    recentActiveSessionsDialogSelectionRebased
            );
        } catch (Exception exc) {
            return new RecentActiveSessionsDialogSnapshot(
                    null,
                    "",
                    0,
                    0,
                    false
            );
        }
    }

    private void restoreRecentActiveSessionsDialogSnapshot(
            RecentActiveSessionsDialogSnapshot snapshot,
            String reason
    ) {
        if (snapshot == null
                || snapshot.payload == null
                || !hasStableWindowId(snapshot.windowId)) {
            clearRecentActiveSessionsDialogProjection(reason + "-missing-rollback");
            return;
        }
        try {
            recentActiveSessionsDialogPayload = new JSONObject(snapshot.payload.toString());
            recentActiveSessionsDialogWindowId = snapshot.windowId;
            recentActiveSessionsDialogPayloadFetchedAtMs =
                    snapshot.payloadFetchedAtMs;
            recentActiveSessionsDialogAtMs = snapshot.projectedAtMs;
            recentActiveSessionsDialogSelectionRebased =
                    snapshot.selectionRebased;
            if (!recentActiveSessionsDialogUsableFor(snapshot.windowId)) {
                clearRecentActiveSessionsDialogProjection(reason + "-invalid-rollback");
                return;
            }
            Log.i(CONTROL_LOG_TAG,
                    "stage=active-switch-projection endpoint=active-dialog"
                            + " result=recent-dialog-rollback"
                            + " windowId=" + safeWindowIdForControlLog(snapshot.windowId)
                            + " reason=" + safeLogToken(reason));
        } catch (Exception exc) {
            clearRecentActiveSessionsDialogProjection(reason + "-rollback-copy-failed");
        }
    }

    private boolean rememberRecentActiveSessionsDialogProjection(
            RecentActiveSessionsDialogSnapshot snapshot,
            String windowId,
            String reason,
            boolean selectionRebase
    ) {
        if (snapshot == null
                || snapshot.payload == null
                || !hasStableWindowId(windowId)
                || snapshot.payloadFetchedAtMs <= 0) {
            return false;
        }
        try {
            JSONObject rebasedPayload = new JSONObject(snapshot.payload.toString());
            long nowMs = SystemClock.elapsedRealtime();
            if (!activeSessionsPayloadRejectReason(rebasedPayload).isEmpty()
                    || activeSessionsDialogEffectivePayloadAgeMs(
                            rebasedPayload,
                            snapshot.payloadFetchedAtMs,
                            nowMs
                    ) > ACTIVE_SESSIONS_VALIDATED_STALE_MAX_AGE_MS
                    || !rebaseActiveSessionsPayloadForWindow(rebasedPayload, windowId)
                    || !activeSessionsPayloadHasExactlyOneActiveWindow(
                            rebasedPayload,
                            windowId
                    )) {
                return false;
            }
            recentActiveSessionsDialogPayload = rebasedPayload;
            recentActiveSessionsDialogWindowId = windowId.trim();
            recentActiveSessionsDialogPayloadFetchedAtMs =
                    snapshot.payloadFetchedAtMs;
            recentActiveSessionsDialogAtMs = nowMs;
            recentActiveSessionsDialogSelectionRebased = selectionRebase;
            // WHY: every accepted projection replaces the timestamps that own
            // the prior expiry callback. Re-arm against the new immutable
            // clocks so a later refresh failure cannot leave an actionable
            // picker alive forever.
            scheduleRecentActiveSessionsDialogExpiryIfShowing(
                    recentActiveSessionsDialogWindowId,
                    recentActiveSessionsDialogPayloadFetchedAtMs,
                    recentActiveSessionsDialogAtMs
            );
            Log.i(CONTROL_LOG_TAG,
                    "stage=active-switch-projection endpoint=active-dialog"
                            + " result=recent-dialog-remembered"
                            + " windowId=" + safeWindowIdForControlLog(windowId)
                            + " reason=" + safeLogToken(reason)
                            + " rows=" + activeSessionsPayloadRowCount(rebasedPayload));
            return true;
        } catch (Exception exc) {
            Log.w(CONTROL_LOG_TAG,
                    "stage=active-switch-projection endpoint=active-dialog"
                            + " result=recent-dialog-rebase-failed"
                            + " reason=" + safeLogToken(reason),
                    exc);
            return false;
        }
    }

    private boolean recentActiveSessionsDialogUsableFor(String windowId) {
        if (recentActiveSessionsDialogPayload == null
                || !hasStableWindowId(windowId)
                || !windowId.equals(recentActiveSessionsDialogWindowId)) {
            return false;
        }
        long nowMs = SystemClock.elapsedRealtime();
        long projectionAgeMs = nowMs - recentActiveSessionsDialogAtMs;
        long effectivePayloadAgeMs = activeSessionsDialogEffectivePayloadAgeMs(
                recentActiveSessionsDialogPayload,
                recentActiveSessionsDialogPayloadFetchedAtMs,
                nowMs
        );
        if (projectionAgeMs < 0
                || (recentActiveSessionsDialogSelectionRebased
                        && projectionAgeMs
                        > ACTIVE_SWITCH_RECENT_DIALOG_MAX_AGE_MS)
                || effectivePayloadAgeMs
                > ACTIVE_SESSIONS_VALIDATED_STALE_MAX_AGE_MS) {
            return false;
        }
        return activeSessionsPayloadRejectReason(recentActiveSessionsDialogPayload).isEmpty()
                && activeSessionsPayloadContainsExactWindow(
                        recentActiveSessionsDialogPayload,
                        windowId
                )
                && activeSessionsPayloadHasExactlyOneActiveWindow(
                        recentActiveSessionsDialogPayload,
                        windowId
                );
    }

    private long activeSessionsDialogEffectivePayloadAgeMs(
            JSONObject payload,
            long payloadFetchedAtMs,
            long nowMs
    ) {
        if (payload == null
                || payloadFetchedAtMs <= 0
                || nowMs < payloadFetchedAtMs) {
            return Long.MAX_VALUE;
        }
        long localAgeMs = nowMs - payloadFetchedAtMs;
        long serverSnapshotAgeMs = payload.has("snapshotAgeMs")
                ? payload.optLong("snapshotAgeMs", -1)
                : 0;
        if (serverSnapshotAgeMs < 0
                || localAgeMs
                > Long.MAX_VALUE - serverSnapshotAgeMs) {
            return Long.MAX_VALUE;
        }
        return localAgeMs + serverSnapshotAgeMs;
    }

    private boolean showRecentActiveSessionsDialog(
            String windowId,
            String actionId,
            String tapId,
            long actionDownUptimeMs,
            long responseRevision
    ) {
        if (!recentActiveSessionsDialogUsableFor(windowId)) {
            return false;
        }
        try {
            JSONObject dialogPayload = activeSessionsCanonicalDisplayCopy(
                    recentActiveSessionsDialogPayload,
                    "recent-dialog"
            );
            if (dialogPayload == null) {
                throw new IllegalStateException(
                        "recent title references could not be resolved"
                );
            }
            showActiveSessionsDialog(
                    dialogPayload,
                    "Active Sessions",
                    true,
                    actionId,
                    tapId,
                    windowId,
                    actionDownUptimeMs,
                    responseRevision
            );
            scheduleRecentActiveSessionsDialogExpiryIfShowing(
                    windowId,
                    recentActiveSessionsDialogPayloadFetchedAtMs,
                    recentActiveSessionsDialogAtMs
            );
            long nowMs = SystemClock.elapsedRealtime();
            Log.i(CONTROL_LOG_TAG,
                    "stage=control-local control=active-sessions"
                            + " result=recent-native-dialog"
                            + " actionId=" + safeLogToken(actionId)
                            + " tapId=" + safeLogToken(tapId)
                            + " windowId=" + safeWindowIdForControlLog(windowId)
                            + " projectionAgeMs="
                            + Math.max(0, nowMs - recentActiveSessionsDialogAtMs)
                            + " effectivePayloadAgeMs="
                            + activeSessionsDialogEffectivePayloadAgeMs(
                                    recentActiveSessionsDialogPayload,
                                    recentActiveSessionsDialogPayloadFetchedAtMs,
                                    nowMs
                            ));
            return true;
        } catch (Exception exc) {
            clearRecentActiveSessionsDialogProjection("show-recent-dialog-failed");
            Log.w(CONTROL_LOG_TAG,
                    "stage=control-local control=active-sessions"
                            + " result=recent-native-dialog-failed",
                    exc);
            return false;
        }
    }

    private void scheduleRecentActiveSessionsDialogExpiryIfShowing(
            String windowId,
            long expectedPayloadFetchedAtMs,
            long expectedProjectedAtMs
    ) {
        if (activeSessionsDialog == null
                || !activeSessionsDialog.isShowing()) {
            return;
        }
        AlertDialog expectedDialog = activeSessionsDialog;
        long expectedDialogGeneration = activeSessionsDialogInstanceGeneration;
        boolean expectedSelectionRebased =
                recentActiveSessionsDialogSelectionRebased;
        long nowMs = SystemClock.elapsedRealtime();
        long projectionAgeMs = Math.max(
                0,
                nowMs - expectedProjectedAtMs
        );
        long effectivePayloadAgeMs = activeSessionsDialogEffectivePayloadAgeMs(
                recentActiveSessionsDialogPayload,
                expectedPayloadFetchedAtMs,
                nowMs
        );
        long projectionRemainingMs = expectedSelectionRebased
                ? Math.max(
                        0,
                        ACTIVE_SWITCH_RECENT_DIALOG_MAX_AGE_MS
                                - projectionAgeMs
                )
                : Long.MAX_VALUE;
        long payloadRemainingMs = Math.max(
                0,
                ACTIVE_SESSIONS_VALIDATED_STALE_MAX_AGE_MS
                        - effectivePayloadAgeMs
        );
        long delayMs = Math.min(projectionRemainingMs, payloadRemainingMs) + 1;
        uiHandler.postDelayed(() -> {
            if (recentActiveSessionsDialogSelectionRebased
                    != expectedSelectionRebased
                    || recentActiveSessionsDialogPayloadFetchedAtMs
                    != expectedPayloadFetchedAtMs
                    || recentActiveSessionsDialogAtMs != expectedProjectedAtMs
                    || !windowId.equals(recentActiveSessionsDialogWindowId)
                    || activeSessionsDialog != expectedDialog
                    || activeSessionsDialogInstanceGeneration
                    != expectedDialogGeneration
                    || !expectedDialog.isShowing()
                    || recentActiveSessionsDialogUsableFor(windowId)) {
                return;
            }
            // WHY: the 3s post-confirmation projection and the 30s canonical
            // payload are both bounded display authority. If refresh does not
            // replace either before its clock expires, remove the whole picker
            // so stale active markers and state-changing controls cannot remain
            // actionable. A late response may refresh the cache but must not
            // reopen a dialog the user no longer owns.
            clearRecentActiveSessionsDialogProjection(
                    expectedSelectionRebased
                            ? "selection-rebase-expired"
                            : "canonical-dialog-expired"
            );
            expectedDialog.dismiss();
            Log.w(CONTROL_LOG_TAG,
                    "stage=control-local control=active-sessions"
                            + " result=recent-native-dialog-expired"
                            + " selectionRebased="
                            + expectedSelectionRebased
                            + " windowId="
                            + safeWindowIdForControlLog(windowId));
        }, delayMs);
    }

    private void clearRecentActiveSessionsDialogProjection(String reason) {
        recentActiveSessionsDialogPayload = null;
        recentActiveSessionsDialogWindowId = "";
        recentActiveSessionsDialogPayloadFetchedAtMs = 0;
        recentActiveSessionsDialogAtMs = 0;
        recentActiveSessionsDialogSelectionRebased = false;
        Log.i(CONTROL_LOG_TAG,
                "stage=active-switch-projection endpoint=active-dialog"
                        + " result=recent-dialog-cleared"
                        + " reason=" + safeLogToken(reason));
    }

    private boolean activeSessionsPayloadContainsExactWindow(
            JSONObject payload,
            String windowId
    ) {
        if (payload == null || !hasStableWindowId(windowId)) {
            return false;
        }
        int matches = 0;
        for (JSONObject window : activeSessionsPayloadRenderedWindows(payload)) {
            if (windowId.equals(window.optString("windowId", "").trim())) {
                matches++;
            }
        }
        return matches == 1;
    }

    private boolean activeSessionsPayloadHasExactlyOneActiveWindow(
            JSONObject payload,
            String windowId
    ) {
        if (payload == null || !hasStableWindowId(windowId)) {
            return false;
        }
        if (!activeSessionsPayloadRequiredAliasesContainExactWindow(
                payload,
                windowId
        )) {
            return false;
        }
        String declaredWindowId = payload.optString("activeWindowId", "").trim();
        if (!declaredWindowId.isEmpty() && !windowId.equals(declaredWindowId)) {
            return false;
        }
        int targetMatches = 0;
        int activeRows = 0;
        int activeTargetRows = 0;
        for (JSONObject window : activeSessionsPayloadRenderedWindows(payload)) {
            boolean target = windowId.equals(
                    window.optString("windowId", "").trim()
            );
            boolean active = window.optBoolean("active", false);
            targetMatches += target ? 1 : 0;
            activeRows += active ? 1 : 0;
            activeTargetRows += target && active ? 1 : 0;
        }
        if (targetMatches != 1
                || activeRows != 1
                || activeTargetRows != 1) {
            return false;
        }
        for (JSONArray windows : activeSessionsPayloadWindowCollections(payload)) {
            int collectionTargetMatches = 0;
            int collectionActiveRows = 0;
            int collectionActiveTargetRows = 0;
            for (int index = 0; index < windows.length(); index++) {
                JSONObject window = windows.optJSONObject(index);
                if (window == null) {
                    continue;
                }
                boolean target = windowId.equals(
                        window.optString("windowId", "").trim()
                );
                boolean active = window.optBoolean("active", false);
                collectionTargetMatches += target ? 1 : 0;
                collectionActiveRows += active ? 1 : 0;
                collectionActiveTargetRows += target && active ? 1 : 0;
            }
            if (collectionTargetMatches > 1
                    || collectionActiveRows
                    != (collectionTargetMatches == 1 ? 1 : 0)
                    || collectionActiveTargetRows
                    != collectionTargetMatches) {
                return false;
            }
        }
        return true;
    }

    private boolean activeSessionsPayloadRequiredAliasesContainExactWindow(
            JSONObject payload,
            String windowId
    ) {
        if (payload == null || !hasStableWindowId(windowId)) {
            return false;
        }
        // WHY: current light/full `/tabs` contracts make every populated core
        // picker alias a complete live/display projection. A contradictory
        // alias must not validate merely because grouped rows contain the
        // selected ID. `topWindows` is deliberately excluded: it is a parent
        // subset and may legitimately omit a selected child while carrying no
        // competing active row.
        String[] requiredAliases = {
                "tabs",
                "windows",
                "displayWindows"
        };
        for (String alias : requiredAliases) {
            JSONArray windows = payload.optJSONArray(alias);
            if (windows == null || windows.length() == 0) {
                return false;
            }
            int matches = 0;
            for (int index = 0; index < windows.length(); index++) {
                JSONObject window = windows.optJSONObject(index);
                if (window != null
                        && windowId.equals(
                                window.optString("windowId", "").trim()
                        )) {
                    matches++;
                }
            }
            if (matches != 1) {
                return false;
            }
        }
        return true;
    }

    private boolean rebaseActiveSessionsPayloadForWindow(
            JSONObject payload,
            String windowId
    ) throws Exception {
        if (payload == null || !hasStableWindowId(windowId)) {
            return false;
        }
        List<JSONObject> renderedWindows =
                activeSessionsPayloadRenderedWindows(payload);
        int matches = 0;
        for (JSONObject window : renderedWindows) {
            if (windowId.equals(window.optString("windowId", "").trim())) {
                matches++;
            }
        }
        if (matches != 1) {
            return false;
        }
        // WHY: `/tabs` can carry the same logical rows in grouped and flat
        // aliases. Rebase every populated representation copy-on-write so
        // dialog rows, activeWindow lookup, Close metadata, and later refresh
        // consumers cannot disagree about which exact stable ID is active.
        for (JSONArray windows : activeSessionsPayloadWindowCollections(payload)) {
            int collectionMatches = 0;
            for (int index = 0; index < windows.length(); index++) {
                JSONObject window = windows.optJSONObject(index);
                if (window == null) {
                    continue;
                }
                boolean target = windowId.equals(
                        window.optString("windowId", "").trim()
                );
                collectionMatches += target ? 1 : 0;
                window.put("active", target);
            }
            if (collectionMatches > 1) {
                return false;
            }
        }
        payload.put("activeWindowId", windowId.trim());
        return activeSessionsPayloadHasExactlyOneActiveWindow(payload, windowId);
    }

    private List<JSONObject> activeSessionsPayloadRenderedWindows(
            JSONObject payload
    ) {
        List<JSONObject> renderedWindows = new ArrayList<>();
        if (payload == null) {
            return renderedWindows;
        }
        JSONArray groups = payload.optJSONArray("groups");
        if (groups != null && groups.length() > 0) {
            for (int groupIndex = 0; groupIndex < groups.length(); groupIndex++) {
                JSONObject group = groups.optJSONObject(groupIndex);
                JSONArray windows = group == null
                        ? null
                        : group.optJSONArray("windows");
                appendActiveSessionsWindows(renderedWindows, windows);
            }
            return renderedWindows;
        }
        JSONArray windows = payload.optJSONArray("displayWindows");
        if (windows == null) {
            windows = payload.optJSONArray("topWindows");
        }
        if (windows == null) {
            windows = payload.optJSONArray("windows");
        }
        appendActiveSessionsWindows(renderedWindows, windows);
        return renderedWindows;
    }

    private void appendActiveSessionsWindows(
            List<JSONObject> renderedWindows,
            JSONArray windows
    ) {
        if (renderedWindows == null || windows == null) {
            return;
        }
        for (int index = 0; index < windows.length(); index++) {
            JSONObject window = windows.optJSONObject(index);
            if (window != null) {
                renderedWindows.add(window);
            }
        }
    }

    private List<JSONArray> activeSessionsPayloadWindowCollections(
            JSONObject payload
    ) {
        List<JSONArray> collections = new ArrayList<>();
        if (payload == null) {
            return collections;
        }
        appendActiveSessionsWindowCollection(
                collections,
                payload.optJSONArray("tabs")
        );
        appendActiveSessionsWindowCollection(
                collections,
                payload.optJSONArray("windows")
        );
        appendActiveSessionsWindowCollection(
                collections,
                payload.optJSONArray("displayWindows")
        );
        appendActiveSessionsWindowCollection(
                collections,
                payload.optJSONArray("topWindows")
        );
        JSONArray groups = payload.optJSONArray("groups");
        if (groups != null) {
            for (int groupIndex = 0;
                    groupIndex < groups.length();
                    groupIndex++) {
                JSONObject group = groups.optJSONObject(groupIndex);
                appendActiveSessionsWindowCollection(
                        collections,
                        group == null ? null : group.optJSONArray("windows")
                );
            }
        }
        return collections;
    }

    private void appendActiveSessionsWindowCollection(
            List<JSONArray> collections,
            JSONArray windows
    ) {
        if (collections == null || windows == null) {
            return;
        }
        for (JSONArray existing : collections) {
            if (existing == windows) {
                return;
            }
        }
        collections.add(windows);
    }

    private void rememberRecentActiveSwitchProjection(String windowId, String reason) {
        // WHY: this display-only continuity cache is not title/session/Send/Close
        // authority. It copies one accepted frame/list for the exact stable
        // @windowId so Android can commit already-owned pixels while fresh truth
        // catches up; every mismatch and rollback remains fail-closed.
        if (!hasStableWindowId(windowId)
                || !windowId.equals(lastAcceptedCaptureRendererFrameWindowId)
                || lastAcceptedCaptureRendererFrameHash == null
                || lastAcceptedCaptureRendererFrameHash.trim().isEmpty()
                || lastAcceptedCaptureRendererRows.isEmpty()) {
            return;
        }
        int bodyLength = 0;
        for (int index = 0; index < lastAcceptedCaptureRendererRows.size(); index++) {
            String row = lastAcceptedCaptureRendererRows.get(index);
            bodyLength += row == null ? 0 : row.length();
            if (index > 0) {
                bodyLength += 1;
            }
        }
        if (bodyLength <= 0) {
            return;
        }
        recentActiveSwitchProjectionWindowId = windowId.trim();
        recentActiveSwitchProjectionFrameWindowId =
                lastAcceptedCaptureRendererFrameWindowId.trim();
        recentActiveSwitchProjectionFrameHash =
                lastAcceptedCaptureRendererFrameHash.trim();
        recentActiveSwitchProjectionBodyLength = bodyLength;
        recentActiveSwitchProjectionRowCount = lastAcceptedCaptureRendererRows.size();
        recentActiveSwitchProjectionAtMs = SystemClock.elapsedRealtime();
        recentActiveSwitchProjectionRows.clear();
        recentActiveSwitchProjectionRows.addAll(lastAcceptedCaptureRendererRows);
        recentActiveSwitchProjectionPaintRows.clear();
        recentActiveSwitchProjectionPaintRows.addAll(lastAcceptedCaptureRendererPaintRows);
        Log.i(CONTROL_LOG_TAG,
                "stage=active-switch-projection endpoint=renderer result=recent-projection-remembered"
                        + " windowId=" + safeWindowIdForControlLog(windowId)
                        + " reason=" + safeLogToken(reason)
                        + " bodyLength=" + recentActiveSwitchProjectionBodyLength
                        + " rowCount=" + recentActiveSwitchProjectionRowCount);
    }

    private boolean recentActiveSwitchProjectionUsableFor(String windowId) {
        boolean hasAcceptedBody = recentActiveSwitchProjectionBodyLength > 0
                && recentActiveSwitchProjectionRowCount > 0;
        if (!hasStableWindowId(windowId)
                || !windowId.equals(recentActiveSwitchProjectionWindowId)
                || !windowId.equals(recentActiveSwitchProjectionFrameWindowId)
                || recentActiveSwitchProjectionFrameHash == null
                || recentActiveSwitchProjectionFrameHash.trim().isEmpty()
                || !hasAcceptedBody) {
            return false;
        }
        long ageMs = SystemClock.elapsedRealtime() - recentActiveSwitchProjectionAtMs;
        if (ageMs < 0 || ageMs > ACTIVE_SWITCH_RECENT_PROJECTION_MAX_AGE_MS) {
            return false;
        }
        return windowId.equals(lastAcceptedCaptureRendererFrameWindowId)
                && recentActiveSwitchProjectionFrameHash.equals(
                        lastAcceptedCaptureRendererFrameHash
                )
                && lastAcceptedCaptureRendererRows.size()
                == recentActiveSwitchProjectionRowCount;
    }

    private boolean paintRecentActiveSwitchProjection(String windowId, String reason) {
        if (!recentActiveSwitchProjectionUsableFor(windowId)
                || !windowId.equals(confirmedVisibleTerminalTargetKey())
                || webView == null) {
            return false;
        }
        // WHY: this is a display-only compositor pulse for already accepted
        // stable @windowId pixels, not title/session/Send/Close authority.
        webView.invalidate();
        commitCaptureRendererVisualFrame("recent-active-switch-" + reason);
        Log.i(CONTROL_LOG_TAG,
                "stage=active-switch-projection endpoint=renderer result=recent-projection-painted"
                        + " windowId=" + safeWindowIdForControlLog(windowId)
                        + " reason=" + safeLogToken(reason)
                        + " ageMs=" + Math.max(
                                0,
                                SystemClock.elapsedRealtime() - recentActiveSwitchProjectionAtMs
                        ));
        return true;
    }

    private RecentActiveSwitchProjectionSnapshot recentActiveSwitchProjectionSnapshot() {
        return new RecentActiveSwitchProjectionSnapshot(
                recentActiveSwitchProjectionWindowId,
                recentActiveSwitchProjectionFrameWindowId,
                recentActiveSwitchProjectionFrameHash,
                recentActiveSwitchProjectionBodyLength,
                recentActiveSwitchProjectionRowCount,
                recentActiveSwitchProjectionAtMs,
                recentActiveSwitchProjectionRows,
                recentActiveSwitchProjectionPaintRows,
                lastAcceptedCaptureRendererHasMoreBefore,
                lastAcceptedCaptureRendererCopyModeViewport,
                lastAcceptedCaptureRendererScrollPosition,
                lastAcceptedCaptureRendererHistorySize,
                lastAcceptedCaptureRendererPaneInMode,
                lastAcceptedCaptureRendererCols
        );
    }

    private void restoreRecentActiveSwitchProjectionSnapshot(
            RecentActiveSwitchProjectionSnapshot snapshot,
            String reason
    ) {
        RecentActiveSwitchProjectionSnapshot rollbackSnapshot = snapshot;
        if (rollbackSnapshot == null || !hasStableWindowId(rollbackSnapshot.windowId)) {
            clearRecentActiveSwitchProjection(reason + "-missing-rollback");
            return;
        }
        recentActiveSwitchProjectionWindowId = snapshot.windowId;
        recentActiveSwitchProjectionFrameWindowId = snapshot.frameWindowId;
        recentActiveSwitchProjectionFrameHash = snapshot.frameHash;
        recentActiveSwitchProjectionBodyLength = snapshot.bodyLength;
        recentActiveSwitchProjectionRowCount = snapshot.rowCount;
        recentActiveSwitchProjectionAtMs = snapshot.acceptedAtMs;
        recentActiveSwitchProjectionRows.clear();
        recentActiveSwitchProjectionRows.addAll(snapshot.rows);
        recentActiveSwitchProjectionPaintRows.clear();
        recentActiveSwitchProjectionPaintRows.addAll(snapshot.paintRows);
        // WHY: rollback reinstates only copied display state for the same stable
        // @windowId. It is not title/session/Send/Close authority.
        lastAcceptedCaptureRendererFrameWindowId = snapshot.frameWindowId;
        lastAcceptedCaptureRendererFrameHash = snapshot.frameHash;
        lastAcceptedCaptureRendererRows.clear();
        lastAcceptedCaptureRendererRows.addAll(snapshot.rows);
        lastAcceptedCaptureRendererPaintRows.clear();
        lastAcceptedCaptureRendererPaintRows.addAll(snapshot.paintRows);
        lastAcceptedCaptureRendererHasMoreBefore = snapshot.hasMoreBefore;
        lastAcceptedCaptureRendererCopyModeViewport = snapshot.copyModeViewport;
        lastAcceptedCaptureRendererScrollPosition = snapshot.scrollPosition;
        lastAcceptedCaptureRendererHistorySize = snapshot.historySize;
        lastAcceptedCaptureRendererPaneInMode = snapshot.paneInMode;
        lastAcceptedCaptureRendererCols = snapshot.cols;
        Log.i(CONTROL_LOG_TAG,
                "stage=active-switch-projection endpoint=renderer result=recent-projection-rollback"
                        + " windowId=" + safeWindowIdForControlLog(snapshot.windowId)
                        + " reason=" + safeLogToken(reason));
        paintRecentActiveSwitchProjection(snapshot.windowId, reason + "-rollback");
    }

    private void clearRecentActiveSwitchProjection(String reason) {
        recentActiveSwitchProjectionWindowId = "";
        recentActiveSwitchProjectionFrameWindowId = "";
        recentActiveSwitchProjectionFrameHash = "";
        recentActiveSwitchProjectionBodyLength = 0;
        recentActiveSwitchProjectionRowCount = 0;
        recentActiveSwitchProjectionAtMs = 0;
        recentActiveSwitchProjectionRows.clear();
        recentActiveSwitchProjectionPaintRows.clear();
        Log.i(CONTROL_LOG_TAG,
                "stage=active-switch-projection endpoint=renderer result=recent-projection-cleared"
                        + " reason=" + safeLogToken(reason));
    }

    private void refreshActiveSessionsDialogIfShowing(String reason) {
        if (activeSessionsDialog == null || !activeSessionsDialog.isShowing()) {
            return;
        }
        long requestGeneration = beginActiveSessionsDialogRefresh(reason);
        if (requestGeneration <= 0L) {
            return;
        }
        long responseRevision = activeSessionsDataRevision;
        String visibleWindowId = visibleTerminalTargetKey();
        // WHY: the installed APK can be foregrounded with an old Active dialog
        // already open. Reopening Active was refreshing `/tabs?light=1`, but the
        // still-open dialog kept showing stale rows until the user manually
        // closed it. The picker already has useful rows, so reconciliation is one
        // direct light request only. A stale/error response must keep last-good
        // pixels and schedule the next light poll; clearing cache, falling back
        // to full /tabs, or retrying bases creates the exact timeout storm that
        // starved terminal streaming on the physical phone.
        Log.i(CONTROL_LOG_TAG,
                "stage=control-local control=active-sessions result=resume-refresh-start"
                        + " reason=" + safeLogToken(reason));
        getJsonDirectOnce("/tabs?light=1", payload -> {
            if (!activeSessionsDialogRefreshOwned(requestGeneration)) {
                return;
            }
            try {
                if (!activeSessionsResponseRevisionCurrent(
                        responseRevision,
                        reason + "-tabs-light"
                )) {
                    finishActiveSessionsDialogRefresh(
                            requestGeneration,
                            "stale-" + reason
                    );
                    return;
                }
                String rejectReason = activeSessionsPayloadRejectReason(payload);
                boolean exactVisibleTarget = hasStableWindowId(visibleWindowId)
                        && activeSessionsPayloadHasExactlyOneActiveWindow(
                                payload,
                                visibleWindowId
                        );
                // WHY(active-switch @94 always-listed 2026-07-27): a fresh /tabs?light
                // payload with rows must always repaint the open Active picker so a
                // switched-to session appears immediately. Only a genuinely rejected/empty
                // payload (rejectReason non-empty) keeps last-good pixels here;
                // exactVisibleTarget no longer discards a good payload — it gates only
                // cache/title/active-row promotion below.
                if (!rejectReason.isEmpty()) {
                    if (showBoundedStaleActiveSessionsDialog(
                            payload,
                            true,
                            visibleWindowId,
                            currentApkActionIdForLog(),
                            currentApkTapIdForLog(),
                            0,
                            responseRevision,
                            reason + "-tabs-light-display"
                    )) {
                        finishActiveSessionsDialogRefresh(
                                requestGeneration,
                                "bounded-stale-" + reason
                        );
                        return;
                    }
                    finishActiveSessionsDialogRefresh(
                            requestGeneration,
                            "kept-" + reason
                    );
                    Log.i(CONTROL_LOG_TAG,
                            "stage=control-local control=active-sessions"
                                    + " result=resume-refresh-kept-last-good"
                                    + " reason=" + safeLogToken(reason)
                                    + " rejectReason=" + safeLogToken(rejectReason)
                                    + " windowId=" + safeWindowIdForControlLog(visibleWindowId));
                    return;
                }
                // WHY: exactVisibleTarget gates only cache promotion + active-row/title
                // trust (rememberActiveSessionsPayload is the last-good authority). An
                // unproven-but-non-rejected payload still renders its rows display-only
                // below, just without becoming cached authority.
                if (exactVisibleTarget) {
                    rememberActiveSessionsPayload(payload, reason + "-tabs-light");
                }
                refreshActiveSessionsDialogPayloadIfShowing(payload, reason + "-tabs-light");
                if (exactVisibleTarget) {
                    // The current live response has replaced any bounded
                    // retained/recent projection in the visible dialog. Cancel
                    // its captured expiry generation so it cannot dismiss fresh
                    // rows after a successful in-place refresh.
                    clearRecentActiveSessionsDialogProjection(
                            reason + "-live-payload-replaced"
                    );
                }
                finishActiveSessionsDialogRefresh(
                        requestGeneration,
                        "payload-" + reason
                );
            } finally {
                finishActiveSessionsDialogRefresh(
                        requestGeneration,
                        "callback-finally-" + reason
                );
            }
        }, exc -> {
            if (!activeSessionsDialogRefreshOwned(requestGeneration)) {
                return;
            }
            try {
                if (!activeSessionsResponseRevisionCurrent(
                        responseRevision,
                        reason + "-tabs-light-failed"
                )) {
                    finishActiveSessionsDialogRefresh(
                            requestGeneration,
                            "stale-failed-" + reason
                    );
                    return;
                }
                finishActiveSessionsDialogRefresh(
                        requestGeneration,
                        "failed-" + reason
                );
                Log.w(CONTROL_LOG_TAG,
                        "stage=control-local control=active-sessions"
                                + " result=resume-refresh-kept-last-good"
                                + " reason=" + safeLogToken(reason),
                        exc);
            } finally {
                finishActiveSessionsDialogRefresh(
                        requestGeneration,
                        "failure-finally-" + reason
                );
            }
        });
    }

    private long beginActiveSessionsDialogRefresh(String reason) {
        if (activeSessionsDialog == null
                || !activeSessionsDialog.isShowing()
                || activeSessionsDisplayPrewarmInFlight
                || activeSessionsDialogRefreshInFlight) {
            if (activeSessionsDialog != null
                    && activeSessionsDialog.isShowing()) {
                scheduleActiveSessionsDialogLiveRefresh(
                        "coalesced-" + reason
                );
            }
            return 0L;
        }
        long requestGeneration = ++activeSessionsDialogRefreshGeneration;
        activeSessionsDialogRefreshInFlight = true;
        return requestGeneration;
    }

    private boolean activeSessionsDialogRefreshOwned(long requestGeneration) {
        return requestGeneration > 0L
                && activeSessionsDialogRefreshInFlight
                && requestGeneration == activeSessionsDialogRefreshGeneration;
    }

    private boolean finishActiveSessionsDialogRefresh(
            long requestGeneration,
            String reason
    ) {
        if (!activeSessionsDialogRefreshOwned(requestGeneration)) {
            return false;
        }
        // WHY: prewarm, resume, and the live timer can finish out of order.
        // Only the generation that claimed this singleflight may release it;
        // an old callback must never clear or reschedule a newer request.
        activeSessionsDialogRefreshInFlight = false;
        scheduleActiveSessionsDialogLiveRefresh(reason);
        return true;
    }

    private void refreshActiveSessionsDialogPayloadIfShowing(JSONObject payload, String reason) {
        if (activeSessionsDialog == null || !activeSessionsDialog.isShowing()) {
            return;
        }
        try {
            refreshActiveSessionsDialog(payload, "Active Sessions");
            Log.i(CONTROL_LOG_TAG,
                    "stage=control-local control=active-sessions result=next-open-cache-ready"
                            + " reason=" + safeLogToken(reason)
                            + " rows=" + activeSessionsPayloadRowCount(payload));
        } catch (Exception exc) {
            Log.w(CONTROL_LOG_TAG,
                    "stage=control-local control=active-sessions result=resume-refresh-render-failed"
                            + " reason=" + safeLogToken(reason),
                    exc);
        }
    }

    private void scheduleActiveSessionsDialogLiveRefresh(String reason) {
        if (activeSessionsDialog == null || !activeSessionsDialog.isShowing() || !activityResumed) {
            return;
        }
        long generation = ++activeSessionsDialogRefreshScheduleGeneration;
        uiHandler.postDelayed(() -> {
            if (generation != activeSessionsDialogRefreshScheduleGeneration
                    || activeSessionsDialog == null
                    || !activeSessionsDialog.isShowing()
                    || !activityResumed
                    || sessionSwitchInFlight
                    || activeSessionsDisplayPrewarmInFlight
                    || activeSessionsDialogRefreshInFlight) {
                return;
            }
            refreshActiveSessionsDialogIfShowing("visible-live");
        }, ACTIVE_SESSIONS_DIALOG_LIVE_REFRESH_MS);
        Log.i(CONTROL_LOG_TAG,
                "stage=control-local control=active-sessions result=live-refresh-scheduled"
                        + " reason=" + safeLogToken(reason)
                        + " delayMs=" + ACTIVE_SESSIONS_DIALOG_LIVE_REFRESH_MS);
    }

    private void stopActiveSessionsDialogLiveRefresh(String reason) {
        activeSessionsDialogRefreshScheduleGeneration++;
        activeSessionsDialogRefreshGeneration++;
        activeSessionsDialogRefreshInFlight = false;
        Log.i(CONTROL_LOG_TAG,
                "stage=control-local control=active-sessions result=live-refresh-stopped"
                        + " reason=" + safeLogToken(reason));
    }

    private int activeSessionsPayloadRowCount(JSONObject payload) {
        if (payload == null) {
            return 0;
        }
        JSONArray tabs = payload.optJSONArray("tabs");
        if (tabs != null) {
            return tabs.length();
        }
        JSONArray windows = payload.optJSONArray("displayWindows");
        if (windows == null) {
            windows = payload.optJSONArray("topWindows");
        }
        if (windows == null) {
            windows = payload.optJSONArray("windows");
        }
        return windows == null ? 0 : windows.length();
    }

    private String activeSessionsPayloadRejectReason(JSONObject payload) {
        if (payload == null) {
            return "empty-payload";
        }
        if (payload.optBoolean("snapshotEmergency", false)) {
            return "snapshot-emergency";
        }
        String snapshotSource = payload.optString("snapshotSource", "").trim().toLowerCase(Locale.US);
        if (snapshotSource.contains("stale")) {
            if (activeSessionsValidatedStalePayloadUsable(payload)) {
                return "";
            }
            return "snapshot-source-stale";
        }
        if (snapshotSource.contains("emergency")) {
            return "snapshot-source-emergency";
        }
        return "";
    }

    private boolean activeSessionsValidatedStalePayloadUsable(JSONObject payload) {
        if (payload == null) {
            return false;
        }
        if (payload.optBoolean("snapshotEmergency", false)) {
            return false;
        }
        if (payload.optBoolean("snapshotActiveValidationSkipped", false)) {
            // WHY: server stale light-tabs rows are safe for the instant picker
            // only after the control server has checked that the snapshot still
            // matches the current tmux active row. Title-sync pressure can skip
            // that validation to keep `/active` reachable; Android must not turn
            // that diagnostic fallback into clickable session authority, or the
            // old dead-row/wrong-title Active Sessions regression comes back.
            return false;
        }
        if (activeSessionsPayloadRowCount(payload) <= 0) {
            return false;
        }
        String activeWindowId = payload.optString("activeWindowId", "");
        if (!hasStableWindowId(activeWindowId)) {
            return false;
        }
        long ageMs = payload.optLong("snapshotAgeMs", Long.MAX_VALUE);
        if (ageMs < 0 || ageMs > ACTIVE_SESSIONS_VALIDATED_STALE_MAX_AGE_MS) {
            // WHY: accepting validated stale rows is a latency fast path, not a
            // persistent offline cache. Keeping a hard freshness cap prevents a
            // revived APK or restored phone from opening a long-dead picker just
            // because `/tabs` is slow, while still letting a human tap render
            // immediately during short control-server/title-sync pressure bursts.
            return false;
        }
        return true;
    }

    private boolean rejectActiveSessionsPayloadIfUnstable(JSONObject payload, String reason) {
        String rejectReason = activeSessionsPayloadRejectReason(payload);
        if (rejectReason.isEmpty()) {
            return false;
        }
        clearActiveSessionsCache(reason + "-" + rejectReason);
        String snapshotSource = payload == null ? "" : payload.optString("snapshotSource", "");
        Log.w(CONTROL_LOG_TAG,
                "stage=control-local control=active-sessions result=payload-rejected"
                        + " reason=" + safeLogToken(reason)
                        + " rejectReason=" + safeLogToken(rejectReason)
                        + " snapshotSource=" + safeLogToken(snapshotSource));
        return true;
    }

    private void clearActiveSessionsCacheAfterSessionChangingOpen(String reason) {
        String normalized = reason == null ? "" : reason.trim().toLowerCase(Locale.US);
        if (normalized.startsWith("new-session")
                || normalized.startsWith("old-session")
                || normalized.startsWith("crashed-session")
                || normalized.startsWith("workspace-restore")) {
            // WHY: session-changing opens can create or select a different live
            // row. Reusing the pre-open Active table makes Active -> Old -> Active
            // show old central titles/status colors before the fresh repaint.
            clearActiveSessionsCache(reason + "-opened");
        }
    }

    private void clearActiveSessionsCache(String reason) {
        long ageMs = cachedActiveSessionsPayload == null
                ? -1
                : Math.max(0, SystemClock.elapsedRealtime() - cachedActiveSessionsPayloadAtMs);
        cachedActiveSessionsPayload = null;
        cachedActiveSessionsPayloadAtMs = 0;
        Log.i(CONTROL_LOG_TAG,
                "stage=control-local control=active-sessions result=cache-cleared"
                        + " reason=" + safeLogToken(reason)
                        + " cacheAgeMs=" + ageMs);
    }

    private void refreshActiveSessionsDialog(JSONObject payload, String title) throws Exception {
        // WHY(active interaction snapshot): after the first rendered frame, every
        // visible row is one user-owned transaction binding title/status/Close UI
        // to an immutable stable @windowId selection closure. Rebuilding this
        // LinearLayout from a background /tabs response changes row order, height,
        // scroll geometry, Close metadata, and the closure under the next DOWN. The
        // physical v289 busy-list run proved the pre-touch hole: the refresh began
        // before ACTION_DOWN, moved @49 into the intended @9 coordinate, and the
        // wrong stable row was correctly selected 2935ms later. A touch-quiet delay
        // cannot repair a refresh that commits before touch; removeAllViews also
        // discards Android view identity entirely. Keep the drawn picker immutable.
        // Live responses still ingest the one canonical title envelope and refresh
        // the retained/next-open cache; /select-live and Close independently
        // revalidate stable identity server-side. Reopen is the atomic publication
        // boundary for new titles, colors, membership, and order.
        if (activeSessionsDialog != null
                && activeSessionsDialog.isShowing()
                && activeSessionsDialogList != null
                && activeSessionsDialogRef != null
                && activeSessionsDialogCloseTargets != null) {
            Log.i(CONTROL_LOG_TAG,
                    "stage=control-local control=active-sessions"
                            + " result=visible-interaction-snapshot-frozen"
                            + " rows=" + activeSessionsPayloadRowCount(payload));
            return;
        }
        showActiveSessionsDialog(payload, title, true);
    }

    private boolean shouldDeferActiveSessionsDialogRefreshForTouch(String title) {
        if (!"Active Sessions".equals(title) || activeSessionsDialogTouchedAtMs <= 0) {
            return false;
        }
        long ageMs = SystemClock.elapsedRealtime() - activeSessionsDialogTouchedAtMs;
        boolean defer = ageMs >= 0 && ageMs < ACTIVE_SESSIONS_DIALOG_TOUCH_QUIET_MS;
        if (defer) {
            Log.i(CONTROL_LOG_TAG,
                    "stage=control-local control=active-sessions result=refresh-deferred"
                            + " reason=touch-quiet"
                            + " ageMs=" + ageMs);
        }
        return defer;
    }

    private boolean markActiveSessionsDialogTouch(MotionEvent event) {
        if (event == null) {
            return false;
        }
        int action = event.getActionMasked();
        if (action == MotionEvent.ACTION_DOWN
                || action == MotionEvent.ACTION_MOVE
                || action == MotionEvent.ACTION_UP) {
            activeSessionsDialogTouchedAtMs = SystemClock.elapsedRealtime();
        }
        return false;
    }

    private void showOldSessions() {
        hideDockedPromptComposerForNavigation("old-dialog");
        // WHY: Old Sessions is a saved-session picker, not a live-session scan.
        // Keep APK Old on the same `/sessions?oldOnly=1` contract as the web
        // remote so Android cannot drift into showing live rows or stale
        // process-name titles when the broad `/sessions` payload changes.
        getJsonWithRetry("/sessions?oldOnly=1", payload -> {
            showOldSessionsDialog(payload);
        }, exc -> {
            toast("Mantis Control is not reachable");
        }
        );
    }

    private void showWorkspaces() {
        hideDockedPromptComposerForNavigation("workspace-dialog");
        // WHY: the phone Workspace button must be the same user-facing restore
        // surface as desktop `[Workspace]` and `/web`, not a backend-only command.
        // The control server owns snapshot recommendation so Android cannot drift
        // into loading a reduced post-restart `last.json`.
        getJsonWithRetry("/workspace-list?limit=40", this::showWorkspaceDialog, exc ->
                toast("Mantis Control is not reachable")
        );
    }

    private void showCrashedSessions() {
        hideDockedPromptComposerForNavigation("crashed-dialog");
        getJsonWithRetry("/crashed-sessions", this::showCrashedSessionsDialog, exc ->
                toast("Mantis Control is not reachable")
        );
    }

    private void showNeedsAttention() {
        hideDockedPromptComposerForNavigation("needs-attention-dialog");
        getJsonWithRetry("/needs-attention", payload -> showActiveSessionsDialog(payload, "Needs Attention", false));
    }

    private void showCodexAccountSettings() {
        hideDockedPromptComposerForNavigation("codex-account-dialog");
        beginApkAction("settings-account", visibleTerminalTargetKey());
        markApkFirstLocalFeedback("settings-account-local-shell", visibleTerminalTargetKey());
        JSONObject localPayload = new JSONObject();
        try {
            localPayload.put("state", "checking_auth");
            localPayload.put("running", true);
            localPayload.put("progressPercent", 1);
            localPayload.put("progressLabel", "opening");
            localPayload.put("loadingMessage", "Checking current account");
            showCodexAccountDialog(localPayload);
            markApkFirstPaint("codex-account-dialog", "local-shell");
        } catch (Exception exc) {
            toast("Codex account failed: " + exc.getMessage());
        }
        getJsonWithRetry("/account-switch-status", payload -> {
            try {
                if (codexAccountDialog != null && codexAccountDialog.isShowing()) {
                    renderCodexAccountDialogPayload(payload);
                    scheduleCodexAccountStatusPoll(payload, "codex-account-status-refresh");
                } else {
                    showCodexAccountDialog(payload);
                }
            } catch (Exception exc) {
                toast("Codex account failed: " + exc.getMessage());
            }
        }, exc -> toast("Mantis Control is not reachable"));
    }

    private void showCodexAccountDialog(JSONObject payload) throws Exception {
        ScrollView scrollView = new ScrollView(this);
        scrollView.setFocusable(false);
        scrollView.setFillViewport(false);

        LinearLayout list = new LinearLayout(this);
        list.setOrientation(LinearLayout.VERTICAL);
        list.setFocusable(false);
        list.setPadding(dp(8), dp(6), dp(8), dp(10));
        scrollView.addView(list);

        final AlertDialog[] dialogRef = new AlertDialog[1];
        populateCodexAccountDialogList(list, payload, dialogRef);

        AlertDialog dialog = new AlertDialog.Builder(this)
                .setView(premiumDialogShell("Codex account", codexAccountDialogSubtitle(payload), scrollView))
                .show();
        dialogRef[0] = dialog;
        codexAccountDialog = dialog;
        codexAccountDialogList = list;
        codexAccountDialogRef = dialogRef;
        stylePremiumDialogWindow(dialog);
        dialog.setOnDismissListener(dismissed -> stopCodexAccountStatusPoll("codex-account-dismiss"));
        scrollView.post(() -> scrollView.scrollTo(0, 0));
        scheduleCodexAccountStatusPoll(payload, "codex-account-show");
    }

    private void populateCodexAccountDialogList(LinearLayout list, JSONObject payload, AlertDialog[] dialogRef) {
        list.removeAllViews();
        addSectionHeader(list, "Current Codex account", 0);
        list.addView(codexAccountText(codexAccountStatusText(payload), 13, Color.rgb(224, 230, 246)));

        if (codexDeviceAuthAvailable(payload)) {
            String target = codexDisplayText(payload.optString("targetLabel", ""), payload.optString("targetEmail", ""));
            addSectionHeader(list, "Login code", 0);
            list.addView(codexAccountActionButton(
                    target.isEmpty() ? "Show Codex login code" : "Show login code for " + target,
                    view -> startCodexAccountDeviceCode(payload.optString("targetEmail", ""), payload.optString("targetLabel", ""), dialogRef)
            ));
        }

        JSONObject device = codexDevice(payload);
        if (device.length() > 0) {
            addSectionHeader(list, "Device sign-in", 0);
            String code = device.optString("code", "");
            String expiresAt = device.optString("expiresAt", "");
            StringBuilder codeText = new StringBuilder();
            codeText.append(code.isEmpty() ? "Open the sign-in page and finish the prompt on the phone." : "Code: " + code);
            if (!expiresAt.isEmpty()) {
                codeText.append("\nExpires: ").append(expiresAt);
            }
            // WHY: the one-time code is volatile UI only. It is shown here and may
            // be copied to Android's clipboard, but this APK never writes it to
            // SharedPreferences, logs, plan receipts, or account presets.
            list.addView(codexAccountText(codeText.toString(), 16, Color.rgb(246, 230, 181)));
            if (!device.optString("url", "").isEmpty()) {
                list.addView(codexAccountActionButton("Open sign-in page", view -> openCodexDeviceAuth(device)));
            }
            if (!code.isEmpty()) {
                list.addView(codexAccountActionButton("Copy one-time code", view -> copyCodexDeviceCode(device)));
            }
        }

        JSONArray hints = payload.optJSONArray("accountHints");
        int hintCount = hints == null ? 0 : hints.length();
        addSectionHeader(list, "Saved accounts", hintCount);
        if (hintCount == 0) {
            list.addView(codexAccountText("No account aliases are configured on this host. You can still sign in with any Codex account.", 13, Color.rgb(174, 181, 205)));
        } else {
            for (int index = 0; index < hintCount; index++) {
                JSONObject hint = hints.optJSONObject(index);
                if (hint == null) {
                    continue;
                }
                String label = codexDisplayText(hint.optString("label", ""), hint.optString("email", ""));
                String email = hint.optString("email", "");
                list.addView(codexAccountActionButton(
                        "Switch to " + label,
                        view -> startCodexAccountSwitch(email, label, dialogRef)
                ));
                // WHY: saved aliases are not reusable credentials. Keep the
                // protected no-device Switch path above so central blocker/repair
                // state stays visible, and expose the explicit per-alias code path
                // beside it so account changes do not look refused in Settings.
                list.addView(codexAccountActionButton(
                        "Show login code for " + label,
                        view -> startCodexAccountDeviceCode(email, label, dialogRef)
                ));
            }
        }

        addSectionHeader(list, "Actions", 0);
        list.addView(codexAccountActionButton(
                codexCurrentAuthenticated(payload) ? "Show login code for another account" : "Show Codex login code",
                view -> startCodexAccountDeviceCode("", "", dialogRef)
        ));
        list.addView(codexAccountActionButton("Refresh status", view -> refreshCodexAccountDialog(dialogRef)));
        list.addView(codexAccountActionButton("Repair signed-in sessions", view -> repairCodexAccountSwitch(dialogRef)));
        if (payload.optBoolean("running", false)) {
            list.addView(codexAccountActionButton("Cancel switch", view -> cancelCodexAccountSwitch(dialogRef)));
        }
    }

    private TextView codexAccountText(String text, int sizeSp, int color) {
        TextView view = new TextView(this);
        view.setText(text);
        view.setTextSize(sizeSp);
        view.setTextColor(color);
        view.setTypeface(Typeface.create("sans-serif", Typeface.NORMAL));
        view.setSingleLine(false);
        view.setIncludeFontPadding(true);
        view.setPadding(dp(10), dp(8), dp(10), dp(8));
        view.setBackground(roundedFill(Color.rgb(28, 31, 42), 6, Color.rgb(62, 68, 91)));
        LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(
                LinearLayout.LayoutParams.MATCH_PARENT,
                LinearLayout.LayoutParams.WRAP_CONTENT
        );
        params.setMargins(0, dp(3), 0, dp(8));
        view.setLayoutParams(params);
        return view;
    }

    private Button codexAccountActionButton(String label, View.OnClickListener listener) {
        Button action = new Button(this);
        action.setText(label);
        action.setAllCaps(false);
        action.setTextSize(13);
        action.setSingleLine(false);
        action.setMaxLines(3);
        action.setTypeface(Typeface.create("sans-serif-medium", Typeface.NORMAL));
        action.setTextColor(Color.rgb(228, 233, 249));
        action.setGravity(android.view.Gravity.CENTER);
        action.setPadding(dp(8), 0, dp(8), 0);
        setTouchableBackground(action, Color.rgb(38, 41, 55), Color.rgb(137, 180, 250));
        action.setOnClickListener(v -> {
            flashTap(v);
            listener.onClick(v);
        });
        LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(
                LinearLayout.LayoutParams.MATCH_PARENT,
                dp(50)
        );
        params.setMargins(0, dp(3), 0, dp(6));
        action.setLayoutParams(params);
        return action;
    }

    private String codexAccountDialogSubtitle(JSONObject payload) {
        String label = payload.optString("progressLabel", payload.optString("state", "idle"));
        int progress = Math.max(0, Math.min(100, payload.optInt("progressPercent", 0)));
        if (payload.optBoolean("ready", false)) {
            return "Ready - 100%";
        }
        if (!label.isEmpty()) {
            return label + " - " + progress + "%";
        }
        return payload.optString("state", "idle");
    }

    private boolean codexAccountShouldPoll(JSONObject payload) {
        String state = payload.optString("state", "idle");
        if (payload.optBoolean("ready", false)
                || "idle".equals(state)
                || "complete".equals(state)
                || "failed".equals(state)
                || "cancelled".equals(state)
                || "expired".equals(state)
                || state.startsWith("blocked")) {
            return false;
        }
        return payload.optBoolean("running", false)
                || "starting".equals(state)
                || "waiting_for_user".equals(state)
                || "verifying".equals(state)
                || "checking_auth".equals(state)
                || "repairing_sessions".equals(state)
                || payload.optLong("nextPollMs", 0) > 0;
    }

    private long codexAccountPollDelayMs(JSONObject payload) {
        long nextPoll = payload.optLong("nextPollMs", CODEX_ACCOUNT_STATUS_POLL_MS);
        if (nextPoll <= 0) {
            nextPoll = CODEX_ACCOUNT_STATUS_POLL_MS;
        }
        return Math.max(750, Math.min(5000, nextPoll));
    }

    private void scheduleCodexAccountStatusPoll(JSONObject payload, String reason) {
        if (!codexAccountShouldPoll(payload)) {
            return;
        }
        final long generation = ++codexAccountStatusPollGeneration;
        final long delayMs = codexAccountPollDelayMs(payload);
        uiHandler.postDelayed(() -> {
            if (generation != codexAccountStatusPollGeneration
                    || !activityResumed
                    || codexAccountDialog == null
                    || !codexAccountDialog.isShowing()) {
                return;
            }
            if (codexAccountStatusPollInFlight) {
                scheduleCodexAccountStatusPoll(payload, "codex-account-poll-in-flight");
                return;
            }
            codexAccountStatusPollInFlight = true;
            getJsonWithRetry("/account-switch-status", updated -> {
                codexAccountStatusPollInFlight = false;
                if (generation != codexAccountStatusPollGeneration
                        || codexAccountDialog == null
                        || !codexAccountDialog.isShowing()) {
                    return;
                }
                renderCodexAccountDialogPayload(updated);
                scheduleCodexAccountStatusPoll(updated, "codex-account-poll-success");
            }, exc -> {
                codexAccountStatusPollInFlight = false;
                if (generation == codexAccountStatusPollGeneration
                        && codexAccountDialog != null
                        && codexAccountDialog.isShowing()) {
                    scheduleCodexAccountStatusPoll(payload, "codex-account-poll-error");
                }
            });
        }, delayMs);
    }

    private void stopCodexAccountStatusPoll(String reason) {
        codexAccountStatusPollGeneration++;
        codexAccountStatusPollInFlight = false;
        if (codexAccountDialog == null || !codexAccountDialog.isShowing()) {
            codexAccountDialog = null;
            codexAccountDialogList = null;
            codexAccountDialogRef = null;
        }
    }

    private void renderCodexAccountDialogPayload(JSONObject payload) {
        if (codexAccountDialogList == null || codexAccountDialogRef == null) {
            return;
        }
        populateCodexAccountDialogList(codexAccountDialogList, payload, codexAccountDialogRef);
    }

    private String codexAccountStatusText(JSONObject payload) {
        JSONObject current = payload.optJSONObject("currentAccount");
        String state = payload.optString("state", "idle");
        String message = payload.optString("message", "");
        String target = codexDisplayText(payload.optString("targetLabel", ""), payload.optString("targetEmail", ""));
        int progress = Math.max(0, Math.min(100, payload.optInt("progressPercent", 0)));
        String progressLabel = payload.optString("progressLabel", "");
        String loadingMessage = payload.optString("loadingMessage", "");
        boolean ready = payload.optBoolean("ready", false);
        String readyMessage = payload.optString("readyMessage", "");
        JSONObject repairSummary = payload.optJSONObject("sessionRepairSummary");
        StringBuilder builder = new StringBuilder();
        builder.append("Current: ").append(codexCurrentAccountLine(current));
        builder.append("\nSwitch state: ").append(state);
        builder.append("\nProgress: ").append(progress).append("%");
        if (!progressLabel.isEmpty()) {
            builder.append(" - ").append(progressLabel);
        }
        if (!target.isEmpty()) {
            builder.append("\nTarget: ").append(target);
        }
        if (ready) {
            builder.append("\nReady: ").append(readyMessage.isEmpty() ? "OAuth repaired; sessions ready." : readyMessage);
        } else if (!loadingMessage.isEmpty()) {
            builder.append("\nLoading: ").append(loadingMessage);
        }
        if (repairSummary != null && repairSummary.optBoolean("available", false)) {
            String repairMessage = repairSummary.optString("message", "");
            builder.append("\nSessions: ").append(repairMessage.isEmpty() ? "checking repair status" : repairMessage);
            builder.append("\nRepaired: ").append(repairSummary.optInt("repairedCount", 0))
                    .append(" Retargeted: ").append(repairSummary.optInt("retargetedCount", 0))
                    .append(" Closed: ").append(repairSummary.optInt("closedOriginals", 0));
        }
        if (!message.isEmpty()) {
            builder.append("\n").append(message);
        }
        return builder.toString();
    }

    private String codexCurrentAccountLine(JSONObject current) {
        if (current == null || !current.optBoolean("authenticated", false)) {
            return "not signed in";
        }
        return codexDisplayText(current.optString("name", ""), current.optString("email", ""));
    }

    private boolean codexCurrentAuthenticated(JSONObject payload) {
        JSONObject current = payload == null ? null : payload.optJSONObject("currentAccount");
        return current != null && current.optBoolean("authenticated", false);
    }

    private String codexDisplayText(String label, String email) {
        String cleanLabel = label == null ? "" : label.trim();
        String cleanEmail = email == null ? "" : email.trim();
        if (!cleanLabel.isEmpty() && !cleanEmail.isEmpty() && !cleanLabel.equals(cleanEmail)) {
            return cleanLabel + " (" + cleanEmail + ")";
        }
        if (!cleanLabel.isEmpty()) {
            return cleanLabel;
        }
        return cleanEmail;
    }

    private JSONObject codexDevice(JSONObject payload) {
        JSONObject device = payload.optJSONObject("device");
        return device == null ? new JSONObject() : device;
    }

    private boolean codexDeviceAuthAvailable(JSONObject payload) {
        return payload != null
                && payload.optBoolean("deviceAuthAvailable", false)
                && "explicit-code-login".equals(payload.optString("deviceAuthAction", ""));
    }

    private void startCodexAccountSwitch(String email, String label, AlertDialog[] dialogRef) {
        confirmCodexAccountSwitch(email, label, dialogRef);
    }

    private void startCodexAccountDeviceCode(String email, String label, AlertDialog[] dialogRef) {
        confirmCodexAccountDeviceCode(email, label, dialogRef);
    }

    private void confirmCodexAccountSwitch(String email, String label, AlertDialog[] dialogRef) {
        String display = codexDisplayText(label, email);
        if (display.isEmpty()) {
            display = "Codex";
        }
        new AlertDialog.Builder(this)
                .setTitle("Start Codex sign-in?")
                .setMessage(
                        "This can trigger Google or OpenAI verification for " + display + ". "
                                + "Current sessions stay visible, but any stale signed-in panes must be repaired after the new login completes."
                )
                .setPositiveButton("Start switch", (dialog, which) -> startCodexAccountSwitchConfirmed(email, label, dialogRef))
                .setNegativeButton("Cancel", null)
                .show();
    }

    private void confirmCodexAccountDeviceCode(String email, String label, AlertDialog[] dialogRef) {
        String display = codexDisplayText(label, email);
        if (display.isEmpty()) {
            display = "Codex";
        }
        new AlertDialog.Builder(this)
                .setTitle("Show Codex login code?")
                .setMessage(
                        "This starts the OpenAI device-code login for " + display + ". "
                                + "Current sessions stay visible; after sign-in, run Repair signed-in sessions if any pane still shows stale auth."
                )
                .setPositiveButton("Show code", (dialog, which) -> startCodexAccountSwitchConfirmed(email, label, true, dialogRef))
                .setNegativeButton("Cancel", null)
                .show();
    }

    private void startCodexAccountSwitchConfirmed(String email, String label, AlertDialog[] dialogRef) {
        startCodexAccountSwitchConfirmed(email, label, false, dialogRef);
    }

    private void startCodexAccountSwitchConfirmed(String email, String label, boolean allowDeviceAuth, AlertDialog[] dialogRef) {
        String path = "/account-switch-start?targetEmail=" + urlEncode(email)
                + "&targetLabel=" + urlEncode(label);
        if (allowDeviceAuth) {
            // WHY: saved-account buttons intentionally use the central no-device
            // decision path. Code login is a separate explicit user action so the
            // APK never mistakes an alias for reusable saved credentials.
            path += "&allowDeviceAuth=1";
        }
        getJsonWithRetry(path, payload -> {
            if (dialogRef[0] != null) {
                dialogRef[0].dismiss();
            }
            showCodexAccountDialog(payload);
        }, exc -> toast("Mantis Control is not reachable"));
    }

    private void refreshCodexAccountDialog(AlertDialog[] dialogRef) {
        getJsonWithRetry("/account-switch-status", payload -> {
            if (dialogRef[0] != null) {
                dialogRef[0].dismiss();
            }
            showCodexAccountDialog(payload);
        }, exc -> toast("Mantis Control is not reachable"));
    }

    private void cancelCodexAccountSwitch(AlertDialog[] dialogRef) {
        getJsonWithRetry("/account-switch-cancel", payload -> {
            if (dialogRef[0] != null) {
                dialogRef[0].dismiss();
            }
            showCodexAccountDialog(payload);
        }, exc -> toast("Mantis Control is not reachable"));
    }

    private void repairCodexAccountSwitch(AlertDialog[] dialogRef) {
        getJsonWithRetry("/account-switch-repair-auth?yes=1", payload -> {
            if (!payload.optBoolean("ok", false)) {
                toast(payload.optString("error", "Auth repair did not complete"));
                clearActiveSessionsCache("account-switch-repair-auth-failed");
            } else {
                recoverVisibleSessionsAfterAccountRepair(payload);
            }
            refreshCodexAccountDialog(dialogRef);
        }, exc -> toast("Mantis Control is not reachable"));
    }

    private void recoverVisibleSessionsAfterAccountRepair(JSONObject payload) {
        // WHY: account repair is a backend-owned auth/session transaction, but the
        // installed APK may still be pinned to a stale MagicDNS control base, stale
        // Active rows, or the hidden replacement side of an auth-repair alias. Keep
        // this APK side-effect read-only: reconnect to the proven direct 8089 owner,
        // refresh central session data, and rebind the capture renderer to the
        // server's visible alias without starting device auth or closing panes.
        activeControlBaseUrl = CONTROL_URL;
        clearActiveSessionsCache("account-switch-repair-auth");
        String targetKey = visibleTerminalTargetKey();
        if (hasStableWindowId(targetKey)) {
            setCaptureRendererWindowTarget(targetKey, "account-switch-repair-auth");
        }
        forceCaptureRendererVisualCommit("account-switch-repair-auth");
        refreshActiveSessionsDialogIfShowing("account-switch-repair-auth");
        scheduleToolbarStatusDotRefresh(0);
        reconcileActiveSessionAfterAccountRepair("account-switch-repair-auth");
        Log.i(CONTROL_LOG_TAG,
                "stage=account-switch endpoint=/account-switch-repair-auth result=apk-reconnect"
                        + " ok=" + payload.optBoolean("ok", false)
                        + " targetWindowId=" + safeWindowIdForControlLog(targetKey));
    }

    private void reconcileActiveSessionAfterAccountRepair(String reason) {
        getJsonWithRetry("/active?readOnly=1", payload -> {
            JSONObject window = payload.optJSONObject("window");
            if (window == null) {
                return;
            }
            rememberActivePhoneWindow(window, reason);
            if (shouldAdoptAccountRepairActiveWindow(window)) {
                String windowId = window.optString("windowId", "");
                canonicalTitleForPayload(window, reason + "-active-alias");
                rememberSelectedPhoneWindow(
                        window.optInt("index", -1),
                        windowId,
                        canonicalTitleBindingFromPayload(window),
                        reason + "-active-alias"
                );
                Log.i(CONTROL_LOG_TAG,
                        "stage=account-switch endpoint=/active result=apk-retargeted-active-alias"
                                + " displayWindowId=" + safeWindowIdForControlLog(windowId)
                                + " resolvedWindowId=" + safeWindowIdForControlLog(window.optString("resolvedWindowId", ""))
                                + " interactiveTargetWindowId=" + safeWindowIdForControlLog(window.optString("interactiveTargetWindowId", ""))
                                + " retargeted=" + window.optBoolean("retargeted", false));
                return;
            }
            if (activeStatusMatchesVisibleTarget(window)) {
                updateSessionTitleStrip(window);
            } else {
                updateSessionTitleStripFromVisibleRenderer(reason + "-active-mismatch");
            }
        }, exc -> Log.w(CONTROL_LOG_TAG,
                "stage=account-switch endpoint=/active result=apk-retarget-refresh-failed"
                        + " reason=" + safeLogToken(reason),
                exc));
    }

    private boolean shouldAdoptAccountRepairActiveWindow(JSONObject window) {
        if (window == null) {
            return false;
        }
        String displayWindowId = stableWindowIdFromPayload(window, "", "windowId", "displayWindowId", "selectedWindowId");
        if (!hasStableWindowId(displayWindowId)) {
            return false;
        }
        if (!hasStableWindowId(selectedPhoneWindowId)) {
            return true;
        }
        String selectedWindowId = selectedPhoneWindowId.trim();
        if (displayWindowId.equals(selectedWindowId)) {
            return true;
        }
        boolean authRepairAlias = window.optBoolean("authRepairAlias", false)
                || window.optBoolean("retargeted", false)
                || window.optBoolean("activeWindowRetargeted", false);
        if (!authRepairAlias) {
            return false;
        }
        String replacementWindowId = stableWindowIdFromPayload(
                window,
                "",
                "resolvedWindowId",
                "replacementWindowId",
                "interactiveTargetWindowId",
                "authRepairAliasStatusSourceWindowId",
                "rawActiveWindowId"
        );
        return hasStableWindowId(replacementWindowId) && selectedWindowId.equals(replacementWindowId);
    }

    private void openCodexDeviceAuth(JSONObject payload) {
        String url = payload.optString("url", "");
        if (url.isEmpty()) {
            toast("No sign-in page yet");
            return;
        }
        try {
            startActivity(new Intent(Intent.ACTION_VIEW, Uri.parse(url)));
        } catch (Exception exc) {
            toast("Could not open sign-in page");
        }
    }

    private void copyCodexDeviceCode(JSONObject payload) {
        String code = payload.optString("code", "");
        if (code.isEmpty()) {
            toast("No code yet");
            return;
        }
        ClipboardManager clipboardManager =
                (ClipboardManager) getSystemService(Context.CLIPBOARD_SERVICE);
        if (clipboardManager == null) {
            toast("Phone clipboard is not available");
            return;
        }
        clipboardManager.setPrimaryClip(ClipData.newPlainText("Codex one-time code", code));
        toast("Code copied");
    }

    private void showActiveSessionsDialog(
            JSONObject payload,
            String title,
            boolean preferGroups,
            String actionId,
            String tapId,
            String targetWindowId,
            long actionDownUptimeMs,
            long responseRevision
    ) throws Exception {
        boolean singletonActiveSessions = "Active Sessions".equals(title) && preferGroups;
        String dialogTargetWindowId = hasStableWindowId(targetWindowId)
                ? targetWindowId.trim()
                : payload.optString("activeWindowId", "").trim();
        if (singletonActiveSessions
                && (!hasStableWindowId(dialogTargetWindowId)
                        || !dialogTargetWindowId.equals(
                                payload.optString("activeWindowId", "").trim()
                        )
                        || !activeSessionsPayloadHasExactlyOneActiveWindow(
                                payload,
                                dialogTargetWindowId
                        ))) {
            // WHY: action/tap correlation is insufficient if a stale cache can
            // paint a different target. The measured dialog must name the exact
            // stable target captured when this Active action began.
            throw new IllegalStateException("active-dialog-target-mismatch");
        }
        if (singletonActiveSessions
                && activeSessionsDialog != null
                && activeSessionsDialog.isShowing()) {
            // WHY: repeated/in-flight Active responses must never create a second
            // native surface or repopulate the first one. The first draw owns the
            // interaction snapshot until dismiss; callbacks only warm next open.
            if (activeSessionsDialogList != null
                    && activeSessionsDialogRef != null
                    && activeSessionsDialogRef.length > 0
                    && activeSessionsDialogRef[0] == activeSessionsDialog
                    && activeSessionsDialogCloseTargets != null) {
                Log.i(CONTROL_LOG_TAG,
                        "stage=control-local control=active-sessions"
                                + " result=duplicate-show-snapshot-frozen"
                                + " rows=" + activeSessionsPayloadRowCount(payload));
                return;
            }
            AlertDialog inconsistentDialog = activeSessionsDialog;
            long inconsistentDialogGeneration = activeSessionsDialogInstanceGeneration;
            inconsistentDialog.dismiss();
            clearActiveSessionsDialogTracking(inconsistentDialog, inconsistentDialogGeneration, "inconsistent");
        }
        ScrollView scrollView = new ScrollView(this);
        scrollView.setFocusable(false);
        scrollView.setFillViewport(false);
        // WHY: summary-plus-tail titles are deliberately longer now. The native
        // picker must create breathing room around wrapped rows instead of
        // shortening the title brain or letting the bottom row clip into the
        // rounded dialog shell.
        scrollView.setPadding(0, 0, 0, dp(ACTIVE_SESSION_SCROLL_BOTTOM_INSET_DP));
        scrollView.setClipToPadding(true);
        LinearLayout list = new LinearLayout(this);
        list.setOrientation(LinearLayout.VERTICAL);
        list.setFocusable(false);
        list.setClipToPadding(false);
        list.setPadding(dp(4), dp(8), dp(4), dp(ACTIVE_SESSION_SCROLL_BOTTOM_INSET_DP));
        scrollView.addView(list);

        final AlertDialog[] dialogRef = new AlertDialog[1];
        final List<ActiveCloseTarget> selectedCloseTargets = new ArrayList<>();
        populateActiveSessionsList(list, payload, title, preferGroups, dialogRef, selectedCloseTargets);

        AlertDialog dialog = new AlertDialog.Builder(this)
                .setView(premiumDialogShell(title, "", scrollView))
                .create();
        dialogRef[0] = dialog;
        if (singletonActiveSessions) {
            // WHY: Needs Attention shares the row renderer but is not the
            // measured Active-open surface. Arming Active telemetry there can
            // consume a stale action/tap pair and falsely satisfy warm proof.
            observeActiveSessionsDialogFirstDraw(
                    dialog,
                    title,
                    actionId,
                    tapId,
                    dialogTargetWindowId,
                    actionDownUptimeMs,
                    responseRevision
            );
        }
        dialog.show();
        if (singletonActiveSessions) {
            long dialogGeneration = ++activeSessionsDialogInstanceGeneration;
            activeSessionsDialog = dialog;
            activeSessionsDialogList = list;
            activeSessionsDialogRef = dialogRef;
            activeSessionsDialogCloseTargets = selectedCloseTargets;
            if (recentActiveSessionsDialogUsableFor(dialogTargetWindowId)) {
                scheduleRecentActiveSessionsDialogExpiryIfShowing(
                        dialogTargetWindowId,
                        recentActiveSessionsDialogPayloadFetchedAtMs,
                        recentActiveSessionsDialogAtMs
                );
            }
            scheduleActiveSessionsDialogLiveRefresh("show");
            // WHY: FIX PREWARM (switch latency) — the Active dialog is now open with
            // the listed @windowIds known; warm each listed session's /terminal-frame
            // cache while the user reads the list so a subsequent switch is a warm hit
            // instead of a cold ~4s build. Gated to the real Active Sessions surface
            // (singletonActiveSessions); throttle/dedup live inside the helper.
            prewarmListedSessionFramesForSwitch(payload, "active-dialog-show");
            dialog.setOnDismissListener(d ->
                    clearActiveSessionsDialogTracking(dialog, dialogGeneration, "dismiss"));
        }
        stylePremiumDialogWindow(dialog);
        // WHY: Android AlertDialog can focus a child row or preserve a measured
        // scroll position, which made Active Sessions open in the middle. The phone picker
        // is always a "start from the newest/attention section" surface.
        scrollView.post(() -> scrollView.scrollTo(0, 0));
    }

    private void showActiveSessionsDialog(
            JSONObject payload,
            String title,
            boolean preferGroups
    ) throws Exception {
        boolean boundActiveAction =
                activeSessionsDialogDrawActionId.equals(currentApkActionIdForLog())
                && activeSessionsDialogDrawTapId.equals(currentApkTapIdForLog())
                && hasStableWindowId(activeSessionsDialogDrawWindowId);
        String payloadWindowId = payload == null
                ? ""
                : payload.optString("activeWindowId", "").trim();
        showActiveSessionsDialog(
                payload,
                title,
                preferGroups,
                boundActiveAction
                        ? activeSessionsDialogDrawActionId
                        : currentApkActionIdForLog(),
                boundActiveAction
                        ? activeSessionsDialogDrawTapId
                        : currentApkTapIdForLog(),
                boundActiveAction
                        ? activeSessionsDialogDrawWindowId
                        : payloadWindowId,
                boundActiveAction
                        ? activeSessionsDialogDrawActionDownUptimeMs
                        : 0,
                boundActiveAction
                        ? activeSessionsDialogDrawDataRevision
                        : activeSessionsDataRevision
        );
    }

    private void observeActiveSessionsDialogFirstDraw(
            AlertDialog dialog,
            String source,
            String actionId,
            String tapId,
            String targetWindowId,
            long actionDownUptimeMs,
            long responseRevision
    ) {
        if (dialog == null || dialog.getWindow() == null) {
            return;
        }
        Window dialogWindow = dialog.getWindow();
        View decor = dialogWindow.getDecorView();
        if (decor == null) {
            return;
        }
        ViewTreeObserver initialObserver = decor.getViewTreeObserver();
        if (!initialObserver.isAlive()) {
            return;
        }

        final class FirstDrawObserver
                implements ViewTreeObserver.OnDrawListener,
                View.OnAttachStateChangeListener {
            private boolean drawDispatched = false;
            private boolean drawListenerRemoved = false;
            private boolean frameMetricsArmed = false;
            private boolean frameMetricsFinished = false;
            private boolean renderedFrameMissingLogged = false;
            private Window.OnFrameMetricsAvailableListener frameMetricsListener;
            private final Runnable frameMetricsTimeout = () -> {
                if (!frameMetricsArmed || frameMetricsFinished) {
                    return;
                }
                frameMetricsFinished = true;
                if (ownsCurrentOpen()) {
                    logRenderedFrameMissingOnce("frame-metrics-timeout");
                }
                removeFrameMetricsListener();
                finishCleanupIfComplete();
            };

            void arm() {
                if (!ownsCurrentOpen()) {
                    return;
                }
                decor.addOnAttachStateChangeListener(this);
                initialObserver.addOnDrawListener(this);
                if (Build.VERSION.SDK_INT < Build.VERSION_CODES.N) {
                    frameMetricsFinished = true;
                    logRenderedFrameMissingOnce("frame-metrics-api-unavailable");
                    return;
                }
                frameMetricsListener = (window, frameMetrics, droppedFrames) -> {
                    if (frameMetricsFinished) {
                        return;
                    }
                    if (!ownsCurrentOpen()) {
                        frameMetricsFinished = true;
                        removeFrameMetricsListener();
                        finishCleanupIfComplete();
                        return;
                    }
                    // WHY: Android reuses the FrameMetrics object. Copy it in the
                    // callback before reading FIRST_DRAW_FRAME so the proof cannot
                    // race a later frame.
                    FrameMetrics metrics = new FrameMetrics(frameMetrics);
                    if (metrics.getMetric(FrameMetrics.FIRST_DRAW_FRAME) != 1) {
                        return;
                    }
                    frameMetricsFinished = true;
                    markApkFirstPaint(
                            "active-sessions-dialog",
                            source + "-frame-metrics",
                            actionId,
                            tapId,
                            targetWindowId,
                            actionDownUptimeMs,
                            SystemClock.uptimeMillis()
                    );
                    removeFrameMetricsListener();
                    finishCleanupIfComplete();
                };
                try {
                    dialogWindow.addOnFrameMetricsAvailableListener(
                            frameMetricsListener,
                            uiHandler
                    );
                    frameMetricsArmed = true;
                    uiHandler.postDelayed(
                            frameMetricsTimeout,
                            ACTIVE_SESSIONS_FIRST_FRAME_TIMEOUT_MS
                    );
                } catch (RuntimeException exc) {
                    frameMetricsFinished = true;
                    logRenderedFrameMissingOnce("frame-metrics-arm-failed");
                    Log.w(CONTROL_LOG_TAG,
                            "stage=apk-first-paint"
                                    + " result=frame-metrics-arm-failed",
                            exc);
                }
            }

            @Override
            public void onDraw() {
                if (drawDispatched) {
                    return;
                }
                drawDispatched = true;
                if (!ownsCurrentOpen()) {
                    frameMetricsFinished = true;
                    removeFrameMetricsListener();
                    decor.post(this::removeDrawListener);
                    return;
                }
                long decorDrawDispatchAtUptimeMs = SystemClock.uptimeMillis();
                logActiveSessionsDecorDrawDispatch(
                        actionId,
                        tapId,
                        targetWindowId,
                        actionDownUptimeMs,
                        decorDrawDispatchAtUptimeMs
                );
                if (!frameMetricsArmed || !decor.isHardwareAccelerated()) {
                    frameMetricsFinished = true;
                    logRenderedFrameMissingOnce(
                            frameMetricsArmed
                                    ? "hardware-acceleration-unavailable"
                                    : "frame-metrics-unavailable"
                    );
                    removeFrameMetricsListener();
                }
                // WHY: Android forbids mutating OnDraw listeners during onDraw.
                // Remove on the decor queue so this remains a true one-shot
                // observation without modifying the tree inside the draw pass.
                decor.post(this::removeDrawListener);
            }

            private void logRenderedFrameMissingOnce(String reason) {
                if (renderedFrameMissingLogged || !ownsCurrentOpen()) {
                    return;
                }
                renderedFrameMissingLogged = true;
                // WHY: OnDraw is only "about to draw." Missing platform frame
                // metrics is a missing acceptance sample, never permission to
                // relabel a pre-draw callback as a rendered frame.
                Log.w(CONTROL_LOG_TAG,
                        "stage=apk-first-paint"
                                + " result=rendered-frame-missing"
                                + " actionId=" + safeLogToken(actionId)
                                + " tapId=" + safeLogToken(tapId)
                                + " windowId="
                                + safeWindowIdForControlLog(targetWindowId)
                                + " surface=active-sessions-dialog"
                                + " reason=" + safeLogToken(reason)
                                + " timeoutMs="
                                + ACTIVE_SESSIONS_FIRST_FRAME_TIMEOUT_MS);
            }

            private boolean ownsCurrentOpen() {
                // WHY: callbacks can arrive after selection or a second Active
                // tap. Only the exact immutable open generation may publish a
                // draw, rendered-frame, or missing-sample receipt.
                return responseRevision == activeSessionsDataRevision
                        && actionId != null
                        && actionId.equals(currentApkActionIdForLog())
                        && tapId != null
                        && tapId.equals(currentApkTapIdForLog())
                        && hasStableWindowId(targetWindowId)
                        && targetWindowId.equals(activeSessionsDialogDrawWindowId)
                        && targetWindowId.equals(visibleTerminalTargetKey());
            }

            private void removeDrawListener() {
                if (drawListenerRemoved) {
                    return;
                }
                drawListenerRemoved = true;
                if (initialObserver.isAlive()) {
                    initialObserver.removeOnDrawListener(this);
                } else {
                    ViewTreeObserver currentObserver =
                            decor.getViewTreeObserver();
                    if (currentObserver.isAlive()) {
                        currentObserver.removeOnDrawListener(this);
                    }
                }
                finishCleanupIfComplete();
            }

            private void removeFrameMetricsListener() {
                uiHandler.removeCallbacks(frameMetricsTimeout);
                if (!frameMetricsArmed || frameMetricsListener == null) {
                    return;
                }
                frameMetricsArmed = false;
                try {
                    dialogWindow.removeOnFrameMetricsAvailableListener(
                            frameMetricsListener
                    );
                } catch (RuntimeException exc) {
                    Log.w(CONTROL_LOG_TAG,
                            "stage=apk-first-paint"
                                    + " result=frame-metrics-remove-failed",
                            exc);
                }
            }

            private void finishCleanupIfComplete() {
                if (drawListenerRemoved
                        && (!frameMetricsArmed || frameMetricsFinished)) {
                    decor.removeOnAttachStateChangeListener(this);
                }
            }

            @Override
            public void onViewAttachedToWindow(View view) {
                // Observers are armed before show so the first dialog frame
                // cannot race registration. No work is needed on attach.
            }

            @Override
            public void onViewDetachedFromWindow(View view) {
                removeDrawListener();
                frameMetricsFinished = true;
                removeFrameMetricsListener();
                decor.removeOnAttachStateChangeListener(this);
            }
        }

        FirstDrawObserver observer = new FirstDrawObserver();
        observer.arm();
    }

    private void clearActiveSessionsDialogTracking(
            AlertDialog expectedDialog,
            long expectedGeneration,
            String reason
    ) {
        if (activeSessionsDialog != expectedDialog
                || activeSessionsDialogInstanceGeneration != expectedGeneration) {
            return;
        }
        activeSessionsDialog = null;
        activeSessionsDialogList = null;
        activeSessionsDialogRef = null;
        activeSessionsDialogCloseTargets = null;
        stopActiveSessionsDialogLiveRefresh(reason);
    }

    private void populateActiveSessionsList(
            LinearLayout list,
            JSONObject payload,
            String title,
            boolean preferGroups,
            AlertDialog[] dialogRef,
            List<ActiveCloseTarget> selectedCloseTargets
    ) throws Exception {
        String session = payload.optString("session", "main");
        list.removeAllViews();
        addActiveDialogActions(list, dialogRef, selectedCloseTargets);
        JSONObject activeWindow = activeWindowFromPayload(payload);
        JSONArray groups = payload.optJSONArray("groups");
        boolean preserveServerDisplayOrder = "Active Sessions".equals(title) && preferGroups;
        if (preferGroups && groups != null && groups.length() > 0) {
            for (int i = 0; i < groups.length(); i++) {
                JSONObject group = groups.getJSONObject(i);
                JSONArray windows = group.optJSONArray("windows");
                if (windows == null || windows.length() == 0) {
                    continue;
                }
                // WHY: the server is the shared session/title brain and already
                // orders Active Sessions by the live operator state. Android must
                // not re-sort grouped rows by a local urgency heuristic, because
                // that buried running/current fork lanes such as @34 below older
                // ready rows while `/tabs?light=1` exported the correct order.
                // active row stays in its state bucket without prefixing the visible title.
                // Do not invent a client-side current heuristic.
                List<JSONObject> groupRows = preserveServerDisplayOrder
                        ? windowsInPayloadOrder(windows)
                        : sortedWindows(windows);
                if (groupRows.isEmpty()) {
                    continue;
                }
                addSectionHeader(list, group.optString("label", "Sessions"), groupRows.size());
                addTabRows(list, groupRows, session, dialogRef, selectedCloseTargets, null, false);
            }
        } else {
            JSONArray windows = payload.optJSONArray("displayWindows");
            if (windows == null) {
                windows = payload.optJSONArray("topWindows");
            }
            if (windows == null) {
                windows = payload.getJSONArray("windows");
            }
            List<JSONObject> rows = preserveServerDisplayOrder
                    ? windowsInPayloadOrder(windows)
                    : sortedWindows(windows);
            if (rows.isEmpty()) {
                addSectionHeader(list, "Nothing needs attention", 0);
            } else {
                addTabRows(list, rows, session, dialogRef, selectedCloseTargets, null, !preferGroups);
            }
        }
    }

    private LinearLayout premiumDialogShell(String title, String subtitle, ScrollView scrollView) {
        LinearLayout shell = new LinearLayout(this);
        shell.setOrientation(LinearLayout.VERTICAL);
        shell.setPadding(dp(16), dp(14), dp(16), dp(12));
        shell.setBackground(roundedFill(
                Color.rgb(18, 19, 26),
                PREMIUM_DIALOG_CORNER_RADIUS_DP,
                Color.rgb(76, 82, 106)
        ));

        TextView titleView = new TextView(this);
        titleView.setText(title);
        titleView.setTextSize(24);
        titleView.setTypeface(Typeface.create("sans-serif-medium", Typeface.NORMAL));
        titleView.setTextColor(Color.rgb(244, 246, 252));
        titleView.setIncludeFontPadding(false);
        titleView.setPadding(0, 0, 0, dp(5));
        shell.addView(titleView, new LinearLayout.LayoutParams(
                LinearLayout.LayoutParams.MATCH_PARENT,
                LinearLayout.LayoutParams.WRAP_CONTENT
        ));

        if (subtitle != null && !subtitle.trim().isEmpty()) {
            TextView subtitleView = new TextView(this);
            subtitleView.setText(subtitle);
            subtitleView.setTextSize(12);
            subtitleView.setTypeface(Typeface.create("sans-serif", Typeface.NORMAL));
            subtitleView.setTextColor(Color.rgb(174, 181, 205));
            subtitleView.setIncludeFontPadding(false);
            subtitleView.setPadding(0, 0, 0, dp(10));
            shell.addView(subtitleView, new LinearLayout.LayoutParams(
                    LinearLayout.LayoutParams.MATCH_PARENT,
                    LinearLayout.LayoutParams.WRAP_CONTENT
            ));
        }

        shell.addView(scrollView, new LinearLayout.LayoutParams(
                LinearLayout.LayoutParams.MATCH_PARENT,
                LinearLayout.LayoutParams.WRAP_CONTENT
        ));
        return shell;
    }

    private void stylePremiumDialogWindow(AlertDialog dialog) {
        if (dialog == null || dialog.getWindow() == null) {
            return;
        }
        // WHY: the old stock AlertDialog gray shell made the APK feel like a
        // debug utility. Making the window transparent lets the app-owned rounded
        // dark panel define the chrome without changing any session actions.
        dialog.getWindow().setBackgroundDrawable(
                new android.graphics.drawable.ColorDrawable(Color.TRANSPARENT)
        );
    }

    private void addActiveDialogActions(
            LinearLayout list,
            AlertDialog[] dialogRef,
            List<ActiveCloseTarget> selectedCloseTargets
    ) {
        LinearLayout actions = new LinearLayout(this);
        actions.setOrientation(LinearLayout.HORIZONTAL);
        actions.setPadding(0, 0, 0, dp(10));
        // WHY: the stock AlertDialog three-button footer can stack or disappear
        // below the phone viewport in Active Sessions, exactly as the user
        // reported. Keep these actions inside the scrollable dialog content as a
        // compact row so New/Rename/Cancel are all visible and scroll with the
        // session list instead of being clipped by Android's button panel.
        actions.addView(activeDialogActionButton("New", v -> {
            if (dialogRef[0] != null) {
                dialogRef[0].dismiss();
            }
            controlAndSettleLiveBottom("/new?fast=1", "", "new-session");
        }));
        actions.addView(activeDialogActionButton("Rename", v -> {
            if (dialogRef[0] != null) {
                dialogRef[0].dismiss();
            }
            showRenameCurrentTab();
        }));
        actions.addView(activeDialogActionButton("Close selected", v ->
                confirmBulkClose(selectedCloseTargets, dialogRef)));
        actions.addView(activeDialogActionButton("Cancel", v -> {
            if (dialogRef[0] != null) {
                dialogRef[0].dismiss();
            }
        }));
        list.addView(actions);
    }

    private Button activeDialogActionButton(String label, View.OnClickListener listener) {
        Button action = new Button(this);
        action.setText(label);
        action.setAllCaps(false);
        action.setTextSize(label != null && label.length() > 8 ? 10 : 12);
        action.setSingleLine(true);
        action.setTypeface(Typeface.create("sans-serif-medium", Typeface.NORMAL));
        action.setTextColor(Color.rgb(228, 233, 249));
        action.setGravity(android.view.Gravity.CENTER);
        action.setPadding(dp(4), 0, dp(4), 0);
        setTouchableBackground(action, Color.rgb(38, 41, 55), Color.rgb(137, 180, 250));
        action.setOnClickListener(v -> {
            flashTap(v);
            listener.onClick(v);
        });
        LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(
                0,
                dp(44),
                1
        );
        params.setMargins(dp(3), 0, dp(3), 0);
        action.setLayoutParams(params);
        return action;
    }

    private void showOldSessionsDialog(JSONObject payload) throws Exception {
        JSONArray oldSessions = payload.optJSONArray("oldSessions");
        if (oldSessions == null) {
            oldSessions = payload.optJSONArray("recentCodexSessions");
        }
        ScrollView scrollView = new ScrollView(this);
        scrollView.setFocusable(false);
        LinearLayout list = new LinearLayout(this);
        list.setOrientation(LinearLayout.VERTICAL);
        list.setFocusable(false);
        list.setPadding(dp(8), dp(6), dp(8), dp(6));
        scrollView.addView(list);

        final AlertDialog[] dialogRef = new AlertDialog[1];
        if (oldSessions == null || oldSessions.length() == 0) {
            addSectionHeader(list, "No old sessions found", 0);
        } else {
            String currentDate = "";
            for (int i = 0; i < oldSessions.length(); i++) {
                JSONObject session = oldSessions.getJSONObject(i);
                // WHY: old-session recovery is for user-owned parent Codex
                // threads. Showing subagent/explorer/worker threads here was
                // explicitly confusing because those are implementation helpers,
                // not sessions the user expects to resume from the phone.
                if (!"user".equals(session.optString("threadSource", "user"))) {
                    continue;
                }
                String dateLabel = session.optString("dateLabel", session.optString("updatedGroup", "Older"));
                if (!dateLabel.equals(currentDate)) {
                    currentDate = dateLabel;
                    addSectionHeader(list, currentDate, countOldSessionsForDate(oldSessions, currentDate));
                }
                addOldSessionRow(list, session, dialogRef);
            }
        }

        AlertDialog dialog = new AlertDialog.Builder(this)
                .setTitle("Old Sessions")
                .setView(scrollView)
                .setPositiveButton("Active Sessions", (d, which) -> showActiveSessions())
                .setNeutralButton("Crashed", (d, which) -> showCrashedSessions())
                .setNegativeButton("Cancel", null)
                .show();
        dialogRef[0] = dialog;
        scrollView.post(() -> scrollView.scrollTo(0, 0));
    }

