    private int countOldSessionsForDate(JSONArray oldSessions, String dateLabel) throws Exception {
        int count = 0;
        for (int i = 0; i < oldSessions.length(); i++) {
            JSONObject session = oldSessions.getJSONObject(i);
            if (!"user".equals(session.optString("threadSource", "user"))) {
                continue;
            }
            String sessionDate = session.optString("dateLabel", session.optString("updatedGroup", "Older"));
            if (dateLabel.equals(sessionDate)) {
                count++;
            }
        }
        return count;
    }

    private String oldSessionTimeLabel(JSONObject session) {
        String dateLabel = session.optString("dateLabel", session.optString("updatedGroup", "Older"));
        String timestamp = session.optString("updatedAt",
                session.optString("startedAt", session.optString("createdAt", "")));
        String time = shortClockTime(timestamp);
        return time.isEmpty() ? dateLabel : dateLabel + " · " + time;
    }

    private int countWorkspaceSnapshotsForDate(JSONArray snapshots, String dateLabel) throws Exception {
        int count = 0;
        for (int i = 0; i < snapshots.length(); i++) {
            JSONObject snapshot = snapshots.getJSONObject(i);
            if (dateLabel.equals(workspaceSnapshotDateLabel(snapshot))) {
                count++;
            }
        }
        return count;
    }

    private int countCrashedSessionsForDate(JSONArray crashedSessions, String dateLabel) throws Exception {
        int count = 0;
        for (int i = 0; i < crashedSessions.length(); i++) {
            JSONObject session = crashedSessions.getJSONObject(i);
            if (!"user".equals(session.optString("threadSource", "user"))) {
                continue;
            }
            String sessionDate = session.optString("dateLabel", session.optString("updatedGroup", "Older"));
            if (dateLabel.equals(sessionDate)) {
                count++;
            }
        }
        return count;
    }

    private JSONObject activeWindowFromPayload(JSONObject payload) throws Exception {
        JSONArray windows = payload.optJSONArray("windows");
        if (windows == null) {
            return null;
        }
        for (int i = 0; i < windows.length(); i++) {
            JSONObject window = windows.getJSONObject(i);
            if (window.optBoolean("active", false)) {
                return window;
            }
        }
        return null;
    }

    private boolean sameWindow(JSONObject left, JSONObject right) {
        if (left == null || right == null) {
            return false;
        }
        String leftId = left.optString("windowId", "");
        String rightId = right.optString("windowId", "");
        if (!leftId.isEmpty() && leftId.equals(rightId)) {
            return true;
        }
        return left.optInt("index", -1) == right.optInt("index", -2);
    }

    private List<JSONObject> sortedWindows(JSONArray windows) throws Exception {
        return sortedWindows(windows, null);
    }

    private List<JSONObject> windowsInPayloadOrder(JSONArray windows) throws Exception {
        return windowsInPayloadOrder(windows, null);
    }

    private List<JSONObject> windowsInPayloadOrder(JSONArray windows, JSONObject skipWindow) throws Exception {
        List<JSONObject> ordered = new ArrayList<>();
        for (int i = 0; i < windows.length(); i++) {
            JSONObject window = windows.getJSONObject(i);
            if (sameWindow(window, skipWindow)) {
                continue;
            }
            ordered.add(window);
        }
        return ordered;
    }

    private List<JSONObject> sortedWindows(JSONArray windows, JSONObject skipWindow) throws Exception {
        List<JSONObject> sorted = new ArrayList<>();
        for (int i = 0; i < windows.length(); i++) {
            JSONObject window = windows.getJSONObject(i);
            if (sameWindow(window, skipWindow)) {
                continue;
            }
            sorted.add(window);
        }
        // WHY: the phone picker is an action queue, not a chronology wall. Show
        // red/problem sessions first, yellow/waiting sessions next, then calm
        // green working rows, while preserving recent activity inside each
        // urgency group so the user sees the sessions that need action first.
        sorted.sort((left, right) -> {
            int leftUrgency = sessionUrgencyRank(left);
            int rightUrgency = sessionUrgencyRank(right);
            if (leftUrgency != rightUrgency) {
                return Integer.compare(leftUrgency, rightUrgency);
            }
            long leftActivity = left.optLong("activityAt", 0);
            long rightActivity = right.optLong("activityAt", 0);
            if (leftActivity != rightActivity) {
                return Long.compare(rightActivity, leftActivity);
            }
            return Integer.compare(right.optInt("index", 0), left.optInt("index", 0));
        });
        return sorted;
    }

    private int sessionUrgencyRank(JSONObject window) {
        String status = window.optString("status", "").toLowerCase(Locale.US);
        String statusLabel = window.optString("statusLabel", "").toLowerCase(Locale.US);
        if ("problem".equals(status)
                || statusLabel.contains("problem")
                || statusLabel.contains("crash")
                || statusLabel.contains("error")) {
            return 0;
        }
        if (window.optBoolean("needsAttention", false) || "waiting".equals(status)) {
            return 1;
        }
        if ("running".equals(status) || "working".equals(statusLabel)) {
            return 3;
        }
        return 2;
    }

    private void addSectionHeader(LinearLayout list, String label, int count) {
        TextView section = new TextView(this);
        section.setText(count > 0 ? label + " (" + count + ")" : label);
        section.setTextSize(13);
        section.setTypeface(Typeface.create("sans-serif-medium", Typeface.NORMAL));
        section.setTextColor(Color.rgb(186, 198, 235));
        section.setPadding(0, dp(10), 0, dp(5));
        list.addView(section);
    }

    private void addTabRows(
            LinearLayout list,
            List<JSONObject> windows,
            String session,
            AlertDialog[] dialogRef,
            List<ActiveCloseTarget> selectedCloseTargets,
            JSONObject skipWindow,
            boolean includeChildRows
    ) throws Exception {
        for (int i = 0; i < windows.size(); i++) {
            JSONObject window = windows.get(i);
            addTabRow(list, window, session, dialogRef, selectedCloseTargets);
            // WHY: `/tabs` keeps child metadata so the parent row can say
            // "1 child lane" and diagnostics can inspect workers. The phone's
            // visible Active Sessions list is operator-facing, so child/proof
            // rows must not reappear under their parent while web stays clean.
            if (!includeChildRows) {
                continue;
            }
            JSONArray children = window.optJSONArray("children");
            if (children == null) {
                continue;
            }
            List<JSONObject> childRows = sortedWindows(children, skipWindow);
            for (int childIndex = 0; childIndex < childRows.size(); childIndex++) {
                addTabRow(list, childRows.get(childIndex), session, dialogRef, selectedCloseTargets);
            }
        }
    }

    private void addTabRow(
            LinearLayout list,
            JSONObject window,
            String session,
            AlertDialog[] dialogRef,
            List<ActiveCloseTarget> selectedCloseTargets
    ) throws Exception {
        int index = window.getInt("index");
        String windowId = window.optString("windowId", "");
        // WHY: Android is a plain title consumer. Only the central authority
        // fields may become row title text; raw tmux `name`, prompt fragments,
        // cached transcript labels, or local fallback strings must stay out of
        // the APK or stale KAI/Orb names can resurrect after restart.
        canonicalTitleForPayload(window, "active-row");
        final CanonicalTitleBinding titleBinding =
                canonicalTitleBindingFromPayload(window);
        final CanonicalTitleEnvelope titleEnvelope =
                canonicalTitleForBinding(titleBinding);
        String visibleTitle = titleEnvelope == null
                ? ""
                : titleEnvelope.displayTitle;
        SendStatusRevisionFence.Status presentedStatus =
                sessionStatusForDisplay(window);
        String status = presentedStatus.state;
        String statusLabel = presentedStatus.label.isEmpty()
                ? "Done"
                : presentedStatus.label;
        String statusTone = presentedStatus.tone;
        boolean statusNeedsAttention = presentedStatus.needsAttention;
        boolean activeSession = window.optBoolean("active", false);
        final String rowSessionId = activeSwitchSessionId(window);
        final String rowThreadId = activeSwitchThreadId(window);

        LinearLayout row = new LinearLayout(this);
        row.setOrientation(LinearLayout.HORIZONTAL);
        row.setGravity(android.view.Gravity.TOP);
        row.setClipToPadding(false);
        row.setPadding(window.optBoolean("isChild", false) ? dp(18) : 0, 0, 0, 0);

        LinearLayout openPanel = new LinearLayout(this);
        openPanel.setOrientation(LinearLayout.VERTICAL);
        openPanel.setGravity(android.view.Gravity.CENTER_VERTICAL);
        openPanel.setClipToPadding(false);
        openPanel.setMinimumWidth(0);
        openPanel.setPadding(
                dp(12),
                dp(ACTIVE_SESSION_CARD_VERTICAL_PADDING_DP),
                dp(12),
                dp(ACTIVE_SESSION_CARD_VERTICAL_PADDING_DP)
        );
        setTouchableBackground(openPanel,
                window.optBoolean("active", false)
                        ? Color.rgb(51, 58, 78)
                        : Color.rgb(32, 35, 48),
                Color.rgb(137, 180, 250));
        View.OnClickListener openSessionClick = v -> {
            flashTap(v);
            selectTabForTyping(
                    index,
                    windowId,
                    titleBinding,
                    dialogRef,
                    rowSessionId,
                    rowThreadId
            );
        };
        View.OnTouchListener activeDialogTouchMarker = (view, event) -> markActiveSessionsDialogTouch(event);
        openPanel.setClickable(true);
        openPanel.setOnClickListener(openSessionClick);
        openPanel.setOnTouchListener(activeDialogTouchMarker);

        LinearLayout titleRow = new LinearLayout(this);
        titleRow.setOrientation(LinearLayout.HORIZONTAL);
        titleRow.setGravity(android.view.Gravity.TOP);
        titleRow.setBaselineAligned(false);
        titleRow.setClipToPadding(false);
        titleRow.setMinimumWidth(0);

        TextView statusDot = new StatusDotTextView(this);
        statusDot.setText("●");
        statusDot.setTextSize(PREMIUM_STATUS_DOT_SP);
        statusDot.setGravity(android.view.Gravity.CENTER);
        statusDot.setIncludeFontPadding(false);
        statusDot.setContentDescription(statusLabel);
        applySessionStatusDot(
                statusDot,
                status,
                statusNeedsAttention,
                statusLabel,
                statusTone,
                activeSession
        );

        TextView titleText = new TextView(this);
        titleText.setText(visibleTitle);
        titleText.setTextSize(16);
        titleText.setTypeface(Typeface.create("sans-serif-medium", Typeface.NORMAL));
        titleText.setTextColor(Color.rgb(244, 246, 252));
        titleText.setSingleLine(false);
        titleText.setMaxLines(Integer.MAX_VALUE);
        titleText.setEllipsize(null);
        titleText.setIncludeFontPadding(true);
        titleText.setHorizontallyScrolling(false);
        titleText.setLineSpacing(dp(ACTIVE_SESSION_TITLE_LINE_SPACING_DP), 1.0f);
        titleText.setPadding(0, 0, 0, dp(1));
        titleText.setMinWidth(0);
        // WHY: Active Sessions title cutoff keeps recurring when row chrome is
        // changed without preserving the owner boundary. The server owns the
        // title text; Android owns wrapping and width allocation. Keep this
        // TextView unlimited, non-ellipsized, and zero-min-width so the weighted
        // title card wraps instead of being starved by the Close action column.
        if (visibleTitle.length() >= ACTIVE_SESSION_TITLE_LONG_TEXT_MIN_CHARS) {
            // WHY: the 2026-06-29 repeat screenshot showed the visible row stop
            // at "Hybrid Mantis APK Responsiveness: Tit" even though `/tabs`
            // carried the full title. Long rows need an explicit measured-height
            // floor so Android cannot keep a stale two-line card after wrapping.
            titleText.setMinLines(ACTIVE_SESSION_TITLE_LONG_MIN_LINES);
        }
        titleText.addOnLayoutChangeListener((view, left, top, right, bottom, oldLeft, oldTop, oldRight, oldBottom) ->
                ensureWrappedTitleFit(titleText, visibleTitle, "active-session-row")
        );
        // WHY: the full session title is now a long-press copy target. Android
        // child views with long-click listeners can intercept taps instead of
        // letting the parent card open the session, which made Active switching
        // feel like it needed 3-6 taps. Give every visible text/status target the
        // same one-tap open action while preserving long-press title copy.
        titleText.setClickable(true);
        titleText.setOnClickListener(openSessionClick);
        titleText.setOnTouchListener(activeDialogTouchMarker);
        titleText.setLongClickable(titleEnvelope != null);
        titleText.setOnLongClickListener(v -> {
            if (titleEnvelope == null) {
                return false;
            }
            ClipboardManager clipboardManager =
                    (ClipboardManager) getSystemService(Context.CLIPBOARD_SERVICE);
            if (clipboardManager != null) {
                clipboardManager.setPrimaryClip(
                        ClipData.newPlainText(
                                "WEzterm session title",
                                titleEnvelope.displayTitle
                        )
                );
                toast("Session title copied");
            }
            return true;
        });

        // WHY: users need to know whether a Codex tab is still actively working
        // before switching or closing it. The dot is driven by control-server
        // pane evidence, not by the mutable title string, so scanability improves
        // without changing the stable windowId close/select target.
        LinearLayout.LayoutParams dotParams = new LinearLayout.LayoutParams(
                dp(28),
                LinearLayout.LayoutParams.WRAP_CONTENT
        );
        dotParams.setMargins(0, dp(2), dp(6), 0);
        titleRow.addView(statusDot, dotParams);
        statusDot.setClickable(true);
        statusDot.setOnClickListener(openSessionClick);
        statusDot.setOnTouchListener(activeDialogTouchMarker);
        titleRow.addView(titleText, new LinearLayout.LayoutParams(
                0,
                LinearLayout.LayoutParams.WRAP_CONTENT,
                1
        ));
        titleRow.setClickable(true);
        titleRow.setOnClickListener(openSessionClick);
        titleRow.setOnTouchListener(activeDialogTouchMarker);
        // WHY: session titles are the user's main recovery signal. A fixed 72dp
        // card plus single-line ellipsis made long Codex titles unreadable on
        // the phone. Let the title row and card grow vertically so the full title
        // is readable, while the dialog ScrollView absorbs the extra height.
        openPanel.addView(titleRow, new LinearLayout.LayoutParams(
                LinearLayout.LayoutParams.MATCH_PARENT,
                LinearLayout.LayoutParams.WRAP_CONTENT
        ));
        // WHY: the dot-only color cue made all rows look broken when the installed APK palette regressed,
        // and color alone did not visibly say
        // which sessions were Working. Keep the central /tabs statusLabel as
        // readable text while the dot remains the compact scan target.
        TextView statusLabelText = new TextView(this);
        statusLabelText.setText(statusLabel);
        statusLabelText.setTextSize(12);
        statusLabelText.setTypeface(Typeface.create("sans-serif-medium", Typeface.NORMAL));
        statusLabelText.setTextColor(sessionStatusTextColor(
                status,
                statusNeedsAttention,
                statusTone
        ));
        statusLabelText.setIncludeFontPadding(false);
        statusLabelText.setClickable(true);
        statusLabelText.setOnClickListener(openSessionClick);
        statusLabelText.setOnTouchListener(activeDialogTouchMarker);
        LinearLayout.LayoutParams statusLabelParams = new LinearLayout.LayoutParams(
                LinearLayout.LayoutParams.WRAP_CONTENT,
                LinearLayout.LayoutParams.WRAP_CONTENT
        );
        statusLabelParams.setMargins(dp(34), dp(2), 0, 0);
        openPanel.addView(statusLabelText, statusLabelParams);

        Button close = new Button(this);
        close.setAllCaps(false);
        close.setTextSize(12);
        close.setTypeface(Typeface.create("sans-serif-medium", Typeface.NORMAL));
        close.setPadding(dp(3), 0, dp(3), 0);
        close.setMinWidth(0);
        close.setMinimumWidth(0);
        close.setMinHeight(dp(ACTIVE_SESSION_CLOSE_BUTTON_MIN_HEIGHT_DP));
        close.setSingleLine(true);
        close.setIncludeFontPadding(false);
        ActiveCloseTarget target = activeCloseTargetFromWindow(
                index,
                window,
                titleBinding,
                statusLabel
        );
        boolean closeTargetSelected = activeBulkCloseTargetForWindow(selectedCloseTargets, windowId) != null;
        boolean directCloseAvailable = activeRowDirectCloseAvailable(window, windowId);
        boolean closeBlockedByMetadata = activeRowCloseBlockedByMetadata(window);
        applyActiveCloseButtonStyle(
                close,
                openPanel,
                closeTargetSelected,
                window.optBoolean("active", false),
                directCloseAvailable,
                closeBlockedByMetadata
        );
        close.setOnClickListener(v -> {
            flashTap(v);
            if (!hasStableWindowId(windowId)) {
                toast("Close target needs a stable window id");
                return;
            }
            if (directCloseAvailable) {
                confirmActiveRowClose(target, dialogRef);
                return;
            }
            if (closeBlockedByMetadata) {
                recheckAndConfirmActiveRowClose(target, dialogRef);
                return;
            }
            // WHY: the row label may only mean direct Close when central
            // closeAction metadata says this stable `@windowId` can close. While
            // the metadata worker is absent/stale, keep the legacy batch path but
            // label it as Select/Selected so users cannot mistake selection for a
            // destructive X/Y close action.
            boolean selected = toggleActiveBulkCloseTarget(selectedCloseTargets, target);
            logActiveBulkCloseTarget(
                    selected ? "bulk-close-select" : "bulk-close-unselect",
                    target,
                    selectedCloseTargets.size()
            );
            applyActiveCloseButtonStyle(
                    close,
                    openPanel,
                    selected,
                    window.optBoolean("active", false),
                    false,
                    false
            );
        });
        close.setOnTouchListener(activeDialogTouchMarker);

        row.addView(openPanel, new LinearLayout.LayoutParams(
                0,
                LinearLayout.LayoutParams.WRAP_CONTENT,
                1
        ));
        // WHY: the row Close control must not steal fixed-width space from long
        // session titles. A prior 72dp button plus 10dp gap made the title card
        // collapse into clipped fragments; use a compact action column and let
        // row height grow when a title needs more lines.
        LinearLayout.LayoutParams closeParams = new LinearLayout.LayoutParams(
                dp(ACTIVE_SESSION_CLOSE_BUTTON_WIDTH_DP),
                LinearLayout.LayoutParams.WRAP_CONTENT
        );
        closeParams.setMargins(dp(ACTIVE_SESSION_CLOSE_BUTTON_GAP_DP), dp(4), 0, dp(4));
        row.addView(close, closeParams);
        LinearLayout.LayoutParams rowParams = new LinearLayout.LayoutParams(
                LinearLayout.LayoutParams.MATCH_PARENT,
                LinearLayout.LayoutParams.WRAP_CONTENT
        );
        rowParams.setMargins(0, dp(4), 0, dp(ACTIVE_SESSION_ROW_GAP_DP));
        list.addView(row, rowParams);
    }

    private boolean toggleActiveBulkCloseTarget(
            List<ActiveCloseTarget> selectedCloseTargets,
            ActiveCloseTarget target
    ) {
        ActiveCloseTarget existing = activeBulkCloseTargetForWindow(
                selectedCloseTargets,
                target.windowId
        );
        if (existing != null) {
            selectedCloseTargets.remove(existing);
            return false;
        }
        selectedCloseTargets.add(target);
        return true;
    }

    private ActiveCloseTarget activeBulkCloseTargetForWindow(
            List<ActiveCloseTarget> selectedCloseTargets,
            String windowId
    ) {
        if (!hasStableWindowId(windowId)) {
            return null;
        }
        String stableWindowId = windowId.trim();
        for (int i = 0; i < selectedCloseTargets.size(); i++) {
            ActiveCloseTarget target = selectedCloseTargets.get(i);
            if (stableWindowId.equals(target.windowId)) {
                return target;
            }
        }
        return null;
    }

    private ActiveCloseTarget activeCloseTargetFromWindow(
            int index,
            JSONObject window,
            CanonicalTitleBinding titleBinding,
            String fallbackStatusLabel
    ) {
        String windowId = window.optString("windowId", "");
        return new ActiveCloseTarget(
                index,
                windowId,
                titleBinding,
                fallbackStatusLabel,
                window.optBoolean("safeToClose", false),
                activeRowDirectCloseAvailable(window, windowId),
                closeActionPathForWindow(window, windowId),
                window.optString("closeBlockedReason", ""),
                window.optString("closeEligibilityReason", "")
        );
    }

    private boolean activeRowDirectCloseAvailable(JSONObject window, String windowId) {
        if (window == null || !hasStableWindowId(windowId)) {
            return false;
        }
        return window.optBoolean("closeActionAvailable", false)
                && !closeActionPathForWindow(window, windowId).isEmpty();
    }

    private boolean activeRowCloseBlockedByMetadata(JSONObject window) {
        if (window == null) {
            return false;
        }
        String reason = activeCloseUnavailableReason(window);
        if (reason.isEmpty()) {
            return false;
        }
        if (window.has("closeActionAvailable")) {
            return !window.optBoolean("closeActionAvailable", false);
        }
        // WHY: the central close guard is the authority. A light/cached payload
        // can still carry `safeToClose=false` plus a blocker without the optional
        // closeActionAvailable field; treating that as selectable recreated the
        // installed APK "Closed 0 of N" protected-row regression.
        return !window.optBoolean("safeToClose", false);
    }

    private String activeCloseUnavailableReason(JSONObject window) {
        if (window == null) {
            return "";
        }
        String blocked = window.optString("closeBlockedReason", "").trim();
        if (!blocked.isEmpty()) {
            return blocked;
        }
        String eligibility = window.optString("closeEligibilityReason", "").trim();
        if (!eligibility.isEmpty()) {
            return eligibility;
        }
        return window.optString("closePolicy", "").trim();
    }

    private String activeCloseUnavailableMessage(ActiveCloseTarget target) {
        String reason = target.closeBlockedReason;
        if (reason.isEmpty()) {
            reason = target.closeEligibilityReason;
        }
        if (reason.isEmpty()) {
            reason = "Close unavailable";
        }
        return reason;
    }

    private void showLocalCloseRecheckFeedback(String reason, int targetCount) {
        // WHY: backend `/tabs?light=1&includeChildren=1` can be seconds slow
        // under control-server CPU pressure. The APK must acknowledge the user's
        // confirmed Close tap locally while preserving the server-owned
        // revalidation gate before any destructive `/close` request is sent.
        toast(targetCount > 1 ? "Re-checking selected sessions..." : "Re-checking close target...");
        Log.i(CONTROL_LOG_TAG,
                "stage=control-local control=close result=recheck-pending"
                        + " reason=" + safeLogToken(reason)
                        + " targetCount=" + Math.max(0, targetCount));
    }

    private String closeActionPathForWindow(JSONObject window, String windowId) {
        if (window == null || !hasStableWindowId(windowId)) {
            return "";
        }
        String path = window.optString("closeActionPath", "").trim();
        if (path.isEmpty() || !path.startsWith("/close")) {
            return "";
        }
        if (!closeActionPathTargetsWindow(path, windowId.trim())) {
            return "";
        }
        return path;
    }

    private boolean closeActionPathTargetsWindow(String path, String windowId) {
        if (path == null || windowId == null || windowId.trim().isEmpty()) {
            return false;
        }
        String stableWindowId = windowId.trim();
        String encodedWindowId = urlEncode(stableWindowId);
        return path.contains("windowId=" + stableWindowId)
                || path.contains("windowId=" + encodedWindowId);
    }

    private void applyActiveCloseButtonStyle(
            Button close,
            LinearLayout openPanel,
            boolean selected,
            boolean active,
            boolean directCloseAvailable,
            boolean closeBlockedByMetadata
    ) {
        if (directCloseAvailable) {
            close.setText("Close");
            close.setTextColor(Color.rgb(255, 228, 234));
            setTouchableBackground(close, Color.rgb(96, 54, 68), Color.rgb(203, 95, 120));
            setTouchableBackground(openPanel,
                    active
                            ? Color.rgb(51, 58, 78)
                            : Color.rgb(32, 35, 48),
                    Color.rgb(137, 180, 250));
            return;
        }
        if (closeBlockedByMetadata) {
            close.setText("Blocked");
            close.setTextColor(Color.rgb(205, 214, 244));
            setTouchableBackground(close, Color.rgb(49, 50, 68), Color.rgb(108, 112, 134));
            setTouchableBackground(openPanel,
                    active
                            ? Color.rgb(51, 58, 78)
                            : Color.rgb(32, 35, 48),
                    Color.rgb(137, 180, 250));
            return;
        }
        if (selected) {
            close.setText("Selected");
            close.setTextColor(Color.rgb(30, 30, 46));
            setTouchableBackground(close, Color.rgb(249, 226, 175), Color.rgb(250, 179, 135));
            setTouchableBackground(openPanel, Color.rgb(62, 55, 38), Color.rgb(249, 226, 175));
            return;
        }
        close.setText("Select");
        close.setTextColor(Color.rgb(228, 233, 249));
        setTouchableBackground(close, Color.rgb(38, 41, 55), Color.rgb(137, 180, 250));
        setTouchableBackground(openPanel,
                active
                        ? Color.rgb(51, 58, 78)
                        : Color.rgb(32, 35, 48),
                Color.rgb(137, 180, 250));
    }

    private void addOldSessionRow(
            LinearLayout list,
            JSONObject session,
            AlertDialog[] dialogRef
    ) {
        String sessionId = session.optString("id", "");
        CanonicalTitleEnvelope titleEnvelope =
                canonicalTitleForArchivedPayload(
                        session,
                        "old-session-row"
                );
        CanonicalTitleBinding titleBinding =
                archivedTitleBindingFromPayload(session);
        // WHY(archived title seam): Old Sessions consumes the same immutable
        // binding/revision envelope as Active and terminal frames. A session id,
        // archive filename, prompt, or humanized label is navigation metadata,
        // never a substitute title when the exact persisted LKG is unavailable.
        String visibleTitle = titleEnvelope == null
                ? ""
                : titleEnvelope.displayTitle;
        String timeLabel = oldSessionTimeLabel(session);
        String cwd = session.optString("cwd", "");

        LinearLayout row = new LinearLayout(this);
        row.setOrientation(LinearLayout.HORIZONTAL);
        row.setPadding(0, dp(3), 0, dp(3));

        LinearLayout openPanel = new LinearLayout(this);
        openPanel.setOrientation(LinearLayout.VERTICAL);
        openPanel.setGravity(android.view.Gravity.CENTER_VERTICAL);
        openPanel.setPadding(dp(12), dp(8), dp(12), dp(8));
        setTouchableBackground(openPanel, Color.rgb(32, 35, 48), Color.rgb(137, 180, 250));
        openPanel.setClickable(true);
        openPanel.setOnClickListener(v -> {
            flashTap(v);
            if (dialogRef[0] != null) {
                dialogRef[0].dismiss();
            }
            openOldSessionDirectly(sessionId, cwd, titleBinding);
        });

        TextView titleText = new TextView(this);
        titleText.setText(visibleTitle);
        titleText.setTextSize(16);
        titleText.setTypeface(Typeface.create("sans-serif-medium", Typeface.NORMAL));
        titleText.setTextColor(Color.rgb(244, 246, 252));
        titleText.setSingleLine(false);
        titleText.setMaxLines(Integer.MAX_VALUE);
        titleText.setEllipsize(null);
        titleText.setIncludeFontPadding(false);
        titleText.setHorizontallyScrolling(false);
        titleText.setLongClickable(titleEnvelope != null);
        titleText.setOnLongClickListener(v -> {
            if (titleEnvelope == null) {
                return false;
            }
            ClipboardManager clipboardManager =
                    (ClipboardManager) getSystemService(Context.CLIPBOARD_SERVICE);
            if (clipboardManager != null) {
                clipboardManager.setPrimaryClip(
                        ClipData.newPlainText(
                                "WEzterm old session title",
                                titleEnvelope.displayTitle
                        )
                );
                toast("Old session title copied");
            }
            return true;
        });

        TextView timeText = new TextView(this);
        timeText.setText(timeLabel);
        timeText.setTextSize(12);
        timeText.setTextColor(Color.rgb(178, 185, 207));
        timeText.setSingleLine(true);
        timeText.setEllipsize(TextUtils.TruncateAt.END);
        timeText.setIncludeFontPadding(false);

        // WHY: the user asked for old sessions to keep the date/time
        // separation while matching Active Sessions' row language. Do not add
        // process names, subagent labels, pane IDs, or tmux details here. The
        // Resume button is the action; the row content stays the saved parent
        // session name so the phone list reads like a normal recent-session
        // picker.
        openPanel.addView(titleText, new LinearLayout.LayoutParams(
                LinearLayout.LayoutParams.MATCH_PARENT,
                LinearLayout.LayoutParams.WRAP_CONTENT
        ));
        openPanel.addView(timeText, new LinearLayout.LayoutParams(
                LinearLayout.LayoutParams.MATCH_PARENT,
                LinearLayout.LayoutParams.WRAP_CONTENT
        ));

        Button resume = new Button(this);
        resume.setText("Resume");
        resume.setAllCaps(false);
        resume.setTextSize(12);
        resume.setTypeface(Typeface.create("sans-serif-medium", Typeface.NORMAL));
        resume.setTextColor(Color.rgb(30, 30, 46));
        setTouchableBackground(resume, Color.rgb(128, 217, 164), Color.rgb(166, 227, 161));
        resume.setPadding(dp(3), 0, dp(3), 0);
        resume.setOnClickListener(v -> {
            flashTap(v);
            if (dialogRef[0] != null) {
                dialogRef[0].dismiss();
            }
            openOldSessionDirectly(sessionId, cwd, titleBinding);
        });

        row.addView(openPanel, new LinearLayout.LayoutParams(
                0,
                LinearLayout.LayoutParams.WRAP_CONTENT,
                1
        ));
        LinearLayout.LayoutParams resumeParams = new LinearLayout.LayoutParams(
                dp(82),
                LinearLayout.LayoutParams.WRAP_CONTENT
        );
        resume.setMinHeight(dp(56));
        resumeParams.setMargins(dp(8), 0, 0, 0);
        row.addView(resume, resumeParams);
        list.addView(row);
    }

