    private void removeXtermBlankTailMask(String reason) {
        boolean keepSessionSwitchLowerShield = shouldKeepSessionSwitchLowerShieldDuringMaskCleanup(reason);
        if (webView == null || Build.VERSION.SDK_INT < Build.VERSION_CODES.KITKAT) {
            if (!keepSessionSwitchLowerShield) {
                forceHideSessionSwitchLowerPaintShield(reason);
            }
            return;
        }
        if (!keepSessionSwitchLowerShield) {
            forceHideSessionSwitchLowerPaintShield(reason);
        }
        // WHY: the live-bottom blank-tail mask exists only to cover stale xterm
        // dotted cells below the live cursor. Read/history mode must show the
        // real scrollback surface, so remove the mask before tmux copy-mode or
        // local history owns the view. v2.33 also removes passive-session-switch
        // lower shields here; keeping them alive made a black covered lower
        // terminal pass the old dotted-field proof even though it was not a real
        // live-bottom render.
        String keepSwitchShield = keepSessionSwitchLowerShield ? "true" : "false";
        webView.evaluateJavascript(
                "(function(){"
                        + "try{"
                        + "var keepSwitchShield=" + keepSwitchShield + ";"
                        + "window.__weztermBlankTailMaskExpiresAt=0;"
                        + "if(window.__weztermBlankTailMaskTimer){clearInterval(window.__weztermBlankTailMaskTimer);window.__weztermBlankTailMaskTimer=null;}"
                        + "if(window.__weztermBlankTailMaskObserver){try{window.__weztermBlankTailMaskObserver.disconnect();}catch(e){}window.__weztermBlankTailMaskObserver=null;}"
                        + "if(!keepSwitchShield){"
                        + "window.__weztermDotRowScrubExpiresAt=0;"
                        + "if(window.__weztermDotRowScrubTimer){clearInterval(window.__weztermDotRowScrubTimer);window.__weztermDotRowScrubTimer=null;}"
                        + "if(window.__weztermDotRowScrubObserver){try{window.__weztermDotRowScrubObserver.disconnect();}catch(e){}window.__weztermDotRowScrubObserver=null;}"
                        + "window.__weztermImmediateDotFillerShieldExpiresAt=0;"
                        + "if(window.__weztermImmediateDotFillerShieldTimer){clearTimeout(window.__weztermImmediateDotFillerShieldTimer);window.__weztermImmediateDotFillerShieldTimer=null;}"
                        + "window.__weztermActiveSwitchLowerDotShieldExpiresAt=0;"
                        + "if(window.__weztermActiveSwitchLowerDotShieldTimer){clearInterval(window.__weztermActiveSwitchLowerDotShieldTimer);window.__weztermActiveSwitchLowerDotShieldTimer=null;}"
                        + "window.__weztermCanvasDotRowScrubExpiresAt=0;"
                        + "if(window.__weztermCanvasDotRowScrubTimer){clearInterval(window.__weztermCanvasDotRowScrubTimer);window.__weztermCanvasDotRowScrubTimer=null;}"
                        + "var hiddenRows=document.querySelectorAll('[data-wezterm-dot-row-hidden=\"1\"]');"
                        + "for(var i=0;i<hiddenRows.length;i++){var row=hiddenRows[i];row.removeAttribute('data-wezterm-dot-row-hidden');row.style.removeProperty('visibility');row.style.removeProperty('color');row.style.removeProperty('-webkit-text-fill-color');row.style.removeProperty('text-shadow');row.style.removeProperty('background');}"
                        + "var activeShield=document.getElementById('wezterm-active-switch-lower-dot-shield');"
                        + "if(activeShield&&activeShield.parentNode){activeShield.parentNode.removeChild(activeShield);}"
                        + "var dotShield=document.getElementById('wezterm-immediate-dot-filler-shield');"
                        + "if(dotShield&&dotShield.parentNode){dotShield.parentNode.removeChild(dotShield);}"
                        + "}"
                        + "var mask=document.getElementById('wezterm-blank-tail-mask');"
                        + "if(mask&&mask.parentNode){mask.parentNode.removeChild(mask);}"
                        + "return 'blank-tail-mask-removed:" + sanitizeJavascriptReason(reason) + "';"
                        + "}catch(e){return 'err';}"
                + "})()",
                null
        );
    }

    private boolean shouldKeepSessionSwitchLowerShieldDuringMaskCleanup(String reason) {
        // WHY: v2.31 intentionally kept lower shields alive during passive
        // session switching so the proof would not show dots. The 2026-06-17
        // black-lower screenshot proved that was a false-green: a covered lower
        // terminal is not a live-bottom render. Cleanup must remove every broad
        // lower shield regardless of reason; only row-level dot scrubber state may
        // survive bounded passive settle.
        return false;
    }

    private void cancelXtermBlankTailMask(String reason) {
        // WHY: `removeXtermBlankTailMask` clears the DOM layer that already exists,
        // while this generation also cancels delayed live-bottom settle callbacks
        // that have not run yet. Without that second guard, typing, tap-to-compose,
        // or one-finger scroll can remove the mask and then see it reinstalled a
        // few frames later as a large black lower-half overlay.
        blankTailMaskGeneration++;
        passiveSwitchXtermSettleGeneration++;
        removeXtermBlankTailMask(reason);
    }

    private void cancelPassiveLiveBottomCallbacksForReadScroll(String reason) {
        // WHY: installed one-finger read scroll is a user-owned state even after the
        // finger lifts. Delayed Bottom/passive-entry/idle visibility callbacks from
        // Send, tab-open, resume, or prior Bottom must not repaint the terminal at
        // live bottom while the user is paused in history. Invalidate the passive
        // trains here; explicit Bottom and down-scroll touch-bottom recovery still
        // use their own current gesture paths.
        entryLiveBottomSettleGeneration++;
        entryBottomCoreGeneration++;
        liveInputVisibilityGeneration++;
        terminalFitGeneration++;
        viewerTypingPositionGeneration++;
        sessionSwitchLiveViewportGeneration++;
        passiveSwitchXtermSettleGeneration++;
        terminalFocusGeneration++;
        lastLiveInputVisibilityBurstAtMs = 0;
        lastTerminalFocusBurstAtMs = 0;
        Log.i(CONTROL_LOG_TAG,
                "stage=read-scroll-guard endpoint=apk result=passive-bottom-cancelled"
                        + " reason=" + safeLogToken(reason));
    }

    private boolean captureRendererGestureScrollActive() {
        // WHY: SCROLL DEEP-HISTORY 2026-07-26 — a user-driven scroll gesture owns the
        // visible viewport. The resulting staged/scrolled frame arrives via idle
        // poll / dom-apply with a NON-touch reason (device proof @6: dom-apply
        // result=suppressed-read-hold reason=poll during an active swipe), so it must
        // commit regardless of endpoint/reason. This is distinct from a genuinely
        // idle read-hold at a held scroll position, where the live tail must stay
        // hidden. Cache-owned (local-history-read-hold) and pre-local-feedback holds
        // still win over this in the commit chain.
        // WHY: an exact cached-history lease already has all MOVE-time data and
        // owns the visible anchor. Publishing generic gesture-scroll permission
        // would let accepted remote/layout frames bypass native read-hold and
        // overwrite that anchor under weak transport.
        if (terminalSnapshotLease != null) {
            return false;
        }
        if (terminalHistoryDragActive
                || terminalHistoryMomentumActive
                || historyScrollRequestInFlight
                || !pendingHistoryScrollWhere.isEmpty()
                || touchScrollAwaitingFirstLocalFeedback()) {
            return true;
        }
        long settleAtMs = lastGestureScrollActivityAtMs;
        return settleAtMs > 0
                && SystemClock.elapsedRealtime() - settleAtMs < CAPTURE_RENDERER_GESTURE_SCROLL_SETTLE_MS;
    }

    private boolean captureRendererGestureScrollCommitWindowActive() {
        // WHY: APK-SCROLL-RELEASE-SNAPBACK — the idle/live visual-commit gate must
        // treat a gesture as "owning the viewport" ONLY while it is genuinely active
        // (finger down, native momentum, or an in-flight/pending history request).
        // captureRendererGestureScrollActive() additionally reports true for
        // CAPTURE_RENDERER_GESTURE_SCROLL_SETTLE_MS (600ms) AFTER the last MOVE so
        // deep-history prefetch/prewarm stays warm. For the COMMIT gate that 600ms
        // post-release tail is exactly what let a live idle-realtime-tick / dom-apply
        // frame commit over a held reading position and snap the rendered viewport to
        // Bottom on finger release (the v233-v238 release snapback). Excluding the
        // settle-tail here lets read-mode-hold (captureRendererReadHoldActive) own the
        // released reading position, while an actually-active gesture still commits its
        // staged/scrolled frames. Prefetch/prewarm sites keep the settle-inclusive
        // captureRendererGestureScrollActive(); only the visual-commit source uses this
        // narrow window. If this is removed the snapback returns; do not fold the
        // settle-tail back into the commit path.
        if (terminalSnapshotLease != null) {
            return false;
        }
        return terminalHistoryDragActive
                || terminalHistoryMomentumActive
                || historyScrollRequestInFlight
                || !pendingHistoryScrollWhere.isEmpty()
                || touchScrollAwaitingFirstLocalFeedback();
    }

    private boolean captureRendererReadHoldActive() {
        return terminalSnapshotLease != null
                || readModeSuppressesKeyboard
                || terminalHistoryViewportActive
                || touchScrollAwaitingFirstLocalFeedback()
                || terminalHistoryDragActive
                || terminalHistoryMomentumActive
                || historyScrollRequestInFlight
                || !pendingHistoryScrollWhere.isEmpty()
                || localHistoryTouchViewportOwnsVisibleSurfaceForReadHold()
                || terminalBottomRestoreInFlight
                // WHY(ROOT-C): a live-TUI scroll-lock is a genuine read-hold; feed nativeReadHold() so
                // the JS commit gate, the active-switch refill (activeSwitchRetainedCommitFullFrameRefetch),
                // and telemetry all treat @8 as held while the user reads.
                || liveTuiScrollLockActive();
    }

    private void syncCaptureRendererReadHold(String reason) {
        if (webView == null || Build.VERSION.SDK_INT < Build.VERSION_CODES.KITKAT) {
            return;
        }
        boolean active = captureRendererReadHoldActive();
        // WHY: APK-SCROLL-RELEASE-SNAPBACK — publish the JS gesture-scroll commit
        // window using the ACTIVE-gesture predicate (no 600ms settle-tail). The tail
        // let __weztermGestureScroll.activeUntil outlive the finger by 600ms, so a
        // post-release sync kept readHoldCommitAllowed() open and the renderer's
        // wrapped r.refresh / idle-realtime-tick / dom-apply committed a live-Bottom
        // frame over the held reading position. With the narrow window, any post-release
        // sync publishes activeUntil<=now and the JS gate returns to the known-good
        // behavior (blocks the live tail during read-hold) while an actually-active
        // gesture still commits its staged deep-history frames.
        boolean gestureScroll = captureRendererGestureScrollCommitWindowActive();
        // WHY(ROOT-B): persistent scrolled-up transcript-TUI hold. True => disables the
        // histSize===0 live-commit exception in the JS gate so nativeReadHold protects the held
        // position; false at the live tail (offset==maxOffset) => follow-live resumes.
        // WHY(ROOT-C): a live-TUI scroll-lock is a detectable, releasable hold (parallel to ROOT-B's
        // offset<maxOffset), so it MUST also disable the histSize===0 live-commit exception in the JS
        // gate — otherwise the idle heartbeat commits straight through and snaps the held view.
        boolean tuiReadHold = localHistoryTouchViewportScrolledUpForReadHold()
                || liveTuiScrollLockActive();
        String quotedReason = JSONObject.quote(sanitizeJavascriptReason(reason));
        // WHY: APK-SCROLL-LOCAL-CACHE-STUTTER-20260709-T5 proved native-side idle
        // commit guards are not enough. The capture renderer itself must know when
        // Android history read mode owns the surface so generic live/idle refreshes
        // do not start network/frame work or mutate accepted-frame seed metadata
        // while the user's finger is moving a local buffer viewport.
        webView.evaluateJavascript(
                "(function(){"
                        + "try{"
                        + "window.__weztermNativeReadHold={active:" + active
                        + ",reason:" + quotedReason
                        + ",updatedAt:Date.now()};"
                        // WHY: SCROLL DEEP-HISTORY 2026-07-26 — publish a self-expiring
                        // gesture-scroll deadline so the JS commit gate can let a
                        // gesture-driven frame through even when it arrives via idle
                        // poll/dom-apply with a non-touch reason.
                        + "window.__weztermGestureScroll={activeUntil:" + (gestureScroll ? "Date.now()+" + CAPTURE_RENDERER_GESTURE_SCROLL_SETTLE_MS : "0") + "};"
                        + "window.__weztermTuiReadHold={active:" + tuiReadHold + "};"
                        + "return window.__weztermNativeReadHold.active?'native-read-hold-active':'native-read-hold-inactive';"
                        + "}catch(e){return 'native-read-hold-error';}"
                + "})()",
                null
        );
    }

    private void clearNativeReadHoldForTouchScrollActionDown(String reason) {
        if (webView == null || Build.VERSION.SDK_INT < Build.VERSION_CODES.KITKAT) {
            return;
        }
        String quotedReason = JSONObject.quote(sanitizeJavascriptReason(reason));
        // WHY: a new physical DOWN supersedes Send/composer/keyboard observation.
        // Clear only the renderer's prior-action hold and publish the new gesture;
        // cached rows, prepared snapshots, anchors, and local viewport stay intact.
        // WHY: [v243 revert of v242] the v242 conditional that preserved
        // native-read-hold on a continuing DOWN is REJECTED: it did not stop the
        // second-touch snapback and it BLOCKED the live-bottom frame on a downward
        // return, clipping the bottom rows (installed red). Unconditional clear is
        // the accepted v241 behavior; the real snapback owner was the DOWN-time
        // renderer nudge-wipe, fixed separately in the touch-start-history path
        // (rebindCaptureRendererTouchNudgeForHeldHistoryStart).
        webView.evaluateJavascript(
                "(function(){try{"
                        + "window.__weztermNativeReadHold={active:false,reason:"
                        + quotedReason
                        + ",updatedAt:Date.now()};"
                        + "window.__weztermGestureScroll={activeUntil:Date.now()+"
                        + CAPTURE_RENDERER_GESTURE_SCROLL_SETTLE_MS
                        + "};"
                        + "return 'touch-scroll-native-read-hold-cleared';"
                        + "}catch(e){return 'touch-scroll-native-read-hold-error';}})()",
                null
        );
    }

    private String sanitizeJavascriptReason(String reason) {
        if (reason == null) {
            return "";
        }
        return reason.replace("\\", "/").replace("'", "").replace("\"", "");
    }

    private void control(String path, String message, boolean refocusTerminal) {
        long readModeGeneration = refocusTerminal ? leaveReadModeForLiveInput() : enterReadMode();
        long touchGeneration = terminalTouchGestureGeneration;
        getJson(path, payload -> {
            if (!payload.optBoolean("ok", false)) {
                String error = payload.optString("error", "Command failed");
                toast(error);
                return;
            }
            if (message != null && !message.isEmpty()) {
                toast(message);
            }
            boolean callbackStillOwnsTouch =
                    readModeGeneration == terminalModeGeneration
                            && touchGeneration == terminalTouchGestureGeneration;
            if (refocusTerminal) {
                if (callbackStillOwnsTouch) {
                    // WHY: generic toolbar/control actions are asynchronous. If the
                    // user starts a newer tap, scroll, picker, or typing action while
                    // the HTTP request is in flight, this callback must not become a
                    // late second IME/focus request that duplicates Samsung/Gboard
                    // composition. `leaveReadModeForLiveInput` already guards read
                    // state, but normal live taps advance only the touch generation,
                    // so both guards are required to block stale Stop/New/Close
                    // callbacks after typing has begun.
                    focusTerminalInputSoon(false);
                }
            } else {
                keepReadModeIfCurrent(readModeGeneration);
            }
            if (!refocusTerminal || callbackStillOwnsTouch) {
                refreshCaptureRendererSoon("control-" + path);
            }
        });
    }

    private void refreshCaptureRendererForTouchBottomRestore(String reason) {
        clearCaptureRendererTouchNudge(reason);
        refreshCaptureRendererNow(reason);
        commitCaptureRendererVisualFrame(reason);
        uiHandler.postDelayed(() -> {
            refreshCaptureRendererNow(reason + "-settle");
            commitCaptureRendererVisualFrame(reason + "-settle");
        }, 120);
    }

    private void refreshCaptureRendererSoon(String reason) {
        refreshCaptureRenderer(reason, true);
    }

    private void refreshCaptureRendererNow(String reason) {
        refreshCaptureRenderer(reason, false);
    }

    private void refreshCaptureRendererForLayoutChange(String reason) {
        long touchGeneration = terminalTouchGestureGeneration;
        refreshCaptureRendererPulseIfAsyncObservationCurrent(reason, touchGeneration);
        // WHY: the read-only capture renderer computes rows inside the WebView.
        // Android can deliver composer/IME layout and WebView resize in separate
        // frames, so one immediate refresh may still use the pre-keyboard height.
        // Bounded follow-ups make the real terminal prompt/cursor row repaint
        // above the native composer without reloading WebView, focusing xterm, or
        // resizing the shared tmux window.
        uiHandler.postDelayed(
                () -> refreshCaptureRendererPulseIfAsyncObservationCurrent(
                        reason + "-layout-settle-1",
                        touchGeneration
                ),
                260
        );
        uiHandler.postDelayed(
                () -> refreshCaptureRendererPulseIfAsyncObservationCurrent(
                        reason + "-layout-settle-2",
                        touchGeneration
                ),
                620
        );
    }

    private void refreshCaptureRendererForComposerTransition(String reason) {
        // WHY: tap-to-type and Send hide/show the native composer while Android's
        // IME is resizing the WebView. The APK now renders through the control
        // server capture renderer, so running the old xterm fit/dot-scrub train
        // during composer transitions only stacks evaluateJavascript/paint work
        // and recreates the black flicker plus multi-second Send feel. Pulse the
        // capture renderer only when it is idle; the locked bottom anchor remains
        // owned by the renderer geometry, and one-finger scroll/zoom/pan stay
        // untouched.
        long touchGeneration = terminalTouchGestureGeneration;
        refreshCaptureRendererPulseIfAsyncObservationCurrent(reason, touchGeneration);
        uiHandler.postDelayed(
                () -> refreshCaptureRendererPulseIfAsyncObservationCurrent(
                        reason + "-composer-settle-1",
                        touchGeneration
                ),
                180
        );
        uiHandler.postDelayed(
                () -> refreshCaptureRendererPulseIfAsyncObservationCurrent(
                        reason + "-composer-settle-2",
                        touchGeneration
                ),
                520
        );
    }

    private void refreshCaptureRendererPulseIfAsyncObservationCurrent(
            String reason,
            long touchGeneration
    ) {
        boolean touchScrollOwnsVisibleSurface = currentApkActionOwnsActiveTouchScroll()
                && (terminalTouchStartedInTerminalBody
                || terminalHistoryDragActive
                || terminalHistoryMomentumActive
                || touchScrollAwaitingFirstLocalFeedback());
        if (touchGeneration != terminalTouchGestureGeneration
                || touchScrollOwnsVisibleSurface) {
            return;
        }
        refreshCaptureRendererPulse(reason);
    }

    private void refreshCaptureRendererForImmediateBottom(String reason) {
        // WHY: the server `/live-bottom` call is already the fast owner for
        // Bottom. Running the old xterm fit/canvas scrub train after an explicit
        // Bottom tap made a sub-second endpoint feel delayed and could repaint
        // while the user was trying to read. Keep one immediate capture refresh
        // for explicit Bottom, then one coalesced settle; tab-open and other
        // passive xterm recovery paths keep their proven guards separately.
        String safeReason = sanitizeJavascriptReason(reason);
        // WHY: inline history replaces the active screen's children. The live
        // frame can still have the renderer's previous hash, so a normal refresh
        // may skip the DOM apply and visually ignore Bottom. Force the explicit
        // post-Bottom frame and require a compositor commit.
        webView.evaluateJavascript(
                "(function(){try{var r=window.__mantisCaptureRenderer;"
                        + "if(r&&typeof r.clearTouchScrollNudge==='function'){r.clearTouchScrollNudge();}"
                        + "if(r&&typeof r.refresh==='function'){r.refresh(true,'" + safeReason + "');return 'capture-bottom-force';}"
                        + "return 'not-capture';}catch(e){return 'capture-bottom-error';}})()",
                null
        );
        commitCaptureRendererVisualFrame(reason);
        uiHandler.postDelayed(() -> {
            refreshCaptureRendererPulse(reason + "-bottom-settle");
            commitCaptureRendererVisualFrame(reason + "-bottom-settle");
        }, 180);
    }

    private void forceCaptureRendererVisualCommit(String reason) {
        // WHY: the user-visible APK regression is a compositor commit problem:
        // leaving and returning to the app runs WebView.onResume() and repaints
        // the capture surface, while send/select only asked renderer JS to
        // refresh. Keep this bounded to explicit send/target changes so scroll,
        // zoom, title authority, and OAuth repair do not inherit a repaint storm.
        refreshCaptureRendererNow(reason);
        commitCaptureRendererVisualFrame(reason);
        uiHandler.postDelayed(() -> {
            refreshCaptureRendererPulse(reason + "-visual-settle");
            commitCaptureRendererVisualFrame(reason + "-visual-settle");
        }, 180);
    }

    private void requestCaptureRendererTouchVisualFrame(String reason) {
        if (webView == null) {
            return;
        }
        if (currentApkActionOwnsActiveTouchScroll()
                && touchScrollFirstLocalFeedbackElapsedMs() < 0) {
            String safeReason = reason == null || reason.trim().isEmpty()
                    ? "touch-scroll"
                    : reason.trim();
            // WHY: the first installed T5 proof after the no-clear-before-hold
            // patch still jumped because WebView completed a scroll visual-state
            // frame before any local owner moved. Defer the compositor commit until
            // `markTouchScrollFirstLocalFeedback` proves a pixel owner exists; this
            // keeps ACTION_DOWN from painting a boundary frame under a stationary
            // finger without weakening later MOVE frame cadence.
            Log.i(CONTROL_LOG_TAG,
                    "stage=capture-renderer endpoint=touch-visual-frame"
                            + " result=deferred-before-local-feedback"
                            + " actionId=" + safeLogToken(activeTouchScrollActionId)
                            + " reason=" + safeLogToken(safeReason)
                            + " windowId=" + safeWindowIdForControlLog(confirmedVisibleTerminalTargetKey()));
            return;
        }
        long now = SystemClock.elapsedRealtime();
        long elapsedMs = lastTouchCaptureRendererVisualFrameAtMs == 0
                ? CAPTURE_RENDERER_TOUCH_VISUAL_FRAME_MIN_MS
                : now - lastTouchCaptureRendererVisualFrameAtMs;
        if (elapsedMs < CAPTURE_RENDERER_TOUCH_VISUAL_FRAME_MIN_MS) {
            return;
        }
        lastTouchCaptureRendererVisualFrameAtMs = now;
        String safeReason = reason == null || reason.trim().isEmpty()
                ? "touch-scroll"
                : reason.trim();
        // WHY: active one-finger scroll and Working/time feedback need Android
        // compositor invalidation around display cadence while backend/tmux row
        // fetches stay throttled. Fetching `/terminal-frame` on every MOVE caused
        // row-step jitter and black flicker, and backend poll timing alone cannot
        // satisfy the 30fps APK complaint.
        Log.i(CONTROL_LOG_TAG,
                "stage=capture-renderer endpoint=touch-visual-frame result=requested"
                        + " actionId=" + safeLogToken(activeTouchScrollActionId)
                        + " reason=" + safeLogToken(safeReason)
                        + " elapsedMs=" + Math.max(0, elapsedMs)
                        + " firstLocalFeedbackElapsedMs=" + touchScrollFirstLocalFeedbackElapsedMs()
                        + " windowId=" + safeWindowIdForControlLog(confirmedVisibleTerminalTargetKey()));
        commitCaptureRendererVisualFrame(safeReason);
    }

    private void scheduleCaptureRendererIdleRealtimeRefresh(String reason) {
        scheduleCaptureRendererIdleRealtimeRefresh(
                reason,
                CAPTURE_RENDERER_IDLE_REALTIME_REFRESH_BASE_MS
        );
    }

    private void scheduleCaptureRendererIdleRealtimeRefresh(String reason, long delayMs) {
        if (webView == null || Build.VERSION.SDK_INT < Build.VERSION_CODES.KITKAT) {
            return;
        }
        long generation = ++captureRendererIdleRealtimeRefreshGeneration;
        Log.i(CONTROL_LOG_TAG,
                "stage=capture-renderer endpoint=idle-refresh result=scheduled"
                        + " reason=" + safeLogToken(reason)
                        + " delayMs=" + Math.max(0, delayMs));
        uiHandler.postDelayed(
                () -> runCaptureRendererIdleRealtimeRefresh(generation, reason),
                Math.max(0, delayMs)
        );
    }

    private void scheduleNextCaptureRendererIdleRealtimeRefresh(long generation, String reason) {
        if (generation != captureRendererIdleRealtimeRefreshGeneration
                || webView == null
                || !activityResumed) {
            return;
        }
        long delayMs = Math.max(
                CAPTURE_RENDERER_IDLE_REALTIME_REFRESH_BASE_MS,
                Math.min(
                        CAPTURE_RENDERER_IDLE_REALTIME_REFRESH_MAX_FAILURE_MS,
                        captureRendererIdleRealtimeRefreshDelayMs
                )
        );
        uiHandler.postDelayed(
                () -> runCaptureRendererIdleRealtimeRefresh(generation, reason),
                delayMs
        );
    }

    private void scheduleCaptureRendererIdleRealtimeRefreshAfterTelemetry(
            String reason,
            long delayMs
    ) {
        if (!activityResumed || webView == null) {
            return;
        }
        scheduleCaptureRendererIdleRealtimeRefresh(reason, delayMs);
    }

    private void stopCaptureRendererIdleRealtimeRefresh(String reason) {
        captureRendererIdleRealtimeRefreshGeneration++;
        clearCaptureRendererIdleRealtimeInFlight(reason);
        captureRendererIdleRealtimeRefreshDelayMs =
                CAPTURE_RENDERER_IDLE_REALTIME_REFRESH_BASE_MS;
        Log.i(CONTROL_LOG_TAG,
                "stage=capture-renderer endpoint=idle-refresh result=stopped"
                        + " reason=" + safeLogToken(reason));
    }

    private boolean captureRendererReadLatchIsStaleAtLiveBottom() {
        // WHY(shared read-hold surface, idle-freeze lane): the read-mode FLAGS
        // (terminalHistoryViewportActive/readModeSuppressesKeyboard) can outlive the real read
        // position — set on scroll-up, never cleared when the user drifts back to live without an
        // explicit Bottom/tap — so shouldSkipCaptureRendererIdleRealtimeRefresh() returns
        // "read-mode-hold" forever and the live tail freezes (device-proved 9min+). Release ONLY
        // when nothing is protected AND the server frontier says we are at the live tail; never
        // while a genuine held read exists (that would repaint a scrolled-up copy-mode read =
        // the v252-254 snapback class this lane must not regress).
        if (!(terminalHistoryViewportActive || readModeSuppressesKeyboard)) {
            return false;
        }
        // WHY(v269 released renderer token): a renderer pointer gesture can
        // have exact same-window visible feedback and a positively accepted
        // release token even when tmux reports the live frontier. That token
        // is the visible read owner; treating only server copy-mode/history as
        // ownership clears native read-hold on the idle tick and lets the
        // frame reconcile snap the held geometry to live bottom.
        if (captureRendererReleasedReadHoldTargetsVisibleSurface()) {
            return false;
        }
        if (localHistoryTouchViewportOwnsVisibleSurfaceForReadHold()) {
            return false; // genuine local held content (incl. ROOT-B histSize==0 offset<maxOffset)
        }
        if (terminalHistoryDragActive
                || terminalHistoryMomentumActive
                || terminalMultiTouchGesture
                || terminalHorizontalPanActive
                || historyScrollRequestInFlight
                || !pendingHistoryScrollWhere.isEmpty()
                || terminalBottomRestoreInFlight
                || touchScrollAwaitingFirstLocalFeedback()) {
            return false; // an active gesture/momentum owns the surface
        }
        // Server-authoritative frontier: tmux only scrolls back in copy-mode/pane-mode, so this
        // mirrors the existing copy-mode test plus the TOUCH_SCROLL_LIVE_BOTTOM_SNAP_LINES band.
        boolean genuinelyScrolledUpServerSide =
                lastAcceptedCaptureRendererCopyModeViewport
                || lastAcceptedCaptureRendererPaneInMode > 0
                || lastAcceptedCaptureRendererScrollPosition > TOUCH_SCROLL_LIVE_BOTTOM_SNAP_LINES;
        return !genuinelyScrolledUpServerSide;
    }

    private void runCaptureRendererIdleRealtimeRefresh(long generation, String reason) {
        if (generation != captureRendererIdleRealtimeRefreshGeneration) {
            return;
        }
        // WHY(shared read-hold surface, idle-freeze lane): clear a stale read-mode latch that has
        // no visible owner and is at the live tail BEFORE the skip check, so the heartbeat resumes
        // instead of skipping "read-mode-hold" forever (device-proved 9min+ freeze). One-shot: the
        // release clears the flags so the next cycle's predicate is false. Frontier-guarded so it
        // can never repaint a genuine scrolled-up read (no v252-254 snapback regression).
        if (captureRendererReadLatchIsStaleAtLiveBottom()) {
            releaseReadHoldAfterNoVisibleScrollOwner("idle-realtime-stale-read-latch");
        }
        String skipReason = shouldSkipCaptureRendererIdleRealtimeRefresh();
        if (!skipReason.isEmpty()) {
            Log.i(CONTROL_LOG_TAG,
                    "stage=capture-renderer endpoint=idle-refresh result=skipped"
                            + " reason=" + safeLogToken(reason)
                            + " skipReason=" + safeLogToken(skipReason));
            scheduleNextCaptureRendererIdleRealtimeRefresh(generation, reason);
            return;
        }
        installCaptureRendererTelemetryHook("idle-refresh");
        // WHY: the installed APK can otherwise show a stale `Working (Nm Ss)`
        // frame until Send/session-switch prods the renderer. This foreground
        // heartbeat only asks the existing capture renderer to poll the confirmed
        // window; it does not reload WebView, change titles, send text, or touch
        // one-finger scroll ownership.
        webView.evaluateJavascript(
                "(function(){"
                        + "try{"
                        + "var r=window.__mantisCaptureRenderer;"
                        + "if(!r||typeof r.refresh!=='function'){return 'idle-refresh-no-renderer';}"
                        + "r.refresh(false,'apk-idle-realtime');"
                        + "return 'idle-refresh-requested';"
                        + "}catch(e){return 'idle-refresh-error';}"
                + "})()",
                result -> {
                    boolean rendererRequested = result != null
                            && result.contains("idle-refresh-requested");
                    if (!rendererRequested) {
                        captureRendererIdleRealtimeRefreshDelayMs =
                                CAPTURE_RENDERER_IDLE_REALTIME_REFRESH_MAX_FAILURE_MS;
                    }
                    Log.i(CONTROL_LOG_TAG,
                            "stage=capture-renderer endpoint=idle-refresh result=complete"
                                    + " " + CAPTURE_RENDERER_IDLE_REFRESH_REASON_LOG
                                    + " jsResult=" + safeLogToken(String.valueOf(result))
                                    + " telemetryInFlight=" + captureRendererIdleRealtimeRefreshInFlight
                                    + " nextDelayMs=" + captureRendererIdleRealtimeRefreshDelayMs
                                    + " windowId=" + safeWindowIdForControlLog(confirmedVisibleTerminalTargetKey()));
                    if (generation == captureRendererIdleRealtimeRefreshGeneration) {
                        scheduleNextCaptureRendererIdleRealtimeRefresh(generation, reason);
                    }
                }
        );
    }

    private String shouldSkipCaptureRendererIdleRealtimeRefresh() {
        if (!activityResumed) {
            return "background";
        }
        if (webView == null) {
            return "no-webview";
        }
        String watchdogTarget = captureRendererIdleRealtimeWatchdogTargetKey();
        if (!hasStableWindowId(watchdogTarget)) {
            return "missing-window";
        }
        if (captureRendererIdleRealtimeRequestBlocksWatchdog(watchdogTarget)) {
            return "in-flight";
        }
        if (touchScrollAwaitingFirstLocalFeedback()) {
            // WHY: the installed transition proof caught a previously scheduled
            // idle `/terminal-frame` response becoming the first readable frame
            // 48ms after ACTION_DOWN and before local finger feedback. Once the
            // user touches the terminal for a one-finger read scroll, local
            // feedback must own the first visible movement.
            return "pre-local-feedback-hold";
        }
        if (localHistoryTouchViewportOwnsVisibleSurfaceForReadHold()) {
            // WHY: APK-SCROLL-FINGER-OWNED-VIEWPORT-IDLE-FRAME-20260710 proved
            // `apk-idle-realtime` `/terminal-frame` responses could still repaint
            // over the APK-local scrollback rows. Idle refreshes may resume after
            // explicit Bottom/live recovery clears this owner, but they cannot be a
            // visible owner while the read-hold viewport is active.
            return "local-history-read-hold";
        }
        if (liveTuiScrollLockActive()) {
            // WHY(ROOT-C): a deliberate scroll-up on a no-scrollback live TUI holds the view; the
            // heartbeat must not fetch+commit a live-bottom frame over it. Releases on return-to-live.
            return "live-tui-scroll-lock";
        }
        if (terminalHistoryViewportActive || readModeSuppressesKeyboard) {
            // WHY: read mode is an intentional history hold. A background
            // heartbeat must not fetch and commit live-prompt frames over the
            // user's stopped one-finger scroll; explicit Bottom and
            // touch-scroll owners still paint.
            return "read-mode-hold";
        }
        if (terminalHistoryDragActive
                || terminalHistoryMomentumActive
                || terminalMultiTouchGesture
                || terminalHorizontalPanActive
                || historyScrollRequestInFlight
                || !pendingHistoryScrollWhere.isEmpty()
                || terminalBottomRestoreInFlight) {
            return "touch-scroll-hold";
        }
        if (sessionSwitchInFlight) {
            long switchAgeMs = sessionSwitchStartedAtMs <= 0
                    ? 0
                    : SystemClock.elapsedRealtime() - sessionSwitchStartedAtMs;
            if (switchAgeMs < CAPTURE_RENDERER_SESSION_SWITCH_REFRESH_GRACE_MS) {
                return "switch-in-flight";
            }
            // WHY: a slow `/select-live` or `/active` call already proved it can
            // exceed Android's read timeout and leave the read-only renderer as a
            // black box while every idle repaint logs `switch-in-flight`. After the
            // short shield grace, keep the renderer heartbeat alive for the current
            // stable target instead of letting backend latency freeze visible paint.
            Log.i(CONTROL_LOG_TAG,
                    "stage=capture-renderer endpoint=idle-refresh result=allowed"
                            + " reason=slow-switch-repaint"
                            + " switchAgeMs=" + Math.max(0, switchAgeMs)
                            + " windowId=" + safeWindowIdForControlLog(confirmedVisibleTerminalTargetKey()));
        }
        return "";
    }

    private String captureRendererIdleRealtimeWatchdogTargetKey() {
        if (hasStableWindowId(captureRendererIdleRealtimeExpectedWindowId)) {
            // WHY: in-place Active A -> B updates the renderer target without a
            // navigation, so the URL can remain A until B's first accepted frame.
            // The centralized target owner already revoked A atomically; admit
            // exact expected B telemetry now so B can become confirmed instead
            // of deadlocking the watchdog behind its own confirmation gate.
            return captureRendererIdleRealtimeExpectedWindowId.trim();
        }
        if (hasStableWindowId(captureRendererWindowTargetKey)) {
            return captureRendererWindowTargetKey.trim();
        }
        return confirmedVisibleTerminalTargetKey();
    }

    private boolean captureRendererIdleRealtimeRequestBlocksWatchdog(String watchdogTarget) {
        if (!captureRendererIdleRealtimeRefreshInFlight) {
            return false;
        }
        if (!hasStableWindowId(watchdogTarget)
                || !watchdogTarget.trim().equals(
                        captureRendererIdleRealtimeInFlightRequestedWindowId)) {
            // WHY: target A's unresolved fetch cannot hold target B behind the
            // stale timeout. The new configured target gets an immediate clean
            // watchdog epoch; A's eventual response remains generation-rejected.
            invalidateCaptureRendererIdleRealtimeInFlight("watchdog-target-changed");
            return false;
        }
        long inFlightAgeMs = captureRendererIdleRealtimeInFlightStartedAtMs <= 0
                ? CAPTURE_RENDERER_IDLE_REALTIME_IN_FLIGHT_STALE_MS
                : Math.max(
                        0,
                        SystemClock.elapsedRealtime()
                                - captureRendererIdleRealtimeInFlightStartedAtMs
                );
        if (inFlightAgeMs < CAPTURE_RENDERER_IDLE_REALTIME_IN_FLIGHT_STALE_MS) {
            return true;
        }
        Log.i(CONTROL_LOG_TAG,
                "stage=capture-renderer endpoint=idle-refresh result=stale-fail-open"
                        + " windowId=" + safeWindowIdForControlLog(watchdogTarget)
                        + " frameWindowId=" + safeWindowIdForControlLog(
                                captureRendererIdleRealtimeInFlightFrameWindowId)
                        + " telemetryGeneration="
                        + captureRendererIdleRealtimeInFlightTelemetryGeneration
                        + " inFlightAgeMs=" + inFlightAgeMs);
        clearCaptureRendererIdleRealtimeInFlight("stale-fail-open");
        captureRendererIdleRealtimeRefreshDelayMs =
                CAPTURE_RENDERER_IDLE_REALTIME_REFRESH_MAX_FAILURE_MS;
        return false;
    }

    // WHY: FIX D (smoothness) — record a CHANGED accepted frame and (re)start the
    // local composite pump. Called from rememberAcceptedCaptureRendererFrame only
    // when the accepted frame's hash/window actually changed, so a static live
    // terminal (unchanged polls) lets the pump auto-stop for battery safety while
    // active output keeps it alive across the 2s poll.
    private void onCaptureRendererStreamingFrameForSmoothness() {
        lastAcceptedCaptureRendererFrameForSmoothnessAtMs = SystemClock.elapsedRealtime();
        startCaptureRendererSmoothnessCompositingIfIdle();
    }

    private void startCaptureRendererSmoothnessCompositingIfIdle() {
        if (captureRendererSmoothnessCompositingActive
                || webView == null
                || !captureRendererSmoothnessCompositingAllowed()) {
            return;
        }
        captureRendererSmoothnessCompositingActive = true;
        Choreographer.getInstance().postFrameCallback(captureRendererSmoothnessFrameCallback);
    }

    // WHY: FIX D (smoothness) — one local composite per display frame. This is a
    // pure client-side recomposite of the DOM the SSE feed already updated: no
    // network, no /terminal-frame fetch, so it cannot clobber scrollback, viewport,
    // or the 2s poll's cache. It self-terminates (clears the running flag and stops
    // re-posting) as soon as it is unsafe/useless — read-hold, any touch/scroll
    // lane, backgrounded, or no changed frame within the idle-stop window.
    private final Choreographer.FrameCallback captureRendererSmoothnessFrameCallback =
            new Choreographer.FrameCallback() {
                @Override
                public void doFrame(long frameTimeNanos) {
                    if (webView == null
                            || !captureRendererSmoothnessCompositingAllowed()
                            || SystemClock.elapsedRealtime()
                                    - lastAcceptedCaptureRendererFrameForSmoothnessAtMs
                                    > CAPTURE_RENDERER_SMOOTHNESS_IDLE_STOP_MS) {
                        captureRendererSmoothnessCompositingActive = false;
                        return;
                    }
                    // WHY: reuse the exact lightweight composite trigger the 2s idle
                    // commit uses (webView.postInvalidateOnAnimation). Do NOT call
                    // commitCaptureRendererVisualFrame here: it also posts a logged
                    // VisualStateCallback, which per display frame would be log/CPU
                    // spam. This only asks the compositor to redraw current pixels.
                    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.JELLY_BEAN) {
                        webView.postInvalidateOnAnimation();
                    } else {
                        webView.postInvalidate();
                    }
                    Choreographer.getInstance().postFrameCallback(this);
                }
            };

    // WHY: FIX D (smoothness) — composite only when safe AND useful. Mirrors the
    // EXACT touch/scroll guard set that handleCaptureRendererIdleCommitRequest uses
    // (noActiveTouchOrScroll) plus read-hold and foreground checks, so the pump
    // never fights one-finger scroll, momentum, horizontal pan, a pending/in-flight
    // history scroll, or bottom restore, never repaints while read-hold protects
    // copy-mode scrollback, and never runs while backgrounded.
    private boolean captureRendererSmoothnessCompositingAllowed() {
        // WHY: BUG #26 (live counters step ~2s instead of every frame) — this pump is
        // a pure compositor redraw of the DOM the SSE feed already mutated
        // (postInvalidateOnAnimation only: no network, no /terminal-frame, no commit),
        // so it cannot clobber scrollback or yank the viewport. It must NOT yield to
        // read-hold: gating on captureRendererReadHoldActive() killed smooth
        // compositing the instant any scroll/read gesture set read-hold — and
        // permanently whenever read-hold latched (e.g. a histSize=0 alt-screen pane) —
        // which is exactly the 2s stepping the user reports. The active-gesture guards
        // below (drag/momentum/pan/bottom-restore) still stop it fighting a live
        // finger, and activityResumed + the idle-stop window still bound CPU.
        return activityResumed
                && !terminalHistoryDragActive
                && !terminalMultiTouchGesture
                && !terminalHorizontalPanActive
                && !historyScrollRequestInFlight
                && !terminalHistoryMomentumActive
                && pendingHistoryScrollWhere.isEmpty()
                && !terminalBottomRestoreInFlight;
    }

    private void commitCaptureRendererVisualFrame(String reason) {
        if (webView == null) {
            return;
        }
        webView.invalidate();
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.JELLY_BEAN) {
            webView.postInvalidateOnAnimation();
        } else {
            webView.postInvalidate();
        }
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M) {
            long requestId = SystemClock.uptimeMillis();
            webView.postVisualStateCallback(requestId, new WebView.VisualStateCallback() {
                @Override
                public void onComplete(long completedRequestId) {
                    Log.i(CONTROL_LOG_TAG,
                            "stage=capture-renderer endpoint=visual-state result=complete"
                                    + " actionId=" + safeLogToken(currentApkActionIdForLog())
                                    + " tapId=" + safeLogToken(currentApkTapIdForLog())
                                    + " actionKind=" + safeLogToken(currentApkActionKindForLog())
                                    + " reason=" + safeLogToken(reason)
                                    + " firstLocalFeedbackElapsedMs=" + currentApkFirstLocalFeedbackElapsedMsForLog()
                                    + " actionElapsedMs=" + currentApkActionElapsedMs()
                                    + " requestId=" + completedRequestId);
                }
            });
        }
    }

    private void syncCaptureRendererAfterViewerScaleChange(String reason) {
        if (webView == null) {
            return;
        }
        long generation = ++captureRendererScaleSyncGeneration;
        invalidateWebViewAfterViewerScale(reason);
        if (terminalMultiTouchGesture) {
            // WHY: a live two-finger pinch already gives WebView ownership of native
            // scale and pan. Calling into JS to mutate capture-renderer geometry on
            // every onScaleChanged tick fights Android's in-progress gesture and is
            // perceived as jumpy/spazzing zoom. Keep compositor invalidation during
            // the pinch, then do one geometry-only sync after release.
            captureRendererScaleSyncDeferredUntilTouchRelease = true;
            captureRendererScaleSyncDeferredReason = reason;
            syncCaptureRendererGeometryOnlyForLivePinch(reason);
            uiHandler.postDelayed(() -> {
                if (generation != captureRendererScaleSyncGeneration
                        || terminalMultiTouchGesture
                        || webView == null
                        || !captureRendererScaleSyncDeferredUntilTouchRelease) {
                    return;
                }
                flushDeferredCaptureRendererScaleSync("scale-settle");
            }, 180);
            return;
        }
        syncCaptureRendererViewportOnlyForScale(reason);
        uiHandler.postDelayed(() -> {
            if (generation != captureRendererScaleSyncGeneration || webView == null) {
                return;
            }
            invalidateWebViewAfterViewerScale(reason + "-settle");
            syncCaptureRendererViewportOnlyForScale(reason + "-settle");
        }, 96);
    }

    private void syncCaptureRendererGeometryOnlyForLivePinch(String reason) {
        if (webView == null || Build.VERSION.SDK_INT < Build.VERSION_CODES.KITKAT) {
            return;
        }
        long now = System.currentTimeMillis();
        if (now - lastCaptureRendererGeometryOnlyScaleSyncAtMs < PINCH_GEOMETRY_ONLY_SYNC_MIN_MS) {
            return;
        }
        lastCaptureRendererGeometryOnlyScaleSyncAtMs = now;
        // WHY: physical zoom-out can expose a newly visible region before release.
        // During the pinch we may update only visualViewport geometry/prepaint; row
        // refresh remains deferred until release so pinch does not jump under the
        // fingers or start network/tmux work mid-gesture.
        webView.evaluateJavascript(captureRendererGeometryOnlyLivePinchScript(reason), null);
    }

    private String captureRendererGeometryOnlyLivePinchScript(String reason) {
        String safeReason = sanitizeJavascriptReason(reason);
        return "(function(){"
                + "try{"
                + "var r=window.__mantisCaptureRenderer;"
                + "if(!r){return 'not-capture';}"
                + "if(typeof r.syncViewportGeometryOnly==='function'){r.syncViewportGeometryOnly('apk-scale-geometry-" + safeReason + "');return 'capture-geometry-only';}"
                + "return 'capture-geometry-missing';"
                + "}catch(e){return 'capture-geometry-error';}"
                + "})()";
    }

    private void flushDeferredCaptureRendererScaleSync(String reason) {
        if (!captureRendererScaleSyncDeferredUntilTouchRelease || webView == null) {
            return;
        }
        captureRendererScaleSyncDeferredUntilTouchRelease = false;
        String deferredReason = captureRendererScaleSyncDeferredReason == null
                || captureRendererScaleSyncDeferredReason.trim().isEmpty()
                ? reason
                : captureRendererScaleSyncDeferredReason;
        invalidateWebViewAfterViewerScale(reason);
        syncCaptureRendererViewportOnlyForScale(deferredReason + "-" + reason);
    }

    private void invalidateWebViewAfterViewerScale(String reason) {
        if (webView == null) {
            return;
        }
        // WHY: zoom-out can reveal WebView pixels that the Android compositor has
        // not repainted yet, leaving a temporary black panel even though the
        // capture renderer still owns the same terminal rows. Invalidate only the
        // viewer/capture surface; do not reload WebView, resize tmux, reset zoom,
        // or route two-finger gestures through `/touch-scroll`.
        webView.invalidate();
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.JELLY_BEAN) {
            webView.postInvalidateOnAnimation();
        } else {
            webView.postInvalidate();
        }
    }

    private void syncCaptureRendererViewportOnlyForScale(String reason) {
        if (webView == null || Build.VERSION.SDK_INT < Build.VERSION_CODES.KITKAT) {
            return;
        }
        webView.evaluateJavascript(captureRendererViewportOnlyScaleReturnScript(reason), null);
    }

    private String captureRendererViewportOnlyScaleReturnScript(String reason) {
        String safeReason = sanitizeJavascriptReason(reason);
        return "(function(){"
                + "try{"
                + "var r=window.__mantisCaptureRenderer;"
                + "if(!r){return 'not-capture';}"
                + "if(typeof r.syncViewportOnly==='function'){r.syncViewportOnly('apk-scale-" + safeReason + "');return 'capture-scale-sync';}"
                + "if(typeof r.measure==='function'){r.measure();return 'capture-scale-measure';}"
                + "return 'capture-scale-missing';"
                + "}catch(e){return 'capture-scale-error';}"
        + "})()";
    }

    private void refreshCaptureRenderer(String reason, boolean includeFollowUp) {
        if (webView == null || Build.VERSION.SDK_INT < Build.VERSION_CODES.KITKAT) {
            return;
        }
        // WHY: APK scroll/buttons still mutate tmux state through the proven
        // `/scroll` and `/touch-scroll` endpoints. The v2.53 read-only renderer
        // regressed by polling slowly and looking frozen after those controls.
        // Refresh only the capture renderer object; never reload the WebView,
        // focus xterm, or resize tmux from this path.
        String followUp = includeFollowUp ? "setTimeout(run,180);" : "";
        webView.evaluateJavascript(
                "(function(){"
                        + "try{"
                        + "var r=window.__mantisCaptureRenderer;"
                        + "if(r&&typeof r.refresh==='function'){"
                        + "var run=function(){r.refresh(false,'" + sanitizeJavascriptReason(reason) + "');};"
                        + "if(typeof requestAnimationFrame==='function'){requestAnimationFrame(run);}else{setTimeout(run,16);}"
                        + followUp
                        + "return 'capture-refresh';"
                        + "}"
                        + "return 'not-capture';"
                        + "}catch(e){return 'err';}"
                + "})()",
                null
        );
    }

    private static String sha256Utf8Exact(String value) {
        if (value == null) {
            return "";
        }
        String body = value;
        for (int index = 0; index < body.length(); index++) {
            char codeUnit = body.charAt(index);
            if (Character.isHighSurrogate(codeUnit)) {
                if (index + 1 >= body.length()
                        || !Character.isLowSurrogate(body.charAt(index + 1))) {
                    return "";
                }
                index++;
            } else if (Character.isLowSurrogate(codeUnit)) {
                return "";
            }
        }
        try {
            ByteBuffer exactUtf8 = StandardCharsets.UTF_8.newEncoder()
                    .onMalformedInput(CodingErrorAction.REPORT)
                    .onUnmappableCharacter(CodingErrorAction.REPORT)
                    .encode(CharBuffer.wrap(body));
            MessageDigest sha256 = MessageDigest.getInstance("SHA-256");
            sha256.update(exactUtf8);
            byte[] digest = sha256.digest();
            char[] alphabet = "0123456789abcdef".toCharArray();
            char[] encoded = new char[digest.length * 2];
            for (int index = 0; index < digest.length; index++) {
                int octet = digest[index] & 0xff;
                encoded[index * 2] = alphabet[octet >>> 4];
                encoded[index * 2 + 1] = alphabet[octet & 0x0f];
            }
            return new String(encoded);
        } catch (Exception unavailableSha256) {
            // SHA-256 is mandatory on Android. A missing digest blocks an exact
            // body receipt; it must never fall back to collision-prone FNV32.
            return "";
        }
    }

    private final class CaptureRendererBridge {
        @JavascriptInterface
        public String bodySha256ForTelemetry(String body) {
            // WHY: hash the in-process immutable body snapshot and return only
            // its digest. Terminal contents are never logged or persisted by
            // this bridge, while malformed UTF-16 fails closed before UTF-8
            // replacement could collapse distinct bodies.
            return sha256Utf8Exact(body);
        }

        @JavascriptInterface
        public void onCaptureRendererTelemetry(String payloadJson) {
            uiHandler.post(() -> handleCaptureRendererTelemetry(payloadJson));
        }

        @JavascriptInterface
        public void onSessionStatusChanged(String statusRevision) {
            // WHY: FEATURE the generated renderer calls this (guarded) on each ~2s
            // poll when the server-side session status revision changes. Marshal
            // to the UI thread and refresh the toolbar status dot plus any open
            // Active dialog rows so status dots update even while the Active picker
            // is closed. Deduped on the revision token to avoid needless polls.
            uiHandler.post(() -> handleSessionStatusChanged(statusRevision));
        }

        @JavascriptInterface
        public void requestIdleVisualCommit(String payloadJson) {
            uiHandler.post(() -> handleCaptureRendererIdleCommitRequest(payloadJson));
        }

        @JavascriptInterface
        public void requestReadyHistoryRefill(String payloadJson) {
            // WHY: the generated renderer asks from its ordinary background poll,
            // never from DOWN/MOVE/UP. Keep network/cache preparation outside the
            // native gesture and kinetic frame owners.
            uiHandler.post(() -> handleReadyHistoryRefillRequest(payloadJson));
        }

        @JavascriptInterface
        public boolean allowInlineLocalHistoryPaint(
                String source,
                String dispatchActionId,
                long requestSerial,
                String where,
                int localViewportOffset,
                int localHistoryCachedRows
        ) {
            return allowInlineLocalHistoryPaintFromRenderer(
                    source,
                    dispatchActionId,
                    requestSerial,
                    where,
                    localViewportOffset,
                    localHistoryCachedRows
            );
        }

        @JavascriptInterface
        public String beginCaptureRendererPointerGesture() {
            String actionId = captureRendererPointerActionId == null
                    ? ""
                    : captureRendererPointerActionId.trim();
            String windowId = captureRendererPointerWindowId == null
                    ? ""
                    : captureRendererPointerWindowId.trim();
            long visualGeneration = captureRendererPointerVisualGeneration;
            if (!captureRendererPointerTouchForwarding
                    || actionId.isEmpty()
                    || !hasStableWindowId(windowId)
                    || visualGeneration != touchScrollVisualNudgeGeneration) {
                return "{\"enabled\":false}";
            }
            Log.i(CONTROL_LOG_TAG,
                    "stage=renderer-pointer-input endpoint=renderer"
                            + " result=POINTER_DOWN_ADMITTED"
                            + " actionId=" + safeLogToken(actionId)
                            + " windowId=" + safeWindowIdForControlLog(windowId)
                            + " visualGeneration=" + visualGeneration);
            // One gesture-start bridge read binds the renderer-local pointer
            // owner. MOVE performs no Java bridge, HTTP, DOM scan, or callback.
            return "{\"enabled\":true,\"actionId\":"
                    + JSONObject.quote(actionId)
                    + ",\"windowId\":" + JSONObject.quote(windowId)
                    + ",\"visualGeneration\":" + visualGeneration + "}";
        }

        @JavascriptInterface
        public String finishCaptureRendererPointerGesture(
                String dispatchActionId,
                long dispatchVisualGeneration
        ) {
            String dispatch = dispatchActionId == null
                    ? ""
                    : dispatchActionId.trim();
            String expected = captureRendererPointerReleaseActionId == null
                    ? ""
                    : captureRendererPointerReleaseActionId.trim();
            if (dispatch.isEmpty()
                    || !dispatch.equals(expected)
                    || dispatchVisualGeneration
                    != captureRendererPointerReleaseVisualGeneration) {
                return "cancel";
            }
            return captureRendererPointerReleaseDeferredForMomentum
                    ? "defer"
                    : "release";
        }

        @JavascriptInterface
        public void onCaptureRendererPointerFeedback(
                String dispatchActionId,
                long dispatchVisualGeneration,
                double appliedPx,
                double rendererFrameElapsedMs
        ) {
            String dispatch = dispatchActionId == null
                    ? ""
                    : dispatchActionId.trim();
            String activePointer = captureRendererPointerActionId == null
                    ? ""
                    : captureRendererPointerActionId.trim();
            String releasedPointer =
                    captureRendererPointerReleaseActionId == null
                            ? ""
                            : captureRendererPointerReleaseActionId.trim();
            boolean exactActive = dispatch.equals(activePointer)
                    && dispatchVisualGeneration
                    == captureRendererPointerVisualGeneration;
            boolean exactReleased = dispatch.equals(releasedPointer)
                    && dispatchVisualGeneration
                    == captureRendererPointerReleaseVisualGeneration;
            if (dispatch.isEmpty()
                    || (!exactActive && !exactReleased)
                    || Math.abs(appliedPx) < 0.5) {
                return;
            }
            uiHandler.post(() -> {
                String currentActionId = activeTouchScrollActionId == null
                        ? ""
                        : activeTouchScrollActionId.trim();
                if (!dispatch.equals(currentActionId)
                        && !dispatch.equals(
                        captureRendererPointerReleaseActionId)) {
                    return;
                }
                markTouchScrollFirstLocalFeedback(
                        "renderer",
                        "renderer-pointer"
                );
                Log.i(CONTROL_LOG_TAG,
                        "stage=touch-nudge endpoint=renderer"
                                + " actionId=" + safeLogToken(dispatch)
                                + " result=DIRECT_POINTER_APPLIED"
                                + " appliedPx="
                                + touchLogFloat((float) appliedPx)
                                + " rendererFrameElapsedMs="
                                + touchLogFloat(
                                (float) rendererFrameElapsedMs)
                                + " visualGeneration="
                                + dispatchVisualGeneration
                                + " firstLocalFeedbackElapsedMs="
                                + touchScrollFirstLocalFeedbackElapsedMs());
            });
        }

        @JavascriptInterface
        public boolean allowCaptureRendererTouchNudge(
                String dispatchActionId,
                long dispatchVisualGeneration
        ) {
            // WHY(v264 post-UP hard stop): this bridge call is synchronous from
            // the queued WebView script. Volatile native ownership therefore
            // fences work that Chromium received before ACTION_UP but executes
            // after Java invalidates the physical touch generation.
            if (dispatchVisualGeneration != touchScrollVisualNudgeGeneration) {
                return false;
            }
            String dispatch = dispatchActionId == null
                    ? ""
                    : dispatchActionId.trim();
            String active = activeTouchScrollActionId == null
                    ? ""
                    : activeTouchScrollActionId.trim();
            return !dispatch.isEmpty() && dispatch.equals(active);
        }

        @JavascriptInterface
        public boolean allowActiveSwitchCachedBodyPaint(
                String cachedWindowId,
                long transitionGeneration,
                long cacheAgeMs,
                String frameHash,
                int bodyLength,
                int rowCount
        ) {
            // WHY: the in-page cache is display-only acceleration. Native exact
            // target/generation admission prevents a delayed A response or stale
            // B entry from becoming selected-body authority; fresh frame+DOM still
            // owns canonical title/body/Send publication.
            return ActiveSwitchSelectedBodyCachePolicy.canPaint(
                    activityResumed,
                    cachedWindowId,
                    selectedPhoneWindowId,
                    pendingActiveSwitchTitleWindowId,
                    transitionGeneration,
                    pendingActiveSwitchTitleGeneration,
                    cacheAgeMs,
                    frameHash,
                    bodyLength,
                    rowCount
            );
        }
    }

    private void handleSessionStatusChanged(String statusRevision) {
        String normalized = statusRevision == null ? "" : statusRevision.trim();
        // WHY: DEDUPE on the revision token. null sentinel forces the first call
        // through; thereafter an identical revision is skipped so the ~2s renderer
        // heartbeat does not re-poll /tabs and /active on every unchanged tick.
        if (lastSeenSessionStatusRevision != null
                && lastSeenSessionStatusRevision.equals(normalized)) {
            return;
        }
        lastSeenSessionStatusRevision = normalized;
        // WHY: reuse the two proven refresh entrypoints rather than hand-rolling a
        // new /tabs->dot render. refreshActiveSessionsDialogIfShowing re-fetches
        // /tabs?light=1 and re-renders the Active dialog rows via
        // applySessionStatusDot when the picker is open (and no-ops when closed);
        // scheduleToolbarStatusDotRefresh repaints the toolbar dot from the same
        // read-only poll the toolbar already trusts. Both guard generation and
        // resumed state, so a stale/dialog-closed call is a safe no-op.
        refreshActiveSessionsDialogIfShowing("session-status-bridge");
        scheduleToolbarStatusDotRefresh(0);
    }

    private void handleReadyHistoryRefillRequest(String payloadJson) {
        JSONObject payload = parseCaptureRendererBridgePayload(payloadJson);
        if (payload == null || !payload.optBoolean("needsReady", false)
                || payload.optBoolean("trueTopPrepared", false)) {
            return;
        }
        String windowId = payload.optString("windowId", "").trim();
        String nextStart = normalizeLocalHistoryStart(payload.optString("nextStart", ""));
        String generationKey = payload.optString("generationKey", "").trim();
        int measuredCols = payload.optInt("measuredCols", -1);
        String visibleWindowId = confirmedVisibleTerminalTargetKey();
        if (!activityResumed || !hasStableWindowId(windowId) || nextStart.isEmpty() || generationKey.isEmpty()
                || measuredCols < 20 || !windowId.equals(visibleWindowId)) {
            notifyReadyHistoryRefillFailed("invalid-background-refill-owner");
            return;
        }
        if (windowId.equals(lastAcceptedCaptureRendererFrameWindowId)) {
            lastAcceptedCaptureRendererCols = measuredCols;
        }
        LocalHistoryRequest request = localHistoryRequestForTouchTarget(windowId);
        JSONObject cursor = new JSONObject();
        try {
            cursor.put("prevStart", nextStart);
            cursor.put("generationKey", generationKey);
        } catch (Exception ignored) {
            notifyReadyHistoryRefillFailed("invalid-next-start");
            return;
        }
        Log.i(CONTROL_LOG_TAG,
                "stage=local-history-ready endpoint=renderer result=background-refill-requested"
                        + " windowId=" + safeWindowIdForControlLog(windowId)
                        + " start=" + safeLogToken(nextStart)
                        + " cols=" + measuredCols
                        + " remainingPreparedPx=" + payload.optInt("remainingPreparedPx", -1)
                        + " prefetchHorizonPx=" + payload.optInt("prefetchHorizonPx", -1));
        prefetchAdjacentLocalHistoryChunkForTouch(request, cursor, activeHistoryScrollRequestSerial);
    }

    private void handleCaptureRendererIdleRealtimeTelemetry(JSONObject payload) {
        if (payload == null
                || !"/terminal-frame".equals(payload.optString("endpoint", ""))) {
            return;
        }
        String stage = payload.optString("stage", "").trim();
        long telemetryGeneration = payload.optLong("generation", -1);
        String requestedWindowId = stableWindowIdFromPayload(
                payload,
                payload.optString("windowId", ""),
                "requestedWindowId",
                "displayWindowId",
                "windowId"
        );
        if ("scheduled".equals(stage)) {
            String watchdogTarget = captureRendererIdleRealtimeWatchdogTargetKey();
            if (telemetryGeneration < 0
                    || !hasStableWindowId(requestedWindowId)
                    || !hasStableWindowId(watchdogTarget)
                    || !requestedWindowId.equals(watchdogTarget)) {
                Log.i(CONTROL_LOG_TAG,
                        "stage=capture-renderer endpoint=idle-refresh result=scheduled-ignored"
                                + " windowId=" + safeWindowIdForControlLog(requestedWindowId)
                                + " watchdogWindowId=" + safeWindowIdForControlLog(watchdogTarget)
                                + " telemetryGeneration=" + telemetryGeneration);
                return;
            }
            if (captureRendererIdleRealtimeRefreshInFlight
                    && requestedWindowId.equals(
                            captureRendererIdleRealtimeInFlightRequestedWindowId)
                    && telemetryGeneration
                            <= captureRendererIdleRealtimeInFlightTelemetryGeneration) {
                return;
            }
            captureRendererIdleRealtimeRefreshInFlight = true;
            captureRendererIdleRealtimeInFlightTelemetryGeneration = telemetryGeneration;
            captureRendererIdleRealtimeInFlightStartedAtMs = SystemClock.elapsedRealtime();
            captureRendererIdleRealtimeInFlightRequestedWindowId = requestedWindowId;
            captureRendererIdleRealtimeInFlightFrameWindowId = requestedWindowId;
            Log.i(CONTROL_LOG_TAG,
                    "stage=capture-renderer endpoint=idle-refresh result=telemetry-in-flight"
                            + " windowId=" + safeWindowIdForControlLog(requestedWindowId)
                            + " telemetryGeneration=" + telemetryGeneration);
            return;
        }
        if (!"response".equals(stage)
                || !captureRendererIdleRealtimeRefreshInFlight) {
            return;
        }
        String frameWindowId = captureRendererFrameWindowId(payload, requestedWindowId);
        if (telemetryGeneration
                        != captureRendererIdleRealtimeInFlightTelemetryGeneration
                || !requestedWindowId.equals(
                        captureRendererIdleRealtimeInFlightRequestedWindowId)
                || !captureRendererFrameTargetsVisibleWindow(
                        payload,
                        frameWindowId,
                        requestedWindowId
                )) {
            // WHY: an old target/generation response is paint telemetry only; it
            // cannot clear a newer request's pressure gate. Marked retargets stay
            // valid through the existing acceptedWindowIds/replacement relation.
            Log.i(CONTROL_LOG_TAG,
                    "stage=capture-renderer endpoint=idle-refresh result=response-ignored"
                            + " windowId=" + safeWindowIdForControlLog(requestedWindowId)
                            + " frameWindowId=" + safeWindowIdForControlLog(frameWindowId)
                            + " telemetryGeneration=" + telemetryGeneration
                            + " inFlightWindowId=" + safeWindowIdForControlLog(
                                    captureRendererIdleRealtimeInFlightRequestedWindowId)
                            + " inFlightTelemetryGeneration="
                            + captureRendererIdleRealtimeInFlightTelemetryGeneration);
            return;
        }
        captureRendererIdleRealtimeInFlightFrameWindowId = frameWindowId;
        int status = payload.optInt("status", -1);
        boolean responseAccepted = status >= 200
                && status < 300
                && payload.optBoolean("acceptedFrame", false);
        long previousDelayMs = captureRendererIdleRealtimeRefreshDelayMs;
        // WHY(active-switch wait-for-ready 2026-07-27): a non-accepted retained-200 body
        // is not a failure to back off from — the control server is still proving
        // continuity and can advertise when the next frame is ready (retryAfterMs /
        // remainingSeconds). Blindly doubling to the 4000ms clamp added up to ~4s of
        // blank latency per switch. Honor a server-advertised wait with ONE refresh
        // (capped 8s); hold BASE cadence while paint-only frames are already repainting
        // the retained body; only fall back to the classic doubling backoff when the
        // server gives no readiness hint.
        boolean paintOnlyFrame = payload.optBoolean("paintOnly", false);
        double advertisedRetryAfterMs = payload.optDouble("retryAfterMs", -1);
        double advertisedRemainingSeconds = payload.optDouble("remainingSeconds", -1);
        long serverAdvertisedWaitMs = -1L;
        if (advertisedRetryAfterMs > 0) {
            serverAdvertisedWaitMs = (long) Math.ceil(advertisedRetryAfterMs);
        } else if (advertisedRemainingSeconds > 0) {
            serverAdvertisedWaitMs = (long) Math.ceil(advertisedRemainingSeconds * 1000.0);
        }
        clearCaptureRendererIdleRealtimeInFlight("terminal-frame-response");
        String idleRealtimeRefreshReason;
        if (responseAccepted) {
            captureRendererIdleRealtimeRefreshDelayMs =
                    CAPTURE_RENDERER_IDLE_REALTIME_REFRESH_BASE_MS;
            idleRealtimeRefreshReason = "terminal-frame-response";
        } else if (serverAdvertisedWaitMs > 0) {
            captureRendererIdleRealtimeRefreshDelayMs =
                    Math.min(8000L, serverAdvertisedWaitMs);
            idleRealtimeRefreshReason = "terminal-frame-response-server-wait";
        } else if (paintOnlyFrame) {
            captureRendererIdleRealtimeRefreshDelayMs =
                    CAPTURE_RENDERER_IDLE_REALTIME_REFRESH_BASE_MS;
            idleRealtimeRefreshReason = "terminal-frame-response-paint-only";
        } else {
            captureRendererIdleRealtimeRefreshDelayMs = Math.min(
                    CAPTURE_RENDERER_IDLE_REALTIME_REFRESH_MAX_FAILURE_MS,
                    Math.max(
                            CAPTURE_RENDERER_IDLE_REALTIME_REFRESH_BASE_MS,
                            previousDelayMs * 2
                    )
            );
            idleRealtimeRefreshReason = "terminal-frame-response-backoff";
        }
        scheduleCaptureRendererIdleRealtimeRefreshAfterTelemetry(
                idleRealtimeRefreshReason,
                captureRendererIdleRealtimeRefreshDelayMs
        );
    }

    private void clearCaptureRendererIdleRealtimeInFlight(String reason) {
        if (captureRendererIdleRealtimeRefreshInFlight) {
            Log.i(CONTROL_LOG_TAG,
                    "stage=capture-renderer endpoint=idle-refresh result=in-flight-cleared"
                            + " reason=" + safeLogToken(reason)
                            + " windowId=" + safeWindowIdForControlLog(
                                    captureRendererIdleRealtimeInFlightRequestedWindowId)
                            + " frameWindowId=" + safeWindowIdForControlLog(
                                    captureRendererIdleRealtimeInFlightFrameWindowId)
                            + " telemetryGeneration="
                            + captureRendererIdleRealtimeInFlightTelemetryGeneration);
        }
        captureRendererIdleRealtimeRefreshInFlight = false;
        captureRendererIdleRealtimeInFlightRequestedWindowId = "";
        captureRendererIdleRealtimeInFlightFrameWindowId = "";
        captureRendererIdleRealtimeInFlightTelemetryGeneration = -1;
        captureRendererIdleRealtimeInFlightStartedAtMs = 0;
    }

    private void invalidateCaptureRendererIdleRealtimeInFlight(String reason) {
        clearCaptureRendererIdleRealtimeInFlight(reason);
        captureRendererIdleRealtimeRefreshDelayMs = CAPTURE_RENDERER_IDLE_REALTIME_REFRESH_BASE_MS;
    }

    private void handleCaptureRendererIdleCommitRequest(String payloadJson) {
        JSONObject payload = parseCaptureRendererBridgePayload(payloadJson);
        if (payload == null) {
            return;
        }
        String windowId = payload.optString("windowId", "").trim();
        String endpoint = payload.optString("endpoint", "");
        String bodySha256 = payload.optString("bodySha256", "")
                .trim()
                .toLowerCase(Locale.US);
        String reason = payload.optString("reason", CAPTURE_RENDERER_IDLE_FRAME_CHANGE_REASON).trim();
        if (!CAPTURE_RENDERER_IDLE_FRAME_CHANGE_REASON.equals(reason)
                && !CAPTURE_RENDERER_IDLE_REALTIME_TICK_REASON.equals(reason)) {
            reason = CAPTURE_RENDERER_IDLE_FRAME_CHANGE_REASON;
        }
        long now = SystemClock.elapsedRealtime();
        String confirmedVisibleWindowId = confirmedVisibleTerminalTargetKey();
        boolean targetConfirmed = captureRendererFrameTargetsVisibleWindow(payload, windowId, confirmedVisibleWindowId);
        boolean preLocalFeedbackHold = touchScrollAwaitingFirstLocalFeedback();
        boolean localHistoryReadHold = localHistoryTouchViewportOwnsVisibleSurfaceForReadHold();
        boolean terminalSnapshotReadHold = terminalSnapshotLease != null;
        boolean readModeHold = captureRendererReadHoldActive();
        boolean noActiveTouchOrScroll = !terminalHistoryDragActive
                && !terminalMultiTouchGesture
                && !terminalHorizontalPanActive
                && !historyScrollRequestInFlight
                && !terminalHistoryMomentumActive
                && pendingHistoryScrollWhere.isEmpty()
                && !terminalBottomRestoreInFlight;
        String skipReason = "";
        if (hasStableWindowId(pendingActiveSwitchTitleWindowId)
                && activeSwitchRendererEventGeneration(payload)
                != pendingActiveSwitchTitleGeneration) {
            skipReason = "late-active-switch-generation";
        } else if (!activityResumed) {
            skipReason = "background";
        } else if (webView == null) {
            skipReason = "no-webview";
        } else if (!hasStableWindowId(windowId)) {
            skipReason = "missing-window";
        } else if (!targetConfirmed) {
            skipReason = "target-mismatch";
        } else if (!payload.optBoolean("acceptedFrame", false)
                && payload.optBoolean("paintOnly", false)
                && !paintOnlyFrameIdentityConsistent(payload, windowId)) {
            // WHY(paint-only identity gate 2026-07-27, review challenge 2): a
            // paint-only retained-200 body is admitted for SPEED, but window-level
            // gates alone cannot prove the body belongs to the session the user
            // switched to (a reused/retargeted @windowId can carry a prior
            // session's bytes while continuity is unproven). Mirror the
            // active-switch lifecycle's identity semantics: block ONLY on a
            // both-known session/thread mismatch against the bound switch identity
            // for this exact window; unknown identity stays window-gated so cold
            // targets still paint quickly.
            skipReason = "paint-only-identity-mismatch";
        } else if (!payload.optBoolean("acceptedFrame", false)
                && !payload.optBoolean("paintOnly", false)) {
            // WHY(active-switch retained-200 paint 2026-07-27): the control server can
            // return a fully paintable retained-200 body (rows>0, body>0, sha present)
            // before it has *proven* transcript continuity; the renderer marks it
            // acceptedFrame:false but paintOnly:true. Admitting paintOnly paints those
            // pixels at switch speed via the purely-visual commitCaptureRendererVisualFrame,
            // while every trusted-authority promotion (rememberAcceptedCaptureRendererFrame,
            // JS lastAccepted*) stays acceptedFrame-gated and untouched. Without this the
            // decisive first paint is dropped as "unaccepted-frame" = the multi-second stall.
            skipReason = "unaccepted-frame";
        } else if ("/terminal-frame".equals(endpoint) && payload.optInt("status", -1) < 200) {
            skipReason = "status-not-ok";
        } else if ("/terminal-frame".equals(endpoint) && payload.optInt("status", -1) >= 300) {
            skipReason = "status-not-ok";
        } else if (payload.optInt("bodyLength", -1) <= 0) {
            skipReason = "empty-body";
        } else if (payload.optInt("rowCount", -1) <= 0) {
            skipReason = "empty-rows";
        } else if (!bodySha256.matches("^[0-9a-f]{64}$")) {
            // WHY: FNV32 is retained only as compact telemetry. Visual commit
            // authority requires the exact SHA-256 receipt for the immutable
            // body snapshot that the renderer accepted.
            skipReason = "missing-body-sha256";
        } else if (preLocalFeedbackHold) {
            // WHY: idle-frame commits are not a valid first feedback source for
            // one-finger scroll. They may contain correct rows, but committing
            // them before the local touch owner moves creates the visible
            // transition jump.
            skipReason = "pre-local-feedback-hold";
        } else if (terminalSnapshotReadHold || localHistoryReadHold) {
            // WHY: delayed idle `/terminal-frame` and DOM-apply callbacks are
            // backend reconciliation only during APK-local scrollback ownership.
            // Letting this path repaint the accepted frame is the installed
            // lag/stutter/sticky-boundary falsifier for T5 scroll proof.
            skipReason = "local-history-read-hold";
        } else if (captureRendererGestureScrollActive()) {
            // WHY: SCROLL DEEP-HISTORY 2026-07-26 — a user-driven scroll gesture owns
            // the viewport; commit its staged/scrolled frame even though it arrives via
            // idle poll/dom-apply with a non-touch reason (device proof @6). Leaving
            // skipReason empty falls through to commit. Cache-owned (above) and
            // pre-local-feedback holds still win; live-tail read-mode-hold resumes once
            // the gesture settles. Target/accepted-frame validity gates above still apply.
            Log.i(CONTROL_LOG_TAG,
                    "stage=capture-renderer-black-refresh endpoint=visual-commit-request result=gesture-scroll-commit"
                            + " windowId=" + safeWindowIdForControlLog(windowId)
                            + " reason=" + safeLogToken(reason));
        } else if (!noActiveTouchOrScroll) {
            skipReason = "touch-scroll-hold";
        } else if (readModeHold) {
            // WHY: APK-SCROLL-SNAPBACK-AFTER-UP-STOP-1248 proved the renderer's
            // generic idle telemetry can commit a fresh live-prompt frame after
            // ACTION_UP, even though the user intentionally stopped in history.
            // While read mode owns the surface, only explicit touch-scroll edge,
            // response, or Bottom owners may replace the frame.
            skipReason = "read-mode-hold";
        } else if (now - lastIdleCaptureRendererVisualCommitAtMs < CAPTURE_RENDERER_IDLE_VISUAL_COMMIT_MIN_MS) {
            skipReason = "rate-limited";
        }
        if (!skipReason.isEmpty()) {
            logCaptureRendererTelemetry(
                    "visual-commit-request",
                    "skipped",
                    windowId,
                    reason,
                    payload,
                    skipReason
            );
            Log.i(CONTROL_LOG_TAG,
                    "stage=capture-renderer-black-refresh endpoint=visual-commit-request result=retained-frame"
                            + " actionId=" + safeLogToken(currentApkActionIdForLog())
                            + " tapId=" + safeLogToken(currentApkTapIdForLog())
                            + " windowId=" + safeWindowIdForControlLog(windowId)
                            + " reason=" + safeLogToken(reason)
                            + " skipReason=" + safeLogToken(skipReason)
                            + " retainedLastAcceptedFrame=true"
                            + " reloadDecision=false");
            return;
        }
        lastIdleCaptureRendererVisualCommitAtMs = now;
        Log.i(CONTROL_LOG_TAG,
                CAPTURE_RENDERER_LOG_VISUAL_COMMIT_REQUESTED
                        + " actionId=" + safeLogToken(currentApkActionIdForLog())
                        + " tapId=" + safeLogToken(currentApkTapIdForLog())
                        + " windowId=" + safeWindowIdForControlLog(windowId)
                        + " reason=" + safeLogToken(reason)
                        + " hash=" + safeLogToken(payload.optString("hash", ""))
                        + " bodySha256=" + safeLogToken(bodySha256)
                        + " bodyLength=" + payload.optInt("bodyLength", -1)
                        + " rowCount=" + payload.optInt("rowCount", -1)
                        + " generation=" + payload.optLong("generation", -1));
        commitCaptureRendererVisualFrame(reason);
    }

    private void handleCaptureRendererTelemetry(String payloadJson) {
        JSONObject payload = parseCaptureRendererBridgePayload(payloadJson);
        if (payload == null) {
            return;
        }
        // WHY: network-pressure ownership must be updated even when read-hold or
        // an old Active transition suppresses the response from painting.
        handleCaptureRendererIdleRealtimeTelemetry(payload);
        if (shouldSuppressCaptureRendererTelemetryForReadHold(payload)) {
            logCaptureRendererTelemetry(
                    payload.optString("endpoint", "renderer"),
                    "suppressed-read-hold",
                    payload.optString("windowId", ""),
                    payload.optString("reason", ""),
                    payload,
                    "native-read-hold"
            );
            return;
        }
        if (hasStableWindowId(pendingActiveSwitchTitleWindowId)
                && ("/terminal-frame".equals(payload.optString("endpoint", ""))
                || "dom-apply".equals(payload.optString("endpoint", "")))
                && activeSwitchRendererEventGeneration(payload)
                != pendingActiveSwitchTitleGeneration) {
            commitPendingActiveSwitchTitleFromFrame(payload);
            logCaptureRendererTelemetry(
                    payload.optString("endpoint", "renderer"),
                    payload.optString("stage", "event"),
                    payload.optString("windowId", ""),
                    payload.optString("reason", ""),
                    payload,
                    "late-active-switch-generation"
            );
            return;
        }
        if ("/terminal-frame".equals(payload.optString("endpoint", ""))) {
            rememberSessionInteractionMetadata(
                    payload,
                    payload.optString("windowId", ""),
                    "/terminal-frame",
                    payload.optString("reason", "capture-renderer")
            );
        }
        // WHY: FIX D (smoothness) — capture the last accepted frame hash before
        // rememberAcceptedCaptureRendererFrame overwrites it so a genuinely CHANGED
        // live frame can be detected here, in the caller. The detection is kept OUT
        // of rememberAcceptedCaptureRendererFrame on purpose: that method is
        // extracted and compiled byte-for-byte by the accepted-frame column-contract
        // harness, which only stubs its existing callees, so adding a new call there
        // would break the harness compile.
        String smoothnessPrevFrameHash = lastAcceptedCaptureRendererFrameHash;
        rememberAcceptedCaptureRendererFrame(payload);
        if (payload.optBoolean("acceptedFrame", false)
                && !hasStableWindowId(pendingActiveSwitchTitleWindowId)) {
            CanonicalTitleBinding acceptedTitleBinding =
                    canonicalTitleBindingFromPayload(payload);
            if (acceptedTitleBinding != null
                    && acceptedTitleBinding.windowId.equals(
                            lastAcceptedCaptureRendererFrameWindowId
                    )) {
                visibleBodyTitleBinding = acceptedTitleBinding;
                updateSessionTitleStrip(visibleBodyTitleBinding);
            }
        }
        if (payload.optBoolean("acceptedFrame", false)) {
            // WHY: SCROLL DEEP-HISTORY 2026-07-26 — mirror the additive claude
            // transcript-scrollback hint next to the accepted live frame. Parsed here
            // (not in the harness-locked rememberAcceptedCaptureRendererFrame). Keys are
            // absent for non-claude / history>0 panes, so these default to false/0 and
            // leave those panes' routing unchanged.
            lastFrameTranscriptScrollbackAvailable = payload.optBoolean("transcriptScrollbackAvailable", false);
            lastFrameTranscriptHistorySize = payload.optInt("transcriptHistorySize", 0);
        }
        if (payload.optBoolean("acceptedFrame", false)
                && !lastAcceptedCaptureRendererFrameHash.isEmpty()
                && !lastAcceptedCaptureRendererFrameHash.equals(smoothnessPrevFrameHash)) {
            // WHY: FIX D — a changed live frame just landed; keep the local composite
            // pump running so the SSE-updated DOM composites every display frame
            // instead of only on the next 2s idle-realtime tick.
            onCaptureRendererStreamingFrameForSmoothness();
        }
        maybeMarkApkFirstReadableFrame(payload, payload.optString("endpoint", "renderer"));
        commitPendingActiveSwitchTitleFromFrame(payload);
        if ("dom-apply".equals(payload.optString("endpoint", ""))
                && "changed".equals(payload.optString("stage", ""))) {
            String projectionWindowId = captureRendererVisibleWindowId(
                    payload,
                    captureRendererFrameWindowId(payload, payload.optString("windowId", ""))
            );
            rememberRecentActiveSwitchProjection(projectionWindowId, "dom-apply-changed");
        }
        logCaptureRendererTelemetry(
                payload.optString("endpoint", "renderer"),
                payload.optString("stage", "event"),
                payload.optString("windowId", ""),
                payload.optString("reason", ""),
                payload,
                payload.optString("skipReason", "")
        );
    }

    private JSONObject parseCaptureRendererBridgePayload(String payloadJson) {
        if (payloadJson == null || payloadJson.trim().isEmpty()) {
            return null;
        }
        try {
            return new JSONObject(payloadJson);
        } catch (Exception exc) {
            Log.i(CONTROL_LOG_TAG,
                    "stage=capture-renderer endpoint=bridge result=parse-error"
                            + " exception=" + safeLogToken(exc.getClass().getSimpleName()));
            return null;
        }
    }

    private void rememberAcceptedCaptureRendererFrame(JSONObject payload) {
        if (payload == null || !payload.optBoolean("acceptedFrame", false)) {
            return;
        }
        String windowId = captureRendererFrameWindowId(payload, payload.optString("windowId", ""));
        String visibleWindowId = captureRendererVisibleWindowId(payload, windowId);
        String frameHash = payload.optString("frameHash", payload.optString("hash", "")).trim();
        if (!hasStableWindowId(windowId) || frameHash.isEmpty()) {
            return;
        }
        if (hasStableWindowId(pendingActiveSwitchTitleWindowId)) {
            // WHY(v277 title/body authority): accepted B is still a candidate
            // until its matching changed-DOM event commits. Preserve A's global
            // frame rows/hash/owner; the successful commit re-enters this method
            // after clearing the pending generation and publishes B atomically.
            return;
        }
        boolean acceptedFrameTargetChanged =
                !windowId.equals(lastAcceptedCaptureRendererFrameWindowId);
        // WHY: response telemetry owns the measured renderer width, while its
        // correlated DOM confirmation intentionally omits requestedCols. Owner
        // invalidation must precede best-effort row/paint parsing because a
        // parse failure cannot authorize stale width from the previous frame.
        if (acceptedFrameTargetChanged) {
            lastAcceptedCaptureRendererCols = -1;
        }
        try {
            List<String> rows = rowsFromPayload(payload);
            List<LocalHistoryPaintRow> paintRows = localHistoryPaintRowsFromPayload(payload, false);
            if (paintRows.isEmpty() && !rows.isEmpty()) {
                paintRows = plainLocalHistoryPaintRows(rows);
            }
            if (acceptedFrameTargetChanged) {
                lastAcceptedCaptureRendererRows.clear();
                lastAcceptedCaptureRendererPaintRows.clear();
            }
            if (!rows.isEmpty()) {
                lastAcceptedCaptureRendererRows.clear();
                lastAcceptedCaptureRendererRows.addAll(rows);
            }
            if (!paintRows.isEmpty()) {
                lastAcceptedCaptureRendererPaintRows.clear();
                lastAcceptedCaptureRendererPaintRows.addAll(paintRows);
            }
        } catch (Exception ignored) {
            lastAcceptedCaptureRendererRows.clear();
            lastAcceptedCaptureRendererPaintRows.clear();
        }
        lastAcceptedCaptureRendererFrameWindowId = windowId;
        lastAcceptedCaptureRendererFrameHash = frameHash;
        lastAcceptedCaptureRendererHasMoreBefore = payload.optBoolean("hasMoreBefore", false);
        lastAcceptedCaptureRendererCopyModeViewport = payload.optBoolean("copyModeViewport", false);
        lastAcceptedCaptureRendererScrollPosition = payload.optInt("scrollPosition", -1);
        lastAcceptedCaptureRendererHistorySize = payload.optInt("historySize", -1);
        lastAcceptedCaptureRendererPaneInMode = payload.optInt("paneInMode", -1);
        int requestedCols = payload.optInt("requestedCols", -1);
        if (requestedCols >= 20) {
            lastAcceptedCaptureRendererCols = requestedCols;
        }
        if (!hasStableWindowId(pendingActiveSwitchTitleWindowId)
                && hasStableWindowId(visibleWindowId)) {
            // WHY: accepted frame telemetry is still only a candidate during an
            // Active switch. The matching changed-DOM callback publishes both
            // confirmed target fields in the atomic lifecycle commit.
            confirmedCaptureRendererFrameWindowTargetKey = visibleWindowId;
        }
        if (acceptedFrameTargetChanged) {
            // WHY(v281 passive-history pressure): accepted live frames can arrive
            // continuously without any user scroll. Warming only the first frame for
            // a new target prevents idle frame cadence from becoming a history-fetch
            // and renderer-restage loop; touch-time prefetch remains unchanged.
            prewarmLocalHistoryForWindow(windowId, "accepted-frame");
        }
    }

    private List<String> lastAcceptedCaptureRendererRowsForLocalHistorySeed() {
        return new ArrayList<>(lastAcceptedCaptureRendererRows);
    }

    private List<LocalHistoryPaintRow> lastAcceptedCaptureRendererPaintRowsForLocalHistorySeed() {
        return new ArrayList<>(lastAcceptedCaptureRendererPaintRows);
    }

    private String captureRendererFrameWindowId(JSONObject payload, String fallback) {
        if (payload == null) {
            return "";
        }
        String windowId = payload.optString("frameWindowId", "").trim();
        if (!hasStableWindowId(windowId)) {
            windowId = payload.optString("windowId", "").trim();
        }
        if (!hasStableWindowId(windowId) && fallback != null) {
            windowId = fallback.trim();
        }
        return hasStableWindowId(windowId) ? windowId : "";
    }

    private String captureRendererVisibleWindowId(JSONObject payload, String fallbackFrameWindowId) {
        String frameWindowId = captureRendererFrameWindowId(payload, fallbackFrameWindowId);
        String displayWindowId = stableWindowIdFromPayload(
                payload,
                "",
                "displayWindowId",
                "requestedWindowId",
                "selectedWindowId"
        );
        if (hasStableWindowId(displayWindowId)
                && captureRendererFrameTargetsVisibleWindow(payload, frameWindowId, displayWindowId)) {
            return displayWindowId.trim();
        }
        return frameWindowId;
    }

    private boolean paintOnlyFrameIdentityConsistent(JSONObject payload, String windowId) {
        // WHY(paint-only identity gate): fail closed ONLY on a both-known
        // session/thread identity mismatch, exactly like the switch lifecycle's
        // exact-identity check; unknown identity (either side) falls back to the
        // window-level relation gates so a cold/never-bound target still paints
        // at switch speed. Never blocks accepted frames — those carry the full
        // continuity proof already.
        String frameSessionId = payload.optString("sessionId", "").trim();
        String frameThreadId = payload.optString("threadId", "").trim();
        if (frameSessionId.isEmpty() && frameThreadId.isEmpty()) {
            return true;
        }
        ActiveSwitchIdentity expected =
                activeSwitchTitleLifecycle == null ? null : activeSwitchTitleLifecycle.identity();
        if (expected == null
                || !hasStableWindowId(expected.windowId)
                || !expected.windowId.equals(windowId)) {
            return true;
        }
        boolean sessionMismatch = !frameSessionId.isEmpty()
                && !expected.sessionId.isEmpty()
                && !frameSessionId.equals(expected.sessionId);
        boolean threadMismatch = !frameThreadId.isEmpty()
                && !expected.threadId.isEmpty()
                && !frameThreadId.equals(expected.threadId);
        return !(sessionMismatch || threadMismatch);
    }

    private boolean captureRendererFrameTargetsVisibleWindow(
            JSONObject payload,
            String frameWindowId,
            String visibleWindowId
    ) {
        if (!hasStableWindowId(frameWindowId) || !hasStableWindowId(visibleWindowId)) {
            return false;
        }
        String stableFrameWindowId = frameWindowId.trim();
        String stableVisibleWindowId = visibleWindowId.trim();
        if (stableFrameWindowId.equals(stableVisibleWindowId)) {
            return true;
        }
        if (payload == null) {
            return false;
        }
        String displayWindowId = stableWindowIdFromPayload(
                payload,
                "",
                "displayWindowId",
                "requestedWindowId",
                "selectedWindowId"
        );
        String requestedWindowId = stableWindowIdFromPayload(
                payload,
                "",
                "requestedWindowId",
                "displayWindowId",
                "selectedWindowId"
        );
        String resolvedWindowId = stableWindowIdFromPayload(
                payload,
                "",
                "frameWindowId",
                "resolvedWindowId",
                "replacementWindowId",
                "interactiveTargetWindowId",
                "targetWindowId",
                "windowId"
        );
        boolean acceptedWindowIdsPresent = captureRendererAcceptedWindowIdsPresent(payload);
        boolean acceptedWindowIdsPair =
                captureRendererAcceptedWindowIdsContain(payload, stableVisibleWindowId)
                        && captureRendererAcceptedWindowIdsContain(payload, stableFrameWindowId);
        boolean metadataLinksVisible = stableVisibleWindowId.equals(displayWindowId)
                || stableVisibleWindowId.equals(requestedWindowId);
        boolean frameMatchesResolved = stableFrameWindowId.equals(resolvedWindowId);
        boolean retargeted = payload.optBoolean("retargeted", false)
                || hasStableWindowId(payload.optString("replacementWindowId", ""))
                || hasStableWindowId(payload.optString("interactiveTargetWindowId", ""))
                || hasStableWindowId(payload.optString("resolvedWindowId", ""))
                || acceptedWindowIdsPresent;
        // WHY: `/terminal-frame?windowId=@alias` may safely return a replacement
        // frame when the server stamps both the requested/display id and the
        // resolved interactive id or acceptedWindowIds pair. Accept only that
        // proven relation; a random different `@windowId` still fails the target
        // gate.
        if (acceptedWindowIdsPresent) {
            return retargeted && acceptedWindowIdsPair;
        }
        return retargeted && metadataLinksVisible && frameMatchesResolved;
    }

    private boolean captureRendererAcceptedWindowIdsPresent(JSONObject payload) {
        if (payload == null) {
            return false;
        }
        JSONArray acceptedWindowIds = payload.optJSONArray("acceptedWindowIds");
        return acceptedWindowIds != null && acceptedWindowIds.length() > 0;
    }

    private boolean captureRendererAcceptedWindowIdsContain(JSONObject payload, String windowId) {
        if (payload == null || !hasStableWindowId(windowId)) {
            return false;
        }
        JSONArray acceptedWindowIds = payload.optJSONArray("acceptedWindowIds");
        if (acceptedWindowIds == null) {
            return false;
        }
        String stableWindowId = windowId.trim();
        for (int i = 0; i < acceptedWindowIds.length(); i++) {
            String acceptedWindowId = acceptedWindowIds.optString(i, "").trim();
            if (stableWindowId.equals(acceptedWindowId)) {
                return true;
            }
        }
        return false;
    }

    private boolean shouldSuppressCaptureRendererTelemetryForReadHold(JSONObject payload) {
        if (payload == null || !captureRendererReadHoldActive()) {
            return false;
        }
        if (captureRendererGestureScrollActive()) {
            // WHY: SCROLL DEEP-HISTORY 2026-07-26 — a user gesture owns the viewport;
            // its staged/scrolled frame (even via idle poll/dom-apply) must be
            // observed and allowed to commit. Read-hold telemetry suppression resumes
            // once the gesture settles, protecting the live tail when idle.
            return false;
        }
        String endpoint = payload.optString("endpoint", "renderer");
        String reason = payload.optString("reason", "");
        if (captureRendererTelemetryAllowedDuringReadHold(endpoint, reason)) {
            return false;
        }
        return "/terminal-frame".equals(endpoint)
                || "dom-apply".equals(endpoint)
                || "visual-commit-request".equals(endpoint);
    }

    private boolean captureRendererTelemetryAllowedDuringReadHold(String endpoint, String reason) {
        if ("telemetry-hook".equals(endpoint)) {
            return true;
        }
        if ("dom-apply".equals(endpoint)) {
            // WHY: DOM observer telemetry can carry a stale touch-bottom settle
            // reason while local-history read-hold owns the visible surface.
            // During one-finger history scroll, all DOM apply changes are
            // observation only and must be logged as suppressed-read-hold.
            return false;
        }
        String safeReason = reason == null ? "" : reason.trim();
        return safeReason.startsWith("touch-")
                || safeReason.contains("touch-scroll")
                || safeReason.contains("touch-bottom")
                || safeReason.contains("live-bottom");
    }

    private void logCaptureRendererTelemetry(
            String endpoint,
            String result,
            String windowId,
            String reason,
            JSONObject payload,
            String skipReason
    ) {
        StringBuilder builder = new StringBuilder();
        builder.append(captureRendererTelemetryPrefix(endpoint, result))
                .append(" windowId=").append(safeWindowIdForControlLog(windowId))
                .append(" actionId=").append(safeLogToken(currentApkActionIdForLog()))
                .append(" tapId=").append(safeLogToken(currentApkTapIdForLog()))
                .append(" actionKind=").append(safeLogToken(currentApkActionKindForLog()))
                .append(" reason=").append(safeLogToken(reason))
                .append(" status=").append(payload.optInt("status", -1))
                .append(" elapsedMs=").append(payload.optLong("elapsedMs", -1))
                .append(" scheduledDelayMs=").append(payload.optLong("scheduledDelayMs", -1))
                .append(" bodyLength=").append(payload.optInt("bodyLength", -1))
                .append(" rowCount=").append(payload.optInt("rowCount", -1))
                .append(" hash=").append(safeLogToken(payload.optString("hash", "")))
                .append(" bodySha256=").append(safeLogToken(payload.optString("bodySha256", "")))
                .append(" acceptedFrame=").append(payload.optBoolean("acceptedFrame", false))
                .append(" transcriptReaderBody=").append(payload.optBoolean("transcriptReaderBody", false))
                .append(" frameWindowId=").append(safeWindowIdForControlLog(payload.optString("frameWindowId", "")))
                .append(" requestedWindowId=").append(safeWindowIdForControlLog(payload.optString("requestedWindowId", "")))
                .append(" displayWindowId=").append(safeWindowIdForControlLog(payload.optString("displayWindowId", "")))
                .append(" resolvedWindowId=").append(safeWindowIdForControlLog(payload.optString("resolvedWindowId", "")))
                .append(" replacementWindowId=").append(safeWindowIdForControlLog(payload.optString("replacementWindowId", "")))
                .append(" interactiveTargetWindowId=").append(safeWindowIdForControlLog(payload.optString("interactiveTargetWindowId", "")))
                .append(" retargeted=").append(payload.optBoolean("retargeted", false))
                .append(" frameHash=").append(safeLogToken(payload.optString("frameHash", "")))
                .append(" generation=").append(payload.optLong("generation", -1))
                .append(" transitionGeneration=").append(payload.optLong("transitionGeneration", -1))
                .append(" observedAtMs=").append(SystemClock.elapsedRealtime());
        if (payload.has("streamState")) {
            builder.append(" streamState=").append(safeLogToken(
                    payload.optString("streamState", "")))
                    .append(" pageMonotonicMs=").append(
                    payload.optLong("pageMonotonicMs", -1));
        }
        if (skipReason != null && !skipReason.trim().isEmpty()) {
            builder.append(" skipReason=").append(safeLogToken(skipReason));
        }
        Log.i(CONTROL_LOG_TAG, builder.toString());
    }

    private String captureRendererTelemetryPrefix(String endpoint, String result) {
        if ("/terminal-frame".equals(endpoint) && "scheduled".equals(result)) {
            return CAPTURE_RENDERER_LOG_TERMINAL_FRAME_SCHEDULED;
        }
        if ("/terminal-frame".equals(endpoint) && "response".equals(result)) {
            return CAPTURE_RENDERER_LOG_TERMINAL_FRAME_RESPONSE;
        }
        if ("dom-apply".equals(endpoint) && "changed".equals(result)) {
            return CAPTURE_RENDERER_LOG_DOM_APPLY_CHANGED;
        }
        if ("visual-commit-request".equals(endpoint) && "requested".equals(result)) {
            return CAPTURE_RENDERER_LOG_VISUAL_COMMIT_REQUESTED;
        }
        return "stage=capture-renderer endpoint=" + safeLogToken(endpoint)
                + " result=" + safeLogToken(result);
    }

    private void installCaptureRendererTelemetryHook(String reason) {
        installCaptureRendererTelemetryHook(reason, 0);
    }

    private void installCaptureRendererTelemetryHook(String reason, int attempt) {
        if (webView == null || Build.VERSION.SDK_INT < Build.VERSION_CODES.KITKAT) {
            return;
        }
        long generation = ++captureRendererTelemetryHookGeneration;
        webView.evaluateJavascript(
                captureRendererTelemetryHookScript(reason),
                result -> {
                    Log.i(CONTROL_LOG_TAG,
                            "stage=capture-renderer endpoint=telemetry-hook result="
                                    + safeLogToken(String.valueOf(result))
                                    + " reason=" + safeLogToken(reason)
                                    + " attempt=" + attempt);
                    if (attempt >= 6
                            || generation != captureRendererTelemetryHookGeneration
                            || result == null
                            || result.contains("capture-telemetry-installed")
                            || result.contains("capture-telemetry-present")) {
                        return;
                    }
                    uiHandler.postDelayed(
                            () -> installCaptureRendererTelemetryHook(reason + "-retry", attempt + 1),
                            CAPTURE_RENDERER_TELEMETRY_HOOK_RETRY_MS
                    );
                }
        );
    }

